/**
 * Tests for LanguageContext
 * Validates language initialization, preference management, and translation functionality
 * 
 * Requirements: 3.1, 3.2, 3.4, 3.5, 3.6
 */

import { renderHook, act, waitFor } from '@testing-library/react';
import { LanguageProvider, useLanguage } from '../contexts/LanguageContext';
import { I18nProvider } from '../utils/i18n';
import * as languageDetection from '../utils/languageDetection';

// Mock localStorage
const localStorageMock = (() => {
  let store: Record<string, string> = {};

  return {
    getItem: (key: string) => store[key] || null,
    setItem: (key: string, value: string) => {
      store[key] = value;
    },
    removeItem: (key: string) => {
      delete store[key];
    },
    clear: () => {
      store = {};
    },
  };
})();

Object.defineProperty(window, 'localStorage', {
  value: localStorageMock,
  writable: true,
});

// Helper to create wrapper with both I18nProvider and LanguageProvider
const createWrapper = () => {
  return ({ children }: { children: React.ReactNode }) => (
    <I18nProvider defaultLanguage="en" enableAutoDetect={false}>
      <LanguageProvider>{children}</LanguageProvider>
    </I18nProvider>
  );
};

describe('LanguageContext', () => {
  beforeEach(() => {
    // Clear localStorage before each test
    localStorageMock.clear();
    
    // Reset mocks
    vi.clearAllMocks();
  });

  describe('useLanguage hook', () => {
    it('should throw error when used outside LanguageProvider', () => {
      // Suppress console.error for this test
      const consoleSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
      
      expect(() => {
        renderHook(() => useLanguage());
      }).toThrow('useLanguage must be used within a LanguageProvider');
      
      consoleSpy.mockRestore();
    });

    it('should provide context value when used within LanguageProvider', () => {
      const { result } = renderHook(() => useLanguage(), {
        wrapper: createWrapper(),
      });

      expect(result.current).toBeDefined();
      expect(result.current.currentLanguage).toBeDefined();
      expect(result.current.availableLanguages).toBeDefined();
      expect(result.current.setLanguage).toBeDefined();
      expect(result.current.t).toBeDefined();
    });
  });

  describe('Language Initialization', () => {
    it('should initialize with detected language on first launch', () => {
      // Mock initializeLanguage to return 'en'
      vi.spyOn(languageDetection, 'initializeLanguage').mockReturnValue('en');

      const { result } = renderHook(() => useLanguage(), {
        wrapper: createWrapper(),
      });

      expect(result.current.currentLanguage).toBe('en');
    });

    it('should fallback to English if initialization fails', () => {
      // Mock initializeLanguage to throw an error
      vi.spyOn(languageDetection, 'initializeLanguage').mockImplementation(() => {
        throw new Error('Initialization failed');
      });
      
      // Suppress console.error for this test
      const consoleSpy = vi.spyOn(console, 'error').mockImplementation(() => {});

      const { result } = renderHook(() => useLanguage(), {
        wrapper: createWrapper(),
      });

      expect(result.current.currentLanguage).toBe('en');
      
      consoleSpy.mockRestore();
    });
  });

  describe('Language Selection', () => {
    it('should change language when setLanguage is called', () => {
      const savePreferenceSpy = vi.spyOn(languageDetection, 'saveLanguagePreference');

      const { result } = renderHook(() => useLanguage(), {
        wrapper: createWrapper(),
      });

      // Change language to Spanish
      act(() => {
        result.current.setLanguage('es');
      });

      expect(result.current.currentLanguage).toBe('es');
      expect(savePreferenceSpy).toHaveBeenCalledWith('es', true);
    });

    it('should fallback to English for unsupported language codes', () => {
      const consoleSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});
      const savePreferenceSpy = vi.spyOn(languageDetection, 'saveLanguagePreference');

      const { result } = renderHook(() => useLanguage(), {
        wrapper: createWrapper(),
      });

      // Try to set an unsupported language
      act(() => {
        result.current.setLanguage('xx');
      });

      expect(result.current.currentLanguage).toBe('en');
      expect(savePreferenceSpy).toHaveBeenCalledWith('en', true);
      expect(consoleSpy).toHaveBeenCalledWith(
        expect.stringContaining('Language code "xx" is not supported')
      );

      consoleSpy.mockRestore();
    });

    it('should update document language attribute when language changes', () => {
      const { result } = renderHook(() => useLanguage(), {
        wrapper: createWrapper(),
      });

      act(() => {
        result.current.setLanguage('fr');
      });

      expect(document.documentElement.lang).toBe('fr');
    });

    it('should handle errors during language change gracefully', () => {
      const consoleSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
      const savePreferenceSpy = vi.spyOn(languageDetection, 'saveLanguagePreference')
        .mockImplementation(() => {
          throw new Error('Save failed');
        });

      const { result } = renderHook(() => useLanguage(), {
        wrapper: createWrapper(),
      });

      // Should not throw, but log error
      act(() => {
        result.current.setLanguage('de');
      });

      expect(consoleSpy).toHaveBeenCalledWith(
        'Failed to change language:',
        expect.any(Error)
      );

      consoleSpy.mockRestore();
      savePreferenceSpy.mockRestore();
    });
  });

  describe('Available Languages', () => {
    it('should provide list of all supported languages', () => {
      const { result } = renderHook(() => useLanguage(), {
        wrapper: createWrapper(),
      });

      expect(result.current.availableLanguages).toBeDefined();
      expect(result.current.availableLanguages.length).toBeGreaterThan(0);
      
      // Check that English is in the list
      const englishLang = result.current.availableLanguages.find(lang => lang.code === 'en');
      expect(englishLang).toBeDefined();
      expect(englishLang?.name).toBe('English');
      expect(englishLang?.nativeName).toBe('English');
    });

    it('should include all expected languages', () => {
      const { result } = renderHook(() => useLanguage(), {
        wrapper: createWrapper(),
      });

      const languageCodes = result.current.availableLanguages.map(lang => lang.code);
      
      // Check for expected languages from SUPPORTED_LANGUAGES
      expect(languageCodes).toContain('en');
      expect(languageCodes).toContain('es');
      expect(languageCodes).toContain('fr');
      expect(languageCodes).toContain('de');
      expect(languageCodes).toContain('ja');
      expect(languageCodes).toContain('zh');
    });
  });

  describe('Translation Function', () => {
    it('should provide translation function', () => {
      const { result } = renderHook(() => useLanguage(), {
        wrapper: createWrapper(),
      });

      expect(result.current.t).toBeDefined();
      expect(typeof result.current.t).toBe('function');
    });

    it('should return translation key if translation not found', () => {
      const { result } = renderHook(() => useLanguage(), {
        wrapper: createWrapper(),
      });

      const translation = result.current.t('nonexistent.key');
      
      // Should return the key itself as fallback
      expect(translation).toBe('nonexistent.key');
    });

    it('should handle translation errors gracefully', () => {
      const consoleSpy = vi.spyOn(console, 'error').mockImplementation(() => {});

      const { result } = renderHook(() => useLanguage(), {
        wrapper: createWrapper(),
      });

      // Should not throw even with invalid parameters
      const translation = result.current.t('test.key', { invalid: undefined });
      
      expect(translation).toBeDefined();
      
      consoleSpy.mockRestore();
    });
  });

  describe('Language Persistence', () => {
    it('should save language preference to localStorage', () => {
      const savePreferenceSpy = vi.spyOn(languageDetection, 'saveLanguagePreference');

      const { result } = renderHook(() => useLanguage(), {
        wrapper: createWrapper(),
      });

      act(() => {
        result.current.setLanguage('ja');
      });

      expect(savePreferenceSpy).toHaveBeenCalledWith('ja', true);
    });

    it('should mark language as user-selected when changed via setLanguage', () => {
      const savePreferenceSpy = vi.spyOn(languageDetection, 'saveLanguagePreference');

      const { result } = renderHook(() => useLanguage(), {
        wrapper: createWrapper(),
      });

      act(() => {
        result.current.setLanguage('zh');
      });

      // Second parameter should be true (user-selected)
      expect(savePreferenceSpy).toHaveBeenCalledWith('zh', true);
    });
  });

  describe('Multiple Language Changes', () => {
    it('should handle multiple language changes correctly', () => {
      const { result } = renderHook(() => useLanguage(), {
        wrapper: createWrapper(),
      });

      // Change to Spanish
      act(() => {
        result.current.setLanguage('es');
      });
      expect(result.current.currentLanguage).toBe('es');

      // Change to French
      act(() => {
        result.current.setLanguage('fr');
      });
      expect(result.current.currentLanguage).toBe('fr');

      // Change to German
      act(() => {
        result.current.setLanguage('de');
      });
      expect(result.current.currentLanguage).toBe('de');
    });

    it('should trigger re-render on each language change', () => {
      const { result, rerender } = renderHook(() => useLanguage(), {
        wrapper: createWrapper(),
      });

      const initialLang = result.current.currentLanguage;

      act(() => {
        result.current.setLanguage('es');
      });

      rerender();

      expect(result.current.currentLanguage).not.toBe(initialLang);
      expect(result.current.currentLanguage).toBe('es');
    });
  });
});

/**
 * MenuBar Compatibility Wrapper Tests
 * 
 * Tests for the MenuBarCompat component which provides backward compatibility
 * for the new comprehensive MenuBar implementation.
 * 
 * Note: This tests the compatibility wrapper. For comprehensive tests of the
 * new MenuBar implementation, see src/components/menuBar/__tests__/
 */

import React from 'react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import '@testing-library/jest-dom';
import { MenuBarCompat } from '../components/MenuBarCompat';

// Mock the new MenuBar component
vi.mock('../components/menuBar', () => ({
  MenuBar: ({ project, hasUnsavedChanges, viewState }: any) => (
    <div data-testid="menu-bar-mock">
      <div data-testid="project-state">{project ? 'has-project' : 'no-project'}</div>
      <div data-testid="unsaved-changes">{hasUnsavedChanges ? 'unsaved' : 'saved'}</div>
      <div data-testid="zoom-level">{viewState.zoomLevel}</div>
    </div>
  ),
}));

// Mock the i18n system
vi.mock('../utils/i18n', () => ({
  useI18n: () => ({
    t: (key: string) => key,
    setLanguage: vi.fn(),
  }),
}));

describe('MenuBarCompat Component', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('Basic Rendering', () => {
    it('should render the MenuBar with default props', () => {
      render(<MenuBarCompat />);
      
      const menuBar = screen.getByTestId('menu-bar-mock');
      expect(menuBar).toBeInTheDocument();
    });

    it('should initialize with no project', () => {
      render(<MenuBarCompat />);
      
      const projectState = screen.getByTestId('project-state');
      expect(projectState).toHaveTextContent('no-project');
    });

    it('should initialize with no unsaved changes', () => {
      render(<MenuBarCompat />);
      
      const unsavedChanges = screen.getByTestId('unsaved-changes');
      expect(unsavedChanges).toHaveTextContent('saved');
    });

    it('should initialize with default zoom level', () => {
      render(<MenuBarCompat />);
      
      const zoomLevel = screen.getByTestId('zoom-level');
      expect(zoomLevel).toHaveTextContent('100');
    });
  });

  describe('Backward Compatibility', () => {
    it('should provide default undo/redo stack', () => {
      // This is implicitly tested by the component rendering without errors
      render(<MenuBarCompat />);
      expect(screen.getByTestId('menu-bar-mock')).toBeInTheDocument();
    });

    it('should provide default clipboard state', () => {
      // This is implicitly tested by the component rendering without errors
      render(<MenuBarCompat />);
      expect(screen.getByTestId('menu-bar-mock')).toBeInTheDocument();
    });

    it('should provide default view state', () => {
      render(<MenuBarCompat />);
      
      const zoomLevel = screen.getByTestId('zoom-level');
      expect(zoomLevel).toHaveTextContent('100');
    });
  });
});

/**
 * Unit tests for NavigationContext
 * 
 * Tests the navigation context provider functionality including:
 * - Context initialization with default values
 * - Navigation to dashboard
 * - canNavigateBack state management
 * - Error handling for hook usage outside provider
 */

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { NavigationProvider, useNavigation } from '../contexts/NavigationContext';
import type { ReactNode } from 'react';

describe('NavigationContext', () => {
  // Mock window.location.hash
  beforeEach(() => {
    // Reset hash before each test
    window.location.hash = '';
  });

  describe('NavigationProvider initialization', () => {
    it('should initialize with dashboard as default screen', () => {
      const { result } = renderHook(() => useNavigation(), {
        wrapper: ({ children }: { children: ReactNode }) => (
          <NavigationProvider>{children}</NavigationProvider>
        ),
      });

      expect(result.current.currentScreen).toBe('dashboard');
    });

    it('should initialize with canNavigateBack as false when on dashboard', () => {
      const { result } = renderHook(() => useNavigation(), {
        wrapper: ({ children }: { children: ReactNode }) => (
          <NavigationProvider>{children}</NavigationProvider>
        ),
      });

      expect(result.current.canNavigateBack).toBe(false);
    });

    it('should provide navigateToDashboard function', () => {
      const { result } = renderHook(() => useNavigation(), {
        wrapper: ({ children }: { children: ReactNode }) => (
          <NavigationProvider>{children}</NavigationProvider>
        ),
      });

      expect(typeof result.current.navigateToDashboard).toBe('function');
    });
  });

  describe('navigateToDashboard function', () => {
    it('should update currentScreen to dashboard', () => {
      const { result } = renderHook(() => useNavigation(), {
        wrapper: ({ children }: { children: ReactNode }) => (
          <NavigationProvider>{children}</NavigationProvider>
        ),
      });

      // Simulate being on a different screen by directly accessing internal state
      // In real usage, this would be set through navigation actions
      act(() => {
        result.current.navigateToDashboard();
      });

      expect(result.current.currentScreen).toBe('dashboard');
    });

    it('should update window.location.hash to #/dashboard', () => {
      const { result } = renderHook(() => useNavigation(), {
        wrapper: ({ children }: { children: ReactNode }) => (
          <NavigationProvider>{children}</NavigationProvider>
        ),
      });

      act(() => {
        result.current.navigateToDashboard();
      });

      expect(window.location.hash).toBe('#/dashboard');
    });

    it('should set canNavigateBack to false after navigating to dashboard', () => {
      const { result } = renderHook(() => useNavigation(), {
        wrapper: ({ children }: { children: ReactNode }) => (
          <NavigationProvider>{children}</NavigationProvider>
        ),
      });

      act(() => {
        result.current.navigateToDashboard();
      });

      expect(result.current.canNavigateBack).toBe(false);
    });

    it('should handle errors gracefully when hash change fails', () => {
      // Mock console.error to suppress error output in test
      const consoleErrorSpy = vi.spyOn(console, 'error').mockImplementation(() => {});

      // Create a scenario where hash change might fail
      const originalHash = window.location.hash;
      
      const { result } = renderHook(() => useNavigation(), {
        wrapper: ({ children }: { children: ReactNode }) => (
          <NavigationProvider>{children}</NavigationProvider>
        ),
      });

      // Should not throw even if hash change has issues
      expect(() => {
        act(() => {
          result.current.navigateToDashboard();
        });
      }).not.toThrow();

      // State should still be updated
      expect(result.current.currentScreen).toBe('dashboard');

      consoleErrorSpy.mockRestore();
    });
  });

  describe('canNavigateBack property', () => {
    it('should be false when currentScreen is dashboard', () => {
      const { result } = renderHook(() => useNavigation(), {
        wrapper: ({ children }: { children: ReactNode }) => (
          <NavigationProvider>{children}</NavigationProvider>
        ),
      });

      // Initially on dashboard
      expect(result.current.currentScreen).toBe('dashboard');
      expect(result.current.canNavigateBack).toBe(false);
    });

    it('should remain false after navigating to dashboard', () => {
      const { result } = renderHook(() => useNavigation(), {
        wrapper: ({ children }: { children: ReactNode }) => (
          <NavigationProvider>{children}</NavigationProvider>
        ),
      });

      act(() => {
        result.current.navigateToDashboard();
      });

      expect(result.current.canNavigateBack).toBe(false);
    });
  });

  describe('useNavigation hook error handling', () => {
    it('should throw error when used outside NavigationProvider', () => {
      // Suppress console.error for this test
      const consoleErrorSpy = vi.spyOn(console, 'error').mockImplementation(() => {});

      expect(() => {
        renderHook(() => useNavigation());
      }).toThrow('useNavigation must be used within a NavigationProvider');

      consoleErrorSpy.mockRestore();
    });
  });

  describe('Context value stability', () => {
    it('should maintain stable navigateToDashboard reference across renders', () => {
      const { result, rerender } = renderHook(() => useNavigation(), {
        wrapper: ({ children }: { children: ReactNode }) => (
          <NavigationProvider>{children}</NavigationProvider>
        ),
      });

      const firstNavigateRef = result.current.navigateToDashboard;
      
      rerender();
      
      const secondNavigateRef = result.current.navigateToDashboard;

      // Function reference should be stable (useCallback)
      expect(firstNavigateRef).toBe(secondNavigateRef);
    });
  });

  describe('Multiple navigation calls', () => {
    it('should handle multiple navigateToDashboard calls without errors', () => {
      const { result } = renderHook(() => useNavigation(), {
        wrapper: ({ children }: { children: ReactNode }) => (
          <NavigationProvider>{children}</NavigationProvider>
        ),
      });

      // Call multiple times
      act(() => {
        result.current.navigateToDashboard();
        result.current.navigateToDashboard();
        result.current.navigateToDashboard();
      });

      expect(result.current.currentScreen).toBe('dashboard');
      expect(result.current.canNavigateBack).toBe(false);
    });
  });
});

/**
 * Test Suite: Production Wizard Context
 * Tests the ProductionWizardProvider and useProductionWizard hook
 */

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ProductionWizardProvider, useProductionWizard } from '../contexts/ProductionWizardContext';
import { z } from 'zod';

// Test data interface
interface TestWizardData {
  name: string;
  description: string;
  value: number;
}

// Test component that uses the wizard context
function TestWizardComponent() {
  const wizard = useProductionWizard<TestWizardData>();

  return (
    <div>
      <div data-testid="current-step">{wizard.currentStep}</div>
      <div data-testid="total-steps">{wizard.totalSteps}</div>
      <div data-testid="form-data">{JSON.stringify(wizard.formData)}</div>
      <div data-testid="is-dirty">{wizard.isDirty.toString()}</div>
      <div data-testid="validation-errors">{JSON.stringify(wizard.validationErrors)}</div>

      <button onClick={() => wizard.nextStep()} data-testid="next-step">Next</button>
      <button onClick={() => wizard.previousStep()} data-testid="prev-step">Previous</button>
      <button onClick={() => wizard.goToStep(2)} data-testid="go-to-step">Go to Step 2</button>

      <button onClick={() => wizard.updateFormData({ name: 'Test Name' })} data-testid="update-data">
        Update Data
      </button>

      <button onClick={() => wizard.resetFormData()} data-testid="reset-data">
        Reset Data
      </button>
    </div>
  );
}

// Mock localStorage
const localStorageMock = {
  getItem: vi.fn(),
  setItem: vi.fn(),
  removeItem: vi.fn(),
  clear: vi.fn(),
};

Object.defineProperty(window, 'localStorage', {
  value: localStorageMock,
});

describe('ProductionWizardProvider', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    localStorageMock.getItem.mockReturnValue(null);
    localStorageMock.setItem.mockImplementation(() => {});
    localStorageMock.removeItem.mockImplementation(() => {});
  });

  describe('Basic Provider Functionality', () => {
    it('should render children with wizard context', () => {
      render(
        <ProductionWizardProvider
          wizardType="test-wizard"
          totalSteps={3}
          onSubmit={vi.fn()}
        >
          <TestWizardComponent />
        </ProductionWizardProvider>
      );

      expect(screen.getByTestId('current-step')).toHaveTextContent('0');
      expect(screen.getByTestId('total-steps')).toHaveTextContent('3');
    });

    it('should initialize with provided initial data', () => {
      const initialData = { name: 'Initial Name', description: '', value: 42 };

      render(
        <ProductionWizardProvider
          wizardType="test-wizard"
          totalSteps={3}
          initialData={initialData}
          onSubmit={vi.fn()}
        >
          <TestWizardComponent />
        </ProductionWizardProvider>
      );

      expect(screen.getByTestId('form-data')).toHaveTextContent(JSON.stringify(initialData));
    });
  });

  describe('Navigation Methods', () => {
    it('should navigate to next step', async () => {
      const user = userEvent.setup();

      render(
        <ProductionWizardProvider
          wizardType="test-wizard"
          totalSteps={3}
          onSubmit={vi.fn()}
        >
          <TestWizardComponent />
        </ProductionWizardProvider>
      );

      expect(screen.getByTestId('current-step')).toHaveTextContent('0');

      await user.click(screen.getByTestId('next-step'));
      expect(screen.getByTestId('current-step')).toHaveTextContent('1');

      await user.click(screen.getByTestId('next-step'));
      expect(screen.getByTestId('current-step')).toHaveTextContent('2');
    });

    it('should navigate to previous step', async () => {
      const user = userEvent.setup();

      render(
        <ProductionWizardProvider
          wizardType="test-wizard"
          totalSteps={3}
          onSubmit={vi.fn()}
        >
          <TestWizardComponent />
        </ProductionWizardProvider>
      );

      // Go to step 2 first
      await user.click(screen.getByTestId('go-to-step'));
      expect(screen.getByTestId('current-step')).toHaveTextContent('2');

      // Go back
      await user.click(screen.getByTestId('prev-step'));
      expect(screen.getByTestId('current-step')).toHaveTextContent('1');
    });

    it('should navigate to specific step', async () => {
      const user = userEvent.setup();

      render(
        <ProductionWizardProvider
          wizardType="test-wizard"
          totalSteps={5}
          onSubmit={vi.fn()}
        >
          <TestWizardComponent />
        </ProductionWizardProvider>
      );

      await user.click(screen.getByTestId('go-to-step'));
      expect(screen.getByTestId('current-step')).toHaveTextContent('2');
    });

    it('should not navigate beyond bounds', async () => {
      const user = userEvent.setup();

      render(
        <ProductionWizardProvider
          wizardType="test-wizard"
          totalSteps={2}
          onSubmit={vi.fn()}
        >
          <TestWizardComponent />
        </ProductionWizardProvider>
      );

      // Try to go to step 5 (out of bounds)
      await user.click(screen.getByTestId('go-to-step'));
      expect(screen.getByTestId('current-step')).toHaveTextContent('0'); // Should stay at 0
    });

    it('should determine if can proceed correctly', async () => {
      render(
        <ProductionWizardProvider
          wizardType="test-wizard"
          totalSteps={3}
          onSubmit={vi.fn()}
        >
          <TestWizardComponent />
        </ProductionWizardProvider>
      );

      // At step 0, should be able to proceed
      // canProceed is not directly exposed in the test component, but we can test navigation
      expect(screen.getByTestId('current-step')).toHaveTextContent('0');
    });
  });

  describe('Form Data Management', () => {
    it('should update form data', async () => {
      const user = userEvent.setup();

      render(
        <ProductionWizardProvider
          wizardType="test-wizard"
          totalSteps={3}
          onSubmit={vi.fn()}
        >
          <TestWizardComponent />
        </ProductionWizardProvider>
      );

      await user.click(screen.getByTestId('update-data'));

      await waitFor(() => {
        const formData = JSON.parse(screen.getByTestId('form-data').textContent || '{}');
        expect(formData.name).toBe('Test Name');
      });

      expect(screen.getByTestId('is-dirty')).toHaveTextContent('true');
    });

    it('should reset form data', async () => {
      const user = userEvent.setup();
      const initialData = { name: 'Initial', description: '', value: 1 };

      render(
        <ProductionWizardProvider
          wizardType="test-wizard"
          totalSteps={3}
          initialData={initialData}
          onSubmit={vi.fn()}
        >
          <TestWizardComponent />
        </ProductionWizardProvider>
      );

      // Update data first
      await user.click(screen.getByTestId('update-data'));

      await waitFor(() => {
        const formData = JSON.parse(screen.getByTestId('form-data').textContent || '{}');
        expect(formData.name).toBe('Test Name');
      });

      // Reset
      await user.click(screen.getByTestId('reset-data'));

      await waitFor(() => {
        const formData = JSON.parse(screen.getByTestId('form-data').textContent || '{}');
        expect(formData.name).toBe('Initial');
      });

      expect(screen.getByTestId('is-dirty')).toHaveTextContent('false');
    });
  });

  describe('Validation', () => {
