import type {
  Avatar,
  CastingAssignment,
  CastingState,
  CastingAnalytics,
  AvatarValidationResult,
  SceneReference,
  OperationRecord,
} from './types';

export class CastingManager {
  private state: CastingState;
  private avatars: Map<string, Avatar> = new Map();
  private sceneReferences: SceneReference[] = [];
  private undoStack: OperationRecord[] = [];
  private redoStack: OperationRecord[] = [];
  private readonly MAX_HISTORY_SIZE = 20;

  constructor() {
    this.state = {
      assignments: [],
      version: '1.0',
      lastModified: new Date().toISOString(),
    };
  }

  /**
   * Assign an actor to a character
   */
  assignActor(characterId: string, avatarId: string): void {
    const previousState = this.captureState();

    // Remove any existing assignment for this character
    this.state.assignments = this.state.assignments.filter(
      assignment => assignment.characterId !== characterId
    );

    // Add new assignment
    const assignment: CastingAssignment = {
      characterId,
      avatarId,
      assignedAt: new Date().toISOString(),
    };

    this.state.assignments.push(assignment);
    this.state.lastModified = new Date().toISOString();

    // Record operation for undo/redo
    this.recordOperation('assign', previousState, this.captureState(), `Assigned actor ${avatarId} to character ${characterId}`);
  }

  /**
   * Get the actor assigned to a character
   */
  getActorForCharacter(characterId: string): Avatar | null {
    const assignment = this.state.assignments.find(
      a => a.characterId === characterId
    );

    if (!assignment) {
      return null;
    }

    return this.avatars.get(assignment.avatarId) || null;
  }

  /**
   * Get all current assignments
   */
  getAssignments(): CastingAssignment[] {
    return [...this.state.assignments];
  }

  /**
   * Replace the actor for a character (with scene tracking)
   */
  replaceActor(characterId: string, newAvatarId: string): void {
    const previousState = this.captureState();
    const existingAssignment = this.state.assignments.find(a => a.characterId === characterId);

    // Use assignActor logic but record as replace
    this.assignActor(characterId, newAvatarId);

    if (existingAssignment) {
      // This was a replacement, record it differently
      this.recordOperation('replace', previousState, this.captureState(), `Replaced actor for character ${characterId} with ${newAvatarId}`);
    }
  }

  /**
   * Unassign actor from a character
   */
  unassignActor(characterId: string): void {
    const previousState = this.captureState();

    this.state.assignments = this.state.assignments.filter(
      assignment => assignment.characterId !== characterId
    );
    this.state.lastModified = new Date().toISOString();

    this.recordOperation('unassign', previousState, this.captureState(), `Unassigned actor from character ${characterId}`);
  }

  /**
   * Get scenes affected by a character change
   */
  getAffectedScenes(characterId: string): SceneReference[] {
    return this.sceneReferences.filter(ref => ref.characterId === characterId);
  }

  /**
   * Update scene references when actor changes
   */
  updateSceneReferences(_characterId: string, _newAvatarId: string): void {
    void _characterId;
    void _newAvatarId;
    // This would typically integrate with the story generation system
    // For now, just log the operation
  }

  /**
   * Load avatars from the assets folder
   */
  async loadAvatars(_assetsPath: string): Promise<Avatar[]> {
    if (_assetsPath) {
      this.avatars.clear();
    }
    return [];
  }

  /**
   * Filter avatars by name or tags
   */
  filterAvatars(query: string): Avatar[] {
    const lowerQuery = query.toLowerCase();
    return Array.from(this.avatars.values()).filter(avatar =>
      avatar.name.toLowerCase().includes(lowerQuery) ||
      avatar.tags.some(tag => tag.toLowerCase().includes(lowerQuery))
    );
  }

  /**
   * Validate an avatar
   */
  validateAvatar(_avatarPath: string): Promise<AvatarValidationResult> {
    if (_avatarPath) {
      return Promise.resolve({
        isValid: true,
        metadata: {
          dimensions: { width: 512, height: 512 },
          format: 'png',
          size: 1024,
        },
      });
    }
    return Promise.resolve({ isValid: true });
  }

  /**
   * Get casting analytics
   */
  getAnalytics(): CastingAnalytics {
    const characterSceneCounts: Record<string, number> = {};
    const avatarUsageCounts: Record<string, number> = {};
    /* const _assignedCharacterIds = new Set(
      this.state.assignments.map(a => a.characterId)
    ); */

    // Calculate scene counts (simplified - in real implementation would query actual scenes)
    this.sceneReferences.forEach(ref => {
      characterSceneCounts[ref.characterId] = (characterSceneCounts[ref.characterId] || 0) + 1;
    });

    // Calculate avatar usage
    this.state.assignments.forEach(assignment => {
      avatarUsageCounts[assignment.avatarId] = (avatarUsageCounts[assignment.avatarId] || 0) + 1;
    });

    const assignedCharacterIds = new Set(this.state.assignments.map(a => a.characterId));
    const allCharacterIds = new Set(this.sceneReferences.map(ref => ref.characterId));
    const uncastCharacters = Array.from(allCharacterIds).filter(id => !assignedCharacterIds.has(id));

    return {
      characterSceneCounts,
      avatarUsageCounts,
      uniqueActorCount: Object.keys(avatarUsageCounts).length,
      uncastCharacters,
    };
  }

  /**
   * Serialize state to JSON
   */
  serialize(): string {
    return JSON.stringify(this.state, null, 2);
  }

  /**
   * Deserialize state from JSON
   */
  deserialize(data: string): void {
    try {
      const parsed = JSON.parse(data);
      if (this.isValidCastingState(parsed)) {
        this.state = parsed;
      } else {
        console.warn('Invalid casting state format, recovering with defaults');
        this.recoverFromCorruptedData(parsed);
      }
    } catch (error) {
      console.error('Failed to deserialize casting state:', error);
      this.recoverFromCorruptedData(null);
    }
  }

  /**
   * Recover from corrupted data by using defaults
   */
  private recoverFromCorruptedData(data: unknown): void {
    // Try to recover valid assignments if possible
    const recoveredAssignments: CastingAssignment[] = [];
    const d = data as Record<string, unknown>;

    if (d && Array.isArray(d.assignments)) {
      for (const assignment of d.assignments) {
        const a = assignment as Record<string, unknown>;
        if (
          a &&
          typeof a === 'object' &&
          typeof a.characterId === 'string' &&
          typeof a.avatarId === 'string' &&
          typeof a.assignedAt === 'string'
        ) {
          recoveredAssignments.push({
            characterId: a.characterId,
            avatarId: a.avatarId,
            assignedAt: a.assignedAt,
          });
        }
      }
    }

    this.state = {
      assignments: recoveredAssignments,
      version: typeof d?.version === 'string' ? d.version : '1.0',
      lastModified: typeof d?.lastModified === 'string' ? d.lastModified : new Date().toISOString(),
    };

  }

  /**
   * Save state to project.json
   */
  async saveState(// eslint-disable-next-line @typescript-eslint/no-unused-vars
    _projectPath: string
  ): Promise<void> {
  }

  /**
   * Load state from project.json
   */
  async loadState(// eslint-disable-next-line @typescript-eslint/no-unused-vars
    _projectPath: string
  ): Promise<void> {
  }

  /**
   * Get current state
   */
  getState(): CastingState {
    return { ...this.state };
  }

  /**
   * Set scene references (for analytics and scene tracking)
   */
  setSceneReferences(references: SceneReference[]): void {
    this.sceneReferences = [...references];
  }

  /**
   * Add an avatar to the collection
   */
  addAvatar(avatar: Avatar): void {
    this.avatars.set(avatar.id, avatar);
  }

  /**
   * Remove an avatar from the collection
   */
  removeAvatar(avatarId: string): void {
    this.avatars.delete(avatarId);
    // Remove assignments that reference this avatar
    this.state.assignments = this.state.assignments.filter(
      assignment => assignment.avatarId !== avatarId
    );
  }

  /**
   * Undo the last operation
   */
  undo(): boolean {
    if (this.undoStack.length === 0) {
      return false;
    }

    const operation = this.undoStack.pop()!;
    const currentState = this.captureState();

    // Apply the previous state
    if (operation.previousState) {
      this.applyState(operation.previousState);
    }

    // Move operation to redo stack
    this.redoStack.push({
      ...operation,
      previousState: currentState,
      newState: operation.previousState,
    });

    return true;
  }

  /**
   * Redo the last undone operation
   */
  redo(): boolean {
    if (this.redoStack.length === 0) {
      return false;
    }

    const operation = this.redoStack.pop()!;
    const currentState = this.captureState();

    // Apply the new state
    if (operation.newState) {
      this.applyState(operation.newState);
    }

    // Move operation back to undo stack
    this.undoStack.push({
      ...operation,
      previousState: currentState,
      newState: operation.newState,
    });

    return true;
  }

  /**
   * Check if undo is available
   */
  canUndo(): boolean {
    return false;
  }

  /**
   * Check if redo is available
   */
  canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  /**
   * Capture current state for undo/redo
   */
  private captureState(): Partial<CastingState> {
    return {
      assignments: [...this.state.assignments],
      version: this.state.version,
      lastModified: this.state.lastModified,
    };
  }

  /**
   * Record an operation for undo/redo
   */
  private recordOperation(
    type: OperationRecord['type'],
    previousState: Partial<CastingState>,
    newState: Partial<CastingState>,
    description: string
  ): void {
    const operation: OperationRecord = {
      id: crypto.randomUUID(),
      type,
      timestamp: new Date().toISOString(),
      previousState,
      newState,
      description,
    };

    this.undoStack.push(operation);

    // Clear redo stack when new operation is performed
    this.redoStack = [];

    // Maintain maximum history size
    if (this.undoStack.length > this.MAX_HISTORY_SIZE) {
      this.undoStack.shift();
    }
  }

  /**
   * Apply a state for undo/redo
   */
  private applyState(state: Partial<CastingState>): void {
    if (state.assignments) {
      this.state.assignments = [...state.assignments];
    }
    if (state.version) {
      this.state.version = state.version;
    }
    if (state.lastModified) {
      this.state.lastModified = state.lastModified;
    }
  }

  private isValidCastingState(state: unknown): state is CastingState {
    if (state === null || typeof state !== 'object') return false;
    
    const s = state as Record<string, unknown>;
    return (
      Array.isArray(s.assignments) &&
      typeof s.version === 'string' &&
      typeof s.lastModified === 'string'
    );
  }
}

import { User, UserCheck, Plus } from 'lucide-react';
import type { Character } from '@/types/character';
import type { Avatar } from '../types';

interface CharacterCardProps {
  character: Character;
  assignedAvatar?: Avatar | null;
  onCast: () => void;
  onReplace: () => void;
  isSelected?: boolean;
}

export function CharacterCard({
  character,
  assignedAvatar,
  onCast,
  onReplace,
  isSelected = false
}: CharacterCardProps) {
  const isCast = !!assignedAvatar;

  return (
    <div
      className={`
        relative p-4 border rounded-lg transition-all cursor-pointer
        ${isSelected ? 'border-primary bg-primary/5' : 'border-border hover:border-primary/50'}
        ${isCast ? 'bg-green-50 dark:bg-green-950/20' : 'bg-muted/50'}
      `}
      onClick={isCast ? onReplace : onCast}
    >
      {/* Cast Status Indicator */}
      <div className="absolute top-2 right-2">
        {isCast ? (
          <div className="flex items-center gap-1 text-green-600 dark:text-green-400">
            <UserCheck className="w-4 h-4" />
            <span className="text-xs font-medium">Cast</span>
          </div>
        ) : (
          <div className="flex items-center gap-1 text-muted-foreground">
            <User className="w-4 h-4" />
            <span className="text-xs font-medium">Uncast</span>
          </div>
        )}
      </div>

      {/* Character Avatar or Placeholder */}
      <div className="flex items-center gap-4 mb-3">
        <div className="w-12 h-12 rounded-full overflow-hidden bg-muted flex items-center justify-center">
          {assignedAvatar ? (
            <img
              src={assignedAvatar.path}
              alt={assignedAvatar.name}
              className="w-full h-full object-cover"
              onError={(e) => {
                const target = e.target as HTMLImageElement;
                target.style.display = 'none';
                const parent = target.parentElement;
                if (parent) {
                  parent.innerHTML = '<div class="text-muted-foreground text-xs">No image</div>';
                }
              }}
            />
          ) : (
            <div className="text-muted-foreground">
              <User className="w-6 h-6" />
            </div>
          )}
        </div>

        <div className="flex-1">
          <h3 className="font-medium text-sm">{character.name}</h3>
          <p className="text-xs text-muted-foreground">
            {character.role.archetype}
          </p>
        </div>
      </div>

      {/* Actor Info */}
      {assignedAvatar && (
        <div className="mb-3 p-2 bg-background rounded border">
          <p className="text-xs font-medium text-green-700 dark:text-green-300">
            Actor: {assignedAvatar.name}
          </p>
        </div>
      )}

      {/* Action Button */}
      <button
        className={`
          w-full py-2 px-3 rounded-md text-sm font-medium transition-colors
          ${isCast
            ? 'bg-primary text-primary-foreground hover:bg-primary/90'
            : 'bg-secondary text-secondary-foreground hover:bg-secondary/80'
          }
        `}
        onClick={(e) => {
          e.stopPropagation();
          isCast ? onReplace() : onCast();
        }}
      >
        <div className="flex items-center justify-center gap-2">
          {isCast ? (
            <>
              <UserCheck className="w-4 h-4" />
              Replace Actor
            </>
          ) : (
            <>
              <Plus className="w-4 h-4" />
              Cast Actor
            </>
          )}
        </div>
      </button>

      {/* Character Details */}
      <div className="mt-3 pt-3 border-t border-border">
        <div className="text-xs text-muted-foreground space-y-1">
          <div>Age: {character.visual_identity.age_range}</div>
          <div>Function: {character.role.narrative_function || 'Not specified'}</div>
        </div>
      </div>
    </div>
  );
}

import React from 'react';
import { AlertTriangle, CheckCircle, Clock } from 'lucide-react';
import { Button } from '@/components/ui/button';
import type { SceneReference } from '../types';

interface SceneImpactViewProps {
  affectedScenes: SceneReference[];
  characterId: string;
  characterName: string;
  onConfirm: () => void;
  onCancel: () => void;
  isProcessing?: boolean;
}

export function SceneImpactView({
  affectedScenes,
  characterId,
  characterName,
  onConfirm,
  onCancel,
  isProcessing = false
}: SceneImpactViewProps) {
  const sceneCount = affectedScenes.length;

  return (
    <div className="space-y-6">
      {/* Warning Header */}
      <div className="flex items-start gap-3 p-4 bg-amber-50 dark:bg-amber-950/20 border border-amber-200 dark:border-amber-800 rounded-lg">
        <AlertTriangle className="w-5 h-5 text-amber-600 dark:text-amber-400 mt-0.5 flex-shrink-0" />
        <div>
          <h3 className="font-medium text-amber-800 dark:text-amber-200">
            Actor Change Impact
          </h3>
          <p className="text-sm text-amber-700 dark:text-amber-300 mt-1">
            Changing the actor for <strong>{characterName}</strong> will affect{' '}
            <strong>{sceneCount}</strong> scene{sceneCount !== 1 ? 's' : ''}.
            The story generation system will need to regenerate these scenes with the new actor.
          </p>
        </div>
      </div>

      {/* Affected Scenes List */}
      <div className="space-y-4">
        <h4 className="font-medium">Affected Scenes</h4>

        {sceneCount === 0 ? (
          <div className="flex items-center gap-3 p-4 bg-green-50 dark:bg-green-950/20 border border-green-200 dark:border-green-800 rounded-lg">
            <CheckCircle className="w-5 h-5 text-green-600 dark:text-green-400" />
            <div>
              <p className="font-medium text-green-800 dark:text-green-200">No scenes affected</p>
              <p className="text-sm text-green-700 dark:text-green-300">
                This character doesn't appear in any scenes yet.
              </p>
            </div>
          </div>
        ) : (
          <div className="space-y-2 max-h-60 overflow-y-auto">
            {affectedScenes.map((scene) => (
              <SceneItem key={scene.sceneId} scene={scene} />
            ))}
          </div>
        )}
      </div>

      {/* Processing Status */}
      {isProcessing && (
        <div className="flex items-center gap-3 p-4 bg-blue-50 dark:bg-blue-950/20 border border-blue-200 dark:border-blue-800 rounded-lg">
          <Clock className="w-5 h-5 text-blue-600 dark:text-blue-400 animate-spin" />
          <div>
            <p className="font-medium text-blue-800 dark:text-blue-200">Processing changes...</p>
            <p className="text-sm text-blue-700 dark:text-blue-300">
              Updating scene references and preparing for regeneration.
            </p>
          </div>
        </div>
      )}

      {/* Action Buttons */}
      <div className="flex justify-end gap-3 pt-4 border-t">
        <Button
          variant="outline"
          onClick={onCancel}
          disabled={isProcessing}
        >
          Cancel
        </Button>
        <Button
          onClick={onConfirm}
          disabled={isProcessing}
        >
          {isProcessing ? 'Processing...' : 'Confirm Change'}
        </Button>
      </div>
    </div>
  );
}

interface SceneItemProps {
  scene: SceneReference;
}

function SceneItem({ scene }: SceneItemProps) {
  return (
    <div className="flex items-center justify-between p-3 bg-muted/50 rounded-lg border">
      <div className="flex-1">
        <div className="flex items-center gap-2">
          <span className="text-sm font-medium">Scene {scene.sceneId}</span>
          {scene.sceneTitle && (
            <span className="text-xs text-muted-foreground">ÔÇó {scene.sceneTitle}</span>
          )}
        </div>
        <p className="text-xs text-muted-foreground mt-1">
          Character appears in this scene
        </p>
      </div>

      <div className="text-xs text-muted-foreground">
        Will be marked for regeneration
      </div>
    </div>
  );
}

