  // Tests de permissions
  private async testPermissions(): Promise<void> {
    console.log('\n­ƒöÉ Tests de permissions...');
    
    try {
      const state = this.manager.getState();
      
      // V├®rifier les permissions requises
      const requiredPermissions = [
        'read:project',
