      );

    } catch (error) {
      this.addTest('Int├®gration', false, error instanceof Error ? error.message : 'Erreur inconnue');
    }
  }

  // M├®thode helper pour ajouter un test
  private addTest(testName: string, passed: boolean, error?: string, details?: any): void {
    this.testResults.push({
      testName,
      passed,
      error,
      details,
    });
  }

  // Afficher les r├®sultats
  private displayResults(): void {
    console.log('\n­ƒôè R├ëSULTATS DES TESTS');
    console.log('='.repeat(50));
    
    const passedTests = this.testResults.filter(test => test.passed);
    const failedTests = this.testResults.filter(test => !test.passed);
    
    console.log(`Ô£à Tests r├®ussis: ${passedTests.length}/${this.testResults.length}`);
    console.log(`ÔØî Tests ├®chou├®s: ${failedTests.length}/${this.testResults.length}`);
    
    if (failedTests.length > 0) {
      console.log('\n­ƒö┤ Tests ├®chou├®s:');
      failedTests.forEach(test => {
        console.log(`  - ${test.testName}: ${test.error || 'Erreur inconnue'}`);
      });
    }
    
    if (passedTests.length === this.testResults.length) {
      console.log('\n­ƒÄë Tous les tests ont r├®ussi! L\'impl├®mentation MCP est fonctionnelle.');
    } else {
      console.log('\nÔÜá´©Å  Certains tests ont ├®chou├®. Veuillez v├®rifier l\'impl├®mentation.');
    }
    
    console.log('\n' + '='.repeat(50));
  }
}

