import React, { useState } from 'react';
import { Sparkles, Loader2, CheckCircle, AlertCircle, Info } from 'lucide-react';
import type { Shot, SurroundConfig } from '../types';
import { getAIPresetService, type AIPresetSuggestion } from '../services/aiPresetService';
import type { SurroundPreset } from '../components/SurroundPresetsPanel';

interface AISurroundAssistantProps {
  shot: Shot;
  currentConfig: SurroundConfig;
  onApplyPreset: (preset: SurroundPreset) => void;
}

/**
 * AISurroundAssistant - AI-powered surround sound preset suggestions
 * 
 * Features:
 * - "Ask AI" button to trigger analysis
 * - Scene type detection and display
 * - Suggested preset with reasoning
 * - Alternative preset options
 * - One-click preset application
 * - Loading and error states
 * 
 * Requirements: 20.11
 */
export const AISurroundAssistant: React.FC<AISurroundAssistantProps> = ({
  shot,
  currentConfig,
  onApplyPreset,
}) => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [suggestion, setSuggestion] = useState<AIPresetSuggestion | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [appliedPresetId, setAppliedPresetId] = useState<string | null>(null);

  const handleAskAI = async () => {
    setIsAnalyzing(true);
    setError(null);
    setSuggestion(null);
    setAppliedPresetId(null);

    try {
      const aiService = getAIPresetService();
      const result = await aiService.suggestPreset(shot);
      setSuggestion(result);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to analyze scene');
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleApplyPreset = (preset: SurroundPreset) => {
    onApplyPreset(preset);
    setAppliedPresetId(preset.id);

    // Clear applied indicator after 2 seconds
    setTimeout(() => {
      setAppliedPresetId(null);
    }, 2000);
  };

  return (
    <div className="space-y-4 p-4 bg-gradient-to-br from-blue-950/30 to-purple-950/30 rounded-lg border border-blue-800/50">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Sparkles className="w-5 h-5 text-blue-400" />
          <h3 className="text-lg font-semibold text-white">AI Assistant</h3>
        </div>

        <button
          onClick={handleAskAI}
          disabled={isAnalyzing}
          className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-colors ${
            isAnalyzing
              ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
              : 'bg-blue-600 text-white hover:bg-blue-700'
          }`}
        >
          {isAnalyzing ? (
            <>
              <Loader2 className="w-4 h-4 animate-spin" />
              Analyzing...
            </>
          ) : (
            <>
              <Sparkles className="w-4 h-4" />
              Ask AI
            </>
          )}
        </button>
      </div>

      {/* Info message */}
      {!suggestion && !error && !isAnalyzing && (
        <div className="flex items-start gap-2 p-3 bg-blue-950/50 rounded-md border border-blue-800/50">
          <Info className="w-4 h-4 text-blue-400 mt-0.5 flex-shrink-0" />
          <p className="text-sm text-blue-200 dark:text-blue-100">
            Click "Ask AI" to analyze this scene and get intelligent surround sound preset
            recommendations based on the content.
          </p>
        </div>
      )}

      {/* Error state */}
      {error && (
        <div className="flex items-start gap-2 p-3 bg-red-900/20 rounded-md border border-red-800/50">
          <AlertCircle className="w-4 h-4 text-red-400 mt-0.5 flex-shrink-0" />
          <div className="flex-1">
            <p className="text-sm font-medium text-red-300">Analysis Failed</p>
            <p className="text-sm text-red-200 mt-1">{error}</p>
          </div>
        </div>
      )}

      {/* Suggestion result */}
      {suggestion && (
        <div className="space-y-4">
          {/* Scene Analysis */}
          <div className="bg-gray-200 dark:bg-gray-800 p-4 rounded-lg border border-gray-300 dark:border-gray-700">
            <h4 className="text-sm font-semibold text-foreground mb-2">Scene Analysis</h4>
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <span className="text-sm text-muted-foreground">Scene Type:</span>
                <span className="text-sm font-medium text-foreground capitalize">
                  {suggestion.analysis.sceneType}
                </span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-sm text-muted-foreground">Confidence:</span>
                <div className="flex items-center gap-2">
                  <div className="w-24 h-2 bg-gray-300 dark:bg-gray-600 rounded-full overflow-hidden">
                    <div
                      className={`h-full rounded-full ${
                        suggestion.confidence >= 80
                          ? 'bg-green-600'
                          : suggestion.confidence >= 50
                          ? 'bg-yellow-600'
                          : 'bg-red-600'
                      }`}
                      style={{ width: `${suggestion.confidence}%` }}
                    />
                  </div>
                  <span className="text-sm font-medium text-foreground">
                    {suggestion.confidence}%
                  </span>
                </div>
              </div>
              {suggestion.analysis.keywords.length > 0 && (
                <div className="pt-2 border-t border-gray-300 dark:border-gray-700">
                  <span className="text-xs text-muted-foreground">Detected keywords:</span>
                  <div className="flex flex-wrap gap-1 mt-1">
                    {suggestion.analysis.keywords.map((keyword, index) => (
                      <span
                        key={index}
                        className="px-2 py-0.5 text-xs bg-blue-950/50 text-blue-300 rounded border border-blue-800/50"
                      >
                        {keyword}
                      </span>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Suggested Preset */}
          <div className="bg-gray-200 dark:bg-gray-800 p-4 rounded-lg border-2 border-blue-600">
            <div className="flex items-center justify-between mb-3">
              <h4 className="text-sm font-semibold text-white dark:text-white">Recommended Preset</h4>
              <span className="text-xs px-2 py-1 bg-blue-950/50 text-blue-300 rounded font-medium border border-blue-800/50">
                {suggestion.preset.mode}
              </span>
            </div>

            <div className="space-y-3">
              <div>
                <h5 className="text-base font-medium text-white dark:text-white">
                  {suggestion.preset.name}
                </h5>
                <p className="text-sm text-gray-600 dark:text-gray-300 mt-1">
                  {suggestion.preset.description}
                </p>
              </div>

              <div className="p-3 bg-blue-950/30 rounded-md border border-blue-800/50">
                <p className="text-sm text-blue-200 dark:text-blue-100">{suggestion.reasoning}</p>
              </div>

              {/* Channel levels preview */}
              <div className="space-y-1">
                <span className="text-xs text-gray-600 dark:text-gray-300">Channel Configuration:</span>
                <div className="grid grid-cols-2 gap-2">
                  {Object.entries(suggestion.preset.channels).map(([channel, level]) => {
                    if (typeof level !== 'number') return null;
                    return (
                      <div key={channel} className="flex items-center gap-2">
                        <span className="text-xs text-gray-600 dark:text-gray-300 w-16 truncate">
                          {channel}:
                        </span>
                        <div className="flex-1 h-1.5 bg-gray-300 dark:bg-gray-600 rounded-full overflow-hidden">
                          <div
                            className="h-full bg-blue-600 rounded-full"
                            style={{ width: `${level}%` }}
                          />
                        </div>
                        <span className="text-xs text-gray-600 dark:text-gray-300 w-8 text-right">
                          {level}%
                        </span>
                      </div>
                    );
                  })}
                </div>
              </div>

              <button
                onClick={() => handleApplyPreset(suggestion.preset)}
                disabled={appliedPresetId === suggestion.preset.id}
                className={`w-full px-4 py-2 rounded-md text-sm font-medium flex items-center justify-center gap-2 transition-colors ${
                  appliedPresetId === suggestion.preset.id
                    ? 'bg-green-600 text-white'
                    : 'bg-blue-600 text-white hover:bg-blue-700'
                }`}
              >
                {appliedPresetId === suggestion.preset.id ? (
                  <>
                    <CheckCircle className="w-4 h-4" />
                    Applied!
                  </>
                ) : (
                  'Apply This Preset'
                )}
              </button>
            </div>
          </div>

          {/* Alternative Presets */}
          {suggestion.alternativePresets && suggestion.alternativePresets.length > 0 && (
            <div className="space-y-2">
              <h4 className="text-sm font-semibold text-white dark:text-white">Alternative Options</h4>
              <div className="grid grid-cols-2 gap-2">
                {suggestion.alternativePresets.map((preset) => (
                  <div
                    key={preset.id}
                    className="bg-gray-200 dark:bg-gray-800 p-3 rounded-lg border border-gray-300 dark:border-gray-700 hover:border-blue-400 transition-colors cursor-pointer"
                    onClick={() => handleApplyPreset(preset)}
                  >
                    <div className="flex items-center justify-between mb-1">
                      <h5 className="text-sm font-medium text-white dark:text-white">{preset.name}</h5>
                      <span className="text-xs px-1.5 py-0.5 bg-gray-300 dark:bg-gray-600 text-gray-700 dark:text-gray-300 rounded">
                        {preset.mode}
                      </span>
                    </div>
                    <p className="text-xs text-gray-600 dark:text-gray-300">{preset.description}</p>
                    {appliedPresetId === preset.id && (
                      <div className="mt-2 flex items-center gap-1 text-green-600">
                        <CheckCircle className="w-3 h-3" />
                        <span className="text-xs font-medium">Applied</span>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {/* Scene info */}
      <div className="pt-3 border-t border-blue-800/50">
        <div className="text-xs text-gray-600 dark:text-gray-300 space-y-1">
          <div>
            <span className="font-medium">Scene:</span> {shot.title}
          </div>
          {shot.description && (
            <div>
              <span className="font-medium">Description:</span>{' '}
              {shot.description.slice(0, 100)}
              {shot.description.length > 100 && '...'}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

/**
 * Compact version of AI Assistant for inline use
 */
export const AISurroundAssistantCompact: React.FC<AISurroundAssistantProps> = ({
  shot,
  currentConfig,
  onApplyPreset,
}) => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [suggestion, setSuggestion] = useState<AIPresetSuggestion | null>(null);

  const handleQuickSuggest = async () => {
    setIsAnalyzing(true);

    try {
      const aiService = getAIPresetService();
      const result = await aiService.suggestPreset(shot);
      setSuggestion(result);

      // Auto-apply if high confidence
      if (result.confidence >= 80) {
        onApplyPreset(result.preset);
      }
    } catch (err) {
      console.error('AI suggestion failed:', err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="flex items-center gap-2">
      <button
        onClick={handleQuickSuggest}
        disabled={isAnalyzing}
        className="px-3 py-1.5 text-sm bg-blue-600 text-white rounded-md hover:bg-blue-700 disabled:bg-gray-300 disabled:cursor-not-allowed flex items-center gap-2"
      >
        {isAnalyzing ? (
          <Loader2 className="w-3 h-3 animate-spin" />
        ) : (
          <Sparkles className="w-3 h-3" />
        )}
        AI Suggest
      </button>

      {suggestion && (
        <span className="text-xs text-muted-foreground">
          Suggested: <span className="font-medium">{suggestion.preset.name}</span>
        </span>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useStore } from '../store';
import type { Animation, Keyframe, Point } from '../types';
import { BezierCurveEditor } from './BezierCurveEditor';

interface AnimationPanelProps {
  shotId: string;
}

export const AnimationPanel: React.FC<AnimationPanelProps> = ({ shotId }) => {
  const shot = useStore((state) => state.shots.find((s) => s.id === shotId));
  const addAnimation = useStore((state) => state.addAnimation);
  const updateAnimation = useStore((state) => state.updateAnimation);
  const deleteAnimation = useStore((state) => state.deleteAnimation);

  const [selectedProperty, setSelectedProperty] = useState<
    'position' | 'scale' | 'rotation' | 'opacity'
  >('position');

  if (!shot) {
    return (
      <div className="p-4 text-gray-500">
        No shot selected. Select a shot to manage animations.
      </div>
    );
  }

  // Find animation for selected property
  const currentAnimation = shot.animations.find(
    (anim) => anim.property === selectedProperty
  );

  const handleAddAnimation = () => {
    if (currentAnimation) return; // Already exists

    const newAnimation: Animation = {
      id: `anim-${Date.now()}`,
      property: selectedProperty,
      keyframes: [],
    };

    addAnimation(shotId, newAnimation);
  };

  const handleDeleteAnimation = () => {
    if (!currentAnimation) return;
    deleteAnimation(shotId, currentAnimation.id);
  };

  const handleAddKeyframe = () => {
    if (!currentAnimation) return;

    const newKeyframe: Keyframe = {
      id: `keyframe-${Date.now()}`,
      time: 0,
      value: selectedProperty === 'position' ? { x: 0, y: 0 } : 1,
      easing: 'linear',
    };

    const updatedKeyframes = [...currentAnimation.keyframes, newKeyframe];
    updateAnimation(shotId, currentAnimation.id, { keyframes: updatedKeyframes });
  };

  const handleDeleteKeyframe = (keyframeId: string) => {
    if (!currentAnimation) return;

    const updatedKeyframes = currentAnimation.keyframes.filter(
      (kf) => kf.id !== keyframeId
    );
    updateAnimation(shotId, currentAnimation.id, { keyframes: updatedKeyframes });
  };

  const handleUpdateKeyframe = (
    keyframeId: string,
    updates: Partial<Keyframe>
  ) => {
    if (!currentAnimation) return;

    const updatedKeyframes = currentAnimation.keyframes.map((kf) =>
      kf.id === keyframeId ? { ...kf, ...updates } : kf
    );
    updateAnimation(shotId, currentAnimation.id, { keyframes: updatedKeyframes });
  };

  // Sort keyframes by time
  const sortedKeyframes = currentAnimation
    ? [...currentAnimation.keyframes].sort((a, b) => a.time - b.time)
    : [];

  return (
    <div className="p-4 space-y-4">
      <div>
        <h3 className="text-lg font-semibold mb-2">Keyframe Animation</h3>
        <p className="text-sm text-gray-600">
          Animate shot properties over time using keyframes
        </p>
      </div>

      {/* Property Selector */}
      <div>
        <label className="block text-sm font-medium mb-2">
          Animated Property
        </label>
        <div className="grid grid-cols-2 gap-2">
          {(['position', 'scale', 'rotation', 'opacity'] as const).map(
            (property) => (
              <button
                key={property}
                onClick={() => setSelectedProperty(property)}
                className={`px-4 py-2 rounded border capitalize ${
                  selectedProperty === property
                    ? 'bg-blue-500 text-white border-blue-600'
                    : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'
                }`}
              >
                {property}
              </button>
            )
          )}
        </div>
      </div>

      {/* Animation Controls */}
      <div className="border-t pt-4">
        {!currentAnimation ? (
          <div className="text-center py-8">
            <p className="text-gray-500 mb-4">
              No animation for {selectedProperty}
            </p>
            <button
              onClick={handleAddAnimation}
              className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600"
            >
              Add Animation
            </button>
          </div>
        ) : (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h4 className="font-medium">
                {selectedProperty.charAt(0).toUpperCase() +
                  selectedProperty.slice(1)}{' '}
                Animation
              </h4>
              <button
                onClick={handleDeleteAnimation}
                className="px-3 py-1 text-sm text-red-600 border border-red-300 rounded hover:bg-red-50"
              >
                Remove Animation
              </button>
            </div>

            {/* Keyframes List */}
            <div>
              <div className="flex items-center justify-between mb-2">
                <label className="text-sm font-medium">Keyframes</label>
                <button
                  onClick={handleAddKeyframe}
                  className="px-3 py-1 text-sm bg-green-500 text-white rounded hover:bg-green-600"
                >
                  Add Keyframe
                </button>
              </div>

              {sortedKeyframes.length === 0 ? (
                <div className="text-center py-4 text-gray-500 text-sm border border-dashed rounded">
                  No keyframes. Add a keyframe to start animating.
                </div>
              ) : (
                <div className="space-y-3">
                  {sortedKeyframes.map((keyframe, index) => (
                    <KeyframeEditor
                      key={keyframe.id}
                      keyframe={keyframe}
                      index={index}
                      property={selectedProperty}
                      shotDuration={shot.duration}
                      onUpdate={(updates) =>
                        handleUpdateKeyframe(keyframe.id, updates)
                      }
                      onDelete={() => handleDeleteKeyframe(keyframe.id)}
                    />
                  ))}
                </div>
              )}
            </div>

            {/* Keyframe Timeline Visualization */}
            {sortedKeyframes.length > 0 && (
              <div className="mt-4">
                <label className="text-sm font-medium mb-2 block">
                  Timeline
                </label>
                <KeyframeTimeline
                  keyframes={sortedKeyframes}
                  duration={shot.duration}
                  property={selectedProperty}
                />
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

// Keyframe Editor Component
interface KeyframeEditorProps {
  keyframe: Keyframe;
  index: number;
  property: 'position' | 'scale' | 'rotation' | 'opacity';
  shotDuration: number;
  onUpdate: (updates: Partial<Keyframe>) => void;
  onDelete: () => void;
}

const KeyframeEditor: React.FC<KeyframeEditorProps> = ({
  keyframe,
  index,
  property,
  shotDuration,
  onUpdate,
  onDelete,
}) => {
  const isPositionProperty = property === 'position';
  const value = keyframe.value as any;

  return (
    <div className="p-3 border rounded bg-gray-50 space-y-2">
      <div className="flex items-center justify-between">
        <span className="text-sm font-medium">Keyframe {index + 1}</span>
        <button
          onClick={onDelete}
          className="text-red-600 hover:text-red-800 text-sm"
        >
          Delete
        </button>
      </div>

      {/* Time */}
      <div>
        <label id={`time-label-${keyframe.id}`} className="text-xs text-gray-600">Time (seconds)</label>
        <input
          type="number"
          min={0}
          max={shotDuration}
          step={0.1}
          value={keyframe.time}
          onChange={(e) => onUpdate({ time: parseFloat(e.target.value) })}
          className="w-full px-2 py-1 text-sm border rounded"
          aria-labelledby={`time-label-${keyframe.id}`}
        />
      </div>

      {/* Value */}
      {isPositionProperty ? (
        <div className="grid grid-cols-2 gap-2">
          <div>
            <label id={`x-label-${keyframe.id}`} className="text-xs text-gray-600">X</label>
            <input
              type="number"
              step={1}
              value={value.x}
              onChange={(e) =>
                onUpdate({ value: { ...value, x: parseFloat(e.target.value) } })
              }
              className="w-full px-2 py-1 text-sm border rounded"
              aria-labelledby={`x-label-${keyframe.id}`}
            />
          </div>
          <div>
            <label id={`y-label-${keyframe.id}`} className="text-xs text-gray-600">Y</label>
            <input
              type="number"
              step={1}
              value={value.y}
              onChange={(e) =>
                onUpdate({ value: { ...value, y: parseFloat(e.target.value) } })
              }
              className="w-full px-2 py-1 text-sm border rounded"
              aria-labelledby={`y-label-${keyframe.id}`}
            />
          </div>
        </div>
      ) : (
        <div>
          <label id={`value-label-${keyframe.id}`} className="text-xs text-gray-600">
            {property === 'scale' && 'Scale'}
            {property === 'rotation' && 'Rotation (degrees)'}
            {property === 'opacity' && 'Opacity (0-1)'}
          </label>
          <input
            type="number"
            step={property === 'opacity' ? 0.1 : 1}
            min={property === 'opacity' ? 0 : undefined}
            max={property === 'opacity' ? 1 : undefined}
            value={value}
            onChange={(e) => onUpdate({ value: parseFloat(e.target.value) })}
            className="w-full px-2 py-1 text-sm border rounded"
            aria-labelledby={`value-label-${keyframe.id}`}
          />
        </div>
      )}

      {/* Easing */}
      <div>
        <label id={`easing-label-${keyframe.id}`} className="text-xs text-gray-600">Easing</label>
        <select
          value={keyframe.easing}
          onChange={(e) =>
            onUpdate({
              easing: e.target.value as Keyframe['easing'],
            })
          }
          className="w-full px-2 py-1 text-sm border rounded"
          aria-labelledby={`easing-label-${keyframe.id}`}
        >
          <option value="linear">Linear</option>
          <option value="ease-in">Ease In</option>
          <option value="ease-out">Ease Out</option>
          <option value="ease-in-out">Ease In-Out</option>
          <option value="bezier">Bezier (Custom)</option>
        </select>
      </div>

      {/* Bezier Curve Editor */}
      {keyframe.easing === 'bezier' && (
        <div className="mt-2 p-2 border rounded bg-white">
          <BezierCurveEditor
            controlPoint1={
              keyframe.bezierControlPoints?.cp1 || { x: 0.25, y: 0.25 }
            }
            controlPoint2={
              keyframe.bezierControlPoints?.cp2 || { x: 0.75, y: 0.75 }
            }
            onChange={(cp1: Point, cp2: Point) =>
              onUpdate({
                bezierControlPoints: { cp1, cp2 },
              })
            }
          />
        </div>
      )}
    </div>
  );
};

// Keyframe Timeline Visualization
interface KeyframeTimelineProps {
  keyframes: Keyframe[];
  duration: number;
  property: 'position' | 'scale' | 'rotation' | 'opacity';
}

const KeyframeTimeline: React.FC<KeyframeTimelineProps> = ({
  keyframes,
  duration,
}) => {
  return (
    <div className="relative h-16 bg-gray-100 border rounded overflow-hidden">
      {/* Time markers */}
      <div className="absolute inset-0 flex">
        {Array.from({ length: Math.ceil(duration) + 1 }).map((_, i) => (
          <div
            key={i}
            className="flex-1 border-r border-gray-300 relative"
            style={{ minWidth: '40px' }}
          >
            <span className="absolute bottom-0 left-1 text-xs text-gray-500">
              {i}s
            </span>
          </div>
        ))}
      </div>

      {/* Keyframe markers */}
      {keyframes.map((keyframe, index) => {
        const position = (keyframe.time / duration) * 100;
        return (
          <div
            key={keyframe.id}
            className="absolute top-2 w-3 h-3 bg-blue-500 rounded-full border-2 border-white shadow-md"
            style={{ left: `${position}%`, transform: 'translateX(-50%)' }}
            title={`Keyframe ${index + 1} at ${keyframe.time.toFixed(1)}s`}
          />
        );
      })}

      {/* Connection lines between keyframes */}
      {keyframes.length > 1 && (
        <svg className="absolute inset-0 pointer-events-none">
          {keyframes.slice(0, -1).map((keyframe, index) => {
            const nextKeyframe = keyframes[index + 1];
            const x1 = (keyframe.time / duration) * 100;
            const x2 = (nextKeyframe.time / duration) * 100;
            return (
              <line
                key={`line-${keyframe.id}`}
                x1={`${x1}%`}
                y1="50%"
                x2={`${x2}%`}
                y2="50%"
                stroke="#3b82f6"
                strokeWidth="2"
                strokeDasharray="4 2"
              />
            );
          })}
        </svg>
      )}
    </div>
  );
};

import { Asset } from '@/types';
import {
  ImageIcon,
  MusicIcon,
  FileIcon,
  SparklesIcon,
  ZapIcon,
  TypeIcon,
  GripVerticalIcon,
} from 'lucide-react';
import { Card, CardContent } from '@/components/ui/card';
import { useDrag } from 'react-dnd';
import { DND_ITEM_TYPES, type AssetDragItem } from '@/constants/dnd';

// ============================================================================
// AssetCard Component
// ============================================================================

interface AssetCardProps {
  asset: Asset;
  onSelect?: (asset: Asset) => void;
}

export function AssetCard({ asset, onSelect }: AssetCardProps) {
  // Set up drag functionality
  const [{ isDragging }, drag, preview] = useDrag<AssetDragItem, void, { isDragging: boolean }>({
    type: DND_ITEM_TYPES.ASSET,
    item: {
      type: DND_ITEM_TYPES.ASSET,
      asset: {
        id: asset.id,
        name: asset.name,
        type: asset.type,
        url: asset.url,
        thumbnail: asset.thumbnail,
        metadata: asset.metadata,
      },
    },
    collect: (monitor) => ({
      isDragging: monitor.isDragging(),
    }),
  });

  // Get icon based on asset type
  const getAssetIcon = () => {
    switch (asset.type) {
      case 'image':
        return <ImageIcon className="h-8 w-8 text-blue-500" />;
      case 'audio':
        return <MusicIcon className="h-8 w-8 text-purple-500" />;
      case 'template':
        return <FileIcon className="h-8 w-8 text-green-500" />;
      case 'video':
        return <FileIcon className="h-8 w-8 text-orange-500" />;
      default:
        return <FileIcon className="h-8 w-8 text-gray-500" />;
    }
  };

  // Get category badge color
  const getCategoryColor = () => {
    switch (asset.type) {
      case 'image':
        return 'bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300';
      case 'audio':
        return 'bg-purple-100 text-purple-700 dark:bg-purple-900 dark:text-purple-300';
      case 'template':
        return 'bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300';
      case 'video':
        return 'bg-orange-100 text-orange-700 dark:bg-orange-900 dark:text-orange-300';
      default:
        return 'bg-gray-100 text-gray-700 dark:bg-gray-900 dark:text-gray-300';
    }
  };

  // Get subcategory icon if available in metadata
  const getSubcategoryIcon = () => {
    const subcategory = asset.metadata?.subcategory;
    if (!subcategory) return null;

    switch (subcategory) {
      case 'transition':
        return <SparklesIcon className="h-3 w-3" />;
      case 'effect':
        return <ZapIcon className="h-3 w-3" />;
      case 'text-template':
        return <TypeIcon className="h-3 w-3" />;
      default:
        return null;
    }
  };

  return (
    <div ref={preview as any} style={{ opacity: isDragging ? 0.5 : 1 }}>
      <Card
        className="group cursor-pointer transition-all hover:shadow-lg hover:scale-105 hover:border-primary"
        onClick={() => onSelect?.(asset)}
      >
        <CardContent className="p-3">
          {/* Drag Handle */}
          <div
            ref={drag as any}
            className="absolute top-2 right-2 cursor-grab active:cursor-grabbing opacity-0 group-hover:opacity-100 transition-opacity z-10"
            title="Drag to use"
          >
            <GripVerticalIcon className="h-4 w-4 text-muted-foreground" />
          </div>

          {/* Thumbnail or Icon */}
          <div className="relative mb-2 flex h-24 items-center justify-center rounded-md bg-muted overflow-hidden">
            {asset.thumbnail ? (
              <img
                src={asset.thumbnail}
                alt={asset.name}
                className="h-full w-full object-cover"
              />
            ) : (
              <div className="flex items-center justify-center">
                {getAssetIcon()}
              </div>
            )}

            {/* Hover overlay */}
            <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
              <span className="text-white text-xs font-medium">
                {isDragging ? 'Dragging...' : 'Click or drag to use'}
              </span>
            </div>
          </div>

          {/* Asset Info */}
          <div className="space-y-1">
            <h4 className="text-sm font-medium truncate" title={asset.name}>
              {asset.name}
            </h4>

            <div className="flex items-center justify-between">
              {/* Type Badge */}
              <span
                className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium ${getCategoryColor()}`}
              >
                {getSubcategoryIcon()}
                {(asset.metadata?.subcategory as string) || asset.type}
              </span>

              {/* Additional metadata */}
              {asset.metadata?.duration && (
                <span className="text-xs text-muted-foreground">
                  {asset.metadata.duration as number}s
                </span>
              )}
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useMemo, useRef, useCallback } from 'react';
import { Asset } from '@/types';
import { AssetCard } from './AssetCard';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  SearchIcon,
  ImageIcon,
  MusicIcon,
  FileIcon,
  SparklesIcon,
  ZapIcon,
  TypeIcon,
  UploadIcon,
} from 'lucide-react';
import { useStore } from '@/store';
import { useVirtualScroll, useScrollPosition } from '@/hooks/useVirtualScroll';
import { generateThumbnail } from '@/utils/imageOptimization';
import { debounce } from '@/utils/memoization';

// ============================================================================
// AssetLibrary Component
// ============================================================================

interface AssetLibraryProps {
  assets: Asset[];
  onAssetSelect?: (asset: Asset) => void;
}

// Asset categories with their display info
const CATEGORIES = [
  { id: 'all' as const, label: 'All Assets', icon: FileIcon },
  { id: 'images' as const, label: 'Images', icon: ImageIcon, type: 'image' as const },
  { id: 'audio' as const, label: 'Audio', icon: MusicIcon, type: 'audio' as const },
  { id: 'templates' as const, label: 'Templates', icon: FileIcon, type: 'template' as const, subcategory: null as null },
  { id: 'transitions' as const, label: 'Transitions', icon: SparklesIcon, type: 'template' as const, subcategory: 'transition' as const },
  { id: 'effects' as const, label: 'Effects', icon: ZapIcon, type: 'template' as const, subcategory: 'effect' as const },
  { id: 'text-templates' as const, label: 'Text Templates', icon: TypeIcon, type: 'template' as const, subcategory: 'text-template' as const },
] as const;

export function AssetLibrary({ assets, onAssetSelect }: AssetLibraryProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('all');
  const [scrollTop, setScrollTop] = useState(0);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const addAsset = useStore((state) => state.addAsset);

  // Debounced search to improve performance
  const debouncedSetSearchQuery = useMemo(
    () => debounce((value: string) => setSearchQuery(value), 300),
    []
  );

  // Track scroll position for virtual scrolling
  useScrollPosition(scrollContainerRef, setScrollTop);

  // Handle file upload with optimized thumbnail generation
  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    for (const file of Array.from(files)) {
      try {
        // Determine asset type based on file extension
        const assetType = categorizeFile(file);

        // Generate optimized thumbnail for images
        let thumbnail: string | undefined;
        if (assetType === 'image') {
          thumbnail = await generateThumbnail(file, {
            maxWidth: 200,
            maxHeight: 200,
            quality: 0.8,
            format: 'jpeg',
          });
        }

        // Create asset object
        const asset: Asset = {
          id: `asset-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
          name: file.name,
          type: assetType,
          url: URL.createObjectURL(file),
          thumbnail,
          metadata: {
            id: `meta-${Date.now()}`,
            filename: file.name,
            type: assetType,
            path: '',
            imported_at: new Date().toISOString(),
            size: file.size,
            lastModified: file.lastModified,
            mimeType: file.type,
          } as any,
        };

        // Add to store
        addAsset(asset);
      } catch (error) {
        console.error('Error uploading file:', file.name, error);
      }
    }

    // Reset file input
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  // Categorize file by extension
  const categorizeFile = (file: File): 'image' | 'audio' | 'template' => {
    const extension = file.name.split('.').pop()?.toLowerCase();

    // Image extensions
    if (['jpg', 'jpeg', 'png', 'gif', 'webp', 'svg'].includes(extension || '')) {
      return 'image';
    }

    // Audio extensions
    if (['mp3', 'wav', 'ogg', 'm4a', 'aac', 'flac'].includes(extension || '')) {
      return 'audio';
    }

    // Template extensions (JSON)
    if (extension === 'json') {
      return 'template';
    }

    // Default to template for unknown types
    return 'template';
  };

  // Generate thumbnail for image files (removed - now using imageOptimization.ts)

  // Filter assets based on search query and active category
  const filteredAssets = useMemo(() => {
    let filtered = assets;

    // Filter by category
    if (activeCategory !== 'all') {
      const category = CATEGORIES.find((c) => c.id === activeCategory);
      if (category && 'type' in category) {
        filtered = filtered.filter((asset) => {
          // Match type
          if (category.type && asset.type !== category.type) {
            return false;
          }
          // Match subcategory if specified
          if ('subcategory' in category && category.subcategory !== undefined) {
            return asset.metadata?.subcategory === category.subcategory;
          }
          // For 'templates' category, show only templates without specific subcategories
          if (activeCategory === 'templates') {
            return asset.type === 'template' &&
              !['transition', 'effect', 'text-template'].includes(asset.metadata?.subcategory ?? '');
          }
          return true;
        });
      }
    }

    // Filter by search query
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter(
        (asset) =>
          asset.name.toLowerCase().includes(query) ||
          asset.type.toLowerCase().includes(query) ||
          asset.metadata?.subcategory?.toLowerCase().includes(query) ||
          asset.metadata?.tags?.some((tag: string) => tag.toLowerCase().includes(query))
      );
    }

    return filtered;
  }, [assets, activeCategory, searchQuery]);

  // Get count for each category (memoized for performance)
  const getCategoryCount = useCallback((categoryId: string) => {
    if (categoryId === 'all') return assets.length;

    const category = CATEGORIES.find((c) => c.id === categoryId);
    if (!category || !('type' in category)) return 0;

    return assets.filter((asset) => {
      if (category.type && asset.type !== category.type) {
        return false;
      }
      if ('subcategory' in category && category.subcategory !== undefined) {
        return asset.metadata?.subcategory === category.subcategory;
      }
      // Handle templates category specifically
      if (categoryId === 'templates') {
        return asset.type === 'template' &&
          !['transition', 'effect', 'text-template'].includes(asset.metadata?.subcategory ?? '');
      }
      return true;
    }).length;
  }, [assets]);

  // Virtual scrolling for large asset lists
  const ITEM_HEIGHT = 240; // Approximate height of asset card
  const CONTAINER_HEIGHT = 600; // Approximate container height

  const { virtualItems, totalHeight } = useVirtualScroll(filteredAssets, {
    itemHeight: ITEM_HEIGHT,
    containerHeight: CONTAINER_HEIGHT,
    overscan: 2,
  });

  // Use virtual scrolling only for large lists (> 50 items)
  const useVirtualization = filteredAssets.length > 50;

  return (
    <div className="flex h-full flex-col bg-background">
      {/* Header */}
      <div className="border-b p-4">
        <div className="flex items-center justify-between mb-3">
          <h2 className="text-lg font-semibold">Asset Library</h2>

          {/* Upload Button */}
          <Button
            size="sm"
            onClick={() => fileInputRef.current?.click()}
            className="gap-2"
          >
            <UploadIcon className="h-4 w-4" />
            Upload
          </Button>

          {/* Hidden file input */}
          <input
            ref={fileInputRef}
            type="file"
            multiple
            accept="image/*,audio/*,.json"
            onChange={handleFileUpload}
            className="hidden"
            aria-label="Upload assets"
            title="Upload assets"
          />
        </div>

        {/* Search Input */}
        <div className="relative">
          <SearchIcon className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            type="text"
            placeholder="Search assets..."
            defaultValue={searchQuery}
            onChange={(e) => debouncedSetSearchQuery(e.target.value)}
            className="pl-9"
          />
        </div>
      </div>

      {/* Category Tabs */}
      <Tabs
        value={activeCategory}
        onValueChange={setActiveCategory}
        className="flex-1 flex flex-col overflow-hidden"
      >
        <div className="border-b px-4">
          <TabsList className="w-full justify-start overflow-x-auto">
            {CATEGORIES.map((category) => {
              const Icon = category.icon;
              const count = getCategoryCount(category.id);

              return (
                <TabsTrigger
                  key={category.id}
                  value={category.id}
                  className="flex items-center gap-2"
                >
                  <Icon className="h-4 w-4" />
                  <span>{category.label}</span>
                  <span className="ml-1 rounded-full bg-muted px-2 py-0.5 text-xs">
                    {count}
                  </span>
                </TabsTrigger>
              );
            })}
          </TabsList>
        </div>

        {/* Asset Grid */}
        <ScrollArea className="flex-1" ref={scrollContainerRef}>
          {CATEGORIES.map((category) => (
            <TabsContent
              key={category.id}
              value={category.id}
              className="mt-0 p-4"
            >
              {filteredAssets.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-12 text-center">
                  <div className="rounded-full bg-muted p-4 mb-4">
                    <FileIcon className="h-8 w-8 text-muted-foreground" />
                  </div>
                  <h3 className="text-lg font-medium mb-1">No assets found</h3>
                  <p className="text-sm text-muted-foreground">
                    {searchQuery
                      ? 'Try adjusting your search query'
                      : 'Upload assets to get started'}
                  </p>
                </div>
              ) : useVirtualization ? (
                // Virtual scrolling for large lists
                <div style={{ height: totalHeight, position: 'relative' }}>
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                    {virtualItems.map(({ index, item, offsetTop }) => (
                      <div
                        key={item.id}
                        style={{
                          position: 'absolute',
                          top: offsetTop,
                          left: 0,
                          right: 0,
                        }}
                      >
                        <AssetCard
                          asset={item}
                          onSelect={onAssetSelect}
                        />
                      </div>
                    ))}
                  </div>
                </div>
              ) : (
                // Regular grid for small lists
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                  {filteredAssets.map((asset) => (
                    <AssetCard
                      key={asset.id}
                      asset={asset}
                      onSelect={onAssetSelect}
                    />
                  ))}
                </div>
              )}
            </TabsContent>
          ))}
        </ScrollArea>
      </Tabs>
    </div>
  );
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { AssetLibraryService, type AssetSource, ASSET_CATEGORIES } from '@/services/assetLibraryService';
import { useToast } from '@/hooks/use-toast';
import {
  Plus,
  Image as ImageIcon,
  Music,
  Video,
  FileText,
  RefreshCw,
  Loader2,
  Check,
  X,
  Trash2,
  Copy,
  Grid,
  List,
  Square,
  Info,
  WifiOff,
  Cloud,
  Database
} from 'lucide-react';
import { VaultGallery } from './workspace/VaultGallery';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { ImageWithHoverButton } from '@/components/camera-angle-editor/ImageHoverButton';
import { useLocalCameraAngleEditorModal } from '@/contexts/CameraAngleEditorContext';
import { CameraAngleEditorModal } from '@/components/camera-angle-editor/CameraAngleEditorModal';

interface AssetPanelProps {
  readonly projectPath?: string;
  readonly className?: string;
}

interface Asset {
  id: string;
  name: string;
  type: 'image' | 'audio' | 'video' | 'template';
  url: string;
  thumbnail?: string;
  metadata?: Record<string, unknown>;
}

/**
 * Helper function to render the appropriate icon based on asset type
 */
const renderAssetTypeIcon = (type: Asset['type']): React.ReactNode => {
  switch (type) {
    case 'image':
      return <ImageIcon className="w-5 h-5 text-muted-foreground" />;
    case 'audio':
      return <Music className="w-5 h-5 text-muted-foreground" />;
    case 'video':
      return <Video className="w-5 h-5 text-muted-foreground" />;
    default:
      return <FileText className="w-5 h-5 text-muted-foreground" />;
  }
};

export function AssetPanel({ projectPath, className }: AssetPanelProps) {
  const { toast } = useToast();

  // Camera angle editor modal state
  const {
    isOpen: isCameraAngleModalOpen,
    imageId: cameraAngleImageId,
    imagePath: cameraAngleImagePath,
    openModal: openCameraAngleModal,
    closeModal: closeCameraAngleModal,
  } = useLocalCameraAngleEditorModal();

  // Asset library state
  const [assetSources, setAssetSources] = useState<AssetSource[]>([]);
  const [filteredAssets, setFilteredAssets] = useState<Asset[]>([]);
  const [assetSearchQuery, setAssetSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [isLoadingAssets, setIsLoadingAssets] = useState(false);

  // Selection state
  const [selectedAssetIds, setSelectedAssetIds] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [activeTab, setActiveTab] = useState<'library' | 'vault'>('library');
  const [lastSelectedIndex, setLastSelectedIndex] = useState<number | null>(null);
  const assetListRef = useRef<HTMLDivElement>(null);

  /**
   * Helper function to render thumbnail content for an asset
   */
  const renderThumbnail = useCallback((asset: Asset, isImage: boolean): React.ReactNode => {
    if (!asset.thumbnail) {
      return renderAssetTypeIcon(asset.type);
    }
    
    if (isImage) {
      return (
        <ImageWithHoverButton
          src={asset.thumbnail}
          alt={asset.name}
          imageId={asset.id}
          imagePath={asset.url || asset.thumbnail}
          onClick={openCameraAngleModal}
          buttonLabel="Edit Angle"
          enableScaleEffect={false}
          imageClassName="w-full h-full object-cover"
        />
      );
    }
    
    return (
      <img
        src={asset.thumbnail}
        alt={asset.name}
        className="w-full h-full object-cover"
      />
    );
  }, [openCameraAngleModal]);

  // Load assets on mount
  useEffect(() => {
    const loadAssets = async () => {
      setIsLoadingAssets(true);
      try {
        const service = AssetLibraryService.getInstance();
        const sources = await service.getAllAssets(projectPath || undefined);
        setAssetSources(sources);

        // Flatten all assets for initial display
        const allAssets = sources.flatMap(s => s.assets);
        setFilteredAssets(allAssets);

        // Show success message if assets were loaded
        if (allAssets.length > 0) {
          toast({
            title: 'Assets Loaded',
            description: `Loaded ${allAssets.length} assets from ${sources.length} sources`,
          });
        }

      } catch (error) {
        console.error('Failed to load assets:', error);
        toast({
          title: 'Asset Loading Error',
          description: 'Failed to load asset library. Running in demo mode.',
          variant: 'destructive',
        });
      } finally {
        setIsLoadingAssets(false);
      }
    };

    loadAssets();
  }, [projectPath, toast]);

  // Handle asset selection
  const handleAssetSelect = useCallback((
    assetId: string,
    index: number,
    event?: React.MouseEvent
  ) => {
    const newSelectedIds = new Set(selectedAssetIds);

    if (event?.ctrlKey || event?.metaKey) {
      // Toggle selection for Ctrl+Click
      if (newSelectedIds.has(assetId)) {
        newSelectedIds.delete(assetId);
      } else {
        newSelectedIds.add(assetId);
      }
      setLastSelectedIndex(index);
    } else if (event?.shiftKey && lastSelectedIndex !== null) {
      // Range selection for Shift+Click
      const start = Math.min(lastSelectedIndex, index);
      const end = Math.max(lastSelectedIndex, index);
      const visibleAssets = getVisibleAssets();
      for (let i = start; i <= end; i++) {
        if (visibleAssets[i]) {
          newSelectedIds.add(visibleAssets[i].id);
        }
      }
      setLastSelectedIndex(index);
    } else {
      // Single selection (replace)
      newSelectedIds.clear();
      newSelectedIds.add(assetId);
      setLastSelectedIndex(index);
    }

    setSelectedAssetIds(newSelectedIds);
  }, [selectedAssetIds, lastSelectedIndex]);

  // Handle asset double-click for preview
  const handleAssetDoubleClick = useCallback((asset: Asset) => {
    toast({
      title: 'Asset Preview',
      description: `Opening preview for: ${asset.name}`,
    });
    // In a full implementation, this would open a modal
  }, [toast]);

  // Clear selection
  const clearSelection = useCallback(() => {
    setSelectedAssetIds(new Set());
    setLastSelectedIndex(null);
  }, []);

  // Select all visible assets
  const selectAll = useCallback(() => {
    const visibleAssets = getVisibleAssets();
    const allIds = new Set(visibleAssets.map(a => a.id));
    setSelectedAssetIds(allIds);
  }, []);

  // Get visible assets based on filters
  const getVisibleAssets = useCallback(() => {
    return filteredAssets;
  }, [filteredAssets]);

  // Handle keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement) return;

      if ((e.ctrlKey || e.metaKey) && e.key === 'a') {
        e.preventDefault();
        selectAll();
      } else if (e.key === 'Escape') {
        e.preventDefault();
        clearSelection();
      } else if (e.key === 'Delete' && selectedAssetIds.size > 0) {
        e.preventDefault();
        handleDeleteSelected();
      }
    };

    globalThis.addEventListener('keydown', handleKeyDown);
    return () => globalThis.removeEventListener('keydown', handleKeyDown);
  }, [selectedAssetIds, selectAll, clearSelection]);

  // Handle delete selected assets
  const handleDeleteSelected = useCallback(() => {
    if (selectedAssetIds.size === 0) return;

    const confirmDelete = globalThis.confirm(
      `Delete ${selectedAssetIds.size} selected asset(s)?`
    );

    if (confirmDelete) {
      toast({
        title: 'Assets Deleted',
        description: `${selectedAssetIds.size} asset(s) have been removed from the library`,
      });
      clearSelection();
    }
  }, [selectedAssetIds, toast, clearSelection]);

  // Handle duplicate selected assets
  const handleDuplicateSelected = useCallback(() => {
    if (selectedAssetIds.size === 0) return;

    toast({
      title: 'Assets Duplicated',
      description: `${selectedAssetIds.size} asset(s) have been duplicated`,
    });
  }, [selectedAssetIds, toast]);

  // Handle asset search with debouncing
  const handleAssetSearch = useCallback(async (query: string) => {
    setAssetSearchQuery(query);

    try {
      const service = AssetLibraryService.getInstance();
      const results = await service.searchAssets(
        {
          query: query.trim() || undefined,
          category: selectedCategory,
        },
        assetSources
      );
      setFilteredAssets(results);
    } catch (error) {
      console.error('Asset search failed:', error);
    }
  }, [selectedCategory, assetSources]);

  // Handle category change
  const handleCategoryChange = useCallback(async (categoryId: string) => {
    setSelectedCategory(categoryId);

    try {
      const service = AssetLibraryService.getInstance();
      const results = await service.searchAssets(
        {
          query: assetSearchQuery.trim() || undefined,
          category: categoryId,
        },
        assetSources
      );
      setFilteredAssets(results);
    } catch (error) {
      console.error('Category filter failed:', error);
    }
  }, [assetSearchQuery, assetSources]);

  // Handle refresh assets
  const handleRefreshAssets = useCallback(async () => {
    setIsLoadingAssets(true);
    try {
      const service = AssetLibraryService.getInstance();
      const sources = await service.refresh(projectPath || undefined);
      setAssetSources(sources);

      // Re-apply current filters
      const results = await service.searchAssets(
        {
          query: assetSearchQuery.trim() || undefined,
          category: selectedCategory,
        },
        sources
      );
      setFilteredAssets(results);

      toast({
        title: 'Assets Refreshed',
        description: `Loaded ${results.length} assets`,
      });
    } catch (error) {
      console.error('Failed to refresh assets:', error);
      toast({
        title: 'Refresh Failed',
        description: 'Failed to refresh asset library',
        variant: 'destructive',
      });
    } finally {
      setIsLoadingAssets(false);
    }
  }, [projectPath, assetSearchQuery, selectedCategory, toast]);

  // Handle import assets
  const handleImportAssets = useCallback(() => {
    // Create file input element
    const input = document.createElement('input');
    input.type = 'file';
    input.multiple = true;
    input.accept = 'image/*,audio/*,video/*';

    input.onchange = async (e) => {
      const files = Array.from((e.target as HTMLInputElement).files || []);
      if (files.length === 0) return;

      // For now, just show success message
      toast({
        title: 'Assets Selected',
        description: `${files.length} files selected. Full import requires a project.`,
      });
    };

    input.click();
  }, [toast]);

  // Render asset in grid view
  const renderAssetGridItem = (asset: Asset, index: number) => {
    const isSelected = selectedAssetIds.has(asset.id);
    const isImage = asset.type === 'image';

    return (
      <button
        type="button"
        key={asset.id}
        onClick={(e) => handleAssetSelect(asset.id, index, e)}
        onDoubleClick={() => handleAssetDoubleClick(asset)}
        className={`
          relative w-full flex items-center gap-2 p-2 rounded-md cursor-pointer border transition-all
          ${isSelected
            ? 'bg-primary/10 border-primary ring-2 ring-primary/30'
            : 'hover:bg-muted border-border group'
          }
        `}
        title={asset.name}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            handleAssetSelect(asset.id, index);
          }
        }}
        aria-label={`Select asset ${asset.name}`}
        aria-pressed={isSelected ? 'true' : 'false'}
      >
        {/* Selection indicator */}
        {isSelected && (
          <div className="absolute top-1 left-1 z-10">
            <div className="w-5 h-5 bg-primary rounded-full flex items-center justify-center">
              <Check className="w-3 h-3 text-primary-foreground" />
            </div>
          </div>
        )}

        {/* Thumbnail */}
        <div className={`
          ${viewMode === 'grid' ? 'w-12 h-12' : 'w-10 h-10'}
          bg-muted rounded flex-shrink-0 flex items-center justify-center overflow-hidden
        `}>
          {renderThumbnail(asset, isImage)}
        </div>

        {/* Asset info */}
        <div className="flex-1 min-w-0 text-left">
          <p className="text-xs font-medium truncate">{asset.name}</p>
          <p className="text-xs text-muted-foreground capitalize">{asset.type}</p>
        </div>

        {/* Hover actions */}
        {!isSelected && (
          <div className="opacity-0 group-hover:opacity-100 transition-opacity absolute right-1 top-1/2 -translate-y-1/2">
            <div className="bg-background/90 rounded p-1 shadow-sm">
              <Copy className="w-3 h-3 text-muted-foreground" />
            </div>
          </div>
        )}
      </button>
    );
  };

  // Render asset in list view
  const renderAssetListItem = (asset: Asset, index: number): React.ReactElement => {
    const isSelected = selectedAssetIds.has(asset.id);
    
    return (
      <button
        type="button"
        key={asset.id}
        onClick={(e) => handleAssetSelect(asset.id, index, e)}
        onDoubleClick={() => handleAssetDoubleClick(asset)}
        className={`
          w-full text-left flex items-center gap-3 p-2 rounded-md cursor-pointer border transition-all
          ${isSelected
            ? 'bg-primary/10 border-primary'
            : 'hover:bg-muted border-border'
          }
        `}
        title={asset.name}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            handleAssetSelect(asset.id, index);
          }
        }}
        aria-label={`Select asset ${asset.name}`}
        aria-pressed={isSelected ? 'true' : 'false'}
      >
        {/* Selection checkbox */}
        <div className={`
          w-4 h-4 rounded border flex items-center justify-center flex-shrink-0
          ${isSelected
            ? 'bg-primary border-primary'
            : 'border-muted-foreground'
          }
        `}>
          {isSelected && <Check className="w-3 h-3 text-primary-foreground" />}
        </div>

        {/* Thumbnail */}
        <div className="w-10 h-10 bg-muted rounded flex-shrink-0 flex items-center justify-center overflow-hidden">
          {(() => {
            if (asset.thumbnail) {
              return (
                <img
                  src={asset.thumbnail}
                  alt={asset.name}
                  className="w-full h-full object-cover"
                />
              );
            }
            return renderAssetTypeIcon(asset.type) as React.ReactNode;
          })() as React.ReactNode}
        </div>

        {/* Asset info */}
        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium truncate">{asset.name}</p>
          <p className="text-xs text-muted-foreground capitalize">{asset.type}</p>
        </div>

        {/* Metadata preview */}
        {asset.metadata?.tags && Array.isArray(asset.metadata.tags) && asset.metadata.tags.length > 0 && (
          <div className="hidden md:flex items-center gap-1">
            {(asset.metadata.tags as string[]).slice(0, 2).map((tag: string, tagIndex: number) => (
              <span
                key={tag}
                className="text-xs px-1.5 py-0.5 bg-muted rounded"
              >
                {tag}
              </span>
            ))}
          </div>
        )}
      </button>
    );
  };

  return (
    <div className={`w-72 border-r border-border bg-card flex flex-col ${className || ''}`}>
      {/* Assets Header */}
      <div className="p-4 border-b border-border">
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-2">
            <h2 className="text-lg font-semibold">Assets</h2>
            {/* Demo Mode Indicator */}
            {!(globalThis as any).electronAPI && (
              <span className="flex items-center gap-1 px-2 py-0.5 text-xs bg-amber-100 text-amber-800 rounded-full">
                <WifiOff className="w-3 h-3" />
                Demo Mode
              </span>
            )}
          </div>
          <div className="flex items-center gap-1">
            <button
              onClick={handleRefreshAssets}
              className={`p-1 rounded-md ${isLoadingAssets ? 'animate-spin' : 'hover:bg-muted'}`}
              title="Refresh asset library"
              aria-label="Refresh asset library"
              disabled={isLoadingAssets}
            >
              <RefreshCw className="w-4 h-4" />
            </button>
            <div className="h-4 w-px bg-border mx-1" />
            <button
              onClick={() => setViewMode('grid')}
              className={`p-1 rounded-md ${viewMode === 'grid' ? 'bg-muted' : 'hover:bg-muted'}`}
              title="Grid view"
              aria-label="Switch to grid view"
            >
              <Grid className="w-4 h-4" />
            </button>
            <button
              onClick={() => setViewMode('list')}
              className={`p-1 rounded-md ${viewMode === 'list' ? 'bg-muted' : 'hover:bg-muted'}`}
              title="List view"
              aria-label="Switch to list view"
            >
              <List className="w-4 h-4" />
            </button>
          </div>
        </div>
        {/* Demo Mode Info */}
        {!(globalThis as any).electronAPI && (
          <div className="flex items-center gap-1 mb-3 text-xs text-muted-foreground">
            <Info className="w-3 h-3" />
            <span>Running in browser with demo assets</span>
          </div>
        )}
        <input
          type="text"
          placeholder="Search assets..."
          value={assetSearchQuery}
          onChange={(e) => handleAssetSearch(e.target.value)}
          className="w-full px-3 py-1.5 text-sm bg-background border border-border rounded-md focus:outline-none focus:ring-2 focus:ring-primary"
          aria-label="Search assets"
        />

        {/* Tab Toggle */}
        <div className="mt-4">
          <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as any)}>
            <TabsList className="grid w-full grid-cols-2 bg-muted/50 p-1 rounded-lg">
              <TabsTrigger value="library" className="flex items-center gap-1.5 text-xs py-1.5 rounded-md data-[state=active]:bg-background data-[state=active]:shadow-sm">
                <Cloud className="w-3.5 h-3.5" />
                Library
              </TabsTrigger>
              <TabsTrigger value="vault" className="flex items-center gap-1.5 text-xs py-1.5 rounded-md data-[state=active]:bg-background data-[state=active]:shadow-sm">
                <Database className="w-3.5 h-3.5" />
                Vault
              </TabsTrigger>
            </TabsList>
          </Tabs>
        </div>
      </div>

      {/* Selection Toolbar */}
      {selectedAssetIds.size > 0 && (
        <div className="px-4 py-2 bg-primary/10 border-b border-primary/20 flex items-center justify-between">
          <span className="text-sm font-medium text-primary">
            {selectedAssetIds.size} selected
          </span>
          <div className="flex items-center gap-1">
            <button
              onClick={selectAll}
              className="p-1 hover:bg-primary/20 rounded"
              title="Select all (Ctrl+A)"
              aria-label="Select all"
            >
              <Square className="w-4 h-4" />
            </button>
            <button
              onClick={clearSelection}
              className="p-1 hover:bg-primary/20 rounded"
              title="Clear selection (Escape)"
              aria-label="Clear selection"
            >
              <X className="w-4 h-4" />
            </button>
            <div className="h-4 w-px bg-border mx-1" />
            <button
              onClick={handleDuplicateSelected}
              className="p-1 hover:bg-primary/20 rounded"
              title="Duplicate"
              aria-label="Duplicate selected"
            >
              <Copy className="w-4 h-4" />
            </button>
            <button
              onClick={handleDeleteSelected}
              className="p-1 hover:bg-red-100 text-red-600 rounded"
              title="Delete (Del)"
              aria-label="Delete selected"
            >
              <Trash2 className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}

      <div className="flex-1 overflow-y-auto">
        {activeTab === 'vault' && projectPath ? (
          <VaultGallery projectId={projectPath.split(/[/\\]/).pop() || ''} className="border-none rounded-none h-full" />
        ) : (
          <>
            <div className="p-2">
              {/* Category Buttons */}
              <div className="flex gap-2 mb-4">
                <button
                  onClick={() => handleCategoryChange('all')}
                  className={`px-3 py-1 text-xs rounded-full transition-colors ${selectedCategory === 'all' ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-accent'
                    }`}
                >
                  All
                </button>
                {ASSET_CATEGORIES.map((category) => (
                  <button
                    key={category.id}
                    onClick={() => handleCategoryChange(category.id)}
                    className={`px-3 py-1 text-xs rounded-full transition-colors ${selectedCategory === category.id ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-accent'
                      }`}
                  >
                    {category.name}
                  </button>
                ))}
              </div>
            </div>

            {/* Asset Grid/List by Source */}
            {isLoadingAssets ? (
              <div className="flex items-center justify-center p-8">
                <Loader2 className="w-6 h-6 animate-spin text-primary" />
              </div>
            ) : (
              <div ref={assetListRef} className="p-4 space-y-4">
                {assetSources.map((source) => {
                  // Filter source assets based on current search/filter criteria
                  const sourceAssets = source.assets.filter(asset => {
                    // Apply search query filter
                    if (assetSearchQuery.trim()) {
                      const query = assetSearchQuery.toLowerCase();
                      const matchesName = asset.name.toLowerCase().includes(query);
                      const matchesTags = asset.metadata?.tags?.some((tag: string) =>
                        tag.toLowerCase().includes(query)
                      );
                      if (!matchesName && !matchesTags) return false;
                    }

                    // Apply category filter
                    if (selectedCategory !== 'all') {
                      const category = ASSET_CATEGORIES.find(c => c.id === selectedCategory);
                      if (category && !category.filter(asset)) return false;
                    }

                    return true;
                  });

                  if (sourceAssets.length === 0) return null;

                  return (
                    <div key={source.id}>
                      <div className="flex items-center justify-between mb-2">
                        <h3 className="text-xs font-semibold text-muted-foreground">
                          {source.name}
                        </h3>
                        <span className="text-xs text-muted-foreground">
                          {sourceAssets.length}
                        </span>
                      </div>

                      {/* Grid View */}
                      {viewMode === 'grid' ? (
                        <div className="space-y-2">
                          {sourceAssets.map((asset, index) => renderAssetGridItem(asset, index))}
                        </div>
                      ) : (
                        /* List View */
                        <div className="space-y-1">
                          {sourceAssets.map((asset, index) => renderAssetListItem(asset, index))}
                        </div>
                      )}
                    </div>
                  );
                })}

                {filteredAssets.length === 0 && !isLoadingAssets && (
                  <div className="text-center py-8 text-muted-foreground">
                    <div className="flex justify-center mb-4">
                      <div className="w-16 h-16 bg-muted rounded-full flex items-center justify-center">
                        <FileText className="w-8 h-8 opacity-50" />
                      </div>
                    </div>
                    <p className="text-sm font-medium mb-2">No assets found</p>
                    {assetSearchQuery ? (
                      <div className="space-y-2">
                        <p className="text-xs">No assets match your search criteria</p>
                        <button
                          onClick={() => {
                            setAssetSearchQuery('');
                            handleAssetSearch('');
                          }}
                          className="text-xs text-primary hover:text-primary/80 underline"
                        >
                          Clear search
                        </button>
                      </div>
                    ) : (
                      <div className="space-y-2">
                        <p className="text-xs">No assets are currently available</p>
                        <div className="text-xs space-y-1">
                          <p>In demo mode, you have access to:</p>
                          <ul className="list-disc list-inside text-xs text-muted-foreground">
                            <li>Sample images from the library</li>
                            <li>UI assets and placeholders</li>
                            <li>StoryCore branding assets</li>
                          </ul>
                        </div>
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}
          </>
        )}
      </div>

      {/* Import Button */}
      <div className="p-4 border-t border-border">
        <button
          onClick={handleImportAssets}
          className="w-full px-4 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90 flex items-center justify-center gap-2 transition-colors"
          aria-label="Import new assets"
        >
          <Plus className="w-4 h-4" />
          Import Assets
        </button>
      </div>

      {/* Camera Angle Editor Modal */}
      <CameraAngleEditorModal
        isOpen={isCameraAngleModalOpen}
        onClose={closeCameraAngleModal}
        initialImageId={cameraAngleImageId || undefined}
        initialImagePath={cameraAngleImagePath || undefined}
      />
    </div>
  );
}

import React, { useState } from 'react';
import { useStore } from '../store';
import type { AudioEffect, AutomationCurve, AudioKeyframe } from '../types';
import { AudioCurveEditor } from './AudioCurveEditor';
import { TrendingUp, Plus, Trash2 } from 'lucide-react';

interface AudioAutomationPanelProps {
  shotId: string;
  trackId: string;
  effectId: string;
}

export const AudioAutomationPanel: React.FC<AudioAutomationPanelProps> = ({
  shotId,
  trackId,
  effectId,
}) => {
  const shot = useStore((state) => state.shots.find((s) => s.id === shotId));
  const updateAudioTrack = useStore((state) => state.updateAudioTrack);
  const [selectedParameter, setSelectedParameter] = useState<string | null>(null);

  const track = shot?.audioTracks.find((t) => t.id === trackId);
  const effect = track?.effects.find((e) => e.id === effectId);

  if (!effect || !track) {
    return null;
  }

  // Get automatable parameters for this effect
  const automatableParams = getAutomatableParameters(effect);

  // Get or create automation curve for parameter
  const getAutomationCurve = (parameter: string): AutomationCurve | null => {
    return effect.automationCurve?.parameter === parameter ? effect.automationCurve : null;
  };

  // Create new automation curve
  const createAutomationCurve = (parameter: string) => {
    const paramInfo = automatableParams.find((p) => p.name === parameter);
    if (!paramInfo) return;

    const newCurve: AutomationCurve = {
      id: `curve-${Date.now()}`,
      parameter,
      keyframes: [
        {
          id: `kf-${Date.now()}-1`,
          time: 0,
          value: paramInfo.default,
          easing: 'linear',
        },
        {
          id: `kf-${Date.now()}-2`,
          time: track.duration,
          value: paramInfo.default,
          easing: 'linear',
        },
      ],
      interpolation: 'smooth',
    };

    updateEffect({ automationCurve: newCurve });
    setSelectedParameter(parameter);
  };

  // Update automation curve
  const updateAutomationCurve = (curve: AutomationCurve) => {
    updateEffect({ automationCurve: curve });
  };

  // Delete automation curve
  const deleteAutomationCurve = () => {
    updateEffect({ automationCurve: undefined });
    setSelectedParameter(null);
  };

  // Update effect
  const updateEffect = (updates: Partial<AudioEffect>) => {
    const updatedEffects = track.effects.map((e) =>
      e.id === effectId ? { ...e, ...updates } : e
    );
    updateAudioTrack(shotId, trackId, { effects: updatedEffects });
  };

  // Change interpolation mode
  const setInterpolation = (interpolation: AutomationCurve['interpolation']) => {
    if (effect.automationCurve) {
      updateAutomationCurve({ ...effect.automationCurve, interpolation });
    }
  };

  const currentCurve = selectedParameter ? getAutomationCurve(selectedParameter) : null;
  const currentParamInfo = automatableParams.find((p) => p.name === selectedParameter);

  return (
    <div className="p-4 space-y-4 border-t">
      <div className="flex items-center justify-between">
        <div>
          <h4 className="font-medium flex items-center gap-2">
            <TrendingUp className="w-4 h-4" />
            Automation
          </h4>
          <p className="text-xs text-gray-600">Automate effect parameters over time</p>
        </div>
      </div>

      {/* Parameter Selector */}
      <div>
        <label htmlFor="parameter-select" className="text-xs text-gray-600 block mb-1">Parameter</label>
        <select
          id="parameter-select"
          value={selectedParameter || ''}
          onChange={(e) => {
            setSelectedParameter(e.target.value || null);
          }}
          className="w-full px-2 py-1 text-sm border rounded"
          aria-label="Select parameter for automation"
          title="Select parameter for automation"
        >
          <option value="">Select parameter...</option>
          {automatableParams.map((param) => (
            <option key={param.name} value={param.name}>
              {param.label}
            </option>
          ))}
        </select>
      </div>

      {/* Automation Controls */}
      {selectedParameter && (
        <div className="space-y-3">
          {currentCurve ? (
            <>
              {/* Interpolation Mode */}
              <div>
                <label className="text-xs text-gray-600 block mb-1">Interpolation</label>
                <div className="flex gap-2">
                  {(['linear', 'smooth', 'step', 'bezier'] as const).map((mode) => (
                    <button
                      key={mode}
                      onClick={() => setInterpolation(mode)}
                      className={`px-3 py-1 text-xs rounded border ${
                        currentCurve.interpolation === mode
                          ? 'bg-blue-500 text-white border-blue-600'
                          : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'
                      }`}
                    >
                      {mode.charAt(0).toUpperCase() + mode.slice(1)}
                    </button>
                  ))}
                </div>
              </div>

              {/* Curve Editor */}
              {currentParamInfo && (
                <AudioCurveEditor
                  curve={currentCurve}
                  duration={track.duration}
                  parameterRange={currentParamInfo.range}
                  parameterLabel={currentParamInfo.label}
                  onUpdate={updateAutomationCurve}
                />
              )}

              {/* Delete Button */}
              <button
                onClick={deleteAutomationCurve}
                className="w-full px-3 py-2 text-sm border rounded text-red-600 border-red-300 hover:bg-red-50 flex items-center justify-center gap-2"
              >
                <Trash2 className="w-4 h-4" />
                Remove Automation
              </button>
            </>
          ) : (
            <button
              onClick={() => createAutomationCurve(selectedParameter)}
              className="w-full px-3 py-2 text-sm border-2 border-dashed rounded text-blue-600 border-blue-300 hover:bg-blue-50 flex items-center justify-center gap-2"
            >
              <Plus className="w-4 h-4" />
              Create Automation Curve
            </button>
          )}
        </div>
      )}

      {/* Curve Presets */}
      {selectedParameter && currentCurve && currentParamInfo && (
        <div className="border-t pt-3">
          <label className="text-xs text-gray-600 block mb-2">Quick Presets</label>
          <div className="grid grid-cols-2 gap-2">
            {CURVE_PRESETS.map((preset) => (
              <button
                key={preset.name}
                onClick={() => applyCurvePreset(preset, currentCurve, currentParamInfo, track.duration, updateAutomationCurve)}
                className="px-3 py-2 text-xs border rounded hover:bg-gray-50"
              >
                {preset.name}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

// Get automatable parameters for an effect
function getAutomatableParameters(effect: AudioEffect): Array<{
  name: string;
  label: string;
  range: { min: number; max: number };
  default: number;
}> {
  switch (effect.type) {
    case 'gain':
      return [
        { name: 'gain', label: 'Gain (dB)', range: { min: -60, max: 60 }, default: 0 },
      ];
    case 'distortion':
      return [
        { name: 'distortion', label: 'Amount', range: { min: 0, max: 100 }, default: 50 },
      ];
    case 'bass-boost':
      return [
        { name: 'bassGain', label: 'Bass Gain (dB)', range: { min: -12, max: 12 }, default: 6 },
      ];
    case 'treble-boost':
      return [
        { name: 'trebleGain', label: 'Treble Gain (dB)', range: { min: -12, max: 12 }, default: 6 },
      ];
    case 'voice-clarity':
      return [
        { name: 'intensity', label: 'Intensity', range: { min: 0, max: 100 }, default: 70 },
      ];
    case 'eq':
      return [
        { name: 'lowGain', label: 'Low Gain (dB)', range: { min: -12, max: 12 }, default: 0 },
        { name: 'midGain', label: 'Mid Gain (dB)', range: { min: -12, max: 12 }, default: 0 },
        { name: 'highGain', label: 'High Gain (dB)', range: { min: -12, max: 12 }, default: 0 },
      ];
    default:
      return [];
  }
}

// Curve presets
const CURVE_PRESETS = [
  { name: 'Fade In', type: 'fade-in' },
  { name: 'Fade Out', type: 'fade-out' },
  { name: 'Pulse', type: 'pulse' },
  { name: 'Wave', type: 'wave' },
];

// Apply curve preset
function applyCurvePreset(
  preset: { name: string; type: string },
  currentCurve: AutomationCurve,
  paramInfo: { range: { min: number; max: number }; default: number },
  duration: number,
  onUpdate: (curve: AutomationCurve) => void
) {
  const { min, max } = paramInfo.range;
  const mid = (min + max) / 2;

  let keyframes: AudioKeyframe[] = [];

  switch (preset.type) {
    case 'fade-in':
      keyframes = [
        { id: `kf-${Date.now()}-1`, time: 0, value: min, easing: 'ease-out' },
        { id: `kf-${Date.now()}-2`, time: duration, value: max, easing: 'linear' },
      ];
      break;
    case 'fade-out':
      keyframes = [
        { id: `kf-${Date.now()}-1`, time: 0, value: max, easing: 'ease-in' },
        { id: `kf-${Date.now()}-2`, time: duration, value: min, easing: 'linear' },
      ];
      break;
    case 'pulse':
      keyframes = [
        { id: `kf-${Date.now()}-1`, time: 0, value: mid, easing: 'ease-in-out' },
        { id: `kf-${Date.now()}-2`, time: duration * 0.25, value: max, easing: 'ease-in-out' },
        { id: `kf-${Date.now()}-3`, time: duration * 0.5, value: mid, easing: 'ease-in-out' },
        { id: `kf-${Date.now()}-4`, time: duration * 0.75, value: max, easing: 'ease-in-out' },
        { id: `kf-${Date.now()}-5`, time: duration, value: mid, easing: 'linear' },
      ];
      break;
    case 'wave':
      keyframes = [
        { id: `kf-${Date.now()}-1`, time: 0, value: mid, easing: 'ease-in-out' },
        { id: `kf-${Date.now()}-2`, time: duration * 0.25, value: max, easing: 'ease-in-out' },
        { id: `kf-${Date.now()}-3`, time: duration * 0.5, value: mid, easing: 'ease-in-out' },
        { id: `kf-${Date.now()}-4`, time: duration * 0.75, value: min, easing: 'ease-in-out' },
        { id: `kf-${Date.now()}-5`, time: duration, value: mid, easing: 'linear' },
      ];
      break;
  }

  onUpdate({ ...currentCurve, keyframes });
}

import React, { useRef, useEffect, useState, useCallback } from 'react';
import type { AutomationCurve, AudioKeyframe } from '../types';

interface AudioCurveEditorProps {
  curve: AutomationCurve;
  duration: number; // Track duration in seconds
  parameterRange: { min: number; max: number };
  parameterLabel: string;
  onUpdate: (curve: AutomationCurve) => void;
  width?: number;
  height?: number;
}

export const AudioCurveEditor: React.FC<AudioCurveEditorProps> = ({
  curve,
  duration,
  parameterRange,
  parameterLabel,
  onUpdate,
  width = 600,
  height = 200,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [selectedKeyframe, setSelectedKeyframe] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [hoveredKeyframe, setHoveredKeyframe] = useState<string | null>(null);

  // Grid configuration
  const GRID_COLOR = '#e5e7eb';
  const CURVE_COLOR = '#3b82f6';
  const KEYFRAME_COLOR = '#3b82f6';
  const KEYFRAME_SELECTED_COLOR = '#1d4ed8';
  const KEYFRAME_HOVER_COLOR = '#60a5fa';
  const KEYFRAME_RADIUS = 6;
  const PADDING = 40;

  // Convert time to canvas X coordinate
  const timeToX = useCallback(
    (time: number): number => {
      return PADDING + ((time / duration) * (width - 2 * PADDING));
    },
    [duration, width]
  );

  // Convert value to canvas Y coordinate (inverted)
  const valueToY = useCallback(
    (value: number): number => {
      const normalized = (value - parameterRange.min) / (parameterRange.max - parameterRange.min);
      return height - PADDING - (normalized * (height - 2 * PADDING));
    },
    [parameterRange, height]
  );

  // Convert canvas X to time
  const xToTime = useCallback(
    (x: number): number => {
      return Math.max(0, Math.min(duration, ((x - PADDING) / (width - 2 * PADDING)) * duration));
    },
    [duration, width]
  );

  // Convert canvas Y to value
  const yToValue = useCallback(
    (y: number): number => {
      const normalized = 1 - ((y - PADDING) / (height - 2 * PADDING));
      return Math.max(
        parameterRange.min,
        Math.min(parameterRange.max, parameterRange.min + normalized * (parameterRange.max - parameterRange.min))
      );
    },
    [parameterRange, height]
  );

  // Draw the curve editor
  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear canvas
    ctx.clearRect(0, 0, width, height);

    // Draw grid
    drawGrid(ctx);

    // Draw curve
    drawCurve(ctx);

    // Draw keyframes
    drawKeyframes(ctx);
  }, [curve, selectedKeyframe, hoveredKeyframe, width, height]);

  // Draw grid with time markers
  const drawGrid = (ctx: CanvasRenderingContext2D) => {
    ctx.strokeStyle = GRID_COLOR;
    ctx.lineWidth = 1;

    // Vertical grid lines (time)
    const timeSteps = Math.ceil(duration);
    for (let i = 0; i <= timeSteps; i++) {
      const x = timeToX(i);
      ctx.beginPath();
      ctx.moveTo(x, PADDING);
      ctx.lineTo(x, height - PADDING);
      ctx.stroke();

      // Time labels
      ctx.fillStyle = '#6b7280';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(`${i}s`, x, height - PADDING + 15);
    }

    // Horizontal grid lines (value)
    const valueSteps = 5;
    for (let i = 0; i <= valueSteps; i++) {
      const value = parameterRange.min + (i / valueSteps) * (parameterRange.max - parameterRange.min);
      const y = valueToY(value);
      ctx.beginPath();
      ctx.moveTo(PADDING, y);
      ctx.lineTo(width - PADDING, y);
      ctx.stroke();

      // Value labels
      ctx.fillStyle = '#6b7280';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'right';
      ctx.fillText(value.toFixed(1), PADDING - 5, y + 3);
    }

    // Border
    ctx.strokeStyle = '#d1d5db';
    ctx.lineWidth = 2;
    ctx.strokeRect(PADDING, PADDING, width - 2 * PADDING, height - 2 * PADDING);

    // Parameter label
    ctx.fillStyle = '#374151';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(parameterLabel, width / 2, 20);
  };

  // Draw the automation curve
  const drawCurve = (ctx: CanvasRenderingContext2D) => {
    if (curve.keyframes.length < 2) return;

    const sortedKeyframes = [...curve.keyframes].sort((a, b) => a.time - b.time);

    ctx.strokeStyle = CURVE_COLOR;
    ctx.lineWidth = 2;
    ctx.beginPath();

    // Draw curve segments between keyframes
    for (let i = 0; i < sortedKeyframes.length - 1; i++) {
      const kf1 = sortedKeyframes[i];
      const kf2 = sortedKeyframes[i + 1];

      const x1 = timeToX(kf1.time);
      const y1 = valueToY(kf1.value);
      const x2 = timeToX(kf2.time);
      const y2 = valueToY(kf2.value);

      if (i === 0) {
        ctx.moveTo(x1, y1);
      }

      // Draw based on interpolation type
      if (curve.interpolation === 'linear' || !kf1.easing) {
        ctx.lineTo(x2, y2);
      } else if (curve.interpolation === 'step') {
        ctx.lineTo(x2, y1);
        ctx.lineTo(x2, y2);
      } else if (curve.interpolation === 'bezier' && kf1.bezierControlPoints) {
        // Bezier curve
        const cp1x = x1 + (x2 - x1) * kf1.bezierControlPoints.cp1.x;
        const cp1y = y1 + (y2 - y1) * kf1.bezierControlPoints.cp1.y;
        const cp2x = x1 + (x2 - x1) * kf1.bezierControlPoints.cp2.x;
        const cp2y = y1 + (y2 - y1) * kf1.bezierControlPoints.cp2.y;
        ctx.bezierCurveTo(cp1x, cp1y, cp2x, cp2y, x2, y2);
      } else {
        // Smooth (ease-in-out)
        const cpx1 = x1 + (x2 - x1) * 0.33;
        const cpy1 = y1;
        const cpx2 = x1 + (x2 - x1) * 0.67;
        const cpy2 = y2;
        ctx.bezierCurveTo(cpx1, cpy1, cpx2, cpy2, x2, y2);
      }
    }

    ctx.stroke();
  };

  // Draw keyframes
  const drawKeyframes = (ctx: CanvasRenderingContext2D) => {
    curve.keyframes.forEach((kf) => {
      const x = timeToX(kf.time);
      const y = valueToY(kf.value);

      // Determine color
      let color = KEYFRAME_COLOR;
      if (selectedKeyframe === kf.id) {
        color = KEYFRAME_SELECTED_COLOR;
      } else if (hoveredKeyframe === kf.id) {
        color = KEYFRAME_HOVER_COLOR;
      }

      // Draw keyframe circle
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.arc(x, y, KEYFRAME_RADIUS, 0, Math.PI * 2);
      ctx.fill();

      // Draw border
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 2;
      ctx.stroke();

      // Draw bezier handles if selected and bezier mode
      if (selectedKeyframe === kf.id && curve.interpolation === 'bezier' && kf.bezierControlPoints) {
        const nextKf = curve.keyframes.find((k) => k.time > kf.time);
        if (nextKf) {
          const x2 = timeToX(nextKf.time);
          const y2 = valueToY(nextKf.value);

          const cp1x = x + (x2 - x) * kf.bezierControlPoints.cp1.x;
          const cp1y = y + (y2 - y) * kf.bezierControlPoints.cp1.y;
          const cp2x = x + (x2 - x) * kf.bezierControlPoints.cp2.x;
          const cp2y = y + (y2 - y) * kf.bezierControlPoints.cp2.y;

          // Draw control point lines
          ctx.strokeStyle = '#9ca3af';
          ctx.lineWidth = 1;
          ctx.setLineDash([5, 5]);
          ctx.beginPath();
          ctx.moveTo(x, y);
          ctx.lineTo(cp1x, cp1y);
          ctx.stroke();
          ctx.beginPath();
          ctx.moveTo(x2, y2);
          ctx.lineTo(cp2x, cp2y);
          ctx.stroke();
          ctx.setLineDash([]);

          // Draw control points
          ctx.fillStyle = '#9ca3af';
          ctx.beginPath();
          ctx.arc(cp1x, cp1y, 4, 0, Math.PI * 2);
          ctx.fill();
          ctx.beginPath();
          ctx.arc(cp2x, cp2y, 4, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    });
  };

  // Find keyframe at position
  const findKeyframeAt = (x: number, y: number): string | null => {
    for (const kf of curve.keyframes) {
      const kfX = timeToX(kf.time);
      const kfY = valueToY(kf.value);
      const distance = Math.sqrt((x - kfX) ** 2 + (y - kfY) ** 2);
      if (distance <= KEYFRAME_RADIUS + 2) {
        return kf.id;
      }
    }
    return null;
  };

  // Handle mouse down
  const handleMouseDown = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    const keyframeId = findKeyframeAt(x, y);

    if (keyframeId) {
      setSelectedKeyframe(keyframeId);
      setIsDragging(true);
    } else {
      // Add new keyframe
      const time = xToTime(x);
      const value = yToValue(y);

      const newKeyframe: AudioKeyframe = {
        id: `kf-${Date.now()}`,
        time,
        value,
        easing: 'linear',
      };

      const updatedCurve: AutomationCurve = {
        ...curve,
        keyframes: [...curve.keyframes, newKeyframe],
      };

      onUpdate(updatedCurve);
      setSelectedKeyframe(newKeyframe.id);
    }
  };

  // Handle mouse move
  const handleMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    if (isDragging && selectedKeyframe) {
      // Update keyframe position
      const time = xToTime(x);
      const value = yToValue(y);

      const updatedKeyframes = curve.keyframes.map((kf) =>
        kf.id === selectedKeyframe ? { ...kf, time, value } : kf
      );

      onUpdate({ ...curve, keyframes: updatedKeyframes });
    } else {
      // Update hover state
      const keyframeId = findKeyframeAt(x, y);
      setHoveredKeyframe(keyframeId);
    }
  };

  // Handle mouse up
  const handleMouseUp = () => {
    setIsDragging(false);
  };

  // Handle double click to delete keyframe
  const handleDoubleClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    const keyframeId = findKeyframeAt(x, y);

    if (keyframeId && curve.keyframes.length > 2) {
      const updatedKeyframes = curve.keyframes.filter((kf) => kf.id !== keyframeId);
      onUpdate({ ...curve, keyframes: updatedKeyframes });
      setSelectedKeyframe(null);
    }
  };

  // Redraw on changes
  useEffect(() => {
    draw();
  }, [draw]);

  return (
    <div className="space-y-2">
      <canvas
        ref={canvasRef}
        width={width}
        height={height}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onDoubleClick={handleDoubleClick}
        className="border rounded cursor-crosshair bg-white"
        style={{ touchAction: 'none' }}
      />

      <div className="text-xs text-gray-600 space-y-1">
        <div>ÔÇó Click to add keyframe</div>
        <div>ÔÇó Drag keyframe to move</div>
        <div>ÔÇó Double-click keyframe to delete</div>
        <div>ÔÇó {curve.keyframes.length} keyframe{curve.keyframes.length !== 1 ? 's' : ''}</div>
      </div>
    </div>
  );
};

