    cursor: 'pointer',
    fontSize: '12px',
  },
  zoomLabel: {
    color: '#fff',
    fontSize: '12px',
    fontWeight: 'bold',
  },
  container: {
    width: '100%',
    height: `${TIMELINE_HEIGHT}px`,
    backgroundColor: '#1a1a1a',
    borderRadius: '4px',
    overflow: 'hidden',
  },
  canvas: {
    display: 'block',
    cursor: 'crosshair',
  },
  legend: {
    display: 'flex',
    gap: '20px',
    padding: '10px',
    marginTop: '10px',
  },
  legendItem: {
    display: 'flex',
