import { useState, useEffect, useRef } from 'react';
import { X } from 'lucide-react';

interface NewProjectDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onCreateProject: (projectName: string) => void;
}

export function NewProjectDialog({ isOpen, onClose, onCreateProject }: NewProjectDialogProps) {
  const [projectName, setProjectName] = useState('');
  const [error, setError] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  // Focus input when dialog opens
  useEffect(() => {
    if (isOpen && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isOpen]);

  // Reset state when dialog closes
  useEffect(() => {
    if (!isOpen) {
      setProjectName('');
      setError('');
    }
  }, [isOpen]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Validate project name
    const trimmedName = projectName.trim();
    if (!trimmedName) {
      setError('Project name is required');
      return;
    }

    if (trimmedName.length < 3) {
      setError('Project name must be at least 3 characters');
      return;
    }

    if (trimmedName.length > 50) {
      setError('Project name must be less than 50 characters');
      return;
    }

    // Check for invalid characters
    const invalidChars = /[<>:"/\\|?*]/;
    if (invalidChars.test(trimmedName)) {
      setError('Project name contains invalid characters');
      return;
    }

    // Create project
    onCreateProject(trimmedName);
    onClose();
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape') {
      onClose();
    }
  };

  if (!isOpen) return null;

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/50"
      onClick={onClose}
      onKeyDown={handleKeyDown}
    >
      <div
        className="relative w-full max-w-md rounded-lg bg-card p-6 shadow-lg"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="mb-4 flex items-center justify-between">
          <h2 className="text-xl font-semibold">Create New Project</h2>
          <button
            onClick={onClose}
            className="rounded-md p-1 hover:bg-accent"
            aria-label="Close dialog"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit}>
          <div className="mb-4">
            <label htmlFor="project-name" className="mb-2 block text-sm font-medium">
              Project Name
            </label>
            <input
              ref={inputRef}
              id="project-name"
              type="text"
              value={projectName}
              onChange={(e) => {
                setProjectName(e.target.value);
                setError('');
              }}
              placeholder="Enter project name"
              className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-ring"
              aria-invalid={error ? "true" : "false"}
              aria-describedby={error ? 'project-name-error' : undefined}
            />
            {error && (
              <p id="project-name-error" className="mt-1 text-sm text-destructive">
                {error}
              </p>
            )}
          </div>

          {/* Project Settings Info */}
          <div className="mb-6 rounded-md bg-muted p-3 text-sm text-muted-foreground">
            <p className="mb-1 font-medium">Default Settings:</p>
            <ul className="ml-4 list-disc space-y-1">
              <li>Empty storyboard</li>
              <li>All capabilities enabled</li>
              <li>Data Contract v1.0 format</li>
            </ul>
          </div>

          {/* Actions */}
          <div className="flex justify-end gap-2">
            <button
              type="button"
              onClick={onClose}
              className="rounded-md border border-input bg-background px-4 py-2 text-sm font-medium hover:bg-accent"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground hover:bg-primary/90"
            >
              Create Project
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

/**
 * Notification System
 * 
 * Provides user feedback for operations throughout the application
 * Requirements: 2.9, 2.10, 12.5
 */

import { useToast } from '@/hooks/use-toast';
import { CheckCircle2, XCircle, AlertCircle, Info, Loader2 } from 'lucide-react';

export type NotificationType = 'success' | 'error' | 'warning' | 'info' | 'loading';

export interface NotificationOptions {
  title: string;
  description?: string;
  type?: NotificationType;
  duration?: number;
}

/**
 * Hook for showing notifications
 */
export function useNotifications() {
  const { toast } = useToast();

  const showNotification = ({
    title,
    description,
    type = 'info',
    duration,
  }: NotificationOptions) => {
    const variant = type === 'error' ? 'destructive' : 'default';

    toast({
      title,
      description,
      variant,
      duration,
    });
  };

  const showSuccess = (title: string, description?: string) => {
    showNotification({ title, description, type: 'success' });
  };

  const showError = (title: string, description?: string) => {
    showNotification({ title, description, type: 'error' });
  };

  const showWarning = (title: string, description?: string) => {
    showNotification({ title, description, type: 'warning' });
  };

  const showInfo = (title: string, description?: string) => {
    showNotification({ title, description, type: 'info' });
  };

  const showLoading = (title: string, description?: string) => {
    showNotification({ title, description, type: 'loading', duration: Infinity });
  };

  return {
    showNotification,
    showSuccess,
    showError,
    showWarning,
    showInfo,
    showLoading,
  };
}

/**
 * Notification icon component
 */
export function NotificationIcon({ type }: { type: NotificationType }) {
  const iconClasses = 'w-5 h-5';

  switch (type) {
    case 'success':
      return <CheckCircle2 className={`${iconClasses} text-green-500`} />;
    case 'error':
      return <XCircle className={`${iconClasses} text-red-500`} />;
    case 'warning':
      return <AlertCircle className={`${iconClasses} text-yellow-500`} />;
    case 'loading':
      return <Loader2 className={`${iconClasses} text-primary animate-spin`} />;
    case 'info':
    default:
      return <Info className={`${iconClasses} text-blue-500`} />;
  }
}

/**
 * Inline notification banner
 */
export function NotificationBanner({
  type,
  title,
  description,
  action,
  onDismiss,
}: {
  type: NotificationType;
  title: string;
  description?: string;
  action?: {
    label: string;
    onClick: () => void;
  };
  onDismiss?: () => void;
}) {
  const bgColors = {
    success: 'bg-green-500/10 border-green-500/20',
    error: 'bg-red-500/10 border-red-500/20',
    warning: 'bg-yellow-500/10 border-yellow-500/20',
    info: 'bg-blue-500/10 border-blue-500/20',
    loading: 'bg-primary/10 border-primary/20',
  };

  const textColors = {
    success: 'text-green-600 dark:text-green-400',
    error: 'text-red-600 dark:text-red-400',
    warning: 'text-yellow-600 dark:text-yellow-400',
    info: 'text-blue-600 dark:text-blue-400',
    loading: 'text-primary',
  };

  return (
    <div className={`p-4 rounded-lg border ${bgColors[type]} flex items-start gap-3`}>
      <NotificationIcon type={type} />
      <div className="flex-1 min-w-0">
        <h4 className={`text-sm font-semibold ${textColors[type]}`}>{title}</h4>
        {description && (
          <p className="text-sm text-muted-foreground mt-1">{description}</p>
        )}
        {action && (
          <button
            onClick={action.onClick}
            className={`text-sm font-medium mt-2 hover:underline ${textColors[type]}`}
          >
            {action.label}
          </button>
        )}
      </div>
      {onDismiss && (
        <button
          onClick={onDismiss}
          className="text-muted-foreground hover:text-foreground"
          aria-label="Dismiss notification"
        >
          <XCircle className="w-4 h-4" />
        </button>
      )}
    </div>
  );
}

/**
 * Pre-configured notification messages for common operations
 */
export const NotificationMessages = {
  // Wizard operations
  wizardLaunched: (wizardName: string) => ({
    title: 'Wizard Launched',
    description: `Starting ${wizardName}`,
    type: 'info' as NotificationType,
  }),

  wizardCompleted: (wizardName: string) => ({
    title: 'Wizard Completed',
    description: `${wizardName} finished successfully`,
    type: 'success' as NotificationType,
  }),

  wizardFailed: (wizardName: string, error: string) => ({
    title: 'Wizard Failed',
    description: `${wizardName} failed: ${error}`,
    type: 'error' as NotificationType,
  }),

  // Asset operations
  assetsImporting: (count: number) => ({
    title: 'Importing Assets',
    description: `Importing ${count} asset${count !== 1 ? 's' : ''}...`,
    type: 'loading' as NotificationType,
  }),

  assetsImported: (successCount: number, failCount: number) => ({
    title: 'Import Complete',
    description: `${successCount} asset${successCount !== 1 ? 's' : ''} imported successfully${failCount > 0 ? `, ${failCount} failed` : ''}`,
    type: failCount > 0 ? ('warning' as NotificationType) : ('success' as NotificationType),
  }),

  assetImportFailed: (error: string) => ({
    title: 'Import Failed',
    description: error,
    type: 'error' as NotificationType,
  }),

  // Shot operations
  shotCreated: (shotTitle: string) => ({
    title: 'Shot Created',
    description: `Created shot: ${shotTitle}`,
    type: 'success' as NotificationType,
  }),

  shotUpdated: (shotTitle: string) => ({
    title: 'Shot Updated',
    description: `Updated shot: ${shotTitle}`,
    type: 'success' as NotificationType,
  }),

  shotDeleted: (shotTitle: string) => ({
    title: 'Shot Deleted',
    description: `Deleted shot: ${shotTitle}`,
    type: 'success' as NotificationType,
  }),

  shotOperationFailed: (operation: string, error: string) => ({
    title: `Failed to ${operation} Shot`,
    description: error,
    type: 'error' as NotificationType,
  }),

  // Project operations
  projectLoaded: (projectName: string) => ({
    title: 'Project Loaded',
    description: `Loaded project: ${projectName}`,
    type: 'success' as NotificationType,
  }),

  projectSaved: () => ({
    title: 'Project Saved',
    description: 'All changes have been saved',
    type: 'success' as NotificationType,
  }),

  projectOperationFailed: (operation: string, error: string) => ({
    title: `Failed to ${operation} Project`,
    description: error,
    type: 'error' as NotificationType,
  }),

  // Connection operations
  serviceConnected: (serviceName: string) => ({
    title: 'Service Connected',
    description: `${serviceName} is now available`,
    type: 'success' as NotificationType,
  }),

  serviceDisconnected: (serviceName: string) => ({
    title: 'Service Unavailable',
    description: `Cannot connect to ${serviceName}. Some features may be disabled.`,
    type: 'warning' as NotificationType,
  }),

  // Generic operations
  operationInProgress: (operation: string) => ({
    title: operation,
    description: 'Please wait...',
    type: 'loading' as NotificationType,
  }),

  operationCompleted: (operation: string) => ({
    title: 'Completed',
    description: `${operation} completed successfully`,
    type: 'success' as NotificationType,
  }),

  operationFailed: (operation: string, error: string) => ({
    title: 'Operation Failed',
    description: `${operation} failed: ${error}`,
    type: 'error' as NotificationType,
  }),
};

import React, { useRef, useEffect, useState } from 'react';
import { useStore } from '../store';
import { usePlaybackEngine } from '../hooks/usePlaybackEngine';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Button } from './ui/button';
import { Slider } from './ui/slider';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from './ui/select';
import { Label } from './ui/label';
import { Switch } from './ui/switch';
import {
  Play,
  Pause,
  Square,
  SkipBack,
  SkipForward,
  Maximize2,
  Volume2,
  VolumeX,
  Repeat,
} from 'lucide-react';

interface PreviewPanelProps {
  className?: string;
}

export const PreviewPanel: React.FC<PreviewPanelProps> = ({ className }) => {
  const { canvasRef } = usePlaybackEngine();
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [volume, setVolume] = useState(100);
  const [isMuted, setIsMuted] = useState(false);
  const [loopMode, setLoopMode] = useState(false);

  const shots = useStore((state) => state.shots);
  const isPlaying = useStore((state) => state.isPlaying);
  const currentTime = useStore((state) => state.currentTime);
  const playbackSpeed = useStore((state) => state.playbackSpeed);
  const play = useStore((state) => state.play);
  const pause = useStore((state) => state.pause);
  const stop = useStore((state) => state.stop);
  const setCurrentTime = useStore((state) => state.setCurrentTime);
  const setPlaybackSpeed = useStore((state) => state.setPlaybackSpeed);

  // Calculate total duration
  const totalDuration = shots.reduce((acc, shot) => {
    let duration = acc + shot.duration;
    if (shot.transitionOut) {
      duration += shot.transitionOut.duration;
    }
    return duration;
  }, 0);

  // Format time as MM:SS:FF (minutes:seconds:frames)
  const formatTime = (seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    const frames = Math.floor((seconds % 1) * 30); // Assuming 30 FPS
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}:${frames.toString().padStart(2, '0')}`;
  };

  // Handle play/pause toggle
  const handlePlayPause = () => {
    if (isPlaying) {
      pause();
    } else {
      play();
    }
  };

  // Handle stop
  const handleStop = () => {
    stop();
  };

  // Handle frame-by-frame navigation
  const handlePreviousFrame = () => {
    const frameTime = 1 / 30; // 30 FPS
    setCurrentTime(Math.max(0, currentTime - frameTime));
  };

  const handleNextFrame = () => {
    const frameTime = 1 / 30; // 30 FPS
    setCurrentTime(Math.min(totalDuration, currentTime + frameTime));
  };

  // Handle fullscreen toggle
  const handleFullscreen = () => {
    if (!canvasRef.current) return;

    if (!isFullscreen) {
      if (canvasRef.current.requestFullscreen) {
        canvasRef.current.requestFullscreen();
      }
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen();
      }
    }
    setIsFullscreen(!isFullscreen);
  };

  // Handle volume change
  const handleVolumeChange = (value: number[]) => {
    setVolume(value[0]);
    if (value[0] > 0 && isMuted) {
      setIsMuted(false);
    }
  };

  // Handle mute toggle
  const handleMuteToggle = () => {
    setIsMuted(!isMuted);
  };

  // Handle timeline scrubbing
  const handleTimelineChange = (value: number[]) => {
    setCurrentTime(value[0]);
  };

  // Handle timeline scrubbing with audio sync
  const handleTimelineScrub = (value: number[]) => {
    const newTime = value[0];
    setCurrentTime(newTime);
    
    // This would involve updating audio tracks to play from the new time
  };

  // Handle playback speed change
  const handlePlaybackSpeedChange = (speed: number) => {
    setPlaybackSpeed(speed);
  };

  // Handle loop mode toggle
  const handleLoopToggle = () => {
    setLoopMode(!loopMode);
  };

  // Handle end of playback for loop mode
  useEffect(() => {
    if (loopMode && !isPlaying && currentTime >= totalDuration && totalDuration > 0) {
      setCurrentTime(0);
      play();
    }
  }, [currentTime, isPlaying, loopMode, totalDuration, play, setCurrentTime]);

  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle>Preview</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Video Canvas */}
        <div className="relative bg-black rounded-lg overflow-hidden aspect-video">
          <canvas
            ref={canvasRef}
            className="w-full h-full object-contain"
            style={{ imageRendering: 'crisp-edges' }}
          />

          {/* Fullscreen Button Overlay */}
          <Button
            size="sm"
            variant="ghost"
            className="absolute top-2 right-2 bg-black/50 hover:bg-black/70"
            onClick={handleFullscreen}
          >
            <Maximize2 className="h-4 w-4" />
          </Button>
        </div>

        {/* Timeline Scrubber */}
        <div className="space-y-2">
          <Slider
            value={[currentTime]}
            min={0}
            max={totalDuration || 1}
            step={1 / 30} // 30 FPS
            onValueChange={handleTimelineScrub}
            className="w-full"
          />
          <div className="flex justify-between text-xs text-muted-foreground">
            <span>{formatTime(currentTime)}</span>
            <span>{formatTime(totalDuration)}</span>
          </div>
        </div>

        {/* Playback Controls */}
        <div className="flex items-center justify-center gap-2">
          {/* Frame Back */}
          <Button
            size="sm"
            variant="outline"
            onClick={handlePreviousFrame}
            disabled={currentTime <= 0}
          >
            <SkipBack className="h-4 w-4" />
          </Button>

          {/* Play/Pause */}
          <Button
            size="lg"
            onClick={handlePlayPause}
            disabled={shots.length === 0}
          >
            {isPlaying ? (
              <Pause className="h-5 w-5" />
            ) : (
              <Play className="h-5 w-5" />
            )}
          </Button>

          {/* Stop */}
          <Button
            size="sm"
            variant="outline"
            onClick={handleStop}
            disabled={!isPlaying && currentTime === 0}
          >
            <Square className="h-4 w-4" />
          </Button>

          {/* Frame Forward */}
          <Button
            size="sm"
            variant="outline"
            onClick={handleNextFrame}
            disabled={currentTime >= totalDuration}
          >
            <SkipForward className="h-4 w-4" />
          </Button>
        </div>

        {/* Volume Control */}
        <div className="flex items-center gap-3">
          <Button
            size="sm"
            variant="ghost"
            onClick={handleMuteToggle}
          >
            {isMuted || volume === 0 ? (
              <VolumeX className="h-4 w-4" />
            ) : (
              <Volume2 className="h-4 w-4" />
            )}
          </Button>
          <Slider
            value={[isMuted ? 0 : volume]}
            min={0}
            max={100}
            step={1}
            onValueChange={handleVolumeChange}
            className="flex-1"
          />
          <span className="text-sm text-muted-foreground w-12 text-right">
            {isMuted ? 0 : volume}%
          </span>
        </div>

        {/* Playback Speed Control */}
        <div className="flex items-center gap-3">
          <Label htmlFor="playback-speed" className="text-sm whitespace-nowrap">
            Speed:
          </Label>
          <Select
            value={playbackSpeed.toString()}
            onValueChange={(value) => handlePlaybackSpeedChange(parseFloat(value))}
          >
            <SelectTrigger id="playback-speed" className="w-24">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="0.25">0.25x</SelectItem>
              <SelectItem value="0.5">0.5x</SelectItem>
              <SelectItem value="0.75">0.75x</SelectItem>
              <SelectItem value="1">1x</SelectItem>
              <SelectItem value="1.25">1.25x</SelectItem>
              <SelectItem value="1.5">1.5x</SelectItem>
              <SelectItem value="2">2x</SelectItem>
            </SelectContent>
          </Select>

          {/* Loop Mode Toggle */}
          <div className="flex items-center gap-2 ml-auto">
            <Switch
              id="loop-mode"
              checked={loopMode}
              onCheckedChange={handleLoopToggle}
            />
            <Label htmlFor="loop-mode" className="text-sm flex items-center gap-1 cursor-pointer">
              <Repeat className="h-4 w-4" />
              Loop
            </Label>
          </div>
        </div>

        {/* Timecode Display */}
        <div className="flex items-center justify-between text-sm">
          <div className="flex items-center gap-2">
            <span className="text-muted-foreground">Timecode:</span>
            <span className="font-mono font-medium">{formatTime(currentTime)}</span>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-muted-foreground">Duration:</span>
            <span className="font-mono font-medium">{formatTime(totalDuration)}</span>
          </div>
        </div>

        {/* Shot Info */}
        {shots.length > 0 && (
          <div className="text-sm text-muted-foreground">
            {shots.length} shot{shots.length !== 1 ? 's' : ''} in timeline
          </div>
        )}

        {shots.length === 0 && (
          <div className="text-center py-8 text-muted-foreground">
            No shots in timeline. Add shots to preview your video.
          </div>
        )}
      </CardContent>
    </Card>
  );
};

/**
 * ProgressPanel Component
 * 
 * Displays progress for all generation tasks with real-time updates.
 * Can be used as a standalone panel or integrated into the task queue modal.
 */

import React, { useEffect } from 'react';
import { useAppStore } from '@/stores/useAppStore';
import { useProgressTracking } from '@/hooks/useProgressTracking';
import { ProgressIndicator } from './ProgressIndicator';
import type { GenerationTask } from '@/types';

export interface ProgressPanelProps {
  /**
   * Filter tasks by status
   */
  filterStatus?: GenerationTask['status'] | 'all';

  /**
   * Show detailed information
   * @default false
   */
  showDetails?: boolean;

  /**
   * Compact mode (smaller display)
   * @default false
   */
  compact?: boolean;

  /**
   * Auto-start tracking
   * @default true
   */
  autoStart?: boolean;

  /**
   * Custom className
   */
  className?: string;

  /**
   * Callback when task completes
   */
  onTaskComplete?: (taskId: string) => void;

  /**
   * Callback when task fails
   */
  onTaskError?: (taskId: string, error: string) => void;
}

export const ProgressPanel: React.FC<ProgressPanelProps> = ({
  filterStatus = 'all',
  showDetails = false,
  compact = false,
  autoStart = true,
  className = '',
  onTaskComplete,
  onTaskError,
}) => {
  const taskQueue = useAppStore((state) => state.taskQueue);

  const {
    progressUpdates,
    getProgress,
    startTrackingAll,
    stopTrackingAll,
  } = useProgressTracking({
    autoStart,
    onComplete: onTaskComplete,
    onError: onTaskError,
  });

  // Filter tasks
  const filteredTasks = taskQueue.filter((task) => {
    if (filterStatus === 'all') return true;
    return task.status === filterStatus;
  });

  // Sort tasks: processing first, then pending, then completed/failed
  const sortedTasks = [...filteredTasks].sort((a, b) => {
    const statusOrder = { processing: 0, pending: 1, completed: 2, failed: 3 };
    const aOrder = statusOrder[a.status];
    const bOrder = statusOrder[b.status];
    
    if (aOrder !== bOrder) {
      return aOrder - bOrder;
    }
    
    return a.priority - b.priority;
  });

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      stopTrackingAll();
    };
  }, [stopTrackingAll]);

  if (sortedTasks.length === 0) {
    return (
      <div className={`text-center py-8 text-gray-500 ${className}`}>
        <p className="text-lg mb-2">No tasks to display</p>
        <p className="text-sm">
          {filterStatus === 'all'
            ? 'Add tasks to the queue to see progress here'
            : `No ${filterStatus} tasks found`}
        </p>
      </div>
    );
  }

  return (
    <div className={`space-y-3 ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-semibold text-gray-900">
          Task Progress
          <span className="ml-2 text-sm font-normal text-gray-500">
            ({sortedTasks.length} {sortedTasks.length === 1 ? 'task' : 'tasks'})
          </span>
        </h3>
        
        {/* Summary Stats */}
        <div className="flex gap-4 text-sm">
          <div className="flex items-center gap-1">
            <span className="w-2 h-2 rounded-full bg-blue-500" />
            <span className="text-gray-600">
              {taskQueue.filter((t) => t.status === 'processing').length} processing
            </span>
          </div>
          <div className="flex items-center gap-1">
            <span className="w-2 h-2 rounded-full bg-gray-400" />
            <span className="text-gray-600">
              {taskQueue.filter((t) => t.status === 'pending').length} pending
            </span>
          </div>
          <div className="flex items-center gap-1">
            <span className="w-2 h-2 rounded-full bg-green-500" />
            <span className="text-gray-600">
              {taskQueue.filter((t) => t.status === 'completed').length} completed
            </span>
          </div>
        </div>
      </div>

      {/* Task List */}
      <div className="space-y-3">
        {sortedTasks.map((task) => (
          <ProgressIndicator
            key={task.id}
            task={task}
            progress={getProgress(task.id)}
            showDetails={showDetails}
            compact={compact}
          />
        ))}
      </div>

      {/* Overall Progress */}
      {!compact && taskQueue.length > 0 && (
        <div className="mt-6 pt-4 border-t">
          <div className="flex justify-between text-sm text-gray-600 mb-2">
            <span className="font-medium">Overall Progress</span>
            <span>
              {taskQueue.filter((t) => t.status === 'completed').length} / {taskQueue.length} completed
            </span>
          </div>
          <div className="w-full bg-gray-200 rounded-full h-3">
            <div
              className="bg-gradient-to-r from-blue-500 to-green-500 h-3 rounded-full transition-all duration-300"
              style={{
                width: `${(taskQueue.filter((t) => t.status === 'completed').length / taskQueue.length) * 100}%`,
              }}
            />
          </div>
        </div>
      )}
    </div>
  );
};

