/**
 * SequenceGenerationControl Component
 * 
 * Controls sequence generation pipeline execution with a "Generate Sequence" button
 * that is enabled only when all shots have valid prompts. Displays GenerationProgressModal
 * during generation to show detailed progress through the StoryCore pipeline.
 * 
 * Requirements: 2.3, 2.4, 3.1, 3.2
 */

import React, { useState, useCallback } from 'react';
import { Button } from './ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from './ui/card';
import { Alert, AlertDescription } from './ui/alert';
import { Badge } from './ui/badge';
import { Sparkles, AlertCircle, CheckCircle, Loader2 } from 'lucide-react';
import { GenerationProgressModal } from './GenerationProgressModal';
import { useProject } from '../contexts/ProjectContext';
import type { GenerationResults } from '../types/projectDashboard';

// ============================================================================
// Component Props
// ============================================================================

export interface SequenceGenerationControlProps {
  /** Optional CSS class name */
  className?: string;
  /** Callback when generation completes successfully */
  onGenerationComplete?: (results: GenerationResults) => void;
  /** Callback when generation is cancelled */
  onGenerationCancel?: () => void;
}

// ============================================================================
// SequenceGenerationControl Component
// ============================================================================

/**
 * SequenceGenerationControl Component
 * 
 * Provides a control interface for triggering sequence generation through the
 * StoryCore pipeline. The "Generate Sequence" button is enabled only when all
 * shots have valid prompts (non-empty, 10-500 characters). During generation,
 * displays a progress modal with stage-by-stage indicators.
 * 
 * Requirements: 2.3, 2.4, 3.1, 3.2
 */
export const SequenceGenerationControl: React.FC<SequenceGenerationControlProps> = ({
  className = '',
  onGenerationComplete,
  onGenerationCancel,
}) => {
  // ============================================================================
  // Context
  // ============================================================================

  const {
    validateAllShots,
    getPromptCompletionStatus,
    generateSequence,
    cancelGeneration,
    generationStatus,
    isGenerating,
  } = useProject();

  // ============================================================================
  // Local State
  // ============================================================================

  const [showProgressModal, setShowProgressModal] = useState(false);

  // ============================================================================
  // Computed Values
  // ============================================================================

  // Validate all shots to determine if generation can proceed
  // Requirements: 2.3, 2.4
  const validation = validateAllShots();
  const canGenerate = validation.valid && !isGenerating;
  
  // Get prompt completion status for display
  const completionStatus = getPromptCompletionStatus();

  // ============================================================================
  // Handlers
  // ============================================================================

  /**
   * Handle generate button click
   * Triggers the generation pipeline and shows progress modal
   * Requirements: 3.1, 3.2
   */
  const handleGenerate = useCallback(async () => {
    if (!canGenerate) return;

    try {
      // Show progress modal
      setShowProgressModal(true);

      // Trigger generation through context
      const results = await generateSequence();

      if (results) {
        // Generation completed successfully
        onGenerationComplete?.(results);
      }
    } catch (error) {
      console.error('Generation error:', error);
    }
  }, [canGenerate, generateSequence, onGenerationComplete]);

  /**
   * Handle cancel button click in progress modal
   * Requirements: 8.5
   */
  const handleCancel = useCallback(() => {
    cancelGeneration();
    onGenerationCancel?.();
  }, [cancelGeneration, onGenerationCancel]);

  /**
   * Handle retry button click after error
   * Requirements: 3.7
   */
  const handleRetry = useCallback(() => {
    // Reset modal state and trigger generation again
    setShowProgressModal(false);
    setTimeout(() => {
      handleGenerate();
    }, 100);
  }, [handleGenerate]);

  /**
   * Handle close button click in progress modal
   */
  const handleCloseModal = useCallback(() => {
    setShowProgressModal(false);
  }, []);

  // ============================================================================
  // Render Helpers
  // ============================================================================

  /**
   * Get button text based on generation state
   */
  const getButtonText = (): string => {
    if (isGenerating) {
      return 'Generating...';
    }
    if (!validation.valid) {
      return 'Fix Prompts to Generate';
    }
    return 'Generate Sequence';
  };

  /**
   * Get button icon based on generation state
   */
  const getButtonIcon = () => {
    if (isGenerating) {
      return <Loader2 className="h-4 w-4 animate-spin" />;
    }
    return <Sparkles className="h-4 w-4" />;
  };

  // ============================================================================
  // Render
  // ============================================================================

  return (
    <>
      <Card className={className}>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Sparkles className="h-5 w-5" />
            Sequence Generation
          </CardTitle>
          <CardDescription>
            Generate your complete sequence through the StoryCore pipeline
          </CardDescription>
        </CardHeader>

        <CardContent className="space-y-4">
          {/* Prompt Completion Status */}
          {/* Requirements: 2.4 */}
          <div className="space-y-2">
            <p className="text-sm font-medium">Prompt Status</p>
            <div className="flex items-center gap-2">
              <Badge
                variant={completionStatus.complete === completionStatus.total ? 'default' : 'secondary'}
                className="flex items-center gap-1"
              >
                <CheckCircle className="h-3 w-3" />
                {completionStatus.complete} / {completionStatus.total} Complete
              </Badge>
              
              {completionStatus.incomplete > 0 && (
                <Badge variant="destructive" className="flex items-center gap-1">
                  <AlertCircle className="h-3 w-3" />
                  {completionStatus.incomplete} Incomplete
                </Badge>
              )}
            </div>
          </div>

          {/* Validation Errors Alert */}
          {/* Requirements: 2.4 */}
          {!validation.valid && validation.invalidShots.length > 0 && (
            <Alert variant="destructive" role="alert" aria-live="polite">
              <AlertCircle className="h-4 w-4" aria-hidden="true" />
              <AlertDescription>
                <p className="font-medium mb-2">
                  Cannot generate: {validation.invalidShots.length} shot(s) have invalid prompts
                </p>
                <ul className="text-sm space-y-1 list-disc list-inside">
                  {validation.invalidShots.slice(0, 3).map((shot) => (
                    <li key={shot.id}>
                      Shot {shot.id.slice(0, 8)}: {
                        shot.promptValidation?.errors[0]?.message || 'Invalid prompt'
                      }
                    </li>
                  ))}
                  {validation.invalidShots.length > 3 && (
                    <li className="text-muted-foreground">
                      ...and {validation.invalidShots.length - 3} more
                    </li>
                  )}
                </ul>
              </AlertDescription>
            </Alert>
          )}

          {/* Success Alert */}
          {validation.valid && completionStatus.total > 0 && !isGenerating && (
            <Alert role="status" aria-live="polite">
              <CheckCircle className="h-4 w-4 text-green-600" aria-hidden="true" />
              <AlertDescription>
                All prompts are valid. Ready to generate sequence!
              </AlertDescription>
            </Alert>
          )}

          {/* Empty Project Alert */}
          {completionStatus.total === 0 && (
            <Alert role="status">
              <AlertCircle className="h-4 w-4" aria-hidden="true" />
              <AlertDescription>
                No shots in project. Add shots to begin generation.
              </AlertDescription>
            </Alert>
          )}

          {/* Pipeline Information */}
          <div className="space-y-2 p-4 bg-muted rounded-lg">
            <p className="text-sm font-medium">Pipeline Stages</p>
            <div className="text-xs text-muted-foreground space-y-1">
              <div className="flex items-center gap-2">
                <span className="text-lg">­ƒÄ¿</span>
                <span>Master Coherence Sheet (3x3 grid)</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="text-lg">ÔÜí</span>
                <span>ComfyUI Image Generation</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="text-lg">­ƒÜÇ</span>
                <span>Promotion Engine Processing</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="text-lg">­ƒöì</span>
                <span>QA Analysis & Autofix</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="text-lg">­ƒôª</span>
                <span>Export Package Creation</span>
              </div>
            </div>
          </div>

          {/* Generate Button */}
          {/* Requirements: 2.3, 3.1 */}
          <Button
            onClick={handleGenerate}
            disabled={!canGenerate || completionStatus.total === 0}
            className="w-full"
            size="lg"
            aria-label={getButtonText()}
            aria-disabled={!canGenerate || completionStatus.total === 0}
          >
            {getButtonIcon()}
            <span className="ml-2">{getButtonText()}</span>
          </Button>

          {/* Generation Info */}
          {completionStatus.total > 0 && (
            <p className="text-xs text-center text-muted-foreground">
              {validation.valid
                ? `Ready to generate ${completionStatus.total} shot${completionStatus.total !== 1 ? 's' : ''}`
                : 'Fix invalid prompts to enable generation'}
            </p>
          )}
        </CardContent>
      </Card>

      {/* Generation Progress Modal */}
      {/* Requirements: 3.2, 8.1, 8.2, 8.3, 8.4, 8.5 */}
      <GenerationProgressModal
        isOpen={showProgressModal}
        status={generationStatus}
        onCancel={handleCancel}
        onClose={handleCloseModal}
        onRetry={handleRetry}
      />
    </>
  );
};

/**
 * Default export
 */
export default SequenceGenerationControl;

import React, { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { useAppStore } from '@/stores/useAppStore';
// No alert-dialog, using Dialog instead
import { ChevronDown, ChevronRight, ChevronUp, Plus, FileText, Copy, Trash2, Download, Star, Expand, Edit } from 'lucide-react';
import { SequencePlan, Act, Scene } from '@/types/sequencePlan';
import { cn } from '@/lib/utils';

interface SequencePlanManagerProps {
  plans: SequencePlan[];
  currentPlanId: string | null;
  onSelectPlan: (planId: string) => void;
  onCreatePlan: (name: string, description?: string) => void;
  onDuplicatePlan: (planId: string) => void;
  onDeletePlan: (planId: string) => void;
  onExportPlan: (planId: string) => void;
  className?: string;
}

interface TreeNode {
  id: string;
  name: string;
  type: 'plan' | 'act' | 'scene' | 'shot';
  children?: TreeNode[];
  level: number;
  parentId?: string;
}

export function SequencePlanManager({
  plans,
  currentPlanId,
  onSelectPlan,
  onCreatePlan,
  onDuplicatePlan,
  onDeletePlan,
  onExportPlan,
  className,
}: SequencePlanManagerProps) {
  const [expandedNodes, setExpandedNodes] = useState<Set<string>>(new Set());
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState<string | null>(null);
  const [createForm, setCreateForm] = useState({ name: '', description: '' });
  
  // Get wizard action from useAppStore
  const openSequencePlanWizard = useAppStore((state) => state.openSequencePlanWizard);

  // Convert plans to tree nodes
  const buildTreeNodes = (): TreeNode[] => {
    const nodes: TreeNode[] = [];

    plans.forEach(plan => {
      const planNode: TreeNode = {
        id: plan.id,
        name: plan.name,
        type: 'plan',
        level: 0,
        children: [],
      };

      // Add acts
      plan.acts.forEach(act => {
        const actNode: TreeNode = {
          id: act.id,
          name: `Act ${act.number}: ${act.title}`,
          type: 'act',
          level: 1,
          parentId: plan.id,
          children: [],
        };

        // Add scenes in this act
        const actScenes = plan.scenes.filter(scene => scene.actId === act.id);
        actScenes.forEach(scene => {
          const sceneNode: TreeNode = {
            id: scene.id,
            name: `Scene ${scene.number}: ${scene.title}`,
            type: 'scene',
            level: 2,
            parentId: act.id,
            children: [],
          };

          // Add shots in this scene
          const sceneShots = plan.shots.filter(shot => scene.shotIds.includes(shot.id));
          sceneNode.children = sceneShots.map(shot => ({
            id: shot.id,
            name: `Shot ${shot.number}`,
            type: 'shot' as const,
            level: 3,
            parentId: scene.id,
          }));

          actNode.children!.push(sceneNode);
        });

        planNode.children!.push(actNode);
      });

      nodes.push(planNode);
    });

    return nodes;
  };

  const treeNodes = buildTreeNodes();

  const toggleExpanded = (nodeId: string) => {
    const newExpanded = new Set(expandedNodes);
    if (newExpanded.has(nodeId)) {
      newExpanded.delete(nodeId);
    } else {
      newExpanded.add(nodeId);
    }
    setExpandedNodes(newExpanded);
  };

  const expandAll = () => {
    const allExpandable = new Set<string>();
    const collectExpandable = (nodes: TreeNode[]) => {
      nodes.forEach(node => {
        if (node.children && node.children.length > 0) {
          allExpandable.add(node.id);
          collectExpandable(node.children);
        }
      });
    };
    collectExpandable(treeNodes);
    setExpandedNodes(allExpandable);
  };

  const collapseAll = () => {
    setExpandedNodes(new Set());
  };

  const renderTreeNode = (node: TreeNode): React.ReactNode => {
    const isExpanded = expandedNodes.has(node.id);
    const isCurrentPlan = node.type === 'plan' && node.id === currentPlanId;
    const hasChildren = node.children && node.children.length > 0;

    return (
      <div key={node.id}>
        <div
          className={cn(
            'group flex items-center py-2 px-2 hover:bg-muted cursor-pointer rounded-sm',
            isCurrentPlan && 'bg-primary/10 border border-primary/20'
          )}
          style={{ paddingLeft: `${node.level * 16 + 8}px` }}
          onClick={() => {
            if (node.type === 'plan') {
              onSelectPlan(node.id);
            } else if (hasChildren) {
              toggleExpanded(node.id);
            }
          }}
        >
          {/* Expand/Collapse Icon */}
          {hasChildren ? (
            <button
              onClick={(e) => {
                e.stopPropagation();
                toggleExpanded(node.id);
              }}
              className="mr-2 p-1 hover:bg-muted rounded"
            >
              {isExpanded ? (
                <ChevronDown className="w-4 h-4" />
              ) : (
                <ChevronRight className="w-4 h-4" />
              )}
            </button>
          ) : (
            <div className="w-6" />
          )}

          {/* Icon based on type */}
          <div className="mr-2">
            {node.type === 'plan' && <FileText className="w-4 h-4" />}
            {node.type === 'act' && <div className="w-4 h-4 rounded bg-blue-500" />}
            {node.type === 'scene' && <div className="w-4 h-4 rounded bg-green-500" />}
            {node.type === 'shot' && <div className="w-4 h-4 rounded bg-orange-500" />}
          </div>

          {/* Name */}
          <span className="flex-1 text-sm truncate">{node.name}</span>

          {/* Current plan indicator */}
          {isCurrentPlan && (
            <Star className="w-4 h-4 text-primary fill-primary ml-2" />
          )}

          {/* Actions for plans */}
          {node.type === 'plan' && (
            <div className="ml-2 flex gap-1 opacity-0 group-hover:opacity-100">
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  const plan = plans.find(p => p.id === node.id);
                  if (plan) {
                    openSequencePlanWizard({
                      mode: 'edit',
                      existingSequencePlan: plan,
                      sourceLocation: 'plans-panel',
                    });
                  }
                }}
                className="p-1 hover:bg-muted rounded"
                title="Edit plan"
              >
                <Edit className="w-3 h-3" />
              </button>
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  onDuplicatePlan(node.id);
                }}
                className="p-1 hover:bg-muted rounded"
                title="Duplicate plan"
              >
                <Copy className="w-3 h-3" />
              </button>
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  onExportPlan(node.id);
                }}
                className="p-1 hover:bg-muted rounded"
                title="Export plan"
              >
                <Download className="w-3 h-3" />
              </button>
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  setShowDeleteModal(node.id);
                }}
                className="p-1 hover:bg-destructive/10 text-destructive hover:text-destructive rounded"
                title="Delete plan"
              >
                <Trash2 className="w-3 h-3" />
              </button>
            </div>
          )}
        </div>

        {/* Children */}
        {hasChildren && isExpanded && (
          <div>
            {node.children!.map(child => renderTreeNode(child))}
          </div>
        )}
      </div>
    );
  };

  const handleCreatePlan = () => {
    if (createForm.name.trim()) {
      onCreatePlan(createForm.name, createForm.description);
      setShowCreateModal(false);
      setCreateForm({ name: '', description: '' });
    }
  };

  const handleDeleteConfirm = () => {
    if (showDeleteModal) {
      onDeletePlan(showDeleteModal);
      setShowDeleteModal(null);
    }
  };

  return (
    <div className={cn('flex flex-col h-full', className)}>
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b">
        <h2 className="text-lg font-semibold">Sequence Plans</h2>
        <div className="flex items-center gap-2">
          <Button
            onClick={expandAll}
            size="sm"
            variant="outline"
            className="flex items-center gap-1"
            title="Expand all"
          >
            <Expand className="w-4 h-4" />
          </Button>
          <Button
            onClick={collapseAll}
            size="sm"
            variant="outline"
            className="flex items-center gap-1"
            title="Collapse all"
          >
            <ChevronUp className="w-4 h-4" />
          </Button>
          <Button
            onClick={() => setShowCreateModal(true)}
            size="sm"
            className="flex items-center gap-2"
          >
            <Plus className="w-4 h-4" />
            New Plan
          </Button>
        </div>
      </div>

      {/* Tree View */}
      <div className="flex-1 overflow-auto p-2">
        {treeNodes.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-8 text-center text-muted-foreground">
            <FileText className="w-12 h-12 mb-4" />
            <p className="text-sm">No sequence plans yet</p>
            <Button
              onClick={() => setShowCreateModal(true)}
              variant="outline"
              size="sm"
              className="mt-4"
            >
              Create your first plan
            </Button>
          </div>
        ) : (
          <div className="space-y-1">
            {treeNodes.map(node => renderTreeNode(node))}
          </div>
        )}
      </div>

      {/* Create Plan Modal */}
      <Dialog open={showCreateModal} onOpenChange={setShowCreateModal}>
