      {/* Tab Content */}
      <div className="flex-1 overflow-hidden">
        {activeTab === 'sprites' && (
          <SpritesList
            sprites={Array.from(sprites.values())}
            spriteOrder={spriteOrder}
            selectedSpriteId={selectedSpriteId}
            onSelect={selectSprite}
