          />
        )}

        {activeTab === 'animations' && (
          <AnimationsPanel sprite={selectedSprite?.sprite || null} />
        )}

        {activeTab === 'effects' && selectedSprite && (
          <EffectsPanel
            effects={selectedSprite.effects}
