import React, { useState } from 'react';
import { VoiceOverGenerator } from './VoiceOverGenerator';
import { VoiceLibrary } from './VoiceLibrary';
import { useVoiceOverGenerator } from '../hooks/useVoiceOverGenerator';
import type { VoiceOver } from '../types';
import { Tabs, TabsContent, TabsList, TabsTrigger } from './ui/tabs';
import { Alert, AlertDescription } from './ui/alert';
import { AlertCircle } from 'lucide-react';

interface VoiceOverPanelProps {
  shotId: string;
  onClose?: () => void;
}

export const VoiceOverPanel: React.FC<VoiceOverPanelProps> = ({ shotId, onClose }) => {
  const { isGenerating, error, generateVoiceOver, clearError } = useVoiceOverGenerator();
  const [selectedVoice, setSelectedVoice] = useState<string>('female');

  const handleGenerate = async (voiceOver: VoiceOver) => {
    try {
      await generateVoiceOver(voiceOver, shotId);
      // Optionally close panel after successful generation
      if (onClose) {
        onClose();
      }
    } catch (err) {
      // Error is handled by the hook
      console.error('Failed to generate voiceover:', err);
    }
  };

  return (
    <div className="space-y-4">
      {error && (
        <Alert variant="destructive">
          <AlertCircle className="h-4 w-4" />
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}

      <Tabs defaultValue="generator" className="w-full">
        <TabsList className="grid w-full grid-cols-2">
          <TabsTrigger value="generator">Generate</TabsTrigger>
          <TabsTrigger value="library">Voice Library</TabsTrigger>
        </TabsList>

        <TabsContent value="generator" className="space-y-4">
          <VoiceOverGenerator
            onGenerate={handleGenerate}
            onCancel={onClose}
            isGenerating={isGenerating}
          />
        </TabsContent>

        <TabsContent value="library" className="space-y-4">
          <VoiceLibrary
            selectedVoice={selectedVoice}
            onSelectVoice={setSelectedVoice}
          />
        </TabsContent>
      </Tabs>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import type { AudioTrack } from '../types';

interface WaveformDisplayProps {
  track: AudioTrack;
  width?: number;
  height?: number;
  color?: string;
  backgroundColor?: string;
  onGenerate?: (waveformData: number[]) => void;
}

export const WaveformDisplay: React.FC<WaveformDisplayProps> = ({
  track,
  width = 300,
  height = 60,
  color = '#3b82f6',
  backgroundColor = '#f3f4f6',
  onGenerate,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (track.waveformData) {
      // Use existing waveform data
      drawWaveform(track.waveformData);
    } else if (track.url) {
      // Generate waveform from audio file
      generateWaveform();
    }
  }, [track.waveformData, track.url, width, height]);

  const generateWaveform = async () => {
    if (!track.url || isGenerating) return;

    setIsGenerating(true);
    setError(null);

    try {
      // Create audio context
      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      
      // Fetch audio file
      const response = await fetch(track.url);
      if (!response.ok) {
        throw new Error('Failed to fetch audio file');
      }
      
      const arrayBuffer = await response.arrayBuffer();
      
      // Decode audio data
      const audioBuffer = await audioContext.decodeAudioData(arrayBuffer);
      
      // Generate waveform data using Web Worker for better performance
      const samples = Math.min(width, 500); // Reduced samples for better performance
      const waveformData = await generateWaveformWithWorker(audioBuffer, samples);
      
      // Draw waveform
      drawWaveform(waveformData);
      
      // Notify parent component
      if (onGenerate) {
        onGenerate(waveformData);
      }
      
      // Close audio context to free resources
      await audioContext.close();
    } catch (err) {
      console.error('Error generating waveform:', err);
      setError('Failed to generate waveform');
      drawPlaceholder();
    } finally {
      setIsGenerating(false);
    }
  };

  const generateWaveformWithWorker = (
    audioBuffer: AudioBuffer,
    samples: number
  ): Promise<number[]> => {
    return new Promise((resolve, reject) => {
      // Fallback to synchronous generation if Worker is not available
      if (typeof Worker === 'undefined') {
        resolve(extractWaveformData(audioBuffer, samples));
        return;
      }

      try {
        // Create worker from inline code (avoids separate file issues)
        const workerCode = `
          self.onmessage = (event) => {
            const { audioData, samples } = event.data;
            const blockSize = Math.floor(audioData.length / samples);
            const waveform = [];

            for (let i = 0; i < samples; i++) {
              const start = i * blockSize;
              const end = start + blockSize;
              let sum = 0;

              for (let j = start; j < end && j < audioData.length; j++) {
                sum += audioData[j] * audioData[j];
              }

              const rms = Math.sqrt(sum / blockSize);
              waveform.push(rms);
            }

            const max = Math.max(...waveform);
            const normalized = waveform.map((value) => (max > 0 ? value / max : 0));
            
            self.postMessage({ waveformData: normalized });
          };
        `;

        const blob = new Blob([workerCode], { type: 'application/javascript' });
        const workerUrl = URL.createObjectURL(blob);
        const worker = new Worker(workerUrl);

        worker.onmessage = (event) => {
          resolve(event.data.waveformData);
          worker.terminate();
          URL.revokeObjectURL(workerUrl);
        };

        worker.onerror = (error) => {
          reject(error);
          worker.terminate();
          URL.revokeObjectURL(workerUrl);
        };

        // Send audio data to worker
        const channelData = audioBuffer.getChannelData(0);
        worker.postMessage({
          audioData: channelData,
          samples,
        });
      } catch (error) {
        // Fallback to synchronous generation
        resolve(extractWaveformData(audioBuffer, samples));
      }
    });
  };

  const extractWaveformData = (audioBuffer: AudioBuffer, samples: number): number[] => {
    const channelData = audioBuffer.getChannelData(0); // Use first channel
    const blockSize = Math.floor(channelData.length / samples);
    const waveform: number[] = [];

    for (let i = 0; i < samples; i++) {
      const start = i * blockSize;
      const end = start + blockSize;
      let sum = 0;

      // Calculate RMS (Root Mean Square) for better visualization
      for (let j = start; j < end && j < channelData.length; j++) {
        sum += channelData[j] * channelData[j];
      }

      const rms = Math.sqrt(sum / blockSize);
      waveform.push(rms);
    }

    // Normalize waveform data
    const max = Math.max(...waveform);
    return waveform.map((value) => (max > 0 ? value / max : 0));
  };

  const drawWaveform = (waveformData: number[]) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear canvas
    ctx.fillStyle = backgroundColor;
    ctx.fillRect(0, 0, width, height);

    // Draw waveform
    const barWidth = width / waveformData.length;
    const centerY = height / 2;

    ctx.fillStyle = color;

    waveformData.forEach((value, index) => {
      const barHeight = value * centerY * 0.9; // 90% of half height
      const x = index * barWidth;
      const y = centerY - barHeight;

      // Draw bar from center
      ctx.fillRect(x, y, Math.max(barWidth - 1, 1), barHeight * 2);
    });
  };

  const drawPlaceholder = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear canvas
    ctx.fillStyle = backgroundColor;
    ctx.fillRect(0, 0, width, height);

    // Draw placeholder text
    ctx.fillStyle = '#9ca3af';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(error || 'No audio', width / 2, height / 2);
  };

  useEffect(() => {
    if (!track.url && !track.waveformData) {
      drawPlaceholder();
    }
  }, [track.url, track.waveformData]);

  return (
    <div className="relative">
      <canvas
        ref={canvasRef}
        width={width}
        height={height}
        className="rounded border border-gray-300"
      />
      {isGenerating && (
        <div className="absolute inset-0 flex items-center justify-center bg-white bg-opacity-75 rounded">
          <div className="text-sm text-gray-600">Generating waveform...</div>
        </div>
      )}
      {error && !isGenerating && (
        <div className="absolute inset-0 flex items-center justify-center bg-red-50 bg-opacity-75 rounded">
          <div className="text-xs text-red-600">{error}</div>
        </div>
      )}
    </div>
  );
};

// Utility function to generate waveform data from audio URL
export async function generateWaveformData(
  audioUrl: string,
  samples: number = 1000
): Promise<number[]> {
  const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();

  try {
    const response = await fetch(audioUrl);
    const arrayBuffer = await response.arrayBuffer();
    const audioBuffer = await audioContext.decodeAudioData(arrayBuffer);

    const channelData = audioBuffer.getChannelData(0);
    const blockSize = Math.floor(channelData.length / samples);
    const waveform: number[] = [];

    for (let i = 0; i < samples; i++) {
      const start = i * blockSize;
      const end = start + blockSize;
      let sum = 0;

      for (let j = start; j < end && j < channelData.length; j++) {
        sum += channelData[j] * channelData[j];
      }

      const rms = Math.sqrt(sum / blockSize);
      waveform.push(rms);
    }

    // Normalize
    const max = Math.max(...waveform);
    const normalized = waveform.map((value) => (max > 0 ? value / max : 0));

    await audioContext.close();
    return normalized;
  } catch (error) {
    console.error('Error generating waveform data:', error);
    await audioContext.close();
    throw error;
  }
}

/**
 * Workflow Progress Bar Component
 * 
 * A sleek, high-level progress tracker showing the user's journey
 * through the filmmaking process.
 */

import React from 'react';
import { useWorkflowStore, WorkflowStage } from '../stores/workflowStore';
import { Check, Circle, ArrowRight } from 'lucide-react';
import { cn } from '@/lib/utils';
import './WorkflowProgressBar.css';

const STAGE_LABELS: Record<WorkflowStage, string> = {
    preparation: 'Pr├®paration',
    storytelling: 'Histoire',
    generation: 'G├®n├®ration AI',
    post_prod: 'Post-Prod',
    delivery: 'Export',
};

const STAGE_ORDER: WorkflowStage[] = ['preparation', 'storytelling', 'generation', 'post_prod', 'delivery'];

export const WorkflowProgressBar: React.FC = () => {
    const { currentStage, stageProgress, globalProgress } = useWorkflowStore();

    return (
        <div className="workflow-progress-container">
            {/* Global Progress Line Overlay (Subtle Background) */}
            <div className="workflow-background-line" />

            {/* Active Stage Indicator Line */}
            <div
                className="workflow-active-line"
                style={{ width: `${(STAGE_ORDER.indexOf(currentStage) / (STAGE_ORDER.length - 1)) * 100}%` }}
            />

            <div className="workflow-stages-row">
                {STAGE_ORDER.map((stage, index) => {
                    const progress = stageProgress[stage];
                    const isCompleted = progress.status === 'completed';
                    const isCurrent = currentStage === stage;
                    const isTodo = progress.status === 'todo';

                    return (
                        <div
                            key={stage}
                            className={cn(
                                "workflow-stage-item",
                                isCompleted && "is-completed",
                                isCurrent && "is-current",
                                isTodo && "is-todo"
                            )}
                        >
                            <div className="stage-icon-wrapper">
                                {isCompleted ? (
                                    <Check className="stage-icon" />
                                ) : (
                                    <span className="stage-number">{index + 1}</span>
                                )}

                                {/* Visual tooltip on hover showing tasks */}
                                <div className="stage-tooltip">
                                    <div className="tooltip-header">{STAGE_LABELS[stage]}</div>
                                    <div className="tooltip-progress">{progress.percentage}% complet├®</div>
                                    <ul className="tooltip-tasks">
                                        {progress.requiredTasks.map(task => (
                                            <li key={task} className={progress.completedTasks.includes(task) ? 'task-done' : ''}>
                                                {progress.completedTasks.includes(task) ? 'Ô£ô' : 'Ôùï'} {formatTaskId(task)}
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                            </div>
                            <span className="stage-label">{STAGE_LABELS[stage]}</span>
                        </div>
                    );
                })}
            </div>

            {/* Global Percentage Badge (Optional, subtle) */}
            <div className="global-progress-badge">
                <span className="percentage">{globalProgress}%</span>
                <span className="label">GLOBAL</span>
            </div>
        </div>
    );
};

function formatTaskId(id: string): string {
    return id
        .replace(/_/g, ' ')
        .replace(/\b\w/g, c => c.toUpperCase());
}

