    it('should NOT display direction controls for "dissolve" transition', () => {
      const shot1 = createMockShot('shot-1', 'Shot 1', 0, createMockTransition({ type: 'dissolve' }));
      const shot2 = createMockShot('shot-2', 'Shot 2', 1);
      
      vi.mocked(useStore).mockImplementation((selector: any) => {
        const state = {
          shots: [shot1, shot2],
          setTransition: mockSetTransition,
        };
        return selector ? selector(state) : state;
      });

      vi.mocked(useSelectedShot).mockReturnValue(shot1);

      render(<TransitionPanel />);

      expect(screen.queryByText('Direction')).not.toBeInTheDocument();
    });

    it('should update direction when changed', () => {
      const shot1 = createMockShot('shot-1', 'Shot 1', 0, createMockTransition({ type: 'wipe', direction: 'right' }));
      const shot2 = createMockShot('shot-2', 'Shot 2', 1);
      
      vi.mocked(useStore).mockImplementation((selector: any) => {
        const state = {
          shots: [shot1, shot2],
          setTransition: mockSetTransition,
        };
        return selector ? selector(state) : state;
      });

      vi.mocked(useSelectedShot).mockReturnValue(shot1);

      render(<TransitionPanel />);

      // Click the "Left" direction radio button
      const leftRadio = screen.getByLabelText('Left');
      fireEvent.click(leftRadio);

      expect(mockSetTransition).toHaveBeenCalledWith(
        'shot-1',
        expect.objectContaining({
          direction: 'left',
        })
      );
    });
  });

  describe('Transition Descriptions', () => {
    const transitionTypes: Array<{ type: Transition['type']; description: string }> = [
      { type: 'fade', description: 'Gradually fade from one shot to another' },
      { type: 'dissolve', description: 'Blend shots together with a cross-dissolve' },
      { type: 'wipe', description: 'Wipe across the screen in a direction' },
      { type: 'slide', description: 'Slide the next shot in from a direction' },
      { type: 'zoom', description: 'Zoom in or out between shots' },
      { type: 'custom', description: 'Custom transition with advanced parameters' },
    ];

    transitionTypes.forEach(({ type, description }) => {
      it(`should display correct description for ${type} transition`, () => {
        const shot1 = createMockShot('shot-1', 'Shot 1', 0, createMockTransition({ type }));
        const shot2 = createMockShot('shot-2', 'Shot 2', 1);
        
        vi.mocked(useStore).mockImplementation((selector: any) => {
          const state = {
            shots: [shot1, shot2],
            setTransition: mockSetTransition,
          };
          return selector ? selector(state) : state;
        });

        vi.mocked(useSelectedShot).mockReturnValue(shot1);

        render(<TransitionPanel />);
        
        expect(screen.getByText(description)).toBeInTheDocument();
      });
    });
  });

  describe('Transition Preview', () => {
    const shot1 = createMockShot('shot-1', 'Shot 1', 0, createMockTransition());
    const shot2 = createMockShot('shot-2', 'Shot 2', 1);

    beforeEach(() => {
      vi.mocked(useStore).mockImplementation((selector: any) => {
        const state = {
          shots: [shot1, shot2],
          setTransition: mockSetTransition,
        };
        return selector ? selector(state) : state;
      });

      vi.mocked(useSelectedShot).mockReturnValue(shot1);
    });

    it('should display transition preview section when transition exists', () => {
      render(<TransitionPanel />);

      expect(screen.getByText('Preview')).toBeInTheDocument();
      expect(screen.getByRole('button', { name: /Play Preview/i })).toBeInTheDocument();
    });

    it('should display "Play Preview" button in initial state', () => {
      render(<TransitionPanel />);

      const playButton = screen.getByRole('button', { name: /Play Preview/i });
      expect(playButton).toBeInTheDocument();
      expect(playButton).not.toBeDisabled();
    });

    it('should display preview container with gradient backgrounds', () => {
      render(<TransitionPanel />);

      expect(screen.getByText('Shot 1')).toBeInTheDocument();
      expect(screen.getByText('Shot 2')).toBeInTheDocument();
    });

    it('should display preview help text', () => {
      render(<TransitionPanel />);

      expect(screen.getByText('Click "Play Preview" to see how the transition will look')).toBeInTheDocument();
    });

    it('should disable play button when playing', () => {
      render(<TransitionPanel />);

      const playButton = screen.getByRole('button', { name: /Play Preview/i });
      fireEvent.click(playButton);

      // Button should show "Playing..." and be disabled
      expect(screen.getByRole('button', { name: /Playing.../i })).toBeDisabled();
    });
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import { WaveformDisplay, generateWaveformData } from '../WaveformDisplay';
import type { AudioTrack } from '../../types';

// Mock AudioContext
class MockAudioContext {
  decodeAudioData = vi.fn();
  close = vi.fn().mockResolvedValue(undefined);
}

class MockAudioBuffer {
  length = 44100;
  numberOfChannels = 2;
  sampleRate = 44100;
  duration = 1;
  
  getChannelData(channel: number): Float32Array {
    // Return mock audio data (sine wave)
    const data = new Float32Array(this.length);
    for (let i = 0; i < this.length; i++) {
      data[i] = Math.sin((i / this.length) * Math.PI * 2) * 0.5;
    }
    return data;
  }
  
  copyFromChannel = vi.fn();
  copyToChannel = vi.fn();
}

describe('WaveformDisplay', () => {
  let mockAudioContext: MockAudioContext;
  let originalAudioContext: any;

  beforeEach(() => {
    mockAudioContext = new MockAudioContext();
    originalAudioContext = (window as any).AudioContext;
    (window as any).AudioContext = vi.fn(() => mockAudioContext);
    
    // Mock fetch
    global.fetch = vi.fn().mockResolvedValue({
      ok: true,
      arrayBuffer: () => Promise.resolve(new ArrayBuffer(8)),
    });
    
    // Mock decodeAudioData to return mock audio buffer
    mockAudioContext.decodeAudioData.mockResolvedValue(new MockAudioBuffer());
  });

  afterEach(() => {
    (window as any).AudioContext = originalAudioContext;
    vi.clearAllMocks();
  });

  const createMockTrack = (overrides?: Partial<AudioTrack>): AudioTrack => ({
    id: 'track-1',
    name: 'Test Track',
    type: 'music',
    url: 'https://example.com/audio.mp3',
    startTime: 0,
    duration: 10,
    offset: 0,
    volume: 80,
    fadeIn: 0,
    fadeOut: 0,
    pan: 0,
    muted: false,
    solo: false,
    effects: [],
    ...overrides,
  });

  it('renders canvas element', () => {
    const track = createMockTrack();
    render(<WaveformDisplay track={track} />);
    
    const canvas = screen.getByRole('img', { hidden: true }) || document.querySelector('canvas');
    expect(canvas).toBeTruthy();
  });

  it('uses provided width and height', () => {
    const track = createMockTrack();
    render(<WaveformDisplay track={track} width={400} height={80} />);
    
    const canvas = document.querySelector('canvas');
    expect(canvas?.width).toBe(400);
    expect(canvas?.height).toBe(80);
  });

  it('uses default width and height when not provided', () => {
    const track = createMockTrack();
    render(<WaveformDisplay track={track} />);
    
    const canvas = document.querySelector('canvas');
    expect(canvas?.width).toBe(300);
    expect(canvas?.height).toBe(60);
  });

  it('displays placeholder when no URL or waveform data', () => {
    const track = createMockTrack({ url: '', waveformData: undefined });
    render(<WaveformDisplay track={track} />);
    
    const canvas = document.querySelector('canvas');
    expect(canvas).toBeTruthy();
  });

  it('generates waveform when URL is provided', async () => {
    const track = createMockTrack();
    const onGenerate = vi.fn();
    
    render(<WaveformDisplay track={track} onGenerate={onGenerate} />);
    
    await waitFor(() => {
      expect(global.fetch).toHaveBeenCalledWith(track.url);
    });
    
    await waitFor(() => {
      expect(mockAudioContext.decodeAudioData).toHaveBeenCalled();
    });
    
    await waitFor(() => {
      expect(onGenerate).toHaveBeenCalled();
    });
  });

  it('uses existing waveform data when available', () => {
    const waveformData = [0.1, 0.5, 0.8, 0.3, 0.6];
    const track = createMockTrack({ waveformData });
    
    render(<WaveformDisplay track={track} />);
    
    // Should not fetch audio file
    expect(global.fetch).not.toHaveBeenCalled();
  });

  it('displays loading state while generating', async () => {
    const track = createMockTrack();
    
    // Make decodeAudioData take time
    mockAudioContext.decodeAudioData.mockImplementation(
      () => new Promise((resolve) => setTimeout(() => resolve(new MockAudioBuffer()), 100))
    );
    
    render(<WaveformDisplay track={track} />);
    
    // Should show loading state
    await waitFor(() => {
      expect(screen.getByText(/generating waveform/i)).toBeTruthy();
    });
  });

  it('displays error when fetch fails', async () => {
    const track = createMockTrack();
    
    // Mock fetch to fail
    global.fetch = vi.fn().mockResolvedValue({
      ok: false,
      status: 404,
    });
    
    render(<WaveformDisplay track={track} />);
    
    await waitFor(() => {
      expect(screen.getByText(/failed to generate waveform/i)).toBeTruthy();
    });
  });

  it('displays error when audio decoding fails', async () => {
    const track = createMockTrack();
    
    // Mock decodeAudioData to fail
    mockAudioContext.decodeAudioData.mockRejectedValue(new Error('Decode error'));
    
    render(<WaveformDisplay track={track} />);
    
    await waitFor(() => {
      expect(screen.getByText(/failed to generate waveform/i)).toBeTruthy();
    });
  });

  it('calls onGenerate callback with waveform data', async () => {
    const track = createMockTrack();
    const onGenerate = vi.fn();
    
    render(<WaveformDisplay track={track} onGenerate={onGenerate} />);
    
    await waitFor(() => {
      expect(onGenerate).toHaveBeenCalled();
    });
    
    const waveformData = onGenerate.mock.calls[0][0];
    expect(Array.isArray(waveformData)).toBe(true);
    expect(waveformData.length).toBeGreaterThan(0);
    expect(waveformData.every((v: number) => v >= 0 && v <= 1)).toBe(true);
  });

  it('closes audio context after generating waveform', async () => {
    const track = createMockTrack();
    
    render(<WaveformDisplay track={track} />);
    
    await waitFor(() => {
      expect(mockAudioContext.close).toHaveBeenCalled();
    });
  });
});

describe('generateWaveformData', () => {
  let mockAudioContext: MockAudioContext;
  let originalAudioContext: any;

  beforeEach(() => {
    mockAudioContext = new MockAudioContext();
    originalAudioContext = (window as any).AudioContext;
    (window as any).AudioContext = vi.fn(() => mockAudioContext);
    
    global.fetch = vi.fn().mockResolvedValue({
      ok: true,
      arrayBuffer: () => Promise.resolve(new ArrayBuffer(8)),
    });
    
    mockAudioContext.decodeAudioData.mockResolvedValue(new MockAudioBuffer());
  });

  afterEach(() => {
    (window as any).AudioContext = originalAudioContext;
    vi.clearAllMocks();
  });

  it('generates waveform data from audio URL', async () => {
    const audioUrl = 'https://example.com/audio.mp3';
    const waveformData = await generateWaveformData(audioUrl, 100);
    
    expect(Array.isArray(waveformData)).toBe(true);
    expect(waveformData.length).toBe(100);
    expect(waveformData.every((v) => v >= 0 && v <= 1)).toBe(true);
  });

  it('normalizes waveform data to 0-1 range', async () => {
    const audioUrl = 'https://example.com/audio.mp3';
    const waveformData = await generateWaveformData(audioUrl);
    
    const max = Math.max(...waveformData);
    expect(max).toBeLessThanOrEqual(1);
    expect(max).toBeGreaterThan(0);
  });

  it('uses default sample count when not provided', async () => {
    const audioUrl = 'https://example.com/audio.mp3';
    const waveformData = await generateWaveformData(audioUrl);
    
    expect(waveformData.length).toBe(1000);
  });

  it('throws error when fetch fails', async () => {
    global.fetch = vi.fn().mockResolvedValue({
      ok: false,
      status: 404,
    });
    
    const audioUrl = 'https://example.com/audio.mp3';
    
    await expect(generateWaveformData(audioUrl)).rejects.toThrow();
  });

  it('closes audio context even when error occurs', async () => {
    mockAudioContext.decodeAudioData.mockRejectedValue(new Error('Decode error'));
    
    const audioUrl = 'https://example.com/audio.mp3';
    
    try {
      await generateWaveformData(audioUrl);
    } catch (error) {
      // Expected to throw
    }
    
    expect(mockAudioContext.close).toHaveBeenCalled();
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import {
  FocusTrap,
  SkipLink,
  LiveRegion,
  AlertRegion,
  AnnouncementProvider,
  useAnnouncements,
  KeyboardShortcuts,
  AccessibleDialog,
  AccessibleTabs,
  Tooltip,
  HighContrastMode,
  ReducedMotion,
} from '../index';

// Test component for AnnouncementProvider
function TestAnnouncementComponent() {
  const { announce } = useAnnouncements();
  return (
    <div>
      <button onClick={() => announce('Test announcement')}>Announce</button>
      <button onClick={() => announce('Urgent announcement', 'assertive')}>Announce Urgent</button>
    </div>
  );
}

describe('Accessibility Components', () => {
  describe('FocusTrap', () => {
    it('should trap focus within the container', () => {
      render(
        <FocusTrap active={true}>
          <button>First</button>
          <button>Second</button>
        </FocusTrap>
      );

      const buttons = screen.getAllByRole('button');
      expect(buttons).toHaveLength(2);
    });

    it('should not trap focus when inactive', () => {
      render(
        <FocusTrap active={false}>
          <button>First</button>
        </FocusTrap>
      );

      expect(screen.getByText('First')).toBeInTheDocument();
    });
  });

  describe('SkipLink', () => {
    it('should render as a hidden link', () => {
      render(<SkipLink target="main-content">Skip to main content</SkipLink>);

      const link = screen.getByText('Skip to main content');
      expect(link).toHaveAttribute('href', '#main-content');
      expect(link).toHaveClass('sr-only');
    });
  });

  describe('LiveRegion', () => {
    it('should render with proper ARIA attributes', () => {
      render(<LiveRegion message="Test message" />);

      const region = screen.getByRole('status');
      expect(region).toHaveTextContent('Test message');
      expect(region).toHaveAttribute('aria-live', 'polite');
    });

    it('should support assertive politeness', () => {
      render(<LiveRegion message="Important" politeness="assertive" />);

      const region = screen.getByRole('status');
      expect(region).toHaveAttribute('aria-live', 'assertive');
