  describe('AnnouncementProvider', () => {
    it('should provide announce function to children', () => {
      render(
        <AnnouncementProvider>
          <TestAnnouncementComponent />
        </AnnouncementProvider>
      );

      const button = screen.getByText('Announce');
      fireEvent.click(button);

