import React, { useEffect, useCallback, useRef } from 'react';
import { cn } from '@/lib/utils';

// ============================================================================
// Accessibility Utilities & Components
// Conformit├® WCAG 2.2 AA
// ============================================================================

// ============================================================================
// Focus Management
// ============================================================================

interface FocusTrapProps {
  children: React.ReactNode;
  active?: boolean;
  className?: string;
}

/**
 * Focus Trap - Emp├¬che la navigation clavier de sortir du composant
 */
export function FocusTrap({ children, active = true, className }: FocusTrapProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!active) return;

    const container = containerRef.current;
    if (!container) return;

    const focusableElements = container.querySelectorAll<HTMLElement>(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    );

    const firstFocusable = focusableElements[0];
    const lastFocusable = focusableElements[focusableElements.length - 1];

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key !== 'Tab') return;

      if (e.shiftKey) {
        if (document.activeElement === firstFocusable) {
          e.preventDefault();
          lastFocusable?.focus();
        }
      } else {
        if (document.activeElement === lastFocusable) {
          e.preventDefault();
          firstFocusable?.focus();
        }
      }
    };

    container.addEventListener('keydown', handleKeyDown);
    firstFocusable?.focus();

    return () => {
      container.removeEventListener('keydown', handleKeyDown);
    };
  }, [active]);

  return (
    <div ref={containerRef} className={className}>
      {children}
    </div>
  );
}

// ============================================================================
// Skip Link Component
// ============================================================================

interface SkipLinkProps {
  target: string;
  children?: React.ReactNode;
  className?: string;
}

export function SkipLink({ target, children, className }: SkipLinkProps) {
  return (
    <a
      href={`#${target}`}
      className={cn(
        'sr-only focus:not-sr-only',
        'focus:absolute focus:top-4 focus:left-4 focus:z-50',
        'focus:bg-primary focus:text-primary-foreground focus:px-4 focus:py-2',
        'focus:rounded-md focus:outline-none focus:ring-2 focus:ring-primary',
        className
      )}
    >
      {children || 'Aller au contenu principal'}
    </a>
  );
}

// ============================================================================
// Live Region Announcer
// ============================================================================

interface LiveRegionProps {
  message: string;
  politeness?: 'polite' | 'assertive';
  atomic?: boolean;
  className?: string;
}

/**
 * Region ARIA live pour les annonces aux screen readers
 */
export function LiveRegion({
  message,
  politeness = 'polite',
  atomic = true,
  className,
}: LiveRegionProps) {
  return (
    <div
      role="status"
      aria-live="polite"
      aria-atomic={atomic ? 'true' : 'false'}
      className={cn('sr-only', className)}
    >
      {message}
    </div>
  );
}

/**
 * Annonce urgente (erreur, avertissement)
 */
export function AlertRegion({ message, className }: { message: string; className?: string }) {
  return (
    <div
      role="alert"
      aria-live="assertive"
