  const [newCharacterArchetype, setNewCharacterArchetype] = useState('hero');
  const [newCharacterName, setNewCharacterName] = useState('');

  // Dialogue configuration
  const addCharacter = () => {
    
    const characters = data.dialogueCharacters || [];
    onUpdate?.({
      dialogueCharacters: [
        ...characters,
