          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
            <div>
              <label style={styles.label}>Style</label>
              <select
                style={styles.select}
                value={data.promptStyle || 'realistic'}
                onChange={(e) => onUpdate({ promptStyle: e.target.value })}
