export const AutomationWizard: React.FC<AutomationWizardProps> = ({
  isOpen,
  onClose,
  onComplete,
  projectId,
  initialData,
  className,
}) => {
  // State
  const [currentStep, setCurrentStep] = useState(1);
  const [completedSteps, setCompletedSteps] = useState<number[]>([]);
  const [stepStates, setStepStates] = useState<Record<number, StepState>>({});
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [wizardData, setWizardData] = useState<Partial<AutomationWizardData>>({
    automationType: 'dialogue',
    dialogueCharacters: [],
    dialogueContext: {
      location: '',
      time_of_day: 'day',
      situation: 'neutral',
      mood: 'neutral',
    },
    numLines: 10,
    gridSize: '3x3',
    gridPoses: ['standing', 'walking', 'fighting', 'casting'],
    gridExpressions: ['neutral', 'happy', 'angry', 'determined'],
    promptStyle: 'realistic',
    promptLighting: 'cinematic',
    promptMood: 'neutral',
    ...initialData,
  });

  // Update data helper
  const updateData = useCallback((data: Partial<AutomationWizardData>) => {
    setWizardData(prev => ({ ...prev, ...data }));
    setError(null);
  }, []);

  // Validation
  const validateStep = useCallback((step: number): { valid: boolean; errors?: Record<string, string[]> } => {
    const errors: Record<string, string[]> = {};

    if (step === 1) {
      if (!wizardData.automationType) {
        errors.type = ['Please select an automation type'];
      }
    }

    if (step === 2) {
      if (wizardData.automationType === 'dialogue') {
        if (!wizardData.dialogueCharacters || wizardData.dialogueCharacters.length === 0) {
          errors.characters = ['Add at least one character'];
        }
        if (!wizardData.dialogueContext?.location) {
          errors.context = ['Please specify a location'];
        }
      }

      if (wizardData.automationType === 'grid') {
        if (!wizardData.gridCharacterId || !wizardData.gridCharacterName) {
          errors.character = ['Please specify character ID and name'];
        }
      }

      if (wizardData.automationType === 'prompt') {
        if (!wizardData.basePrompt || wizardData.basePrompt.trim().length < 10) {
          errors.prompt = ['Please enter a prompt (at least 10 characters)'];
        }
      }
    }

    return {
      valid: Object.keys(errors).length === 0,
      errors: Object.keys(errors).length > 0 ? errors : undefined,
    };
  }, [wizardData]);

  // Navigation
  const canGoNext = useMemo(() => {
    const result = validateStep(currentStep);
    return result.valid;
  }, [currentStep, validateStep]);

  const canGoPrevious = currentStep > 1;

  const handleNext = useCallback(() => {
    const result = validateStep(currentStep);
    
    if (!result.valid) {
      setError(Object.values(result.errors || {}).flat().join('. '));
      return;
    }

    setStepStates(prev => ({
      ...prev,
      [currentStep]: { status: 'valid' },
    }));

    if (!completedSteps.includes(currentStep)) {
      setCompletedSteps(prev => [...prev, currentStep]);
    }

    if (currentStep < WIZARD_STEPS.length) {
      setCurrentStep(currentStep + 1);
    }
  }, [currentStep, validateStep, completedSteps]);

  const handlePrevious = useCallback(() => {
    if (currentStep > 1) {
      setCurrentStep(currentStep - 1);
    }
  }, [currentStep]);

  const handleGoToStep = useCallback((step: number) => {
    if (step <= currentStep || completedSteps.includes(step - 1)) {
      setCurrentStep(step);
    }
  }, [currentStep, completedSteps]);

  // Generate content
  const handleGenerate = useCallback(async () => {
    setIsGenerating(true);
    setError(null);

    try {
      if (wizardData.automationType === 'dialogue') {
        const result = await automationService.generateDialogue({
          characters: wizardData.dialogueCharacters || [],
          context: wizardData.dialogueContext || {
            location: 'Unknown',
            time_of_day: 'day',
            situation: 'neutral',
            mood: 'neutral',
          },
          dialogueType: 'conversation',
          numLines: wizardData.numLines || 10,
        });
        updateData({ generatedDialogue: result });
      }

      if (wizardData.automationType === 'grid') {
        const result = await automationService.generateCharacterGrid({
          characterId: wizardData.gridCharacterId || '',
          characterName: wizardData.gridCharacterName || '',
          gridSize: wizardData.gridSize,
          poses: wizardData.gridPoses,
          expressions: wizardData.gridExpressions,
        });
        updateData({ generatedGrid: result });
      }

      if (wizardData.automationType === 'prompt') {
        const result = await automationService.enhancePrompt({
          base_prompt: wizardData.basePrompt || '',
          style: wizardData.promptStyle as 'realistic' | 'anime' | 'fantasy' | 'science_fiction' | 'oil_painting' | 'watercolor' | 'photographic' | 'cyberpunk' | 'gothic' | 'minimalist',
          lighting: wizardData.promptLighting as 'cinematic' | 'natural' | 'dramatic' | 'soft' | 'volumetric' | 'neon' | 'golden_hour' | 'blue_hour',
          mood: wizardData.promptMood as 'neutral' | 'tense' | 'peaceful' | 'mysterious' | 'epic' | 'joyful' | 'somber' | 'horror' | 'romantic' | 'dreamy',
        });
        updateData({ enhancedPrompt: result });
      }

      // Move to results step
      setCompletedSteps(prev => [...prev, 3]);
      setCurrentStep(4);
    } catch (err: unknown) {
      const errorMessage = err instanceof Error ? err.message : 'Generation failed';
      setError(errorMessage);
    } finally {
      setIsGenerating(false);
    }
  }, [wizardData, updateData]);

  // Export results
  const handleExport = useCallback(() => {
    const dataStr = JSON.stringify(wizardData, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `automation-${wizardData.automationType}-${Date.now()}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    
    onComplete?.(wizardData as AutomationWizardData);
  }, [wizardData, onComplete]);

  // Handle complete
  const handleComplete = useCallback(() => {
    onComplete?.(wizardData as AutomationWizardData);
    onClose();
  }, [wizardData, onComplete, onClose]);

  // Render current step
  const renderStep = () => {
    switch (currentStep) {
      case 1:
        return (
          <Step1SelectType
            data={wizardData}
            onUpdate={updateData}
          />
        );
      case 2:
        return (
          <Step2Configure
            data={wizardData}
            onUpdate={updateData}
            errors={validateStep(currentStep).errors}
          />
        );
      case 3:
        return (
          <Step3Preview
            data={wizardData}
            onUpdate={updateData}
            onGenerate={handleGenerate}
            isGenerating={isGenerating}
          />
        );
      case 4:
        return (
          <Step4Results
            data={wizardData}
            onUpdate={updateData}
            onExport={handleExport}
          />
        );
      default:
        return null;
    }
  };

  // Handle escape key
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isOpen) {
        onClose();
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  return (
    <div style={styles.overlay} onClick={onClose}>
      <div
        style={styles.container}
        className={className}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div style={styles.header}>
          <h2 style={styles.title}>Automation Wizard</h2>
          <button style={styles.closeButton} onClick={onClose} aria-label="Close">
            ├ù
          </button>
        </div>

        {/* Step Indicator */}
        <div style={styles.stepIndicator}>
          <WizardStepIndicator
            steps={WIZARD_STEPS}
            currentStep={currentStep}
            stepStates={stepStates}
            onStepClick={handleGoToStep}
            allowJumpToStep={false}
          />
        </div>

        {/* Error Display */}
        {error && (
          <div style={{ padding: '0 24px' }}>
            <div style={styles.error}>{error}</div>
          </div>
        )}

        {/* Content */}
        <div style={styles.content}>
          {isGenerating ? (
            <div style={styles.loading}>
              <div style={styles.spinner} />
              <span>Generating content...</span>
            </div>
          ) : (
            renderStep()
          )}
        </div>

        {/* Footer */}
        <div style={styles.footer}>
          <WizardNavigation
            currentStep={currentStep}
            totalSteps={WIZARD_STEPS.length}
            canGoNext={canGoNext && !isGenerating}
            canGoBack={canGoPrevious && !isGenerating}
            onNext={currentStep === 3 ? () => {} : handleNext}
            onBack={handlePrevious}
            onSubmit={currentStep === 4 ? handleComplete : undefined}
            onCancel={onClose}
            canSkip={false}
            onSkip={() => {}}
            onSaveDraft={() => {}}
          />
        </div>
      </div>

      {/* CSS Animation for spinner */}
      <style>
        {`
          @keyframes spin {
            from { transform: rotate(0deg); }
            to { transform: rotate(360deg); }
          }
        `}
      </style>
    </div>
  );
};

export default AutomationWizard;

/**
 * BatchOperationsToolbar - Barre d'outils pour op├®rations par lots
 * 
 * Affiche une barre d'outils contextuelle lors de s├®lection multiple avec:
 * - Boutons d'op├®rations (Duplicate, Delete, Export, Transform, Tag)
 * - Barre de progression pendant le traitement
 * - Rapport d'erreurs en cas d'├®chec partiel
 * 
 * Exigences: 8.1, 8.5, 8.6
 */

import React, { useState, useMemo, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import type { ProductionShot, BatchOperationType, BatchOperationResult } from '../../types';
import { BatchOperationsManager, type BatchOperationOptions } from '../../services/batchOperations';
import {
  Copy,
  Trash2,
  Download,
  Wand2,
  Tag,
  X,
  AlertCircle,
  CheckCircle,
  Loader2
} from 'lucide-react';

/**
 * Convertit un ProductionShot en Shot pour les op├®rations batch
 * Note: Utilise le type Shot de index.ts (pas celui de shot.ts)
 */
const productionShotToShot = (productionShot: ProductionShot): import('../../types').Shot => ({
  id: productionShot.id,
  title: `Shot ${productionShot.number}`,
  description: productionShot.notes || '',
  duration: productionShot.timing.duration / 24, // Convert frames to seconds (assuming 24fps)
  image: productionShot.thumbnailUrl,
  audioTracks: [],
  effects: [],
  textLayers: [],
  animations: [],
  position: productionShot.number,
  metadata: {
    sequencePlanId: productionShot.sequencePlanId,
    sceneId: productionShot.sceneId,
    status: productionShot.status,
    tags: productionShot.tags,
    type: productionShot.type,
    timing: productionShot.timing
  }
});

/**
 * Props du composant
 */
export interface BatchOperationsToolbarProps {
  selectedShots: ProductionShot[];
  onOperationComplete?: (result: BatchOperationResult) => void;
  onClose?: () => void;
  estimatedTime?: number;
}

/**
 * ├ëtat de l'op├®ration en cours
 */
interface OperationState {
  type: BatchOperationType;
  progress: number;
  isRunning: boolean;
  result?: BatchOperationResult;
  error?: Error;
}

/**
 * Barre d'outils pour op├®rations par lots
 * Exigence: 8.1 - Affichage lors de s├®lection multiple
 * Exigence: 8.5 - Support des op├®rations
 * Exigence: 8.6 - Rapport d'erreurs
 */
export const BatchOperationsToolbar: React.FC<BatchOperationsToolbarProps> = ({
  selectedShots,
  onOperationComplete,
  onClose,
  estimatedTime
}) => {
  const [operationState, setOperationState] = useState<OperationState | null>(null);
  const [showErrorReport, setShowErrorReport] = useState(false);
  
  // Cr├®er le gestionnaire d'op├®rations (use useState to avoid constructor issues)
  const [manager] = useState(() => new BatchOperationsManager());
  
  /**
   * Ex├®cute une op├®ration
   * Exigence: 8.5 - Support des op├®rations
   */
  const handleOperation = useCallback(async (
    type: BatchOperationType,
    options: BatchOperationOptions = {}
  ) => {
    setOperationState({
      type,
      progress: 0,
      isRunning: true
    });
    
    try {
      const convertedShots = selectedShots.map(productionShotToShot);
      const result = await manager.execute(type, convertedShots, options);
      
      setOperationState({
        type,
        progress: 100,
        isRunning: false,
        result
      });
      
      // Notifier le parent
      onOperationComplete?.(result);
      
      // Afficher le rapport d'erreurs si n├®cessaire
      if (result.failed.length > 0) {
        setShowErrorReport(true);
      } else {
        // Fermer automatiquement apr├¿s succ├¿s complet
        setTimeout(() => {
          setOperationState(null);
        }, 2000);
      }
      
    } catch (error) {
      setOperationState({
        type,
        progress: 0,
        isRunning: false,
        error: error as Error
      });
    }
  }, [manager, selectedShots, onOperationComplete]);
  
  /**
   * Annule l'op├®ration en cours
   */
  const handleCancel = useCallback(() => {
    if (operationState?.isRunning) {
      // Annuler via le gestionnaire
      // Note: n├®cessite l'ID de l'op├®ration, ├á impl├®menter
      setOperationState(null);
    }
  }, [operationState]);
  
  /**
   * Ferme la barre d'outils
   */
  const handleClose = useCallback(() => {
    setOperationState(null);
    setShowErrorReport(false);
    onClose?.();
  }, [onClose]);
  
  /**
   * Formate le temps estim├®
   */
  const formatEstimatedTime = (ms: number): string => {
    if (ms < 1000) {
      return `${ms}ms`;
    } else if (ms < 60000) {
      return `${Math.ceil(ms / 1000)}s`;
    } else {
      const minutes = Math.floor(ms / 60000);
      const seconds = Math.ceil((ms % 60000) / 1000);
      return `${minutes}m ${seconds}s`;
    }
  };
  
  /**
   * Obtient l'estimation de temps pour une op├®ration
   */
  const getEstimatedTime = (type: BatchOperationType): string => {
    if (estimatedTime) {
      return formatEstimatedTime(estimatedTime);
    }
    const estimated = manager.estimateTime(type, selectedShots.length);
    return formatEstimatedTime(estimated);
  };
  
  return (
    <AnimatePresence>
      <motion.div
        className="batch-operations-toolbar"
        initial={{ y: -20, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        exit={{ y: -20, opacity: 0 }}
        transition={{ duration: 0.2 }}
      >
        <div className="toolbar-content">
          {/* En-t├¬te */}
          <div className="toolbar-header">
            <span className="selection-count">
              {selectedShots.length} plan{selectedShots.length > 1 ? 's' : ''} s├®lectionn├®{selectedShots.length > 1 ? 's' : ''}
            </span>
            <button
              className="close-button"
              onClick={handleClose}
              aria-label="Fermer"
            >
              <X size={16} />
            </button>
          </div>
          
          {/* Boutons d'op├®rations */}
          {!operationState && (
            <div className="toolbar-actions">
              <button
                className="action-button"
                onClick={() => handleOperation('duplicate')}
                title={`Dupliquer (Ôëê${getEstimatedTime('duplicate')})`}
              >
                <Copy size={18} />
                <span>Dupliquer</span>
              </button>
              
              <button
                className="action-button danger"
                onClick={() => {
                  if (selectedShots.length > 5) {
                    if (confirm(`├ètes-vous s├╗r de vouloir supprimer ${selectedShots.length} plans ?`)) {
                      handleOperation('delete');
                    }
                  } else {
                    handleOperation('delete');
                  }
                }}
                title={`Supprimer (Ôëê${getEstimatedTime('delete')})`}
              >
                <Trash2 size={18} />
                <span>Supprimer</span>
              </button>
              
              <button
                className="action-button"
                onClick={() => handleOperation('export')}
                title={`Exporter (Ôëê${getEstimatedTime('export')})`}
              >
                <Download size={18} />
                <span>Exporter</span>
              </button>
              
              <button
                className="action-button"
                onClick={() => handleOperation('transform')}
                title={`Transformer (Ôëê${getEstimatedTime('transform')})`}
              >
                <Wand2 size={18} />
                <span>Transformer</span>
              </button>
              
              <button
                className="action-button"
                onClick={() => handleOperation('tag')}
                title={`Ajouter des tags (Ôëê${getEstimatedTime('tag')})`}
              >
                <Tag size={18} />
                <span>Tags</span>
              </button>
            </div>
          )}
          
          {/* Progression */}
          {operationState?.isRunning && (
            <div className="toolbar-progress">
              <div className="progress-header">
                <span className="progress-label">
                  {operationState.type === 'duplicate' && 'Duplication en cours...'}
                  {operationState.type === 'delete' && 'Suppression en cours...'}
                  {operationState.type === 'export' && 'Export en cours...'}
                  {operationState.type === 'transform' && 'Transformation en cours...'}
                  {operationState.type === 'tag' && 'Ajout de tags en cours...'}
                </span>
                <button
                  className="cancel-button"
                  onClick={handleCancel}
                  aria-label="Annuler"
                >
                  <X size={14} />
                </button>
              </div>
              
              <div className="progress-bar-container">
                <div
                  className="progress-bar"
                  style={{ width: `${operationState.progress}%` }}
                />
              </div>
              
              <div className="progress-info">
                <span>{Math.round(operationState.progress)}%</span>
                <Loader2 size={14} className="spinner" />
              </div>
            </div>
          )}
          
          {/* R├®sultat */}
          {operationState && !operationState.isRunning && operationState.result && (
            <div className="toolbar-result">
              {operationState.result.failed.length === 0 ? (
                <div className="result-success">
                  <CheckCircle size={18} className="success-icon" />
                  <span>
                    {operationState.result.success.length} plan{operationState.result.success.length > 1 ? 's' : ''} trait├®{operationState.result.success.length > 1 ? 's' : ''} avec succ├¿s
                  </span>
                  <span className="result-time">
                    ({formatEstimatedTime(operationState.result.totalTime)})
                  </span>
                </div>
              ) : (
                <div className="result-partial">
                  <AlertCircle size={18} className="warning-icon" />
                  <span>
                    {operationState.result.success.length} succ├¿s, {operationState.result.failed.length} ├®chec{operationState.result.failed.length > 1 ? 's' : ''}
                  </span>
                  <button
                    className="view-errors-button"
                    onClick={() => setShowErrorReport(true)}
                  >
                    Voir les erreurs
                  </button>
                </div>
              )}
            </div>
          )}
          
          {/* Erreur */}
          {operationState && !operationState.isRunning && operationState.error && (
            <div className="toolbar-error">
              <AlertCircle size={18} className="error-icon" />
              <span>Erreur: {operationState.error.message}</span>
            </div>
          )}
        </div>
        
        {/* Rapport d'erreurs */}
        <AnimatePresence>
          {showErrorReport && operationState?.result && (
            <motion.div
              className="error-report-overlay"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setShowErrorReport(false)}
            >
              <motion.div
                className="error-report"
                initial={{ scale: 0.9, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                exit={{ scale: 0.9, opacity: 0 }}
                onClick={(e) => e.stopPropagation()}
              >
                <div className="error-report-header">
                  <h3>Rapport d'erreurs</h3>
                  <button
                    className="close-button"
                    onClick={() => setShowErrorReport(false)}
                    aria-label="Fermer"
                  >
                    <X size={18} />
                  </button>
                </div>
                
                <div className="error-report-content">
                  <p className="error-summary">
                    {operationState.result.failed.length} plan{operationState.result.failed.length > 1 ? 's' : ''} n'ont pas pu ├¬tre trait├®{operationState.result.failed.length > 1 ? 's' : ''}:
                  </p>
                  
                  <ul className="error-list">
                    {operationState.result.failed.map((failure, index) => (
                      <li key={index} className="error-item">
                        <strong>{`Shot ${failure.shot.number}`}</strong>
                        <span className="error-message">{failure.error.message}</span>
                      </li>
                    ))}
                  </ul>
                </div>
                
                <div className="error-report-footer">
                  <button
                    className="retry-button"
                    onClick={() => {
                      setShowErrorReport(false);
                      // R├®essayer avec les plans ├®chou├®s
                      handleOperation(operationState.type, {});
                    }}
                  >
                    R├®essayer les ├®checs
                  </button>
                  <button
                    className="close-button-secondary"
                    onClick={() => setShowErrorReport(false)}
                  >
                    Fermer
                  </button>
                </div>
              </motion.div>
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>
    </AnimatePresence>
  );
};

/**
 * BulkMetadataEditor - ├ëditeur de m├®tadonn├®es group├®es
 * 
 * Permet l'├®dition de m├®tadonn├®es pour plusieurs plans simultan├®ment:
 * - Interface d'├®dition group├®e
 * - Pr├®visualisation des changements
 * - Application ├á tous les plans s├®lectionn├®s
 * 
 * Exigence: 8.3 - ├ëdition group├®e de m├®tadonn├®es
 */

import React, { useState, useMemo, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import type { Shot } from '../../types';
import { X, Eye, Check, AlertCircle } from 'lucide-react';

/**
 * Props du composant
 */
export interface BulkMetadataEditorProps {
  selectedShots: Shot[];
  onApply: (updates: Partial<Shot>) => void;
  onCancel: () => void;
}

/**
 * Champs de m├®tadonn├®es ├®ditables
 */
interface MetadataField {
  key: keyof Shot | string;
  label: string;
  type: 'text' | 'number' | 'select' | 'tags';
  options?: string[];
  placeholder?: string;
}

/**
 * Changements de m├®tadonn├®es
 */
interface MetadataChanges {
  [key: string]: unknown;
}

/**
 * ├ëditeur de m├®tadonn├®es group├®es
 * Exigence: 8.3 - ├ëdition group├®e avec pr├®visualisation
 */
export const BulkMetadataEditor: React.FC<BulkMetadataEditorProps> = ({
  selectedShots,
  onApply,
  onCancel
}) => {
  const [changes, setChanges] = useState<MetadataChanges>({});
  const [showPreview, setShowPreview] = useState(false);
  const [previewIndex, setPreviewIndex] = useState(0);

  /**
   * Champs de m├®tadonn├®es disponibles
   */
  const fields: MetadataField[] = useMemo(() => [
    {
      key: 'title',
      label: 'Titre',
      type: 'text',
      placeholder: 'Nouveau titre...'
    },
    {
      key: 'description',
      label: 'Description',
      type: 'text',
      placeholder: 'Nouvelle description...'
    },
    {
      key: 'duration',
      label: 'Dur├®e (secondes)',
      type: 'number',
      placeholder: '0'
    },
    {
      key: 'metadata.category',
      label: 'Cat├®gorie',
      type: 'select',
      options: ['Action', 'Dialogue', 'Transition', 'Establishing', 'Close-up']
    },
    {
      key: 'metadata.tags',
      label: 'Tags',
      type: 'tags',
      placeholder: 'Ajouter des tags...'
    }
  ], []);

  /**
   * Valeurs communes entre les plans s├®lectionn├®s
   */
  const commonValues = useMemo(() => {
    const values: Record<string, unknown> = {};

    for (const field of fields) {
      const fieldValues = selectedShots.map(shot => {
        if (field.key.includes('.')) {
          const [parent, child] = field.key.split('.');
          return (shot as any)[parent]?.[child];
        }
        return (shot as any)[field.key];
      });

      // V├®rifier si toutes les valeurs sont identiques
      const firstValue = fieldValues[0];
      const allSame = fieldValues.every(v =>
        JSON.stringify(v) === JSON.stringify(firstValue)
      );

      if (allSame) {
        values[field.key] = firstValue;
      } else {
        values[field.key] = null; // Valeurs mixtes
      }
    }

    return values;
  }, [selectedShots, fields]);

  /**
   * Met ├á jour un champ
   */
  const handleFieldChange = useCallback((key: string, value: unknown) => {
    setChanges(prev => ({
      ...prev,
      [key]: value
    }));
  }, []);

  /**
   * Applique les changements
   */
  const handleApply = useCallback(() => {
    const updates: Partial<Shot> = {};

    for (const [key, value] of Object.entries(changes)) {
      if (key.includes('.')) {
        const [parent, child] = key.split('.');
        if (!updates[parent as keyof Shot]) {
          (updates as any)[parent] = {};
        }
        (updates as any)[parent][child] = value;
      } else {
        (updates as any)[key] = value;
      }
    }

    onApply(updates);
  }, [changes, onApply]);

  /**
   * Pr├®visualise les changements sur un plan
   */
  const previewShot = useMemo(() => {
    if (!showPreview || selectedShots.length === 0) {
      return null;
    }

    const shot = selectedShots[previewIndex];
    const preview = { ...shot };

    for (const [key, value] of Object.entries(changes)) {
      if (key.includes('.')) {
        const [parent, child] = key.split('.');
        if (!preview[parent as keyof Shot]) {
          (preview as any)[parent] = {};
        }
        (preview as any)[parent][child] = value;
      } else {
        (preview as any)[key] = value;
      }
    }

    return preview;
  }, [showPreview, selectedShots, previewIndex, changes]);

  /**
   * Nombre de changements
   */
  const changeCount = Object.keys(changes).length;

  /**
   * Rend un champ d'├®dition
   */
  const renderField = (field: MetadataField) => {
    const currentValue = changes[field.key] ?? commonValues[field.key];
    const hasChange = field.key in changes;
    const isMixed = commonValues[field.key] === null && !hasChange;

    return (
      <div key={field.key} className={`metadata-field ${hasChange ? 'has-change' : ''}`}>
        <label className="field-label">
          {field.label}
          {isMixed && <span className="mixed-indicator">(Valeurs mixtes)</span>}
        </label>

        {field.type === 'text' && (
          <input
            type="text"
            className="field-input"
            value={(currentValue as any) || ''}
            onChange={(e) => handleFieldChange(field.key, e.target.value)}
            placeholder={field.placeholder}
          />
        )}

        {field.type === 'number' && (
          <input
            type="number"
            className="field-input"
            value={(currentValue as any) || ''}
            onChange={(e) => handleFieldChange(field.key, parseFloat(e.target.value))}
            placeholder={field.placeholder}
          />
        )}

        {field.type === 'select' && (
          <select
            className="field-select"
            value={(currentValue as any) || ''}
            onChange={(e) => handleFieldChange(field.key, e.target.value)}
          >
            <option value="">-- S├®lectionner --</option>
            {field.options?.map(option => (
              <option key={option} value={option}>
                {option}
              </option>
            ))}
          </select>
        )}

        {field.type === 'tags' && (
          <input
            type="text"
            className="field-input"
            value={Array.isArray(currentValue) ? currentValue.join(', ') : ''}
            onChange={(e) => {
              const tags = e.target.value.split(',').map(t => t.trim()).filter(Boolean);
              handleFieldChange(field.key, tags);
            }}
            placeholder={field.placeholder}
          />
        )}

        {hasChange && (
          <button
            className="reset-field-button"
            onClick={() => {
              setChanges(prev => {
                const next = { ...prev };
                delete next[field.key];
                return next;
              });
            }}
            title="R├®initialiser"
          >
            <X size={14} />
          </button>
        )}
      </div>
    );
  };

  return (
    <motion.div
      className="bulk-metadata-editor-overlay"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      onClick={onCancel}
    >
      <motion.div
        className="bulk-metadata-editor"
        initial={{ scale: 0.9, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        exit={{ scale: 0.9, opacity: 0 }}
        onClick={(e) => e.stopPropagation()}
      >
        {/* En-t├¬te */}
        <div className="editor-header">
          <div className="header-info">
            <h2>├ëdition group├®e</h2>
            <span className="selection-info">
              {selectedShots.length} plan{selectedShots.length > 1 ? 's' : ''} s├®lectionn├®{selectedShots.length > 1 ? 's' : ''}
            </span>
          </div>
          <button
            className="close-button"
            onClick={onCancel}
            aria-label="Fermer"
          >
            <X size={20} />
          </button>
        </div>

        {/* Contenu */}
        <div className="editor-content">
          {/* Champs d'├®dition */}
          <div className="fields-section">
            <h3>M├®tadonn├®es</h3>
            <div className="fields-list">
              {fields.map(renderField)}
            </div>
          </div>

          {/* Pr├®visualisation */}
          {showPreview && previewShot && (
            <div className="preview-section">
              <div className="preview-header">
                <h3>Pr├®visualisation</h3>
                <div className="preview-navigation">
                  <button
                    onClick={() => setPreviewIndex(Math.max(0, previewIndex - 1))}
                    disabled={previewIndex === 0}
                  >
                    ÔåÉ
                  </button>
                  <span>
                    {previewIndex + 1} / {selectedShots.length}
                  </span>
                  <button
                    onClick={() => setPreviewIndex(Math.min(selectedShots.length - 1, previewIndex + 1))}
                    disabled={previewIndex === selectedShots.length - 1}
                  >
                    ÔåÆ
                  </button>
                </div>
              </div>

              <div className="preview-content">
                <div className="preview-item">
                  <strong>Titre:</strong>
                  <span>{previewShot.title}</span>
                </div>
                <div className="preview-item">
                  <strong>Description:</strong>
                  <span>{previewShot.description}</span>
                </div>
                <div className="preview-item">
                  <strong>Dur├®e:</strong>
                  <span>{previewShot.duration}s</span>
                </div>
                {previewShot.metadata?.category && (
                  <div className="preview-item">
                    <strong>Cat├®gorie:</strong>
                    <span>{(previewShot.metadata as any).category}</span>
                  </div>
                )}
                {previewShot.metadata?.tags && (
                  <div className="preview-item">
                    <strong>Tags:</strong>
                    <span>{(previewShot.metadata as any).tags.join(', ')}</span>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>

        {/* Pied de page */}
        <div className="editor-footer">
          <div className="footer-info">
            {changeCount > 0 ? (
              <span className="change-count">
                <AlertCircle size={16} />
                {changeCount} changement{changeCount > 1 ? 's' : ''}
              </span>
            ) : (
              <span className="no-changes">Aucun changement</span>
            )}
          </div>

          <div className="footer-actions">
            <button
              className="preview-button"
              onClick={() => setShowPreview(!showPreview)}
              disabled={changeCount === 0}
            >
              <Eye size={16} />
              {showPreview ? 'Masquer' : 'Pr├®visualiser'}
            </button>

            <button
              className="cancel-button"
              onClick={onCancel}
            >
              Annuler
            </button>

            <button
              className="apply-button"
              onClick={handleApply}
              disabled={changeCount === 0}
            >
              <Check size={16} />
              Appliquer
            </button>
          </div>
        </div>
      </motion.div>
    </motion.div>
  );
};

/**
 * Unit tests for AnglePresetSelector Component
 * 
 * Tests for the camera angle preset selection component including:
 * - Rendering presets
 * - Selection state
 * - Select all/clear functionality
 * - Disabled state
 */

import React from 'react';
import { describe, it, expect, beforeEach, vi } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { AnglePresetSelector } from '../AnglePresetSelector';
import type { CameraAnglePresetMetadata, CameraAnglePreset } from '@/types/cameraAngle';

// Sample mock data matching actual types
