/**
 * Caption Styles Panel Component
 * MI2: Caption Styles - Modern, Classic, Dynamic
 */

import React, { useState, useEffect } from 'react';
import { useCaptionStyleStore } from '../../stores/captionStyleStore';
import { captionStylesService } from '../../services/CaptionStylesService';
import { CaptionStyle } from '../../types/caption-style';
import styles from './CaptionStylesPanel.module.css';

type StyleCategory = 'modern' | 'classic' | 'dynamic' | 'all';

export const CaptionStylesPanel: React.FC = () => {
  const {
    builtInStyles,
    userPresets,
    favoriteStyleIds,
    recentStyles,
    activeTrack,
    selectedStyleId,
    previewMode,
    isPanelOpen,
    isStyleEditorOpen,
    applyStyleToTrack,
    togglePanel,
    toggleStyleEditor,
    setPreviewMode,
    selectStyle,
  } = useCaptionStyleStore();

  const [activeCategory, setActiveCategory] = useState<StyleCategory>('all');
  const [previewText, setPreviewText] = useState('Hello, World!');
  const [selectedStyle, setSelectedStyle] = useState<CaptionStyle | null>(null);

  // Load built-in styles on mount
  useEffect(() => {
    captionStylesService.getAllStyles().forEach((style) => {
      useCaptionStyleStore.getState().registerBuiltInStyle(style);
    });
  }, []);

  // Combine built-in and user presets
  const allStyles = [...builtInStyles, ...userPresets.map((p) => ({
    ...p,
    id: p.styleId,
  } as CaptionStyle))];

  const filteredStyles = activeCategory === 'all'
    ? allStyles
    : allStyles.filter((s) => s.category === activeCategory);

  const handleStyleClick = (style: CaptionStyle) => {
    setSelectedStyle(style);
    selectStyle(style.id);
  };

  const handleApplyStyle = (style: CaptionStyle) => {
    if (activeTrack) {
      applyStyleToTrack(style.id, activeTrack.id);
    }
  };

  const toggleFavorite = (styleId: string) => {
    if (favoriteStyleIds.includes(styleId)) {
      useCaptionStyleStore.getState().removeFromFavorites(styleId);
    } else {
      useCaptionStyleStore.getState().addToFavorites(styleId);
    }
  };

  const categories = [
    { id: 'all', label: 'All', icon: '­ƒôØ' },
    { id: 'modern', label: 'Modern', icon: 'Ô£¿' },
    { id: 'classic', label: 'Classic', icon: '­ƒô£' },
    { id: 'dynamic', label: 'Dynamic', icon: '­ƒÄ¡' },
  ];

  if (!isPanelOpen) {
    return (
      <button className={styles.toggleButton} onClick={togglePanel}>
        ­ƒÆ¼ Captions
      </button>
    );
  }

  return (
    <div className={styles.panel}>
      <div className={styles.header}>
        <h3>Caption Styles</h3>
        <div className={styles.headerActions}>
          <button
            className={`${styles.actionBtn} ${previewMode ? styles.active : ''}`}
            onClick={() => setPreviewMode(!previewMode)}
            title="Preview Mode"
          >
            ­ƒæü
          </button>
          <button
            className={styles.actionBtn}
            onClick={toggleStyleEditor}
            title="Style Editor"
          >
            Ô£Å´©Å
          </button>
          <button className={styles.closeButton} onClick={togglePanel}>
            ├ù
          </button>
        </div>
      </div>

      <div className={styles.content}>
        {/* Preview Text Input */}
        <div className={styles.previewInput}>
          <input
            type="text"
            value={previewText}
            onChange={(e) => setPreviewText(e.target.value)}
            placeholder="Enter preview text..."
            className={styles.textInput}
          />
        </div>

        {/* Category Tabs */}
        <div className={styles.categories}>
          {categories.map((cat) => (
            <button
              key={cat.id}
              className={`${styles.categoryTab} ${
                activeCategory === cat.id ? styles.active : ''
              }`}
              onClick={() => setActiveCategory(cat.id as StyleCategory)}
            >
              <span className={styles.catIcon}>{cat.icon}</span>
              <span className={styles.catLabel}>{cat.label}</span>
            </button>
          ))}
        </div>

        {/* Styles Grid */}
        <div className={styles.stylesGrid}>
          {filteredStyles.map((style) => (
            <div
              key={style.id}
              className={`${styles.styleCard} ${
                selectedStyleId === style.id ? styles.selected : ''
              }`}
              onClick={() => handleStyleClick(style)}
            >
              {/* Style Preview */}
              <div
                className={styles.stylePreview}
                style={getStylePreviewStyle(style)}
              >
                <span style={getStyleTextStyle(style)}>{previewText}</span>
              </div>

              <div className={styles.styleInfo}>
                <h4 className={styles.styleName}>{style.name}</h4>
                <p className={styles.styleDesc}>{style.description}</p>
              </div>

              <div className={styles.styleActions}>
                <button
                  className={`${styles.favBtn} ${
                    favoriteStyleIds.includes(style.id) ? styles.active : ''
                  }`}
                  onClick={(e) => {
                    e.stopPropagation();
                    toggleFavorite(style.id);
                  }}
                >
                  {favoriteStyleIds.includes(style.id) ? 'Ôÿà' : 'Ôÿå'}
                </button>
                <button
                  className={styles.applyBtn}
                  onClick={(e) => {
                    e.stopPropagation();
                    handleApplyStyle(style);
                  }}
                  disabled={!activeTrack}
                >
                  Apply
                </button>
              </div>
            </div>
          ))}
        </div>

        {/* Recently Used */}
        {recentStyles.length > 0 && (
          <div className={styles.section}>
            <h4 className={styles.sectionTitle}>Recently Used</h4>
            <div className={styles.recentList}>
              {recentStyles.slice(0, 5).map((styleId) => {
                const style = allStyles.find((s) => s.id === styleId);
                if (!style) return null;
                return (
                  <button
                    key={styleId}
                    className={styles.recentItem}
                    onClick={() => handleApplyStyle(style)}
                    disabled={!activeTrack}
                  >
                    <span style={getStyleTextStyle(style)}>Aa</span>
                    <span>{style.name}</span>
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {/* Active Track Info */}
        {activeTrack && (
          <div className={styles.trackInfo}>
            <span>Active Track:</span>
            <strong>{activeTrack.name}</strong>
            <span className={styles.trackLang}>{activeTrack.language}</span>
          </div>
        )}

        {/* Preview Mode */}
        {previewMode && selectedStyle && (
          <div className={styles.fullPreview}>
            <div className={styles.fullPreviewContent}>
              <div
                className={styles.previewCard}
                style={getStylePreviewStyle(selectedStyle)}
              >
                <span style={getStyleTextStyle(selectedStyle)}>
                  {previewText}
                </span>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

// Helper function to generate preview style for cards
function getStylePreviewStyle(style: CaptionStyle): React.CSSProperties {
  return {
    background: style.background.enabled
      ? `rgba(0, 0, 0, ${style.background.opacity / 100})`
      : 'transparent',
    padding: style.background.padding,
    borderRadius: style.background.cornerRadius,
  };
}

// Helper function to generate text style
function getStyleTextStyle(style: CaptionStyle): React.CSSProperties {
  return {
    fontFamily: style.font.family,
    fontSize: `${style.font.size}px`,
    fontWeight: style.font.weight,
    fontStyle: style.font.style,
    color: style.textAppearance.color,
    textShadow: style.textAppearance.shadow
      ? `${style.textAppearance.shadow.offsetX}px ${style.textAppearance.shadow.offsetY}px ${style.textAppearance.shadow.blur}px rgba(0, 0, 0, ${style.textAppearance.shadow.opacity / 100})`
      : 'none',
    textTransform: style.font.textTransform,
    letterSpacing: `${style.font.letterSpacing}px`,
    lineHeight: style.font.lineHeight,
  };
}

export default CaptionStylesPanel;

import React, { useState, useEffect, useCallback } from 'react';
import { Edit2, Trash2, User, Image as ImageIcon, Loader2, RefreshCw } from 'lucide-react';
import type { Character } from '@/types/character';
import { ComfyUIService } from '@/services/comfyuiService';
import { useAppStore } from '@/stores/useAppStore';
import { downloadAndSaveImage, getImageDisplayUrl } from '@/services/imageStorageService';
import { devLog, devWarn } from '@/utils/devOnly';
import { logger } from '@/utils/logger';
import './CharacterCard.css';

/**
 * Props for the CharacterCard component
 * Requirements: 1.2, 1.4, 2.1, 4.2
 */
export interface CharacterCardProps {
  /** The character to display */
  character: Character;

  /** Optional click handler for the card */
  onClick?: () => void;

  /** Whether the card is in selection mode (for Story Generator) */
  selectable?: boolean;

  /** Whether the card is currently selected */
  selected?: boolean;

  /** Handler for selection changes */
  onSelect?: (selected: boolean) => void;

  /** Whether to show action buttons (edit, delete) */
  showActions?: boolean;

  /** Handler for edit button click */
  onEdit?: () => void;

  /** Handler for delete button click */
  onDelete?: () => void;

  /** Handler for image generation */
  /** Handler for image generation */
  onImageGenerated?: (imageUrl: string, prompt?: string) => void | Promise<void>;

  /** Whether the card is in loading state */
  loading?: boolean;
}

/**
 * CharacterCard Component
 * 
 * Displays a character summary card with thumbnail, name, archetype, age range,
 * and creation date. Supports selection mode for Story Generator and action buttons
 * for editing and deletion.
 * 
 * Requirements:
 * - Req 1.2: Display character name, archetype, age range, creation date
 * - Req 1.4: Display thumbnail if available
 * - Req 2.1: Edit button functionality
 * - Req 4.2: Selection mode for Story Generator
 */
export const CharacterCard = React.memo<CharacterCardProps>(({
  character,
  onClick,
  selectable = false,
  selected = false,
  onSelect,
  showActions = false,
  onEdit,
  onDelete,
  onImageGenerated,
  loading = false,
}) => {
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [generatedImageUrl, setGeneratedImageUrl] = useState<string | null>(null);
  const [displayImageUrl, setDisplayImageUrl] = useState<string | null>(null);

  const comfyuiService = ComfyUIService.getInstance();
  const project = useAppStore((state) => state.project);

  // Get visual style from project
  const visualStyle = (project as any)?.visualStyle || (project as any)?.visual_style || 'realistic';

  // Load display URL for saved portrait
  useEffect(() => {
    const loadDisplayUrl = async () => {
      // Priority 1: Generated image URL (temporary, from current session)
      if (generatedImageUrl) {
        setDisplayImageUrl(generatedImageUrl);
        return;
      }

      // Priority 2: Saved portrait path (persistent)
      if (character.visual_identity?.generated_portrait) {
        const portraitPath = character.visual_identity.generated_portrait;
        const url = await getImageDisplayUrl(
          typeof portraitPath === 'string' ? portraitPath : String(portraitPath),
          project?.metadata?.path as string | undefined
        );
        if (url) {
          setDisplayImageUrl(url);
          return;
        }
      }

      // Priority 3: Legacy thumbnail_url
      if ((character as any).thumbnail_url) {
        setDisplayImageUrl((character as any).thumbnail_url);
        return;
      }

      // No image available
      setDisplayImageUrl(null);
    };

    loadDisplayUrl();
  }, [character, generatedImageUrl, project?.metadata?.path]);
  // Format creation date
  const formatDate = (timestamp: string): string => {
    try {
      const date = new Date(timestamp);
      // Check if date is valid
      if (Number.isNaN(date.getTime())) {
        return 'Unknown date';
      }
      return date.toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
      });
    } catch {
      return 'Unknown date';
    }
  };

  // Handle card click
  const handleCardClick = useCallback(() => {
    if (selectable && onSelect) {
      onSelect(!selected);
    } else if (onClick) {
      onClick();
    }
  }, [selectable, onSelect, selected, onClick]);

  // Handle checkbox change
  const handleCheckboxChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    e.stopPropagation();
    if (onSelect) {
      onSelect(e.target.checked);
    }
  }, [onSelect]);

  // Handle edit button click
  const handleEditClick = useCallback((e: React.MouseEvent) => {
    e.stopPropagation();
    if (onEdit) {
      onEdit();
    }
  }, [onEdit]);

  // Handle delete button click
  const handleDeleteClick = useCallback((e: React.MouseEvent) => {
    e.stopPropagation();
    if (onDelete) {
      onDelete();
    }
  }, [onDelete]);

  // Get thumbnail URL from visual identity or use placeholder
  const thumbnailUrl = displayImageUrl;

  /**
   * Build visual style prefix for prompt
   */
  const buildStylePrefix = (): string => {
    const styleMap: Record<string, string> = {
      'photorealistic': 'photorealistic',
      'cinematic': 'cinematic',
      'anime': 'anime style',
      'cartoon': 'cartoon style',
      'sketch': 'sketch art',
      'oil-painting': 'oil painting',
      'watercolor': 'watercolor painting',
      'digital-art': 'digital art',
      'comic-book': 'comic book style',
      'noir': 'film noir style',
      'vintage': 'vintage style',
      'modern': 'modern style',
      'minimalist': 'minimalist style',
      'realistic': 'realistic'
    };
    return styleMap[visualStyle] || visualStyle;
  };

  /**
   * Build visual identity details for prompt
   */
  const buildVisualDetails = (): string[] => {
    const details: string[] = [];
    const visual = character.visual_identity;

    if (!visual) return details;

    // Face and hair
    if (visual.hair_color && visual.hair_style) {
      details.push(`${visual.hair_color} ${visual.hair_style} hair`);
    } else if (visual.hair_color) {
      details.push(`${visual.hair_color} hair`);
    }

    if (visual.eye_color) {
      details.push(`${visual.eye_color} eyes`);
    }

    if (visual.facial_structure) {
      details.push(`${visual.facial_structure} face`);
    }

    // Skin and build
    if (visual.skin_tone) {
      details.push(`${visual.skin_tone} skin`);
    }

    if (visual.build) {
      details.push(`${visual.build} build`);
    }

    // Clothing
    if (visual.clothing_style) {
      details.push(`wearing ${visual.clothing_style} clothing`);
    }

    // Distinctive features
    if (visual.distinctive_features && visual.distinctive_features.length > 0) {
      details.push(visual.distinctive_features.join(', '));
    }

    return details;
  };

  /**
   * Build a detailed prompt from character data
   */
  const buildCharacterPrompt = (): string => {
