    try {
      prompt = buildCharacterPrompt();
      const negativePrompt = buildNegativePrompt();

      devLog('­ƒÄ¿ [CharacterCard] Starting image generation');
      devLog('­ƒôØ Prompt:', prompt);
      devLog('­ƒÜ½ Negative:', negativePrompt);
