export interface CharacterCardProps {
  character: Character;
  onClick?: () => void;
  selectable?: boolean;
  selected?: boolean;
  onSelect?: (selected: boolean) => void;
  showActions?: boolean;
  onEdit?: () => void;
  onDelete?: () => void;
  loading?: boolean;
}

// ============================================================================
// Helper Functions
