    it('should have proper aria-label for delete button', () => {
      const character = createMockCharacter();
      render(
        <CharacterCard
          character={character}
          showActions={true}
          onDelete={vi.fn()}
        />
      );
      
      const deleteButton = screen.getByLabelText('Delete John Doe');
