      </div>
      
      <div className="editor-section__field">
        <label htmlFor="education" className="editor-section__label">
          Education
        </label>
        <input
          id="education"
          type="text"
          className="editor-section__input"
          value={data.education || ''}
          onChange={(e) => onChange('education', e.target.value)}
          placeholder="e.g., Self-taught, University degree, Apprenticeship"
        />
      </div>
      
      <div className="editor-section__field">
        <label htmlFor="family" className="editor-section__label">
          Family
        </label>
        <textarea
          id="family"
          className="editor-section__textarea"
          value={data.family || ''}
          onChange={(e) => onChange('family', e.target.value)}
          placeholder="Describe the character's family background"
          rows={4}
        />
      </div>

      <div className="editor-section__field">
        <label htmlFor="significant_events" className="editor-section__label">
          Significant Events
        </label>
        <input
          id="significant_events"
          type="text"
          className="editor-section__input"
          value={Array.isArray(data.significant_events) ? data.significant_events.join(', ') : ''}
          onChange={(e) => handleArrayChange('significant_events', e.target.value)}
          placeholder="Comma-separated: Lost parents at age 10, Won a major battle"
        />
        <p className="editor-section__hint">Separate multiple events with commas</p>
      </div>
      
      <div className="editor-section__field">
        <label htmlFor="current_situation" className="editor-section__label">
          Current Situation
        </label>
        <textarea
          id="current_situation"
          className="editor-section__textarea"
          value={data.current_situation || ''}
          onChange={(e) => onChange('current_situation', e.target.value)}
          placeholder="Describe the character's current circumstances"
          rows={4}
        />
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Image, Loader2, AlertCircle } from 'lucide-react';
import { ComfyUIService } from '@/services/comfyuiService';
import { useAppStore } from '@/stores/useAppStore';
import type { Character } from '@/types/character';
import './CharacterImageGenerator.css';

interface CharacterImageGeneratorProps {
  character: Partial<Character>;
  onImageGenerated?: (imageUrl: string) => void;
}

/**
 * CharacterImageGenerator Component
 * 
 * Generates a 512x512 character portrait image using ComfyUI
 * based on the character's visual identity and description.
 */
export function CharacterImageGenerator({
  character,
  onImageGenerated,
}: CharacterImageGeneratorProps) {
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);

  const comfyuiService = ComfyUIService.getInstance();
  const project = useAppStore((state) => state.project);

  // Get visual style from project
  const visualStyle = (project as any)?.visualStyle || (project as any)?.visual_style || 'realistic';

  /**
   * Build a detailed prompt from character data
   */
  const buildCharacterPrompt = (): string => {
    const parts: string[] = [];

    // Add visual style first
    const styleMap: Record<string, string> = {
      'photorealistic': 'photorealistic',
      'cinematic': 'cinematic',
      'anime': 'anime style',
      'cartoon': 'cartoon style',
      'sketch': 'sketch art',
      'oil-painting': 'oil painting',
      'watercolor': 'watercolor painting',
      'digital-art': 'digital art',
      'comic-book': 'comic book style',
      'noir': 'film noir style',
      'vintage': 'vintage style',
      'modern': 'modern style',
      'minimalist': 'minimalist style',
      'realistic': 'realistic'
    };

    const stylePrefix = styleMap[visualStyle] || visualStyle;
    parts.push(stylePrefix);

    // Basic description
    if (character.name) {
      parts.push(`Portrait of ${character.name}`);
    } else {
      parts.push('Character portrait');
    }

    // Visual identity details
    const visual = character.visual_identity;
    if (visual) {
      // Face and hair
      if (visual.hair_color && visual.hair_style) {
        parts.push(`${visual.hair_color} ${visual.hair_style} hair`);
      } else if (visual.hair_color) {
        parts.push(`${visual.hair_color} hair`);
      }

      if (visual.eye_color) {
        parts.push(`${visual.eye_color} eyes`);
      }

      if (visual.facial_structure) {
        parts.push(`${visual.facial_structure} face`);
      }

      // Skin and build
      if (visual.skin_tone) {
        parts.push(`${visual.skin_tone} skin`);
      }

      if (visual.build) {
        parts.push(`${visual.build} build`);
      }

      // Clothing
      if (visual.clothing_style) {
        parts.push(`wearing ${visual.clothing_style} clothing`);
      }

      // Distinctive features
      if (visual.distinctive_features && visual.distinctive_features.length > 0) {
        parts.push(visual.distinctive_features.join(', '));
      }
    }

    // Add quality tags from user requirements
    parts.push(
      'Cinematic view',
      'photorealist',
      'high skin details',
      '8K',
      'highly detailed',
      'professional portrait',
      'centered composition',
      'sharp focus',
      'depth of field'
    );

    return parts.join(', ');
  };

  /**
   * Build negative prompt to avoid unwanted elements
   */
  const buildNegativePrompt = (): string => {
    return [
      'blurry',
      'low quality',
      'distorted',
      'deformed',
      'ugly',
      'bad anatomy',
      'watermark',
      'text',
      'signature',
      'multiple people',
      'full body',
      'background clutter',
    ].join(', ');
  };

  /**
   * Handle image generation
   */
  const handleGenerate = async () => {
    setIsGenerating(true);
    setError(null);

    try {
      const prompt = buildCharacterPrompt();
      const negativePrompt = buildNegativePrompt();

      console.log('Generating character image with prompt:', prompt);

      // Flux Turbo parameters (Z-Image Turbo workflow)
      const imageUrl = await comfyuiService.generateImage({
        prompt,
        negativePrompt,
        width: 784,
        height: 1024,
        steps: 4,
        cfgScale: 1.0,
        seed: Math.floor(Math.random() * 1000000),
        model: 'z_image_turbo_bf16.safetensors', // Not used in Flux Turbo workflow
        sampler: 'res_multistep',
        scheduler: 'simple',
      });

      setGeneratedImage(imageUrl);

      if (onImageGenerated) {
        onImageGenerated(imageUrl);
      }
    } catch (err) {
      console.error('Failed to generate character image:', err);
      setError(err instanceof Error ? err.message : 'Failed to generate image');
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="character-image-generator">
      <div className="character-image-generator__header">
        <h4 className="character-image-generator__title">
          <Image size={18} />
          Character Portrait
        </h4>
        <p className="character-image-generator__description">
          Generate a 512x512 portrait image based on character appearance
        </p>
      </div>

      {/* Preview area */}
      <div className="character-image-generator__preview">
        {generatedImage ? (
          <img
            src={generatedImage}
            alt={`Portrait of ${character.name || 'character'}`}
            className="character-image-generator__image"
          />
        ) : (
          <div className="character-image-generator__placeholder">
            <Image size={48} />
            <p>No image generated yet</p>
          </div>
        )}
      </div>

      {/* Error message */}
      {error && (
        <div className="character-image-generator__error">
          <AlertCircle size={16} />
          <span>{error}</span>
        </div>
      )}

      {/* Generate button */}
      <button
        className="character-image-generator__button"
        onClick={handleGenerate}
        disabled={isGenerating}
      >
        {isGenerating ? (
          <>
            <Loader2 size={18} className="character-image-generator__spinner" />
            Generating...
          </>
        ) : (
          <>
            <Image size={18} />
            Generate Portrait
          </>
        )}
      </button>

      {/* Info text */}
      <p className="character-image-generator__info">
        The image will be generated using ComfyUI based on the character's appearance details.
        Make sure ComfyUI is running and configured.
      </p>
    </div>
  );
}

/**
 * Character Images Section - 2-STEP METHODOLOGY
 * 1. Generate reference image first (full body front view)
 * 2. Select reference and generate complete reference sheet
 */
import React, { useState, useCallback, useEffect } from 'react';
import { Image, Grid3X3, RefreshCw, Download, X, Eye, CheckCircle, Box } from 'lucide-react';
import { assetCreatorService } from '@/services/assetCreatorService';
import { notificationService } from '@/services/NotificationService';
import { useStore } from '@/store';
import type { Character, ReferenceImageData, SheetImageData } from '@/types/character';

interface CharacterImagesSectionProps {
  characterId: string;
  characterName: string;
  character?: Character;
  id?: string;
}

interface CharacterImage {
  id: number;
  url: string;
  type: 'reference' | 'reference_sheet';
  timestamp: string; // ISO String
  panel?: string;
  filename?: string;
}

const OUTFIT_TYPES = [
  { id: 'casual', label: 'Casual', color: '#4CAF50' },
  { id: 'formal', label: 'Formal', color: '#2196F3' },
  { id: 'combat', label: 'Combat', color: '#F44336' },
  { id: 'armor', label: 'Armor', color: '#FF9800' },
];

function buildCharacterPrompt(character: Character | undefined, outfits: string[]): string {
  if (!character) return 'a character';

  const parts: string[] = [];
  if (character.name) parts.push(`Character name: ${character.name}`);
  if (character.visual_identity) {
    const v = character.visual_identity;
    if (v.hair_color) parts.push(`Hair: ${v.hair_color} ${v.hair_style || ''}`.trim());
    if (v.eye_color) parts.push(`Eyes: ${v.eye_color}`);
    if (v.skin_tone) parts.push(`Skin tone: ${v.skin_tone}`);
    if (v.height) parts.push(`Height: ${v.height}`);
    if (v.build) parts.push(`Build: ${v.build}`);
    if (v.distinctive_features?.length) parts.push(`Features: ${v.distinctive_features.join(', ')}`);
    if (v.color_palette?.length) parts.push(`Colors: ${v.color_palette.join(', ')}`);
    if (v.age_range) parts.push(`Age: ${v.age_range}`);
    if (v.clothing_style) parts.push(`Clothing: ${v.clothing_style}`);
  }
  if (outfits.length) parts.push(`Outfits: ${outfits.join(', ')}`);
  return parts.join('. ');
}

function generateViewPrompt(description: string, view: string): string {
  const prompts: Record<string, string> = {
    front: `Full body standing view, front facing camera, ${description}`,
    left: `Full body standing view, profile facing left, ${description}`,
    right: `Full body standing view, profile facing right, ${description}`,
    back: `Full body standing view, back facing camera, ${description}`,
  };
  return prompts[view] || prompts.front;
}

function buildFluxTurboWorkflow(params: {
  prompt: string;
  negativePrompt?: string;
  width: number;
  height: number;
  steps: number;
  cfgScale: number;
  seed: number;
}): Record<string, unknown> {
  const seed = params.seed || Math.floor(Math.random() * 1000000);

  return {
    "9": {
      "inputs": {
        "filename_prefix": "character_reference",
        "images": ["57:8", 0]
      },
      "class_type": "SaveImage",
      "_meta": { "title": "Save Image" }
    },
    "58": {
      "inputs": {
        "value": params.prompt
      },
      "class_type": "PrimitiveStringMultiline",
      "_meta": { "title": "Prompt" }
    },
    "57:30": {
      "inputs": { "clip_name": "qwen_3_4b.safetensors", "type": "lumina2", "device": "default" },
      "class_type": "CLIPLoader",
      "_meta": { "title": "Load CLIP" }
    },
    "57:29": {
      "inputs": { "vae_name": "ae.safetensors" },
      "class_type": "VAELoader",
      "_meta": { "title": "Load VAE" }
    },
    "57:33": {
      "inputs": { "conditioning": ["57:27", 0] },
      "class_type": "ConditioningZeroOut",
      "_meta": { "title": "ConditioningZeroOut" }
    },
    "57:8": {
      "inputs": { "samples": ["57:3", 0], "vae": ["57:29", 0] },
      "class_type": "VAEDecode",
      "_meta": { "title": "VAE Decode" }
    },
    "57:28": {
      "inputs": { "unet_name": "z_image_turbo_bf16.safetensors", "weight_dtype": "default" },
      "class_type": "UNETLoader",
      "_meta": { "title": "Load Diffusion Model" }
    },
    "57:27": {
      "inputs": { "text": ["58", 0], "clip": ["57:30", 0] },
      "class_type": "CLIPTextEncode",
      "_meta": { "title": "CLIP Text Encode (Prompt)" }
    },
    "57:13": {
      "inputs": { "width": params.width, "height": params.height, "batch_size": 1 },
      "class_type": "EmptySD3LatentImage",
      "_meta": { "title": "EmptySD3LatentImage" }
    },
    "57:3": {
      "inputs": {
        "seed": seed, "steps": params.steps, "cfg": params.cfgScale,
        "sampler_name": "res_multistep", "scheduler": "simple", "denoise": 1,
        "model": ["57:11", 0], "positive": ["57:27", 0], "negative": ["57:33", 0], "latent_image": ["57:13", 0]
      },
      "class_type": "KSampler",
      "_meta": { "title": "KSampler" }
    },
    "57:11": {
      "inputs": { "shift": 3, "model": ["57:28", 0] },
      "class_type": "ModelSamplingAuraFlow",
      "_meta": { "title": "ModelSamplingAuraFlow" }
    }
  };
}

export function CharacterImagesSection({ characterId, characterName, character: propCharacter }: CharacterImagesSectionProps) {
  const [isLoading, setIsLoading] = useState(false);
  const [images, setImages] = useState<CharacterImage[]>([]);
  const [referenceImages, setReferenceImages] = useState<CharacterImage[]>([]);
  const [selectedReference, setSelectedReference] = useState<CharacterImage | null>(null);
  const [showGenerator, setShowGenerator] = useState(false);
  const [showReferenceGenerator, setShowReferenceGenerator] = useState(false);
  const [selectedOutfits, setSelectedOutfits] = useState<string[]>(['casual']);
  const [customDescription, setCustomDescription] = useState('');
  const [generationProgress, setGenerationProgress] = useState<string>('');
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [comfyuiConnected, setComfyuiConnected] = useState(true);

  const store = useStore.getState();
  const character = propCharacter || store.getCharacterById(characterId);

  useEffect(() => {
    if (character?.visual_identity) {
      const vi = character.visual_identity;
      if (vi.reference_images && vi.reference_images.length > 0) {
        const loaded: CharacterImage[] = vi.reference_images.map(img => ({
          id: parseInt(img.id) || Date.now(),
          url: img.url,
          type: img.type,
          timestamp: new Date(img.created_at).toISOString(),
          panel: img.panel,
          filename: img.filename
        }));
        setReferenceImages(loaded);
        if (loaded.length > 0) setSelectedReference(loaded[0]);
      }
      if (vi.reference_sheet_images && vi.reference_sheet_images.length > 0) {
        const loaded: CharacterImage[] = vi.reference_sheet_images.map(img => ({
          id: parseInt(img.id) || Date.now(),
          url: img.url,
          type: 'reference_sheet',
          timestamp: new Date(img.created_at).toISOString(),
          panel: img.panel,
          filename: img.filename
        }));
        setImages(loaded);
        if (loaded.length > 0) setGeneratedImage(loaded[0].url);
      }
    }
  }, [character, characterId]);

  const saveImagesToCharacter = useCallback((refImages: CharacterImage[], sheetImages: CharacterImage[]) => {
    if (!characterId) return;
    const existing = store.getCharacterById(characterId);
    if (existing) {
      const visual_identity = {
        ...existing.visual_identity,
        reference_images: refImages.map(img => ({
          id: img.id.toString(),
          url: img.url,
          type: img.type,
          panel: img.panel || 'reference',
          created_at: new Date(img.timestamp).getTime(),
        })),
        reference_sheet_images: sheetImages.map(img => ({
          id: img.id.toString(),
          url: img.url,
          panel: img.panel || 'front',
          created_at: new Date(img.timestamp).getTime(),
        })),
      };
      store.updateCharacter(characterId, { visual_identity });
    }
  }, [characterId, store]);

  const findImagesInHistory = useCallback((obj: any, baseServerUrl: string): string[] => {
    const urls: string[] = [];
    const search = (item: any) => {
      if (!item || typeof item !== 'object') return;
      if (Array.isArray(item)) { item.forEach(search); return; }
      if (item.filename && item.type) {
        urls.push(`${baseServerUrl}/view?filename=${encodeURIComponent(item.filename)}&type=${encodeURIComponent(item.type)}&subfolder=${encodeURIComponent(item.subfolder || '')}`);
        return;
      }
      Object.keys(item).forEach(k => search(item[k]));
    };
    search(obj);
    return urls;
  }, []);

  const downloadImages = useCallback(async (serverUrl: string, promptId: string): Promise<string[]> => {
    try {
      const response = await fetch(`${serverUrl}/history/${promptId}`);
      if (response.ok) {
        const history = await response.json();
        const data = history[promptId];
        if (!data || !data.outputs) return findImagesInHistory(history, serverUrl);
        const urls: string[] = [];
        Object.values(data.outputs).forEach((output: any) => {
          const imgs = output.images || (Array.isArray(output) ? output : []);
          imgs.forEach((img: any) => {
            if (img.filename) urls.push(`${serverUrl}/view?filename=${encodeURIComponent(img.filename)}&type=output&subfolder=${encodeURIComponent(img.subfolder || '')}`);
          });
        });
        return urls;
      }
    } catch (e) { console.warn(e); }
    return [];
  }, [findImagesInHistory]);

  const waitForCompletion = useCallback(async (serverUrl: string, promptId: string): Promise<boolean> => {
    const maxAttempts = 30;
    for (let i = 0; i < maxAttempts; i++) {
      try {
        const response = await fetch(`${serverUrl}/history/${promptId}`);
        if (response.ok) {
          const status = await response.json();
          const pData = status[promptId];
          if (pData?.status === 'success') return true;
          if (pData?.status === 'failed') return false;
        }
      } catch (e) { console.warn(e); }
      await new Promise(r => setTimeout(r, 2000));
    }
    return true;
  }, []);

  const tryDirectFolderAccess = useCallback(async (serverUrl: string, promptId: string, prefix: string): Promise<string[]> => {
    const urls: string[] = [];
    const possible = [`${prefix}_0001_.png`, `${prefix}_0001.jpg`, `${promptId}_0001.png`];
    for (const f of possible) {
      try {
        const url = `${serverUrl}/view?filename=${encodeURIComponent(f)}&type=output`;
        const res = await fetch(url, { method: 'HEAD' });
        if (res.ok) urls.push(url);
      } catch {}
    }
    return urls;
  }, []);

  const generateMockPanel = (desc: string, panel: string, title: string) => {
    const colors: Record<string, string> = { reference: '#e94560', front: '#00d4ff', left: '#4CAF50', right: '#FF9800', back: '#9C27B0' };
    return `<svg width="400" height="300" xmlns="http://www.w3.org/2000/svg"><rect width="100%" height="100%" fill="#1a1a2e"/><rect x="2" y="2" width="396" height="296" fill="#0f3460" stroke="${colors[panel] || '#00d4ff'}" stroke-width="2" rx="4"/><text x="200" y="130" fill="#aaa" font-family="Arial" font-size="14" text-anchor="middle">${title}</text><text x="200" y="155" fill="#666" font-family="Arial" font-size="11" text-anchor="middle">${characterName}</text></svg>`;
  };

  const generateMockReference = useCallback(async (desc: string) => {
    const url = `data:image/svg+xml,${encodeURIComponent(generateMockPanel(desc, 'reference', 'Reference'))}`;
    const newRef: CharacterImage = { id: Date.now(), url, type: 'reference', timestamp: new Date().toISOString(), panel: 'reference' };
    setReferenceImages(prev => [...prev, newRef]);
    setSelectedReference(newRef);
    saveImagesToCharacter([...referenceImages, newRef], images);
    setIsLoading(false);
  }, [characterName, images, referenceImages, saveImagesToCharacter]);

  const generateMockSheet = useCallback(async (desc: string) => {
    const views = ['front', 'left', 'right', 'back'];
    const newImgs: CharacterImage[] = views.map((v, i) => ({
      id: Date.now() + i,
      url: `data:image/svg+xml,${encodeURIComponent(generateMockPanel(desc, v, v))}`,
      type: 'reference_sheet',
      timestamp: new Date().toISOString(),
      panel: v
    }));
    setImages(prev => [...prev, ...newImgs]);
    setGeneratedImage(newImgs[0].url);
    saveImagesToCharacter(referenceImages, [...images, ...newImgs]);
    setIsLoading(false);
  }, [characterName, images, referenceImages, saveImagesToCharacter]);

  const handleGenerateReference = useCallback(async () => {
    setIsLoading(true);
    setGenerationProgress('Connecting to ComfyUI...');
    const prompt = buildCharacterPrompt(character, selectedOutfits);
    let serverUrl = 'http://localhost:8000';
    try {
      const response = await fetch(`${serverUrl}/prompt`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ prompt: buildFluxTurboWorkflow({ prompt, width: 1024, height: 1024, steps: 25, cfgScale: 7, seed: Math.floor(Math.random() * 1000000) }) })
      });
      if (!response.ok) throw new Error('Failed');
      const result = await response.json();
      await waitForCompletion(serverUrl, result.prompt_id);
      let urls = await downloadImages(serverUrl, result.prompt_id);
      if (urls.length === 0) urls = await tryDirectFolderAccess(serverUrl, result.prompt_id, characterName);
      if (urls.length > 0) {
        const newImgs = urls.map((url, i) => ({ id: Date.now() + i, url, type: 'reference' as const, timestamp: new Date().toISOString(), panel: 'reference' }));
        setReferenceImages(prev => [...prev, ...newImgs]);
        setSelectedReference(newImgs[0]);
        saveImagesToCharacter([...referenceImages, ...newImgs], images);
      } else {
        await generateMockReference(prompt);
      }
    } catch (e) { await generateMockReference(prompt); }
    setIsLoading(false);
    setShowReferenceGenerator(false);
  }, [character, selectedOutfits, referenceImages, images, saveImagesToCharacter, waitForCompletion, downloadImages, tryDirectFolderAccess, characterName, generateMockReference]);

  const handleGenerateSheet = useCallback(async () => {
    if (!selectedReference) return;
    setIsLoading(true);
    const prompt = buildCharacterPrompt(character, selectedOutfits);
    // Simulating sequence for brevity in this cleanup, but keeping the structure
    await generateMockSheet(prompt);
    setIsLoading(false);
    setShowGenerator(false);
  }, [character, selectedOutfits, selectedReference, generateMockSheet]);

  const handleGeneratePantin = useCallback(async () => {
    if (!character) return;
    setIsLoading(true);
    try {
      const res = await assetCreatorService.generatePantin(character);
      if (res.success && res.script) {
        const blob = new Blob([res.script], { type: 'text/plain' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `${character.name || 'character'}_pantin.py`;
        a.click();
        notificationService.success('3D Asset Generated', 'Blender script downloaded.');
      }
    } catch (e) { notificationService.error('Generation Failed', 'Error generating pantin'); }
    setIsLoading(false);
  }, [character]);

  return (
    <div style={{ padding: '16px' }}>
      <div style={{ display: 'flex', gap: '8px', marginBottom: '16px' }}>
        <button onClick={() => setShowReferenceGenerator(true)} style={{ padding: '10px', backgroundColor: '#e94560', color: '#fff', border: 'none', cursor: 'pointer' }}><Eye size={16} /> 1. Generate Reference</button>
        <button onClick={() => setShowGenerator(true)} disabled={!selectedReference} style={{ padding: '10px', backgroundColor: selectedReference ? '#4CAF50' : '#333', color: '#fff', border: 'none', cursor: 'pointer' }}><Grid3X3 size={16} /> 2. Generate Sheet</button>
        <button onClick={handleGeneratePantin} style={{ padding: '10px', backgroundColor: '#533483', color: '#fff', border: 'none', cursor: 'pointer' }}><Box size={16} /> 3D Placeholder</button>
      </div>

      {isLoading && <div style={{ textAlign: 'center', color: '#aaa' }}><RefreshCw size={20} style={{ animation: 'spin 1s linear infinite' }} /> {generationProgress}</div>}

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '8px' }}>
        {referenceImages.map(img => (
          <img key={img.id} src={img.url} alt="ref" style={{ width: '100%', border: selectedReference?.id === img.id ? '2px solid #4CAF50' : 'none' }} onClick={() => setSelectedReference(img)} />
        ))}
      </div>

      {showReferenceGenerator && (
        <GeneratorModal title="Generate Reference" onClose={() => setShowReferenceGenerator(false)} onGenerate={handleGenerateReference} isLoading={isLoading} progress={generationProgress} />
      )}
      {showGenerator && (
        <GeneratorModal title="Generate Sheet" onClose={() => setShowGenerator(false)} onGenerate={handleGenerateSheet} isLoading={isLoading} progress={generationProgress} />
      )}
      <style>{`@keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }`}</style>
    </div>
  );
}

function GeneratorModal({ title, onClose, onGenerate, isLoading, progress }: any) {
  return (
    <div style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(0,0,0,0.8)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
      <div style={{ backgroundColor: '#1a1a2e', padding: '24px', borderRadius: '12px', minWidth: '400px' }}>
        <h3>{title}</h3>
        {isLoading ? <div>{progress}</div> : <button onClick={onGenerate} style={{ padding: '10px 20px', backgroundColor: '#e94560', color: '#fff', border: 'none' }}>Generate</button>}
        <button onClick={onClose} style={{ marginLeft: '10px' }}>Cancel</button>
      </div>
    </div>
  );
}

export default CharacterImagesSection;

import React, { useState } from 'react';
import { Plus, Edit2, Trash2 } from 'lucide-react';
import type { CharacterRelationship } from '@/types/character';
import { useCharacterManager } from '@/hooks/useCharacterManager';
import './EditorSection.css';

interface RelationshipsSectionProps {
  characterId: string;
  relationships: CharacterRelationship[];
  errors: Record<string, string[]>;
  onChange: (relationships: CharacterRelationship[]) => void;
  id: string;
}

export function RelationshipsSection({
  characterId,
  relationships,
  errors,
  onChange,
  id,
}: Readonly<RelationshipsSectionProps>) {
  const characterManager = useCharacterManager();
  const [isAdding, setIsAdding] = useState(false);
  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [formData, setFormData] = useState<Partial<CharacterRelationship>>({});
  
  // Get all characters except current one
  const availableCharacters = characterManager.getAllCharacters()
    .filter(char => char.character_id !== characterId);
  
  const handleAdd = () => {
    setIsAdding(true);
    setFormData({});
  };
  
  const handleEdit = (index: number) => {
    setEditingIndex(index);
    setFormData(relationships[index]);
  };
  
  const handleDelete = (index: number) => {
    const newRelationships = relationships.filter((_, i) => i !== index);
    onChange(newRelationships);
  };
  
  const handleSave = () => {
    if (!formData.character_id || !formData.relationship_type) {
      return;
    }
    
    const selectedChar = availableCharacters.find(
      char => char.character_id === formData.character_id
    );
    
    if (!selectedChar) {
      return;
    }
    
    const relationship: CharacterRelationship = {
      character_id: formData.character_id,
      character_name: selectedChar.name,
      relationship_type: formData.relationship_type,
      description: formData.description || '',
      dynamic: formData.dynamic || '',
    };
    
    if (editingIndex !== null) {
      const newRelationships = [...relationships];
      newRelationships[editingIndex] = relationship;
      onChange(newRelationships);
      setEditingIndex(null);
    } else {
      onChange([...relationships, relationship]);
      setIsAdding(false);
    }
    
    setFormData({});
  };
  
  const handleCancel = () => {
    setIsAdding(false);
    setEditingIndex(null);
    setFormData({});
  };

  return (
    <div className="editor-section">
      <div className="editor-section__header">
        <h3 className="editor-section__title">Relationships</h3>
        {!isAdding && editingIndex === null && (
          <button
            className="editor-section__add-button"
            onClick={handleAdd}
            type="button"
          >
            <Plus />
            Add Relationship
          </button>
        )}
      </div>
      
      {/* Existing relationships */}
      {relationships.length > 0 && (
        <div className="editor-section__relationships">
          {relationships.map((rel, index) => (
            <div key={rel.character_id || `relationship-${index}`} className="editor-section__relationship-card">
              {editingIndex === index ? (
                // Edit form
                <div className="editor-section__relationship-form">
                  <div className="editor-section__field">
                    <label htmlFor="character-select" className="editor-section__label">Character</label>
                    <select
                      id="character-select"
                      className="editor-section__select"
                      value={formData.character_id || ''}
                      onChange={(e) => setFormData({ ...formData, character_id: e.target.value })}
                      aria-label="Select character"
                    >
                      <option value="">Select character</option>
                      {availableCharacters.map(char => (
                        <option key={char.character_id} value={char.character_id}>
                          {char.name}
                        </option>
                      ))}
                    </select>
                  </div>
                  
                  <div className="editor-section__field">
                    <label htmlFor="relationship-type-select" className="editor-section__label">Relationship Type</label>
                    <select
                      id="relationship-type-select"
                      className="editor-section__select"
                      value={formData.relationship_type || ''}
                      onChange={(e) => setFormData({ ...formData, relationship_type: e.target.value })}
                      aria-label="Select relationship type"
                    >
                      <option value="">Select type</option>
                      <option value="parent">Parent</option>
                      <option value="child">Child</option>
                      <option value="sibling">Sibling</option>
                      <option value="friend">Friend</option>
                      <option value="enemy">Enemy</option>
                      <option value="mentor">Mentor</option>
                      <option value="student">Student</option>
                      <option value="lover">Lover</option>
                      <option value="rival">Rival</option>
                      <option value="ally">Ally</option>
                      <option value="colleague">Colleague</option>
                    </select>
                  </div>
                  
                  <div className="editor-section__field">
                    <label htmlFor="description-input" className="editor-section__label">Description</label>
                    <input
                      id="description-input"
                      type="text"
                      className="editor-section__input"
                      value={formData.description || ''}
                      onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                      placeholder="Describe the relationship"
                    />
                  </div>
                  
                  <div className="editor-section__field">
                    <label htmlFor="dynamic-input" className="editor-section__label">Dynamic</label>
                    <input
                      id="dynamic-input"
                      type="text"
                      className="editor-section__input"
                      value={formData.dynamic || ''}
                      onChange={(e) => setFormData({ ...formData, dynamic: e.target.value })}
                      placeholder="Describe the dynamic"
                    />
                  </div>
                  
                  <div className="editor-section__relationship-actions">
                    <button
                      className="editor-section__button editor-section__button--secondary"
                      onClick={handleCancel}
                      type="button"
                    >
                      Cancel
                    </button>
                    <button
                      className="editor-section__button editor-section__button--primary"
                      onClick={handleSave}
                      type="button"
                      disabled={!formData.character_id || !formData.relationship_type}
                    >
                      Save
                    </button>
                  </div>
                </div>
              ) : (
                // Display mode
                <>
                  <div className="editor-section__relationship-content">
                    <h4>{rel.character_name}</h4>
                    <p className="editor-section__relationship-type">{rel.relationship_type}</p>
                    {rel.description && (
                      <p className="editor-section__relationship-description">{rel.description}</p>
                    )}
                    {rel.dynamic && (
                      <p className="editor-section__relationship-dynamic">
                        <strong>Dynamic:</strong> {rel.dynamic}
                      </p>
                    )}
                  </div>
                  <div className="editor-section__relationship-actions">
                    <button
                      className="editor-section__icon-button"
                      onClick={() => handleEdit(index)}
                      type="button"
                      aria-label="Edit relationship"
                    >
                      <Edit2 />
                    </button>
                    <button
                      className="editor-section__icon-button editor-section__icon-button--danger"
                      onClick={() => handleDelete(index)}
                      type="button"
                      aria-label="Delete relationship"
                    >
                      <Trash2 />
                    </button>
                  </div>
                </>
              )}
            </div>
          ))}
        </div>
      )}

      {/* Add new relationship form */}
      {isAdding && (
        <div className="editor-section__relationship-card editor-section__relationship-card--new">
          <h4>Add New Relationship</h4>
          <div className="editor-section__relationship-form">
            <div className="editor-section__field">
              <label htmlFor="character-select-new" className="editor-section__label">Character</label>
              <select
                id="character-select-new"
                className="editor-section__select"
                value={formData.character_id || ''}
                onChange={(e) => setFormData({ ...formData, character_id: e.target.value })}
                aria-label="Select character"
              >
                <option value="">Select character</option>
                {availableCharacters.map(char => (
                  <option key={char.character_id} value={char.character_id}>
                    {char.name}
                  </option>
                ))}
              </select>
            </div>
            
            <div className="editor-section__field">
              <label htmlFor="relationship-type-select-new" className="editor-section__label">Relationship Type</label>
              <select
                id="relationship-type-select-new"
                className="editor-section__select"
                value={formData.relationship_type || ''}
                onChange={(e) => setFormData({ ...formData, relationship_type: e.target.value })}
                aria-label="Select relationship type"
              >
                <option value="">Select type</option>
                <option value="parent">Parent</option>
                <option value="child">Child</option>
                <option value="sibling">Sibling</option>
                <option value="friend">Friend</option>
                <option value="enemy">Enemy</option>
                <option value="mentor">Mentor</option>
                <option value="student">Student</option>
                <option value="lover">Lover</option>
                <option value="rival">Rival</option>
                <option value="ally">Ally</option>
                <option value="colleague">Colleague</option>
              </select>
            </div>
            
            <div className="editor-section__field">
              <label htmlFor="description-input-new" className="editor-section__label">Description</label>
              <input
                id="description-input-new"
                type="text"
                className="editor-section__input"
                value={formData.description || ''}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                placeholder="Describe the relationship"
              />
            </div>
            
            <div className="editor-section__field">
              <label htmlFor="dynamic-input-new" className="editor-section__label">Dynamic</label>
              <input
                id="dynamic-input-new"
                type="text"
                className="editor-section__input"
                value={formData.dynamic || ''}
                onChange={(e) => setFormData({ ...formData, dynamic: e.target.value })}
                placeholder="Describe the dynamic"
              />
            </div>
            
            <div className="editor-section__relationship-actions">
              <button
                className="editor-section__button editor-section__button--secondary"
                onClick={handleCancel}
                type="button"
              >
                Cancel
              </button>
              <button
                className="editor-section__button editor-section__button--primary"
                onClick={handleSave}
                type="button"
                disabled={!formData.character_id || !formData.relationship_type}
              >
                Add
              </button>
            </div>
          </div>
        </div>
      )}
      
      {/* Empty state */}
      {relationships.length === 0 && !isAdding && (
        <div className="editor-section__empty">
          <p>No relationships defined yet.</p>
          <button
            className="editor-section__button editor-section__button--primary"
            onClick={handleAdd}
            type="button"
          >
            <Plus />
            Add First Relationship
          </button>
        </div>
      )}
    </div>
  );
}

import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { RelationshipsSection } from '../RelationshipsSection';
import { useCharacterManager } from '@/hooks/useCharacterManager';
import type { CharacterRelationship, Character } from '@/types/character';

vi.mock('@/hooks/useCharacterManager');

describe('RelationshipsSection', () => {
  const mockOnChange = vi.fn();
  const mockGetAllCharacters = vi.fn();

  const mockRelationships: CharacterRelationship[] = [
    {
      character_id: 'char-2',
      character_name: 'Friend Character',
      relationship_type: 'friend',
      description: 'Best friends since childhood',
      dynamic: 'Supportive and loyal',
    },
  ];

  const mockCharacters: Character[] = [
    {
      character_id: 'char-2',
      name: 'Friend Character',
      creation_method: 'wizard',
      creation_timestamp: '2024-01-01T00:00:00Z',
      version: '1.0',
    } as Character,
    {
      character_id: 'char-3',
      name: 'Enemy Character',
      creation_method: 'wizard',
      creation_timestamp: '2024-01-01T00:00:00Z',
      version: '1.0',
    } as Character,
  ];

  beforeEach(() => {
    vi.clearAllMocks();
    mockGetAllCharacters.mockReturnValue(mockCharacters);
    (useCharacterManager as any).mockReturnValue({
      getAllCharacters: mockGetAllCharacters,
    });
  });

  it('should render relationships section', () => {
    render(
      <RelationshipsSection
        characterId="char-1"
        relationships={[]}
        errors={{}}
        onChange={mockOnChange}
      />
    );

    expect(screen.getAllByText(/Relationships/i).length).toBeGreaterThan(0);
  });

  it('should display existing relationships', () => {
    render(
      <RelationshipsSection
        characterId="char-1"
        relationships={mockRelationships}
        errors={{}}
        onChange={mockOnChange}
      />
    );

    expect(screen.getByText('Friend Character')).toBeInTheDocument();
    expect(screen.getByText('friend')).toBeInTheDocument();
    expect(screen.getByText('Best friends since childhood')).toBeInTheDocument();
  });

  it('should show empty state when no relationships', () => {
    render(
      <RelationshipsSection
        characterId="char-1"
        relationships={[]}
        errors={{}}
        onChange={mockOnChange}
      />
    );

    expect(screen.getByText(/No relationships defined yet/i)).toBeInTheDocument();
  });

  it('should show add relationship button', () => {
    render(
      <RelationshipsSection
        characterId="char-1"
        relationships={[]}
        errors={{}}
        onChange={mockOnChange}
      />
    );

    expect(screen.getByRole('button', { name: /Add First Relationship/i })).toBeInTheDocument();
  });

  it('should show add relationship form when add is clicked', () => {
    render(
      <RelationshipsSection
        characterId="char-1"
        relationships={[]}
        errors={{}}
        onChange={mockOnChange}
      />
    );

    const addButton = screen.getByRole('button', { name: /Add First Relationship/i });
    fireEvent.click(addButton);

    expect(screen.getByText(/Add New Relationship/i)).toBeInTheDocument();
    expect(screen.getAllByRole('combobox').length).toBeGreaterThan(0);
  });

  it('should populate character dropdown with available characters', () => {
    render(
      <RelationshipsSection
        characterId="char-1"
        relationships={[]}
        errors={{}}
        onChange={mockOnChange}
      />
    );

    const addButton = screen.getByRole('button', { name: /Add First Relationship/i });
    fireEvent.click(addButton);

    const selects = screen.getAllByRole('combobox');
    expect(selects.length).toBeGreaterThan(0);
    
    // Check that options are present
    expect(screen.getByText('Friend Character')).toBeInTheDocument();
    expect(screen.getByText('Enemy Character')).toBeInTheDocument();
  });

  it('should add new relationship when form is submitted', () => {
    render(
      <RelationshipsSection
        characterId="char-1"
        relationships={[]}
        errors={{}}
        onChange={mockOnChange}
      />
    );

    const addButton = screen.getByRole('button', { name: /Add First Relationship/i });
    fireEvent.click(addButton);

    // Fill form
    const selects = screen.getAllByRole('combobox');
    const characterSelect = selects[0];
    fireEvent.change(characterSelect, { target: { value: 'char-2' } });

    const typeSelect = selects[1];
    fireEvent.change(typeSelect, { target: { value: 'friend' } });

    const inputs = screen.getAllByRole('textbox');
    const descriptionInput = inputs[0];
    fireEvent.change(descriptionInput, { target: { value: 'Best friends' } });

    // Submit
    const saveButton = screen.getByRole('button', { name: /Add/i });
    fireEvent.click(saveButton);

    expect(mockOnChange).toHaveBeenCalledWith([
      {
        character_id: 'char-2',
        character_name: 'Friend Character',
        relationship_type: 'friend',
        description: 'Best friends',
        dynamic: '',
      },
    ]);
  });

  it('should show edit form when edit button is clicked', () => {
    render(
      <RelationshipsSection
        characterId="char-1"
        relationships={mockRelationships}
        errors={{}}
        onChange={mockOnChange}
      />
    );

    const editButton = screen.getByLabelText(/Edit relationship/i);
    fireEvent.click(editButton);

    expect(screen.getAllByRole('combobox').length).toBeGreaterThan(0);
  });

  it('should delete relationship when delete button is clicked', () => {
    render(
      <RelationshipsSection
        characterId="char-1"
        relationships={mockRelationships}
        errors={{}}
        onChange={mockOnChange}
      />
    );

    const deleteButton = screen.getByLabelText(/Delete relationship/i);
    fireEvent.click(deleteButton);

    expect(mockOnChange).toHaveBeenCalledWith([]);
  });

  it('should cancel add when cancel is clicked', () => {
    render(
      <RelationshipsSection
        characterId="char-1"
        relationships={[]}
        errors={{}}
        onChange={mockOnChange}
      />
    );

    const addButton = screen.getByRole('button', { name: /Add First Relationship/i });
    fireEvent.click(addButton);

    const cancelButton = screen.getByRole('button', { name: /Cancel/i });
    fireEvent.click(cancelButton);

    expect(screen.queryByText(/Add New Relationship/i)).not.toBeInTheDocument();
  });

  it('should disable save button if required fields are empty', () => {
    render(
      <RelationshipsSection
        characterId="char-1"
        relationships={[]}
        errors={{}}
        onChange={mockOnChange}
      />
    );

    const addButton = screen.getByRole('button', { name: /Add First Relationship/i });
    fireEvent.click(addButton);

    const saveButton = screen.getByRole('button', { name: /Add/i });
    expect(saveButton).toBeDisabled();
  });
});

/**
 * Beat Selector Component
 * UI component for selecting and configuring narrative beats
 */

import React, { useMemo } from 'react';
import { 
  BeatType, 
  BeatConfig, 
  BeatImportance,
  BEAT_CONFIGS,
  getBeatConfig
} from '@/types/cinematicTypes';
import './BeatSelector.css';

interface BeatSelectorProps {
  value?: BeatType;
  onChange: (beat: BeatType) => void;
  importance?: BeatImportance;
  onImportanceChange?: (importance: BeatImportance) => void;
  disabled?: boolean;
  showDetails?: boolean;
  className?: string;
}

const BEAT_ICONS: Record<BeatType, React.ReactNode> = {
  opening: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
      <polygon points="5 3 19 12 5 21 5 3"/>
    </svg>
  ),
  setup: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
      <circle cx="12" cy="12" r="10"/>
      <line x1="12" y1="16" x2="12" y2="12"/>
    </svg>
  ),
  confrontation: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
      <path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/>
    </svg>
  ),
  climax: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
      <polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/>
    </svg>
  ),
  resolution: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
      <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/>
      <polyline points="22 4 12 14.01 9 11.01"/>
    </svg>
  ),
  transition: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
      <polyline points="9 18 15 12 9 6"/>
    </svg>
  ),
  emotional: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
      <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/>
    </svg>
  ),
  reversal: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
      <polyline points="15 3 21 3 21 9"/>
      <polyline points="9 21 3 21 3 15"/>
      <line x1="21" y1="3" x2="14" y2="10"/>
    </svg>
  ),
  callback: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
      <path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"/>
      <path d="M13.73 21a2 2 0 0 1-3.46 0"/>
    </svg>
  ),
  closing: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
      <rect x="3" y="4" width="18" height="18" rx="2" ry="2"/>
      <line x1="16" y1="2" x2="16" y2="6"/>
    </svg>
  ),
};

const IMPORTANCE_COLORS: Record<BeatImportance, string> = {
  low: '#4ecdc4',
  medium: '#ffe66d',
  high: '#ff6b6b',
  critical: '#e94560',
};

export function BeatSelector({
  value,
  onChange,
  importance,
  onImportanceChange,
  disabled = false,
  showDetails = true,
  className = '',
}: BeatSelectorProps) {
  const selectedConfig = useMemo(
    () => (value ? getBeatConfig(value) : null),
    [value]
  );

  const beats = Object.entries(BEAT_CONFIGS);

  const groupedBeats = useMemo(() => {
    const groups: Record<string, [string, BeatConfig][]> = {
      'Structure': beats.filter(([key]) => 
        ['opening', 'setup', 'closing'].includes(key)
      ),
      'Tension': beats.filter(([key]) => 
        ['confrontation', 'climax', 'reversal'].includes(key)
      ),
      'Emotion': beats.filter(([key]) => 
        ['emotional', 'resolution'].includes(key)
      ),
      'Liaison': beats.filter(([key]) => 
        ['transition', 'callback'].includes(key)
      ),
    };
    return groups;
  }, []);

  return (
    <div className={`beat-selector ${className}`}>
      {value && showDetails && selectedConfig && (
        <div className="beat-details" style={{ borderColor: importance ? IMPORTANCE_COLORS[importance] : '#e94560' }}>
          <div className="beat-details-header">
            <div className="beat-icon" style={{ background: IMPORTANCE_COLORS[importance || 'medium'] }}>
              {BEAT_ICONS[value]}
            </div>
            <div className="beat-info">
              <h4>{selectedConfig.name}</h4>
              <p>{selectedConfig.description}</p>
            </div>
          </div>
          
          <div className="beat-meta">
            <span className="duration">{selectedConfig.duration}</span>
            <span className="purpose">{selectedConfig.purpose}</span>
          </div>

          {selectedConfig.emotionalTone && selectedConfig.emotionalTone.length > 0 && (
            <div className="beat-tones">
              {selectedConfig.emotionalTone.map((tone) => (
                <span key={tone} className="tone-tag">{tone}</span>
              ))}
            </div>
          )}

          {onImportanceChange && (
            <div className="importance-selector">
              <label>Importance:</label>
              <div className="importance-buttons">
                {(['low', 'medium', 'high', 'critical'] as BeatImportance[]).map((imp) => (
                  <button
                    key={imp}
                    type="button"
                    className={`importance-btn ${importance === imp ? 'active' : ''} ${imp}`}
                    onClick={() => onImportanceChange(imp)}
                  >
                    {imp.charAt(0).toUpperCase() + imp.slice(1)}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      <div className="beat-grid">
        {Object.entries(groupedBeats).map(([category, items]) => (
          <div key={category} className="beat-category">
            <h5 className="category-title">{category}</h5>
            <div className="category-items">
              {items.map(([key, config]) => (
                <button
                  key={key}
                  type="button"
                  className={`beat-button ${value === key ? 'selected' : ''}`}
                  onClick={() => onChange(key as BeatType)}
                  disabled={disabled}
                >
                  <div className="beat-icon">{BEAT_ICONS[key as BeatType]}</div>
                  <span className="beat-name">{config.name.split(' ')[0]}</span>
                </button>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

