      id: Date.now().toString(),
      type: type,
      enabled: true,
      feather: 0.2,
      invert: false,
      points: type === 'circle' ? [{ x: 0.5, y: 0.5, radius: 0.3 }] : [],
    };
    setWindows([...windows, newWindow]);
  };

  const handleWindowChange = (id: string, changes: any) => {
    setWindows(windows.map(window => 
      window.id === id ? { ...window, ...changes } : window
