                if (!channelData) return;

                ctx.strokeStyle = channel === 'r' ? '#ff0000' : channel === 'g' ? '#00ff00' : '#0000ff';
                ctx.lineWidth = 1;
                ctx.beginPath();
                channelData.forEach((value, i) => {
                  const x = (i / channelData.length) * canvas.width;
                  const y = canvas.height - (value / 255) * canvas.height;
                  if (i === 0) {
                    ctx.moveTo(x, y);
                  } else {
                    ctx.lineTo(x, y);
                  }
                });
                ctx.stroke();
              });
            }}
          />
        )}
      </div>
    </div>
  );
};

