    render(
      <MockModeToggle 
        enabled={false} 
        onChange={handleChange} 
        showDescription={false}
      />
    );
    
    expect(screen.queryByText(/Using real ComfyUI backend/)).not.toBeInTheDocument();
  });

  it('should show enabled description when enabled', () => {
