                      </button>

                      {line.recordedAudio && (
                        <button
                          onClick={() => playAudio(line.recordedAudio!)}
                          className="action-btn play-btn"
                        >
                          <Play size={16} />
                          ├ëcouter
                        </button>
                      )}
                    </div>

                    {/* G├®n├®ration SAPI */}
                    <div className="action-group">
                      <button
