    localStorage.removeItem('characterCreator_draft');
    setDraftData(null);
  };

  const getGenreString = (genre: unknown): string => {
    // Handle different cases safely
    if (!genre) {
      return 'fantastique';
    }

    if (typeof genre === 'string') {
      return genre;
    }

    if (Array.isArray(genre)) {
      return genre.join(', ');
    }

    return String(genre);
  };

  const generateLlmSuggestions = async () => {
    if (!worldContext) return;

    try {
      // Get properly configured LLM service from ConfigManager
      const llmConfig = ConfigManager.getLLMConfig();
      // Cast to required type to fix type mismatch
      const llmService = new LLMService(llmConfig as any);

      // Safely get genre string with proper error handling
      const genreString = getGenreString(worldContext.genre);
      const rulesString = worldContext.rules && Array.isArray(worldContext.rules)
        ? worldContext.rules.map((r: { rule: string }) => r.rule).join(', ')
        : 'magie et technologie';

      // Enhanced prompts with more world context and JSON formatting
      const namePrompt = `Pour un monde ${genreString} avec ces caract├®ristiques: ${worldContext.description || 'monde fantastique'}, g├®n├¿re 5 noms de personnages originaux et immersifs. Les noms doivent ├¬tre coh├®rents avec le genre et l'ambiance du monde.

R├®ponds UNIQUEMENT avec un objet JSON valide suivant ce format:
{ "suggestions": ["nom1", "nom2", "nom3", "nom4", "nom5"] }`;

      const personalityPrompt = `Dans un monde ${genreString} (${worldContext.atmosphere || 'myst├®rieux'}), d├®cris 4 traits de personnalit├® complexes et int├®ressants pour des personnages. Chaque trait doit ├¬tre unique et adapt├® au contexte du monde.

R├®ponds UNIQUEMENT avec un objet JSON valide suivant ce format:
{ "suggestions": ["trait1", "trait2", "trait3", "trait4"] }`;

      const abilityPrompt = `Pour un monde ${genreString} avec ces r├¿gles: ${rulesString}, quelles seraient 4 capacit├®s ou pouvoirs uniques et ├®quilibr├®s ? Chaque capacit├® doit ├¬tre coh├®rente avec les r├¿gles du monde.

R├®ponds UNIQUEMENT avec un objet JSON valide suivant ce format:
{ "suggestions": ["capacit├®1", "capacit├®2", "capacit├®3", "capacit├®4"] }`;

      const backstoryPrompt = `G├®n├¿re 3 concepts d'histoire personnelle courte pour un personnage dans ce monde: ${worldContext.description || 'monde fantastique'}. Chaque backstory doit ├¬tre intrigante et li├®e aux ├®l├®ments culturels du monde.

R├®ponds UNIQUEMENT avec un objet JSON valide suivant ce format:
{ "suggestions": ["histoire 1...", "histoire 2...", "histoire 3..."] }`;

      // Parallel generation for better performance
      const [nameResponse, personalityResponse, abilityResponse, backstoryResponse] = await Promise.all([
        llmService.generateText(namePrompt, { temperature: 0.8, maxTokens: 150 }),
        llmService.generateText(personalityPrompt, { temperature: 0.7, maxTokens: 150 }),
        llmService.generateText(abilityPrompt, { temperature: 0.7, maxTokens: 150 }),
        llmService.generateText(backstoryPrompt, { temperature: 0.8, maxTokens: 200 })
      ]);

      // Helper function to safely parse the JSON LLM generation
      const parseJsonGeneration = (text: string, fallbackExtract: (str: string) => string[]): string[] => {
        const suggestionSchema = z.object({ suggestions: z.array(z.string()) });
        try {
          const match = text.match(/\{[\s\S]*?\}/);
          if (match) {
            const parsed = JSON.parse(match[0]);
            const validated = suggestionSchema.parse(parsed);
            return validated.suggestions;
          }
        } catch (e) {
          console.warn("Zod validation or JSON parse failed for text:", text, e);
        }
        return fallbackExtract(text);
      };

      const names = parseJsonGeneration(
        nameResponse,
        (res) => res.split(',').map(n => n.trim()).filter(n => n.length > 0).slice(0, 5)
      );
      const personalities = parseJsonGeneration(
        personalityResponse, 
        (res) => res.split(',').map(p => p.trim()).filter(p => p.length > 0).slice(0, 4)
      );
      const abilities = parseJsonGeneration(
        abilityResponse, 
        (res) => res.split(',').map(a => a.trim()).filter(a => a.length > 0).slice(0, 4)
      );
      const backstories = parseJsonGeneration(
        backstoryResponse, 
        (res) => res.split('|').map(b => b.trim()).filter(b => b.length > 0).slice(0, 3)
      );

      setLlmSuggestions({
        name: names,
        personality: personalities,
        abilities: abilities,
        backstory: backstories
      });
    } catch (error) {
      console.error('Erreur lors de la g├®n├®ration des suggestions LLM:', error);
      // Enhanced fallback with world-aware defaults
      setLlmSuggestions({
        name: ['Elyndor', 'Sylvana', 'Tharivol', 'Morwen', 'Kaelith'],
        personality: ['Courageux et d├®termin├®', 'Sage et myst├®rieux', 'Charismatique et ambitieux', 'R├®serv├® et observateur'],
        abilities: ['Manipulation des ├®l├®ments', 'Communication animale', 'Art de l\'illusion', 'Ma├«trise des ombres'],
        backstory: [
          'Ancien guerrier ayant perdu son royaume dans une guerre ancienne',
          'Mage errant ├á la recherche d\'un artefact l├®gendaire',
          'Enfant des rues devenu ma├«tre voleur dans les bas-fonds'
        ]
      });
    }
  };

  const applyTemplate = (templateId: string) => {
    const template = characterTemplates.find(t => t.id === templateId);
    if (template) {
      setSelectedTemplate(templateId);
      updateCharacter('personality', template.baseStats.personality);
      updateCharacter('abilities', template.baseStats.abilities);
    }
  };

  const validateStep = (stepIndex: number): string[] => {
    const errors: string[] = [];

    switch (stepIndex) {
      case 1: // Basic Information
        if (!character.name.trim()) {
          errors.push("Le nom du personnage est obligatoire");
        }
        break;
      case 2: // Personality & Appearance
        if (character.personality.length === 0) {
          errors.push("Au moins un trait de personnalit├® est requis");
        }
        if (!character.appearance.trim()) {
          errors.push("La description de l'apparence est obligatoire");
        }
        break;
      case 3: // History & Context
        if (!character.backstory.trim()) {
          errors.push("L'histoire personnelle est obligatoire");
        }
        if (!character.worldRelation.trim()) {
          errors.push("La relation au monde du projet est obligatoire");
        }
        break;
      case 4: // Abilities & Voice
        if (character.abilities.length === 0) {
          errors.push("Au moins une capacit├® est requise");
        }
        if (!character.voiceId) {
          errors.push("La s├®lection d'une voix SAPI est obligatoire");
        }
        break;
      default:
        break;
    }

    return errors;
  };

  const handleNext = () => {
    if (currentStep < steps.length - 1) {
      const errors = validateStep(currentStep);
      if (errors.length > 0) {
        setValidationErrors({ ...validationErrors, [currentStep]: errors });
        return;
      }

      // Clear any previous errors for this step
      const newErrors = { ...validationErrors };
      delete newErrors[currentStep];
      setValidationErrors(newErrors);

      setCurrentStep(currentStep + 1);
    }
  };

  const handlePrevious = () => {
    if (currentStep > 0) {
