                  placeholder="Entrez le nom du personnage"
                />
                <EnhancedCharacterAssistant
                  // eslint-disable-next-line @typescript-eslint/no-explicit-any
                  worldContext={worldContext as any}
                  // eslint-disable-next-line @typescript-eslint/no-explicit-any
