import React, { useRef, useEffect, useState, useCallback } from 'react';
import { Volume2, VolumeX } from 'lucide-react';
import './AudioWaveform.css';

interface AudioWaveformProps {
  audioUrl?: string;
  duration: number;
  currentTime: number;
  volume?: number;
  isMuted?: boolean;
  onVolumeChange?: (volume: number) => void;
  onMuteToggle?: () => void;
  height?: number;
  className?: string;
}

export const AudioWaveform: React.FC<AudioWaveformProps> = ({
  audioUrl,
  duration,
  currentTime,
  volume = 1,
  isMuted = false,
  onVolumeChange,
  onMuteToggle,
  height = 60,
  className = '',
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [waveformData, setWaveformData] = useState<number[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  // Generate mock waveform data (in a real implementation, this would analyze the audio file)
  const generateWaveformData = useCallback((samples: number = 200) => {
    const data: number[] = [];
    for (let i = 0; i < samples; i++) {
      // Create a more realistic waveform with some variation
      const baseHeight = Math.random() * 0.3 + 0.2; // Base height between 0.2 and 0.5
      const variation = Math.sin(i * 0.1) * 0.2; // Sine wave variation
      const noise = (Math.random() - 0.5) * 0.1; // Random noise
      data.push(Math.max(0.05, Math.min(1, baseHeight + variation + noise)));
    }
    return data;
  }, []);

  // Load and analyze audio file
  useEffect(() => {
    if (!audioUrl) {
      // Generate mock data if no audio URL provided
      setWaveformData(generateWaveformData());
      return;
    }

    setIsLoading(true);
    // In a real implementation, you would:
    // 1. Load the audio file
    // 2. Use Web Audio API to analyze the waveform
    // 3. Generate waveform data from the audio buffer
    // For now, we'll use mock data
    setTimeout(() => {
      setWaveformData(generateWaveformData());
      setIsLoading(false);
    }, 500);
  }, [audioUrl, generateWaveformData]);

  // Draw waveform on canvas
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || waveformData.length === 0) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = canvas.width;
    const canvasHeight = canvas.height;

    // Clear canvas
    ctx.clearRect(0, 0, width, canvasHeight);

    // Draw waveform
    const barWidth = width / waveformData.length;
    const centerY = canvasHeight / 2;

    waveformData.forEach((amplitude, index) => {
      const x = index * barWidth;
      const barHeight = amplitude * canvasHeight * 0.8; // Scale to 80% of canvas height

      // Calculate progress-based coloring
      const progress = currentTime / duration;
      const isPlayed = index / waveformData.length <= progress;

      // Color gradient: blue for unplayed, green for played
      ctx.fillStyle = isPlayed ? '#10b981' : '#3b82f6';

      // Draw the waveform bar (centered vertically)
      ctx.fillRect(x, centerY - barHeight / 2, barWidth - 1, barHeight);
    });

    // Draw progress line
    if (duration > 0) {
      const progressX = (currentTime / duration) * width;
      ctx.strokeStyle = '#ef4444';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(progressX, 0);
      ctx.lineTo(progressX, canvasHeight);
      ctx.stroke();
    }
  }, [waveformData, currentTime, duration]);

  const handleCanvasClick = useCallback((event: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const clickProgress = x / canvas.width;
    const newTime = clickProgress * duration;

    // In a real implementation, you would call onTimeChange here
    // For now, we'll just log it
    console.log('Waveform clicked at time:', newTime);
  }, [duration]);

  return (
    <div className={`audio-waveform ${className}`}>
      <div className="waveform-header">
        <div className="waveform-info">
          <span className="waveform-label">Audio Track</span>
          {audioUrl && <span className="waveform-duration">{formatTime(duration)}</span>}
        </div>

        <div className="waveform-controls">
          {/* Volume slider */}
          <div className="volume-control">
            <button
              className="volume-btn"
              onClick={onMuteToggle}
              title={isMuted ? 'Unmute' : 'Mute'}
            >
              {isMuted ? <VolumeX size={16} /> : <Volume2 size={16} />}
            </button>
            <input
              type="range"
              min="0"
              max="1"
              step="0.01"
              value={isMuted ? 0 : volume}
              onChange={(e) => onVolumeChange?.(parseFloat(e.target.value))}
              className="volume-slider"
            />
            <span className="volume-value">{Math.round((isMuted ? 0 : volume) * 100)}%</span>
          </div>
        </div>
      </div>

      <div className="waveform-canvas-container">
        {isLoading ? (
          <div className="waveform-loading">
            <div className="loading-spinner"></div>
            <span>Loading audio...</span>
          </div>
        ) : (
          <canvas
            ref={canvasRef}
            width={800}
            height={height}
            className="waveform-canvas"
            onClick={handleCanvasClick}
            style={{ cursor: 'pointer' }}
          />
        )}
      </div>
    </div>
  );
};

// Utility function to format time
function formatTime(seconds: number): string {
  const mins = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60);
  return `${mins}:${secs.toString().padStart(2, '0')}`;
}

import React, { useMemo } from 'react';

interface TimelineRulerProps {
  duration: number;
  zoom: number;
  currentTime: number;
  fps?: number;
}

export function TimelineRuler({ duration, zoom, currentTime, fps = 30 }: TimelineRulerProps) {
  // Calculate major and minor tick intervals based on zoom
  const tickIntervals = useMemo(() => {
    const totalWidth = duration * zoom * 100; // pixels per second * zoom

    // Major ticks (with time labels)
    let majorInterval = 1; // seconds
    if (totalWidth < 500) majorInterval = 5;
    else if (totalWidth < 1000) majorInterval = 2;
    else if (totalWidth > 2000) majorInterval = 0.5;

    // Minor ticks (without labels)
    const minorInterval = majorInterval / 5;

    return { major: majorInterval, minor: minorInterval };
  }, [duration, zoom]);

  // Generate tick marks
  const ticks = useMemo(() => {
    const ticks = [];
    const { major, minor } = tickIntervals;

    // Calculate visible time range (this could be enhanced with scrolling)
    const startTime = 0;
    const endTime = duration;

    // Major ticks
    for (let time = startTime; time <= endTime; time += major) {
      const position = (time / duration) * 100;
      ticks.push({
        time,
        position,
        type: 'major',
        label: formatTime(time)
      });
    }

    // Minor ticks
    for (let time = startTime; time <= endTime; time += minor) {
      // Skip if there's already a major tick at this position
      if (time % major !== 0) {
        const position = (time / duration) * 100;
        ticks.push({
          time,
          position,
          type: 'minor',
          label: null
        });
      }
    }

    return ticks;
  }, [duration, tickIntervals]);

  // Current time indicator
  const currentTimePosition = (currentTime / duration) * 100;

  return (
    <div className="timeline-ruler">
      <div className="ruler-track">
        {ticks.map((tick, index) => (
          <div
            key={`${tick.type}-${tick.time}-${index}`}
            className={`ruler-tick ${tick.type}`}
            style={{ left: `${tick.position}%` }}
          >
            {tick.type === 'major' && tick.label && (
              <span className="tick-label">{tick.label}</span>
            )}
          </div>
        ))}

        {/* Current time indicator */}
        <div
          className="current-time-indicator"
          style={{ left: `${currentTimePosition}%` }}
        >
          <div className="time-line" />
          <div className="time-caret" />
        </div>
      </div>
    </div>
  );
}

// Format time as MM:SS, HH:MM:SS, or HH:MM:SS:FF (with frames)
function formatTime(seconds: number, showFrames: boolean = false): string {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = Math.floor(seconds % 60);
  const frames = showFrames ? Math.floor((seconds % 1) * 30) : 0; // Assuming 30fps

  if (hours > 0) {
    if (showFrames) {
      return `${hours}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}:${frames.toString().padStart(2, '0')}`;
    } else {
      return `${hours}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
    }
  } else {
    if (showFrames) {
      return `${minutes}:${secs.toString().padStart(2, '0')}:${frames.toString().padStart(2, '0')}`;
    } else {
      return `${minutes}:${secs.toString().padStart(2, '0')}`;
    }
  }
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Play, Pause, SkipBack, SkipForward, RotateCcw, ZoomIn, ZoomOut } from 'lucide-react';

interface TimelineScrubberProps {
  currentTime: number;
  duration: number;
  zoom: number;
  isPlaying: boolean;
  onTimeChange: (time: number) => void;
  onPlayPause: () => void;
  onZoomChange: (zoom: number) => void;
  onFrameStep: (direction: 'forward' | 'backward') => void;
  loopEnabled?: boolean;
  onLoopToggle?: () => void;
}

export function TimelineScrubber({
  currentTime,
  duration,
  zoom,
  isPlaying,
  onTimeChange,
  onPlayPause,
  onZoomChange,
  onFrameStep,
  loopEnabled = false,
  onLoopToggle
}: TimelineScrubberProps) {
  const [isDragging, setIsDragging] = useState(false);
  const [dragStartX, setDragStartX] = useState(0);
  const [dragStartTime, setDragStartTime] = useState(0);
  const scrubberRef = useRef<HTMLDivElement>(null);

  // Format time as HH:MM:SS:FF (frames)
  const formatTime = useCallback((time: number) => {
    const hours = Math.floor(time / 3600);
    const minutes = Math.floor((time % 3600) / 60);
    const seconds = Math.floor(time % 60);
    const frames = Math.floor((time % 1) * 30); // Assuming 30fps

    return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}:${frames.toString().padStart(2, '0')}`;
  }, []);

  // Handle scrubber click/drag
  const handleScrubberInteraction = useCallback((clientX: number) => {
    if (!scrubberRef.current) return;

    const rect = scrubberRef.current.getBoundingClientRect();
    const percentage = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
    const newTime = percentage * duration;

    onTimeChange(newTime);
  }, [duration, onTimeChange]);

  // Mouse event handlers
  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    setIsDragging(true);
    setDragStartX(e.clientX);
    setDragStartTime(currentTime);
    handleScrubberInteraction(e.clientX);
  }, [currentTime, handleScrubberInteraction]);

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (isDragging) {
      handleScrubberInteraction(e.clientX);
    }
  }, [isDragging, handleScrubberInteraction]);

  const handleMouseUp = useCallback(() => {
    setIsDragging(false);
  }, []);

  // Global mouse events for dragging
  useEffect(() => {
    if (isDragging) {
      document.addEventListener('mousemove', handleMouseMove);
      document.addEventListener('mouseup', handleMouseUp);
      return () => {
        document.removeEventListener('mousemove', handleMouseMove);
        document.removeEventListener('mouseup', handleMouseUp);
      };
    }
  }, [isDragging, handleMouseMove, handleMouseUp]);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Only handle shortcuts when not typing in an input
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) {
        return;
      }

      switch (e.key) {
        case ' ':
          e.preventDefault();
          onPlayPause();
          break;
        case 'ArrowLeft':
          if (e.shiftKey) {
            e.preventDefault();
            onFrameStep('backward');
          }
          break;
        case 'ArrowRight':
          if (e.shiftKey) {
            e.preventDefault();
            onFrameStep('forward');
          }
          break;
        case 'z':
        case 'Z':
          if (e.ctrlKey || e.metaKey) {
            e.preventDefault();
            // Toggle zoom (this could be enhanced with zoom to fit, etc.)
            onZoomChange(zoom === 1 ? 2 : 1);
          }
          break;
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [onPlayPause, onFrameStep, onZoomChange, zoom]);

  const progressPercentage = duration > 0 ? (currentTime / duration) * 100 : 0;

  return (
    <div className="timeline-scrubber">
      {/* Time Display */}
      <div className="time-display">
        <span className="current-time">{formatTime(currentTime)}</span>
        <span className="separator">/</span>
        <span className="total-time">{formatTime(duration)}</span>
      </div>

      {/* Playback Controls */}
      <div className="playback-controls">
        <button
          className="control-btn"
          onClick={() => onTimeChange(0)}
          title="Go to Start (Home)"
        >
          <SkipBack size={16} />
        </button>

        <button
          className="control-btn frame-step"
          onClick={() => onFrameStep('backward')}
          title="Previous Frame (Shift+ÔåÉ)"
        >
          <SkipBack size={12} />
        </button>

        <button
          className="control-btn play-pause"
          onClick={onPlayPause}
          title={isPlaying ? 'Pause (Space)' : 'Play (Space)'}
        >
          {isPlaying ? <Pause size={16} /> : <Play size={16} />}
        </button>

        <button
          className="control-btn frame-step"
          onClick={() => onFrameStep('forward')}
          title="Next Frame (Shift+ÔåÆ)"
        >
          <SkipForward size={12} />
        </button>

        <button
          className="control-btn"
          onClick={() => onTimeChange(duration)}
          title="Go to End (End)"
        >
          <SkipForward size={16} />
        </button>

        {onLoopToggle && (
          <button
            className={`control-btn loop-btn ${loopEnabled ? 'active' : ''}`}
            onClick={onLoopToggle}
            title="Loop Playback"
          >
            <RotateCcw size={14} />
          </button>
        )}
      </div>

      {/* Scrubber Bar */}
      <div className="scrubber-container">
        <div
          ref={scrubberRef}
          className="scrubber-bar"
          onMouseDown={handleMouseDown}
        >
          <div
            className="scrubber-progress"
            style={{ width: `${progressPercentage}%` }}
          />
          <div
            className="scrubber-handle"
            style={{ left: `${progressPercentage}%` }}
          />
        </div>
      </div>

      {/* Zoom Controls */}
      <div className="zoom-controls">
        <button
          className="zoom-btn"
          onClick={() => onZoomChange(Math.max(0.1, zoom - 0.1))}
          title="Zoom Out"
        >
          <ZoomOut size={14} />
        </button>

        <span className="zoom-level">{Math.round(zoom * 100)}%</span>

        <button
          className="zoom-btn"
          onClick={() => onZoomChange(Math.min(5, zoom + 0.1))}
          title="Zoom In"
        >
          <ZoomIn size={14} />
        </button>
      </div>
    </div>
  );
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Volume2, Plus, X } from 'lucide-react';
import './VolumeKeyframes.css';

interface VolumeKeyframe {
  id: string;
  time: number;
  volume: number;
}

interface VolumeKeyframesProps {
  duration: number;
  currentTime: number;
  keyframes: VolumeKeyframe[];
  onKeyframesChange: (keyframes: VolumeKeyframe[]) => void;
  height?: number;
  className?: string;
}

export const VolumeKeyframes: React.FC<VolumeKeyframesProps> = ({
  duration,
  currentTime,
  keyframes,
  onKeyframesChange,
  height = 40,
  className = '',
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [draggedKeyframe, setDraggedKeyframe] = useState<string | null>(null);
  const [isAddingKeyframe, setIsAddingKeyframe] = useState(false);

  // Get volume at current time (interpolated between keyframes)
  const getCurrentVolume = useCallback((time: number): number => {
    if (keyframes.length === 0) return 1;

    // Sort keyframes by time
    const sortedKeyframes = [...keyframes].sort((a, b) => a.time - b.time);

    // Find keyframes before and after current time
    const beforeKeyframe = sortedKeyframes.filter(kf => kf.time <= time).pop();
    const afterKeyframe = sortedKeyframes.filter(kf => kf.time > time)[0];

    if (!beforeKeyframe && !afterKeyframe) return 1;
    if (!beforeKeyframe) return afterKeyframe.volume;
    if (!afterKeyframe) return beforeKeyframe.volume;

    // Linear interpolation between keyframes
    const timeDiff = afterKeyframe.time - beforeKeyframe.time;
    const volumeDiff = afterKeyframe.volume - beforeKeyframe.volume;
    const progress = (time - beforeKeyframe.time) / timeDiff;

    return beforeKeyframe.volume + (volumeDiff * progress);
  }, [keyframes]);

  // Add a new keyframe at current time
  const addKeyframe = useCallback(() => {
    const currentVolume = getCurrentVolume(currentTime);
    const newKeyframe: VolumeKeyframe = {
      id: `kf_${Date.now()}`,
      time: currentTime,
      volume: currentVolume,
    };

    onKeyframesChange([...keyframes, newKeyframe]);
  }, [currentTime, keyframes, getCurrentVolume, onKeyframesChange]);

  // Remove a keyframe
  const removeKeyframe = useCallback((keyframeId: string) => {
    onKeyframesChange(keyframes.filter(kf => kf.id !== keyframeId));
  }, [keyframes, onKeyframesChange]);

  // Update keyframe position/volume
  const updateKeyframe = useCallback((keyframeId: string, updates: Partial<VolumeKeyframe>) => {
    onKeyframesChange(
      keyframes.map(kf =>
        kf.id === keyframeId ? { ...kf, ...updates } : kf
      )
    );
  }, [keyframes, onKeyframesChange]);

  // Handle mouse events for dragging keyframes
  const handleMouseDown = useCallback((keyframeId: string) => {
    setDraggedKeyframe(keyframeId);
  }, []);

  const handleMouseMove = useCallback((event: React.MouseEvent) => {
    if (!draggedKeyframe || !containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;

    // Calculate new time and volume
    const newTime = Math.max(0, Math.min(duration, (x / rect.width) * duration));
    const newVolume = Math.max(0, Math.min(1, 1 - (y / rect.height)));

    updateKeyframe(draggedKeyframe, { time: newTime, volume: newVolume });
  }, [draggedKeyframe, duration, updateKeyframe]);

  const handleMouseUp = useCallback(() => {
    setDraggedKeyframe(null);
  }, []);

  // Handle double-click to add keyframe
  const handleDoubleClick = useCallback((event: React.MouseEvent) => {
    if (!containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const newTime = Math.max(0, Math.min(duration, (x / rect.width) * duration));

    const newKeyframe: VolumeKeyframe = {
      id: `kf_${Date.now()}`,
      time: newTime,
      volume: getCurrentVolume(newTime),
    };

    onKeyframesChange([...keyframes, newKeyframe]);
  }, [duration, keyframes, getCurrentVolume, onKeyframesChange]);

  // Draw the volume curve
  useEffect(() => {
    // This would draw the interpolated curve between keyframes
    // For now, we'll use CSS to show the keyframes
  }, [keyframes]);

  return (
    <div className={`volume-keyframes ${className}`}>
      <div className="keyframes-header">
        <div className="keyframes-label">
          <Volume2 size={14} />
          <span>Volume</span>
        </div>

        <button
          className="add-keyframe-btn"
          onClick={addKeyframe}
          title="Add keyframe at current time"
        >
          <Plus size={14} />
        </button>
      </div>

      <div
        ref={containerRef}
        className="keyframes-container"
        style={{ height }}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onDoubleClick={handleDoubleClick}
      >
        {/* Volume curve background */}
        <div className="volume-curve">
          {keyframes
            .sort((a, b) => a.time - b.time)
            .map((keyframe, index, sortedKeyframes) => {
              const nextKeyframe = sortedKeyframes[index + 1];
              if (!nextKeyframe) return null;

              const startX = (keyframe.time / duration) * 100;
              const endX = (nextKeyframe.time / duration) * 100;
              const startY = (1 - keyframe.volume) * 100;
              const endY = (1 - nextKeyframe.volume) * 100;

              return (
                <svg
                  key={`curve-${keyframe.id}-${nextKeyframe.id}`}
                  className="curve-segment"
                  style={{
                    position: 'absolute',
                    left: `${startX}%`,
                    top: 0,
                    width: `${endX - startX}%`,
                    height: '100%',
                  }}
                >
                  <line
                    x1="0%"
                    y1={`${startY}%`}
                    x2="100%"
                    y2={`${endY}%`}
                    stroke="#3b82f6"
                    strokeWidth="2"
                  />
                </svg>
              );
            })}
        </div>

        {/* Keyframe points */}
        {keyframes.map((keyframe) => (
          <div
            key={keyframe.id}
            className={`keyframe-point ${draggedKeyframe === keyframe.id ? 'dragging' : ''}`}
            style={{
              left: `${(keyframe.time / duration) * 100}%`,
              top: `${(1 - keyframe.volume) * 100}%`,
            }}
            onMouseDown={() => handleMouseDown(keyframe.id)}
            title={`Time: ${formatTime(keyframe.time)}, Volume: ${Math.round(keyframe.volume * 100)}%`}
          >
            <div className="keyframe-handle">
              <button
                className="keyframe-delete"
                onClick={(e) => {
                  e.stopPropagation();
                  removeKeyframe(keyframe.id);
                }}
                title="Delete keyframe"
              >
                <X size={8} />
              </button>
            </div>
          </div>
        ))}

        {/* Current time indicator */}
        <div
          className="current-time-indicator"
          style={{ left: `${(currentTime / duration) * 100}%` }}
        />
      </div>

      {/* Volume value display */}
      <div className="volume-display">
        <span className="current-volume">
          {Math.round(getCurrentVolume(currentTime) * 100)}%
        </span>
      </div>
    </div>
  );
};

// Utility function to format time
function formatTime(seconds: number): string {
  const mins = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60);
  const ms = Math.floor((seconds % 1) * 100);
  return `${mins}:${secs.toString().padStart(2, '0')}.${ms.toString().padStart(2, '0')}`;
}

