/**
 * Generation Button Toolbar Component
 * 
 * Container component that displays generation buttons in editor and dashboard contexts.
 * Manages button visibility, dialog state, and context-aware behavior.
 * Enhanced with re-generation group and export film button.
 * 
 * Requirements: 5.1, 5.2
 */

import React, { useState, useCallback, lazy, Suspense } from 'react';
import { PromptGenerationButton } from './PromptGenerationButton';
import { ImageGenerationButton } from './ImageGenerationButton';
import { VideoGenerationButton } from './VideoGenerationButton';
import { AudioGenerationButton } from './AudioGenerationButton';
import { RegenerationGroup, ExportFilmButton } from './RegenerationButtons';
import { useGenerationStore } from '../../stores/generationStore';
import type { Shot, Sequence } from '../../types';
import type { GeneratedAsset } from '../../types/generation';
import './GenerationButtonToolbar.css';

// Lazy load dialog components for better performance
const PromptGenerationDialog = lazy(() => import('./PromptGenerationDialog').then(m => ({ default: m.PromptGenerationDialog })));
const ImageGenerationDialog = lazy(() => import('./ImageGenerationDialog').then(m => ({ default: m.ImageGenerationDialog })));
const VideoGenerationDialog = lazy(() => import('./VideoGenerationDialog').then(m => ({ default: m.VideoGenerationDialog })));
const AudioGenerationDialog = lazy(() => import('./AudioGenerationDialog').then(m => ({ default: m.AudioGenerationDialog })));
const GenerationProgressModal = lazy(() => import('./GenerationProgressModal').then(m => ({ default: m.GenerationProgressModal })));

export interface GenerationButtonToolbarProps {
  /**
   * Context where toolbar is displayed
   */
  context: 'editor' | 'dashboard';

  /**
   * Current shot (editor context)
   */
  currentShot?: Shot;

  /**
   * Current sequence (editor context)
   */
  currentSequence?: Sequence;

  /**
   * Callback when generation completes
   */
  onGenerationComplete?: (asset: GeneratedAsset) => void;

  /**
   * Callback for export film
   */
  onExportFilm?: () => void;

  /**
   * Custom className for styling
   */
  className?: string;
}

/**
 * Generation Button Toolbar
 * 
 * Displays generation buttons in a toolbar layout.
 * Adapts to editor or dashboard context.
 * Manages dialog state and generation workflow.
 */
export const GenerationButtonToolbar: React.FC<GenerationButtonToolbarProps> = ({
  context,
  currentShot,
  currentSequence,
  onGenerationComplete,
  onExportFilm,
  className = '',
}) => {
  const { currentPipeline } = useGenerationStore();

  // Dialog state management
  const [activeDialog, setActiveDialog] = useState<'prompt' | 'image' | 'video' | 'audio' | null>(null);

  // Determine if generation is in progress
  const isGenerating = currentPipeline?.stages.prompt?.status === 'in_progress' ||
    currentPipeline?.stages.image?.status === 'in_progress' ||
    currentPipeline?.stages.video?.status === 'in_progress' ||
    currentPipeline?.stages.audio?.status === 'in_progress';

  // Button click handlers
  const handlePromptClick = useCallback(() => {
    setActiveDialog('prompt');
  }, []);

  const handleImageClick = useCallback(() => {
    setActiveDialog('image');
  }, []);

  const handleVideoClick = useCallback(() => {
    setActiveDialog('video');
  }, []);

  const handleAudioClick = useCallback(() => {
    setActiveDialog('audio');
  }, []);

  // Dialog close handlers
  const handleCloseDialog = useCallback(() => {
    setActiveDialog(null);
  }, []);

  // Generation complete handler
  const handleGenerationComplete = useCallback((asset: GeneratedAsset) => {
    if (onGenerationComplete) {
      onGenerationComplete(asset);
    }
  }, [onGenerationComplete]);

  // Determine toolbar layout based on context
  const toolbarClass = context === 'editor'
    ? 'generation-toolbar-editor'
    : 'generation-toolbar-dashboard';

  return (
    <>
      {/* Toolbar Container */}
      <div className={`generation-button-toolbar ${toolbarClass} ${className}`}>
        <div className="toolbar-buttons">
          <PromptGenerationButton
            onClick={handlePromptClick}
            isGenerating={currentPipeline?.stages.prompt?.status === 'in_progress'}
          />

          <ImageGenerationButton
            onClick={handleImageClick}
            isGenerating={currentPipeline?.stages.image?.status === 'in_progress'}
          />

          <VideoGenerationButton
            onClick={handleVideoClick}
            isGenerating={currentPipeline?.stages.video?.status === 'in_progress'}
          />

          <AudioGenerationButton
            onClick={handleAudioClick}
            isGenerating={currentPipeline?.stages.audio?.status === 'in_progress'}
          />
        </div>

        {/* Re-generation buttons ÔÇö shown when a shot is selected */}
        {context === 'editor' && currentShot && (
          <div className="toolbar-regen-section">
            <span className="toolbar-regen-label">R├®g├®n├®rer :</span>
            <RegenerationGroup
              shotId={currentShot.id}
              shotLabel={currentShot.title}
              size="sm"
              types={['image', 'text', 'audio']}
            />
          </div>
        )}

        {/* Export Film button ÔÇö shown in dashboard */}
        {context === 'dashboard' && (
          <div className="toolbar-export-section">
            <ExportFilmButton
              onExport={onExportFilm}
              disabled={isGenerating}
            />
          </div>
        )}
      </div>

      {/* Dialogs - Lazy loaded with Suspense */}
      <Suspense fallback={<div className="dialog-loading">Loading...</div>}>
        {activeDialog === 'prompt' && (
          <PromptGenerationDialog
            isOpen={true}
            onClose={handleCloseDialog}
            onGenerate={(prompt) => {
              handleGenerationComplete({
                id: crypto.randomUUID(),
                type: 'prompt',
                url: '',
                metadata: {
                  generationParams: { text: prompt.text, categories: prompt.categories },
                  fileSize: 0,
                  format: 'text',
                },
                relatedAssets: [],
                timestamp: Date.now(),
              });
              handleCloseDialog();
            }}
          />
        )}

        {activeDialog === 'image' && (
          <ImageGenerationDialog
            isOpen={true}
            onClose={handleCloseDialog}
            initialPrompt={currentPipeline?.stages.prompt?.result?.text}
          />
        )}

        {activeDialog === 'video' && (
          <VideoGenerationDialog
            isOpen={true}
            onClose={handleCloseDialog}
            sourceImage={currentPipeline?.stages.image?.result}
          />
        )}

        {activeDialog === 'audio' && (
          <AudioGenerationDialog
            isOpen={true}
            onClose={handleCloseDialog}
          />
        )}
      </Suspense>

      {/* Progress Modal - Lazy loaded with Suspense */}
      {isGenerating && currentPipeline && (
        <Suspense fallback={<div className="modal-loading">Loading progress...</div>}>
          <GenerationProgressModal
            isOpen={isGenerating}
            generationType={
              currentPipeline.stages.prompt?.status === 'in_progress' ? 'prompt' :
                currentPipeline.stages.image?.status === 'in_progress' ? 'image' :
                  currentPipeline.stages.video?.status === 'in_progress' ? 'video' :
                    'audio'
            }
            progress={
              currentPipeline.stages.prompt?.progress ||
              currentPipeline.stages.image?.progress ||
              currentPipeline.stages.video?.progress ||
              currentPipeline.stages.audio?.progress ||
              {
                stage: 'Initializing',
                stageProgress: 0,
                overallProgress: 0,
                estimatedTimeRemaining: 0,
                message: 'Starting generation...',
                cancellable: false,
              }
            }
            onCancel={() => {
              // Cancel logic would go here
            }}
          />
        </Suspense>
      )}
    </>
  );
};

/**
 * Generation History Panel Component
 * 
 * Displays all previous generations with thumbnails, metadata, and version comparison.
 * Allows users to view history, select entries, display parameters, and regenerate.
 * 
 * Requirements: 14.2, 14.5
 */

import React, { useState, useMemo } from 'react';
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Separator } from '../ui/separator';
import { Input } from '../ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/select';
import { ScrollArea } from '../ui/scroll-area';
import {
  History,
  Image as ImageIcon,
  Video as VideoIcon,
  Volume2 as AudioIcon,
  FileText,
  Calendar,
  RefreshCw,
  Search,
  Filter,
  ArrowUpDown,
  GitCompare,
  X,
} from 'lucide-react';
import type { HistoryEntry, GeneratedAsset } from '../../types/generation';
import { generationHistoryService } from '../../services/GenerationHistoryService';

export interface GenerationHistoryPanelProps {
  /**
   * Callback when a history entry is selected
   */
  onEntrySelect?: (entry: HistoryEntry) => void;
  
  /**
   * Callback when regenerate is clicked
   */
  onRegenerate?: (entry: HistoryEntry) => void;
  
  /**
   * Custom className for styling
   */
  className?: string;
}

/**
 * Filter options for history
 */
interface HistoryFilters {
  type: 'all' | 'prompt' | 'image' | 'video' | 'audio';
  searchQuery: string;
  sortBy: 'timestamp' | 'version';
  sortOrder: 'asc' | 'desc';
}

/**
 * Format timestamp for display
 */
const formatTimestamp = (timestamp: number): string => {
  const date = new Date(timestamp);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffMins = Math.floor(diffMs / 60000);
  const diffHours = Math.floor(diffMs / 3600000);
  const diffDays = Math.floor(diffMs / 86400000);
  
  if (diffMins < 1) return 'Just now';
  if (diffMins < 60) return `${diffMins}m ago`;
  if (diffHours < 24) return `${diffHours}h ago`;
  if (diffDays < 7) return `${diffDays}d ago`;
  
  return date.toLocaleDateString();
};

/**
 * Get asset type icon
 */
const getAssetIcon = (type: HistoryEntry['type']) => {
  switch (type) {
    case 'image':
      return ImageIcon;
    case 'video':
      return VideoIcon;
    case 'audio':
      return AudioIcon;
    case 'prompt':
      return FileText;
    default:
      return FileText;
  }
};

/**
 * Get asset type label
 */
const getAssetTypeLabel = (type: HistoryEntry['type']): string => {
  switch (type) {
    case 'image':
      return 'Image';
    case 'video':
      return 'Video';
    case 'audio':
      return 'Audio';
    case 'prompt':
      return 'Prompt';
    default:
      return 'Asset';
  }
};

/**
 * Generation History Panel
 * 
 * Displays all previous generations with filtering, sorting, and version comparison.
 */
export const GenerationHistoryPanel: React.FC<GenerationHistoryPanelProps> = ({
  onEntrySelect,
  onRegenerate,
  className = '',
}) => {
  // State
  const [selectedEntry, setSelectedEntry] = useState<HistoryEntry | null>(null);
  const [comparisonEntry, setComparisonEntry] = useState<HistoryEntry | null>(null);
  const [filters, setFilters] = useState<HistoryFilters>({
    type: 'all',
    searchQuery: '',
    sortBy: 'timestamp',
    sortOrder: 'desc',
  });
  
  // Get all history entries
  const allEntries = useMemo(() => {
    return generationHistoryService.getAllEntries();
  }, []);
  
  // Filter and sort entries
  const filteredEntries = useMemo(() => {
    let entries = [...allEntries];
    
    // Filter by type
    if (filters.type !== 'all') {
      entries = entries.filter(entry => entry.type === filters.type);
    }
    
    // Filter by search query
    if (filters.searchQuery) {
      const query = filters.searchQuery.toLowerCase();
      entries = entries.filter(entry => {
        // Search in parameters
        const paramsStr = JSON.stringify(entry.params).toLowerCase();
        return paramsStr.includes(query);
      });
    }
    
    // Sort entries
    entries.sort((a, b) => {
      let comparison = 0;
      
      if (filters.sortBy === 'timestamp') {
        comparison = a.timestamp - b.timestamp;
      } else if (filters.sortBy === 'version') {
        comparison = a.version - b.version;
      }
      
      return filters.sortOrder === 'asc' ? comparison : -comparison;
    });
    
    return entries;
  }, [allEntries, filters]);
  
  // Get statistics
  const statistics = useMemo(() => {
    return generationHistoryService.getStatistics();
  }, [allEntries]);
  
  /**
   * Handle entry selection
   */
  const handleEntryClick = (entry: HistoryEntry) => {
    setSelectedEntry(entry);
    if (onEntrySelect) {
      onEntrySelect(entry);
    }
  };
  
  /**
   * Handle regenerate
   */
  const handleRegenerate = (entry: HistoryEntry) => {
    if (onRegenerate) {
      onRegenerate(entry);
    }
  };
  
  /**
   * Handle comparison mode
   */
  const handleCompare = (entry: HistoryEntry) => {
    if (!comparisonEntry) {
      setComparisonEntry(entry);
    } else {
      // Already in comparison mode, clear it
      setComparisonEntry(null);
    }
  };
  
  /**
   * Clear comparison
   */
  const clearComparison = () => {
    setComparisonEntry(null);
  };
  
  /**
   * Update filter
   */
  const updateFilter = <K extends keyof HistoryFilters>(
    key: K,
    value: HistoryFilters[K]
  ) => {
    setFilters(prev => ({ ...prev, [key]: value }));
  };
  
  return (
    <div className={`space-y-4 ${className}`}>
      {/* Header */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <History className="h-5 w-5" />
            Generation History
          </CardTitle>
          <CardDescription>
            View all previous generations with parameters and versions
          </CardDescription>
        </CardHeader>
        
        <CardContent className="space-y-4">
          {/* Statistics */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="space-y-1">
              <p className="text-sm text-muted-foreground">Total Entries</p>
              <p className="text-2xl font-bold">{statistics.totalEntries}</p>
            </div>
            <div className="space-y-1">
              <p className="text-sm text-muted-foreground">Images</p>
              <p className="text-2xl font-bold">{statistics.entriesByType.image || 0}</p>
            </div>
            <div className="space-y-1">
              <p className="text-sm text-muted-foreground">Videos</p>
              <p className="text-2xl font-bold">{statistics.entriesByType.video || 0}</p>
            </div>
            <div className="space-y-1">
              <p className="text-sm text-muted-foreground">Audio</p>
              <p className="text-2xl font-bold">{statistics.entriesByType.audio || 0}</p>
            </div>
          </div>
          
          <Separator />
          
          {/* Filters */}
          <div className="space-y-3">
            <div className="flex items-center gap-2">
              <Filter className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm font-medium">Filters</span>
            </div>
            
            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
              {/* Type Filter */}
              <Select
                value={filters.type}
                onValueChange={(value) => updateFilter('type', value as HistoryFilters['type'])}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Filter by type" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Types</SelectItem>
                  <SelectItem value="prompt">Prompts</SelectItem>
                  <SelectItem value="image">Images</SelectItem>
                  <SelectItem value="video">Videos</SelectItem>
                  <SelectItem value="audio">Audio</SelectItem>
                </SelectContent>
              </Select>
              
              {/* Sort By */}
              <Select
                value={filters.sortBy}
                onValueChange={(value) => updateFilter('sortBy', value as HistoryFilters['sortBy'])}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Sort by" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="timestamp">Date</SelectItem>
                  <SelectItem value="version">Version</SelectItem>
                </SelectContent>
              </Select>
              
              {/* Sort Order */}
              <Button
                variant="outline"
                onClick={() => updateFilter('sortOrder', filters.sortOrder === 'asc' ? 'desc' : 'asc')}
              >
                <ArrowUpDown className="mr-2 h-4 w-4" />
                {filters.sortOrder === 'asc' ? 'Ascending' : 'Descending'}
              </Button>
            </div>
            
            {/* Search */}
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                type="text"
                placeholder="Search parameters..."
                value={filters.searchQuery}
                onChange={(e) => updateFilter('searchQuery', e.target.value)}
                className="pl-9"
              />
            </div>
          </div>
        </CardContent>
      </Card>
      
      {/* Comparison Mode Banner */}
      {comparisonEntry && (
        <Card className="border-primary">
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <GitCompare className="h-5 w-5 text-primary" />
                <span className="font-medium">Comparison Mode Active</span>
                <Badge variant="secondary">
                  Comparing v{comparisonEntry.version}
                </Badge>
              </div>
              <Button variant="ghost" size="sm" onClick={clearComparison}>
                <X className="h-4 w-4" />
              </Button>
            </div>
            <p className="text-sm text-muted-foreground mt-2">
              Select another entry to compare parameters
            </p>
          </CardContent>
        </Card>
      )}
      
      {/* History List */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base">
            History Entries ({filteredEntries.length})
          </CardTitle>
        </CardHeader>
        
        <CardContent>
          <ScrollArea className="h-[600px] pr-4">
            {filteredEntries.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-12 text-center">
                <History className="h-12 w-12 text-muted-foreground mb-4" />
                <p className="text-muted-foreground">No history entries found</p>
                <p className="text-sm text-muted-foreground mt-1">
                  Generate some content to see it here
                </p>
              </div>
            ) : (
              <div className="space-y-3">
                {filteredEntries.map((entry) => (
                  <HistoryEntryCard
                    key={entry.id}
                    entry={entry}
                    isSelected={selectedEntry?.id === entry.id}
                    isComparing={comparisonEntry?.id === entry.id}
                    onClick={() => handleEntryClick(entry)}
                    onRegenerate={() => handleRegenerate(entry)}
                    onCompare={() => handleCompare(entry)}
                  />
                ))}
              </div>
            )}
          </ScrollArea>
        </CardContent>
      </Card>
      
      {/* Selected Entry Details */}
      {selectedEntry && (
        <HistoryEntryDetails
          entry={selectedEntry}
          comparisonEntry={comparisonEntry}
          onRegenerate={() => handleRegenerate(selectedEntry)}
        />
      )}
    </div>
  );
};

/**
 * History Entry Card Component
 */
interface HistoryEntryCardProps {
  entry: HistoryEntry;
  isSelected: boolean;
  isComparing: boolean;
  onClick: () => void;
  onRegenerate: () => void;
  onCompare: () => void;
}

const HistoryEntryCard: React.FC<HistoryEntryCardProps> = ({
  entry,
  isSelected,
  isComparing,
  onClick,
  onRegenerate,
  onCompare,
}) => {
  const AssetIcon = getAssetIcon(entry.type);
  const assetLabel = getAssetTypeLabel(entry.type);
  
  return (
    <button
      onClick={onClick}
      className={`w-full text-left p-4 rounded-lg border transition-colors ${
        isSelected
          ? 'border-primary bg-primary/5'
          : isComparing
          ? 'border-blue-500 bg-blue-500/5'
          : 'border-border hover:border-primary/50'
      }`}
    >
      <div className="flex items-start gap-3">
        {/* Thumbnail */}
        <div className="flex-shrink-0 w-16 h-16 rounded-md bg-muted flex items-center justify-center overflow-hidden">
          {(entry.type === 'image' || entry.type === 'video') && entry.result.url ? (
            entry.type === 'image' ? (
              <img
                src={entry.result.url}
                alt={assetLabel}
                className="w-full h-full object-cover"
              />
            ) : (
              <video
                src={entry.result.url}
                className="w-full h-full object-cover"
                muted
              />
            )
          ) : (
            <AssetIcon className="h-8 w-8 text-muted-foreground" />
          )}
        </div>
        
        {/* Content */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <Badge variant="secondary" className="text-xs">
              {assetLabel}
            </Badge>
            <Badge variant="outline" className="text-xs">
              v{entry.version}
            </Badge>
            {isComparing && (
              <Badge variant="default" className="text-xs bg-blue-500">
                Comparing
              </Badge>
            )}
          </div>
          
          <p className="text-sm font-medium truncate">
            {entry.params.prompt || entry.params.text || `${assetLabel} Generation`}
          </p>
          
          <div className="flex items-center gap-2 mt-1 text-xs text-muted-foreground">
            <Calendar className="h-3 w-3" />
            <span>{formatTimestamp(entry.timestamp)}</span>
          </div>
        </div>
        
        {/* Actions */}
        <div className="flex flex-col gap-1">
          <div
            role="button"
            tabIndex={0}
            onClick={(e) => {
              e.stopPropagation();
              onRegenerate();
            }}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.stopPropagation();
                onRegenerate();
              }
            }}
            className="inline-flex items-center justify-center whitespace-nowrap font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 hover:bg-accent hover:text-accent-foreground rounded-md text-xs h-8 px-2 cursor-pointer"
          >
            <RefreshCw className="h-3 w-3" />
          </div>
          <div
            role="button"
            tabIndex={0}
            onClick={(e) => {
              e.stopPropagation();
              onCompare();
            }}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.stopPropagation();
                onCompare();
              }
            }}
            className="inline-flex items-center justify-center whitespace-nowrap font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 hover:bg-accent hover:text-accent-foreground rounded-md text-xs h-8 px-2 cursor-pointer"
          >
            <GitCompare className="h-3 w-3" />
          </div>
        </div>
      </div>
    </button>
  );
};

/**
 * History Entry Details Component
 */
interface HistoryEntryDetailsProps {
  entry: HistoryEntry;
  comparisonEntry: HistoryEntry | null;
  onRegenerate: () => void;
}

const HistoryEntryDetails: React.FC<HistoryEntryDetailsProps> = ({
  entry,
  comparisonEntry,
  onRegenerate,
}) => {
  const AssetIcon = getAssetIcon(entry.type);
  const assetLabel = getAssetTypeLabel(entry.type);
  
  // Get version comparison if comparing
  const comparison = useMemo(() => {
    if (!comparisonEntry) return null;
    
    return generationHistoryService.compareVersions(
      entry.result.id,
      comparisonEntry.version,
      entry.version
    );
  }, [entry, comparisonEntry]);
  
  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <AssetIcon className="h-5 w-5" />
          {assetLabel} Details - Version {entry.version}
        </CardTitle>
        <CardDescription>
          Generated on {new Date(entry.timestamp).toLocaleString()}
        </CardDescription>
      </CardHeader>
      
      <CardContent className="space-y-4">
        {/* Asset Preview */}
        {(entry.type === 'image' || entry.type === 'video') && entry.result.url && (
          <div className="rounded-lg overflow-hidden border">
            {entry.type === 'image' ? (
              <img
                src={entry.result.url}
                alt={assetLabel}
                className="w-full h-auto"
              />
            ) : (
              <video
                src={entry.result.url}
                controls
                className="w-full h-auto"
              />
            )}
          </div>
        )}
        
        <Separator />
        
        {/* Parameters */}
        <div className="space-y-2">
          <h4 className="text-sm font-semibold">Generation Parameters</h4>
          <div className="grid grid-cols-2 gap-3 text-sm">
            {Object.entries(entry.params).map(([key, value]) => {
              const isChanged = comparison?.paramDifferences[key];
              
              return (
                <div
                  key={key}
                  className={`p-2 rounded ${
                    isChanged ? 'bg-yellow-500/10 border border-yellow-500/20' : 'bg-muted'
                  }`}
                >
                  <span className="text-muted-foreground capitalize block mb-1">
                    {key.replace(/([A-Z])/g, ' $1').trim()}:
                  </span>
                  <span className="font-medium block">
                    {typeof value === 'object' ? JSON.stringify(value) : String(value)}
                  </span>
                  
                  {/* Show comparison value */}
                  {isChanged && comparisonEntry && (
                    <div className="mt-2 pt-2 border-t border-yellow-500/20">
                      <span className="text-xs text-muted-foreground">
                        v{comparisonEntry.version}:
                      </span>
                      <span className="text-xs font-medium ml-1">
                        {typeof isChanged.v1 === 'object'
                          ? JSON.stringify(isChanged.v1)
                          : String(isChanged.v1)}
                      </span>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
        
        {/* Comparison Summary */}
        {comparison && comparisonEntry && (
          <>
            <Separator />
            <div className="space-y-2">
              <h4 className="text-sm font-semibold flex items-center gap-2">
                <GitCompare className="h-4 w-4" />
                Version Comparison
              </h4>
              <div className="p-3 bg-muted rounded-lg space-y-2">
                <p className="text-sm">
                  Comparing <Badge variant="secondary">v{comparisonEntry.version}</Badge> with{' '}
                  <Badge variant="secondary">v{entry.version}</Badge>
                </p>
                <p className="text-sm text-muted-foreground">
                  {Object.keys(comparison.paramDifferences).length} parameter(s) changed
                </p>
                {Object.keys(comparison.paramDifferences).length > 0 && (
                  <div className="text-xs space-y-1 mt-2">
                    {Object.keys(comparison.paramDifferences).map((key) => (
                      <Badge key={key} variant="outline" className="mr-1">
                        {key}
                      </Badge>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </>
        )}
      </CardContent>
      
      <CardFooter>
        <Button onClick={onRegenerate} className="w-full">
          <RefreshCw className="mr-2 h-4 w-4" />
          Regenerate with These Parameters
        </Button>
      </CardFooter>
    </Card>
  );
};

/**
 * Generation Progress Modal Component
 * 
 * Displays real-time progress for generation tasks in the generation-buttons-ui feature.
 * Shows stage-by-stage progress (prompt ÔåÆ image ÔåÆ video ÔåÆ audio), estimated time remaining,
 * and provides cancel/retry functionality.
 * 
 * Requirements: 7.1, 7.3, 7.4, 7.5
 */

import { useEffect, useState, useRef, useCallback } from 'react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Progress } from '@/components/ui/progress';
import { AlertCircle, CheckCircle2, Loader2, XCircle, Sparkles, Image, Video, Music } from 'lucide-react';
import type { GenerationProgress } from '@/types/generation';
import { TwoStageVideoProgress } from './TwoStageVideoProgress';
import {
  useFocusTrap,
  useProgressAnnouncer,
  useErrorAnnouncer,
  getProgressAriaLabel,
  getTimeRemainingAriaLabel,
} from '@/hooks/useAccessibility';
import { debounce } from '@/utils/assetOptimization';

// ============================================================================
// Types
// ============================================================================

/**
 * Generation type for the modal
 */
export type GenerationType = 'prompt' | 'image' | 'video' | 'audio';

/**
 * Props for GenerationProgressModal component
 */
export interface GenerationProgressModalProps {
  /** Whether the modal is open */
  isOpen: boolean;
  /** Type of generation being performed */
  generationType: GenerationType;
  /** Current generation progress */
  progress: GenerationProgress;
  /** Callback when cancel button is clicked */
  onCancel?: () => void;
  /** Callback when close button is clicked (after completion or error) */
  onClose?: () => void;
  /** Callback when retry button is clicked (after error) */
  onRetry?: () => void;
}

/**
 * Stage information for display
 */
interface StageInfo {
  key: GenerationType;
  name: string;
  icon: React.ReactNode;
  description: string;
}

// ============================================================================
// Constants
// ============================================================================

/**
 * Pipeline stages configuration
 * Requirements: 7.1
 */
const PIPELINE_STAGES: StageInfo[] = [
  {
    key: 'prompt',
    name: 'Prompt Generation',
    icon: <Sparkles className="h-4 w-4" />,
    description: 'Generating optimized prompt',
  },
  {
    key: 'image',
    name: 'Image Generation',
    icon: <Image className="h-4 w-4" />,
    description: 'Creating image with Flux Turbo',
  },
  {
    key: 'video',
    name: 'Video Generation',
    icon: <Video className="h-4 w-4" />,
    description: 'Generating video with LTX2 i2v',
  },
  {
    key: 'audio',
    name: 'Audio Generation',
    icon: <Music className="h-4 w-4" />,
    description: 'Creating audio with TTS',
  },
];

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Format duration in milliseconds to human-readable string
 * Requirements: 7.3
 */
function formatDuration(ms: number): string {
  const seconds = Math.floor(ms / 1000);
  const minutes = Math.floor(seconds / 60);
  const hours = Math.floor(minutes / 60);

  if (hours > 0) {
    return `${hours}h ${minutes % 60}m`;
  }
  if (minutes > 0) {
    return `${minutes}m ${seconds % 60}s`;
  }
  return `${seconds}s`;
}

/**
 * Get stage status based on current generation type and progress
 * Requirements: 7.1
 */
function getStageStatus(
  stageKey: GenerationType,
  currentType: GenerationType,
  isComplete: boolean,
  hasError: boolean
): 'pending' | 'in-progress' | 'complete' | 'error' {
  const stageOrder: GenerationType[] = ['prompt', 'image', 'video', 'audio'];
  const stageIndex = stageOrder.indexOf(stageKey);
  const currentIndex = stageOrder.indexOf(currentType);

  if (hasError) {
    if (stageIndex < currentIndex) return 'complete';
    if (stageIndex === currentIndex) return 'error';
    return 'pending';
  }

  if (isComplete) {
    return 'complete';
  }

  if (stageIndex < currentIndex) return 'complete';
  if (stageIndex === currentIndex) return 'in-progress';
  return 'pending';
}

/**
 * Get progress color based on status
 */
function getProgressColor(status: 'pending' | 'in-progress' | 'complete' | 'error'): string {
  switch (status) {
    case 'complete':
      return 'hsl(142, 76%, 36%)'; // green
    case 'in-progress':
      return 'hsl(221, 83%, 53%)'; // blue
    case 'error':
      return 'hsl(0, 84%, 60%)'; // red
    default:
      return 'hsl(240, 5%, 64%)'; // gray
  }
}

// ============================================================================
// Component
// ============================================================================

/**
 * GenerationProgressModal Component
 * 
 * Displays generation progress with real-time updates, stage indicators,
 * timing information, and error handling capabilities.
 * 
 * Requirements: 7.1, 7.3, 7.4, 7.5
 */
export function GenerationProgressModal({
  isOpen,
  generationType,
  progress,
  onCancel,
  onClose,
  onRetry,
}: GenerationProgressModalProps) {
  const [startTime] = useState<number>(Date.now());
  const [elapsedTime, setElapsedTime] = useState<number>(0);
  const [debouncedProgress, setDebouncedProgress] = useState<GenerationProgress>(progress);
  
  // Accessibility hooks
  const focusTrapRef = useFocusTrap(isOpen);
  
  // Debounce progress updates to reduce re-renders
  // Requirements: Performance
  const updateProgress = useCallback(
    debounce((newProgress: GenerationProgress) => {
      setDebouncedProgress(newProgress);
    }, 200), // Update at most every 200ms
    []
  );
  
  // Update debounced progress when progress changes
  useEffect(() => {
    updateProgress(progress);
  }, [progress, updateProgress]);
  
  // Determine generation state
  const isComplete = debouncedProgress.overallProgress >= 100 && debouncedProgress.message.toLowerCase().includes('complete');
  const hasError = debouncedProgress.message.toLowerCase().includes('error') || debouncedProgress.message.toLowerCase().includes('fail');
  const isGenerating = !isComplete && !hasError;
  
  // Announce progress updates
  useProgressAnnouncer(
    debouncedProgress.overallProgress,
    `${generationType} generation`,
    isGenerating
  );
  
  // Announce errors
  useErrorAnnouncer(hasError ? debouncedProgress.message : null);

  /**
   * Update elapsed time every second
   * Requirements: 7.3
   */
  useEffect(() => {
    if (!isOpen) {
      setElapsedTime(0);
      return;
    }

    const updateElapsed = () => {
      setElapsedTime(Date.now() - startTime);
    };

    // Initial update
    updateElapsed();

    // Update every second
    const interval = setInterval(updateElapsed, 1000);

    return () => clearInterval(interval);
  }, [isOpen, startTime]);

  /**
   * Get dialog title based on status
   */
  const getDialogTitle = (): string => {
    if (hasError) return 'Generation Failed';
    if (isComplete) return 'Generation Complete';
    
    const stage = PIPELINE_STAGES.find(s => s.key === generationType);
    return stage ? stage.name : 'Generating...';
  };

  /**
   * Get dialog description based on status
   */
  const getDialogDescription = (): string => {
    if (hasError) {
      return 'An error occurred during generation. You can retry or cancel.';
    }
    if (isComplete) {
      return 'Your content has been generated successfully!';
    }
    return debouncedProgress.message || 'Processing your request...';
  };

  /**
   * Build stage information array with status
   * Requirements: 7.1
   */
  const stages = PIPELINE_STAGES.map(stage => ({
    ...stage,
    status: getStageStatus(stage.key, generationType, isComplete, hasError),
  }));

  return (
    <Dialog 
      open={isOpen} 
      onOpenChange={(open) => {
        // Only allow closing if not generating or if onClose is provided
        if (!open && (!isGenerating || onClose)) {
          onClose?.();
        }
      }}
    >
      <DialogContent
        ref={focusTrapRef}
        className="sm:max-w-[600px]"
        onInteractOutside={(e) => {
          // Prevent closing while generating
          if (isGenerating) {
            e.preventDefault();
          }
        }}
        aria-describedby="generation-progress-description"
        aria-live="polite"
        aria-atomic="false"
        role="dialog"
        aria-modal="true"
      >
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            {hasError && <XCircle className="h-5 w-5 text-red-500" aria-hidden="true" />}
            {isComplete && <CheckCircle2 className="h-5 w-5 text-green-500" aria-hidden="true" />}
            {isGenerating && <Loader2 className="h-5 w-5 animate-spin text-blue-500" aria-hidden="true" />}
            {getDialogTitle()}
          </DialogTitle>
          <DialogDescription id="generation-progress-description">
            {getDialogDescription()}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6 py-4">
          {/* Two-Stage Video Progress (for video generation only) */}
          {/* Requirements: 3.2 */}
          {generationType === 'video' && isGenerating && (
            <TwoStageVideoProgress 
              progress={progress}
              isComplete={isComplete}
            />
          )}
          
          {/* Overall Progress Bar (for non-video or completed video) */}
          {/* Requirements: 7.1, 7.3 */}
          {(generationType !== 'video' || !isGenerating) && (
            <div className="space-y-2">
              <div className="flex items-center justify-between text-sm">
                <span className="font-medium">Overall Progress</span>
                <span className="text-muted-foreground">
                  {Math.round(debouncedProgress.overallProgress)}%
                </span>
              </div>
              <Progress
                value={debouncedProgress.overallProgress}
                className="h-2"
                aria-label={getProgressAriaLabel(debouncedProgress.overallProgress)}
                aria-valuenow={Math.round(debouncedProgress.overallProgress)}
                aria-valuemin={0}
                aria-valuemax={100}
              />
            </div>
          )}

          {/* Stage Progress (if different from overall) - for non-video only */}
          {/* Requirements: 7.1 */}
          {generationType !== 'video' && debouncedProgress.stageProgress !== debouncedProgress.overallProgress && (
            <div className="space-y-2">
              <div className="flex items-center justify-between text-sm">
                <span className="font-medium">Stage Progress</span>
                <span className="text-muted-foreground">
                  {Math.round(debouncedProgress.stageProgress)}%
                </span>
              </div>
              <Progress
                value={debouncedProgress.stageProgress}
                className="h-2"
                aria-label={getProgressAriaLabel(debouncedProgress.stageProgress, debouncedProgress.stage)}
                aria-valuenow={Math.round(debouncedProgress.stageProgress)}
                aria-valuemin={0}
                aria-valuemax={100}
              />
            </div>
          )}

          {/* Pipeline Stage Indicators */}
          {/* Requirements: 7.1 */}
          <div className="space-y-3">
            <h4 className="text-sm font-medium">Pipeline Stages</h4>
            <div className="space-y-2">
              {stages.map((stage) => (
                <div
                  key={stage.key}
                  className="flex items-center gap-3 rounded-lg border p-3 transition-colors"
                  style={{
                    borderColor: stage.status === 'in-progress' ? getProgressColor(stage.status) : undefined,
                    backgroundColor: stage.status === 'in-progress' ? `${getProgressColor(stage.status)}10` : undefined,
                  }}
                >
                  {/* Stage Icon/Status */}
                  <div className="flex-shrink-0">
                    {stage.status === 'complete' && (
                      <CheckCircle2 className="h-5 w-5 text-green-500" aria-label="Complete" />
                    )}
                    {stage.status === 'in-progress' && (
                      <Loader2 className="h-5 w-5 animate-spin text-blue-500" aria-label="In progress" />
                    )}
                    {stage.status === 'error' && (
                      <XCircle className="h-5 w-5 text-red-500" aria-label="Error" />
                    )}
                    {stage.status === 'pending' && (
                      <div className="h-5 w-5 rounded-full border-2 border-gray-300" aria-label="Pending" />
                    )}
                  </div>

                  {/* Stage Name and Icon */}
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <span className="text-muted-foreground">{stage.icon}</span>
                      <span className="text-sm font-medium">{stage.name}</span>
                    </div>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      {stage.description}
                    </p>
                  </div>

                  {/* Stage Status Text */}
                  <div className="text-xs text-muted-foreground">
                    {stage.status === 'complete' && 'Complete'}
                    {stage.status === 'in-progress' && 'In Progress'}
                    {stage.status === 'error' && 'Failed'}
                    {stage.status === 'pending' && 'Pending'}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Timing Information */}
          {/* Requirements: 7.3, 7.4 */}
          <div className="grid grid-cols-2 gap-4" role="region" aria-label="Generation timing information">
            <div className="rounded-lg border p-3">
              <div className="text-xs text-muted-foreground mb-1">Elapsed Time</div>
              <div 
                className="text-lg font-semibold" 
                aria-live="polite"
                aria-label={`Elapsed time: ${formatDuration(elapsedTime)}`}
              >
                {formatDuration(elapsedTime)}
              </div>
            </div>
            <div className="rounded-lg border p-3">
              <div className="text-xs text-muted-foreground mb-1">
                {isComplete ? 'Total Time' : 'Est. Remaining'}
              </div>
              <div 
                className="text-lg font-semibold" 
                aria-live="polite"
                aria-label={
                  isComplete
                    ? `Total time: ${formatDuration(elapsedTime)}`
                    : debouncedProgress.estimatedTimeRemaining > 0
                    ? getTimeRemainingAriaLabel(debouncedProgress.estimatedTimeRemaining)
                    : 'Estimated time remaining: calculating'
                }
              >
                {isComplete
                  ? formatDuration(elapsedTime)
                  : debouncedProgress.estimatedTimeRemaining > 0
                  ? formatDuration(debouncedProgress.estimatedTimeRemaining)
                  : '--'}
              </div>
            </div>
          </div>

          {/* Current Stage Message (for non-video only) */}
          {/* Requirements: 7.1 */}
          {generationType !== 'video' && isGenerating && debouncedProgress.stage && (
            <div className="rounded-lg bg-muted p-3">
              <div className="text-xs text-muted-foreground mb-1">Current Stage</div>
              <div className="text-sm font-medium">{debouncedProgress.stage}</div>
            </div>
          )}

          {/* Error Display */}
          {/* Requirements: 7.5 */}
          {hasError && (
            <div className="rounded-lg border border-red-200 bg-red-50 p-4" role="alert">
              <div className="flex items-start gap-3">
                <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0 mt-0.5" aria-hidden="true" />
                <div className="flex-1">
                  <h4 className="text-sm font-semibold text-red-900 mb-1">
                    Error Details
                  </h4>
                  <p className="text-sm text-red-700">{debouncedProgress.message}</p>
                </div>
              </div>
            </div>
          )}

          {/* Success Message */}
          {isComplete && (
            <div className="rounded-lg border border-green-200 bg-green-50 p-4" role="status">
              <div className="flex items-start gap-3">
                <CheckCircle2 className="h-5 w-5 text-green-500 flex-shrink-0 mt-0.5" aria-hidden="true" />
                <div className="flex-1">
                  <h4 className="text-sm font-semibold text-green-900 mb-1">
                    Generation Successful
                  </h4>
                  <p className="text-sm text-green-700">
                    Your content has been generated and is ready to use.
                  </p>
                </div>
              </div>
            </div>
          )}
        </div>

        <DialogFooter>
          {/* Cancel Button (only during generation if cancellable) */}
          {/* Requirements: 7.5 */}
          {isGenerating && debouncedProgress.cancellable && onCancel && (
            <Button 
              variant="outline" 
              onClick={onCancel}
              aria-label="Cancel generation"
            >
              Cancel
            </Button>
          )}

          {/* Retry Button (only on error) */}
          {/* Requirements: 7.5 */}
          {hasError && onRetry && (
            <Button 
              variant="default" 
              onClick={onRetry}
              aria-label="Retry generation"
            >
              Retry
            </Button>
          )}

          {/* Close Button (on error or completion) */}
          {(hasError || isComplete) && onClose && (
            <Button
              variant={hasError ? 'outline' : 'default'}
              onClick={onClose}
              aria-label={hasError ? 'Close modal' : 'View results'}
            >
              {hasError ? 'Close' : 'View Results'}
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

export default GenerationProgressModal;

/**
 * Image Generation Button Component
 * 
 * Button that triggers image generation dialog.
 * Supports pipeline state awareness, tooltips, and keyboard shortcuts.
 * 
 * Requirements: 2.1, 5.3, 5.4, 5.5, 13.2
 */

import React, { useEffect } from 'react';
import { Button } from '../ui/button';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '../ui/tooltip';
import { Image } from 'lucide-react';
import { useGenerationStore } from '../../stores/generationStore';
import {
  useKeyboardShortcut,
  useButtonStateAnnouncer,
  getButtonAriaDescription,
} from '../../hooks/useAccessibility';

export interface ImageGenerationButtonProps {
  /**
   * Whether the button is disabled
   */
  disabled?: boolean;
  
  /**
   * Reason for disabled state (shown in tooltip)
   */
  disabledReason?: string;
  
  /**
   * Callback when button is clicked
   */
  onClick: () => void;
  
  /**
   * Whether generation is in progress
   */
  isGenerating?: boolean;
  
  /**
   * Custom className for styling
   */
  className?: string;
}

/**
 * Image Generation Button
 * 
 * Displays a button that opens the image generation dialog.
 * Shows appropriate state (enabled, disabled, generating) with visual indicators.
 * Supports keyboard shortcut (Ctrl+Shift+I).
 * Enabled only after prompt generation is complete.
 */
export const ImageGenerationButton: React.FC<ImageGenerationButtonProps> = ({
  disabled = false,
  disabledReason,
  onClick,
  isGenerating = false,
  className = '',
}) => {
  const { currentPipeline } = useGenerationStore();
  
  // Determine button state based on pipeline
  const promptStage = currentPipeline?.stages.prompt;
  const imageStage = currentPipeline?.stages.image;
  
  const isPromptCompleted = promptStage?.status === 'completed';
  const isImageCompleted = imageStage?.status === 'completed';
  const isImageFailed = imageStage?.status === 'failed';
  const isImageInProgress = imageStage?.status === 'in_progress' || isGenerating;
  
  // Button is enabled only if prompt is completed
  const isButtonDisabled = disabled || !isPromptCompleted || isImageInProgress;
  
  // Register keyboard shortcut with accessibility
  const shortcutString = useKeyboardShortcut(
    'I',
    onClick,
    {
      ctrl: true,
      shift: true,
      enabled: !isButtonDisabled,
    }
  );
  
  // Announce button state changes
  useButtonStateAnnouncer(
    'Image generation button',
    isButtonDisabled,
    disabledReason || (!isPromptCompleted ? 'Complete prompt generation first' : undefined)
  );
  
  // Determine tooltip content
  const getTooltipContent = (): string => {
    if (disabledReason) {
      return disabledReason;
    }
    
    if (!isPromptCompleted) {
      return 'Complete prompt generation first';
    }
    
    if (isImageInProgress) {
      return 'Generating image...';
    }
    
    if (isImageCompleted) {
      return `Image generated. Click to regenerate. (${shortcutString})`;
    }
    
    if (isImageFailed) {
      return `Image generation failed. Click to retry. (${shortcutString})`;
    }
    
    return `Generate image from prompt (${shortcutString})`;
  };
  
  // Get ARIA description
  const ariaDescription = getButtonAriaDescription(
    'image',
    isButtonDisabled,
    isImageInProgress,
    isImageCompleted,
    isImageFailed,
    disabledReason || (!isPromptCompleted ? 'Complete prompt generation first' : undefined)
  );
  
  // Determine button variant
  const getButtonVariant = (): 'default' | 'outline' | 'secondary' | 'ghost' | 'destructive' => {
    if (isImageFailed) {
      return 'destructive';
    }
    
    if (isImageCompleted) {
      return 'secondary';
    }
    
    return 'default';
  };
  
  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            onClick={onClick}
            disabled={isButtonDisabled}
            variant={getButtonVariant()}
            className={`gap-2 ${className}`}
            aria-label="Generate image"
            aria-description={ariaDescription}
            aria-busy={isImageInProgress}
            aria-disabled={isButtonDisabled}
            aria-keyshortcuts={shortcutString}
          >
            <Image className="h-4 w-4" aria-hidden="true" />
            {isImageInProgress ? 'Generating...' : isImageCompleted ? 'Regenerate Image' : 'Generate Image'}
          </Button>
        </TooltipTrigger>
        <TooltipContent>
          <p>{getTooltipContent()}</p>
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
};

/**
 * Image Generation Dialog Component
 * 
 * Dialog for generating images using ComfyUI Flux Turbo workflow.
 * Provides parameter controls and integrates with the generation pipeline.
 * 
 * Requirements: 2.1, 2.2, 10.1, 10.4
 */

import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '../ui/dialog';
import { Button } from '../ui/button';
import { Label } from '../ui/label';
import { Input } from '../ui/input';
import { Textarea } from '../ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '../ui/select';
import { Slider } from '../ui/slider';
import { Loader2, Image as ImageIcon, Check, AlertCircle } from 'lucide-react';
import { generationOrchestrator } from '../../services/GenerationOrchestrator';
import { useGenerationStore } from '../../stores/generationStore';
import type { ImageGenerationParams } from '../../types/generation';
import { ErrorDisplay } from './ErrorDisplay';
import { PresetManager } from './PresetManager';
import type { ImagePreset } from '../../services/PresetManagementService';
import {
  categorizeError,
  preserveStateOnError,
  restorePreservedState,
  suggestParameterAdjustments,
  type CategorizedError,
  type PreservedState,
} from '../../utils/errorHandling';

export interface ImageGenerationDialogProps {
  /**
   * Whether the dialog is open
   */
  isOpen: boolean;
  
  /**
   * Callback when dialog is closed
   */
  onClose: () => void;
  
  /**
   * Initial prompt (pre-filled from previous step)
   */
  initialPrompt?: string;
}

/**
 * Default image generation parameters
 */
const DEFAULT_PARAMS: ImageGenerationParams = {
  prompt: '',
  negativePrompt: 'blurry, low quality, distorted, deformed, ugly, bad anatomy',
  width: 1024,
  height: 1024,
  steps: 20,
  cfgScale: 7.5,
  seed: -1, // Random seed
  sampler: 'euler_ancestral',
  scheduler: 'normal',
};

/**
 * Available samplers
 */
const SAMPLERS = [
  'euler',
  'euler_ancestral',
  'heun',
  'dpm_2',
  'dpm_2_ancestral',
  'lms',
  'dpm_fast',
  'dpm_adaptive',
  'dpmpp_2s_ancestral',
  'dpmpp_sde',
  'dpmpp_2m',
  'ddim',
  'uni_pc',
];

/**
 * Available schedulers
 */
const SCHEDULERS = [
  'normal',
  'karras',
  'exponential',
  'sgm_uniform',
  'simple',
  'ddim_uniform',
];

/**
 * Common image dimensions
 */
const COMMON_DIMENSIONS = [
  { label: 'Square (1024x1024)', width: 1024, height: 1024 },
  { label: 'Portrait (768x1024)', width: 768, height: 1024 },
  { label: 'Landscape (1024x768)', width: 1024, height: 768 },
  { label: 'Wide (1280x720)', width: 1280, height: 720 },
  { label: 'Ultra Wide (1920x1080)', width: 1920, height: 1080 },
];

/**
 * Image Generation Dialog
 * 
 * Provides UI for configuring image generation parameters and triggering generation.
 * Integrates with ComfyUIService for z_image_turbo workflow.
 */
export const ImageGenerationDialog: React.FC<ImageGenerationDialogProps> = ({
  isOpen,
  onClose,
  initialPrompt,
}) => {
  const { currentPipeline, completeStage, failStage, updateStageProgress } = useGenerationStore();
  
  // Parameters state
  const [params, setParams] = useState<ImageGenerationParams>(DEFAULT_PARAMS);
  const [isGenerating, setIsGenerating] = useState(false);
  const [categorizedError, setCategorizedError] = useState<CategorizedError | null>(null);
  const [preservedState, setPreservedState] = useState<PreservedState | null>(null);
  const [validationErrors, setValidationErrors] = useState<Record<string, string>>({});
  
  // Pre-fill prompt from previous step
  useEffect(() => {
    if (isOpen) {
      const promptStage = currentPipeline?.stages.prompt;
      const promptText = initialPrompt || promptStage?.result?.text || '';
      
      setParams((prev) => ({
        ...prev,
        prompt: promptText,
      }));
      setCategorizedError(null);
      setValidationErrors({});
    }
  }, [isOpen, initialPrompt, currentPipeline]);
  
  /**
   * Update parameter value
   */
  const updateParam = <K extends keyof ImageGenerationParams>(
    key: K,
    value: ImageGenerationParams[K]
  ) => {
    setParams((prev) => ({
      ...prev,
      [key]: value,
    }));
    
    // Clear validation error for this field
    if (validationErrors[key]) {
      setValidationErrors((prev) => {
        const newErrors = { ...prev };
        delete newErrors[key];
        return newErrors;
      });
    }
  };
  
  /**
   * Apply preset dimensions
   */
  const applyDimensions = (width: number, height: number) => {
    setParams((prev) => ({
      ...prev,
      width,
      height,
    }));
  };
  
  /**
   * Load preset parameters
   */
  const handleLoadPreset = (preset: ImagePreset) => {
    setParams((prev) => ({
      ...prev,
      ...preset.params,
    }));
  };
  
  /**
   * Validate parameters
   */
  const validateParams = (): boolean => {
    const errors: Record<string, string> = {};
    
    if (!params.prompt.trim()) {
      errors.prompt = 'Prompt is required';
    }
    
    if (params.width < 256 || params.width > 2048) {
      errors.width = 'Width must be between 256 and 2048';
    }
    
    if (params.height < 256 || params.height > 2048) {
      errors.height = 'Height must be between 256 and 2048';
    }
    
    if (params.width % 8 !== 0) {
      errors.width = 'Width must be divisible by 8';
    }
    
    if (params.height % 8 !== 0) {
      errors.height = 'Height must be divisible by 8';
    }
    
    if (params.steps < 1 || params.steps > 150) {
      errors.steps = 'Steps must be between 1 and 150';
    }
    
    if (params.cfgScale < 1 || params.cfgScale > 30) {
      errors.cfgScale = 'CFG Scale must be between 1 and 30';
    }
    
    setValidationErrors(errors);
    return Object.keys(errors).length === 0;
  };
  
  /**
   * Generate image
   */
  const handleGenerate = async () => {
    // Validate parameters
    if (!validateParams()) {
      const error = new Error('Please fix the validation errors before generating');
      const categorized = categorizeError(error);
      setCategorizedError(categorized);
      return;
    }
    
    setIsGenerating(true);
    setCategorizedError(null);
    
    try {
      const result = await generationOrchestrator.generateImage(
        params,
        (progress) => {
          updateStageProgress('image', progress);
        },
        (error) => {
          const categorized = categorizeError(error);
          setCategorizedError(categorized);
          failStage('image', error.message);
          
          // Preserve state on error
          const preserved = preserveStateOnError(
            categorized,
            { params },
            [],
            null
          );
          setPreservedState(preserved);
        }
      );
      
      // Complete the image stage
      completeStage('image', result);
      
      // Close dialog
      onClose();
    } catch (err) {
      const error = err instanceof Error ? err : new Error('Failed to generate image');
      const categorized = categorizeError(error);
      setCategorizedError(categorized);
      
      // Preserve state on error
      const preserved = preserveStateOnError(
        categorized,
        { params },
        [],
        null
      );
      setPreservedState(preserved);
    } finally {
      setIsGenerating(false);
    }
  };
  
  /**
   * Handle dialog close
   */
  const handleClose = () => {
    if (!isGenerating) {
      onClose();
    }
  };
  
  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <ImageIcon className="h-5 w-5" />
            Generate Image
          </DialogTitle>
          <DialogDescription>
            Configure parameters for image generation using Flux Turbo.
          </DialogDescription>
        </DialogHeader>
        
        <div className="space-y-4 py-4">
          {/* Preset Manager */}
          <PresetManager
            type="image"
            currentParams={params}
            onLoadPreset={(preset) => handleLoadPreset(preset as ImagePreset)}
          />
          
          {/* Prompt */}
          <div className="space-y-2">
            <Label htmlFor="prompt">
              Prompt <span className="text-destructive">*</span>
            </Label>
            <Textarea
              id="prompt"
              value={params.prompt}
              onChange={(e) => updateParam('prompt', e.target.value)}
              placeholder="Describe the image you want to generate..."
              className="min-h-[100px]"
              disabled={isGenerating}
            />
            {validationErrors.prompt && (
              <p className="text-sm text-destructive flex items-center gap-1">
                <AlertCircle className="h-3 w-3" />
                {validationErrors.prompt}
              </p>
            )}
          </div>
          
          {/* Negative Prompt */}
          <div className="space-y-2">
            <Label htmlFor="negativePrompt">Negative Prompt</Label>
            <Textarea
              id="negativePrompt"
              value={params.negativePrompt}
              onChange={(e) => updateParam('negativePrompt', e.target.value)}
              placeholder="What to avoid in the image..."
              className="min-h-[60px]"
              disabled={isGenerating}
            />
          </div>
          
          {/* Dimensions */}
          <div className="space-y-2">
            <Label>Dimensions</Label>
            <div className="grid grid-cols-2 gap-2 mb-2">
              {COMMON_DIMENSIONS.map((preset) => (
                <Button
                  key={preset.label}
                  variant="outline"
                  size="sm"
                  onClick={() => applyDimensions(preset.width, preset.height)}
                  disabled={isGenerating}
                  className={
                    params.width === preset.width && params.height === preset.height
                      ? 'border-primary'
                      : ''
                  }
                >
                  {preset.label}
                </Button>
              ))}
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="width">Width</Label>
                <Input
                  id="width"
                  type="number"
                  value={params.width}
                  onChange={(e) => updateParam('width', parseInt(e.target.value) || 1024)}
                  min={256}
                  max={2048}
                  step={8}
                  disabled={isGenerating}
                />
                {validationErrors.width && (
                  <p className="text-sm text-destructive flex items-center gap-1">
                    <AlertCircle className="h-3 w-3" />
                    {validationErrors.width}
                  </p>
                )}
              </div>
              <div className="space-y-2">
                <Label htmlFor="height">Height</Label>
                <Input
                  id="height"
                  type="number"
                  value={params.height}
                  onChange={(e) => updateParam('height', parseInt(e.target.value) || 1024)}
                  min={256}
                  max={2048}
                  step={8}
                  disabled={isGenerating}
                />
                {validationErrors.height && (
                  <p className="text-sm text-destructive flex items-center gap-1">
                    <AlertCircle className="h-3 w-3" />
                    {validationErrors.height}
                  </p>
                )}
              </div>
            </div>
          </div>
          
          {/* Steps */}
          <div className="space-y-2">
            <div className="flex justify-between">
              <Label htmlFor="steps">Steps</Label>
              <span className="text-sm text-muted-foreground">{params.steps}</span>
            </div>
            <Slider
              id="steps"
              value={[params.steps]}
              onValueChange={([value]) => updateParam('steps', value)}
              min={1}
              max={150}
              step={1}
              disabled={isGenerating}
            />
            {validationErrors.steps && (
              <p className="text-sm text-destructive flex items-center gap-1">
                <AlertCircle className="h-3 w-3" />
                {validationErrors.steps}
              </p>
            )}
          </div>
          
          {/* CFG Scale */}
          <div className="space-y-2">
            <div className="flex justify-between">
              <Label htmlFor="cfgScale">CFG Scale</Label>
              <span className="text-sm text-muted-foreground">{params.cfgScale.toFixed(1)}</span>
            </div>
            <Slider
              id="cfgScale"
              value={[params.cfgScale]}
              onValueChange={([value]) => updateParam('cfgScale', value)}
              min={1}
              max={30}
              step={0.5}
              disabled={isGenerating}
            />
            {validationErrors.cfgScale && (
              <p className="text-sm text-destructive flex items-center gap-1">
                <AlertCircle className="h-3 w-3" />
                {validationErrors.cfgScale}
              </p>
            )}
          </div>
          
          {/* Seed */}
          <div className="space-y-2">
            <Label htmlFor="seed">Seed (-1 for random)</Label>
            <Input
              id="seed"
              type="number"
              value={params.seed}
              onChange={(e) => updateParam('seed', parseInt(e.target.value) || -1)}
              disabled={isGenerating}
            />
          </div>
          
          {/* Sampler and Scheduler */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="sampler">Sampler</Label>
              <Select
                value={params.sampler}
                onValueChange={(value) => updateParam('sampler', value)}
                disabled={isGenerating}
              >
                <SelectTrigger id="sampler">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {SAMPLERS.map((sampler) => (
                    <SelectItem key={sampler} value={sampler}>
                      {sampler}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            
            <div className="space-y-2">
              <Label htmlFor="scheduler">Scheduler</Label>
              <Select
                value={params.scheduler}
                onValueChange={(value) => updateParam('scheduler', value)}
                disabled={isGenerating}
              >
                <SelectTrigger id="scheduler">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {SCHEDULERS.map((scheduler) => (
                    <SelectItem key={scheduler} value={scheduler}>
                      {scheduler}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          
          {/* Error Display */}
          {categorizedError && (
            <ErrorDisplay
              error={categorizedError}
              onRetry={categorizedError.canRetry ? handleGenerate : undefined}
              onAdjustParameters={() => {
                // Suggest parameter adjustments
                const suggestions = suggestParameterAdjustments(categorizedError, params);
                if (suggestions) {
                  setParams((prev) => ({ ...prev, ...suggestions }));
                }
                setCategorizedError(null);
              }}
              onDismiss={() => setCategorizedError(null)}
              className="mt-4"
            />
          )}
        </div>
        
        <DialogFooter>
          <Button
            variant="outline"
            onClick={handleClose}
            disabled={isGenerating}
          >
            Cancel
          </Button>
          
          <Button
            onClick={handleGenerate}
            disabled={isGenerating || !params.prompt.trim()}
          >
            {isGenerating ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Generating...
              </>
            ) : (
              <>
                <Check className="mr-2 h-4 w-4" />
                Generate Image
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

/**
 * Pipeline Completion View Component
 * 
 * Displays all generated assets together when pipeline is complete,
 * with export options and asset relationship visualization.
 * 
 * Requirements: 6.5, 9.4
 */

import React, { useState } from 'react';
import { useGenerationStore } from '../../stores/generationStore';
import { PipelineStateMachine } from '../../services/PipelineStateMachine';
import type { GeneratedAsset, GeneratedPrompt } from '../../types/generation';

export interface PipelineCompletionViewProps {
  pipelineId: string;
  onClose?: () => void;
  onExport?: (assets: GeneratedAsset[], format: ExportFormat) => void;
  onRestart?: () => void;
}

export type ExportFormat = 'individual' | 'batch' | 'zip' | 'mp4' | 'webm';

interface ExportOptions {
  format: ExportFormat;
  includeMetadata: boolean;
  includePrompt: boolean;
  quality: 'low' | 'medium' | 'high';
}

/**
 * Pipeline Completion View Component
 */
export const PipelineCompletionView: React.FC<PipelineCompletionViewProps> = ({
  pipelineId,
  onClose,
  onExport,
  onRestart,
}) => {
  const currentPipeline = useGenerationStore(state => state.currentPipeline);
  const getRelatedAssets = useGenerationStore(state => state.getRelatedAssets);
  const getAllPipelineAssets = useGenerationStore(state => state.getAllPipelineAssets);

  const [exportOptions, setExportOptions] = useState<ExportOptions>({
    format: 'individual',
    includeMetadata: true,
    includePrompt: true,
    quality: 'high',
  });

  const [selectedAssets, setSelectedAssets] = useState<Set<string>>(new Set());

  if (!currentPipeline || currentPipeline.id !== pipelineId) {
    return (
      <div className="pipeline-completion-view">
        <div className="error-message">
          Pipeline not found
        </div>
      </div>
    );
  }

  if (!PipelineStateMachine.isPipelineComplete(currentPipeline)) {
    return (
      <div className="pipeline-completion-view">
        <div className="info-message">
          Pipeline is not yet complete
        </div>
      </div>
    );
  }

  const assets = getAllPipelineAssets();
  const completedStages = PipelineStateMachine.getCompletedStages(currentPipeline);
  const allAssets: GeneratedAsset[] = [
    assets.image,
    assets.video,
    assets.audio,
  ].filter((asset): asset is GeneratedAsset => asset !== undefined);

  const handleAssetSelect = (assetId: string) => {
    const newSelected = new Set(selectedAssets);
    if (newSelected.has(assetId)) {
      newSelected.delete(assetId);
    } else {
      newSelected.add(assetId);
    }
    setSelectedAssets(newSelected);
  };

  const handleSelectAll = () => {
    if (selectedAssets.size === allAssets.length) {
      setSelectedAssets(new Set());
    } else {
      setSelectedAssets(new Set(allAssets.map(a => a.id)));
    }
  };

  const handleExport = () => {
    const assetsToExport = allAssets.filter(a => selectedAssets.has(a.id));
    if (assetsToExport.length === 0) {
      alert('Please select at least one asset to export');
      return;
    }

    onExport?.(assetsToExport, exportOptions.format);
  };

  const getAssetRelationships = (assetId: string): GeneratedAsset[] => {
    return getRelatedAssets(assetId);
  };

  return (
    <div className="pipeline-completion-view">
      {/* Header */}
      <div className="completion-header">
        <h2>Pipeline Complete</h2>
        <p className="completion-subtitle">
          All stages completed successfully. Review and export your generated assets.
        </p>
        {onClose && (
          <button
            className="close-button"
            onClick={onClose}
            aria-label="Close completion view"
          >
            ├ù
          </button>
        )}
      </div>

      {/* Pipeline Summary */}
      <div className="pipeline-summary">
        <div className="summary-card">
          <h3>Pipeline Summary</h3>
          <div className="summary-stats">
            <div className="stat">
              <span className="stat-label">Completed Stages</span>
              <span className="stat-value">{completedStages.length}</span>
            </div>
            <div className="stat">
              <span className="stat-label">Generated Assets</span>
              <span className="stat-value">{allAssets.length}</span>
            </div>
            <div className="stat">
              <span className="stat-label">Duration</span>
              <span className="stat-value">
                {Math.round((currentPipeline.updatedAt - currentPipeline.createdAt) / 1000)}s
              </span>
            </div>
          </div>
        </div>

        {/* Prompt Display */}
        {assets.prompt && (
          <div className="prompt-card">
            <h4>Generated Prompt</h4>
            <p className="prompt-text">{assets.prompt.text}</p>
          </div>
        )}
      </div>

      {/* Assets Grid */}
      <div className="assets-section">
        <div className="assets-header">
          <h3>Generated Assets</h3>
          <button
            className="select-all-button"
            onClick={handleSelectAll}
          >
            {selectedAssets.size === allAssets.length ? 'Deselect All' : 'Select All'}
          </button>
        </div>

        <div className="assets-grid">
          {allAssets.map(asset => {
            const isSelected = selectedAssets.has(asset.id);
            const relatedAssets = getAssetRelationships(asset.id);

            return (
              <div
                key={asset.id}
                className={`asset-card ${isSelected ? 'selected' : ''}`}
                onClick={() => handleAssetSelect(asset.id)}
              >
                <div className="asset-checkbox">
                  <input
                    type="checkbox"
                    checked={isSelected}
                    onChange={() => handleAssetSelect(asset.id)}
                    onClick={(e) => e.stopPropagation()}
                  />
                </div>

                <div className="asset-preview">
                  {asset.type === 'image' && (
                    <img src={asset.url} alt="Generated image" />
                  )}
                  {asset.type === 'video' && (
                    <video src={asset.url} controls />
                  )}
                  {asset.type === 'audio' && (
                    <audio src={asset.url} controls />
                  )}
                </div>

                <div className="asset-info">
                  <div className="asset-type-badge">{asset.type}</div>
                  <div className="asset-metadata">
                    <span className="metadata-item">
                      {(asset.metadata.fileSize / 1024).toFixed(2)} KB
                    </span>
                    {asset.metadata.dimensions && (
                      <span className="metadata-item">
                        {asset.metadata.dimensions.width}├ù{asset.metadata.dimensions.height}
                      </span>
                    )}
                    {asset.metadata.duration && (
                      <span className="metadata-item">
                        {asset.metadata.duration.toFixed(1)}s
                      </span>
                    )}
                  </div>

                  {relatedAssets.length > 0 && (
                    <div className="asset-relationships">
                      <span className="relationships-label">Related:</span>
                      <span className="relationships-count">{relatedAssets.length} asset(s)</span>
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Export Options */}
      <div className="export-section">
        <h3>Export Options</h3>
        
        <div className="export-options-grid">
          <div className="option-group">
            <label htmlFor="export-format">Format</label>
            <select
              id="export-format"
              value={exportOptions.format}
              onChange={(e) => setExportOptions({
                ...exportOptions,
                format: e.target.value as ExportFormat,
              })}
            >
              <option value="individual">Individual Files</option>
              <option value="batch">Batch Export</option>
              <option value="zip">ZIP Archive</option>
              <option value="mp4">MP4 Video</option>
              <option value="webm">WebM Video</option>
            </select>
          </div>

          <div className="option-group">
            <label htmlFor="export-quality">Quality</label>
            <select
              id="export-quality"
              value={exportOptions.quality}
              onChange={(e) => setExportOptions({
                ...exportOptions,
                quality: e.target.value as 'low' | 'medium' | 'high',
              })}
            >
              <option value="low">Low</option>
              <option value="medium">Medium</option>
