/**
 * Video Preview Panel Component
 * 
 * Displays generated video with playback controls, metadata, and action buttons.
 * Provides save, regenerate, and export options.
 * Enables audio generation button on success.
 * 
 * Requirements: 3.3, 3.5
 */

import React, { useState, useRef, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Separator } from '../ui/separator';
import { Slider } from '../ui/slider';
import {
  Download,
  RefreshCw,
  Video as VideoIcon,
  Calendar,
  HardDrive,
  Maximize2,
  Play,
  Pause,
  Volume2,
  VolumeX,
  Mic,
  Clock,
} from 'lucide-react';
import type { GeneratedAsset } from '../../types/generation';
import { shouldStreamVideo, createStreamingVideoUrl, formatFileSize } from '../../utils/assetOptimization';

export interface VideoPreviewPanelProps {
  /**
   * Generated video asset
   */
  asset: GeneratedAsset;
  
  /**
   * Callback when save is clicked
   */
  onSave?: (asset: GeneratedAsset) => void;
  
  /**
   * Callback when regenerate is clicked
   */
  onRegenerate?: () => void;
  
  /**
   * Callback when audio generation is triggered
   */
  onGenerateAudio?: (asset: GeneratedAsset) => void;
  
  /**
   * Whether audio generation is available
   */
  canGenerateAudio?: boolean;
  
  /**
   * Custom className for styling
   */
  className?: string;
}

/**
 * Format file size for display
 */
const formatFileSizeLocal = (bytes: number): string => {
  return formatFileSize(bytes);
};

/**
 * Format timestamp for display
 */
const formatTimestamp = (timestamp: number): string => {
  const date = new Date(timestamp);
  return date.toLocaleString();
};

/**
 * Format duration for display (seconds to MM:SS)
 */
const formatDuration = (seconds: number): string => {
  const mins = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60);
  return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
};

/**
 * Video Preview Panel
 * 
 * Displays generated video with playback controls, metadata, parameters, and action buttons.
 * Enables audio generation workflow on successful video generation.
 * Supports streaming for large video files.
 */
export const VideoPreviewPanel: React.FC<VideoPreviewPanelProps> = ({
  asset,
  onSave,
  onRegenerate,
  onGenerateAudio,
  canGenerateAudio = true,
  className = '',
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(1);
  const [isVideoExpanded, setIsVideoExpanded] = useState(false);
  const [videoUrl, setVideoUrl] = useState<string>(asset.url);
  const [useStreaming, setUseStreaming] = useState(false);
  
  const { metadata } = asset;
  const { generationParams, fileSize, dimensions, format } = metadata;
  const videoDuration = metadata.duration || 0;
  
  // Determine if streaming should be used
  useEffect(() => {
    const shouldStream = shouldStreamVideo(fileSize);
    setUseStreaming(shouldStream);
    
    if (shouldStream) {
      const streamingUrl = createStreamingVideoUrl(asset.url);
      setVideoUrl(streamingUrl);
    } else {
      setVideoUrl(asset.url);
    }
  }, [asset.url, fileSize]);
  
  /**
   * Handle play/pause toggle
   */
  const togglePlayPause = () => {
    if (!videoRef.current) return;
    
    if (isPlaying) {
      videoRef.current.pause();
    } else {
      videoRef.current.play();
    }
    setIsPlaying(!isPlaying);
  };
  
  /**
   * Handle mute toggle
   */
  const toggleMute = () => {
    if (!videoRef.current) return;
    
    videoRef.current.muted = !isMuted;
    setIsMuted(!isMuted);
  };
  
  /**
   * Handle volume change
   */
  const handleVolumeChange = (value: number[]) => {
    if (!videoRef.current) return;
    
    const newVolume = value[0];
    videoRef.current.volume = newVolume;
    setVolume(newVolume);
    
    // Unmute if volume is increased from 0
    if (newVolume > 0 && isMuted) {
      setIsMuted(false);
      videoRef.current.muted = false;
    }
  };
  
  /**
   * Handle time update
   */
  const handleTimeUpdate = () => {
    if (!videoRef.current) return;
    setCurrentTime(videoRef.current.currentTime);
  };
  
  /**
   * Handle loaded metadata
   */
  const handleLoadedMetadata = () => {
    if (!videoRef.current) return;
    setDuration(videoRef.current.duration);
  };
  
  /**
   * Handle seek
   */
  const handleSeek = (value: number[]) => {
    if (!videoRef.current) return;
    
    const newTime = value[0];
    videoRef.current.currentTime = newTime;
    setCurrentTime(newTime);
  };
  
  /**
   * Handle video ended
   */
  const handleVideoEnded = () => {
    setIsPlaying(false);
  };
  
  /**
   * Handle save action
   */
  const handleSave = () => {
    if (onSave) {
      onSave(asset);
    }
  };
  
  /**
   * Handle regenerate action
   */
  const handleRegenerate = () => {
    if (onRegenerate) {
      onRegenerate();
    }
  };
  
  /**
   * Handle audio generation
   */
  const handleGenerateAudio = () => {
    if (onGenerateAudio && canGenerateAudio) {
      onGenerateAudio(asset);
    }
  };
  
  /**
   * Toggle video expansion
   */
  const toggleVideoExpansion = () => {
    setIsVideoExpanded(!isVideoExpanded);
  };
  
  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <VideoIcon className="h-5 w-5" />
          Generated Video
        </CardTitle>
        <CardDescription>
          Video generated successfully. You can save, regenerate, or proceed to audio generation.
        </CardDescription>
      </CardHeader>
      
      <CardContent className="space-y-4">
        {/* Video Player */}
        <div className="relative group">
          {useStreaming && (
            <Badge variant="secondary" className="absolute top-2 left-2 z-10">
              Streaming
            </Badge>
          )}
          <video
            ref={videoRef}
            src={videoUrl}
            className={`w-full rounded-lg border bg-black ${
              isVideoExpanded ? 'max-h-none' : 'max-h-96'
            }`}
            onTimeUpdate={handleTimeUpdate}
            onLoadedMetadata={handleLoadedMetadata}
            onEnded={handleVideoEnded}
            onClick={togglePlayPause}
            preload={useStreaming ? 'metadata' : 'auto'}
          />
          
          {/* Expand Button */}
          <Button
            variant="secondary"
            size="icon"
            className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity"
            onClick={toggleVideoExpansion}
          >
            <Maximize2 className="h-4 w-4" />
          </Button>
          
          {/* Play/Pause Overlay */}
          {!isPlaying && (
            <div className="absolute inset-0 flex items-center justify-center">
              <Button
                variant="secondary"
                size="icon"
                className="h-16 w-16 rounded-full opacity-80 hover:opacity-100"
                onClick={togglePlayPause}
              >
                <Play className="h-8 w-8" />
              </Button>
            </div>
          )}
        </div>
        
        {/* Video Controls */}
        <div className="space-y-2">
          {/* Progress Bar */}
          <div className="flex items-center gap-2">
            <span className="text-xs text-muted-foreground min-w-[40px]">
              {formatDuration(currentTime)}
            </span>
            <Slider
              value={[currentTime]}
              max={duration || 100}
              step={0.1}
              onValueChange={handleSeek}
              className="flex-1"
            />
            <span className="text-xs text-muted-foreground min-w-[40px]">
              {formatDuration(duration)}
            </span>
          </div>
          
          {/* Control Buttons */}
          <div className="flex items-center gap-2">
            {/* Play/Pause */}
            <Button
              variant="outline"
              size="icon"
              onClick={togglePlayPause}
            >
              {isPlaying ? (
                <Pause className="h-4 w-4" />
              ) : (
                <Play className="h-4 w-4" />
              )}
            </Button>
            
            {/* Mute/Unmute */}
            <Button
              variant="outline"
              size="icon"
              onClick={toggleMute}
            >
              {isMuted ? (
                <VolumeX className="h-4 w-4" />
              ) : (
                <Volume2 className="h-4 w-4" />
              )}
            </Button>
            
            {/* Volume Slider */}
            <div className="flex items-center gap-2 flex-1 max-w-[200px]">
              <Slider
                value={[volume]}
                max={1}
                step={0.01}
                onValueChange={handleVolumeChange}
              />
            </div>
          </div>
        </div>
        
        {/* Metadata */}
        <div className="space-y-2">
          <h4 className="text-sm font-semibold">Metadata</h4>
          <div className="grid grid-cols-2 gap-2 text-sm">
            {/* Dimensions */}
            {dimensions && (
              <div className="flex items-center gap-2">
                <VideoIcon className="h-4 w-4 text-muted-foreground" />
                <span className="text-muted-foreground">Dimensions:</span>
                <Badge variant="secondary">
                  {dimensions.width} ├ù {dimensions.height}
                </Badge>
              </div>
            )}
            
            {/* Duration */}
            {videoDuration > 0 && (
              <div className="flex items-center gap-2">
                <Clock className="h-4 w-4 text-muted-foreground" />
                <span className="text-muted-foreground">Duration:</span>
                <Badge variant="secondary">{formatDuration(videoDuration)}</Badge>
              </div>
            )}
            
            {/* File Size */}
            <div className="flex items-center gap-2">
              <HardDrive className="h-4 w-4 text-muted-foreground" />
              <span className="text-muted-foreground">Size:</span>
              <Badge variant="secondary">{formatFileSizeLocal(fileSize)}</Badge>
            </div>
            
            {/* Format */}
            <div className="flex items-center gap-2">
              <VideoIcon className="h-4 w-4 text-muted-foreground" />
              <span className="text-muted-foreground">Format:</span>
              <Badge variant="secondary">{format.toUpperCase()}</Badge>
            </div>
            
            {/* Timestamp */}
            <div className="flex items-center gap-2 col-span-2">
              <Calendar className="h-4 w-4 text-muted-foreground" />
              <span className="text-muted-foreground">Created:</span>
              <Badge variant="secondary">{formatTimestamp(asset.timestamp)}</Badge>
            </div>
          </div>
        </div>
        
        <Separator />
        
        {/* Generation Parameters */}
        <div className="space-y-2">
          <h4 className="text-sm font-semibold">Generation Parameters</h4>
          <div className="grid grid-cols-2 gap-2 text-sm">
            {generationParams.frameCount && (
              <div>
                <span className="text-muted-foreground">Frame Count:</span>{' '}
                <span className="font-medium">{generationParams.frameCount}</span>
              </div>
            )}
            {generationParams.frameRate && (
              <div>
                <span className="text-muted-foreground">Frame Rate:</span>{' '}
                <span className="font-medium">{generationParams.frameRate} fps</span>
              </div>
            )}
            {generationParams.motionStrength !== undefined && (
              <div>
                <span className="text-muted-foreground">Motion Strength:</span>{' '}
                <span className="font-medium">{generationParams.motionStrength}</span>
              </div>
            )}
            {generationParams.seed !== undefined && (
              <div>
                <span className="text-muted-foreground">Seed:</span>{' '}
                <span className="font-medium">{generationParams.seed}</span>
              </div>
            )}
          </div>
          
          {/* Motion Prompt */}
          {generationParams.prompt && (
            <div className="mt-2">
              <span className="text-muted-foreground text-sm">Motion Description:</span>
              <p className="text-sm mt-1 p-2 bg-muted rounded-md">
                {generationParams.prompt}
              </p>
            </div>
          )}
          
          {/* Source Image Path */}
          {generationParams.inputImagePath && (
            <div className="mt-2">
              <span className="text-muted-foreground text-sm">Source Image:</span>
              <p className="text-sm mt-1 p-2 bg-muted rounded-md font-mono">
                {generationParams.inputImagePath}
              </p>
            </div>
          )}
        </div>
      </CardContent>
      
      <CardFooter className="flex flex-wrap gap-2">
        {/* Save Button */}
        {onSave && (
          <Button variant="outline" onClick={handleSave}>
            <Download className="mr-2 h-4 w-4" />
            Save
          </Button>
        )}
        
        {/* Regenerate Button */}
        {onRegenerate && (
          <Button variant="outline" onClick={handleRegenerate}>
            <RefreshCw className="mr-2 h-4 w-4" />
            Regenerate
          </Button>
        )}
        
        {/* Generate Audio Button */}
        {onGenerateAudio && (
          <Button
            onClick={handleGenerateAudio}
            disabled={!canGenerateAudio}
            className="ml-auto"
          >
            <Mic className="mr-2 h-4 w-4" />
            Generate Audio
          </Button>
        )}
      </CardFooter>
    </Card>
  );
};

/**
 * Asset Preview Panel Tests
 * 
 * Tests for the unified asset preview component.
 * Validates asset display, metadata viewer, export controls, regenerate button, and related assets.
 * 
 * Requirements: 9.2, 9.3, 9.4
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, fireEvent, within } from '@testing-library/react';
import { AssetPreviewPanel } from '../AssetPreviewPanel';
import type { GeneratedAsset } from '../../../types/generation';

describe('AssetPreviewPanel', () => {
  // Mock assets
  const mockImageAsset: GeneratedAsset = {
    id: 'asset-1',
    type: 'image',
    url: 'https://example.com/image.png',
    metadata: {
      generationParams: {
        prompt: 'A beautiful landscape',
        steps: 30,
        cfgScale: 7.5,
        sampler: 'euler',
        scheduler: 'normal',
        seed: 12345,
      },
      fileSize: 2048000,
      dimensions: { width: 1024, height: 768 },
      format: 'png',
    },
    relatedAssets: ['asset-2', 'asset-3'],
    timestamp: Date.now(),
  };
  
  const mockVideoAsset: GeneratedAsset = {
    id: 'asset-2',
    type: 'video',
    url: 'https://example.com/video.mp4',
    metadata: {
      generationParams: {
        prompt: 'Camera pans left',
        frameCount: 120,
        frameRate: 24,
        motionStrength: 0.8,
        inputImagePath: '/path/to/image.png',
      },
      fileSize: 10240000,
      dimensions: { width: 1920, height: 1080 },
      duration: 5,
      format: 'mp4',
    },
    relatedAssets: ['asset-1', 'asset-3'],
    timestamp: Date.now(),
  };
  
  const mockAudioAsset: GeneratedAsset = {
    id: 'asset-3',
    type: 'audio',
    url: 'https://example.com/audio.wav',
    metadata: {
      generationParams: {
        text: 'This is a narration',
        voiceType: 'female',
        speed: 1.0,
        pitch: 0,
        language: 'en-US',
        emotion: 'neutral',
      },
      fileSize: 512000,
      duration: 3,
      format: 'wav',
    },
    relatedAssets: ['asset-1', 'asset-2'],
    timestamp: Date.now(),
  };
  
  const mockPromptAsset: GeneratedAsset = {
    id: 'asset-4',
    type: 'prompt',
    url: '',
    metadata: {
      generationParams: {
        text: 'A cinematic shot of a sunset over mountains',
        categories: {
          genre: 'landscape',
          shotType: 'wide',
          lighting: 'golden hour',
        },
      },
      fileSize: 128,
      format: 'txt',
    },
    relatedAssets: [],
    timestamp: Date.now(),
  };
  
  const mockRelatedAssets: GeneratedAsset[] = [
    mockImageAsset,
    mockVideoAsset,
    mockAudioAsset,
  ];
  
  // Mock callbacks
  let mockOnSave: ReturnType<typeof vi.fn>;
  let mockOnExport: ReturnType<typeof vi.fn>;
  let mockOnRegenerate: ReturnType<typeof vi.fn>;
  let mockOnRelatedAssetClick: ReturnType<typeof vi.fn>;
  
  beforeEach(() => {
    mockOnSave = vi.fn();
    mockOnExport = vi.fn();
    mockOnRegenerate = vi.fn();
    mockOnRelatedAssetClick = vi.fn();
  });
  
  describe('Image Asset Display', () => {
    it('should render image asset using ImagePreviewPanel', () => {
      render(
        <AssetPreviewPanel
          asset={mockImageAsset}
          onSave={mockOnSave}
          onRegenerate={mockOnRegenerate}
        />
      );
      
      // Should use ImagePreviewPanel which displays "Generated Image"
      expect(screen.getByText('Generated Image')).toBeInTheDocument();
    });
    
    it('should display related assets for image', () => {
      render(
        <AssetPreviewPanel
          asset={mockImageAsset}
          relatedAssets={mockRelatedAssets}
          onRelatedAssetClick={mockOnRelatedAssetClick}
        />
      );
      
      expect(screen.getByText('Related Assets in Pipeline')).toBeInTheDocument();
    });
  });
  
  describe('Video Asset Display', () => {
    it('should render video asset using VideoPreviewPanel', () => {
      render(
        <AssetPreviewPanel
          asset={mockVideoAsset}
          onSave={mockOnSave}
          onRegenerate={mockOnRegenerate}
        />
      );
      
      // Should use VideoPreviewPanel which displays "Generated Video"
      expect(screen.getByText('Generated Video')).toBeInTheDocument();
    });
    
    it('should display related assets for video', () => {
      render(
        <AssetPreviewPanel
          asset={mockVideoAsset}
          relatedAssets={mockRelatedAssets}
          onRelatedAssetClick={mockOnRelatedAssetClick}
        />
      );
      
      expect(screen.getByText('Related Assets in Pipeline')).toBeInTheDocument();
    });
  });
  
  describe('Audio Asset Display', () => {
    it('should render audio asset using AudioPreviewPanel', () => {
      render(
        <AssetPreviewPanel
          asset={mockAudioAsset}
          onSave={mockOnSave}
          onRegenerate={mockOnRegenerate}
        />
      );
      
      // Should use AudioPreviewPanel which displays "Generated Audio"
      expect(screen.getByText('Generated Audio')).toBeInTheDocument();
    });
    
    it('should display related assets for audio', () => {
      render(
        <AssetPreviewPanel
          asset={mockAudioAsset}
          relatedAssets={mockRelatedAssets}
          onRelatedAssetClick={mockOnRelatedAssetClick}
        />
      );
      
      expect(screen.getByText('Related Assets in Pipeline')).toBeInTheDocument();
    });
  });
  
  describe('Prompt Asset Display', () => {
    it('should render prompt asset with generic preview', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
          onSave={mockOnSave}
          onRegenerate={mockOnRegenerate}
        />
      );
      
      expect(screen.getByText('Generated Prompt')).toBeInTheDocument();
      expect(screen.getByText('A cinematic shot of a sunset over mountains')).toBeInTheDocument();
    });
    
    it('should display metadata for prompt asset', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
          onSave={mockOnSave}
          onRegenerate={mockOnRegenerate}
        />
      );
      
      expect(screen.getByText('Metadata')).toBeInTheDocument();
      expect(screen.getByText('128 B')).toBeInTheDocument();
      expect(screen.getByText('TXT')).toBeInTheDocument();
    });
    
    it('should display generation parameters for prompt asset', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
          onSave={mockOnSave}
          onRegenerate={mockOnRegenerate}
        />
      );
      
      expect(screen.getByText('Generation Parameters')).toBeInTheDocument();
    });
  });
  
  describe('Metadata Viewer', () => {
    it('should display file size in human-readable format', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
          onSave={mockOnSave}
        />
      );
      
      expect(screen.getByText('128 B')).toBeInTheDocument();
    });
    
    it('should display format in uppercase', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
          onSave={mockOnSave}
        />
      );
      
      expect(screen.getByText('TXT')).toBeInTheDocument();
    });
    
    it('should display timestamp', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
          onSave={mockOnSave}
        />
      );
      
      expect(screen.getByText(/Created:/)).toBeInTheDocument();
    });
  });
  
  describe('Export Controls', () => {
    it('should display export button when onExport is provided', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
          onExport={mockOnExport}
        />
      );
      
      // Prompt assets only have 'original' format, so no format selector is shown
      expect(screen.getByText(/Export as/)).toBeInTheDocument();
    });
    
    it('should allow selecting export format', () => {
      render(
        <AssetPreviewPanel
          asset={mockImageAsset}
          onExport={mockOnExport}
        />
      );
      
      // Note: For image assets, it uses ImagePreviewPanel which doesn't show export formats
      // This test would work for prompt assets
    });
    
    it('should call onExport with selected format', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
          onExport={mockOnExport}
        />
      );
      
      const exportButton = screen.getByText(/Export as/);
      fireEvent.click(exportButton);
      
      expect(mockOnExport).toHaveBeenCalledWith(mockPromptAsset, 'original');
    });
    
    it('should update export button text when format changes', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
          onExport={mockOnExport}
        />
      );
      
      expect(screen.getByText('Export as ORIGINAL')).toBeInTheDocument();
    });
  });
  
  describe('Action Buttons', () => {
    it('should render save button when onSave is provided', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
          onSave={mockOnSave}
        />
      );
      
      expect(screen.getByText('Save')).toBeInTheDocument();
    });
    
    it('should call onSave when save button is clicked', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
          onSave={mockOnSave}
        />
      );
      
      const saveButton = screen.getByText('Save');
      fireEvent.click(saveButton);
      
      expect(mockOnSave).toHaveBeenCalledWith(mockPromptAsset);
    });
    
    it('should render regenerate button when onRegenerate is provided', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
          onRegenerate={mockOnRegenerate}
        />
      );
      
      expect(screen.getByText('Regenerate')).toBeInTheDocument();
    });
    
    it('should call onRegenerate when regenerate button is clicked', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
          onRegenerate={mockOnRegenerate}
        />
      );
      
      const regenerateButton = screen.getByText('Regenerate');
      fireEvent.click(regenerateButton);
      
      expect(mockOnRegenerate).toHaveBeenCalled();
    });
    
    it('should not render buttons when callbacks are not provided', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
        />
      );
      
      expect(screen.queryByText('Save')).not.toBeInTheDocument();
      expect(screen.queryByText('Regenerate')).not.toBeInTheDocument();
    });
  });
  
  describe('Related Assets', () => {
    it('should display related assets section when provided', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
          relatedAssets={mockRelatedAssets}
        />
      );
      
      expect(screen.getByText('Related Assets in Pipeline')).toBeInTheDocument();
    });
    
    it('should not display related assets section when empty', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
          relatedAssets={[]}
        />
      );
      
      expect(screen.queryByText('Related Assets in Pipeline')).not.toBeInTheDocument();
    });
    
    it('should display thumbnails for related assets', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
          relatedAssets={mockRelatedAssets}
        />
      );
      
      const relatedSection = screen.getByText('Related Assets in Pipeline').closest('div');
      expect(relatedSection).toBeInTheDocument();
      
      // Should have 3 related assets
      const buttons = screen.getAllByRole('button');
      const assetButtons = buttons.filter(btn => 
        btn.className.includes('aspect-square')
      );
      expect(assetButtons.length).toBe(3);
    });
    
    it('should call onRelatedAssetClick when related asset is clicked', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
          relatedAssets={mockRelatedAssets}
          onRelatedAssetClick={mockOnRelatedAssetClick}
        />
      );
      
      const assetButtons = screen.getAllByRole('button').filter(btn => 
        btn.className.includes('aspect-square')
      );
      
      fireEvent.click(assetButtons[0]);
      
      expect(mockOnRelatedAssetClick).toHaveBeenCalledWith(mockRelatedAssets[0]);
    });
    
    it('should display asset type labels in related assets', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
          relatedAssets={mockRelatedAssets}
        />
      );
      
      // Hover over first asset to see label
      const assetButtons = screen.getAllByRole('button').filter(btn => 
        btn.className.includes('aspect-square')
      );
      
      fireEvent.mouseEnter(assetButtons[0]);
      
      // Labels should be in the DOM (even if not visible)
      expect(screen.getByText('Image')).toBeInTheDocument();
    });
  });
  
  describe('Asset Type Handling', () => {
    it('should handle image assets correctly', () => {
      render(
        <AssetPreviewPanel
          asset={mockImageAsset}
        />
      );
      
      expect(screen.getByText('Generated Image')).toBeInTheDocument();
    });
    
    it('should handle video assets correctly', () => {
      render(
        <AssetPreviewPanel
          asset={mockVideoAsset}
        />
      );
      
      expect(screen.getByText('Generated Video')).toBeInTheDocument();
    });
    
    it('should handle audio assets correctly', () => {
      render(
        <AssetPreviewPanel
          asset={mockAudioAsset}
        />
      );
      
      expect(screen.getByText('Generated Audio')).toBeInTheDocument();
    });
    
    it('should handle prompt assets correctly', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
        />
      );
      
      expect(screen.getByText('Generated Prompt')).toBeInTheDocument();
    });
  });
  
  describe('Accessibility', () => {
    it('should have accessible buttons', () => {
      render(
        <AssetPreviewPanel
          asset={mockPromptAsset}
          onSave={mockOnSave}
          onRegenerate={mockOnRegenerate}
        />
      );
      
      const saveButton = screen.getByText('Save');
      const regenerateButton = screen.getByText('Regenerate');
      
