      fileSize: 2048,
      dimensions: { width: 1024, height: 768 },
      format: 'png',
    },
    relatedAssets: [],
    timestamp: Date.now(),
  };

  const mockVideo: GeneratedAsset = {
    id: 'video-1',
    type: 'video',
    url: '/test-video.mp4',
    metadata: {
      generationParams: {},
      fileSize: 10240,
