        <PromptGenerationDialog
          isOpen={false}
          onClose={mockOnClose}
          onGenerate={mockOnGenerate}
        />
      );
      
      // Reopen dialog
      rerender(
        <PromptGenerationDialog
          isOpen={true}
          onClose={mockOnClose}
          onGenerate={mockOnGenerate}
        />
      );
      
      // Should not show generated prompt
      expect(screen.queryByLabelText(/Generated Prompt/i)).not.toBeInTheDocument();
    });
  });
});

