    // Try to generate
    const generateButton = screen.getByRole('button', { name: /Generate Video/ });
    await user.click(generateButton);
    
    // Should show validation error
    await waitFor(() => {
      expect(screen.getByText('Width must be divisible by 8')).toBeInTheDocument();
