              Show Grid Lines
            </label>
          </div>

          <div style={{ marginBottom: '12px' }}>
            <label style={{ display: 'flex', alignItems: 'center', fontSize: '12px' }}>
              <input
                type="checkbox"
                checked={config.snapEnabled}
                onChange={(e) => onConfigChange({ snapEnabled: e.target.checked })}
                style={{ marginRight: '8px' }}
