              Snap to Grid
            </label>
          </div>

          <div style={{ fontSize: '10px', color: '#666', marginTop: '12px' }}>
            {responsive.breakpoint.name} ÔÇó {responsive.orientation}
          </div>
        </div>
      )}
    </motion.div>
  );
};

/**
