};

// ============================================================================
// Example: Conditional Keyboard Shortcuts
// ============================================================================

export const ConditionalShortcutsExample: React.FC = () => {
  const [shortcutsEnabled, setShortcutsEnabled] = useState(true);
  const gridBounds = { width: 1920, height: 1080 };

