/**
 * Installation Step Component
 * Executes installation and displays progress
 */

import React, { useState, useEffect, useRef } from 'react';
import { Play, Loader2, AlertTriangle, CheckCircle, XCircle, RotateCcw, Clock } from 'lucide-react';
import { InstallationStepProps } from '../../types/installation';

export const InstallationStep: React.FC<InstallationStepProps> = ({
  canInstall,
  isInstalling,
  progress,
  statusMessage,
  error,
  onInstall,
  onRetry
}) => {
  const [estimatedTimeRemaining, setEstimatedTimeRemaining] = useState<number | null>(null);
  const [statusLog, setStatusLog] = useState<Array<{ timestamp: number; message: string }>>([]);
  const startTimeRef = useRef<number | null>(null);
  const lastProgressRef = useRef<number>(0);

  // Track installation start time
  useEffect(() => {
    if (isInstalling && startTimeRef.current === null) {
      startTimeRef.current = Date.now();
      lastProgressRef.current = progress;
    } else if (!isInstalling) {
      startTimeRef.current = null;
      lastProgressRef.current = 0;
    }
  }, [isInstalling, progress]);

  // Calculate estimated time remaining
  useEffect(() => {
    if (isInstalling && startTimeRef.current && progress > 0 && progress < 100) {
      const elapsedTime = Date.now() - startTimeRef.current;
      const progressDelta = progress - lastProgressRef.current;
      
      if (progressDelta > 0) {
        const timePerPercent = elapsedTime / progress;
        const remainingProgress = 100 - progress;
        const estimatedMs = timePerPercent * remainingProgress;
        setEstimatedTimeRemaining(Math.ceil(estimatedMs / 1000)); // Convert to seconds
        lastProgressRef.current = progress;
      }
    } else {
      setEstimatedTimeRemaining(null);
    }
  }, [isInstalling, progress]);

  // Update status log
  useEffect(() => {
    if (statusMessage && isInstalling) {
      setStatusLog(prev => {
        const newLog = [...prev, { timestamp: Date.now(), message: statusMessage }];
        // Keep only last 10 messages
        return newLog.slice(-10);
      });
    } else if (!isInstalling && progress === 0) {
      setStatusLog([]);
    }
  }, [statusMessage, isInstalling, progress]);

  // Format time remaining
  const formatTimeRemaining = (seconds: number): string => {
    if (seconds < 60) {
      return `${seconds} second${seconds !== 1 ? 's' : ''}`;
    }
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    if (remainingSeconds === 0) {
      return `${minutes} minute${minutes !== 1 ? 's' : ''}`;
    }
    return `${minutes}m ${remainingSeconds}s`;
  };
  const getTooltipText = (): string => {
    if (isInstalling) {
      return 'Installation in progress...';
    }
    if (!canInstall) {
      return 'Place the ZIP file in the download zone first';
    }
    return 'Click to start installation';
  };

  const getButtonContent = () => {
    if (isInstalling) {
      return (
        <>
          <Loader2 className="w-5 h-5 animate-spin" />
          Installing...
        </>
      );
    }
    if (error) {
      return (
        <>
          <XCircle className="w-5 h-5" />
          Installation Failed
        </>
      );
    }
    if (progress === 100) {
      return (
        <>
          <CheckCircle className="w-5 h-5" />
          Installation Complete
        </>
      );
    }
    return (
      <>
        <Play className="w-5 h-5" />
        Start Installation
      </>
    );
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="text-center">
        <div className="mx-auto w-16 h-16 bg-green-100 dark:bg-green-900/30 rounded-full flex items-center justify-center mb-4">
          {isInstalling ? (
            <Loader2 className="w-8 h-8 text-green-600 dark:text-green-400 animate-spin" />
          ) : error ? (
            <XCircle className="w-8 h-8 text-red-600 dark:text-red-400" />
          ) : progress === 100 ? (
            <CheckCircle className="w-8 h-8 text-green-600 dark:text-green-400" />
          ) : (
            <Play className="w-8 h-8 text-green-600 dark:text-green-400" />
          )}
        </div>
        <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">
          {isInstalling ? 'Installing ComfyUI' : error ? 'Installation Error' : progress === 100 ? 'Installation Complete' : 'Ready to Install'}
        </h2>
        <p className="text-gray-600 dark:text-gray-400">
          {isInstalling
            ? 'Please wait while we set up ComfyUI...'
            : error
            ? 'An error occurred during installation'
            : progress === 100
            ? 'ComfyUI has been successfully installed'
            : 'Click the button below to begin installation'}
        </p>
      </div>

      {/* Installation Button */}
      {!isInstalling && progress < 100 && (
        <div className="bg-gradient-to-br from-green-50 to-emerald-50 dark:from-green-900/20 dark:to-emerald-900/20 border-2 border-green-200 dark:border-green-800 rounded-xl p-6">
          <div className="text-center space-y-4">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
              Step 3: Install ComfyUI
            </h3>

            <button
              onClick={onInstall}
              disabled={!canInstall || isInstalling}
              title={getTooltipText()}
              className={`inline-flex items-center gap-2 px-8 py-4 font-semibold rounded-lg transition-all shadow-lg ${
                canInstall && !isInstalling
                  ? 'bg-green-600 hover:bg-green-700 text-white hover:shadow-xl cursor-pointer'
                  : 'bg-gray-300 dark:bg-gray-700 text-gray-500 dark:text-gray-400 cursor-not-allowed'
              }`}
            >
              {getButtonContent()}
            </button>

            {canInstall && !isInstalling && (
              <p className="text-sm text-green-700 dark:text-green-300 font-medium">
                Ô£ô Ready to install
              </p>
            )}

            {!canInstall && !isInstalling && (
              <p className="text-sm text-gray-600 dark:text-gray-400">
                Waiting for ZIP file to be placed in download zone...
              </p>
            )}
          </div>
        </div>
      )}

      {/* Progress Bar */}
      {(isInstalling || progress > 0) && progress < 100 && (
        <div className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg p-6">
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h3 className="font-semibold text-gray-900 dark:text-white">
                Installation Progress
              </h3>
              <span className="text-sm font-medium text-gray-600 dark:text-gray-400">
                {progress}%
              </span>
            </div>

            {/* Progress Bar */}
            <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-3 overflow-hidden">
              <div
                className="bg-gradient-to-r from-green-500 to-emerald-500 h-full transition-all duration-500 ease-out rounded-full"
                style={{ width: `${progress}%` }}
              />
            </div>

            {/* Status Message */}
            {statusMessage && (
              <div className="flex items-center gap-2 text-sm text-gray-700 dark:text-gray-300">
                <Loader2 className="w-4 h-4 animate-spin text-green-600" />
                <span>{statusMessage}</span>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Status Log */}
      {isInstalling && statusLog.length > 0 && (
        <div className="bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-lg p-4">
          <h3 className="font-semibold text-gray-900 dark:text-white mb-3 text-sm">
            Installation Log
          </h3>
          <div className="space-y-1 max-h-48 overflow-y-auto">
            {statusLog.map((log, index) => (
              <div key={index} className="text-xs font-mono text-gray-600 dark:text-gray-400 flex items-start gap-2">
                <span className="text-gray-400 dark:text-gray-600 flex-shrink-0">
                  {new Date(log.timestamp).toLocaleTimeString()}
                </span>
                <span className="flex-1">{log.message}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Error Display */}
      {error && (
        <div className="bg-red-50 dark:bg-red-900/20 border-2 border-red-200 dark:border-red-800 rounded-lg p-6">
          <div className="flex items-start gap-4">
            <AlertTriangle className="w-6 h-6 text-red-600 dark:text-red-400 flex-shrink-0 mt-0.5" />
            <div className="flex-1">
              <h3 className="font-semibold text-red-900 dark:text-red-200 mb-2">
                Installation Failed
              </h3>
              <p className="text-sm text-red-800 dark:text-red-300 mb-4">
                {error}
              </p>
              <button
                onClick={onRetry}
                className="inline-flex items-center gap-2 px-4 py-2 bg-red-600 hover:bg-red-700 text-white font-medium rounded-lg transition-colors"
              >
                <RotateCcw className="w-4 h-4" />
                Retry Installation
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Success Display */}
      {progress === 100 && !error && (
        <div className="bg-green-50 dark:bg-green-900/20 border-2 border-green-200 dark:border-green-800 rounded-lg p-6">
          <div className="flex items-start gap-4">
            <CheckCircle className="w-6 h-6 text-green-600 dark:text-green-400 flex-shrink-0 mt-0.5" />
            <div className="flex-1">
              <h3 className="font-semibold text-green-900 dark:text-green-200 mb-2">
                Installation Successful!
              </h3>
              <p className="text-sm text-green-800 dark:text-green-300">
                ComfyUI Portable has been installed successfully with CORS enabled.
                You can now proceed to the next step.
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Installation Info */}
      {!isInstalling && progress === 0 && !error && (
        <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg p-4">
          <div className="flex items-start gap-3">
            <AlertTriangle className="w-5 h-5 text-blue-600 dark:text-blue-400 flex-shrink-0 mt-0.5" />
            <div>
              <h3 className="font-semibold text-blue-900 dark:text-blue-200 mb-1">
                What will be installed?
              </h3>
              <ul className="text-sm text-blue-800 dark:text-blue-300 space-y-1">
                <li>ÔÇó ComfyUI Portable (extracted from ZIP)</li>
                <li>ÔÇó CORS configuration for UI integration</li>
                <li>ÔÇó Required models and workflows</li>
                <li>ÔÇó Startup scripts with proper settings</li>
              </ul>
            </div>
          </div>
        </div>
      )}

      {/* Estimated Time */}
      {isInstalling && estimatedTimeRemaining !== null && (
        <div className="text-center space-y-2">
          <div className="flex items-center justify-center gap-2 text-sm text-gray-600 dark:text-gray-400">
            <Clock className="w-4 h-4" />
            <p>Estimated time remaining: {formatTimeRemaining(estimatedTimeRemaining)}</p>
          </div>
          <p className="text-xs text-gray-500 dark:text-gray-500">
            Please do not close this window
          </p>
        </div>
      )}

      {isInstalling && estimatedTimeRemaining === null && progress > 0 && (
        <div className="text-center text-sm text-gray-600 dark:text-gray-400">
          <p>Calculating estimated time...</p>
          <p className="text-xs mt-1">Please do not close this window</p>
        </div>
      )}
    </div>
  );
};

/**
 * Installation Wizard Modal
 * Main container component that orchestrates the installation wizard
 */

import React, { useEffect, useState, useCallback } from 'react';
import { X, ChevronRight, Check, Settings, ShieldCheck, Cpu } from 'lucide-react';
import { InstallationWizardModalProps } from '../../types/installation';
import { useInstallationWizard } from '../../contexts/InstallationWizardContext';
import { useFileDetection } from '../../hooks/useFileDetection';
import { INSTALLATION_CONFIG } from '../../config/installationConfig';
import { installationApi } from '../../services/installationApiService';
import { DownloadStep } from './DownloadStep';
import { PlacementStep } from './PlacementStep';
import { InstallationStep } from './InstallationStep';
import { CompletionStep } from './CompletionStep';
import '../wizard/WizardModal.css';

export const InstallationWizardModal: React.FC<InstallationWizardModalProps> = ({
  isOpen,
  onClose,
  onComplete
}) => {
  const {
    wizardState,
    setCurrentStep,
    setFileDetected,
    setInstallationProgress,
    setInstallationError,
    setInstallationComplete,
    resetWizard
  } = useInstallationWizard();

  const [downloadZonePath, setDownloadZonePath] = useState('');
  const [isInitialized, setIsInitialized] = useState(false);

  // File detection hook
  const {
    fileDetected,
    fileValid,
    validationResult,
    refresh: refreshFileDetection
  } = useFileDetection({
    downloadZonePath,
    enabled: isOpen && wizardState.currentStep === 'placement'
  });

  // Handle Escape key
  const handleKeyDown = useCallback(
    (event: KeyboardEvent) => {
      if (event.key === 'Escape' && !(wizardState.installationProgress > 0 && wizardState.installationProgress < 100)) {
        handleClose();
      }
    },
    [onClose, wizardState.installationProgress]
  );

  useEffect(() => {
    if (isOpen) {
      window.addEventListener('keydown', handleKeyDown);
      document.body.style.overflow = 'hidden';
      if (!isInitialized) {
        initializeWizard();
      }
    } else {
      window.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = 'unset';
    }

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = 'unset';
    };
  }, [isOpen, handleKeyDown, isInitialized]);

  // Update file detection state
  useEffect(() => {
    setFileDetected(fileDetected, fileValid);
  }, [fileDetected, fileValid, setFileDetected]);

  // Auto-advance to installation step when file is valid
  useEffect(() => {
    if (wizardState.currentStep === 'placement' && fileDetected && fileValid) {
      const timer = setTimeout(() => {
        setCurrentStep('installation');
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [wizardState.currentStep, fileDetected, fileValid, setCurrentStep]);

  const initializeWizard = async () => {
    try {
      const response = await installationApi.initialize();

      if (!response.success || !response.data) {
        throw new Error(response.error || 'Failed to initialize wizard');
      }

      setDownloadZonePath(response.data.downloadZonePath);
      setIsInitialized(true);
    } catch (error) {
      console.error('Wizard initialization error:', error);
      setInstallationError('Failed to initialize installation wizard');
    }
  };

  const handleDownloadClick = () => {
    setTimeout(() => {
      setCurrentStep('placement');
    }, 500);
  };

  const handleOpenFolder = async () => {
    try {
      if ((window as any).electronAPI?.openFolder) {
        await (window as any).electronAPI.openFolder(downloadZonePath);
      } else {
        alert(`Please navigate to this folder:\n\n${downloadZonePath}\n\nCopy the ComfyUI Portable ZIP file into this folder.`);
        try {
          await navigator.clipboard.writeText(downloadZonePath);
        } catch (clipboardError) {
          console.warn('Could not copy to clipboard:', clipboardError);
        }
      }
    } catch (error) {
      console.error('Failed to open folder:', error);
      alert(`Could not open folder. Please manually navigate to:\n\n${downloadZonePath}`);
    }
  };

  const handleInstall = async () => {
    try {
      setInstallationProgress(0, 'Starting installation...');

      const zipFilePath = validationResult?.fileName
        ? `${downloadZonePath}/${validationResult.fileName}`
        : '';

      const cleanup = await installationApi.install(
        {
          zipFilePath,
          enableCORS: true,
          installModels: INSTALLATION_CONFIG.requiredModels.map(m => m.id),
          installWorkflows: INSTALLATION_CONFIG.requiredWorkflows.map(w => w.id)
        },
        (update) => {
          setInstallationProgress(update.progress, update.message);

          if (update.error) {
            setInstallationError(update.error);
            return;
          }

          if (update.progress >= 100) {
            performPostInstallationVerification({
              comfyui_path: '',
              comfyui_url: 'http://127.0.0.1:8188',
              installed_models: [],
              installed_workflows: []
            });
          }
        },
        (error) => {
          console.error('Installation error:', error);
          setInstallationError(error.message);
        }
      );

      (window as any).__installationCleanup = cleanup;

    } catch (error) {
      console.error('Installation error:', error);
      setInstallationError(error instanceof Error ? error.message : 'Installation failed');
    }
  };

  const performPostInstallationVerification = async (installResult: any) => {
    try {
      setInstallationProgress(95, 'Verifying installation...');
      const verifyResponse = await installationApi.verify();
      
      if (!verifyResponse.success || !verifyResponse.data) {
        throw new Error(verifyResponse.error || 'Verification failed');
      }

      const verifyData = verifyResponse.data;
      setInstallationProgress(99, 'Updating configuration...');
      
      try {
        await updateApplicationConfiguration({
          comfyUIInstalled: true,
          comfyUIPath: installResult.comfyui_path,
          comfyUIUrl: verifyData.url || 'http://127.0.0.1:8188',
          installedAt: new Date().toISOString()
        });
      } catch (configError) {
        console.warn('Could not update configuration:', configError);
      }

      setInstallationProgress(100, 'Installation complete!');
      
      setInstallationComplete(
        verifyData.url || 'http://127.0.0.1:8188',
        verifyData.models || [],
        verifyData.workflows || []
      );

    } catch (error) {
      console.error('Post-installation verification error:', error);
      setInstallationError(
        error instanceof Error 
          ? `Verification failed: ${error.message}` 
          : 'Post-installation verification failed'
      );
    }
  };

  const updateApplicationConfiguration = async (config: any) => {
    try {
      localStorage.setItem('comfyui_config', JSON.stringify(config));
      return true;
    } catch (error) {
      console.error('Failed to update configuration:', error);
      throw error;
    }
  };

  const handleRetry = () => {
    setInstallationError(null);
    setInstallationProgress(0, '');
    handleInstall();
  };

  const handleOpenComfyUI = () => {
    if (wizardState.comfyUIUrl) {
      window.open(wizardState.comfyUIUrl, '_blank', 'noopener,noreferrer');
    }
  };

  const handleClose = () => {
    if ((window as any).__installationCleanup) {
      (window as any).__installationCleanup();
      delete (window as any).__installationCleanup;
    }
    
    installationApi.disconnect();
    
    if (wizardState.currentStep === 'completion') {
      onComplete(wizardState.comfyUIUrl || '');
    }
    resetWizard();
    setIsInitialized(false);
    onClose();
  };

  if (!isOpen) return null;

  const steps = [
    { id: 'download', label: 'Download', number: 1 },
    { id: 'placement', label: 'Place File', number: 2 },
    { id: 'installation', label: 'Install', number: 3 },
    { id: 'completion', label: 'Complete', number: 4 }
  ];

  const currentStepIndex = steps.findIndex(s => s.id === wizardState.currentStep);

  return (
    <div className="wizard-modal-overlay" onClick={() => !(wizardState.installationProgress > 0 && wizardState.installationProgress < 100) && handleClose()}>
      <div className="wizard-modal-container max-w-4xl" onClick={(e) => e.stopPropagation()}>
        <div className="wizard-modal-header">
           <div className="flex items-center gap-3">
            <div className="p-2 bg-blue-500/20 rounded-lg text-blue-400">
              <Settings size={20} className={wizardState.installationProgress > 0 && wizardState.installationProgress < 100 ? "animate-spin" : ""} />
            </div>
            <div className="flex flex-col">
              <h2 className="wizard-modal-title">System Setup Wizard</h2>
              <span className="text-[10px] text-blue-400/70 uppercase tracking-widest font-black">Environment Provisioning Engine</span>
            </div>
          </div>
          <button
            className="wizard-modal-close"
            onClick={handleClose}
            aria-label="Fermer"
            disabled={wizardState.installationProgress > 0 && wizardState.installationProgress < 100}
          >
            <X size={20} />
          </button>
        </div>

        <div className="wizard-modal-content p-8">
           {/* Progress Line */}
           <div className="flex items-center justify-between mb-12 bg-black/40 p-6 rounded-2xl border border-white/5 shadow-inner">
             {steps.map((step, index) => (
               <React.Fragment key={step.id}>
                 <div className="flex flex-col items-center gap-2 relative z-10">
                   <div className={`w-10 h-10 rounded-full flex items-center justify-center font-black text-sm transition-all duration-500 ${
                     index < currentStepIndex 
                       ? 'bg-emerald-500 text-white shadow-[0_0_15px_rgba(16,185,129,0.4)]' 
                       : index === currentStepIndex 
                       ? 'bg-blue-600 text-white shadow-[0_0_15px_rgba(37,99,235,0.4)] ring-4 ring-blue-500/20' 
                       : 'bg-black/40 border border-white/10 text-slate-500'
                   }`}>
                     {index < currentStepIndex ? <Check size={20} /> : step.number}
                   </div>
                   <span className={`text-[10px] uppercase font-black tracking-widest transition-colors ${
                     index <= currentStepIndex ? 'text-white' : 'text-slate-500'
                   }`}>{step.label}</span>
                 </div>
                 {index < steps.length - 1 && (
                   <div className={`flex-1 h-[2px] mx-4 transition-colors duration-1000 ${
                     index < currentStepIndex ? 'bg-emerald-500' : 'bg-white/10'
                   }`} />
                 )}
               </React.Fragment>
             ))}
           </div>

           <div className="installation-step-content min-h-[400px]">
              {wizardState.currentStep === 'download' && (
                <div className="animate-in fade-in slide-in-from-bottom-4">
                  <DownloadStep
                    downloadUrl={INSTALLATION_CONFIG.downloadUrl}
                    expectedFileName={INSTALLATION_CONFIG.expectedFileName}
                    expectedFileSize="2.5 GB"
                    onDownloadClick={handleDownloadClick}
                  />
                </div>
              )}

              {wizardState.currentStep === 'placement' && (
                <div className="animate-in fade-in slide-in-from-bottom-4">
                  <PlacementStep
                    downloadZonePath={downloadZonePath}
                    fileDetected={fileDetected}
                    fileValid={fileValid}
                    validationError={validationResult?.errors[0] || null}
                    onOpenFolder={handleOpenFolder}
                    onRefresh={refreshFileDetection}
                  />
                </div>
              )}

              {wizardState.currentStep === 'installation' && (
                <div className="animate-in fade-in zoom-in-95">
                  <InstallationStep
                    canInstall={fileDetected && fileValid}
                    isInstalling={wizardState.installationProgress > 0 && wizardState.installationProgress < 100}
                    progress={wizardState.installationProgress}
                    statusMessage={wizardState.installationStatus}
                    error={wizardState.installationError}
                    onInstall={handleInstall}
                    onRetry={handleRetry}
                  />
                </div>
              )}

              {wizardState.currentStep === 'completion' && (
                <div className="animate-in scale-in duration-500">
                  <CompletionStep
                    success={wizardState.installationProgress === 100 && !wizardState.installationError}
                    comfyUIUrl={wizardState.comfyUIUrl}
                    installedModels={wizardState.installedModels}
                    installedWorkflows={wizardState.installedWorkflows}
                    onOpenComfyUI={handleOpenComfyUI}
                    onClose={handleClose}
                  />
                </div>
              )}
           </div>
        </div>

        <div className="p-8 border-t border-white/5 bg-black/60 flex justify-between items-center">
           <div className="flex items-center gap-4 text-slate-500">
              <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest bg-white/5 px-3 py-1.5 rounded-lg">
                <ShieldCheck size={12} className="text-emerald-400" /> Integrity Secured
              </div>
              <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest bg-white/5 px-3 py-1.5 rounded-lg">
                <Cpu size={12} className="text-blue-400" /> x64 Optimized
              </div>
           </div>
           
           <button 
             onClick={handleClose}
             disabled={wizardState.installationProgress > 0 && wizardState.installationProgress < 100}
             className="px-8 py-3 bg-white/5 hover:bg-white/10 border border-white/10 rounded-xl text-[10px] font-black uppercase tracking-widest text-slate-400 hover:text-white transition-all disabled:opacity-50 disabled:cursor-not-allowed"
           >
             {wizardState.installationProgress > 0 && wizardState.installationProgress < 100 ? "Crucial Task in Progress" : "Quit Wizard"}
           </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import {
  FolderOpen,
  Folder,
  File,
  ChevronRight,
  ChevronDown,
  Home,
  Search,
  Loader2,
  CheckCircle,
  AlertCircle,
  X
} from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Alert } from '@/components/ui/alert';

// ============================================================================
// Types
// ============================================================================

interface DirectoryItem {
  name: string;
  path: string;
  isDirectory: boolean;
  size: number;
  modified: string;
}

interface FolderNavigationModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSelectProject: (projectPath: string) => Promise<void>;
  initialPath?: string;
}

interface TreeNode {
  item: DirectoryItem;
  children?: TreeNode[];
  expanded?: boolean;
  loading?: boolean;
}

// ============================================================================
// Folder Navigation Modal Component
// ============================================================================

/**
 * Folder Navigation Modal Component
 * 
 * **DEMO MODE ONLY**: This component provides a custom folder navigation
 * interface for web browser environments where native OS dialogs are unavailable.
 * 
 * **DO NOT USE IN ELECTRON MODE**: When running as a desktop application,
 * the native OS file dialog (Windows File Explorer, macOS Finder, etc.) 
 * should ALWAYS be used via window.electronAPI.project.selectForOpen().
 * 
 * The native dialog provides:
 * - Familiar user experience with OS-native controls
 * - Better performance and responsiveness
 * - Access to all file system features (network drives, shortcuts, etc.)
 * - Proper keyboard navigation and accessibility
 * - Integration with OS-level file management features
 * 
 * This custom modal should only be rendered when window.electronAPI is undefined.
 * It has been incorrectly reintroduced 3 times in place of the native dialog,
 * causing poor user experience. The conditional rendering in LandingPageWithHooks.tsx
 * ensures this component is excluded from the React component tree in Electron mode.
 * 
 * @see LandingPageWithHooks.tsx for conditional rendering implementation
 * @see useLandingPage.ts for native dialog usage in Electron mode
 * 
 * @param {FolderNavigationModalProps} props - Component props
 * @param {boolean} props.open - Whether the modal is open
 * @param {function} props.onOpenChange - Callback when modal open state changes
 * @param {function} props.onSelectProject - Callback when a project is selected
 * @param {string} [props.initialPath] - Optional initial directory path
 */
export function FolderNavigationModal({
  open,
  onOpenChange,
  onSelectProject,
  initialPath,
}: FolderNavigationModalProps) {
  const [currentPath, setCurrentPath] = useState(initialPath || '');
  const [searchQuery, setSearchQuery] = useState('');
  const [treeData, setTreeData] = useState<TreeNode[]>([]);
  const [selectedPath, setSelectedPath] = useState<string | null>(null);
  const [isValidating, setIsValidating] = useState(false);
  const [validationResult, setValidationResult] = useState<any>(null);
  const [isOpening, setIsOpening] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Initialize with default path
  useEffect(() => {
    if (open && !currentPath) {
      const defaultPath = initialPath || 'C:/Users/Documents'; // Default to Documents folder
      setCurrentPath(defaultPath);
      if (defaultPath) {
        loadDirectory(defaultPath);
      }
    }
  }, [open, initialPath]);

  // Load directory contents
  const loadDirectory = useCallback(async (path: string, node?: TreeNode) => {
    if (node) {
      node.loading = true;
      setTreeData(prev => [...prev]); // Trigger re-render
    }

    try {
      let contents: DirectoryItem[] = [];

      if (window.electronAPI) {
        contents = await (window.electronAPI.project as any).listDirectory(path);
      } else {
        // Demo mode - simulate directory listing
        contents = [
          { name: 'Documents', path: 'C:/Users/Documents', isDirectory: true, size: 0, modified: new Date().toISOString() },
          { name: 'Downloads', path: 'C:/Users/Downloads', isDirectory: true, size: 0, modified: new Date().toISOString() },
          { name: 'Desktop', path: 'C:/Users/Desktop', isDirectory: true, size: 0, modified: new Date().toISOString() },
        ];
      }

      const children = contents
        .filter(item => item.isDirectory)
        .map(item => ({ item, expanded: false, loading: false }));

      if (node) {
        node.children = children;
        node.loading = false;
      } else {
        setTreeData(children);
      }
      setTreeData(prev => [...prev]); // Trigger re-render
    } catch (err) {
      console.error('Failed to load directory:', err);
      setError('Failed to load directory contents');
      if (node) {
        node.loading = false;
        setTreeData(prev => [...prev]);
      }
    }
  }, []);

  // Toggle directory expansion
  const toggleDirectory = async (node: TreeNode) => {
    if (node.expanded) {
      node.expanded = false;
      setTreeData(prev => [...prev]);
    } else {
      node.expanded = true;
      if (!node.children) {
        await loadDirectory(node.item.path, node);
      } else {
        setTreeData(prev => [...prev]);
      }
    }
  };

  // Handle path selection
  const handleSelectPath = async (path: string) => {
    setSelectedPath(path);
    setError(null);

    // Validate project
    await validateProject(path);
  };

  // Validate project
  const validateProject = async (path: string) => {
    setIsValidating(true);
    setValidationResult(null);

    try {
      if (window.electronAPI) {
        const result = await window.electronAPI.project.validate(path);
        setValidationResult(result);
      } else {
        // Demo validation
        await new Promise(resolve => setTimeout(resolve, 500));
        setValidationResult({
          isValid: true,
          errors: [],
          warnings: [{ type: 'info', message: 'Demo mode: validation skipped' }],
        });
      }
    } catch (err) {
      console.error('Validation failed:', err);
      setValidationResult({
        isValid: false,
        errors: [{ type: 'error', message: err instanceof Error ? err.message : 'Validation failed' }],
        warnings: [],
      });
    } finally {
      setIsValidating(false);
    }
  };

  // Handle open project
  const handleOpenProject = async () => {
    if (!selectedPath || !validationResult?.isValid) return;

    setIsOpening(true);
    setError(null);

    try {
      await onSelectProject(selectedPath);
      onOpenChange(false);
      // Reset state
      setSelectedPath(null);
      setValidationResult(null);
      setSearchQuery('');
    } catch (err) {
      console.error('Failed to open project:', err);
      setError(err instanceof Error ? err.message : 'Failed to open project');
    } finally {
      setIsOpening(false);
    }
  };

  // Render tree node
  const renderTreeNode = (node: TreeNode, level = 0) => (
    <div key={node.item.path}>
      <div
        className={`flex items-center gap-2 px-2 py-1 hover:bg-gray-700 cursor-pointer rounded ${
          selectedPath === node.item.path ? 'bg-blue-600/20 border border-blue-500' : ''
        }`}
        style={{ paddingLeft: `${level * 20 + 8}px` }}
        onClick={() => handleSelectPath(node.item.path)}
      >
        {node.item.isDirectory ? (
          <>
            {node.expanded ? (
              <ChevronDown className="w-4 h-4 text-gray-400" />
            ) : (
              <ChevronRight className="w-4 h-4 text-gray-400" />
            )}
            <Folder className="w-4 h-4 text-blue-400" />
          </>
        ) : (
          <>
            <div className="w-4" /> {/* Spacer */}
            <File className="w-4 h-4 text-gray-400" />
          </>
        )}
        <span className="text-sm text-white truncate">{node.item.name}</span>
        {node.loading && <Loader2 className="w-4 h-4 animate-spin text-gray-400 ml-auto" />}
      </div>
      {node.expanded && node.children && (
        <div>
          {node.children.map(child => renderTreeNode(child, level + 1))}
        </div>
      )}
    </div>
  );

  // Filter tree data based on search
  const filteredTreeData = treeData.filter(node =>
    node.item.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[600px] max-h-[80vh] bg-gray-900 border-gray-700 text-white flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-xl">
            <div className="flex items-center justify-center w-10 h-10 rounded-lg bg-purple-500/20">
              <FolderOpen className="w-5 h-5 text-purple-400" />
            </div>
            Open Existing Project
          </DialogTitle>
          <DialogDescription className="text-gray-400">
            Navigate through your folders to find and open a StoryCore project.
          </DialogDescription>
        </DialogHeader>

        <div className="flex flex-col gap-4 flex-1 min-h-0">
          {/* Search */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
            <Input
              placeholder="Search folders..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-10 bg-gray-800 border-gray-700 text-white placeholder:text-gray-500"
            />
          </div>

          {/* Error Display */}
          {error && (
            <Alert variant="destructive" className="bg-red-900/20 border-red-800 text-red-400">
              <AlertCircle className="h-4 w-4" />
              <p>{error}</p>
            </Alert>
          )}

          {/* Directory Tree */}
          <div className="flex-1 min-h-0">
            <ScrollArea className="h-full">
              <div className="space-y-1">
                {filteredTreeData.length > 0 ? (
                  filteredTreeData.map(node => renderTreeNode(node))
                ) : (
                  <div className="text-center py-8 text-gray-400">
                    {searchQuery ? 'No folders match your search' : 'No folders to display'}
                  </div>
                )}
              </div>
            </ScrollArea>
          </div>

          {/* Selected Path Display */}
          {selectedPath && (
            <div className="p-3 rounded-lg bg-gray-800 border border-gray-700">
              <div className="flex items-center gap-2 mb-2">
                <Home className="w-4 h-4 text-gray-400" />
                <span className="text-sm font-medium text-gray-200">Selected:</span>
              </div>
              <p className="text-sm text-gray-300 font-mono break-all">{selectedPath}</p>
            </div>
          )}

          {/* Validation Results */}
          {isValidating && (
            <div className="flex items-center justify-center py-4">
              <div className="flex items-center gap-2 text-gray-400">
                <Loader2 className="w-4 h-4 animate-spin" />
                <span className="text-sm">Validating project...</span>
              </div>
            </div>
          )}

          {validationResult && !isValidating && (
            <div className="space-y-2">
              {validationResult.isValid ? (
                <div className="rounded-lg bg-green-900/20 border border-green-800 p-3">
                  <div className="flex items-center gap-2">
                    <CheckCircle className="w-4 h-4 text-green-400" />
                    <span className="text-sm text-green-300">Valid StoryCore project</span>
                  </div>
                </div>
              ) : (
                <div className="rounded-lg bg-red-900/20 border border-red-800 p-3">
                  <div className="flex items-start gap-2">
                    <AlertCircle className="w-4 h-4 text-red-400 flex-shrink-0 mt-0.5" />
                    <div className="flex-1">
                      <span className="text-sm font-medium text-red-400">Invalid project</span>
                      <ul className="mt-1 space-y-1">
                        {validationResult.errors?.map((error: unknown, index: number) => (
                          <li key={index} className="text-xs text-red-300">ÔÇó {error.message}</li>
                        ))}
                      </ul>
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        <DialogFooter>
          <Button
            type="button"
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={isOpening || isValidating}
            className="bg-gray-800 border-gray-700 text-white hover:bg-gray-700"
          >
            <X className="w-4 h-4 mr-2" />
            Cancel
          </Button>
          <Button
            onClick={handleOpenProject}
            disabled={!selectedPath || !validationResult?.isValid || isOpening || isValidating}
            className="bg-purple-600 hover:bg-purple-700 text-white"
          >
            {isOpening ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Opening...
              </>
            ) : (
              <>
                <FolderOpen className="mr-2 h-4 w-4" />
                Open Project
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { memo } from 'react';
import { Check, Globe } from 'lucide-react';
import { Button } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { type LanguageCode } from '@/utils/llmConfigStorage';

// ============================================================================
// Types
// ============================================================================

export type { LanguageCode };

export interface LanguageOption {
  code: LanguageCode;
  name: string;
  nativeName: string;
  flag: string;
}

export interface LanguageSelectorProps {
  currentLanguage: LanguageCode;
  onLanguageChange: (language: LanguageCode) => void;
  position?: 'top' | 'bottom';
}

// ============================================================================
// Constants
// ============================================================================

