/**
 * LocationCard Component
 * 
 * Displays a location summary card with thumbnail, name, type, and cube progress.
 * Supports selection mode for Story Generator and action buttons for editing and deletion.
 * 
 * File: creative-studio-ui/src/components/location/LocationCard.tsx
 */

import React, { useState } from 'react';
import { Edit2, Trash2, MapPin, Image as ImageIcon, Loader2, Box } from 'lucide-react';
import type { Location } from '@/types/location';
import { getLocationCompletionPercentage } from '@/stores/locationStore';
import './LocationCard.css';

// ============================================================================
// Types
// ============================================================================

/**
 * Props for the LocationCard component
 */
export interface LocationCardProps {
  /** The location to display */
  location: Location;
  
  /** Optional click handler for the card */
  onClick?: () => void;
  
  /** Whether the card is in selection mode */
  selectable?: boolean;
  
  /** Whether the card is currently selected */
  selected?: boolean;
  
  /** Handler for selection changes */
  onSelect?: (selected: boolean) => void;
  
  /** Whether to show action buttons (edit, delete) */
  showActions?: boolean;
  
  /** Handler for edit button click */
  onEdit?: () => void;
  
  /** Handler for delete button click */
  onDelete?: () => void;
  
  /** Whether the card is in loading state */
  loading?: boolean;
}

// ============================================================================
// Component
// ============================================================================

export function LocationCard({
  location,
  onClick,
  selectable = false,
  selected = false,
  onSelect,
  showActions = false,
  onEdit,
  onDelete,
  loading = false,
}: LocationCardProps) {
  const [imageError, setImageError] = useState(false);
  
  const completionPercentage = getLocationCompletionPercentage(location);
  const hasThumbnail = location.metadata?.thumbnail_path && !imageError;
  
  // Get thumbnail from front face if no dedicated thumbnail
  const displayThumbnail = hasThumbnail 
    ? location.metadata.thumbnail_path 
    : location.cube_textures?.front?.image_path;
  
  const handleCardClick = () => {
    if (selectable && onSelect) {
      onSelect(!selected);
    } else if (onClick) {
      onClick();
    }
  };
  
  const handleEditClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (onEdit) onEdit();
  };
  
  const handleDeleteClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (onDelete) onDelete();
  };
  
  const handleSelectChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    e.stopPropagation();
    if (onSelect) onSelect(e.target.checked);
  };
  
  return (
    <div 
      className={`location-card ${selectable ? 'selectable' : ''} ${selected ? 'selected' : ''} ${loading ? 'loading' : ''}`}
      onClick={handleCardClick}
    >
      {loading && (
        <div className="location-card__loading-overlay">
          <Loader2 className="location-card__spinner" />
        </div>
      )}
      
      {selectable && (
        <div className="location-card__checkbox">
          <input
            type="checkbox"
            checked={selected}
            onChange={handleSelectChange}
            onClick={(e) => e.stopPropagation()}
            title="Select location"
          />
        </div>
      )}
      
      <div className="location-card__thumbnail">
        {displayThumbnail ? (
          <img 
            src={displayThumbnail} 
            alt={location.name}
            onError={() => setImageError(true)}
          />
        ) : (
          <div className="location-card__thumbnail-placeholder">
            <MapPin size={48} />
          </div>
        )}
        
        {/* Cube Progress Indicator */}
        <div className="location-card__cube-progress">
          <Box size={14} />
          <span>{completionPercentage}%</span>
        </div>
      </div>
      
      <div className="location-card__content">
        <div className="location-card__header">
          <h3 className="location-card__name">{location.name}</h3>
          <span className={`location-card__type location-card__type--${location.location_type}`}>
            {location.location_type === 'exterior' ? 'Exterior' : 'Interior'}
          </span>
        </div>
        
        <p className="location-card__description">
          {location.metadata?.description?.slice(0, 100)}
          {location.metadata?.description?.length > 100 && '...'}
        </p>
        
        {location.metadata?.genre_tags && location.metadata.genre_tags.length > 0 && (
          <div className="location-card__tags">
            {location.metadata.genre_tags.slice(0, 3).map((tag) => (
              <span key={tag} className="location-card__tag">
                {tag}
              </span>
            ))}
            {location.metadata.genre_tags.length > 3 && (
              <span className="location-card__tag location-card__tag--more">
                +{location.metadata.genre_tags.length - 3}
              </span>
            )}
          </div>
        )}
        
        <div className="location-card__meta">
          <span className="location-card__created">
            Created: {new Date(location.creation_timestamp).toLocaleDateString()}
          </span>
          {location.is_world_derived && (
            <span className="location-card__derived">
              From World Building
            </span>
          )}
        </div>
      </div>
      
      {showActions && !loading && (
        <div className="location-card__actions">
          <button 
            className="location-card__action location-card__action--edit"
            onClick={handleEditClick}
            title="Edit location"
          >
            <Edit2 size={16} />
          </button>
          <button 
            className="location-card__action location-card__action--delete"
            onClick={handleDeleteClick}
            title="Delete location"
          >
            <Trash2 size={16} />
          </button>
        </div>
      )}
    </div>
  );
}

export default LocationCard;

/**
 * LocationList Component
 * 
 * Grid layout for displaying location cards with filter and create functionality.
 * 
 * File: creative-studio-ui/src/components/location/LocationList.tsx
 * 
 * Updated: Added pagination support for large location lists
 */

import React, { useMemo } from 'react';
import { Plus, Grid, List, Filter, Search } from 'lucide-react';
import { LocationCard } from './LocationCard';
import type { Location, LocationType } from '@/types/location';
import { useLocationStore, getFilteredLocations } from '@/stores/locationStore';
import { usePagination } from '@/hooks/usePagination';
import { Pagination } from '@/components/ui/pagination';
import './LocationList.css';

// ============================================================================
// Types
// ============================================================================

/**
 * Props for the LocationList component
 */
export interface LocationListProps {
  /** Handler for create location button click */
  onCreateLocation: () => void;
  
  /** Handler for location card click */
  onLocationClick: (location: Location) => void;
  
  /** Handler for location edit */
  onEditLocation: (location: Location) => void;
  
  /** Handler for location delete */
  onDeleteLocation: (location: Location) => void;
  
  /** Whether to show filter controls */
  showFilters?: boolean;
  
  /** Whether to show create button */
  showCreateButton?: boolean;
  
  /** Whether to show action buttons on cards */
  showActions?: boolean;
  
  /** Whether to show selection controls */
  selectable?: boolean;
  
  /** Selected location IDs (for selection mode) */
  selectedIds?: string[];
  
  /** Handler for selection changes */
  onSelectionChange?: (ids: string[]) => void;
}

// ============================================================================
// Component
// ============================================================================

export function LocationList({
  onCreateLocation,
  onLocationClick,
  onEditLocation,
  onDeleteLocation,
  showFilters = true,
  showCreateButton = true,
  showActions = true,
  selectable = false,
  selectedIds = [],
  onSelectionChange,
}: LocationListProps) {
  const {
    locations,
    filterType,
    filterWorld,
    searchQuery,
    selectLocation,
    setFilterType,
    setFilterWorld,
    setSearchQuery,
    isLoading,
  } = useLocationStore();
  
  const filteredLocations = useMemo(
    () => getFilteredLocations(useLocationStore.getState()),
    [locations, filterType, filterWorld, searchQuery]
  );
  
  /**
   * Pagination for locations
   */
  const {
    paginatedItems,
    pagination,
    goToPage,
    setPageSize,
  } = usePagination({
    items: filteredLocations,
    pageSize: 12,
    resetOnItemsChange: true,
  });
  
  const handleLocationClick = (location: Location) => {
    selectLocation(location.location_id);
    onLocationClick(location);
  };
  
  const handleSelectionChange = (location: Location, selected: boolean) => {
    if (onSelectionChange) {
      if (selected) {
        onSelectionChange([...selectedIds, location.location_id]);
      } else {
        onSelectionChange(selectedIds.filter((id) => id !== location.location_id));
      }
    }
  };
  
  const uniqueWorlds = useMemo(() => {
    const worlds = new Set<string>();
    locations.forEach((loc) => {
      if (loc.world_id) worlds.add(loc.world_id);
    });
    return Array.from(worlds);
  }, [locations]);
  
  return (
    <div className="location-list">
      {/* Header */}
      <div className="location-list__header">
        <h2 className="location-list__title">Locations</h2>
        {showCreateButton && (
          <button className="location-list__create-btn" onClick={onCreateLocation}>
            <Plus size={18} />
            Create Location
          </button>
        )}
      </div>
      
      {/* Filters */}
      {showFilters && (
        <div className="location-list__filters">
          {/* Search */}
          <div className="location-list__search">
            <Search size={16} className="location-list__search-icon" />
            <input
              type="text"
              placeholder="Search locations..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="location-list__search-input"
            />
          </div>
          
          {/* Type Filter */}
          <div className="location-list__filter">
            <Filter size={16} />
            <select
              value={filterType}
              onChange={(e) => setFilterType(e.target.value as LocationType | 'all')}
              className="location-list__select"
              aria-label="Filter by location type"
            >
              <option value="all">All Types</option>
              <option value="exterior">Exterior</option>
              <option value="interior">Interior</option>
            </select>
          </div>
          
          {/* World Filter */}
          {uniqueWorlds.length > 0 && (
            <div className="location-list__filter">
              <select
                value={filterWorld}
                onChange={(e) => setFilterWorld(e.target.value)}
                className="location-list__select"
                aria-label="Filter by world"
              >
                <option value="all">All Worlds</option>
                {uniqueWorlds.map((worldId) => (
                  <option key={worldId} value={worldId}>
                    {worldId}
                  </option>
                ))}
              </select>
            </div>
          )}
          
          {/* Results Count */}
          <div className="location-list__count">
            {filteredLocations.length} location{filteredLocations.length !== 1 ? 's' : ''}
          </div>
        </div>
      )}
      
      {/* Grid */}
      {isLoading ? (
        <div className="location-list__loading">
          <div className="location-list__spinner" />
          <p>Loading locations...</p>
        </div>
      ) : filteredLocations.length === 0 ? (
        <div className="location-list__empty">
          <div className="location-list__empty-icon">­ƒôì</div>
          <h3>No locations found</h3>
          <p>
            {searchQuery || filterType !== 'all' || filterWorld !== 'all'
              ? 'Try adjusting your filters'
              : 'Create your first location to get started'}
          </p>
          {showCreateButton && (
            <button className="location-list__create-btn" onClick={onCreateLocation}>
              <Plus size={18} />
              Create Location
            </button>
          )}
        </div>
      ) : (
        <>
          <div className="location-list__grid">
            {paginatedItems.map((location) => (
              <LocationCard
                key={location.location_id}
                location={location}
                onClick={() => handleLocationClick(location)}
                selectable={selectable}
                selected={selectedIds.includes(location.location_id)}
                onSelect={(selected) => handleSelectionChange(location, selected)}
                showActions={showActions}
                onEdit={() => onEditLocation(location)}
                onDelete={() => onDeleteLocation(location)}
              />
            ))}
          </div>
          
          {/* Pagination Controls */}
          <Pagination
            pagination={pagination}
            onPageChange={goToPage}
            onPageSizeChange={setPageSize}
            showPageSizeSelector
            className="location-list__pagination"
          />
        </>
       )}
    </div>
  );
}

