    { id: 'rain', label: 'Rain' },
    { id: 'storm', label: 'Storm' },
    { id: 'fog', label: 'Fog' },
    { id: 'snow', label: 'Snow' },
  ];
  
  const handleConfigUpdate = useCallback((updates: Partial<SkyBoxConfig>) => {
    const newConfig = { ...localConfig, ...updates };
