              <option key={weather.id} value={weather.id}>
                {weather.label}
              </option>
            ))}
          </select>
        </div>
      </div>
      
      {/* Sky Colors */}
      <div className="skybox-panel__section">
        <h4 className="skybox-panel__section-title">
          <Sparkles size={16} />
          Sky Colors
        </h4>
        
        <div className="skybox-panel__colors">
          <div className="skybox-panel__color-input">
            <label>Top</label>
            <input
              type="color"
