/**
 * Menu Component
 * 
 * A menu trigger button with an associated dropdown menu.
 * Handles:
 * - Menu open/close state
 * - Click and hover interactions
 * - Keyboard activation (Enter, Space, Arrow keys)
 * - Focus management
 * - ARIA attributes for accessibility
 * 
 * @module components/menuBar/Menu
 */

import React, { useState, useRef, useEffect } from 'react';
import { MenuDropdown } from './MenuDropdown';
import { MenuItemProps } from './MenuItem';
import { useScreenReaderAnnouncer } from './ScreenReaderAnnouncer';

export interface MenuProps {
  /** Unique identifier for the menu */
  id: string;
  
  /** Display label for the menu trigger button */
  label: string;
  
  /** Array of menu items */
  items: Omit<MenuItemProps, 'focused' | 'tabIndex' | 'onFocus' | 'onMouseEnter'>[];
  
  /** Whether the menu is disabled */
  disabled?: boolean;
  
  /** Whether the menu is open (controlled by parent for mutual exclusivity) */
  isOpen?: boolean;
  
  /** Callback when menu opens */
  onOpen?: () => void;
  
  /** Callback when menu closes */
  onClose?: () => void;
  
  /** Callback when an item is clicked */
  onItemClick?: (itemId: string) => void;
  
  /** Callback to register the trigger button ref for keyboard focus management */
  onRegisterTriggerRef?: (ref: HTMLButtonElement | null) => void;
  
  /** Additional CSS classes for the trigger button */
  className?: string;
  
  /** Position of the dropdown */
  position?: 'left' | 'right';
}

/**
 * Menu Component
 * 
 * Renders a menu trigger button with an associated dropdown menu.
 * 
 * @example
 * ```tsx
 * <Menu
 *   id="file-menu"
 *   label="File"
 *   items={[
 *     { id: 'new', label: 'New Project', shortcut: 'Ctrl+N', onClick: handleNew },
 *     { id: 'open', label: 'Open Project', shortcut: 'Ctrl+O', onClick: handleOpen },
 *     { id: 'save', label: 'Save', shortcut: 'Ctrl+S', onClick: handleSave }
 *   ]}
 * />
 * ```
 */
export const Menu: React.FC<MenuProps> = ({
  id,
  label,
  items,
  disabled = false,
  isOpen: controlledIsOpen,
  onOpen,
  onClose,
  onItemClick,
  onRegisterTriggerRef,
  className = '',
  position = 'left',
}) => {
  // Menu open state - use controlled mode if isOpen prop provided, otherwise use internal state
  const [internalIsOpen, setInternalIsOpen] = useState(false);
  const isOpen = controlledIsOpen !== undefined ? controlledIsOpen : internalIsOpen;
  const setIsOpen = controlledIsOpen !== undefined 
    ? (open: boolean) => { if (open && onOpen) onOpen(); if (!open && onClose) onClose(); }
    : setInternalIsOpen;
  
  const triggerRef = useRef<HTMLButtonElement>(null);
  const menuContainerRef = useRef<HTMLDivElement>(null);
  
  // Get screen reader announcer (optional - only if provider is available)
  let announcer: ReturnType<typeof useScreenReaderAnnouncer> | null = null;
  try {
    announcer = useScreenReaderAnnouncer();
  } catch {
    // Provider not available, announcements will be skipped
  }

  /**
   * Register trigger ref with parent MenuBar for Alt key focus management
   * Requirements: 10.1
   */
  useEffect(() => {
    if (onRegisterTriggerRef && triggerRef.current) {
      onRegisterTriggerRef(triggerRef.current);
    }
    
    return () => {
      if (onRegisterTriggerRef) {
        onRegisterTriggerRef(null);
      }
    };
  }, [onRegisterTriggerRef]);

  /**
   * Open the menu
   */
  const openMenu = () => {
    if (disabled) return;
    setIsOpen(true);
    if (onOpen) {
      onOpen();
    }
    
    // Announce menu opened to screen readers
    // Requirements: 10.3
    if (announcer) {
      announcer.announce(`${label} menu opened`, 'polite', 100);
    }
  };

  /**
   * Close the menu
   */
  const closeMenu = () => {
    setIsOpen(false);
    if (onClose) {
      onClose();
    }
    // Return focus to trigger button
    triggerRef.current?.focus();
    
    // Announce menu closed to screen readers
    // Requirements: 10.3
    if (announcer) {
      announcer.announce(`${label} menu closed`, 'polite');
    }
  };

  /**
   * Toggle menu open/close
   */
  const toggleMenu = () => {
    if (isOpen) {
      closeMenu();
    } else {
      openMenu();
    }
  };

  /**
   * Handle trigger button click
   */
  const handleClick = () => {
    toggleMenu();
  };

  /**
   * Handle trigger button keyboard events
   */
  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (disabled) return;

    switch (event.key) {
      case 'Enter':
      case ' ':
        event.preventDefault();
        toggleMenu();
        break;

      case 'ArrowDown':
        event.preventDefault();
        openMenu();
        break;

      case 'ArrowUp':
        event.preventDefault();
        openMenu();
        break;

      case 'Escape':
        if (isOpen) {
          event.preventDefault();
          closeMenu();
        }
        break;
    }
  };

  /**
   * Handle item click from dropdown
   */
  const handleItemClick = (itemId: string) => {
    if (onItemClick) {
      onItemClick(itemId);
    }
    closeMenu();
  };

  /**
   * Close menu when clicking outside
   */
  useEffect(() => {
    if (!isOpen) return;

    // Use ref to track whether menu should be open (prevents race conditions)
    const menuContainer = menuContainerRef.current;
    let isMenuOpen = true;

    const handleClickOutside = (event: MouseEvent) => {
      if (!isMenuOpen || !menuContainer) return;
      
      if (!menuContainer.contains(event.target as Node)) {
        // Use setTimeout to allow event propagation before closing
        setTimeout(() => {
          if (isMenuOpen && menuContainerRef.current) {
            closeMenu();
          }
        }, 0);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);

    // Cleanup function
    return () => {
      isMenuOpen = false;
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isOpen, closeMenu]);

  return (
    <div ref={menuContainerRef} className="relative" role="none">
      {/* Menu Trigger Button */}
      <button
        ref={triggerRef}
        id={`${id}-trigger`}
        type="button"
        aria-haspopup="menu"
        aria-expanded={isOpen}
        aria-controls={`${id}-menu`}
        aria-label={label}
        disabled={disabled}
        onClick={handleClick}
        onKeyDown={handleKeyDown}
        className={`
          px-3 py-1.5 text-sm font-medium
          rounded-md
          transition-all duration-150 ease-in-out
          focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2
          ${
            disabled
              ? 'text-gray-500 dark:text-gray-400 cursor-not-allowed'
              : isOpen
              ? 'bg-accent text-accent-foreground'
              : 'text-foreground hover:bg-accent hover:text-accent-foreground'
          }
          ${className}
        `}
      >
        {label}
      </button>

      {/* Menu Dropdown */}
      <MenuDropdown
        items={items}
        isOpen={isOpen}
        onClose={closeMenu}
        onItemClick={handleItemClick}
        ariaLabel={`${label} menu`}
        position={position}
      />
    </div>
  );
};

export default Menu;

/**
 * MenuDropdown Component
 * 
 * A dropdown menu that displays menu items with full keyboard navigation support.
 * Implements the WAI-ARIA menu pattern with:
 * - Arrow key navigation (up/down)
 * - Enter key activation
 * - Escape key to close
 * - Home/End key navigation
 * - Roving tabindex for focus management
 * - Submenu support
 * 
 * @module components/menuBar/MenuDropdown
 */

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { MenuItem, MenuItemProps } from './MenuItem';
import { useScreenReaderAnnouncer } from './ScreenReaderAnnouncer';
import {
  getNextEnabledItemIndex,
  getFirstEnabledItemIndex,
  getLastEnabledItemIndex,
  findMenuItemByFirstLetter,
} from '../../utils/menuNavigation';

export interface MenuDropdownProps {
  /** Array of menu items to display */
  items: (Omit<MenuItemProps, 'focused' | 'tabIndex' | 'onFocus' | 'onMouseEnter'> | { id: string; separator: true })[];

  /** Whether the dropdown is open */
  isOpen: boolean;

  /** Callback when the dropdown should close */
  onClose: () => void;

  /** Callback when an item is clicked */
  onItemClick?: (itemId: string) => void;

  /** ARIA label for the menu */
  ariaLabel?: string;

  /** Additional CSS classes */
  className?: string;

  /** Position of the dropdown relative to trigger */
  position?: 'left' | 'right';
}

/**
 * MenuDropdown Component
 * 
 * Renders a dropdown menu with keyboard navigation and accessibility support.
 * 
 * @example
 * ```tsx
 * <MenuDropdown
 *   items={[
 *     { id: 'new', label: 'New Project', shortcut: 'Ctrl+N', onClick: handleNew },
 *     { id: 'open', label: 'Open Project', shortcut: 'Ctrl+O', onClick: handleOpen },
 *     { id: 'save', label: 'Save', shortcut: 'Ctrl+S', enabled: hasProject, onClick: handleSave }
 *   ]}
 *   isOpen={isOpen}
 *   onClose={handleClose}
 *   ariaLabel="File menu"
 * />
 * ```
 */
export const MenuDropdown: React.FC<MenuDropdownProps> = ({
  items,
  isOpen,
  onClose,
  onItemClick,
  ariaLabel,
  className = '',
  position = 'left',
}) => {
  const [focusedIndex, setFocusedIndex] = useState(0);
  const menuRef = useRef<HTMLDivElement>(null);
  const itemRefs = useRef<(HTMLButtonElement | null)[]>([]);

  // Get screen reader announcer (optional - only if provider is available)
  let announcer: ReturnType<typeof useScreenReaderAnnouncer> | null = null;
  try {
    announcer = useScreenReaderAnnouncer();
  } catch {
    // Provider not available, announcements will be skipped
  }

  /**
   * Handle keyboard navigation
   */
  const handleKeyDown = useCallback(
    (event: KeyboardEvent) => {
      if (!isOpen) return;

      switch (event.key) {
        case 'ArrowDown':
          event.preventDefault();
          setFocusedIndex((prev) => getNextEnabledItemIndex(items, prev, 'next'));
          break;

        case 'ArrowUp':
          event.preventDefault();
          setFocusedIndex((prev) => getNextEnabledItemIndex(items, prev, 'previous'));
          break;

        case 'Home':
          event.preventDefault();
          setFocusedIndex(getFirstEnabledItemIndex(items));
          break;

        case 'End':
          event.preventDefault();
          setFocusedIndex(getLastEnabledItemIndex(items));
          break;

        case 'Escape':
          event.preventDefault();
          onClose();
          break;

        case 'Tab':
          // Close menu on Tab to allow normal tab navigation
          event.preventDefault();
          onClose();
          break;

        default:
          // Support letter key navigation
          if (event.key.length === 1 && !event.ctrlKey && !event.metaKey && !event.altKey) {
            event.preventDefault();
            const letter = event.key.toLowerCase();
            const nextIndex = findMenuItemByFirstLetter(items, letter, focusedIndex + 1);

            if (nextIndex !== -1) {
              setFocusedIndex(nextIndex);
            }
          }
          break;
      }
    },
    [isOpen, onClose, items, focusedIndex]
  );

  /**
   * Focus the current item when focusedIndex changes
   */
  useEffect(() => {
    if (isOpen && itemRefs.current[focusedIndex]) {
      itemRefs.current[focusedIndex]?.focus();

      // Announce focused item to screen readers
      // Requirements: 10.3
      const focusedItem = items[focusedIndex];
      if (focusedItem && announcer && !('separator' in focusedItem)) {
        const item = focusedItem as Omit<MenuItemProps, 'focused' | 'tabIndex' | 'onFocus' | 'onMouseEnter'>;
        const enabledState = item.enabled === false ? 'disabled' : 'enabled';
        const checkedState = item.checked !== undefined
          ? item.checked ? 'checked' : 'not checked'
          : '';
        const shortcutText = item.shortcut ? `, keyboard shortcut ${item.shortcut}` : '';

        announcer.announce(
          `${item.label}${checkedState ? `, ${checkedState}` : ''}${shortcutText}, ${enabledState}`,
          'polite'
        );
      }
    }
  }, [focusedIndex, isOpen, items, announcer]);

  /**
   * Set up keyboard event listeners
   */
  useEffect(() => {
    if (isOpen) {
      document.addEventListener('keydown', handleKeyDown);
      return () => {
        document.removeEventListener('keydown', handleKeyDown);
      };
    }
  }, [isOpen, handleKeyDown]);

  /**
   * Focus first enabled item when menu opens
   */
  useEffect(() => {
    if (isOpen) {
      const firstEnabled = getFirstEnabledItemIndex(items);
      setFocusedIndex(firstEnabled);
    }
  }, [isOpen, items]);

  /**
   * Handle click outside to close menu
   */
  useEffect(() => {
    if (!isOpen) return;

    // Use ref to track whether menu should be open (prevents race conditions)
    const menuContainer = menuRef.current;
    let isMenuOpen = true;

    const handleClickOutside = (event: MouseEvent) => {
      if (!isMenuOpen || !menuContainer) return;

      if (!menuContainer.contains(event.target as Node)) {
        // Use setTimeout to allow event propagation before closing
        setTimeout(() => {
          if (isMenuOpen && menuRef.current) {
            onClose();
          }
        }, 0);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);

    // Cleanup function
    return () => {
      isMenuOpen = false;
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isOpen, onClose]);

  /**
   * Handle item click
   */
  const handleItemClick = (item: typeof items[0], index: number) => {
    // Skip if it's a separator
    if ('separator' in item) return;

    const menuItem = item as Omit<MenuItemProps, 'focused' | 'tabIndex' | 'onFocus' | 'onMouseEnter'>;

    if (menuItem.enabled === false) return;

    // Prefer the dropdown's onItemClick handler if provided (unified handling)
    if (onItemClick) {
      onItemClick(menuItem.id);
    } else if (menuItem.onClick) {
      // Fallback to individual click handler
      menuItem.onClick();
    }

    // Close the menu after clicking (unless it has a submenu)
    if (!menuItem.hasSubmenu) {
      onClose();
    }
  };

  /**
   * Handle mouse enter on item
   */
  const handleItemMouseEnter = (index: number) => {
    setFocusedIndex(index);
  };

  if (!isOpen) return null;

  return (
    <div
      ref={menuRef}
      role="menu"
      aria-label={ariaLabel}
      aria-orientation="vertical"
      className={`
        absolute mt-1 min-w-max
        bg-popover text-popover-foreground
        border border-border
        rounded-md shadow-lg
        py-1
        z-[200]
        transition-all duration-150 ease-in-out
        origin-top
        ${position === 'left' ? 'left-0' : 'right-0'}
        ${isOpen ? 'opacity-100 visible scale-100' : 'opacity-0 invisible scale-95'}
        ${className}
      `}
    >
      {items.length > 0 ? (
        items.map((item, index) => {
          // Handle separator items
          if ('separator' in item && item.separator) {
            return (
              <div
                key={item.id}
                className="my-1 px-2"
                role="separator"
                aria-orientation="horizontal"
              >
                <div className="h-px bg-border/50" />
              </div>
            );
          }

          // Handle regular menu items
          return (
            <MenuItem
              key={item.id}
              ref={(el) => {
                itemRefs.current[index] = el;
              }}
              {...(item as Omit<MenuItemProps, 'focused' | 'tabIndex' | 'onFocus' | 'onMouseEnter'>)}
              focused={focusedIndex === index}
              tabIndex={focusedIndex === index ? 0 : -1}
              onClick={() => handleItemClick(item as Omit<MenuItemProps, 'focused' | 'tabIndex' | 'onFocus' | 'onMouseEnter'>, index)}
              onFocus={() => setFocusedIndex(index)}
              onMouseEnter={() => handleItemMouseEnter(index)}
            />
          );
        })
      ) : (
        <div className="px-3 py-2 text-sm text-gray-500">
          Aucun ├®l├®ment disponible
        </div>
      )}
    </div>
  );
};

export default MenuDropdown;

/**
 * Screen Reader Announcer Component
 * 
 * Provides accessibility announcements for screen readers.
 * Uses ARIA live regions to announce menu navigation and state changes.
 */

import React, { createContext, useContext, useCallback } from 'react';

interface ScreenReaderAnnouncerContextType {
  announce: (message: string, priority?: 'polite' | 'assertive', delay?: number) => void;
}

const ScreenReaderAnnouncerContext = createContext<ScreenReaderAnnouncerContextType | null>(null);

export const ScreenReaderAnnouncerProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const announce = useCallback((message: string, priority: 'polite' | 'assertive' = 'polite', delay = 0) => {
    // Create a temporary live region for the announcement
    const liveRegion = document.createElement('div');
    liveRegion.setAttribute('role', 'status');
    liveRegion.setAttribute('aria-live', priority);
    liveRegion.setAttribute('aria-atomic', 'true');
    liveRegion.style.position = 'absolute';
    liveRegion.style.left = '-10000px';
    liveRegion.style.width = '1px';
    liveRegion.style.height = '1px';
    liveRegion.style.overflow = 'hidden';
    
    document.body.appendChild(liveRegion);
    
    // Announce after delay
    setTimeout(() => {
      liveRegion.textContent = message;
    }, delay);
    
    // Remove after announcement
    setTimeout(() => {
      document.body.removeChild(liveRegion);
    }, delay + 1000);
  }, []);

  return (
    <ScreenReaderAnnouncerContext.Provider value={{ announce }}>
      {children}
    </ScreenReaderAnnouncerContext.Provider>
  );
};

export const useScreenReaderAnnouncer = () => {
  const context = useContext(ScreenReaderAnnouncerContext);
  if (!context) {
    throw new Error('useScreenReaderAnnouncer must be used within ScreenReaderAnnouncerProvider');
  }
  return context;
};

/**
 * MenuBarErrorBoundary Tests
 * 
 * Tests for the MenuBarErrorBoundary component to ensure proper error handling,
 * user feedback, and logging functionality.
 * 
 * Requirements: 15.2 (Error Handling and User Feedback)
 */

import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { MenuBarErrorBoundary } from '../MenuBarErrorBoundary';
import { notificationService } from '../../../services/menuBar/NotificationService';

// Component that throws an error for testing
const ThrowError: React.FC<{ shouldThrow?: boolean; errorMessage?: string }> = ({
  shouldThrow = true,
  errorMessage = 'Test error',
}) => {
  if (shouldThrow) {
    throw new Error(errorMessage);
  }
  return <div>No error</div>;
};

describe('MenuBarErrorBoundary', () => {
  // Mock console.error to avoid cluttering test output
  const originalConsoleError = console.error;
  beforeEach(() => {
    console.error = vi.fn();
  });

  afterEach(() => {
    console.error = originalConsoleError;
    vi.clearAllMocks();
  });

  describe('Normal Operation', () => {
    it('should render children when no error occurs', () => {
      render(
        <MenuBarErrorBoundary>
          <div data-testid="child">Child content</div>
        </MenuBarErrorBoundary>
      );

      expect(screen.getByTestId('child')).toBeInTheDocument();
      expect(screen.getByText('Child content')).toBeInTheDocument();
    });

    it('should not show error UI when children render successfully', () => {
      render(
        <MenuBarErrorBoundary>
          <ThrowError shouldThrow={false} />
        </MenuBarErrorBoundary>
      );

      expect(screen.getByText('No error')).toBeInTheDocument();
      expect(screen.queryByRole('alert')).not.toBeInTheDocument();
    });
  });

  describe('Error Handling', () => {
    it('should catch errors thrown by children', () => {
      render(
        <MenuBarErrorBoundary>
          <ThrowError />
        </MenuBarErrorBoundary>
      );

      // Should show error UI instead of crashing
      expect(screen.getByRole('alert')).toBeInTheDocument();
      expect(screen.getByText('Menu bar error')).toBeInTheDocument();
    });

    it('should display default fallback UI when error occurs', () => {
      render(
        <MenuBarErrorBoundary>
          <ThrowError />
        </MenuBarErrorBoundary>
      );

      // Check for error icon
      const errorIcon = screen.getByRole('alert').querySelector('svg');
      expect(errorIcon).toBeInTheDocument();

      // Check for error message
      expect(screen.getByText('Menu bar error')).toBeInTheDocument();

      // Check for retry button
      expect(screen.getByRole('button', { name: /retry/i })).toBeInTheDocument();
    });

    it('should display custom fallback UI when provided', () => {
      const customFallback = <div data-testid="custom-fallback">Custom error UI</div>;

      render(
        <MenuBarErrorBoundary fallback={customFallback}>
          <ThrowError />
        </MenuBarErrorBoundary>
      );

      expect(screen.getByTestId('custom-fallback')).toBeInTheDocument();
      expect(screen.getByText('Custom error UI')).toBeInTheDocument();
    });

    it('should log error to console for debugging', () => {
      const errorMessage = 'Test error message';
      const consoleErrorSpy = vi.spyOn(console, 'error');

      render(
        <MenuBarErrorBoundary>
          <ThrowError errorMessage={errorMessage} />
        </MenuBarErrorBoundary>
      );

      // Verify console.error was called with error details
      expect(consoleErrorSpy).toHaveBeenCalled();
      const calls = consoleErrorSpy.mock.calls;
      
      // Check that error was logged
      const errorCall = calls.find(call => 
        call[0]?.includes('MenuBar Error Boundary caught an error')
      );
      expect(errorCall).toBeDefined();

      // Check that component stack was logged
      const stackCall = calls.find(call => 
        call[0]?.includes('Component stack')
      );
      expect(stackCall).toBeDefined();
    });

    it('should show user-friendly notification when error occurs', () => {
      const showSpy = vi.spyOn(notificationService, 'show');

      render(
        <MenuBarErrorBoundary>
          <ThrowError />
        </MenuBarErrorBoundary>
      );

      // Verify notification was shown
      expect(showSpy).toHaveBeenCalledWith({
        type: 'error',
        message: 'An unexpected error occurred in the menu bar. Please reload the page.',
        duration: null,
        action: {
          label: 'Reload',
          callback: expect.any(Function),
        },
      });
    });

    it('should call custom onError callback when provided', () => {
      const onErrorMock = vi.fn();
      const errorMessage = 'Custom error';

      render(
        <MenuBarErrorBoundary onError={onErrorMock}>
          <ThrowError errorMessage={errorMessage} />
        </MenuBarErrorBoundary>
      );

      // Verify custom error handler was called
      expect(onErrorMock).toHaveBeenCalledTimes(1);
      
      // Check error parameter
      const [error, errorInfo] = onErrorMock.mock.calls[0];
      expect(error).toBeInstanceOf(Error);
      expect(error.message).toBe(errorMessage);
      
      // Check errorInfo parameter
      expect(errorInfo).toHaveProperty('componentStack');
    });
  });

  describe('Error Recovery', () => {
    it('should have a retry button in the error UI', () => {
      render(
        <MenuBarErrorBoundary>
          <ThrowError />
        </MenuBarErrorBoundary>
      );

      // Error UI should be visible with retry button
      expect(screen.getByRole('alert')).toBeInTheDocument();
      const retryButton = screen.getByRole('button', { name: /retry/i });
      expect(retryButton).toBeInTheDocument();
      
      // Verify button is clickable
      expect(retryButton).not.toBeDisabled();
    });

    it('should provide reload action in notification', () => {
      const showSpy = vi.spyOn(notificationService, 'show');

      render(
        <MenuBarErrorBoundary>
          <ThrowError />
        </MenuBarErrorBoundary>
      );

      // Get the notification callback
      const notificationCall = showSpy.mock.calls[0][0];
      const reloadCallback = notificationCall.action?.callback;

      // Verify reload callback exists and is a function
      expect(reloadCallback).toBeDefined();
      expect(typeof reloadCallback).toBe('function');
    });
  });

  describe('Accessibility', () => {
    it('should have proper ARIA attributes on error UI', () => {
      render(
        <MenuBarErrorBoundary>
          <ThrowError />
        </MenuBarErrorBoundary>
      );

      const errorAlert = screen.getByRole('alert');
      expect(errorAlert).toHaveAttribute('aria-live', 'assertive');
    });

    it('should have accessible retry button', () => {
      render(
        <MenuBarErrorBoundary>
          <ThrowError />
        </MenuBarErrorBoundary>
      );

      const retryButton = screen.getByRole('button', { name: /retry loading menu bar/i });
      expect(retryButton).toBeInTheDocument();
      expect(retryButton).toHaveAttribute('aria-label', 'Retry loading menu bar');
    });

    it('should hide error icon from screen readers', () => {
      render(
        <MenuBarErrorBoundary>
          <ThrowError />
        </MenuBarErrorBoundary>
      );

      const errorIcon = screen.getByRole('alert').querySelector('svg');
      expect(errorIcon).toHaveAttribute('aria-hidden', 'true');
    });
  });

  describe('Multiple Errors', () => {
    it('should handle multiple errors in sequence', () => {
      const showSpy = vi.spyOn(notificationService, 'show');

      // First error
      const { unmount } = render(
        <MenuBarErrorBoundary>
          <ThrowError errorMessage="First error" />
        </MenuBarErrorBoundary>
      );

      expect(showSpy).toHaveBeenCalledTimes(1);

      // Unmount and create a new error boundary instance
      unmount();

      // Second error in a new error boundary
      render(
        <MenuBarErrorBoundary>
          <ThrowError errorMessage="Second error" />
        </MenuBarErrorBoundary>
      );

      expect(showSpy).toHaveBeenCalledTimes(2);
    });
  });

  describe('Edge Cases', () => {
    it('should handle errors with no message', () => {
      const ThrowEmptyError: React.FC = () => {
        throw new Error();
      };

      render(
        <MenuBarErrorBoundary>
          <ThrowEmptyError />
        </MenuBarErrorBoundary>
      );

      // Should still show error UI
      expect(screen.getByRole('alert')).toBeInTheDocument();
    });

    it('should handle non-Error objects thrown', () => {
      const ThrowString: React.FC = () => {
        throw 'String error';
      };

      render(
        <MenuBarErrorBoundary>
          <ThrowString />
        </MenuBarErrorBoundary>
      );

      // Should still catch and display error UI
      expect(screen.getByRole('alert')).toBeInTheDocument();
    });

    it('should handle errors in nested components', () => {
      const NestedComponent: React.FC = () => (
        <div>
          <div>
            <ThrowError />
          </div>
        </div>
      );

      render(
        <MenuBarErrorBoundary>
          <NestedComponent />
        </MenuBarErrorBoundary>
      );

      // Should catch error from nested component
      expect(screen.getByRole('alert')).toBeInTheDocument();
    });
  });
});

/**
