      selectedShotId: 'shot-1', // Selected shot
    } as any;

    // Create mock clipboard
    mockClipboard = {
      hasContent: false,
      contentType: null,
      cut: vi.fn((content) => {
        mockClipboard.hasContent = true;
        mockClipboard.contentType = 'shot';
      }),
      copy: vi.fn((content) => {
        mockClipboard.hasContent = true;
        mockClipboard.contentType = 'shot';
      }),
      paste: vi.fn(() => mockShot),
