/**
 * User Preferences Modal
 * 
 * Provides a comprehensive preferences window for managing user-specific settings.
 * Currently supports language selection with plans for additional preferences.
 * 
 * Features:
 * - Language selection dropdown with all supported languages
 * - Immediate language application on save
 * - Cancel functionality to discard changes
 * - Native language names for better UX
 * 
 * @module components/modals/UserPreferencesModal
 */

import React, { useState, useEffect } from 'react';
import { Modal } from './Modal';
import { useLanguage } from '../../contexts/LanguageContext';
import { Button } from '@/components/ui/button';

export interface UserPreferencesModalProps {
  isOpen: boolean;
  onClose: () => void;
}

/**
 * User Preferences Modal Component
 * 
 * Displays a modal dialog for managing user preferences including language selection.
 * 
 * Implementation Details:
 * - Uses local state to track selected language before saving
 * - Only updates context and persists on Save button click
 * - Cancel button discards changes and closes modal
 * - Language dropdown displays format: "Native Name (English Name)"
 * 
 * @example
 * ```tsx
 * function SettingsMenu() {
 *   const [isOpen, setIsOpen] = useState(false);
 *   
 *   return (
 *     <>
 *       <button onClick={() => setIsOpen(true)}>User Preferences</button>
 *       <UserPreferencesModal 
 *         isOpen={isOpen} 
 *         onClose={() => setIsOpen(false)} 
 *       />
 *     </>
 *   );
 * }
 * ```
 */
export function UserPreferencesModal({ isOpen, onClose }: UserPreferencesModalProps) {
  const { currentLanguage, availableLanguages, setLanguage, t } = useLanguage();
  
  // Local state for selected language (not applied until Save is clicked)
  const [selectedLanguage, setSelectedLanguage] = useState(currentLanguage);

  /**
   * Sync local state with context when modal opens or current language changes
   * This ensures the dropdown shows the correct current language when reopened
   */
  useEffect(() => {
    if (isOpen) {
      setSelectedLanguage(currentLanguage);
    }
  }, [isOpen, currentLanguage]);

  /**
   * Handle Save button click
   * 
   * Applies the selected language to the context (which triggers immediate UI update
   * and persists to localStorage), then closes the modal.
   */
  const handleSave = () => {
    if (selectedLanguage !== currentLanguage) {
      setLanguage(selectedLanguage);
    }
    onClose();
  };

  /**
   * Handle Cancel button click
   * 
   * Discards any changes by resetting local state to current language,
   * then closes the modal without saving.
   */
  const handleCancel = () => {
    setSelectedLanguage(currentLanguage);
    onClose();
  };

  /**
   * Handle language dropdown change
   * 
   * Updates local state only - does not apply the language until Save is clicked.
   */
  const handleLanguageChange = (event: React.ChangeEvent<HTMLSelectElement>) => {
    setSelectedLanguage(event.target.value);
  };

  return (
    <Modal 
      isOpen={isOpen} 
      onClose={handleCancel}
      title={t('preferences.title') || 'User Preferences'}
      size="md"
    >
      <div className="space-y-6">
        {/* Language Selection Section */}
        <div className="space-y-3">
          <label 
            htmlFor="language-select"
            className="block text-sm font-medium text-gray-700 dark:text-gray-300"
          >
            {t('preferences.language') || 'Language'}
          </label>
          
          <select
            id="language-select"
            value={selectedLanguage}
            onChange={handleLanguageChange}
            className="w-full px-3 py-2 border border-gray-300 dark:border-gray-700 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100"
            aria-label={t('preferences.selectLanguage') || 'Select language'}
          >
            {availableLanguages.map((lang) => (
              <option key={lang.code} value={lang.code}>
                {lang.nativeName} ({lang.name})
              </option>
            ))}
          </select>
          
          <p className="text-xs text-gray-500 dark:text-gray-400">
            {t('preferences.languageDescription') || 'Select your preferred language for the interface'}
          </p>
        </div>

        {/* Future preference sections can be added here */}
        {/* Example:
        <div className="space-y-3">
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
            Theme
          </label>
          <select className="w-full px-3 py-2 border rounded-md">
            <option>Light</option>
            <option>Dark</option>
            <option>Auto</option>
          </select>
        </div>
        */}

        {/* Action Buttons */}
        <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
          <Button
            variant="outline"
            onClick={handleCancel}
            className="px-4 py-2"
          >
            {t('common.cancel') || 'Cancel'}
          </Button>
          
          <Button
            variant="default"
            onClick={handleSave}
            className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white"
          >
            {t('common.save') || 'Save'}
          </Button>
        </div>
      </div>
    </Modal>
  );
}

/**
 * VaultModal - Asset Vault for StoryCore Engine
 *
 * A comprehensive asset management modal that provides:
 * - Unified view of all project assets (videos, images, audio)
 * - Advanced filtering and search
 * - Grid and list view modes
 * - Asset preview and metadata
 * - Drag-and-drop support for asset import
 * - Integration with generation workflows
 *
 * @author StoryCore Engine
 * @version 1.0.0
 */

import React, { useState, useEffect, useMemo } from 'react';
import './VaultModal.css';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  Film,
  Image as ImageIcon,
  Music,
  FileText,
  Search,
  RefreshCw,
  Grid3X3,
  List,
  Download,
  Trash2,
  Heart,
  Eye,
  FolderOpen,
  HardDrive,
  X,
  Check,
  Copy,
} from 'lucide-react';
import { useAppStore } from '@/stores/useAppStore';
import { videoEditorAPI } from '@/services/videoEditorAPI';
import { notificationService } from '@/services/NotificationService';

// Asset types
type AssetType = 'video' | 'image' | 'audio' | 'all';

// Asset interface
interface VaultAsset {
  id: string;
  path: string;
  type: 'generated_video' | 'generated_image' | 'audio' | 'video' | 'image';
  name: string;
  size?: number;
  duration?: number;
  added_at?: string;
  metadata?: {
    prompt?: string;
    model?: string;
    width?: number;
    height?: number;
    fps?: number;
    bitrate?: number;
    format?: string;
  };
  favorite?: boolean;
  tags?: string[];
}

// Sorting options
type SortOption = 'date_desc' | 'date_asc' | 'name_asc' | 'name_desc' | 'size_desc' | 'size_asc';

interface VaultModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export function VaultModal({ isOpen, onClose }: VaultModalProps) {
  const project = useAppStore((state) => state.project);

  // State
  const [assets, setAssets] = useState<VaultAsset[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedType, setSelectedType] = useState<AssetType>('all');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [sortBy, setSortBy] = useState<SortOption>('date_desc');
  const [showOnlyFavorites, setShowOnlyFavorites] = useState(false);
  const [selectedAssets, setSelectedAssets] = useState<Set<string>>(new Set());
  const [previewAsset, setPreviewAsset] = useState<VaultAsset | null>(null);

  // Stats
  const [stats, setStats] = useState({
    totalAssets: 0,
    totalSize: 0,
    videosCount: 0,
    imagesCount: 0,
    audioCount: 0,
    favoriteCount: 0,
  });

  // Load assets on open
  useEffect(() => {
    if (project?.id && isOpen) {
      loadAssets();
    }
  }, [project?.id, isOpen]);

  // Load all assets from API
  const loadAssets = async () => {
    setIsLoading(true);
    try {
      const response = await videoEditorAPI.listProjectAssets(project?.id || '');
      const loadedAssets: VaultAsset[] = (response.assets || []).map((asset: { id?: string; path: string; type: VaultAsset['type']; size?: number; duration?: number; added_at?: string; metadata?: VaultAsset['metadata']; favorite?: boolean; tags?: string[] }) => ({
        id: asset.id || crypto.randomUUID(),
        path: asset.path,
        type: asset.type,
        name: asset.path.split('/').pop() || asset.path,
        size: asset.size,
        duration: asset.duration,
        added_at: asset.added_at,
        metadata: asset.metadata,
        favorite: asset.favorite || false,
        tags: asset.tags || [],
      }));

      setAssets(loadedAssets);
      calculateStats(loadedAssets);
    } catch (error) {
      console.error('[VaultModal] Failed to load assets:', error);
      notificationService.error('Error', 'Failed to load vault assets');
    } finally {
      setIsLoading(false);
    }
  };

  // Calculate statistics
  const calculateStats = (assetList: VaultAsset[]) => {
    const totalSize = assetList.reduce((sum, a) => sum + (a.size || 0), 0);
    const videosCount = assetList.filter(a => a.type === 'generated_video' || a.type === 'video').length;
    const imagesCount = assetList.filter(a => a.type === 'generated_image' || a.type === 'image').length;
    const audioCount = assetList.filter(a => a.type === 'audio').length;
    const favoriteCount = assetList.filter(a => a.favorite).length;

    setStats({
      totalAssets: assetList.length,
      totalSize,
      videosCount,
      imagesCount,
      audioCount,
      favoriteCount,
    });
  };

  // Filtered and sorted assets
  const filteredAssets = useMemo(() => {
    let filtered = [...assets];

    // Type filter
    if (selectedType !== 'all') {
      filtered = filtered.filter(asset => {
        if (selectedType === 'video') {
          return asset.type === 'generated_video' || asset.type === 'video';
        }
        if (selectedType === 'image') {
          return asset.type === 'generated_image' || asset.type === 'image';
        }
        return asset.type === selectedType;
      });
    }

    // Search filter
    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter(asset =>
        asset.name.toLowerCase().includes(query) ||
        asset.path.toLowerCase().includes(query) ||
        asset.metadata?.prompt?.toLowerCase().includes(query) ||
        asset.tags?.some(tag => tag.toLowerCase().includes(query))
      );
    }

    // Favorites filter
    if (showOnlyFavorites) {
      filtered = filtered.filter(asset => asset.favorite);
    }

    // Sorting
    filtered.sort((a, b) => {
      switch (sortBy) {
        case 'date_desc':
          return new Date(b.added_at || 0).getTime() - new Date(a.added_at || 0).getTime();
        case 'date_asc':
          return new Date(a.added_at || 0).getTime() - new Date(b.added_at || 0).getTime();
        case 'name_asc':
          return a.name.localeCompare(b.name);
        case 'name_desc':
          return b.name.localeCompare(a.name);
        case 'size_desc':
          return (b.size || 0) - (a.size || 0);
        case 'size_asc':
          return (a.size || 0) - (b.size || 0);
        default:
          return 0;
      }
    });

    return filtered;
  }, [assets, selectedType, searchQuery, showOnlyFavorites, sortBy]);

  // Toggle favorite
  const toggleFavorite = (assetId: string) => {
    setAssets(prev => prev.map(asset =>
      asset.id === assetId ? { ...asset, favorite: !asset.favorite } : asset
    ));
    calculateStats(assets.map(asset =>
      asset.id === assetId ? { ...asset, favorite: !asset.favorite } : asset
    ));
  };

  // Delete asset
  const deleteAsset = async (asset: VaultAsset) => {
    if (!confirm(`Are you sure you want to delete "${asset.name}"?`)) return;

    try {
      // API call to delete would go here
      setAssets(prev => prev.filter(a => a.id !== asset.id));
      notificationService.success('Deleted', `"${asset.name}" has been deleted`);
    } catch {
      notificationService.error('Error', 'Failed to delete asset');
    }
  };

  // Download asset
  const downloadAsset = (asset: VaultAsset) => {
    const url = `/api/video-editor/projects/${project?.id}/media-raw?path=${asset.path}`;
    const link = document.createElement('a');
    link.href = url;
    link.download = asset.name;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Copy path to clipboard
  const copyPathToClipboard = (path: string) => {
    navigator.clipboard.writeText(path);
    notificationService.success('Copied', 'Path copied to clipboard');
  };

  // Toggle selection
  const toggleSelection = (assetId: string) => {
    setSelectedAssets(prev => {
      const next = new Set(prev);
      if (next.has(assetId)) {
        next.delete(assetId);
      } else {
        next.add(assetId);
      }
      return next;
    });
  };

  // Select all
  const selectAll = () => {
    setSelectedAssets(new Set(filteredAssets.map(a => a.id)));
  };

  // Clear selection
  const clearSelection = () => {
    setSelectedAssets(new Set());
  };

  // Bulk delete
  const bulkDelete = async () => {
    if (selectedAssets.size === 0) return;
    if (!confirm(`Delete ${selectedAssets.size} selected assets?`)) return;

    try {
      setAssets(prev => prev.filter(a => !selectedAssets.has(a.id)));
      clearSelection();
      notificationService.success('Deleted', `${selectedAssets.size} assets deleted`);
    } catch {
      notificationService.error('Error', 'Failed to delete assets');
    }
  };

  // Format file size
  const formatSize = (bytes?: number) => {
    if (!bytes) return 'N/A';
    const units = ['B', 'KB', 'MB', 'GB'];
    let unitIndex = 0;
    let size = bytes;
    while (size >= 1024 && unitIndex < units.length - 1) {
      size /= 1024;
      unitIndex++;
    }
    return `${size.toFixed(1)} ${units[unitIndex]}`;
  };

  // Format duration
  const formatDuration = (seconds?: number) => {
    if (!seconds) return 'N/A';
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  // Get asset icon
  const getAssetIcon = (type: string) => {
    switch (type) {
      case 'generated_video':
      case 'video':
        return <Film className="w-4 h-4 text-blue-400" />;
      case 'generated_image':
      case 'image':
        return <ImageIcon className="w-4 h-4 text-green-400" />;
      case 'audio':
        return <Music className="w-4 h-4 text-purple-400" />;
      default:
        return <FileText className="w-4 h-4 text-gray-400" />;
    }
  };

  // Get asset URL
  const getAssetUrl = (asset: VaultAsset) => {
    return `/api/video-editor/projects/${project?.id}/media-raw?path=${asset.path}`;
  };

  if (!project) {
    return (
      <Dialog open={isOpen} onOpenChange={onClose}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-hidden">
          <DialogHeader>
            <DialogTitle>Asset Vault</DialogTitle>
          </DialogHeader>
          <div className="p-8 text-center text-gray-500">
            <FolderOpen className="w-12 h-12 mx-auto mb-4 opacity-50" />
            <p>No project open</p>
            <p className="text-sm">Open a project to access the Asset Vault</p>
          </div>
        </DialogContent>
      </Dialog>
    );
  }

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="vault-modal max-w-7xl max-h-[95vh] overflow-hidden flex flex-col">
        <DialogHeader className="flex-shrink-0">
          <DialogTitle className="flex items-center gap-2 text-xl">
            <HardDrive className="w-5 h-5 text-primary" />
            Asset Vault
            <Badge variant="secondary" className="ml-2">
              {stats.totalAssets} assets
            </Badge>
          </DialogTitle>
        </DialogHeader>

        {/* Stats Bar */}
        <div className="flex-shrink-0 px-4 py-2 bg-muted/30 border-b flex items-center justify-between">
          <div className="flex items-center gap-6 text-sm text-muted-foreground">
            <span className="flex items-center gap-1.5">
              <Film className="w-4 h-4 text-blue-400" />
              {stats.videosCount} videos
            </span>
            <span className="flex items-center gap-1.5">
              <ImageIcon className="w-4 h-4 text-green-400" />
              {stats.imagesCount} images
            </span>
            <span className="flex items-center gap-1.5">
              <Music className="w-4 h-4 text-purple-400" />
              {stats.audioCount} audio
            </span>
            <span className="flex items-center gap-1.5">
              <Heart className="w-4 h-4 text-red-400" />
              {stats.favoriteCount} favorites
            </span>
          </div>
          <span className="text-sm text-muted-foreground">
            Total: {formatSize(stats.totalSize)}
          </span>
        </div>

        {/* Toolbar */}
        <div className="flex-shrink-0 p-4 border-b flex items-center gap-4 flex-wrap">
          {/* Search */}
          <div className="relative flex-1 min-w-[200px] max-w-sm">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input
              placeholder="Search assets..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-10"
            />
          </div>

          {/* Type Filter */}
          <Tabs value={selectedType} onValueChange={(v) => setSelectedType(v as AssetType)}>
            <TabsList className="h-9">
              <TabsTrigger value="all" className="text-xs px-3">All</TabsTrigger>
              <TabsTrigger value="video" className="text-xs px-3">
                <Film className="w-3 h-3 mr-1" />
                Videos
              </TabsTrigger>
              <TabsTrigger value="image" className="text-xs px-3">
                <ImageIcon className="w-3 h-3 mr-1" />
                Images
              </TabsTrigger>
