/**
 * WorldModal - Modale de gestion du monde
 *
 * Permet de voir, cr├®er, modifier et supprimer les ├®l├®ments du monde du projet
 */

import React, { useState, useEffect } from 'react';
import './SharedModalStyles.css';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import {
  GlobeIcon,
  PlusIcon,
  EditIcon,
  TrashIcon,
  SaveIcon,
  XIcon,
  SearchIcon,
  StarIcon,
  MapPinIcon,
  MountainIcon,
  CastleIcon,
} from 'lucide-react';
import { useAppStore } from '@/stores/useAppStore';
import { notificationService } from '@/services/NotificationService';

interface WorldElement {
  id: string;
  name: string;
  description: string;
  type: 'location' | 'landmark' | 'region' | 'realm' | 'dimension';
  geography: string;
  culture: string;
  history: string;
  significance: string;
  importance: 'high' | 'medium' | 'low';
  tags: string[];
  createdAt: Date;
  updatedAt: Date;
}

interface WorldModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export function WorldModal({ isOpen, onClose }: WorldModalProps) {
  const project = useAppStore((state) => state.project);

  // ├ëtat local pour les ├®l├®ments du monde
  const [worldElements, setWorldElements] = useState<WorldElement[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedType, setSelectedType] = useState<WorldElement['type'] | 'all'>('all');
  const [selectedImportance, setSelectedImportance] = useState<WorldElement['importance'] | 'all'>('all');
  const [editingElement, setEditingElement] = useState<WorldElement | null>(null);

  // Charger les ├®l├®ments du monde du projet
  useEffect(() => {
    if (project && isOpen) {
      loadWorldElements();
    }
  }, [project, isOpen]);

  const loadWorldElements = () => {
    if (!project) return;

    try {
      // Dans un vrai syst├¿me, cela viendrait du projet ou d'une API
      // Pour l'instant, on simule avec des donn├®es locales
      const projectWorldElements = localStorage.getItem(`world_elements_${project.id}`);
      if (projectWorldElements) {
        const parsed = JSON.parse(projectWorldElements);
        const elementsWithDates = parsed.map((element: unknown) => ({
          ...element,
          createdAt: new Date(element.createdAt),
          updatedAt: new Date(element.updatedAt)
        }));
        setWorldElements(elementsWithDates);
      } else {
        // ├ël├®ments du monde par d├®faut pour la d├®monstration
        const defaultElements: WorldElement[] = [
          {
            id: 'world_1',
            name: 'Royaume d\'Eldoria',
            description: 'Un royaume majestueux avec des ch├óteaux imposants et des for├¬ts enchant├®es.',
            type: 'realm',
            geography: 'Vall├®es verdoyantes, montagnes escarp├®es, rivi├¿res cristallines',
            culture: 'Chevalerie, magie ancienne, festivals des saisons',
            history: 'Fond├® il y a 500 ans par le Roi Arthur apr├¿s la Grande Guerre',
            significance: 'Centre politique et culturel du continent',
            importance: 'high',
            tags: ['royaume', 'magie', 'chevalerie', 'politique'],
            createdAt: new Date(),
            updatedAt: new Date()
          },
          {
            id: 'world_2',
            name: 'For├¬t de Cristal',
            description: 'Une for├¬t mystique o├╣ les arbres scintillent comme des diamants.',
            type: 'location',
            geography: 'For├¬t dense avec des arbres de cristal, ruisseaux magiques',
            culture: 'Esprits de la nature, druides protecteurs',
            history: 'Cr├®├®e par les anciens elfes pour prot├®ger les secrets de la magie',
            significance: 'Source de magie pure et lieu de p├¿lerinage',
            importance: 'medium',
            tags: ['magie', 'nature', 'elfes', 'myst├¿re'],
            createdAt: new Date(),
            updatedAt: new Date()
          },
          {
            id: 'world_3',
            name: 'Montagnes de Feu',
            description: 'Des montagnes volcaniques o├╣ le feu et la lave r├¿gnent en ma├«tres.',
            type: 'region',
            geography: 'Cha├«ne de volcans actifs, rivi├¿res de lave, terres st├®riles',
            culture: 'Forgeurs de m├®tal, gardiens du feu, rituels volcaniques',
            history: 'Form├®es lors de la chute des anciens dieux du feu',
            significance: 'Source de m├®taux pr├®cieux et lieu de pouvoir ├®l├®mentaire',
            importance: 'medium',
            tags: ['volcan', 'feu', 'm├®tal', 'danger'],
            createdAt: new Date(),
            updatedAt: new Date()
          }
        ];
        setWorldElements(defaultElements);
        saveWorldElements(defaultElements);
      }
    } catch (error) {
      console.error('Failed to load world elements:', error);
      notificationService.error('Erreur', 'Impossible de charger les ├®l├®ments du monde');
    }
  };

  const saveWorldElements = (elements: WorldElement[]) => {
    if (!project) return;

    try {
      localStorage.setItem(`world_elements_${project.id}`, JSON.stringify(elements));
    } catch (error) {
      console.error('Failed to save world elements:', error);
      notificationService.error('Erreur', 'Impossible de sauvegarder les ├®l├®ments du monde');
    }
  };

  const filteredElements = worldElements.filter(element => {
    const matchesSearch = searchQuery === '' ||
      element.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      element.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
      element.tags.some(tag => tag.toLowerCase().includes(searchQuery.toLowerCase()));

    const matchesType = selectedType === 'all' || element.type === selectedType;
    const matchesImportance = selectedImportance === 'all' || element.importance === selectedImportance;

    return matchesSearch && matchesType && matchesImportance;
  });

  const handleCreateElement = () => {
    const newElement: WorldElement = {
      id: `world_${Date.now()}`,
      name: '',
      description: '',
      type: 'location',
      geography: '',
      culture: '',
      history: '',
      significance: '',
      importance: 'low',
      tags: [],
      createdAt: new Date(),
      updatedAt: new Date()
    };

    setEditingElement(newElement);
  };

const handleEditElement = (element: WorldElement) => {
    setEditingElement({ ...element });
  };

  const handleSaveElement = (element: WorldElement) => {
    if (!element.name.trim()) {
      notificationService.warning('Erreur', 'Le nom de l\'├®l├®ment est requis');
      return;
    }

    const updatedElements = editingElement?.id
      ? worldElements.map(e => e.id === element.id ? { ...element, updatedAt: new Date() } : e)
      : [...worldElements, element];

    setWorldElements(updatedElements);
    saveWorldElements(updatedElements);
    setEditingElement(null);

    notificationService.success(
      '├ël├®ment sauvegard├®',
      `L'├®l├®ment "${element.name}" a ├®t├® ${editingElement?.id ? 'modifi├®' : 'cr├®├®'} avec succ├¿s.`
    );
  };

  const handleDeleteElement = (elementId: string) => {
    const element = worldElements.find(e => e.id === elementId);
    if (!element) return;

    if (confirm(`├ètes-vous s├╗r de vouloir supprimer l'├®l├®ment "${element.name}" ?`)) {
      const updatedElements = worldElements.filter(e => e.id !== elementId);
      setWorldElements(updatedElements);
      saveWorldElements(updatedElements);

      notificationService.info('├ël├®ment supprim├®', `L'├®l├®ment "${element.name}" a ├®t├® supprim├®.`);
    }
  };

  const getTypeIcon = (type: WorldElement['type']) => {
    switch (type) {
      case 'realm':
        return <CastleIcon className="w-4 h-4 text-purple-500" />;
      case 'region':
        return <MountainIcon className="w-4 h-4 text-green-500" />;
      case 'location':
        return <MapPinIcon className="w-4 h-4 text-blue-500" />;
      case 'landmark':
        return <StarIcon className="w-4 h-4 text-yellow-500" />;
      case 'dimension':
        return <GlobeIcon className="w-4 h-4 text-indigo-500" />;
    }
  };

  const getTypeLabel = (type: WorldElement['type']) => {
    switch (type) {
      case 'realm':
        return 'Royaume';
      case 'region':
        return 'R├®gion';
      case 'location':
        return 'Lieu';
      case 'landmark':
        return 'Point de rep├¿re';
      case 'dimension':
        return 'Dimension';
    }
  };

  const getImportanceColor = (importance: WorldElement['importance']) => {
    switch (importance) {
      case 'high':
        return 'bg-red-100 text-red-800';
      case 'medium':
        return 'bg-yellow-100 text-yellow-800';
      case 'low':
        return 'bg-gray-100 text-gray-800';
    }
  };

  if (!project) {
    return (
