        { time: 100, value: 1.0 }
      ],
      easing: 'easeInOut'
    }
  ]);

  const handleTemplateClick = (templateId: string) => {
    // Open template logic
  };

  const handleAddKeyframe = () => {
    const newKeyframe = {
      id: `keyframe_${Date.now()}`,
      name: 'New Property',
      property: 'opacity',
      values: [
        { time: 0, value: 1.0 },
        { time: 100, value: 0.0 }
      ],
      easing: 'linear'
    };
    setKeyframes([...keyframes, newKeyframe]);
  };

  return (
    <div className={styles.motionPage}>
      <div className={styles.pageHeader}>
        <h2>Motion Graphics Page</h2>
        <div className={styles.pageTabs}>
          <button
            className={`${styles.tabBtn} ${activeTab === 'templates' ? styles.active : ''}`}
            onClick={() => setActiveTab('templates')}
          >
            Templates
          </button>
          <button
            className={`${styles.tabBtn} ${activeTab === 'keyframing' ? styles.active : ''}`}
            onClick={() => setActiveTab('keyframing')}
          >
            Keyframing
          </button>
          <button
            className={`${styles.tabBtn} ${activeTab === 'animation' ? styles.active : ''}`}
            onClick={() => setActiveTab('animation')}
          >
            Animation
          </button>
          <button
            className={`${styles.tabBtn} ${activeTab === 'export' ? styles.active : ''}`}
            onClick={() => setActiveTab('export')}
          >
            Export
          </button>
        </div>
      </div>

      <div className={styles.pageContent}>
        {activeTab === 'templates' && (
          <div className={styles.templatesView}>
            <h3>Templates Library</h3>
            <div className={styles.templatesGrid}>
              {templates.map((template) => (
                <div key={template.id} className={styles.templateCard}>
                  <div className={styles.templatePreview}>
                    <img src={template.preview} alt={template.name} />
                    <span className={styles.templateDuration}>{template.duration}</span>
                  </div>
                  <div className={styles.templateInfo}>
                    <h4>{template.name}</h4>
                    <p className={styles.templateType}>{template.type}</p>
                    <p className={styles.templateResolution}>{template.resolution}</p>
                  </div>
                  <div className={styles.templateActions}>
                    <button onClick={() => handleTemplateClick(template.id)}>Use Template</button>
                  </div>
                </div>
              ))}
            </div>
            <button className={styles.addTemplateBtn}>+ New Template</button>
          </div>
        )}

        {activeTab === 'keyframing' && (
          <div className={styles.keyframingView}>
            <h3>Keyframe Editor</h3>
            <div className={styles.keyframesList}>
              {keyframes.map((keyframe) => (
                <div key={keyframe.id} className={styles.keyframeCard}>
                  <div className={styles.keyframeHeader}>
                    <h4>{keyframe.name}</h4>
                    <span className={styles.keyframeProperty}>{keyframe.property}</span>
                  </div>
                  <div className={styles.keyframeEasing}>
                    <label>Easing:</label>
                    <select value={keyframe.easing}>
                      <option value="linear">Linear</option>
                      <option value="easeIn">Ease In</option>
                      <option value="easeOut">Ease Out</option>
                      <option value="easeInOut">Ease In Out</option>
                    </select>
                  </div>
                  <div className={styles.keyframeValues}>
                    {keyframe.values.map((value: any, index: number) => (
                      <div key={index} className={styles.keyframeValue}>
                        <label>Time: {value.time}%</label>
                        <input
                          type="text"
                          value={JSON.stringify(value.value)}
                          readOnly
                        />
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
            <button className={styles.addKeyframeBtn} onClick={handleAddKeyframe}>
              + Add Keyframe
            </button>
          </div>
        )}

        {activeTab === 'animation' && (
          <div className={styles.animationView}>
            <h3>Animation Tools</h3>
            <p>Animation features will be implemented in a future phase.</p>
          </div>
        )}

        {activeTab === 'export' && (
          <div className={styles.exportView}>
            <h3>Export</h3>
            <p>Export features will be implemented in a future phase.</p>
          </div>
        )}
      </div>

      <div className={styles.pageFooter}>
        <div className={styles.globalControls}>
          <label className={styles.toggleLabel}>
            <input type="checkbox" />
            <span>Motion Processing ON</span>
          </label>
        </div>

        <div className={styles.pageActions}>
          <button className={styles.primaryBtn}>Apply Animation</button>
          <button className={styles.secondaryBtn}>Reset Animation</button>
          <button className={styles.compareBtn}>Preview</button>
        </div>
      </div>
    </div>
  );
};

/**
 * Main Sidebar Navigation Component
 * Primary navigation for the application with service status indicators
 */

import React, { useState } from 'react';
import { useAppStore } from '@/stores/useAppStore';
import { useTheme } from '@/hooks/useTheme';
import {
  LayoutDashboard,
  FolderOpen,
  Wand2,
  Image,
  Settings,
  ChevronLeft,
  ChevronRight,
  Moon,
  Sun,
  Wifi,
  WifiOff,
  Cpu,
  Sparkles,
  Bell,
  User,
  HelpCircle,
} from 'lucide-react';
import { cn } from '@/lib/utils';

interface NavItem {
  id: string;
  label: string;
  icon: React.ReactNode;
  badge?: number | string;
  badgeColor?: 'default' | 'success' | 'warning' | 'error' | 'info';
  onClick?: () => void;
}

interface MainSidebarProps {
  activeView: string;
  onViewChange: (view: string) => void;
  collapsed?: boolean;
  onToggleCollapse?: () => void;
  className?: string;
}

export function MainSidebar({
  activeView,
  onViewChange,
  collapsed = false,
  onToggleCollapse,
  className,
}: MainSidebarProps) {
  const { theme, effectiveTheme, toggleTheme } = useTheme();
  const [notifications] = useState(3); // Mock notifications count

  // Get service status from store
  const isOllamaConnected = useAppStore((state) => state.ollamaStatus === 'connected');
  const isComfyUIConnected = useAppStore((state) => state.comfyuiStatus === 'connected');

  const navItems: NavItem[] = [
    {
      id: 'dashboard',
      label: 'Dashboard',
      icon: <LayoutDashboard className="w-5 h-5" />,
    },
    {
      id: 'projects',
      label: 'Projets',
      icon: <FolderOpen className="w-5 h-5" />,
    },
    {
      id: 'wizards',
      label: 'Wizards',
      icon: <Wand2 className="w-5 h-5" />,
      badge: '6',
      badgeColor: 'info',
    },
    {
      id: 'ai-services',
      label: 'Local AI',
      icon: <Sparkles className="w-5 h-5" />,
    },
    {
      id: 'media',
      label: 'M├®diath├¿que',
      icon: <Image className="w-5 h-5" />,
    },
    {
      id: 'settings',
      label: 'R├®glages',
      icon: <Settings className="w-5 h-5" />,
    },
  ];

  const bottomItems: NavItem[] = [
    {
      id: 'help',
      label: 'Aide',
      icon: <HelpCircle className="w-5 h-5" />,
      onClick: () => window.open('/docs', '_blank'),
    },
    {
      id: 'profile',
      label: 'Profil',
      icon: <User className="w-5 h-5" />,
    },
  ];

  const ServiceStatus = () => (
    <div className="space-y-2 px-3 py-2 border-t border-border">
      {/* Ollama Status */}
      <div className={cn(
        'flex items-center gap-2 px-2 py-1.5 rounded-md text-xs',
        isOllamaConnected ? 'bg-green-500/10 text-green-600' : 'bg-red-500/10 text-red-600'
      )}>
        {isOllamaConnected ? (
          <Wifi className="w-3.5 h-3.5" />
        ) : (
          <WifiOff className="w-3.5 h-3.5" />
        )}
        <span className="flex-1">Ollama</span>
        <span className={cn(
          'w-2 h-2 rounded-full',
          isOllamaConnected ? 'bg-green-500' : 'bg-red-500'
        )} />
      </div>

      {/* ComfyUI Status */}
      <div className={cn(
        'flex items-center gap-2 px-2 py-1.5 rounded-md text-xs',
        isComfyUIConnected ? 'bg-green-500/10 text-green-600' : 'bg-red-500/10 text-red-600'
      )}>
        {isComfyUIConnected ? (
          <Cpu className="w-3.5 h-3.5" />
        ) : (
          <Cpu className="w-3.5 h-3.5" />
        )}
        <span className="flex-1">ComfyUI</span>
        <span className={cn(
          'w-2 h-2 rounded-full',
          isComfyUIConnected ? 'bg-green-500' : 'bg-red-500'
        )} />
      </div>
    </div>
  );

  const ThemeToggle = () => (
    <button
      onClick={() => toggleTheme()}
      className={cn(
        'w-full flex items-center gap-3 px-3 py-2 rounded-lg transition-colors',
        'hover:bg-accent text-muted-foreground hover:text-foreground'
      )}
      title={`Theme actuel: ${theme}`}
    >
      {effectiveTheme === 'dark' ? (
        <Moon className="w-5 h-5" />
      ) : (
        <Sun className="w-5 h-5" />
      )}
      {!collapsed && <span className="text-sm">Theme</span>}
    </button>
  );

  return (
    <aside
      className={cn(
        'flex flex-col h-screen bg-background border-r transition-all duration-300',
        collapsed ? 'w-16' : 'w-64',
        className
      )}
    >
      {/* Header / Logo */}
      <div className={cn(
        'flex items-center gap-3 p-4 border-b border-border',
        collapsed ? 'justify-center' : ''
      )}>
        <div className="flex items-center justify-center w-10 h-10 rounded-lg bg-primary">
          <Sparkles className="w-6 h-6 text-primary-foreground" />
