          </div>
        )}
      </div>

      {/* Main Navigation */}
      <nav className="flex-1 p-2 space-y-1 overflow-y-auto">
        {navItems.map((item) => (
          <button
            key={item.id}
            onClick={() => onViewChange(item.id)}
            className={cn(
              'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all',
              'hover:bg-accent',
              activeView === item.id
                ? 'bg-primary text-primary-foreground hover:bg-primary/90'
                : 'text-muted-foreground hover:text-foreground'
            )}
            title={collapsed ? item.label : undefined}
          >
            <span className="flex-shrink-0">{item.icon}</span>
            {!collapsed && (
              <>
                <span className="flex-1 text-left text-sm font-medium">
                  {item.label}
                </span>
                {item.badge && (
                  <span className={cn(
                    'px-2 py-0.5 text-xs rounded-full',
                    activeView === item.id
                      ? 'bg-primary-foreground/20 text-primary-foreground'
                      : cn(
                        'bg-primary/10 text-primary',
                        item.badgeColor === 'success' && 'bg-green-500/10 text-green-600',
                        item.badgeColor === 'warning' && 'bg-yellow-500/10 text-yellow-600',
                        item.badgeColor === 'error' && 'bg-red-500/10 text-red-600',
                        item.badgeColor === 'info' && 'bg-blue-500/10 text-blue-600'
                      )
                  )}>
                    {item.badge}
                  </span>
                )}
              </>
            )}
          </button>
        ))}
      </nav>

      {/* Bottom Section */}
      <div className="p-2 border-t border-border space-y-1">
        {/* Notifications */}
        <button
          className={cn(
            'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-colors relative',
            'hover:bg-accent text-muted-foreground hover:text-foreground'
          )}
          title={collapsed ? 'Notifications' : undefined}
        >
          <Bell className="w-5 h-5" />
          {!collapsed && <span className="text-sm">Notifications</span>}
          {notifications > 0 && (
            <span className="absolute top-1 right-1 w-4 h-4 bg-red-500 text-white text-[10px] rounded-full flex items-center justify-center">
              {notifications}
            </span>
          )}
        </button>

        {/* Theme Toggle */}
        <ThemeToggle />

        {/* Service Status */}
        {!collapsed && <ServiceStatus />}

        {/* Bottom Nav Items */}
        {bottomItems.map((item) => (
          <button
            key={item.id}
            onClick={item.onClick}
            className={cn(
              'w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-colors',
              'hover:bg-accent text-muted-foreground hover:text-foreground'
            )}
            title={collapsed ? item.label : undefined}
          >
            <span className="flex-shrink-0">{item.icon}</span>
            {!collapsed && (
              <span className="text-sm font-medium">{item.label}</span>
            )}
          </button>
        ))}
      </div>

      {/* Collapse Toggle */}
      {onToggleCollapse && (
        <button
          onClick={onToggleCollapse}
          className={cn(
            'flex items-center justify-center p-3 border-t border-border',
            'hover:bg-accent transition-colors text-muted-foreground'
          )}
          title={collapsed ? 'D├®velopper' : 'R├®duire'}
        >
          {collapsed ? (
            <ChevronRight className="w-5 h-5" />
          ) : (
            <ChevronLeft className="w-5 h-5" />
          )}
        </button>
      )}
    </aside>
  );
}

/**
 * Compact sidebar for mobile or secondary views
 */
export function CompactSidebar({
  items,
  activeItem,
  onItemClick,
  className,
}: {
  items: NavItem[];
  activeItem: string;
  onItemClick: (id: string) => void;
  className?: string;
}) {
  return (
    <aside
      className={cn(
        'flex flex-col h-screen bg-background border-r',
        className
      )}
    >
      <nav className="flex-1 p-2 space-y-1">
        {items.map((item) => (
          <button
            key={item.id}
            onClick={() => onItemClick(item.id)}
            className={cn(
              'w-full flex items-center justify-center gap-3 px-3 py-2.5 rounded-lg transition-all',
              'hover:bg-accent',
              activeItem === item.id
                ? 'bg-primary text-primary-foreground'
                : 'text-muted-foreground hover:text-foreground'
            )}
            title={item.label}
          >
            <span className="flex-shrink-0">{item.icon}</span>
          </button>
        ))}
      </nav>
    </aside>
  );
}

/**
 * Breadcrumb navigation component
 */
interface BreadcrumbItem {
  label: string;
  onClick?: () => void;
  icon?: React.ReactNode;
}

interface BreadcrumbProps {
  items: BreadcrumbItem[];
  className?: string;
}

export function Breadcrumb({ items, className }: BreadcrumbProps) {
  return (
    <nav className={cn('flex items-center gap-2 text-sm', className)}>
      {items.map((item, index) => (
        <React.Fragment key={index}>
          {index > 0 && (
            <span className="text-muted-foreground">/</span>
          )}
          {item.onClick ? (
            <button
              onClick={item.onClick}
              className="flex items-center gap-1 text-muted-foreground hover:text-foreground transition-colors"
            >
              {item.icon}
              <span>{item.label}</span>
            </button>
          ) : (
            <span className="flex items-center gap-1 text-foreground font-medium">
              {item.icon}
              <span>{item.label}</span>
            </span>
          )}
        </React.Fragment>
      ))}
    </nav>
  );
}

export default MainSidebar;

/**
 * NotificationCenter - Centre de notifications intelligentes
 *
 * Interface utilisateur pour afficher et g├®rer les notifications contextuelles
 */

import React, { useState, useEffect } from 'react';
import {
  Bell,
  X,
  Check,
  AlertCircle,
  Info,
  AlertTriangle,
  Zap,
  Clock,
  Settings,
  Volume2,
  VolumeX
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { notificationService, type Notification, type NotificationType } from '@/services/NotificationService';

interface NotificationCenterProps {
  className?: string;
}

export function NotificationCenter({ className = '' }: NotificationCenterProps) {
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isOpen, setIsOpen] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);

  useEffect(() => {
    // S'abonner aux changements de notifications
    const unsubscribe = notificationService.subscribe((activeNotifications) => {
      setNotifications(activeNotifications);
      setUnreadCount(notificationService.getUnreadCount());
    });

    // Charger les notifications initiales
    setNotifications(notificationService.getActiveNotifications());
    setUnreadCount(notificationService.getUnreadCount());

    return unsubscribe;
  }, []);

  const getNotificationIcon = (type: NotificationType) => {
    switch (type) {
      case 'success':
        return <Check className="w-5 h-5 text-green-500" />;
      case 'error':
        return <AlertCircle className="w-5 h-5 text-red-500" />;
      case 'warning':
        return <AlertTriangle className="w-5 h-5 text-yellow-500" />;
      case 'info':
        return <Info className="w-5 h-5 text-blue-500" />;
      case 'update':
        return <Zap className="w-5 h-5 text-purple-500" />;
      case 'reminder':
        return <Clock className="w-5 h-5 text-orange-500" />;
      case 'achievement':
        return <Zap className="w-5 h-5 text-yellow-400" />;
      case 'system':
        return <Settings className="w-5 h-5 text-gray-500" />;
      default:
        return <Info className="w-5 h-5 text-gray-500" />;
    }
  };

  const getNotificationColor = (type: NotificationType) => {
    switch (type) {
      case 'success':
        return 'border-green-500 bg-green-50';
      case 'error':
        return 'border-red-500 bg-red-50';
      case 'warning':
        return 'border-yellow-500 bg-yellow-50';
      case 'info':
        return 'border-blue-500 bg-blue-50';
      case 'update':
        return 'border-purple-500 bg-purple-50';
      case 'reminder':
        return 'border-orange-500 bg-orange-50';
      case 'achievement':
        return 'border-yellow-400 bg-yellow-50';
      case 'system':
        return 'border-gray-500 bg-gray-50';
      default:
        return 'border-gray-500 bg-gray-50';
    }
  };

  const formatTimeAgo = (date: Date) => {
    const now = new Date();
    const diffInSeconds = Math.floor((now.getTime() - date.getTime()) / 1000);

    if (diffInSeconds < 60) {
      return '├Ç l\'instant';
    } else if (diffInSeconds < 3600) {
      const minutes = Math.floor(diffInSeconds / 60);
      return `Il y a ${minutes} min`;
    } else if (diffInSeconds < 86400) {
      const hours = Math.floor(diffInSeconds / 3600);
      return `Il y a ${hours} h`;
    } else {
      const days = Math.floor(diffInSeconds / 86400);
      return `Il y a ${days} j`;
    }
  };

  const handleMarkAsRead = (id: string) => {
    notificationService.markAsRead(id);
  };

  const handleDismiss = (id: string) => {
    notificationService.dismiss(id);
  };

  const handleClearAll = () => {
    notificationService.clearAll();
  };

  const handleNotificationAction = (action: () => void) => {
    action();
  };

  return (
    <div className={`relative ${className}`}>
      {/* Bouton du centre de notifications */}
      <Button
        variant="ghost"
        size="icon"
        onClick={() => setIsOpen(!isOpen)}
        className="relative text-gray-400 hover:text-white hover:bg-gray-700"
        title="Centre de notifications"
        aria-label={`Notifications (${unreadCount} non lues)`}
      >
        <Bell className="w-5 h-5" />
        {unreadCount > 0 && (
          <span className="absolute -top-1 -right-1 bg-red-500 text-white text-xs rounded-full h-5 w-5 flex items-center justify-center font-bold">
            {unreadCount > 99 ? '99+' : unreadCount}
          </span>
        )}
      </Button>

      {/* Panneau des notifications */}
      {isOpen && (
        <div className="absolute right-0 top-12 w-96 max-h-96 bg-gray-800 border border-gray-700 rounded-lg shadow-xl z-50 overflow-hidden">
          {/* Header */}
          <div className="flex items-center justify-between p-4 border-b border-gray-700">
            <h3 className="text-lg font-semibold text-white">Notifications</h3>
            <div className="flex items-center gap-2">
              {notifications.length > 0 && (
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={handleClearAll}
                  className="text-xs text-gray-400 hover:text-white"
                >
                  Tout effacer
                </Button>
              )}
              <Button
                variant="ghost"
                size="icon"
                onClick={() => setIsOpen(false)}
                className="text-gray-400 hover:text-white"
              >
                <X className="w-4 h-4" />
              </Button>
            </div>
          </div>

          {/* Liste des notifications */}
          <div className="max-h-80 overflow-y-auto">
            {notifications.length === 0 ? (
              <div className="p-8 text-center text-gray-500">
                <Bell className="w-8 h-8 mx-auto mb-2 opacity-50" />
                <p className="text-sm">Aucune notification</p>
              </div>
            ) : (
              <div className="divide-y divide-gray-700">
                {notifications.map((notification) => (
                  <div
                    key={notification.id}
                    className={`p-4 ${getNotificationColor(notification.type)} ${!notification.read ? 'bg-opacity-20' : 'bg-opacity-10'}`}
                  >
                    <div className="flex items-start gap-3">
                      {/* Ic├┤ne */}
                      <div className="flex-shrink-0 mt-0.5">
                        {getNotificationIcon(notification.type)}
                      </div>

                      {/* Contenu */}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-start justify-between">
                          <h4 className="text-sm font-medium text-gray-900 truncate">
                            {notification.title}
                          </h4>
                          <button
                            onClick={() => handleDismiss(notification.id)}
                            className="text-gray-400 hover:text-gray-600 ml-2 flex-shrink-0"
                            title="Fermer"
                          >
                            <X className="w-4 h-4" />
                          </button>
                        </div>

                        <p className="text-sm text-gray-700 mt-1">
                          {notification.message}
                        </p>

                        {/* Actions */}
                        {notification.actions && notification.actions.length > 0 && (
                          <div className="flex gap-2 mt-2">
                            {notification.actions.map((action, index) => (
                              <Button
                                key={index}
                                variant={action.primary ? "default" : "outline"}
                                size="sm"
                                onClick={() => handleNotificationAction(action.action)}
                                className="text-xs h-7"
                              >
                                {action.label}
                              </Button>
                            ))}
                          </div>
                        )}

                        {/* M├®tadonn├®es */}
                        <div className="flex items-center justify-between mt-2 text-xs text-gray-500">
                          <span>{formatTimeAgo(notification.timestamp)}</span>
                          {!notification.read && (
                            <button
                              onClick={() => handleMarkAsRead(notification.id)}
                              className="text-blue-600 hover:text-blue-800"
                            >
                              Marquer comme lu
                            </button>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Footer avec param├¿tres */}
          <div className="p-3 border-t border-gray-700 bg-gray-900">
            <Button
              variant="ghost"
              size="sm"
              className="w-full text-xs text-gray-400 hover:text-white justify-start"
              onClick={() => {
              }}
            >
              <Settings className="w-4 h-4 mr-2" />
              Param├¿tres des notifications
            </Button>
          </div>
        </div>
      )}

      {/* Overlay pour fermer en cliquant ailleurs */}
      {isOpen && (
        <div
          className="fixed inset-0 z-40"
          onClick={() => setIsOpen(false)}
        />
      )}
    </div>
  );
}

/**
 * 3D Object Placer Component
 * 
 * Interface for placing 3D objects into scenes with drag-and-drop positioning.
 * Requirements: 3D object library integration, position controls, real-time preview
 */

import React, { useState, useCallback, useRef, useMemo } from 'react';
import { useToast } from '@/hooks/use-toast';
import './ObjectPlacer.css';

interface Object3D {
  id: string;
  name: string;
  category: string;
  tags?: string[];
  thumbnail?: string;
}

interface ObjectPlacerProps {
  /** Current scene background image */
  backgroundImage?: string;

  /** Canvas dimensions */
  width: number;
  height: number;

  /** Current camera settings for perspective matching */
  cameraPosition: { x: number; y: number; z: number };
  cameraTarget: { x: number; y: number; z: number };
  cameraFOV: number;

  /** Existing placements */
  placements: ObjectPlacement3D[];

  /** Called when placement changes */
  onPlacementsChange: (placements: ObjectPlacement3D[]) => void;

  /** Called when an object is selected */
  onObjectSelect?: (placementId: string | null) => void;

  /** Available 3D objects from library */
  availableObjects: Object3D[];
}

interface ObjectPlacement3D {
  placementId: string;
  objectId: string;
  objectName: string;
  position: { x: number; y: number; z: number };
  rotation: { x: number; y: number; z: number };
  scale: { x: number; y: number; z: number };
  visible: boolean;
  depth: number;
}

/**
 * Transform mode for object manipulation
 */
type TransformMode = 'translate' | 'rotate' | 'scale';

/**
 * 3D Object Placer Component
 */
export const ObjectPlacer: React.FC<ObjectPlacerProps> = ({
  backgroundImage,
  width,
  height,
  cameraPosition,
  cameraTarget,
  cameraFOV,
  placements,
  onPlacementsChange,
  onObjectSelect,
  availableObjects,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const { toast } = useToast();

  // State
  const [selectedPlacementId, setSelectedPlacementId] = useState<string | null>(null);
  const [transformMode, setTransformMode] = useState<TransformMode>('translate');
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [showObjectLibrary, setShowObjectLibrary] = useState(false);

  // Calculate 2D screen positions from 3D placements
  const screenPlacements = useMemo(() => {
    return placements.map(placement => ({
      ...placement,
      screenPosition: calculateScreenPosition(
        placement.position,
        cameraPosition,
        cameraTarget,
        cameraFOV,
        width,
        height
      ),
      scaleFactor: calculateScaleFactor(
        placement.position,
        cameraPosition,
        cameraFOV,
        height
      ),
    }));
  }, [placements, cameraPosition, cameraTarget, cameraFOV, width, height]);

  // Handle mouse down on placement
  const handlePlacementMouseDown = useCallback((e: React.MouseEvent, placementId: string) => {
    e.stopPropagation();
    setSelectedPlacementId(placementId);
    setIsDragging(true);
    setDragStart({ x: e.clientX, y: e.clientY });
    onObjectSelect?.(placementId);
  }, [onObjectSelect]);

  // Handle mouse move for dragging
  const handleMouseMove = useCallback((e: React.MouseEvent) => {
    if (!isDragging || !selectedPlacementId) return;

    const deltaX = e.clientX - dragStart.x;
    const deltaY = e.clientY - dragStart.y;

    // Update placement based on transform mode
    onPlacementsChange(placements.map(p => {
      if (p.placementId !== selectedPlacementId) return p;

      if (transformMode === 'translate') {
        // Convert screen movement to 3D position change
        const position = { ...p.position };

        // X movement affects X and Z (based on camera angle)
        position.x += deltaX * 0.01;

        // Y movement affects Y (up/down)
        position.y -= deltaY * 0.01;

        // Recalculate Z based on depth sorting
        position.z = calculateDepthFromPosition(position, cameraPosition);

        return { ...p, position, depth: position.z };
      } else if (transformMode === 'rotate') {
        // Rotate based on drag direction
        return {
          ...p,
          rotation: {
            x: p.rotation.x + deltaY * 0.5,
            y: p.rotation.y + deltaX * 0.5,
            z: p.rotation.z,
          },
        };
      } else if (transformMode === 'scale') {
        // Scale based on drag distance
        const scaleDelta = 1 + (deltaY * 0.01);
        return {
          ...p,
          scale: {
            x: p.scale.x * scaleDelta,
            y: p.scale.y * scaleDelta,
            z: p.scale.z * scaleDelta,
          },
        };
      }
      return p;
    }));

    setDragStart({ x: e.clientX, y: e.clientY });
  }, [isDragging, selectedPlacementId, dragStart, placements, transformMode, cameraPosition, onPlacementsChange]);

  // Handle mouse up
  const handleMouseUp = useCallback(() => {
    setIsDragging(false);
  }, []);

  // Handle canvas click (deselect)
  const handleCanvasClick = useCallback(() => {
    setSelectedPlacementId(null);
    onObjectSelect?.(null);
  }, [onObjectSelect]);

  // Add new object from library
  const handleAddObject = useCallback((object: Object3D) => {
    const newPlacement: ObjectPlacement3D = {
      placementId: `placement_${Date.now()}`,
      objectId: object.id,
      objectName: object.name,
      position: { x: 0, y: 0, z: 2 }, // Place in front of camera
      rotation: { x: 0, y: 0, z: 0 },
      scale: { x: 1, y: 1, z: 1 },
      visible: true,
      depth: 2,
    };

    onPlacementsChange([...placements, newPlacement]);
    setShowObjectLibrary(false);

    toast({
      title: 'Object Added',
      description: `Added ${object.name} to scene`,
      variant: 'success',
    });
  }, [placements, onPlacementsChange, toast]);

  // Remove selected object
  const handleRemoveObject = useCallback(() => {
    if (!selectedPlacementId) return;

    onPlacementsChange(placements.filter(p => p.placementId !== selectedPlacementId));
    setSelectedPlacementId(null);

    toast({
      title: 'Object Removed',
      variant: 'info',
    });
  }, [selectedPlacementId, placements, onPlacementsChange, toast]);

  // Update placement properties
  const updatePlacement = useCallback((updates: Partial<ObjectPlacement3D>) => {
    if (!selectedPlacementId) return;

    onPlacementsChange(placements.map(p =>
      p.placementId === selectedPlacementId
        ? { ...p, ...updates }
        : p
    ));
  }, [selectedPlacementId, placements, onPlacementsChange]);

  // Get selected placement
  const selectedPlacement = placements.find(p => p.placementId === selectedPlacementId);

  return (
    <div className="object-placer">
      {/* Canvas / Preview Area */}
      <div
        ref={containerRef}
        className="object-placer-canvas"
        style={{ width, height }}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onClick={handleCanvasClick}
      >
        {/* Background Image */}
        {backgroundImage && (
          <img
            src={backgroundImage}
            alt="Scene background"
            className="scene-background"
            style={{ width, height }}
          />
        )}

        {/* Placed Objects */}
        {screenPlacements.map(placement => (
          <ObjectPreview
            key={placement.placementId}
            placement={placement}
            isSelected={placement.placementId === selectedPlacementId}
            onMouseDown={(e) => handlePlacementMouseDown(e, placement.placementId)}
          />
        ))}

        {/* Grid Overlay */}
        <div className="grid-overlay" />
      </div>

      {/* Toolbar */}
      <div className="object-placer-toolbar">
        {/* Transform Mode Selector */}
        <div className="transform-mode-selector">
          <button
            className={`transform-btn ${transformMode === 'translate' ? 'active' : ''}`}
            onClick={() => setTransformMode('translate')}
            title="Move (G)"
          >
            <MoveIcon />
          </button>
          <button
            className={`transform-btn ${transformMode === 'rotate' ? 'active' : ''}`}
            onClick={() => setTransformMode('rotate')}
            title="Rotate (R)"
          >
            <RotateIcon />
          </button>
          <button
            className={`transform-btn ${transformMode === 'scale' ? 'active' : ''}`}
            onClick={() => setTransformMode('scale')}
            title="Scale (S)"
          >
            <ScaleIcon />
          </button>
        </div>

        {/* Add Object Button */}
        <button
          className="add-object-btn"
          onClick={() => setShowObjectLibrary(true)}
          title="Add 3D Object"
        >
          <PlusIcon />
          <span>Add Object</span>
        </button>

        {/* Selected Object Info */}
        {selectedPlacement && (
          <div className="selected-info">
            <span className="object-name">{selectedPlacement.objectName}</span>
            <span className="position-display">
              ({selectedPlacement.position.x.toFixed(1)}, {selectedPlacement.position.y.toFixed(1)}, {selectedPlacement.position.z.toFixed(1)})
            </span>
          </div>
        )}

        {/* Delete Button */}
        {selectedPlacement && (
          <button
            className="delete-btn"
            onClick={handleRemoveObject}
            title="Remove Object"
          >
            <TrashIcon />
          </button>
        )}
      </div>

      {/* Object Library Panel */}
      {showObjectLibrary && (
        <ObjectLibraryPanel
          objects={availableObjects}
          onSelect={handleAddObject}
          onClose={() => setShowObjectLibrary(false)}
        />
      )}

      {/* Properties Panel for Selected Object */}
      {selectedPlacement && (
        <ObjectPropertiesPanel
          placement={selectedPlacement}
          onChange={updatePlacement}
        />
      )}
    </div>
  );
};

/**
 * Object preview rendered on canvas
 */
const ObjectPreview: React.FC<{
  placement: ObjectPlacement3D & { screenPosition: { x: number; y: number }; scaleFactor: number };
  isSelected: boolean;
  onMouseDown: (e: React.MouseEvent) => void;
}> = ({ placement, isSelected, onMouseDown }) => {
  const size = 60 * placement.scaleFactor;

  return (
    <div
      className={`object-preview ${isSelected ? 'selected' : ''}`}
      style={{
        left: placement.screenPosition.x - size / 2,
        top: placement.screenPosition.y - size / 2,
        width: size,
        height: size,
      }}
      onMouseDown={onMouseDown}
    >
