            <span className="handle handle-tl" />
            <span className="handle handle-tr" />
            <span className="handle handle-bl" />
            <span className="handle handle-br" />
          </div>
        )}

        {/* Object icon/placeholder */}
        <span className="object-icon">­ƒôª</span>

