                    </List>
                  </CardContent>
                </Card>
              </Grid>

              {/* Digital Human Detection */}
              <Grid size={{ xs: 12, md: 4 }}>
                <Card>
                  <CardContent>
                    <Typography variant="subtitle1" fontWeight="bold" gutterBottom>
                      <Person sx={{ verticalAlign: 'middle', mr: 0.5 }} />
