                          border: 1,
                          borderColor: selectedShots.includes(shot.id) ? 'primary.main' : 'divider',
                          borderRadius: 1,
                          mb: 1,
                          bgcolor: selectedShots.includes(shot.id) ? 'action.selected' : 'transparent',
                        }}
