                        <ListItemIcon>
                          <Checkbox
                            edge="start"
                            checked={selectedShots.includes(shot.id)}
                            tabIndex={-1}
                          />
                        </ListItemIcon>
                        <ListItemText
                          primary={`Shot ${index + 1}: ${formatDuration(shot.startTime)} - ${formatDuration(shot.endTime)}`}
                          secondary={
                            <Box component="span">
                              <Chip 
                                size="small" 
                                label={getCompositionLabel(shot.composition.framing)}
                                sx={{ mr: 1, mt: 0.5 }}
                              />
