                  </Button>
                  <Button 
                    variant="contained" 
                    onClick={() => setTabValue(2)}
                    disabled={selectedShots.length === 0}
                  >
                    Continue to Settings
                  </Button>
                </Box>
              </Grid>
            </Grid>
          )}
        </TabPanel>

        {/* Tab 3: Settings */}
        <TabPanel value={tabValue} index={2}>
          {referenceVideo && (
            <Grid container spacing={3}>
              {/* Timing Settings */}
              <Grid size={{ xs: 12, md: 6 }}>
