          margin: 0;
          padding-left: 1.5rem;
          list-style: disc;
        }

        .tips-list li {
          margin-bottom: 0.5rem;
          font-size: 14px;
          color: var(--text-secondary, #666);
          line-height: 1.5;
        }

        .tips-list li:last-child {
          margin-bottom: 0;
        }

        @media (max-width: 768px) {
          .no-results {
            padding: 2rem 1rem;
          }

          .no-results-icon {
            width: 72px;
            height: 72px;
          }

          .no-results-icon :global(svg) {
            width: 36px;
            height: 36px;
          }

          .no-results h3 {
            font-size: 20px;
          }

          .search-query {
            font-size: 14px;
          }
        }
      `}</style>
    </motion.div>
  );
};

