/**
 * Service Status Banner Component
 * 
 * Displays connection status for Ollama (LLM) and ComfyUI services.
 * Provides clear feedback and quick configuration options when services are unavailable.
 * 
 * Requirements: Service availability check for wizards that require LLM/ComfyUI
 */

import React, { useState, useEffect } from 'react';
import { useServiceStatus, ServiceStatus } from '@/hooks/useServiceStatus';
import { AlertCircle, CheckCircle, Settings, Loader2, ExternalLink, RefreshCw } from 'lucide-react';

export interface ServiceRequirement {
  service: 'ollama' | 'comfyui';
  required: boolean;
  description: string;
  configUrl?: string;
}

export interface ServiceStatusBannerProps {
  requirements: ServiceRequirement[];
  onConfigure?: (service: 'ollama' | 'comfyui') => void;
  onRetry?: () => void;
  showDetails?: boolean;
  variant?: 'banner' | 'card' | 'inline';
}

// Map service names to display names
const SERVICE_NAMES: Record<string, string> = {
  ollama: 'Ollama (LLM)',
  comfyui: 'ComfyUI',
};

// Map service names to setup instructions
const SERVICE_SETUP_INSTRUCTIONS: Record<string, string> = {
  ollama: 'Download Ollama from ollama.com and run: ollama serve',
  comfyui: 'Ensure ComfyUI is running and the server URL is configured in settings.',
};

/**
 * Get status icon and color based on service status
 */
function getStatusConfig(status: ServiceStatus): {
  icon: React.ReactNode;
  color: string;
  text: string;
} {
  switch (status) {
    case 'connected':
      return {
        icon: <CheckCircle className="w-4 h-4" />,
        color: 'text-green-500',
        text: 'Connected',
      };
    case 'disconnected':
      return {
        icon: <AlertCircle className="w-4 h-4" />,
        color: 'text-red-500',
        text: 'Not connected',
      };
    case 'checking':
      return {
        icon: <Loader2 className="w-4 h-4 animate-spin" />,
        color: 'text-yellow-500',
        text: 'Checking...',
      };
  }
}

/**
 * Service status badge component
 */
interface ServiceBadgeProps {
  service: string;
  status: ServiceStatus;
  required: boolean;
  onConfigure?: () => void;
  showDetails?: boolean;
}

function ServiceBadge({
  service,
  status,
  required,
  onConfigure,
  showDetails,
}: ServiceBadgeProps) {
  const { icon, color, text } = getStatusConfig(status);
  const isAvailable = status === 'connected';
  const showWarning = status === 'disconnected' && required;

  return (
    <div
      className={`
        flex items-center gap-2 px-3 py-2 rounded-lg border
        ${showWarning 
          ? 'border-red-200 bg-red-50' 
          : 'border-gray-200 bg-white'
        }
      `}
    >
      <span className={color}>{icon}</span>
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium text-gray-900">
          {SERVICE_NAMES[service]}
        </p>
        {showDetails && (
          <p className={`text-xs ${color}`}>{text}</p>
        )}
      </div>
      {showWarning && onConfigure && (
        <button
          onClick={onConfigure}
          className="flex items-center gap-1 px-2 py-1 text-xs font-medium
                   text-red-700 bg-red-100 rounded hover:bg-red-200
                   transition-colors"
        >
          <Settings className="w-3 h-3" />
          Configure
        </button>
      )}
    </div>
  );
}

/**
 * Service Status Banner Component
 */
export function ServiceStatusBanner({
  requirements,
  onConfigure,
  onRetry,
  showDetails = true,
  variant = 'banner',
}: ServiceStatusBannerProps) {
  const serviceStatus = useServiceStatus();
  const [isExpanded, setIsExpanded] = useState(false);
  
  // Check all requirements
  const allConnected = requirements.every(req => 
    serviceStatus[req.service] === 'connected'
  );
  
  const missingRequired = requirements.filter(req => 
    req.required && serviceStatus[req.service] !== 'connected'
  );
  
  const isChecking = Object.values(serviceStatus).some(s => s === 'checking');

  // Auto-expand if there are missing required services
  useEffect(() => {
    if (missingRequired.length > 0) {
      setIsExpanded(true);
    }
  }, [missingRequired.length]);

  // Don't show anything if all services are connected and not checking
  if (allConnected && !isChecking) {
    return null;
  }

  const variantStyles = {
    banner: 'fixed bottom-4 right-4 z-50 max-w-md shadow-lg',
    card: 'border rounded-xl p-4',
    inline: 'inline-flex',
  };

  const content = (
    <div 
      className={`
        ${variantStyles[variant]}
        ${variant === 'banner' ? 'bg-white rounded-xl' : ''}
      `}
    >
      {/* Header */}
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          {isChecking ? (
            <Loader2 className="w-5 h-5 animate-spin text-blue-500" />
          ) : missingRequired.length > 0 ? (
            <AlertCircle className="w-5 h-5 text-amber-500" />
          ) : (
            <CheckCircle className="w-5 h-5 text-green-500" />
          )}
          
          <div>
            <p className="text-sm font-medium text-gray-900">
              {isChecking 
                ? 'Checking services...' 
                : missingRequired.length > 0
                  ? `${missingRequired.length} service(s) unavailable`
                  : 'All services connected'
              }
            </p>
            {variant !== 'inline' && (
              <p className="text-xs text-gray-500">
                {missingRequired.length > 0
                  ? 'Some features may be limited'
                  : 'Ready to use AI-powered features'
                }
              </p>
            )}
          </div>
        </div>

        {/* Actions */}
        <div className="flex items-center gap-2">
          {onRetry && (
            <button
              onClick={onRetry}
              className="p-2 text-gray-500 hover:text-gray-700 
                       hover:bg-gray-100 rounded-lg transition-colors"
              title="Retry connection check"
            >
              <RefreshCw className="w-4 h-4" />
            </button>
          )}
          
          {variant !== 'inline' && (
            <button
              onClick={() => setIsExpanded(!isExpanded)}
              className="text-sm text-blue-600 hover:text-blue-700 
                       font-medium transition-colors"
            >
              {isExpanded ? 'Hide details' : 'Show details'}
            </button>
          )}
        </div>
      </div>

      {/* Expanded details */}
      {isExpanded && variant !== 'inline' && (
        <div className="mt-4 pt-4 border-t border-gray-200">
          {/* Service badges */}
          <div className="grid gap-3">
            {requirements.map(req => (
              <ServiceBadge
                key={req.service}
                service={req.service}
                status={serviceStatus[req.service]}
                required={req.required}
                onConfigure={onConfigure ? () => onConfigure(req.service) : undefined}
                showDetails={showDetails}
              />
            ))}
          </div>

          {/* Missing services info */}
          {missingRequired.length > 0 && (
            <div className="mt-4 p-3 bg-amber-50 rounded-lg">
              <p className="text-sm font-medium text-amber-900">
                Missing required services
              </p>
              <ul className="mt-2 space-y-1">
                {missingRequired.map(req => (
                  <li key={req.service} className="text-sm text-amber-800">
                    ÔÇó {SERVICE_NAMES[req.service]}: {req.description}
                  </li>
                ))}
              </ul>
            </div>
          )}

          {/* Setup instructions link */}
          {missingRequired.length > 0 && (
            <div className="mt-4 flex items-center gap-3">
              <a
                href="https://ollama.com/download"
                target="_blank"
                rel="noopener noreferrer"
                className="flex items-center gap-1 text-sm text-blue-600 
                         hover:text-blue-700"
              >
                <ExternalLink className="w-3 h-3" />
                Download Ollama
              </a>
              <span className="text-gray-300">|</span>
              <a
                href="https://github.com/comfyanonymous/ComfyUI"
                target="_blank"
                rel="noopener noreferrer"
                className="flex items-center gap-1 text-sm text-blue-600 
                         hover:text-blue-700"
              >
                <ExternalLink className="w-3 h-3" />
                Get ComfyUI
              </a>
            </div>
          )}
        </div>
      )}

      {/* Inline variant: simple indicator */}
      {variant === 'inline' && missingRequired.length > 0 && (
        <div className="mt-2 text-xs text-amber-600">
          {missingRequired.map(r => SERVICE_NAMES[r.service]).join(', ')} unavailable
        </div>
      )}
    </div>
  );

  // For banner variant, add backdrop
  if (variant === 'banner') {
    return (
      <>
        {content}
      </>
    );
  }

  return content;
}

/**
 * Wizard-specific service requirements helper
 */
export function getWizardServiceRequirements(wizardId: string): ServiceRequirement[] {
  const requirementsMap: Record<string, ServiceRequirement[]> = {
    'project-init': [
      { service: 'ollama', required: false, description: 'For AI story generation' },
    ],
    'world-building': [
      { service: 'ollama', required: true, description: 'Required for world generation' },
    ],
    'character-creation': [
      { service: 'ollama', required: true, description: 'Required for character generation' },
      { service: 'comfyui', required: false, description: 'For image tile generation' },
    ],
    'storyteller-wizard': [
      { service: 'ollama', required: true, description: 'Required for story generation' },
    ],
    'shot-planning': [
      { service: 'ollama', required: false, description: 'For shot suggestions' },
    ],
    'shot-reference-wizard': [
      { service: 'comfyui', required: true, description: 'Required for image generation' },
    ],
    'dialogue-wizard': [
      { service: 'ollama', required: true, description: 'Required for dialogue generation' },
    ],
    'scene-generator': [
      { service: 'ollama', required: true, description: 'Required for scene generation' },
      { service: 'comfyui', required: true, description: 'Required for image generation' },
    ],
    'storyboard-creator': [
      { service: 'ollama', required: true, description: 'Required for storyboard generation' },
      { service: 'comfyui', required: true, description: 'Required for panel images' },
    ],
    'style-transfer': [
      { service: 'comfyui', required: true, description: 'Required for style transfer' },
    ],
    'marketing-wizard': [
      { service: 'ollama', required: false, description: 'For content suggestions' },
      { service: 'comfyui', required: false, description: 'For thumbnail generation' },
    ],
  };

  return requirementsMap[wizardId] || [];
}

/**
 * Component to show service status in wizard header
 */
export function WizardServiceIndicator({
  wizardId,
  onConfigure,
}: {
  wizardId: string;
  onConfigure?: (service: 'ollama' | 'comfyui') => void;
}) {
  const requirements = getWizardServiceRequirements(wizardId);
  const serviceStatus = useServiceStatus();
  
  const missingRequired = requirements.filter(req => 
    req.required && serviceStatus[req.service] !== 'connected'
  );

  if (missingRequired.length === 0) {
    return null;
  }

  return (
    <ServiceStatusBanner
      requirements={requirements}
      onConfigure={onConfigure}
      variant="inline"
    />
  );
}

/**
 * ComfyUI Servers Panel Component
 * 
 * Main panel for managing multiple ComfyUI servers
 */

import { useState, useEffect } from 'react';
import { Plus, RefreshCw, Download, Upload, AlertCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { ComfyUIServerCard } from './ComfyUIServerCard';
import { ComfyUIServerModal } from './ComfyUIServerModal';
import { getComfyUIServersService } from '@/services/comfyuiServersService';
import type { ComfyUIServer, CreateComfyUIServerInput } from '@/types/comfyuiServers';
import { useToast } from '@/hooks/use-toast';

export interface ComfyUIServersPanelProps {
  className?: string;
}

export function ComfyUIServersPanel({ className }: ComfyUIServersPanelProps) {
  const service = getComfyUIServersService();
  const { toast } = useToast();

  // State
  const [servers, setServers] = useState<ComfyUIServer[]>([]);
  const [activeServerId, setActiveServerId] = useState<string | null>(null);
  const [autoSwitch, setAutoSwitch] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingServer, setEditingServer] = useState<ComfyUIServer | null>(null);
  const [isTestingAll, setIsTestingAll] = useState(false);

  // Load servers on mount
  useEffect(() => {
    loadServers();
  }, []);

  const loadServers = () => {
    setServers(service.getAllServers());
    setActiveServerId(service.getActiveServerId());
    setAutoSwitch(service.getAutoSwitchOnFailure());
  };

  const handleAddServer = (input: CreateComfyUIServerInput) => {
    try {
      service.addServer(input);
      loadServers();
      toast({
        title: 'Server Added',
        description: `${input.name} has been added successfully.`,
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to add server. Please try again.',
        variant: 'destructive',
      });
    }
  };

  const handleEditServer = (input: CreateComfyUIServerInput) => {
    if (!editingServer) return;

    try {
      service.updateServer(editingServer.id, input);
      loadServers();
      toast({
        title: 'Server Updated',
        description: `${input.name} has been updated successfully.`,
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to update server. Please try again.',
        variant: 'destructive',
      });
    }
  };

  const handleDeleteServer = (id: string) => {
    const server = service.getServer(id);
    if (!server) return;

    if (confirm(`Are you sure you want to delete "${server.name}"?`)) {
      try {
        service.deleteServer(id);
        loadServers();
        toast({
          title: 'Server Deleted',
          description: `${server.name} has been deleted.`,
        });
      } catch (error) {
        toast({
          title: 'Error',
          description: 'Failed to delete server. Please try again.',
          variant: 'destructive',
        });
      }
    }
  };

  const handleSetActive = (id: string) => {
    try {
      service.setActiveServer(id);
      loadServers();
      const server = service.getServer(id);
      toast({
        title: 'Active Server Changed',
        description: `${server?.name} is now the active server.`,
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to set active server. Please try again.',
        variant: 'destructive',
      });
    }
  };

  const handleTestServer = async (id: string) => {
    try {
      const success = await service.testServer(id);
      loadServers();
      
      const server = service.getServer(id);
      if (success) {
        toast({
          title: 'Connection Successful',
          description: `Successfully connected to ${server?.name}.`,
        });
      } else {
        toast({
          title: 'Connection Failed',
          description: `Failed to connect to ${server?.name}.`,
          variant: 'destructive',
        });
      }
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to test connection. Please try again.',
        variant: 'destructive',
      });
    }
  };

  const handleTestAll = async () => {
    setIsTestingAll(true);
    try {
      const results = await service.testAllServers();
      loadServers();
      
      const successCount = Array.from(results.values()).filter(Boolean).length;
      toast({
        title: 'Connection Tests Complete',
        description: `${successCount} of ${results.size} servers connected successfully.`,
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to test connections. Please try again.',
        variant: 'destructive',
      });
    } finally {
      setIsTestingAll(false);
    }
  };

  const handleAutoSwitchChange = (enabled: boolean) => {
    service.setAutoSwitchOnFailure(enabled);
    setAutoSwitch(enabled);
    toast({
      title: 'Auto-Switch Updated',
      description: `Auto-switch on failure is now ${enabled ? 'enabled' : 'disabled'}.`,
    });
  };

  const handleExport = () => {
    try {
      const config = service.exportConfig();
      const blob = new Blob([config], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `comfyui-servers-${Date.now()}.json`;
      a.click();
      URL.revokeObjectURL(url);
      
      toast({
        title: 'Configuration Exported',
        description: 'Server configuration has been exported successfully.',
      });
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to export configuration.',
        variant: 'destructive',
      });
    }
  };

  const handleImport = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    
    input.onchange = async (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (!file) return;

      try {
        const text = await file.text();
        const success = service.importConfig(text);
        
        if (success) {
          loadServers();
          toast({
            title: 'Configuration Imported',
            description: 'Server configuration has been imported successfully.',
          });
        } else {
          toast({
            title: 'Import Failed',
            description: 'Invalid configuration file.',
            variant: 'destructive',
          });
        }
      } catch (error) {
        toast({
          title: 'Error',
          description: 'Failed to import configuration.',
          variant: 'destructive',
        });
      }
    };
    
    input.click();
  };

  return (
    <div className={className}>
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle>ComfyUI Servers</CardTitle>
              <CardDescription>
                Manage multiple ComfyUI server connections
              </CardDescription>
            </div>
            <div className="flex gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={handleTestAll}
                disabled={isTestingAll || servers.length === 0}
              >
                <RefreshCw className={`mr-2 h-4 w-4 ${isTestingAll ? 'animate-spin' : ''}`} />
                Test All
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={handleExport}
                disabled={servers.length === 0}
              >
                <Download className="mr-2 h-4 w-4" />
                Export
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={handleImport}
              >
                <Upload className="mr-2 h-4 w-4" />
                Import
              </Button>
              <Button onClick={() => setShowAddModal(true)}>
                <Plus className="mr-2 h-4 w-4" />
                Add Server
              </Button>
            </div>
          </div>
        </CardHeader>

        <CardContent className="space-y-4">
          {/* Auto-Switch Setting */}
          <div className="flex items-center justify-between p-4 border rounded-lg">
            <div className="space-y-0.5">
              <Label htmlFor="autoSwitch">Auto-switch on Failure</Label>
              <p className="text-sm text-muted-foreground">
                Automatically switch to another server if the active one fails
              </p>
            </div>
            <Switch
              id="autoSwitch"
              checked={autoSwitch}
              onCheckedChange={handleAutoSwitchChange}
            />
          </div>

          {/* Server List */}
          {servers.length === 0 ? (
            <Alert>
              <AlertCircle className="h-4 w-4" />
              <AlertDescription>
                No servers configured. Click "Add Server" to get started.
              </AlertDescription>
            </Alert>
          ) : (
            <div className="space-y-2">
              {servers.map((server) => (
                <ComfyUIServerCard
                  key={server.id}
                  server={server}
                  isActive={server.id === activeServerId}
                  onSetActive={() => handleSetActive(server.id)}
                  onEdit={() => setEditingServer(server)}
                  onDelete={() => handleDeleteServer(server.id)}
                  onTest={() => handleTestServer(server.id)}
                />
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Add/Edit Modal */}
      <ComfyUIServerModal
        server={editingServer}
        isOpen={showAddModal || !!editingServer}
        onClose={() => {
          setShowAddModal(false);
          setEditingServer(null);
        }}
        onSave={editingServer ? handleEditServer : handleAddServer}
      />
    </div>
  );
}

/**
 * LLM Settings Panel Component
 * 
 * Provides UI for configuring LLM integration settings including:
 * - Provider selection (OpenAI, Anthropic, Local, Custom)
 * - Model selection with info display
 * - Generation parameters (temperature, max tokens, etc.)
 * - System prompt editors
 * - Connection testing and validation
 * 
 * Validates Requirements: 3.1, 3.2, 3.6
 */

import React, { useState, useEffect } from 'react';
import { Check, AlertCircle, Loader2, Info, Eye, EyeOff, Download, Upload, Trash2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Slider } from '@/components/ui/slider';
import { Textarea } from '@/components/ui/textarea';
import { Separator } from '@/components/ui/separator';
import { Badge } from '@/components/ui/badge';
import { Switch } from '@/components/ui/switch';
import { cn } from '@/lib/utils';
import type {
  LLMConfig,
  LLMProvider,
} from '@/services/llmService';
import { getAvailableProviders, getDefaultSystemPrompts } from '@/services/llmService';
import {
  saveLLMSettings,
  loadLLMSettings,
  deleteLLMSettings,
  exportSettings,
  importSettings,
  isCryptoAvailable,
  getLastValidationTime,
} from '@/utils/secureStorage';
import { LocalModelSelector } from './LocalModelSelector';

// ============================================================================
// Types
// ============================================================================

export interface LLMSettingsPanelProps {
  currentConfig?: Partial<LLMConfig>;
  onSave: (config: LLMConfig) => void | Promise<void>;
  onCancel?: () => void;
  onTestConnection?: (config: Partial<LLMConfig>) => Promise<boolean>;
  className?: string;
}

interface ConnectionStatus {
  state: 'idle' | 'testing' | 'success' | 'error';
  message?: string;
}

// ============================================================================
// Validation Helpers
// ============================================================================

/**
 * Validate API key format based on provider
 */
function validateApiKeyFormat(provider: LLMProvider, apiKey: string): string | null {
  if (!apiKey) {
    return 'API key is required';
  }

  switch (provider) {
    case 'openai':
      if (!apiKey.startsWith('sk-')) {
        return 'OpenAI API keys must start with "sk-"';
      }
      if (apiKey.length < 20) {
        return 'OpenAI API key appears to be too short';
      }
      break;
    case 'anthropic':
      if (!apiKey.startsWith('sk-ant-')) {
        return 'Anthropic API keys must start with "sk-ant-"';
      }
      if (apiKey.length < 20) {
        return 'Anthropic API key appears to be too short';
      }
      break;
  }

  return null;
}

/**
 * Validate endpoint URL format
 */
function validateEndpointFormat(endpoint: string): string | null {
  if (!endpoint) {
    return 'API endpoint is required';
  }

  try {
    const url = new URL(endpoint);
    if (!['http:', 'https:'].includes(url.protocol)) {
      return 'Endpoint must use HTTP or HTTPS protocol';
    }
  } catch {
    return 'Invalid URL format. Please enter a valid endpoint URL.';
  }

  return null;
}

/**
 * Get provider-specific connection error message
 */
function getConnectionErrorMessage(provider: LLMProvider): string {
  switch (provider) {
    case 'openai':
      return 'Connection failed. Please verify your OpenAI API key has the correct permissions and your account has sufficient credits.';
    case 'anthropic':
      return 'Connection failed. Please verify your Anthropic API key is valid and has access to the selected model.';
    case 'local':
      return 'Connection failed. Please ensure your local LLM server is running and accessible at the specified endpoint.';
    case 'custom':
      return 'Connection failed. Please verify the custom endpoint is accessible and the API key (if required) is correct.';
    default:
      return 'Connection failed. Please check your settings and try again.';
  }
}

/**
 * Get provider-specific connection error guidance
 */
function getConnectionErrorGuidance(provider: LLMProvider): string {
  switch (provider) {
    case 'openai':
      return 'Check: 1) API key is correct, 2) Account has credits, 3) Key has proper permissions.';
    case 'anthropic':
      return 'Check: 1) API key is correct, 2) Model access is enabled, 3) Account is active.';
    case 'local':
      return 'Check: 1) Server is running, 2) Endpoint URL is correct, 3) No firewall blocking.';
    case 'custom':
      return 'Check: 1) Endpoint is accessible, 2) Authentication is correct, 3) API is compatible.';
    default:
      return 'Please verify your configuration and try again.';
  }
}

// ============================================================================
// LLM Settings Panel Component
// ============================================================================

export function LLMSettingsPanel({
  currentConfig,
  onSave,
  onCancel,
  onTestConnection,
  className,
}: LLMSettingsPanelProps) {
  // ============================================================================
  // State
  // ============================================================================

  const [provider, setProvider] = useState<LLMProvider>(currentConfig?.provider || 'openai');
  const [apiKey, setApiKey] = useState(currentConfig?.apiKey || '');
  const [apiEndpoint, setApiEndpoint] = useState(currentConfig?.apiEndpoint || '');
  const [model, setModel] = useState(currentConfig?.model || '');
  const [temperature, setTemperature] = useState(currentConfig?.parameters?.temperature ?? 0.7);
  const [maxTokens, setMaxTokens] = useState(currentConfig?.parameters?.maxTokens ?? 2000);
  const [topP, setTopP] = useState(currentConfig?.parameters?.topP ?? 1.0);
  const [frequencyPenalty, setFrequencyPenalty] = useState(currentConfig?.parameters?.frequencyPenalty ?? 0);
  const [presencePenalty, setPresencePenalty] = useState(currentConfig?.parameters?.presencePenalty ?? 0);
  const [timeout, setTimeout] = useState(currentConfig?.timeout ?? 30000);
  const [retryAttempts, setRetryAttempts] = useState(currentConfig?.retryAttempts ?? 3);
  const [streamingEnabled, setStreamingEnabled] = useState(currentConfig?.streamingEnabled ?? true);

  // New creativity and vectorial enhancement parameters
  const [creativityMode, setCreativityMode] = useState(currentConfig?.parameters?.creativityMode || 'balanced');
  const [jokesEnabled, setJokesEnabled] = useState(currentConfig?.parameters?.jokesEnabled || false);
  const [wordGamesEnabled, setWordGamesEnabled] = useState(currentConfig?.parameters?.wordGamesEnabled || false);
  const [probabilityFramingEnabled, setProbabilityFramingEnabled] = useState(currentConfig?.parameters?.probabilityFramingEnabled || false);
  const [vectorialOptimization, setVectorialOptimization] = useState(currentConfig?.parameters?.vectorialOptimization || 'standard');
  const [embeddingModel, setEmbeddingModel] = useState(currentConfig?.parameters?.embeddingModel || 'default');
  const [similarityThreshold, setSimilarityThreshold] = useState(currentConfig?.parameters?.similarityThreshold || 0.7);
  
  const defaultPrompts = getDefaultSystemPrompts();
  const [worldPrompt, setWorldPrompt] = useState(
    currentConfig?.systemPrompts?.worldGeneration || defaultPrompts.worldGeneration
  );
  const [characterPrompt, setCharacterPrompt] = useState(
    currentConfig?.systemPrompts?.characterGeneration || defaultPrompts.characterGeneration
  );
  const [dialoguePrompt, setDialoguePrompt] = useState(
    currentConfig?.systemPrompts?.dialogueGeneration || defaultPrompts.dialogueGeneration
  );

  const [showApiKey, setShowApiKey] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>({ state: 'idle' });
  const [isSaving, setIsSaving] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [cryptoAvailable, setCryptoAvailable] = useState(true);
  const [lastValidated, setLastValidated] = useState<Date | null>(null);

  const providers = getAvailableProviders();
  const currentProviderInfo = providers.find(p => p.id === provider);
  const currentModelInfo = currentProviderInfo?.models.find(m => m.id === model);

  // ============================================================================
  // Effects
  // ============================================================================

  // Load settings on mount
  useEffect(() => {
    const loadStoredSettings = async () => {
      setIsLoading(true);
      
      // Check if Web Crypto API is available
      if (!isCryptoAvailable()) {
        setCryptoAvailable(false);
        console.warn('Web Crypto API not available. Settings encryption disabled.');
      }

      try {
        // Load settings from secure storage
        const storedConfig = await loadLLMSettings();
        
        if (storedConfig) {
          // Populate form with stored settings
          setProvider(storedConfig.provider);
          setApiKey(storedConfig.apiKey);
          
          // Use stored endpoint or fall back to provider's default
          let endpoint = storedConfig.apiEndpoint || '';
          if (!endpoint && (storedConfig.provider === 'local' || storedConfig.provider === 'custom')) {
            const providerInfo = providers.find(p => p.id === storedConfig.provider);
            endpoint = providerInfo?.defaultEndpoint || '';
          }
          setApiEndpoint(endpoint);
          
          setModel(storedConfig.model);
          setTemperature(storedConfig.parameters.temperature);
          setMaxTokens(storedConfig.parameters.maxTokens);
          setTopP(storedConfig.parameters.topP);
          setFrequencyPenalty(storedConfig.parameters.frequencyPenalty);
          setPresencePenalty(storedConfig.parameters.presencePenalty);
          setTimeout(storedConfig.timeout);
          setRetryAttempts(storedConfig.retryAttempts);
          setStreamingEnabled(storedConfig.streamingEnabled);
          
          // Safely access systemPrompts with fallback to defaults
          if (storedConfig.systemPrompts) {
            setWorldPrompt(storedConfig.systemPrompts.worldGeneration || defaultPrompts.worldGeneration);
            setCharacterPrompt(storedConfig.systemPrompts.characterGeneration || defaultPrompts.characterGeneration);
            setDialoguePrompt(storedConfig.systemPrompts.dialogueGeneration || defaultPrompts.dialogueGeneration);
          } else {
            // Use defaults if systemPrompts is missing
            setWorldPrompt(defaultPrompts.worldGeneration);
            setCharacterPrompt(defaultPrompts.characterGeneration);
            setDialoguePrompt(defaultPrompts.dialogueGeneration);
          }

          // Set last validation time
          const lastValidation = getLastValidationTime();
          setLastValidated(lastValidation);
        } else if (currentConfig) {
          // Fall back to currentConfig prop if no stored settings
          // (This maintains backward compatibility)
        }
      } catch (error) {
        console.error('Failed to load stored settings:', error);
      } finally {
        setIsLoading(false);
      }
    };

    loadStoredSettings();
  }, []); // Only run on mount

  // Update model when provider changes
  useEffect(() => {
    const providerInfo = providers.find(p => p.id === provider);
    if (providerInfo && providerInfo.models.length > 0) {
      // Set first model as default if current model is not available
      const modelExists = providerInfo.models.some(m => m.id === model);
      if (!modelExists) {
        setModel(providerInfo.models[0].id);
      }
    }
  }, [provider, providers, model]);

  // Update endpoint when provider changes
  useEffect(() => {
    const providerInfo = providers.find(p => p.id === provider);
    if (providerInfo && !apiEndpoint) {
      setApiEndpoint(providerInfo.defaultEndpoint);
    }
  }, [provider, providers, apiEndpoint]);

  // ============================================================================
  // Handlers
  // ============================================================================

  const validateCredentials = (): string | null => {
    // Validate provider-specific requirements
    if (currentProviderInfo?.requiresApiKey) {
      const apiKeyError = validateApiKeyFormat(provider, apiKey);
      if (apiKeyError) {
        return apiKeyError;
      }
    }

    // Validate endpoint for local/custom providers
    if (provider === 'local' || provider === 'custom') {
      const endpointError = validateEndpointFormat(apiEndpoint);
      if (endpointError) {
        return endpointError;
      }
    }

    // Validate model selection
    if (!model) {
      return 'Please select a model';
    }

    // Validate parameters are within valid ranges
    if (temperature < 0 || temperature > 2) {
      return 'Temperature must be between 0 and 2';
    }

    if (maxTokens < 1) {
      return 'Max tokens must be at least 1';
    }

    if (currentModelInfo && maxTokens > currentModelInfo.contextWindow) {
      return `Max tokens cannot exceed model limit of ${currentModelInfo.contextWindow.toLocaleString()}`;
    }

    if (topP < 0 || topP > 1) {
      return 'Top P must be between 0 and 1';
    }

    if (frequencyPenalty < -2 || frequencyPenalty > 2) {
      return 'Frequency penalty must be between -2 and 2';
    }

    if (presencePenalty < -2 || presencePenalty > 2) {
      return 'Presence penalty must be between -2 and 2';
    }

    if (timeout < 1000) {
      return 'Timeout must be at least 1000ms (1 second)';
    }

    if (retryAttempts < 0 || retryAttempts > 10) {
      return 'Retry attempts must be between 0 and 10';
    }

    return null;
  };

  const handleTestConnection = async () => {
    if (!onTestConnection) return;

    // Validate before testing
    const validationError = validateCredentials();
    if (validationError) {
      setConnectionStatus({
        state: 'error',
        message: validationError,
      });
      return;
    }

    setConnectionStatus({ state: 'testing', message: 'Testing connection...' });

    try {
      const config: Partial<LLMConfig> = {
        provider,
        apiKey,
        apiEndpoint: (provider === 'local' || provider === 'custom') ? apiEndpoint : undefined,
        model,
      };

      const success = await onTestConnection(config);

      if (success) {
        setConnectionStatus({
          state: 'success',
          message: 'Connection successful! API key is valid and the model is accessible.',
        });
      } else {
        setConnectionStatus({
          state: 'error',
          message: getConnectionErrorMessage(provider),
        });
      }
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Connection test failed';
      setConnectionStatus({
        state: 'error',
        message: `${errorMessage}. ${getConnectionErrorGuidance(provider)}`,
      });
    }
  };

  const handleSave = async () => {
    // Validate before saving
    const validationError = validateCredentials();
    if (validationError) {
      setConnectionStatus({
        state: 'error',
        message: validationError,
      });
      return;
    }

    // Validate connection if handler is provided
    if (onTestConnection && connectionStatus.state !== 'success') {
      setConnectionStatus({
        state: 'error',
        message: 'Please test the connection before saving.',
      });
      return;
    }

    setIsSaving(true);

    try {
      const config: LLMConfig = {
        provider,
        apiKey,
        apiEndpoint: (provider === 'local' || provider === 'custom') ? apiEndpoint : undefined,
        model,
        parameters: {
          temperature,
          maxTokens,
          topP,
          frequencyPenalty,
          presencePenalty,
          creativityMode,
          jokesEnabled,
          wordGamesEnabled,
          probabilityFramingEnabled,
          vectorialOptimization,
          embeddingModel,
          similarityThreshold,
        },
        systemPrompts: {
          worldGeneration: worldPrompt,
          characterGeneration: characterPrompt,
          dialogueGeneration: dialoguePrompt,
        },
        timeout,
        retryAttempts,
        streamingEnabled,
      };

      // Save to secure storage with encryption
      if (cryptoAvailable) {
        await saveLLMSettings(config);
        setLastValidated(new Date());
      }

      // Also call the onSave callback for backward compatibility
      await onSave(config);

      // Show success message
      setConnectionStatus({
        state: 'success',
        message: 'Settings saved successfully with encrypted credentials.',
      });
    } catch (error) {
      setConnectionStatus({
        state: 'error',
        message: error instanceof Error ? error.message : 'Failed to save settings',
      });
    } finally {
      setIsSaving(false);
    }
  };

  const handleResetPrompts = () => {
    const defaults = getDefaultSystemPrompts();
    setWorldPrompt(defaults.worldGeneration);
    setCharacterPrompt(defaults.characterGeneration);
    setDialoguePrompt(defaults.dialogueGeneration);
  };

  const handleExportSettings = () => {
    try {
      const exportData = exportSettings();
      
      // Create download link
      const blob = new Blob([exportData], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `storycore-settings-${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      setConnectionStatus({
        state: 'success',
        message: 'Settings exported successfully (credentials excluded for security).',
      });
    } catch (error) {
      setConnectionStatus({
        state: 'error',
        message: error instanceof Error ? error.message : 'Failed to export settings',
      });
    }
  };

  const handleImportSettings = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'application/json';
    
    input.onchange = async (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (!file) return;

      try {
        const text = await file.text();
        const success = importSettings(text);

        if (success) {
          // Reload settings
          const storedConfig = await loadLLMSettings();
          if (storedConfig) {
            setProvider(storedConfig.provider);
            setModel(storedConfig.model);
            setTemperature(storedConfig.parameters.temperature);
            setMaxTokens(storedConfig.parameters.maxTokens);
            setTopP(storedConfig.parameters.topP);
            setFrequencyPenalty(storedConfig.parameters.frequencyPenalty);
            setPresencePenalty(storedConfig.parameters.presencePenalty);
            setTimeout(storedConfig.timeout);
            setRetryAttempts(storedConfig.retryAttempts);
            setStreamingEnabled(storedConfig.streamingEnabled);
            
            // Safely access systemPrompts with fallback to defaults
            const defaults = getDefaultSystemPrompts();
            if (storedConfig.systemPrompts) {
              setWorldPrompt(storedConfig.systemPrompts.worldGeneration || defaults.worldGeneration);
              setCharacterPrompt(storedConfig.systemPrompts.characterGeneration || defaults.characterGeneration);
              setDialoguePrompt(storedConfig.systemPrompts.dialogueGeneration || defaults.dialogueGeneration);
            } else {
              setWorldPrompt(defaults.worldGeneration);
              setCharacterPrompt(defaults.characterGeneration);
              setDialoguePrompt(defaults.dialogueGeneration);
            }
          }

          setConnectionStatus({
            state: 'success',
            message: 'Settings imported successfully. Please re-enter your API key.',
          });
        } else {
          throw new Error('Invalid settings file format');
        }
      } catch (error) {
        setConnectionStatus({
          state: 'error',
          message: error instanceof Error ? error.message : 'Failed to import settings',
        });
      }
    };

    input.click();
  };

  const handleDeleteSettings = () => {
    if (!confirm('Are you sure you want to delete all saved settings? This action cannot be undone.')) {
      return;
    }

    try {
      deleteLLMSettings();
      
      // Reset form to defaults
      const defaults = getDefaultSystemPrompts();
      setProvider('openai');
      setApiKey('');
      setApiEndpoint('');
      setModel('');
      setTemperature(0.7);
      setMaxTokens(2000);
      setTopP(1.0);
      setFrequencyPenalty(0);
      setPresencePenalty(0);
      setTimeout(30000);
      setRetryAttempts(3);
      setStreamingEnabled(true);
      setWorldPrompt(defaults.worldGeneration);
      setCharacterPrompt(defaults.characterGeneration);
      setDialoguePrompt(defaults.dialogueGeneration);
      setConnectionStatus({ state: 'idle' });
      setLastValidated(null);

      setConnectionStatus({
        state: 'success',
        message: 'All settings deleted successfully.',
      });
    } catch (error) {
      setConnectionStatus({
        state: 'error',
        message: error instanceof Error ? error.message : 'Failed to delete settings',
      });
    }
  };

  const isFormValid = () => {
    if (!provider || !model) return false;
    if (currentProviderInfo?.requiresApiKey && !apiKey) return false;
    if ((provider === 'local' || provider === 'custom') && !apiEndpoint) return false;
    return true;
  };

  // ============================================================================
  // Render
  // ============================================================================

  if (isLoading) {
    return (
      <div className={cn('flex items-center justify-center p-8', className)}>
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className={cn('space-y-6', className)}>
      {/* Crypto Warning */}
      {!cryptoAvailable && (
        <div className="flex items-start gap-2 p-3 rounded-lg text-sm bg-amber-50 text-amber-800 border border-amber-200 dark:bg-amber-950 dark:text-amber-200 dark:border-amber-800">
          <AlertCircle className="h-4 w-4 mt-0.5 flex-shrink-0" />
          <div>
            <p className="font-medium">Encryption unavailable</p>
            <p className="text-xs mt-1 opacity-90">
              Web Crypto API is not available in your browser. Credentials will be stored without encryption.
            </p>
          </div>
        </div>
      )}

      {/* Last Validated Info */}
      {lastValidated && (
        <div className="flex items-center gap-2 text-xs text-muted-foreground">
          <Check className="h-3 w-3 text-green-600" />
          <span>Last validated: {lastValidated.toLocaleString()}</span>
        </div>
      )}

      {/* Provider Selection */}
      <Card>
        <CardHeader>
          <CardTitle>Provider Selection</CardTitle>
          <CardDescription>
            Choose your LLM provider and configure authentication
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-3">
            <Label>Provider</Label>
            <RadioGroup value={provider} onValueChange={(value) => {
              const newProvider = value as LLMProvider;
              setProvider(newProvider);
              
              // Get the default endpoint for the selected provider
              const providerInfo = providers.find(p => p.id === newProvider);
              const defaultEndpoint = providerInfo?.defaultEndpoint || '';
              
              // Set the endpoint to the provider's default
              setApiEndpoint(defaultEndpoint);
              
              // Clear connection status when provider changes
              if (connectionStatus.state !== 'idle') {
                setConnectionStatus({ state: 'idle' });
              }
            }}>
              {providers.map((p) => (
                <div key={p.id} className="flex items-center space-x-2">
                  <RadioGroupItem value={p.id} id={p.id} />
                  <Label htmlFor={p.id} className="font-normal cursor-pointer">
                    {p.name}
                    {p.requiresApiKey && (
                      <Badge variant="outline" className="ml-2 text-xs">
                        Requires API Key
                      </Badge>
                    )}
                  </Label>
                </div>
              ))}
            </RadioGroup>
          </div>

          {/* Model Selection */}
          <div className="space-y-2">
            <Label htmlFor="model">Model</Label>
            {(provider === 'local' || provider === 'custom') ? (
              // Show Local Model Selector for local/custom providers
              <div className="mt-4">
                <LocalModelSelector
                  selectedModel={model}
                  onModelSelect={(modelId) => {
                    setModel(modelId);
                    // Clear connection status when model changes
                    if (connectionStatus.state !== 'idle') {
                      setConnectionStatus({ state: 'idle' });
                    }
                  }}
                  endpoint={apiEndpoint || 'http://localhost:11434'}
                />
              </div>
            ) : (
              // Show regular dropdown for cloud providers
              <>
                <Select value={model} onValueChange={setModel}>
                  <SelectTrigger id="model">
                    <SelectValue placeholder="Select a model" />
                  </SelectTrigger>
                  <SelectContent>
                    {currentProviderInfo?.models.map((m) => (
                      <SelectItem key={m.id} value={m.id}>
                        {m.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                {currentModelInfo && (
                  <div className="text-xs text-muted-foreground space-y-1 mt-2">
                    <div className="flex items-center gap-2">
                      <Info className="h-3 w-3" />
                      <span>Context: {currentModelInfo.contextWindow.toLocaleString()} tokens</span>
                    </div>
                    {currentModelInfo.costPer1kTokens && (
                      <div className="ml-5">
                        Cost: ${currentModelInfo.costPer1kTokens}/1K tokens
                      </div>
                    )}
                    <div className="ml-5">
                      Capabilities: {currentModelInfo.capabilities.join(', ')}
                    </div>
                  </div>
                )}
              </>
            )}
          </div>

          {/* API Key */}
          {currentProviderInfo?.requiresApiKey && (
            <div className="space-y-2">
              <Label htmlFor="apiKey">API Key</Label>
              <div className="relative">
                <Input
                  id="apiKey"
                  type={showApiKey ? 'text' : 'password'}
                  value={apiKey}
                  onChange={(e) => {
                    setApiKey(e.target.value);
                    // Clear connection status when API key changes
                    if (connectionStatus.state !== 'idle') {
                      setConnectionStatus({ state: 'idle' });
                    }
                  }}
                  placeholder="sk-..."
                  className={cn(
                    'pr-10',
                    apiKey && validateApiKeyFormat(provider, apiKey) && 'border-red-500 focus-visible:ring-red-500'
                  )}
                  aria-invalid={apiKey ? !!validateApiKeyFormat(provider, apiKey) : undefined}
                  aria-describedby={apiKey && validateApiKeyFormat(provider, apiKey) ? 'apiKey-error' : undefined}
                />
                <button
                  type="button"
                  onClick={() => setShowApiKey(!showApiKey)}
                  className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                  aria-label={showApiKey ? 'Hide API key' : 'Show API key'}
                >
                  {showApiKey ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                </button>
              </div>
              {apiKey && validateApiKeyFormat(provider, apiKey) && (
                <p id="apiKey-error" className="text-xs text-red-600 dark:text-red-400" role="alert">
                  {validateApiKeyFormat(provider, apiKey)}
                </p>
              )}
            </div>
          )}

          {/* Custom Endpoint */}
          {(provider === 'local' || provider === 'custom') && (
            <div className="space-y-2">
              <Label htmlFor="apiEndpoint">API Endpoint</Label>
              <Input
                id="apiEndpoint"
                type="url"
                value={apiEndpoint}
                onChange={(e) => {
                  setApiEndpoint(e.target.value);
                  // Clear connection status when endpoint changes
                  if (connectionStatus.state !== 'idle') {
                    setConnectionStatus({ state: 'idle' });
                  }
                }}
                placeholder={currentProviderInfo?.defaultEndpoint || 'http://localhost:8000'}
                className={cn(
                  apiEndpoint && validateEndpointFormat(apiEndpoint) && 'border-red-500 focus-visible:ring-red-500'
                )}
                aria-invalid={apiEndpoint ? !!validateEndpointFormat(apiEndpoint) : undefined}
                aria-describedby={apiEndpoint && validateEndpointFormat(apiEndpoint) ? 'endpoint-error' : undefined}
              />
              <p className="text-xs text-muted-foreground">
                The base URL for your {provider} LLM server (default: {currentProviderInfo?.defaultEndpoint || 'http://localhost:8000'})
              </p>
              {apiEndpoint && validateEndpointFormat(apiEndpoint) && (
                <p id="endpoint-error" className="text-xs text-red-600 dark:text-red-400" role="alert">
                  {validateEndpointFormat(apiEndpoint)}
                </p>
              )}
            </div>
          )}

          {/* Connection Test */}
          {onTestConnection && (
            <div className="space-y-2">
              <Button
                onClick={handleTestConnection}
                disabled={!isFormValid() || connectionStatus.state === 'testing'}
                variant="outline"
                className="w-full"
              >
                {connectionStatus.state === 'testing' && (
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                )}
                Test Connection
              </Button>

              {connectionStatus.state !== 'idle' && (
                <div
                  className={cn(
                    'flex items-start gap-2 p-3 rounded-lg text-sm',
