          >
            {isSaving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Save Settings
          </Button>
        </div>
      </div>
    </div>
  );
}

// ============================================================================
// Tooltip Info Component
// ============================================================================

interface TooltipInfoProps {
  content: string;
}

function TooltipInfo({ content }: TooltipInfoProps) {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div className="relative inline-block">
      <button
        type="button"
        onMouseEnter={() => setIsOpen(true)}
        onMouseLeave={() => setIsOpen(false)}
        onFocus={() => setIsOpen(true)}
        onBlur={() => setIsOpen(false)}
        className="text-muted-foreground hover:text-foreground"
        aria-label="More information"
      >
        <Info className="h-3 w-3" />
      </button>
      {isOpen && (
        <div className="absolute z-50 w-64 p-2 text-xs bg-popover text-popover-foreground border rounded-md shadow-md left-0 top-full mt-1">
          {content}
        </div>
      )}
    </div>
  );
}

/**
 * Local Model Selector Component
 * 
 * Provides UI for selecting and downloading local LLM models
 * Integrates with Ollama for model management
 */

import { useState, useEffect } from 'react';
import { Download, Check, AlertCircle, Loader2, Trash2, Info, HardDrive, Cpu, Zap } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Separator } from '@/components/ui/separator';
import { cn } from '@/lib/utils';
import {
  getLocalModelService,
  type LocalModel,
  type ModelDownloadProgress,
  LOCAL_MODELS,
} from '@/services/localModelService';

// ============================================================================
// Types
// ============================================================================

export interface LocalModelSelectorProps {
  selectedModel?: string;
  onModelSelect: (modelId: string) => void;
  endpoint?: string;
  className?: string;
}

interface ModelState {
  installed: boolean;
  downloading: boolean;
  progress: number;
  error?: string;
}

// ============================================================================
// Local Model Selector Component
// ============================================================================

export function LocalModelSelector({
  selectedModel,
  onModelSelect,
  endpoint = 'http://localhost:11434',
  className,
}: LocalModelSelectorProps) {
  // ============================================================================
  // State
  // ============================================================================

  const [isOllamaRunning, setIsOllamaRunning] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [modelStates, setModelStates] = useState<Map<string, ModelState>>(new Map());
  const [recommendedModels, setRecommendedModels] = useState<LocalModel[]>([]);
  const [selectedFamily, setSelectedFamily] = useState<LocalModel['family'] | 'all'>('all');
  const [showOnlyInstalled, setShowOnlyInstalled] = useState(false);

  const modelService = getLocalModelService(endpoint);

  // ============================================================================
  // Effects
  // ============================================================================

  useEffect(() => {
    checkOllamaStatus();
  }, [endpoint]);

  useEffect(() => {
    if (isOllamaRunning) {
      loadInstalledModels();
      loadRecommendedModels();
    }
  }, [isOllamaRunning]);

  // ============================================================================
  // Handlers
  // ============================================================================

  const checkOllamaStatus = async () => {
    setIsLoading(true);
    const running = await modelService.isOllamaRunning();
    setIsOllamaRunning(running);
    setIsLoading(false);
  };

  const loadInstalledModels = async () => {
    const installed = await modelService.getInstalledModels();
    const newStates = new Map<string, ModelState>();

    LOCAL_MODELS.forEach(model => {
      newStates.set(model.id, {
        installed: installed.includes(model.id),
        downloading: false,
        progress: 0,
      });
    });

    setModelStates(newStates);
  };

  const loadRecommendedModels = async () => {
    const recommended = await modelService.getRecommendedModels();
    setRecommendedModels(recommended);
  };

  const handleDownloadModel = async (modelId: string) => {
    try {
      // First check if Ollama is running
      const isRunning = await modelService.isOllamaRunning();
      if (!isRunning) {
        setModelStates(prev => {
          const newStates = new Map(prev);
          newStates.set(modelId, {
            installed: false,
            downloading: false,
            progress: 0,
            error: 'Ollama is not running. Please start Ollama and try again.',
          });
          return newStates;
        });
        return;
      }

      // Update state to show downloading
      setModelStates(prev => {
        const newStates = new Map(prev);
        newStates.set(modelId, {
          installed: false,
          downloading: true,
          progress: 0,
        });
        return newStates;
      });

      ;

      // Start download
      const success = await modelService.downloadModel(
        modelId,
        (progress: ModelDownloadProgress) => {
          ;
          
          setModelStates(prev => {
            const newStates = new Map(prev);
            newStates.set(modelId, {
              installed: progress.status === 'completed',
              downloading: progress.status === 'downloading',
              progress: progress.progress,
              error: progress.error,
            });
            return newStates;
          });
        }
      );

      if (success) {
        ;
        // Automatically select the downloaded model
        onModelSelect(modelId);
      } else {
        console.error(`Model ${modelId} download failed`);
      }
    } catch (error) {
      console.error('Error in handleDownloadModel:', error);
      setModelStates(prev => {
        const newStates = new Map(prev);
        newStates.set(modelId, {
          installed: false,
          downloading: false,
          progress: 0,
          error: error instanceof Error ? error.message : 'Download failed',
        });
        return newStates;
      });
    }
  };

  const handleDeleteModel = async (modelId: string) => {
    if (!confirm(`Are you sure you want to delete ${modelId}? This will free up disk space but you'll need to download it again to use it.`)) {
      return;
    }

    const success = await modelService.deleteModel(modelId);
    
    if (success) {
      setModelStates(prev => {
        const newStates = new Map(prev);
        newStates.set(modelId, {
          installed: false,
          downloading: false,
          progress: 0,
        });
        return newStates;
      });

      // If deleted model was selected, clear selection
      if (selectedModel === modelId) {
        onModelSelect('');
      }
    }
  };

  // ============================================================================
  // Render Helpers
  // ============================================================================

  const getFilteredModels = (): LocalModel[] => {
    let filtered = LOCAL_MODELS;

    // Filter by family
    if (selectedFamily !== 'all') {
      filtered = filtered.filter(m => m.family === selectedFamily);
    }

    // Filter by installed status
    if (showOnlyInstalled) {
      filtered = filtered.filter(m => modelStates.get(m.id)?.installed);
    }

    return filtered;
  };

  const renderModelCard = (model: LocalModel) => {
    const state = modelStates.get(model.id) || {
      installed: false,
      downloading: false,
      progress: 0,
    };

    const isSelected = selectedModel === model.id;
    const isRecommended = recommendedModels.some(m => m.id === model.id);

    return (
      <Card
        key={model.id}
        className={cn(
          'cursor-pointer transition-all hover:shadow-md',
          isSelected && 'ring-2 ring-primary',
          !state.installed && !state.downloading && 'opacity-75'
        )}
        onClick={() => {
          if (state.installed) {
            onModelSelect(model.id);
          }
        }}
      >
        <CardHeader className="pb-3">
          <div className="flex items-start justify-between">
            <div className="flex-1">
              <CardTitle className="text-base flex items-center gap-2">
                {model.displayName}
                {isRecommended && (
                  <Badge variant="secondary" className="text-xs">
                    <Zap className="h-3 w-3 mr-1" />
                    Recommended
                  </Badge>
                )}
                {state.installed && (
                  <Badge variant="default" className="text-xs">
                    <Check className="h-3 w-3 mr-1" />
                    Installed
                  </Badge>
                )}
              </CardTitle>
              <CardDescription className="text-xs mt-1">
                {model.description}
              </CardDescription>
            </div>
          </div>
        </CardHeader>

        <CardContent className="space-y-3">
          {/* Model Info */}
          <div className="flex flex-wrap gap-2 text-xs">
            <Badge variant="outline" className="gap-1">
              <HardDrive className="h-3 w-3" />
              {model.size}
            </Badge>
            <Badge variant="outline" className="gap-1">
              <Cpu className="h-3 w-3" />
              {model.minRAM}GB RAM min
            </Badge>
            {model.requiresGPU && (
              <Badge variant="outline" className="gap-1">
                <Zap className="h-3 w-3" />
                GPU Required
              </Badge>
            )}
          </div>

          {/* Capabilities */}
          <div className="flex flex-wrap gap-1">
            {model.capabilities.slice(0, 3).map(cap => (
              <Badge key={cap} variant="secondary" className="text-xs">
                {cap}
              </Badge>
            ))}
            {model.capabilities.length > 3 && (
              <Badge variant="secondary" className="text-xs">
                +{model.capabilities.length - 3} more
              </Badge>
            )}
          </div>

          {/* Download Progress */}
          {state.downloading && (
            <div className="space-y-2">
              <Progress value={state.progress} className="h-2" />
              <p className="text-xs text-muted-foreground">
                Downloading... {Math.round(state.progress)}%
              </p>
            </div>
          )}

          {/* Error Message */}
          {state.error && (
            <div className="flex items-start gap-2 p-2 rounded-lg text-xs bg-red-50 text-red-800 border border-red-200 dark:bg-red-950 dark:text-red-200 dark:border-red-800">
              <AlertCircle className="h-3 w-3 mt-0.5 flex-shrink-0" />
              <p>{state.error}</p>
            </div>
          )}

          {/* Actions */}
          <div className="flex gap-2">
            {!state.installed && !state.downloading && (
              <Button
                size="sm"
                variant="default"
                className="flex-1"
                onClick={(e) => {
                  e.stopPropagation();
                  handleDownloadModel(model.id);
                }}
              >
                <Download className="h-4 w-4 mr-2" />
                Download
              </Button>
            )}

            {state.installed && (
              <>
                <Button
                  size="sm"
                  variant={isSelected ? 'default' : 'outline'}
                  className="flex-1"
                  onClick={(e) => {
                    e.stopPropagation();
                    onModelSelect(model.id);
                  }}
                >
                  {isSelected ? (
                    <>
                      <Check className="h-4 w-4 mr-2" />
                      Selected
                    </>
                  ) : (
                    'Select'
                  )}
                </Button>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={(e) => {
                    e.stopPropagation();
                    handleDeleteModel(model.id);
                  }}
                >
                  <Trash2 className="h-4 w-4" />
                </Button>
              </>
            )}

            {state.downloading && (
              <Button size="sm" variant="outline" className="flex-1" disabled>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                Downloading...
              </Button>
            )}
          </div>
        </CardContent>
      </Card>
    );
  };

  // ============================================================================
  // Render
  // ============================================================================

  if (isLoading) {
    return (
      <div className={cn('flex items-center justify-center p-8', className)}>
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!isOllamaRunning) {
    return (
      <div className={cn('space-y-4', className)}>
        <div className="flex items-start gap-2 p-4 rounded-lg text-sm bg-amber-50 text-amber-800 border border-amber-200 dark:bg-amber-950 dark:text-amber-200 dark:border-amber-800">
          <AlertCircle className="h-4 w-4 mt-0.5 flex-shrink-0" />
          <div>
            <p className="font-medium">Ollama is not running</p>
            <p className="text-xs mt-1 opacity-90">
              Please start Ollama to manage local models. Visit{' '}
              <a
                href="https://ollama.ai"
                target="_blank"
                rel="noopener noreferrer"
                className="underline"
              >
                ollama.ai
              </a>{' '}
              to download and install.
            </p>
          </div>
        </div>

        <Button onClick={checkOllamaStatus} variant="outline" className="w-full">
          Retry Connection
        </Button>
      </div>
    );
  }

  const filteredModels = getFilteredModels();

  return (
    <div className={cn('space-y-4', className)}>
      {/* Info Banner */}
      <div className="flex items-start gap-2 p-3 rounded-lg text-sm bg-blue-50 text-blue-800 border border-blue-200 dark:bg-blue-950 dark:text-blue-200 dark:border-blue-800">
        <Info className="h-4 w-4 mt-0.5 flex-shrink-0" />
        <div>
          <p className="font-medium">Local Model Management</p>
          <p className="text-xs mt-1 opacity-90">
            Download and manage local LLM models. Models run on your machine without requiring API keys.
          </p>
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-wrap gap-2">
        <Button
          size="sm"
          variant={selectedFamily === 'all' ? 'default' : 'outline'}
          onClick={() => setSelectedFamily('all')}
        >
          All Models
        </Button>
        <Button
          size="sm"
          variant={selectedFamily === 'gemma' ? 'default' : 'outline'}
          onClick={() => setSelectedFamily('gemma')}
        >
          Gemma
        </Button>
        <Button
          size="sm"
          variant={selectedFamily === 'llama' ? 'default' : 'outline'}
          onClick={() => setSelectedFamily('llama')}
        >
          Llama
        </Button>
        <Button
          size="sm"
          variant={selectedFamily === 'mistral' ? 'default' : 'outline'}
          onClick={() => setSelectedFamily('mistral')}
        >
          Mistral
        </Button>
        <Button
          size="sm"
          variant={selectedFamily === 'phi' ? 'default' : 'outline'}
          onClick={() => setSelectedFamily('phi')}
        >
          Phi
        </Button>
        <Button
          size="sm"
          variant={selectedFamily === 'qwen' ? 'default' : 'outline'}
          onClick={() => setSelectedFamily('qwen')}
        >
          Qwen
        </Button>

        <Separator orientation="vertical" className="h-8" />

        <Button
          size="sm"
          variant={showOnlyInstalled ? 'default' : 'outline'}
          onClick={() => setShowOnlyInstalled(!showOnlyInstalled)}
        >
          <Check className="h-4 w-4 mr-2" />
          Installed Only
        </Button>
      </div>

      {/* Model Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {filteredModels.map(model => renderModelCard(model))}
      </div>

      {filteredModels.length === 0 && (
        <div className="text-center py-8 text-muted-foreground">
          <p>No models found matching your filters.</p>
          <Button
            variant="link"
            onClick={() => {
              setSelectedFamily('all');
              setShowOnlyInstalled(false);
            }}
          >
            Clear filters
          </Button>
        </div>
      )}
    </div>
  );
}

/**
 * Ollama Settings Component
 * 
 * Allows users to configure Ollama local LLM with automatic model selection
 */

import { useState, useEffect } from 'react';
import {
  detectSystemCapabilities,
  getModelRecommendation,
  checkOllamaStatus,
  getInstalledModels,
  isModelInstalled,
  GEMMA3_MODELS,
  DEFAULT_OLLAMA_CONFIG,
  type ModelRecommendation,
  type SystemCapabilities,
  type OllamaModelConfig,
} from '@/services/ollamaConfig';

export interface OllamaSettingsProps {
  onConfigChange?: (config: {
    endpoint: string;
    model: string;
  }) => void;
}

export function OllamaSettings({ onConfigChange }: OllamaSettingsProps) {
  const [capabilities, setCapabilities] = useState<SystemCapabilities | null>(null);
  const [recommendation, setRecommendation] = useState<ModelRecommendation | null>(null);
  const [selectedModel, setSelectedModel] = useState<string>('');
  const [endpoint, setEndpoint] = useState(DEFAULT_OLLAMA_CONFIG.endpoint);
  const [isOllamaRunning, setIsOllamaRunning] = useState(false);
  const [installedModels, setInstalledModels] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Detect system capabilities and get recommendation
  useEffect(() => {
    async function initialize() {
      setIsLoading(true);
      setError(null);

      try {
        // Detect system capabilities
        const caps = await detectSystemCapabilities();
        setCapabilities(caps);

        // Get model recommendation
        const rec = await getModelRecommendation();
        setRecommendation(rec);
        setSelectedModel(rec.model.id);

        // Check Ollama status
        const running = await checkOllamaStatus(endpoint);
        setIsOllamaRunning(running);

        if (running) {
          // Get installed models
          const models = await getInstalledModels(endpoint);
          setInstalledModels(models);
        }
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to initialize Ollama settings');
      } finally {
        setIsLoading(false);
      }
    }

    initialize();
  }, [endpoint]);

  // Notify parent of config changes
  useEffect(() => {
    if (selectedModel && endpoint) {
      onConfigChange?.({ endpoint, model: selectedModel });
    }
  }, [selectedModel, endpoint, onConfigChange]);

  const handleModelChange = (modelId: string) => {
    setSelectedModel(modelId);
  };

  const handleEndpointChange = (newEndpoint: string) => {
    setEndpoint(newEndpoint);
  };

  const handleRefresh = async () => {
    setIsLoading(true);
    setError(null);

    try {
      const running = await checkOllamaStatus(endpoint);
      setIsOllamaRunning(running);

      if (running) {
        const models = await getInstalledModels(endpoint);
        setInstalledModels(models);
      }
    } catch (err) {
      setError('Failed to connect to Ollama');
    } finally {
      setIsLoading(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="text-center">
          <div className="mb-4 h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent"></div>
          <p className="text-sm text-muted-foreground">Detecting system capabilities...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h3 className="text-lg font-semibold">Ollama Configuration</h3>
        <p className="text-sm text-muted-foreground">
          Configure local LLM with automatic model selection based on your system
        </p>
      </div>

      {/* Error Display */}
      {error && (
        <div className="rounded-md bg-destructive/10 p-4 text-sm text-destructive">
          {error}
        </div>
      )}

      {/* Ollama Status */}
      <div className="rounded-lg border p-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div
              className={`h-3 w-3 rounded-full ${
                isOllamaRunning ? 'bg-green-500' : 'bg-red-500'
              }`}
            />
            <div>
              <p className="font-medium">
                {isOllamaRunning ? 'Ollama is running' : 'Ollama is not running'}
              </p>
              <p className="text-sm text-muted-foreground">{endpoint}</p>
            </div>
          </div>
          <button
            onClick={handleRefresh}
            className="rounded-md bg-secondary px-3 py-1.5 text-sm hover:bg-secondary/80"
          >
            Refresh
          </button>
        </div>

        {!isOllamaRunning && (
          <div className="mt-4 rounded-md bg-muted p-3 text-sm">
            <p className="font-medium">Ollama not detected</p>
            <p className="mt-1 text-muted-foreground">
              Make sure Ollama is installed and running. Visit{' '}
              <a
                href="https://ollama.ai"
                target="_blank"
                rel="noopener noreferrer"
                className="text-primary underline"
              >
                ollama.ai
              </a>{' '}
              to download.
            </p>
          </div>
        )}
      </div>

      {/* System Capabilities */}
      {capabilities && (
        <div className="rounded-lg border p-4">
          <h4 className="mb-3 font-medium">System Capabilities</h4>
          <div className="grid grid-cols-2 gap-4 text-sm">
            <div>
              <p className="text-muted-foreground">Total RAM</p>
              <p className="font-medium">{capabilities.totalRAM.toFixed(1)} GB</p>
            </div>
            <div>
              <p className="text-muted-foreground">Available RAM</p>
              <p className="font-medium">{capabilities.availableRAM.toFixed(1)} GB</p>
            </div>
            <div>
              <p className="text-muted-foreground">GPU</p>
              <p className="font-medium">{capabilities.hasGPU ? 'Yes' : 'No'}</p>
            </div>
            {capabilities.gpuVRAM && (
              <div>
                <p className="text-muted-foreground">GPU VRAM</p>
                <p className="font-medium">{capabilities.gpuVRAM.toFixed(1)} GB</p>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Model Recommendation */}
      {recommendation && (
        <div className="rounded-lg border border-primary/20 bg-primary/5 p-4">
          <div className="mb-2 flex items-center gap-2">
            <svg
              className="h-5 w-5 text-primary"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
              />
            </svg>
            <h4 className="font-medium">Recommended Model</h4>
          </div>
          <p className="mb-3 text-sm text-muted-foreground">{recommendation.reason}</p>

          {recommendation.warnings.length > 0 && (
            <div className="mb-3 rounded-md bg-yellow-500/10 p-3 text-sm text-yellow-700 dark:text-yellow-400">
              {recommendation.warnings.map((warning, i) => (
                <p key={i}>{warning}</p>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Model Selection */}
      <div className="space-y-3">
        <h4 className="font-medium">Select Model</h4>
        <div className="space-y-2">
          {GEMMA3_MODELS.map((model) => {
            const isInstalled = installedModels.includes(model.id);
            const isRecommended = recommendation?.model.id === model.id;
            const canRun = capabilities
              ? capabilities.availableRAM >= model.minRAM
              : true;

            return (
              <label
                key={model.id}
                className={`flex cursor-pointer items-start gap-3 rounded-lg border p-4 transition-colors ${
                  selectedModel === model.id
                    ? 'border-primary bg-primary/5'
                    : 'hover:bg-muted/50'
                } ${!canRun ? 'opacity-50' : ''}`}
              >
                <input
                  type="radio"
                  name="model"
                  value={model.id}
                  checked={selectedModel === model.id}
                  onChange={(e) => handleModelChange(e.target.value)}
                  disabled={!canRun}
                  className="mt-1"
                />
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <p className="font-medium">{model.name}</p>
                    {isRecommended && (
                      <span className="rounded-full bg-primary px-2 py-0.5 text-xs text-primary-foreground">
                        Recommended
                      </span>
                    )}
                    {isInstalled && (
                      <span className="rounded-full bg-green-500/10 px-2 py-0.5 text-xs text-green-700 dark:text-green-400">
                        Installed
                      </span>
                    )}
                  </div>
                  <p className="mt-1 text-sm text-muted-foreground">{model.description}</p>
                  <div className="mt-2 flex gap-4 text-xs text-muted-foreground">
                    <span>Min RAM: {model.minRAM}GB</span>
                    <span>Recommended: {model.recommendedRAM}GB</span>
                    {model.minVRAM && <span>Min VRAM: {model.minVRAM}GB</span>}
                  </div>
                  {!canRun && (
                    <p className="mt-2 text-xs text-destructive">
                      Insufficient RAM for this model
                    </p>
                  )}
                  {!isInstalled && isOllamaRunning && (
                    <p className="mt-2 text-xs text-muted-foreground">
                      Run: <code className="rounded bg-muted px-1">ollama pull {model.id}</code>
                    </p>
                  )}
                </div>
              </label>
            );
          })}
        </div>
      </div>

      {/* Endpoint Configuration */}
      <div className="space-y-2">
        <label className="text-sm font-medium">Ollama Endpoint</label>
        <input
          type="text"
          value={endpoint}
          onChange={(e) => handleEndpointChange(e.target.value)}
          placeholder="http://localhost:11434"
          className="w-full rounded-md border bg-background px-3 py-2 text-sm"
        />
        <p className="text-xs text-muted-foreground">
          Default: {DEFAULT_OLLAMA_CONFIG.endpoint}
        </p>
      </div>

      {/* Alternative Models */}
      {recommendation && recommendation.alternatives.length > 0 && (
        <div className="rounded-lg border p-4">
          <h4 className="mb-2 font-medium">Alternative Models</h4>
          <p className="mb-3 text-sm text-muted-foreground">
            Other models compatible with your system
          </p>
          <div className="space-y-2">
            {recommendation.alternatives.map((model) => (
              <div key={model.id} className="flex items-center justify-between text-sm">
                <span>{model.name}</span>
                <span className="text-muted-foreground">{model.description}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * Tests d'int├®gration pour AddonsPanel
 * 
 * Teste l'int├®gration entre l'interface utilisateur et les services de gestion des add-ons
 */

import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import { AddonsPanel } from '../AddonsPanel';
import { addonManager } from '@/services/AddonManager';
import { fileSystemService } from '@/services/FileSystemService';
import { promises as fs } from 'fs';
import path from 'path';
import { vi } from 'vitest';

// Mock useToast hook
vi.mock('@/hooks/use-toast', () => ({
  useToast: () => ({
    toast: vi.fn()
  })
}));

describe('AddonsPanel Integration Tests', () => {
  const testFile = 'test-addons-panel.json';

  beforeEach(async () => {
    // Nettoyer le fichier de test
    try {
      await fs.unlink(testFile);
    } catch {}

    // R├®initialiser le manager
    await addonManager.initialize();
  });

  afterEach(async () => {
    // Nettoyer le fichier de test
    try {
      await fs.unlink(testFile);
    } catch {}
  });

  it('should render and initialize add-ons', async () => {
    render(<AddonsPanel />);

    // V├®rifier que le titre est affich├®
    expect(screen.getByText('Gestion des Add-ons')).toBeInTheDocument();

    // V├®rifier que les boutons d'export/import sont pr├®sents
    expect(screen.getByText('Exporter')).toBeInTheDocument();
    expect(screen.getByText('Importer')).toBeInTheDocument();

    // Attendre que les add-ons soient charg├®s
    await waitFor(() => {
      expect(screen.getByText('Casting Manager')).toBeInTheDocument();
    });
  });

  it('should export configuration when export button is clicked', async () => {
    render(<AddonsPanel />);

    // Attendre que les add-ons soient charg├®s
    await waitFor(() => {
      expect(screen.getByText('Casting Manager')).toBeInTheDocument();
    });

    // Cliquer sur le bouton Exporter
    const exportButton = screen.getByText('Exporter');
    fireEvent.click(exportButton);

    // V├®rifier que le fichier a ├®t├® cr├®├®
    const fileExists = await fileSystemService.fileExists(testFile);
    expect(fileExists).toBe(true);

    // V├®rifier le contenu du fichier
    const config = await fileSystemService.readConfigFile(testFile);
    expect(config).toBeDefined();
  });

  it('should import configuration when import button is clicked', async () => {
    // Cr├®er un fichier de configuration de test
    const testConfig = {
      'casting': {
        enabled: true,
        settings: { maxActorsPerScene: 10 }
      }
    };

    await fileSystemService.writeConfigFile(testFile, testConfig);

    render(<AddonsPanel />);

    // Attendre que les add-ons soient charg├®s
    await waitFor(() => {
      expect(screen.getByText('Casting Manager')).toBeInTheDocument();
    });

    // Cliquer sur le bouton Importer
    const importButton = screen.getByText('Importer');
    fireEvent.click(importButton);

    // V├®rifier que la configuration a ├®t├® import├®e
    const castingAddon = addonManager.getAddon('casting');
    expect(castingAddon?.enabled).toBe(true);

    const settings = addonManager.getAddonSettings('casting');
    expect(settings?.maxActorsPerScene).toBe(10);
  });

  it('should toggle add-on activation', async () => {
    render(<AddonsPanel />);

    // Attendre que les add-ons soient charg├®s
    await waitFor(() => {
      expect(screen.getByText('Casting Manager')).toBeInTheDocument();
    });

    // Trouver le bouton d'activation pour le casting
    const toggleButton = screen.getByText('Activer');
    fireEvent.click(toggleButton);

    // Attendre que l'add-on soit activ├®
    await waitFor(() => {
      expect(screen.getByText('D├®sactiver')).toBeInTheDocument();
    });

    // V├®rifier que l'add-on est activ├®
    const castingAddon = addonManager.getAddon('casting');
    expect(castingAddon?.enabled).toBe(true);
  });

  it('should filter add-ons by search query', async () => {
    render(<AddonsPanel />);

    // Attendre que les add-ons soient charg├®s
    await waitFor(() => {
      expect(screen.getByText('Casting Manager')).toBeInTheDocument();
    });

    // Rechercher "Audio"
    const searchInput = screen.getByPlaceholderText('Rechercher des add-ons...');
    fireEvent.change(searchInput, { target: { value: 'Audio' } });

    // V├®rifier que seul l'add-on audio est affich├®
    expect(screen.getByText('Audio Production Suite')).toBeInTheDocument();
    expect(screen.queryByText('Casting Manager')).not.toBeInTheDocument();
  });

  it('should filter add-ons by category', async () => {
    render(<AddonsPanel />);

    // Attendre que les add-ons soient charg├®s
    await waitFor(() => {
      expect(screen.getByText('Casting Manager')).toBeInTheDocument();
    });

    // Filtrer par cat├®gorie "Traitement"
    const processingButton = screen.getByText('Traitement');
    fireEvent.click(processingButton);

    // V├®rifier que seuls les add-ons de traitement sont affich├®s
    expect(screen.getByText('Audio Production Suite')).toBeInTheDocument();
    expect(screen.getByText('Comic to Sequence Converter')).toBeInTheDocument();
    expect(screen.queryByText('Casting Manager')).not.toBeInTheDocument();
  });

  it('should handle export error gracefully', async () => {
    // Simuler une erreur d'├®criture de fichier
    const originalWriteFile = fileSystemService.writeConfigFile;
    fileSystemService.writeConfigFile = async () => {
      throw new Error('Permission denied');
    };

    render(<AddonsPanel />);

    // Attendre que les add-ons soient charg├®s
    await waitFor(() => {
      expect(screen.getByText('Casting Manager')).toBeInTheDocument();
    });

    // Cliquer sur le bouton Exporter
    const exportButton = screen.getByText('Exporter');
    fireEvent.click(exportButton);

    // Restaurer la m├®thode originale
    fileSystemService.writeConfigFile = originalWriteFile;

    // V├®rifier que l'erreur est g├®r├®e (pas de crash)
    expect(screen.getByText('Casting Manager')).toBeInTheDocument();
  });

  it('should handle import error gracefully', async () => {
    // Cr├®er un fichier de configuration invalide
    await fs.writeFile(testFile, 'invalid json content', 'utf-8');

