      );

      await user.type(screen.getByLabelText('API Key'), 'sk-1234567890abcdefghij');
      await user.click(screen.getByRole('button', { name: /Test Connection/i }));

      await waitFor(() => {
        expect(screen.getByText(/Check: 1\) API key is correct/i)).toBeInTheDocument();
      });
    });

    it('shows testing state during connection test', async () => {
      const user = userEvent.setup();
      let resolveTest: (value: boolean) => void;
      const testPromise = new Promise<boolean>((resolve) => {
        resolveTest = resolve;
      });
      mockOnTestConnection.mockReturnValue(testPromise);

      render(
        <LLMSettingsPanel
          onSave={mockOnSave}
          onTestConnection={mockOnTestConnection}
        />
      );

      await user.type(screen.getByLabelText('API Key'), 'sk-1234567890abcdefghij');
      await user.click(screen.getByRole('button', { name: /Test Connection/i }));

      // Should show testing state
      expect(screen.getByText(/Testing connection/i)).toBeInTheDocument();
      expect(screen.getByRole('button', { name: /Test Connection/i })).toBeDisabled();

      // Resolve the test
      resolveTest!(true);

      await waitFor(() => {
        expect(screen.getByText(/Connection successful/i)).toBeInTheDocument();
      });
    });

    it('handles connection test exceptions', async () => {
      const user = userEvent.setup();
      mockOnTestConnection.mockRejectedValue(new Error('Network error'));

      render(
        <LLMSettingsPanel
          onSave={mockOnSave}
          onTestConnection={mockOnTestConnection}
        />
      );

      await user.type(screen.getByLabelText('API Key'), 'sk-1234567890abcdefghij');
      await user.click(screen.getByRole('button', { name: /Test Connection/i }));

      await waitFor(() => {
        expect(screen.getByText(/Network error/i)).toBeInTheDocument();
      });
    });

    it('shows different error messages for different providers', async () => {
      const user = userEvent.setup();
      mockOnTestConnection.mockResolvedValue(false);

      render(
        <LLMSettingsPanel
          onSave={mockOnSave}
          onTestConnection={mockOnTestConnection}
        />
      );

      // Test OpenAI
      await user.type(screen.getByLabelText('API Key'), 'sk-1234567890abcdefghij');
      await user.click(screen.getByRole('button', { name: /Test Connection/i }));

      await waitFor(() => {
        expect(screen.getByText(/OpenAI API key/i)).toBeInTheDocument();
      });

      // Switch to Anthropic
      await user.click(screen.getByLabelText(/Anthropic/i));
      const apiKeyInput = screen.getByLabelText('API Key');
      await user.clear(apiKeyInput);
      await user.type(apiKeyInput, 'sk-ant-1234567890abcdefghij');
      await user.click(screen.getByRole('button', { name: /Test Connection/i }));

      await waitFor(() => {
        expect(screen.getByText(/Anthropic API key/i)).toBeInTheDocument();
      });
    });

    it('clears connection status when provider changes', async () => {
      const user = userEvent.setup();
      mockOnTestConnection.mockResolvedValue(true);

      render(
        <LLMSettingsPanel
          onSave={mockOnSave}
          onTestConnection={mockOnTestConnection}
        />
      );

      // Test OpenAI connection
      await user.type(screen.getByLabelText('API Key'), 'sk-1234567890abcdefghij');
      await user.click(screen.getByRole('button', { name: /Test Connection/i }));

      await waitFor(() => {
        expect(screen.getByText(/Connection successful/i)).toBeInTheDocument();
      });

      // Switch provider
      await user.click(screen.getByLabelText(/Anthropic/i));

      // Success message should be cleared
      expect(screen.queryByText(/Connection successful/i)).not.toBeInTheDocument();
    });

    it('shows success indicator with checkmark', async () => {
      const user = userEvent.setup();
      mockOnTestConnection.mockResolvedValue(true);

      render(
        <LLMSettingsPanel
          onSave={mockOnSave}
          onTestConnection={mockOnTestConnection}
        />
      );

      await user.type(screen.getByLabelText('API Key'), 'sk-1234567890abcdefghij');
      await user.click(screen.getByRole('button', { name: /Test Connection/i }));

      await waitFor(() => {
        const successDiv = screen.getByText(/Connection successful/i).closest('div');
        expect(successDiv).toHaveClass('bg-green-50');
      });
    });

    it('shows verification message after successful test', async () => {
      const user = userEvent.setup();
      mockOnTestConnection.mockResolvedValue(true);

      render(
        <LLMSettingsPanel
          onSave={mockOnSave}
          onTestConnection={mockOnTestConnection}
        />
      );

      await user.type(screen.getByLabelText('API Key'), 'sk-1234567890abcdefghij');
      await user.click(screen.getByRole('button', { name: /Test Connection/i }));

      await waitFor(() => {
        expect(screen.getByText(/Connection verified. You can now save your settings/i)).toBeInTheDocument();
      });
    });
  });

  // ============================================================================
  // Save Validation Tests
  // ============================================================================

  describe('Save Validation', () => {
    it('requires connection test before saving when handler provided', async () => {
      const user = userEvent.setup();
      render(
        <LLMSettingsPanel
          onSave={mockOnSave}
          onTestConnection={mockOnTestConnection}
        />
      );

      // Enter valid API key but don't test
      await user.type(screen.getByLabelText('API Key'), 'sk-1234567890abcdefghij');

      // Try to save
      await user.click(screen.getByRole('button', { name: /Save Settings/i }));

      // Should not call onSave
      expect(mockOnSave).not.toHaveBeenCalled();
    });

    it('shows reminder to test connection before saving', async () => {
      const user = userEvent.setup();
      render(
        <LLMSettingsPanel
          onSave={mockOnSave}
          onTestConnection={mockOnTestConnection}
        />
      );

      // Enter valid API key
      await user.type(screen.getByLabelText('API Key'), 'sk-1234567890abcdefghij');

      // Should show reminder
      expect(screen.getByText(/Please test the connection before saving/i)).toBeInTheDocument();
    });

    it('allows saving after successful connection test', async () => {
      const user = userEvent.setup();
      mockOnTestConnection.mockResolvedValue(true);

      render(
        <LLMSettingsPanel
          onSave={mockOnSave}
          onTestConnection={mockOnTestConnection}
        />
      );

      // Enter valid API key and test
      await user.type(screen.getByLabelText('API Key'), 'sk-1234567890abcdefghij');
      await user.click(screen.getByRole('button', { name: /Test Connection/i }));

      await waitFor(() => {
        expect(screen.getByText(/Connection successful/i)).toBeInTheDocument();
      });

      // Now save should work
      await user.click(screen.getByRole('button', { name: /Save Settings/i }));

      expect(mockOnSave).toHaveBeenCalled();
    });

    it('shows validation error message when form is incomplete', async () => {
      render(<LLMSettingsPanel onSave={mockOnSave} />);

      // Should show incomplete message
      expect(screen.getByText(/Configuration incomplete/i)).toBeInTheDocument();
      expect(screen.getByText(/API key is required/i)).toBeInTheDocument();
    });

    it('validates parameter ranges before saving', async () => {
      const user = userEvent.setup();
      render(<LLMSettingsPanel onSave={mockOnSave} />);

      // Enter valid API key
      await user.type(screen.getByLabelText('API Key'), 'sk-1234567890abcdefghij');

      // Set invalid max tokens
      const maxTokensInput = screen.getByLabelText(/Max Tokens/i);
      await user.clear(maxTokensInput);
      await user.type(maxTokensInput, '0');

      // Try to save
      await user.click(screen.getByRole('button', { name: /Save Settings/i }));

      // Should show validation error
      expect(screen.getByText(/Max tokens must be at least 1/i)).toBeInTheDocument();
      expect(mockOnSave).not.toHaveBeenCalled();
    });

    it('disables save button when validation fails', async () => {
      const user = userEvent.setup();
      render(<LLMSettingsPanel onSave={mockOnSave} />);

      // Enter invalid API key
      await user.type(screen.getByLabelText('API Key'), 'invalid');

      const saveButton = screen.getByRole('button', { name: /Save Settings/i });
      expect(saveButton).toBeDisabled();
    });

    it('enables save button when all validation passes', async () => {
      const user = userEvent.setup();
      mockOnTestConnection.mockResolvedValue(true);

      render(
        <LLMSettingsPanel
          onSave={mockOnSave}
          onTestConnection={mockOnTestConnection}
        />
      );

      // Enter valid API key
      await user.type(screen.getByLabelText('API Key'), 'sk-1234567890abcdefghij');

      // Test connection
      await user.click(screen.getByRole('button', { name: /Test Connection/i }));

      await waitFor(() => {
        const saveButton = screen.getByRole('button', { name: /Save Settings/i });
        expect(saveButton).not.toBeDisabled();
      });
    });
  });

  // ============================================================================
  // Accessibility Tests
  // ============================================================================

  describe('Accessibility', () => {
    it('uses role="alert" for status messages', async () => {
      const user = userEvent.setup();
      mockOnTestConnection.mockResolvedValue(true);

      render(
        <LLMSettingsPanel
          onSave={mockOnSave}
          onTestConnection={mockOnTestConnection}
        />
      );

      await user.type(screen.getByLabelText('API Key'), 'sk-1234567890abcdefghij');
      await user.click(screen.getByRole('button', { name: /Test Connection/i }));

      await waitFor(() => {
        const alert = screen.getByRole('alert');
        expect(alert).toBeInTheDocument();
      });
    });

    it('uses aria-live for dynamic status updates', async () => {
      const user = userEvent.setup();
      mockOnTestConnection.mockResolvedValue(true);

      render(
        <LLMSettingsPanel
          onSave={mockOnSave}
          onTestConnection={mockOnTestConnection}
        />
      );

      await user.type(screen.getByLabelText('API Key'), 'sk-1234567890abcdefghij');
      await user.click(screen.getByRole('button', { name: /Test Connection/i }));

      await waitFor(() => {
        const statusDiv = screen.getByText(/Connection successful/i).closest('div');
        expect(statusDiv).toHaveAttribute('aria-live', 'polite');
      });
    });

    it('associates error messages with inputs using aria-describedby', async () => {
      const user = userEvent.setup();
      render(<LLMSettingsPanel onSave={mockOnSave} />);

      const apiKeyInput = screen.getByLabelText('API Key');
      await user.type(apiKeyInput, 'invalid');

      const errorId = apiKeyInput.getAttribute('aria-describedby');
      expect(errorId).toBe('apiKey-error');
      expect(screen.getByText(/must start with/i)).toHaveAttribute('id', errorId);
    });
  });
});

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { motion } from 'framer-motion';
import './FrameComparisonView.css';

export interface FrameComparisonViewProps {
  videoUrl: string;
  frameRate: number;
  frame1: number;
  frame2: number;
  onClose?: () => void;
}

export const FrameComparisonView: React.FC<FrameComparisonViewProps> = ({
  videoUrl,
  frameRate,
  frame1: initialFrame1,
  frame2: initialFrame2,
  onClose
}) => {
  const [frame1, setFrame1] = useState(initialFrame1);
  const [frame2, setFrame2] = useState(initialFrame2);
  const [sliderPosition, setSliderPosition] = useState(50); // 0-100%
  const [comparisonMode, setComparisonMode] = useState<'slider' | 'sidebyside'>('sidebyside');
  const video1Ref = useRef<HTMLVideoElement>(null);
  const video2Ref = useRef<HTMLVideoElement>(null);
  const sliderContainerRef = useRef<HTMLDivElement>(null);

  // Convert frame to time
  const frameToTime = useCallback((frame: number): number => {
    return frame / frameRate;
  }, [frameRate]);

  // Format timecode
  const formatTimecode = useCallback((frame: number): string => {
    const totalSeconds = frame / frameRate;
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = Math.floor(totalSeconds % 60);
    const frames = frame % frameRate;
    
    return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}:${Math.floor(frames).toString().padStart(2, '0')}`;
  }, [frameRate]);

  // Seek videos to frames
  useEffect(() => {
    if (video1Ref.current) {
      video1Ref.current.currentTime = frameToTime(frame1);
    }
  }, [frame1, frameToTime]);

  useEffect(() => {
    if (video2Ref.current) {
      video2Ref.current.currentTime = frameToTime(frame2);
    }
  }, [frame2, frameToTime]);

  // Handle slider drag
  const handleSliderDrag = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
    if (!sliderContainerRef.current) return;
    
    const rect = sliderContainerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const percentage = Math.max(0, Math.min(100, (x / rect.width) * 100));
    setSliderPosition(percentage);
  }, []);

  const handleMouseDown = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
    handleSliderDrag(e);
    
    const handleMouseMove = (moveEvent: MouseEvent) => {
      if (!sliderContainerRef.current) return;
      
      const rect = sliderContainerRef.current.getBoundingClientRect();
      const x = moveEvent.clientX - rect.left;
      const percentage = Math.max(0, Math.min(100, (x / rect.width) * 100));
      setSliderPosition(percentage);
    };
    
    const handleMouseUp = () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
    
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  }, [handleSliderDrag]);

  return (
    <div className="frame-comparison-view">
      <div className="frame-comparison-view__header">
        <h2>Comparaison de Frames</h2>
        <div className="frame-comparison-view__mode-toggle">
          <button
            className={comparisonMode === 'sidebyside' ? 'active' : ''}
            onClick={() => setComparisonMode('sidebyside')}
            title="Vue c├┤te ├á c├┤te"
          >
            Ô¼î
          </button>
          <button
            className={comparisonMode === 'slider' ? 'active' : ''}
            onClick={() => setComparisonMode('slider')}
            title="Vue avec slider"
          >
            Ô¼ìÔ¼îÔ¼Ä
          </button>
        </div>
        {onClose && (
          <button className="frame-comparison-view__close" onClick={onClose}>
            Ô£ò
          </button>
        )}
      </div>

      <div className="frame-comparison-view__content">
        {comparisonMode === 'sidebyside' ? (
          <div className="frame-comparison-view__sidebyside">
            {/* Frame 1 */}
            <div className="frame-comparison-view__frame">
              <div className="frame-comparison-view__frame-header">
                <span>Frame {frame1}</span>
                <span className="frame-comparison-view__timecode">
                  {formatTimecode(frame1)}
                </span>
              </div>
              <div className="frame-comparison-view__video-container">
                <video
                  ref={video1Ref}
                  src={videoUrl}
                  className="frame-comparison-view__video"
                  preload="auto"
                />
              </div>
              <div className="frame-comparison-view__frame-controls">
                <button onClick={() => setFrame1(Math.max(0, frame1 - 1))}>
                  ÔåÉ
                </button>
                <input
                  type="number"
                  value={frame1}
                  onChange={(e) => setFrame1(parseInt(e.target.value) || 0)}
                  min="0"
                />
                <button onClick={() => setFrame1(frame1 + 1)}>
                  ÔåÆ
                </button>
              </div>
            </div>

            {/* Frame 2 */}
            <div className="frame-comparison-view__frame">
              <div className="frame-comparison-view__frame-header">
                <span>Frame {frame2}</span>
                <span className="frame-comparison-view__timecode">
                  {formatTimecode(frame2)}
                </span>
              </div>
              <div className="frame-comparison-view__video-container">
                <video
                  ref={video2Ref}
                  src={videoUrl}
                  className="frame-comparison-view__video"
                  preload="auto"
                />
              </div>
              <div className="frame-comparison-view__frame-controls">
                <button onClick={() => setFrame2(Math.max(0, frame2 - 1))}>
                  ÔåÉ
                </button>
                <input
                  type="number"
                  value={frame2}
                  onChange={(e) => setFrame2(parseInt(e.target.value) || 0)}
                  min="0"
                />
                <button onClick={() => setFrame2(frame2 + 1)}>
                  ÔåÆ
                </button>
              </div>
            </div>
          </div>
        ) : (
          <div className="frame-comparison-view__slider-mode">
            <div
              ref={sliderContainerRef}
              className="frame-comparison-view__slider-container"
              onMouseDown={handleMouseDown}
            >
              {/* Frame 2 (background) */}
              <div className="frame-comparison-view__slider-background">
                <video
                  ref={video2Ref}
                  src={videoUrl}
                  className="frame-comparison-view__video"
                  preload="auto"
                />
                <div className="frame-comparison-view__slider-label frame-comparison-view__slider-label--right">
                  Frame {frame2} - {formatTimecode(frame2)}
                </div>
              </div>

              {/* Frame 1 (foreground with clip) */}
              <div
                className="frame-comparison-view__slider-foreground"
                style={{
                  clipPath: `inset(0 ${100 - sliderPosition}% 0 0)`
                }}
              >
                <video
                  ref={video1Ref}
                  src={videoUrl}
                  className="frame-comparison-view__video"
                  preload="auto"
                />
                <div className="frame-comparison-view__slider-label frame-comparison-view__slider-label--left">
                  Frame {frame1} - {formatTimecode(frame1)}
                </div>
              </div>

              {/* Slider Handle */}
              <div
                className="frame-comparison-view__slider-handle"
                style={{ left: `${sliderPosition}%` }}
              >
                <div className="frame-comparison-view__slider-line" />
                <div className="frame-comparison-view__slider-grip">
                  <span>Ô¼î</span>
                </div>
              </div>
            </div>

            {/* Slider Mode Controls */}
            <div className="frame-comparison-view__slider-controls">
              <div className="frame-comparison-view__slider-control-group">
                <label>Frame 1:</label>
                <button onClick={() => setFrame1(Math.max(0, frame1 - 1))}>
                  ÔåÉ
                </button>
                <input
                  type="number"
                  value={frame1}
                  onChange={(e) => setFrame1(parseInt(e.target.value) || 0)}
                  min="0"
                />
                <button onClick={() => setFrame1(frame1 + 1)}>
                  ÔåÆ
                </button>
              </div>
              <div className="frame-comparison-view__slider-control-group">
                <label>Frame 2:</label>
                <button onClick={() => setFrame2(Math.max(0, frame2 - 1))}>
                  ÔåÉ
                </button>
                <input
                  type="number"
                  value={frame2}
                  onChange={(e) => setFrame2(parseInt(e.target.value) || 0)}
                  min="0"
                />
                <button onClick={() => setFrame2(frame2 + 1)}>
                  ÔåÆ
                </button>
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="frame-comparison-view__info">
        <div className="frame-comparison-view__info-item">
          <strong>Diff├®rence:</strong> {Math.abs(frame2 - frame1)} frames ({((Math.abs(frame2 - frame1) / frameRate)).toFixed(2)}s)
        </div>
        <div className="frame-comparison-view__info-item">
          <strong>Mode:</strong> {comparisonMode === 'sidebyside' ? 'C├┤te ├á c├┤te' : 'Slider'}
        </div>
      </div>
    </div>
  );
};

export default FrameComparisonView;

