import React, { useState, useEffect, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { FrameComparisonView } from './FrameComparisonView';
import './ShotFrameViewer.css';

export interface ShotMetadata {
  id: string;
  name: string;
  description?: string;
  duration: number;
  startTime: number;
  endTime: number;
  videoUrl?: string;
  thumbnailUrl?: string;
  frameRate: number;
  resolution: { width: number; height: number };
  position: number;
  track: number;
  inPoint: number; // Point d'entr├®e en frames
  outPoint: number; // Point de sortie en frames
  tags: string[];
  category?: string;
  status: 'draft' | 'ready' | 'processing' | 'error';
  locked: boolean;
  createdAt: number;
  updatedAt: number;
  version: number;
}

export interface ShotFrameViewerProps {
  shot: ShotMetadata;
  onUpdate?: (shot: ShotMetadata) => void;
  onClose?: () => void;
}

export type TimecodeFormat = 'frames' | 'seconds' | 'smpte';

interface ValidationError {
  field: string;
  message: string;
}

export const ShotFrameViewer: React.FC<ShotFrameViewerProps> = ({
  shot: initialShot,
  onUpdate,
  onClose
}) => {
  const [shot, setShot] = useState<ShotMetadata>(initialShot);
  const [currentFrame, setCurrentFrame] = useState(shot.inPoint);
  const [validationErrors, setValidationErrors] = useState<ValidationError[]>([]);
  const [isDirty, setIsDirty] = useState(false);
  const [zoomLevel, setZoomLevel] = useState(100); // 100% = normal, up to 400%
  const [showComparison, setShowComparison] = useState(false);
  const [comparisonFrame, setComparisonFrame] = useState(shot.inPoint);
  const [timecodeFormat, setTimecodeFormat] = useState<TimecodeFormat>('smpte');
  const videoRef = useRef<HTMLVideoElement>(null);
  const previewContainerRef = useRef<HTMLDivElement>(null);

  // Calculate current time from frame number
  const frameToTime = useCallback((frame: number): number => {
    return frame / shot.frameRate;
  }, [shot.frameRate]);

  // Calculate frame number from time
  const timeToFrame = useCallback((time: number): number => {
    return Math.round(time * shot.frameRate);
  }, [shot.frameRate]);

  // Navigate to specific frame
  const seekToFrame = useCallback((frameNumber: number) => {
    const clampedFrame = Math.max(shot.inPoint, Math.min(shot.outPoint, frameNumber));
    setCurrentFrame(clampedFrame);
    
    if (videoRef.current) {
      videoRef.current.currentTime = frameToTime(clampedFrame);
    }
  }, [shot.inPoint, shot.outPoint, frameToTime]);

  // Real-time validation
  const validateField = useCallback((field: string, value: unknown): string | null => {
    switch (field) {
      case 'name':
        if (!value || value.trim().length === 0) {
          return 'Le nom est requis';
        }
        if (value.length > 100) {
          return 'Le nom ne peut pas d├®passer 100 caract├¿res';
        }
        break;

      case 'duration':
        if (value <= 0) {
          return 'La dur├®e doit ├¬tre positive';
        }
        if (value > 3600) {
          return 'La dur├®e ne peut pas d├®passer 1 heure';
        }
        break;

      case 'frameRate':
        if (value <= 0 || value > 120) {
          return 'Le framerate doit ├¬tre entre 1 et 120 fps';
        }
        break;

      case 'inPoint':
        if (value < 0) {
          return 'Le point d\'entr├®e ne peut pas ├¬tre n├®gatif';
        }
        if (value >= shot.outPoint) {
          return 'Le point d\'entr├®e doit ├¬tre avant le point de sortie';
        }
        break;

      case 'outPoint':
        if (value <= shot.inPoint) {
          return 'Le point de sortie doit ├¬tre apr├¿s le point d\'entr├®e';
        }
        const maxFrames = timeToFrame(shot.duration);
        if (value > maxFrames) {
          return `Le point de sortie ne peut pas d├®passer ${maxFrames} frames`;
        }
        break;

      case 'resolution.width':
      case 'resolution.height':
        if (value <= 0 || value > 7680) {
          return 'La r├®solution doit ├¬tre entre 1 et 7680 pixels';
        }
        break;
    }

    return null;
  }, [shot.outPoint, shot.inPoint, shot.duration, timeToFrame]);

  // Update field with validation
  const updateField = useCallback((field: string, value: unknown) => {
    const error = validateField(field, value);

    // Update validation errors
    setValidationErrors(prev => {
      const filtered = prev.filter(e => e.field !== field);
      if (error) {
        return [...filtered, { field, message: error }];
      }
      return filtered;
    });

    // Update shot data
    setShot(prev => {
      const updated = { ...prev };
      const keys = field.split('.');
      let current: unknown = updated;

      for (let i = 0; i < keys.length - 1; i++) {
        current = current[keys[i]];
      }

      current[keys[keys.length - 1]] = value;

      // Auto-calculate duration when in/out points change
      if (field === 'inPoint' || field === 'outPoint') {
        updated.duration = (updated.outPoint - updated.inPoint) / updated.frameRate;
      }

      updated.updatedAt = Date.now();
      updated.version += 1;

      return updated;
    });

    setIsDirty(true);
  }, [validateField]);



  // Save changes
  const handleSave = useCallback(() => {
    if (validationErrors.length === 0) {
      onUpdate?.(shot);
      setIsDirty(false);
    }
  }, [shot, validationErrors, onUpdate]);

  // Format timecode
  const formatTimecode = useCallback((frame: number, format?: TimecodeFormat): string => {
    const currentFormat = format || timecodeFormat;
    
    switch (currentFormat) {
      case 'frames':
        return `${frame} frames`;
      
      case 'seconds': {
        const totalSeconds = frame / shot.frameRate;
        return `${totalSeconds.toFixed(3)}s`;
      }
      
      case 'smpte':
      default: {
        const totalSeconds = frame / shot.frameRate;
        const hours = Math.floor(totalSeconds / 3600);
        const minutes = Math.floor((totalSeconds % 3600) / 60);
        const seconds = Math.floor(totalSeconds % 60);
        const frames = frame % shot.frameRate;
        
        return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}:${Math.floor(frames).toString().padStart(2, '0')}`;
      }
    }
  }, [shot.frameRate, timecodeFormat]);

  // Get validation error for field
  const getFieldError = useCallback((field: string): string | null => {
    const error = validationErrors.find(e => e.field === field);
    return error ? error.message : null;
  }, [validationErrors]);

  // Zoom controls
  const handleZoomIn = useCallback(() => {
    setZoomLevel(prev => Math.min(400, prev + 25));
  }, []);

  const handleZoomOut = useCallback(() => {
    setZoomLevel(prev => Math.max(100, prev - 25));
  }, []);

  const handleZoomReset = useCallback(() => {
    setZoomLevel(100);
  }, []);

  // Mouse wheel zoom
  useEffect(() => {
    const handleWheel = (e: WheelEvent) => {
      if (e.ctrlKey || e.metaKey) {
        e.preventDefault();
        if (e.deltaY < 0) {
          handleZoomIn();
        } else {
          handleZoomOut();
        }
      }
    };

    const container = previewContainerRef.current;
    if (container) {
      container.addEventListener('wheel', handleWheel, { passive: false });
      return () => container.removeEventListener('wheel', handleWheel);
    }
  }, [handleZoomIn, handleZoomOut]);

  return (
    <div className="shot-frame-viewer">
      <div className="shot-frame-viewer__header">
        <h2>Shot Frame Viewer</h2>
        <div className="shot-frame-viewer__header-actions">
          {/* Timecode Format Selector */}
          <div className="shot-frame-viewer__timecode-format">
            <label htmlFor="timecode-format">Format:</label>
            <select
              id="timecode-format"
              value={timecodeFormat}
              onChange={(e) => setTimecodeFormat(e.target.value as TimecodeFormat)}
              className="shot-frame-viewer__format-select"
            >
              <option value="smpte">SMPTE (HH:MM:SS:FF)</option>
              <option value="seconds">Secondes</option>
              <option value="frames">Frames</option>
            </select>
          </div>
          
          {isDirty && (
            <motion.span
              className="shot-frame-viewer__dirty-indicator"
              initial={{ opacity: 0, scale: 0.8 }}
              animate={{ opacity: 1, scale: 1 }}
            >
              ÔÇó Non sauvegard├®
            </motion.span>
          )}
          <button
            className="shot-frame-viewer__save-btn"
            onClick={handleSave}
            disabled={validationErrors.length > 0 || !isDirty}
          >
            Sauvegarder
          </button>
          {onClose && (
            <button
              className="shot-frame-viewer__close-btn"
              onClick={onClose}
            >
              Ô£ò
            </button>
          )}
        </div>
      </div>

      <div className="shot-frame-viewer__content">
        {/* Video Preview */}
        <div className="shot-frame-viewer__preview" ref={previewContainerRef}>
          <div
            className="shot-frame-viewer__preview-content"
            style={{
              transform: `scale(${zoomLevel / 100})`,
              transformOrigin: 'center center'
            }}
          >
            {shot.videoUrl ? (
              <video
                ref={videoRef}
                src={shot.videoUrl}
                className="shot-frame-viewer__video"
                onTimeUpdate={(e) => {
                  const frame = timeToFrame(e.currentTarget.currentTime);
                  setCurrentFrame(frame);
                }}
              />
            ) : (
              <div className="shot-frame-viewer__no-video">
                <span>Aucune vid├®o disponible</span>
              </div>
            )}
          </div>
          
          <div className="shot-frame-viewer__timecode">
            {formatTimecode(currentFrame)}
          </div>

          {/* Zoom Controls */}
          <div className="shot-frame-viewer__zoom-controls">
            <button
              onClick={handleZoomOut}
              disabled={zoomLevel <= 100}
              title="Zoom arri├¿re (Ctrl + Molette)"
            >
              ÔêÆ
            </button>
            <span className="shot-frame-viewer__zoom-level">
              {zoomLevel}%
            </span>
            <button
              onClick={handleZoomIn}
              disabled={zoomLevel >= 400}
              title="Zoom avant (Ctrl + Molette)"
            >
              +
            </button>
            <button
              onClick={handleZoomReset}
              disabled={zoomLevel === 100}
              title="R├®initialiser le zoom"
              className="shot-frame-viewer__zoom-reset"
            >
              Ôƒ▓
            </button>
          </div>

          {zoomLevel > 100 && (
            <div className="shot-frame-viewer__zoom-hint">
              Aper├ºu haute qualit├® activ├® ({zoomLevel}%)
            </div>
          )}
        </div>

        {/* Frame Navigation */}
        <div className="shot-frame-viewer__navigation">
          <button
            onClick={() => seekToFrame(shot.inPoint)}
            title="Aller au d├®but (Home)"
          >
            ÔÅ«
          </button>
          <button
            onClick={() => seekToFrame(currentFrame - 1)}
            title="Frame pr├®c├®dente (ÔåÉ)"
          >
            ÔÅ¬
          </button>
          <span className="shot-frame-viewer__frame-counter">
            Frame {currentFrame} / {shot.outPoint}
          </span>
          <button
            onClick={() => seekToFrame(currentFrame + 1)}
            title="Frame suivante (ÔåÆ)"
          >
            ÔÅ®
          </button>
          <button
            onClick={() => seekToFrame(shot.outPoint)}
            title="Aller ├á la fin (End)"
          >
            ÔÅ¡
          </button>
          <button
            onClick={() => {
              setComparisonFrame(currentFrame);
              setShowComparison(true);
            }}
            title="Comparer avec un autre frame"
            className="shot-frame-viewer__compare-btn"
          >
            Ô¼î Comparer
          </button>
        </div>

        {/* Timeline with In/Out Point Markers */}
        <div className="shot-frame-viewer__timeline">
          <div className="shot-frame-viewer__timeline-header">
            <span>Timeline</span>
            <div className="shot-frame-viewer__timeline-shortcuts">
              <span title="D├®finir le point d'entr├®e">I: In Point</span>
              <span title="D├®finir le point de sortie">O: Out Point</span>
            </div>
          </div>
          <div className="shot-frame-viewer__timeline-track">
            {/* In Point Marker */}
            <div
              className="shot-frame-viewer__timeline-marker shot-frame-viewer__timeline-marker--in"
              style={{
                left: `${(shot.inPoint / shot.outPoint) * 100}%`
              }}
              title={`In Point: ${formatTimecode(shot.inPoint)}`}
            >
              <div className="shot-frame-viewer__timeline-marker-label">I</div>
              <div className="shot-frame-viewer__timeline-marker-line" />
            </div>

            {/* Current Frame Indicator */}
            <div
              className="shot-frame-viewer__timeline-indicator"
              style={{
                left: `${(currentFrame / shot.outPoint) * 100}%`
              }}
            >
              <div className="shot-frame-viewer__timeline-indicator-head" />
              <div className="shot-frame-viewer__timeline-indicator-line" />
            </div>

            {/* Out Point Marker */}
            <div
              className="shot-frame-viewer__timeline-marker shot-frame-viewer__timeline-marker--out"
              style={{
                left: `${(shot.outPoint / shot.outPoint) * 100}%`
              }}
              title={`Out Point: ${formatTimecode(shot.outPoint)}`}
            >
              <div className="shot-frame-viewer__timeline-marker-label">O</div>
              <div className="shot-frame-viewer__timeline-marker-line" />
            </div>

            {/* Active Region */}
            <div
              className="shot-frame-viewer__timeline-active-region"
              style={{
                left: `${(shot.inPoint / shot.outPoint) * 100}%`,
                width: `${((shot.outPoint - shot.inPoint) / shot.outPoint) * 100}%`
              }}
            />

            {/* Clickable Track */}
            <div
              className="shot-frame-viewer__timeline-clickable"
              onClick={(e) => {
                const rect = e.currentTarget.getBoundingClientRect();
                const x = e.clientX - rect.left;
                const percentage = x / rect.width;
                const frame = Math.round(percentage * shot.outPoint);
                seekToFrame(frame);
              }}
            />
          </div>
          <div className="shot-frame-viewer__timeline-info">
            <span>In: {formatTimecode(shot.inPoint)}</span>
            <span>Duration: {shot.duration.toFixed(2)}s ({shot.outPoint - shot.inPoint} frames)</span>
            <span>Out: {formatTimecode(shot.outPoint)}</span>
          </div>
        </div>

        {/* Metadata Editor */}
        <div className="shot-frame-viewer__metadata">
          <h3>M├®tadonn├®es</h3>
          
          <div className="shot-frame-viewer__form">
            {/* Name */}
            <div className="shot-frame-viewer__field">
              <label htmlFor="shot-name">Nom *</label>
              <input
                id="shot-name"
                type="text"
                value={shot.name}
                onChange={(e) => updateField('name', e.target.value)}
                className={getFieldError('name') ? 'error' : ''}
              />
              <AnimatePresence>
                {getFieldError('name') && (
                  <motion.span
                    className="shot-frame-viewer__error"
                    initial={{ opacity: 0, y: -5 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -5 }}
                  >
                    {getFieldError('name')}
                  </motion.span>
                )}
              </AnimatePresence>
            </div>

            {/* Description */}
            <div className="shot-frame-viewer__field">
              <label htmlFor="shot-description">Description</label>
              <textarea
                id="shot-description"
                value={shot.description || ''}
                onChange={(e) => updateField('description', e.target.value)}
                rows={3}
              />
            </div>

            {/* Duration (read-only, calculated from in/out points) */}
            <div className="shot-frame-viewer__field">
              <label>Dur├®e</label>
              <input
                type="text"
                value={`${shot.duration.toFixed(2)}s`}
                readOnly
                className="shot-frame-viewer__readonly"
              />
            </div>

            {/* Frame Rate */}
            <div className="shot-frame-viewer__field">
              <label htmlFor="shot-framerate">Frame Rate (fps) *</label>
              <input
                id="shot-framerate"
                type="number"
                value={shot.frameRate}
                onChange={(e) => updateField('frameRate', parseFloat(e.target.value))}
                min="1"
                max="120"
                step="0.01"
                className={getFieldError('frameRate') ? 'error' : ''}
              />
              <AnimatePresence>
                {getFieldError('frameRate') && (
                  <motion.span
                    className="shot-frame-viewer__error"
                    initial={{ opacity: 0, y: -5 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -5 }}
                  >
                    {getFieldError('frameRate')}
                  </motion.span>
                )}
              </AnimatePresence>
            </div>

            {/* In Point */}
            <div className="shot-frame-viewer__field">
              <label htmlFor="shot-inpoint">Point d'entr├®e (frames) *</label>
              <input
                id="shot-inpoint"
                type="number"
                value={shot.inPoint}
                onChange={(e) => updateField('inPoint', parseInt(e.target.value))}
                min="0"
                className={getFieldError('inPoint') ? 'error' : ''}
              />
              <AnimatePresence>
                {getFieldError('inPoint') && (
                  <motion.span
                    className="shot-frame-viewer__error"
                    initial={{ opacity: 0, y: -5 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -5 }}
                  >
                    {getFieldError('inPoint')}
                  </motion.span>
                )}
              </AnimatePresence>
              <span className="shot-frame-viewer__field-hint">
                Raccourci: Appuyez sur 'I' pour d├®finir au frame actuel
              </span>
            </div>

            {/* Out Point */}
            <div className="shot-frame-viewer__field">
              <label htmlFor="shot-outpoint">Point de sortie (frames) *</label>
              <input
                id="shot-outpoint"
                type="number"
                value={shot.outPoint}
                onChange={(e) => updateField('outPoint', parseInt(e.target.value))}
                min="1"
                className={getFieldError('outPoint') ? 'error' : ''}
              />
              <AnimatePresence>
                {getFieldError('outPoint') && (
                  <motion.span
                    className="shot-frame-viewer__error"
                    initial={{ opacity: 0, y: -5 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -5 }}
                  >
                    {getFieldError('outPoint')}
                  </motion.span>
                )}
              </AnimatePresence>
              <span className="shot-frame-viewer__field-hint">
                Raccourci: Appuyez sur 'O' pour d├®finir au frame actuel
              </span>
            </div>

            {/* Resolution */}
            <div className="shot-frame-viewer__field-group">
              <label>R├®solution</label>
              <div className="shot-frame-viewer__field-row">
                <input
                  type="number"
                  value={shot.resolution.width}
                  onChange={(e) => updateField('resolution.width', parseInt(e.target.value))}
                  min="1"
                  max="7680"
                  className={getFieldError('resolution.width') ? 'error' : ''}
                />
                <span>├ù</span>
                <input
                  type="number"
                  value={shot.resolution.height}
                  onChange={(e) => updateField('resolution.height', parseInt(e.target.value))}
                  min="1"
                  max="7680"
                  className={getFieldError('resolution.height') ? 'error' : ''}
                />
              </div>
              <AnimatePresence>
                {(getFieldError('resolution.width') || getFieldError('resolution.height')) && (
                  <motion.span
                    className="shot-frame-viewer__error"
                    initial={{ opacity: 0, y: -5 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -5 }}
                  >
                    {getFieldError('resolution.width') || getFieldError('resolution.height')}
                  </motion.span>
                )}
              </AnimatePresence>
            </div>

            {/* Position & Track */}
            <div className="shot-frame-viewer__field-group">
              <div className="shot-frame-viewer__field-row">
                <div className="shot-frame-viewer__field">
                  <label htmlFor="shot-position">Position</label>
                  <input
                    id="shot-position"
                    type="number"
                    value={shot.position}
                    onChange={(e) => updateField('position', parseInt(e.target.value))}
                    min="0"
                  />
                </div>
                <div className="shot-frame-viewer__field">
                  <label htmlFor="shot-track">Piste</label>
                  <input
                    id="shot-track"
                    type="number"
                    value={shot.track}
                    onChange={(e) => updateField('track', parseInt(e.target.value))}
                    min="0"
                  />
                </div>
              </div>
            </div>

            {/* Category */}
            <div className="shot-frame-viewer__field">
              <label htmlFor="shot-category">Cat├®gorie</label>
              <select
                id="shot-category"
                value={shot.category || ''}
                onChange={(e) => updateField('category', e.target.value || undefined)}
              >
                <option value="">Aucune</option>
                <option value="action">Action</option>
                <option value="dialogue">Dialogue</option>
                <option value="establishing">Establishing</option>
                <option value="closeup">Close-up</option>
                <option value="transition">Transition</option>
              </select>
            </div>

            {/* Status */}
            <div className="shot-frame-viewer__field">
              <label htmlFor="shot-status">Statut</label>
              <select
                id="shot-status"
                value={shot.status}
                onChange={(e) => updateField('status', e.target.value as ShotMetadata['status'])}
              >
                <option value="draft">Brouillon</option>
                <option value="ready">Pr├¬t</option>
                <option value="processing">En traitement</option>
                <option value="error">Erreur</option>
              </select>
            </div>

            {/* Tags */}
            <div className="shot-frame-viewer__field">
              <label htmlFor="shot-tags">Tags (s├®par├®s par des virgules)</label>
              <input
                id="shot-tags"
                type="text"
                value={shot.tags.join(', ')}
                onChange={(e) => updateField('tags', e.target.value.split(',').map(t => t.trim()).filter(Boolean))}
              />
            </div>

            {/* Locked */}
            <div className="shot-frame-viewer__field">
              <label>
                <input
                  type="checkbox"
                  checked={shot.locked}
                  onChange={(e) => updateField('locked', e.target.checked)}
                />
                <span>Verrouill├®</span>
              </label>
            </div>
          </div>
        </div>
      </div>

      {/* Validation Summary */}
      <AnimatePresence>
        {validationErrors.length > 0 && (
          <motion.div
            className="shot-frame-viewer__validation-summary"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 20 }}
          >
            <h4>ÔÜá Erreurs de validation</h4>
            <ul>
              {validationErrors.map((error, index) => (
                <li key={index}>
                  <strong>{error.field}:</strong> {error.message}
                </li>
              ))}
            </ul>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Frame Comparison Modal */}
      <AnimatePresence>
        {showComparison && shot.videoUrl && (
          <motion.div
            className="shot-frame-viewer__comparison-modal"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            <motion.div
              className="shot-frame-viewer__comparison-content"
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
            >
              <FrameComparisonView
                videoUrl={shot.videoUrl}
                frameRate={shot.frameRate}
                frame1={currentFrame}
                frame2={comparisonFrame}
                onClose={() => setShowComparison(false)}
              />
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default ShotFrameViewer;

/**
 * TimelineView - Displays shots in temporal sequence with drag-to-reorder
 * 
 * Features:
 * - Display shots in temporal sequence
 * - Show shot thumbnails and durations
 * - Implement drag-to-reorder functionality
 * - Add shot selection highlighting
 * - Update on storyboard changes
 * 
 * Requirements: 4.5, 5.6, 11.6, 12.2, 12.6
 */

import React, { useState, useRef, useEffect } from 'react';
import { GripVertical, Clock } from 'lucide-react';
import type { Shot } from '../../types';

export interface TimelineViewProps {
  shots: Shot[];
  selectedShotId: string | null;
  onShotSelect: (shotId: string) => void;
  onShotReorder: (shotIds: string[]) => void;
}

interface DragState {
  draggedIndex: number | null;
  dragOverIndex: number | null;
}

export const TimelineView: React.FC<TimelineViewProps> = ({
  shots,
  selectedShotId,
  onShotSelect,
  onShotReorder,
}) => {
  const [dragState, setDragState] = useState<DragState>({
    draggedIndex: null,
    dragOverIndex: null,
  });

  // Calculate total duration
  const totalDuration = shots.reduce((sum, shot) => sum + shot.duration, 0);

  // Format duration as MM:SS
  const formatDuration = (seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  // Handle drag start
  const handleDragStart = (e: React.DragEvent<HTMLDivElement>, index: number) => {
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', index.toString());
    setDragState({
      draggedIndex: index,
      dragOverIndex: null,
    });
  };

  // Handle drag over
  const handleDragOver = (e: React.DragEvent<HTMLDivElement>, index: number) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    
    if (dragState.draggedIndex !== null && dragState.draggedIndex !== index) {
      setDragState(prev => ({
        ...prev,
        dragOverIndex: index,
      }));
    }
  };

  // Handle drag leave
  const handleDragLeave = () => {
    setDragState(prev => ({
      ...prev,
      dragOverIndex: null,
    }));
  };

  // Handle drop
  const handleDrop = (e: React.DragEvent<HTMLDivElement>, dropIndex: number) => {
    e.preventDefault();
    
    const dragIndex = dragState.draggedIndex;
    if (dragIndex === null || dragIndex === dropIndex) {
      setDragState({ draggedIndex: null, dragOverIndex: null });
      return;
    }

    // Reorder shots
    const newShots = [...shots];
    const [draggedShot] = newShots.splice(dragIndex, 1);
    newShots.splice(dropIndex, 0, draggedShot);

    // Call reorder callback with new shot IDs order
    onShotReorder(newShots.map(shot => shot.id));

    // Reset drag state
    setDragState({ draggedIndex: null, dragOverIndex: null });
  };

  // Handle drag end
  const handleDragEnd = () => {
    setDragState({ draggedIndex: null, dragOverIndex: null });
  };

  // Handle shot click
  const handleShotClick = (shotId: string) => {
    onShotSelect(shotId);
  };

  return (
    <div className="flex flex-col h-full bg-gray-900">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-gray-700">
        <h3 className="text-sm font-semibold text-gray-300">Timeline</h3>
        <div className="flex items-center gap-2 text-xs text-gray-400">
          <Clock className="w-4 h-4" />
          <span>{shots.length} shot{shots.length !== 1 ? 's' : ''}</span>
          <span className="text-gray-600">ÔÇó</span>
          <span>{formatDuration(totalDuration)}</span>
        </div>
      </div>

      {/* Timeline Content */}
      <div className="flex-1 overflow-y-auto p-4">
        {shots.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-gray-500">
            <p className="text-sm">No shots in timeline</p>
            <p className="text-xs mt-1">Create a shot to get started</p>
          </div>
        ) : (
          <div className="space-y-2">
            {shots.map((shot, index) => {
              const isSelected = shot.id === selectedShotId;
              const isDragging = dragState.draggedIndex === index;
              const isDragOver = dragState.dragOverIndex === index;

              return (
                <div
                  key={shot.id}
                  draggable
                  onDragStart={(e) => handleDragStart(e, index)}
                  onDragOver={(e) => handleDragOver(e, index)}
                  onDragLeave={handleDragLeave}
                  onDrop={(e) => handleDrop(e, index)}
                  onDragEnd={handleDragEnd}
                  onClick={() => handleShotClick(shot.id)}
                  className={`
                    relative group cursor-pointer rounded-lg border-2 transition-all
                    ${isSelected 
                      ? 'border-blue-500 bg-blue-900 bg-opacity-30' 
                      : 'border-gray-700 bg-gray-800 hover:border-gray-600'
                    }
                    ${isDragging ? 'opacity-50' : ''}
                    ${isDragOver ? 'border-blue-400 border-dashed' : ''}
                  `}
                >
                  {/* Drag Handle */}
                  <div className="absolute left-2 top-1/2 -translate-y-1/2 text-gray-500 group-hover:text-gray-400 cursor-grab active:cursor-grabbing">
                    <GripVertical className="w-4 h-4" />
                  </div>

                  {/* Shot Content */}
                  <div className="flex items-center gap-3 pl-8 pr-3 py-3">
                    {/* Thumbnail */}
                    <div className="flex-shrink-0 w-20 h-12 bg-gray-700 rounded overflow-hidden">
                      {shot.image ? (
                        <img
                          src={shot.image}
                          alt={shot.title}
                          className="w-full h-full object-cover"
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center text-gray-500 text-xs">
                          No image
                        </div>
                      )}
                    </div>

                    {/* Shot Info */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="text-xs text-gray-500 font-mono">
                          #{index + 1}
                        </span>
                        <h4 className="text-sm font-medium text-white truncate">
                          {shot.title}
                        </h4>
                      </div>
                      {shot.description && (
                        <p className="text-xs text-gray-400 truncate mt-1">
                          {shot.description}
                        </p>
                      )}
                      <div className="flex items-center gap-3 mt-1">
                        <span className="text-xs text-gray-500">
                          {shot.duration}s
                        </span>
                        {shot.audioTracks && shot.audioTracks.length > 0 && (
                          <span className="text-xs text-green-400">
                            ­ƒöè {shot.audioTracks.length} track{shot.audioTracks.length > 1 ? 's' : ''}
                          </span>
                        )}
                        {shot.metadata?.status && (
                          <span className={`text-xs px-2 py-0.5 rounded ${
                            shot.metadata.status === 'ready' ? 'bg-green-900 text-green-300' :
                            shot.metadata.status === 'generating' ? 'bg-yellow-900 text-yellow-300' :
                            shot.metadata.status === 'failed' ? 'bg-red-900 text-red-300' :
                            'bg-gray-700 text-gray-400'
                          }`}>
                            {shot.metadata.status}
                          </span>
                        )}
                      </div>
                    </div>

                    {/* Duration Badge */}
                    <div className="flex-shrink-0 text-right">
                      <div className="text-xs font-mono text-gray-400">
                        {formatDuration(shot.duration)}
                      </div>
                    </div>
                  </div>

                  {/* Drop Indicator */}
                  {isDragOver && (
                    <div className="absolute inset-0 border-2 border-blue-400 border-dashed rounded-lg pointer-events-none" />
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

/**
 * Template Marketplace Panel Component
 * MI3: Template Marketplace - User template sharing
 */

import React, { useState, useEffect } from 'react';
import { useTemplateMarketplaceStore } from '../../stores/templateMarketplaceStore';
import { templateMarketplaceService } from '../../services/TemplateMarketplaceService';
import { Template, TemplateCategory } from '../../types/template-marketplace';
import styles from './TemplateMarketplacePanel.module.css';

type SortOption = 'newest' | 'popular' | 'rating' | 'price-low' | 'price-high';

export const TemplateMarketplacePanel: React.FC = () => {
  const {
    marketplace,
    userLibrary,
    selectedTemplateId,
    isPanelOpen,
    isDetailViewOpen,
    isUploadModalOpen,
    searchTemplates,
    loadMoreTemplates,
    selectTemplate,
    openDetailView,
    closeDetailView,
    downloadTemplate,
    favoriteTemplate,
    unfavoriteTemplate,
    togglePanel,
    openUploadModal,
    closeUploadModal,
  } = useTemplateMarketplaceStore();

  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState<TemplateCategory | 'all'>('all');
  const [sortBy, setSortBy] = useState<SortOption>('popular');
  const [priceFilter, setPriceFilter] = useState<'all' | 'free' | 'paid'>('all');

  // Load featured templates on mount
  useEffect(() => {
    templateMarketplaceService.getFeaturedTemplates().then((templates) => {
      useTemplateMarketplaceStore.setState((state) => ({
        marketplace: {
          ...state.marketplace,
          templates,
          featuredTemplates: templates.map((t) => t.id),
        },
      }));
    });
  }, []);

  // Search when filters change
  useEffect(() => {
    searchTemplates({
      query: searchQuery,
      categories: activeCategory === 'all' ? [] : [activeCategory as TemplateCategory],
      sortBy,
      price: priceFilter,
      page: 1,
    });
  }, [searchQuery, activeCategory, sortBy, priceFilter]);

  const handleTemplateClick = (template: Template) => {
    selectTemplate(template.id);
    openDetailView(template.id);
  };

  const handleDownload = async (templateId: string) => {
    await downloadTemplate(templateId);
  };

  const handleToggleFavorite = (templateId: string) => {
    if (userLibrary.favorites.includes(templateId)) {
      unfavoriteTemplate(templateId);
    } else {
      favoriteTemplate(templateId);
    }
  };

  const categories: { id: TemplateCategory | 'all'; label: string; icon: string }[] = [
    { id: 'all', label: 'All', icon: '­ƒôª' },
    { id: 'intro', label: 'Intro', icon: '­ƒÄ¼' },
    { id: 'transitions', label: 'Transitions', icon: '­ƒöÇ' },
    { id: 'lower-thirds', label: 'Lower Thirds', icon: '­ƒÅÀ´©Å' },
    { id: 'titles', label: 'Titles', icon: 'Ô£¿' },
    { id: 'social-media', label: 'Social', icon: '­ƒô▒' },
    { id: 'promotional', label: 'Promo', icon: '­ƒôó' },
  ];

  if (!isPanelOpen) {
    return (
      <button className={styles.toggleButton} onClick={togglePanel}>
        ­ƒøÆ Marketplace
      </button>
    );
  }

  return (
    <div className={styles.panel}>
      <div className={styles.header}>
        <h3>Template Marketplace</h3>
        <div className={styles.headerActions}>
          <button className={styles.uploadBtn} onClick={openUploadModal}>
            Ô¼å´©Å Upload
          </button>
          <button className={styles.closeButton} onClick={togglePanel}>
            ├ù
          </button>
        </div>
      </div>

      <div className={styles.content}>
        {/* Search Bar */}
        <div className={styles.searchBar}>
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search templates..."
            className={styles.searchInput}
          />
        </div>

        {/* Filters */}
        <div className={styles.filters}>
          <select
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value as SortOption)}
            className={styles.select}
          >
            <option value="popular">Most Popular</option>
            <option value="newest">Newest</option>
            <option value="rating">Highest Rated</option>
            <option value="price-low">Price: Low to High</option>
            <option value="price-high">Price: High to Low</option>
          </select>

          <select
            value={priceFilter}
            onChange={(e) => setPriceFilter(e.target.value as 'all' | 'free' | 'paid')}
            className={styles.select}
          >
            <option value="all">All Prices</option>
            <option value="free">Free</option>
            <option value="paid">Paid</option>
          </select>
        </div>

        {/* Categories */}
        <div className={styles.categories}>
          {categories.map((cat) => (
            <button
              key={cat.id}
              className={`${styles.categoryChip} ${
                activeCategory === cat.id ? styles.active : ''
              }`}
              onClick={() => setActiveCategory(cat.id)}
            >
              <span className={styles.catIcon}>{cat.icon}</span>
              <span className={styles.catLabel}>{cat.label}</span>
            </button>
          ))}
        </div>

        {/* Templates Grid */}
        <div className={styles.templatesGrid}>
          {marketplace.templates.map((template) => (
            <div
              key={template.id}
              className={`${styles.templateCard} ${
                selectedTemplateId === template.id ? styles.selected : ''
              }`}
              onClick={() => handleTemplateClick(template)}
            >
              <div
                className={styles.templateThumb}
                style={{ backgroundImage: `url(${template.thumbnail})` }}
              >
                {template.isFeatured && (
                  <span className={styles.featuredBadge}>Featured</span>
                )}
                {template.pricing.type === 'free' && (
                  <span className={styles.freeBadge}>Free</span>
                )}
              </div>

              <div className={styles.templateInfo}>
                <h4 className={styles.templateName}>{template.name}</h4>
                <p className={styles.templateDesc}>{template.description}</p>
                <div className={styles.templateMeta}>
                  <span className={styles.author}>
                    by {template.author.displayName}
                  </span>
                  <div className={styles.stats}>
                    <span>Ô¼ç´©Å {template.statistics.downloads}</span>
                    <span>Ô¡É {template.statistics.rating.toFixed(1)}</span>
                  </div>
                </div>
              </div>

              <div className={styles.templateActions}>
                <button
                  className={`${styles.favBtn} ${
                    userLibrary.favorites.includes(template.id) ? styles.active : ''
                  }`}
                  onClick={(e) => {
                    e.stopPropagation();
                    handleToggleFavorite(template.id);
                  }}
                >
                  {userLibrary.favorites.includes(template.id) ? 'ÔØñ´©Å' : '­ƒñì'}
                </button>
                <button
                  className={styles.downloadBtn}
                  onClick={(e) => {
                    e.stopPropagation();
                    handleDownload(template.id);
                  }}
                >
                  {template.pricing.type === 'free' ? 'Download' : 
                   `$${template.pricing.price}`}
                </button>
              </div>
            </div>
          ))}
        </div>

        {/* Load More */}
        {marketplace.hasMore && (
          <button
            className={styles.loadMoreBtn}
            onClick={loadMoreTemplates}
            disabled={marketplace.isLoading}
          >
            {marketplace.isLoading ? 'Loading...' : 'Load More'}
          </button>
        )}

        {/* User Library */}
        <div className={styles.librarySection}>
          <h4 className={styles.sectionTitle}>My Library</h4>
          <div className={styles.libraryStats}>
            <div className={styles.statItem}>
              <span className={styles.statValue}>
                {userLibrary.purchasedTemplates.length}
              </span>
              <span className={styles.statLabel}>Purchased</span>
            </div>
            <div className={styles.statItem}>
              <span className={styles.statValue}>
                {userLibrary.downloadedTemplates.length}
              </span>
              <span className={styles.statLabel}>Downloaded</span>
            </div>
            <div className={styles.statItem}>
              <span className={styles.statValue}>
                {userLibrary.favorites.length}
              </span>
              <span className={styles.statLabel}>Favorites</span>
            </div>
          </div>
        </div>
      </div>

      {/* Detail View Modal */}
      {isDetailViewOpen && selectedTemplateId && (
        <div className={styles.modal} onClick={closeDetailView}>
          <div className={styles.modalContent} onClick={(e) => e.stopPropagation()}>
            <button className={styles.modalClose} onClick={closeDetailView}>
              ├ù
            </button>
            <TemplateDetailView templateId={selectedTemplateId} />
          </div>
        </div>
      )}

      {/* Upload Modal */}
      {isUploadModalOpen && (
        <div className={styles.modal} onClick={closeUploadModal}>
          <div className={styles.modalContent} onClick={(e) => e.stopPropagation()}>
            <div className={styles.modalHeader}>
              <h3>Upload Template</h3>
              <button className={styles.modalClose} onClick={closeUploadModal}>
                ├ù
              </button>
            </div>
            <div className={styles.modalBody}>
              <p>Template upload form would go here</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// Template Detail View Component
const TemplateDetailView: React.FC<{ templateId: string }> = ({ templateId }) => {
  const { marketplace } = useTemplateMarketplaceStore();
  const template = marketplace.templates.find((t) => t.id === templateId);

  if (!template) return null;

  return (
    <div className={styles.detailView}>
      <div
        className={styles.detailThumb}
        style={{ backgroundImage: `url(${template.thumbnail})` }}
      />
      <div className={styles.detailContent}>
        <h2>{template.name}</h2>
        <p className={styles.detailDesc}>{template.description}</p>
        
        <div className={styles.detailMeta}>
          <span>by {template.author.displayName}</span>
          <span>Ô¼ç´©Å {template.statistics.downloads}</span>
          <span>Ô¡É {template.statistics.rating.toFixed(1)}</span>
        </div>

        <div className={styles.detailPricing}>
          {template.pricing.type === 'free' ? (
            <span className={styles.freeTag}>Free</span>
          ) : (
            <span className={styles.priceTag}>${template.pricing.price}</span>
          )}
        </div>

        <div className={styles.detailFeatures}>
          {template.features.map((feature) => (
            <div key={feature.id} className={styles.feature}>
              <span>Ô£ô {feature.name}</span>
            </div>
          ))}
        </div>

        <div className={styles.detailActions}>
          <button className={styles.primaryBtn}>
            {template.pricing.type === 'free' ? 'Download' : 'Purchase'}
          </button>
          <button className={styles.secondaryBtn}>Add to Collection</button>
        </div>
      </div>
    </div>
  );
};

export default TemplateMarketplacePanel;

