/**
 * TransitionWrapper Component
 * Main wrapper component for applying transitions to any content
 */

import React, { CSSProperties, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  TransitionConfig,
  TransitionState,
  TransitionPreset,
  TransitionCategory,
  FadeTransitionConfig,
  SlideTransitionConfig,
  ZoomTransitionConfig,
  WipeTransitionConfig,
  GlitchTransitionConfig,
  GPUMode,
} from '../../services/transitions';
import { useTransition, useCSSTransition, TRANSITION_CSS_CLASSES } from '../../hooks/useTransition';

// ============================================
// Props
// ============================================

export interface TransitionWrapperProps {
  /** Child content to apply transition to */
  children: React.ReactNode;
  
  /** Transition configuration */
  config?: Partial<TransitionConfig>;
  
  /** Preset ID to use */
  presetId?: string;
  
  /** Whether the transition should trigger automatically */
  autoTrigger?: boolean;
  
  /** Trigger dependency - when this changes, transition runs */
  trigger?: unknown;
  
  /** Transition direction */
  direction?: 'forward' | 'backward';
  
  /** Whether to preserve the old content during transition */
  preserveOldContent?: boolean;
  
  /** Custom CSS class for the container */
  className?: string;
  
  /** Custom styles for the container */
  style?: CSSProperties;
  
  /** Canvas ref for WebGL transitions */
  canvasRef?: React.RefObject<HTMLCanvasElement | null>;
  
  /** Callback when transition starts */
  onTransitionStart?: () => void;
  
  /** Callback when transition completes */
  onTransitionComplete?: () => void;
  
  /** Callback on each progress update */
  onProgressUpdate?: (progress: number) => void;
  
  /** Render function for old content (when preserveOldContent is true) */
  renderOldContent?: () => React.ReactNode;
  
  /** Render function for new content */
  renderNewContent?: (progress: number) => React.ReactNode;
}

// ============================================
// Default Props
// ============================================

const defaultProps: Partial<TransitionWrapperProps> = {
  autoTrigger: false,
  preserveOldContent: true,
  direction: 'forward',
};

// ============================================
// CSS Styles
// ============================================

const styles: Record<string, CSSProperties> = {
  container: {
    position: 'relative',
    overflow: 'hidden',
    width: '100%',
    height: '100%',
  },
  oldContent: {
    position: 'absolute',
    top: 0,
    left: 0,
    width: '100%',
    height: '100%',
    zIndex: 1,
  },
  newContent: {
    position: 'absolute',
    top: 0,
    left: 0,
    width: '100%',
    height: '100%',
    zIndex: 2,
  },
  canvas: {
    position: 'absolute',
    top: 0,
    left: 0,
    width: '100%',
    height: '100%',
    zIndex: 3,
  },
};

// ============================================
// Component
// ============================================

export const TransitionWrapper: React.FC<TransitionWrapperProps> = (props) => {
  const {
    children,
    config,
    presetId,
    autoTrigger,
    trigger,
    direction,
    preserveOldContent,
    className,
    style,
    canvasRef,
    onTransitionStart,
    onTransitionComplete,
    onProgressUpdate,
    renderOldContent,
    renderNewContent,
  } = { ...defaultProps, ...props };

  const internalCanvasRef = useRef<HTMLCanvasElement>(null);
  const effectiveCanvasRef = canvasRef || internalCanvasRef;
  const [oldChildren, setOldChildren] = useState<React.ReactNode>(null);
  const [newChildren, setNewChildren] = useState<React.ReactNode>(children);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [progress, setProgress] = useState(0);

  // WebGL-based transition
  const {
    state,
    isActive,
    isComplete,
    start,
    cancel,
    reset,
    applyPreset,
    getPreset,
    getPresets,
    getPresetsByCategory,
    metrics,
    engine,
  } = useTransition(effectiveCanvasRef, config);

  // CSS-based transition helper
  const {
    isTransitioning: cssTransitioning,
    fadeOut,
    fadeIn,
    slideLeft,
    slideRight,
    zoomIn,
    zoomOut,
  } = useCSSTransition(useRef<HTMLDivElement>(null));

  // Apply preset if specified
  useEffect(() => {
    if (presetId && engine) {
      const preset = getPreset(presetId);
      if (preset) {
        start(preset.defaultConfig);
      }
    }
  }, [presetId, engine, getPreset, start]);

  // Handle trigger changes
  useEffect(() => {
    if (autoTrigger && trigger !== undefined) {
      // Store old children
      if (preserveOldContent) {
        setOldChildren(newChildren);
      }
      
      // Update new children
      setNewChildren(children);
      
      // Start transition
      if (presetId && engine) {
        applyPreset(presetId);
      } else if (config) {
        start(config as TransitionConfig);
      } else {
        // Default to fade
        fadeOut();
        setTimeout(() => {
          fadeIn();
          setIsTransitioning(true);
        }, 100);
      }
    }
  }, [autoTrigger, trigger, children, preserveOldContent, presetId, config, engine, applyPreset, start, fadeOut, fadeIn]);

  // Update progress
  useEffect(() => {
    setProgress(state.progress);
    onProgressUpdate?.(state.progress);

    if (state.phase === 'running') {
      setIsTransitioning(true);
      onTransitionStart?.();
    }

    if (state.phase === 'complete') {
      setIsTransitioning(false);
      setOldChildren(null);
      onTransitionComplete?.();
    }
  }, [state, onTransitionStart, onTransitionComplete, onProgressUpdate]);

  // Render content based on transition type
  const renderTransitionContent = useMemo(() => {
    if (!isTransitioning && !isActive) {
      return (
        <div style={styles.newContent}>
          {renderNewContent ? renderNewContent(1) : newChildren}
        </div>
      );
    }

    return (
      <>
        {preserveOldContent && oldChildren && (
          <div style={styles.oldContent}>
            {renderOldContent ? renderOldContent() : oldChildren}
          </div>
        )}
        <div style={styles.newContent}>
          {renderNewContent ? renderNewContent(progress) : newChildren}
        </div>
      </>
    );
  }, [isTransitioning, isActive, progress, preserveOldContent, oldChildren, newChildren, renderOldContent, renderNewContent]);

  return (
    <>
      <style>{TRANSITION_CSS_CLASSES}</style>
      <div
        className={`transition-wrapper ${className || ''}`}
        style={{ ...styles.container, ...style }}
      >
        {renderTransitionContent}
        <canvas
          ref={effectiveCanvasRef}
          style={styles.canvas}
          width={style?.width || 800}
          height={style?.height || 600}
        />
      </div>
    </>
  );
};

// ============================================
// Preset Selector Component
// ============================================

export interface TransitionPresetSelectorProps {
  /** Currently selected preset ID */
  selectedPresetId?: string;
  
  /** Callback when a preset is selected */
  onSelect?: (presetId: string) => void;
  
  /** Filter by category */
  category?: TransitionCategory;
  
  /** Custom class name */
  className?: string;
  
  /** Show thumbnails */
  showThumbnails?: boolean;
  
  /** Custom styles */
  style?: CSSProperties;
}

export const TransitionPresetSelector: React.FC<TransitionPresetSelectorProps> = ({
  selectedPresetId,
  onSelect,
  category,
  className,
  showThumbnails = true,
  style,
}) => {
  const presets = useMemo(() => {
    // This would normally get presets from the engine
    // For now, return a static list
    const allPresets: TransitionPreset[] = [
      { id: 'fade-black', name: 'Fade to Black', category: 'fade', description: 'Smooth fade to black', defaultConfig: { type: 'fade', duration: 500, easing: 'easeInOut', gpuMode: 'auto', performanceTier: 'high', fadeType: 'black' } as FadeTransitionConfig, tags: ['fade', 'black'], gpuSupported: true, performanceRating: 5 },
      { id: 'fade-white', name: 'Fade to White', category: 'fade', description: 'Smooth fade to white', defaultConfig: { type: 'fade', duration: 500, easing: 'easeInOut', gpuMode: 'auto', performanceTier: 'high', fadeType: 'white' } as FadeTransitionConfig, tags: ['fade', 'white'], gpuSupported: true, performanceRating: 5 },
      { id: 'fade-cross', name: 'Cross Fade', category: 'fade', description: 'Cross dissolve between clips', defaultConfig: { type: 'fade', duration: 600, easing: 'linear', gpuMode: 'auto', performanceTier: 'high', fadeType: 'cross' } as FadeTransitionConfig, tags: ['fade', 'cross'], gpuSupported: true, performanceRating: 5 },
      { id: 'slide-left', name: 'Slide Left', category: 'slide', description: 'Slide from right to left', defaultConfig: { type: 'slide', duration: 400, easing: 'easeOut', gpuMode: 'auto', performanceTier: 'high', direction: 'left' } as SlideTransitionConfig, tags: ['slide', 'left'], gpuSupported: true, performanceRating: 5 },
      { id: 'slide-right', name: 'Slide Right', category: 'slide', description: 'Slide from left to right', defaultConfig: { type: 'slide', duration: 400, easing: 'easeOut', gpuMode: 'auto', performanceTier: 'high', direction: 'right' } as SlideTransitionConfig, tags: ['slide', 'right'], gpuSupported: true, performanceRating: 5 },
      { id: 'slide-up', name: 'Slide Up', category: 'slide', description: 'Slide from bottom to top', defaultConfig: { type: 'slide', duration: 400, easing: 'easeOut', gpuMode: 'auto', performanceTier: 'high', direction: 'up' } as SlideTransitionConfig, tags: ['slide', 'up'], gpuSupported: true, performanceRating: 5 },
      { id: 'slide-down', name: 'Slide Down', category: 'slide', description: 'Slide from top to bottom', defaultConfig: { type: 'slide', duration: 400, easing: 'easeOut', gpuMode: 'auto', performanceTier: 'high', direction: 'down' } as SlideTransitionConfig, tags: ['slide', 'down'], gpuSupported: true, performanceRating: 5 },
      { id: 'zoom-in', name: 'Zoom In', category: 'zoom', description: 'Zoom into next clip', defaultConfig: { type: 'zoom', duration: 500, easing: 'easeInOut', gpuMode: 'auto', performanceTier: 'high', zoomType: 'in', intensity: 1.5 } as ZoomTransitionConfig, tags: ['zoom', 'in'], gpuSupported: true, performanceRating: 5 },
      { id: 'zoom-out', name: 'Zoom Out', category: 'zoom', description: 'Zoom out of current clip', defaultConfig: { type: 'zoom', duration: 500, easing: 'easeInOut', gpuMode: 'auto', performanceTier: 'high', zoomType: 'out', intensity: 0.5 } as ZoomTransitionConfig, tags: ['zoom', 'out'], gpuSupported: true, performanceRating: 5 },
      { id: 'zoom-pulsar', name: 'Pulsar Zoom', category: 'zoom', description: 'Dynamic zoom with pulse', defaultConfig: { type: 'zoom', duration: 600, easing: 'elastic', gpuMode: 'auto', performanceTier: 'high', zoomType: 'pulsar', intensity: 2.0 } as ZoomTransitionConfig, tags: ['zoom', 'pulsar', 'dynamic'], gpuSupported: true, performanceRating: 4 },
      { id: 'wipe-linear', name: 'Linear Wipe', category: 'wipe', description: 'Linear wipe transition', defaultConfig: { type: 'wipe', duration: 400, easing: 'linear', gpuMode: 'auto', performanceTier: 'high', wipeType: 'linear', direction: 'left' } as WipeTransitionConfig, tags: ['wipe', 'linear'], gpuSupported: true, performanceRating: 5 },
      { id: 'wipe-radial', name: 'Radial Wipe', category: 'wipe', description: 'Radial wipe from center', defaultConfig: { type: 'wipe', duration: 500, easing: 'easeInOut', gpuMode: 'auto', performanceTier: 'high', wipeType: 'radial', direction: 'left' } as WipeTransitionConfig, tags: ['wipe', 'radial'], gpuSupported: true, performanceRating: 5 },
      { id: 'glitch-rgb', name: 'RGB Glitch', category: 'glitch', description: 'RGB split glitch effect', defaultConfig: { type: 'glitch', duration: 300, easing: 'linear', gpuMode: 'auto', performanceTier: 'high', glitchType: 'rgbSplit', intensity: 0.5 } as GlitchTransitionConfig, tags: ['glitch', 'rgb', 'vhs'], gpuSupported: true, performanceRating: 4 },
      { id: 'glitch-noise', name: 'Noise Glitch', category: 'glitch', description: 'Digital noise glitch', defaultConfig: { type: 'glitch', duration: 400, easing: 'linear', gpuMode: 'auto', performanceTier: 'high', glitchType: 'noise', intensity: 0.7 } as GlitchTransitionConfig, tags: ['glitch', 'noise', 'static'], gpuSupported: true, performanceRating: 4 },
    ];

    if (category) {
      return allPresets.filter(p => p.category === category);
    }
    return allPresets;
  }, [category]);

  return (
    <div className={`transition-preset-selector ${className || ''}`} style={style}>
      <div className="preset-grid" style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fill, minmax(120px, 1fr))',
        gap: '8px',
        padding: '8px',
      }}>
        {presets.map((preset) => (
          <div
            key={preset.id}
            className={`preset-item ${selectedPresetId === preset.id ? 'selected' : ''}`}
            onClick={() => onSelect?.(preset.id)}
            style={{
              padding: '12px',
              border: selectedPresetId === preset.id ? '2px solid #007bff' : '1px solid #ddd',
              borderRadius: '8px',
              cursor: 'pointer',
              textAlign: 'center',
              transition: 'all 0.2s ease',
              background: selectedPresetId === preset.id ? '#e7f1ff' : '#fff',
            }}
          >
            {showThumbnails && (
              <div
                className="preset-thumbnail"
                style={{
                  width: '100%',
                  height: '60px',
                  background: `linear-gradient(135deg, #667eea 0%, #764ba2 100%)`,
                  borderRadius: '4px',
                  marginBottom: '8px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  color: '#fff',
                  fontSize: '12px',
                }}
              >
                {preset.category.toUpperCase()}
              </div>
            )}
            <div className="preset-name" style={{ fontWeight: 500, fontSize: '14px' }}>
              {preset.name}
            </div>
            <div className="preset-description" style={{ fontSize: '11px', color: '#666', marginTop: '4px' }}>
              {preset.description}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

// ============================================
// Progress Bar Component
// ============================================

export interface TransitionProgressBarProps {
  /** Current progress (0-1) */
  progress: number;
  
  /** Whether transition is active */
  isActive?: boolean;
  
  /** Custom class name */
  className?: string;
  
  /** Custom styles */
  style?: CSSProperties;
  
  /** Bar color */
  color?: string;
  
  /** Bar height */
  height?: number;
}

export const TransitionProgressBar: React.FC<TransitionProgressBarProps> = ({
  progress,
  isActive = true,
  className,
  style,
  color = '#007bff',
  height = 4,
}) => {
  return (
    <div
      className={`transition-progress-bar ${className || ''}`}
      style={{
        width: '100%',
        height: `${height}px`,
        background: '#e0e0e0',
        borderRadius: `${height / 2}px`,
        overflow: 'hidden',
        ...style,
      }}
    >
      <div
        className="progress-fill"
        style={{
          width: `${progress * 100}%`,
          height: '100%',
          background: color,
          borderRadius: `${height / 2}px`,
          transition: isActive ? 'width 0.05s linear' : 'none',
        }}
      />
    </div>
  );
};

// ============================================
// Metrics Display Component
// ============================================

export interface TransitionMetricsDisplayProps {
  /** Metrics to display */
  metrics: {
    totalTime?: number;
    averageFPS?: number;
    minFPS?: number;
    maxFPS?: number;
    gpuMemoryPeak?: number;
    frameDrops?: number;
    cpuTimePerFrame?: number;
    gpuTimePerFrame?: number;
  } | null;
  
  /** Custom class name */
  className?: string;
  
  /** Custom styles */
  style?: CSSProperties;
  
  /** Whether to show detailed metrics */
  showDetails?: boolean;
}

export const TransitionMetricsDisplay: React.FC<TransitionMetricsDisplayProps> = ({
  metrics,
  className,
  style,
  showDetails = false,
}) => {
  if (!metrics) {
    return (
      <div className={`transition-metrics ${className || ''}`} style={style}>
        No metrics available
      </div>
    );
  }

  return (
    <div
      className={`transition-metrics ${className || ''}`}
      style={{
        padding: '12px',
        background: '#f5f5f5',
        borderRadius: '8px',
        fontSize: '12px',
        fontFamily: 'monospace',
        ...style,
      }}
    >
      <div style={{ fontWeight: 600, marginBottom: '8px' }}>Transition Metrics</div>
      <div>Total Time: {metrics.totalTime?.toFixed(2) || 0}ms</div>
      <div>Average FPS: {metrics.averageFPS || 0}</div>
      <div>Min FPS: {metrics.minFPS || 0}</div>
      <div>Max FPS: {metrics.maxFPS || 0}</div>
      {showDetails && (
        <>
          <div>Frame Drops: {metrics.frameDrops || 0}</div>
          <div>GPU Memory: {metrics.gpuMemoryPeak ? `${(metrics.gpuMemoryPeak / 1024 / 1024).toFixed(2)}MB` : 'N/A'}</div>
          <div>CPU/frame: {metrics.cpuTimePerFrame?.toFixed(2) || 0}ms</div>
          <div>GPU/frame: {metrics.gpuTimePerFrame?.toFixed(2) || 0}ms</div>
        </>
      )}
    </div>
  );
};

/**
 * Error Notification Component
 * 
 * Toast-style notification for displaying errors and success messages
 * Based on existing src/ui/ErrorNotification.tsx with enhancements
 */

import React, { useState, useEffect } from 'react';

export type NotificationType = 'error' | 'warning' | 'info' | 'success';

export interface NotificationAction {
  label: string;
  onClick: () => void;
  primary?: boolean;
}

export interface Notification {
  id: string;
  type: NotificationType;
  title: string;
  message: string;
  actions?: NotificationAction[];
  autoClose?: boolean;
  duration?: number;
}

interface ErrorNotificationProps {
  notifications: Notification[];
  onDismiss: (id: string) => void;
}

export function ErrorNotification({
  notifications,
  onDismiss
}: ErrorNotificationProps) {
  const [visibleNotifications, setVisibleNotifications] = useState<Notification[]>([]);

  useEffect(() => {
    setVisibleNotifications(notifications);
  }, [notifications]);

  const handleDismiss = (id: string) => {
    setVisibleNotifications(prev => prev.filter(n => n.id !== id));
    onDismiss(id);
  };

  if (notifications.length === 0) return null;

  const getNotificationStyle = (type: NotificationType): React.CSSProperties => {
    const baseStyle: React.CSSProperties = {
      padding: '12px 16px',
      marginBottom: '10px',
      borderRadius: '4px',
      border: '1px solid',
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'flex-start',
      position: 'relative',
      animation: 'slideIn 0.3s ease-out'
    };

    switch (type) {
      case 'error':
        return { ...baseStyle, backgroundColor: '#f8d7da', borderColor: '#f5c6cb', color: '#721c24' };
      case 'warning':
        return { ...baseStyle, backgroundColor: '#fff3cd', borderColor: '#ffeaa7', color: '#856404' };
      case 'info':
        return { ...baseStyle, backgroundColor: '#d1ecf1', borderColor: '#bee5eb', color: '#0c5460' };
      case 'success':
        return { ...baseStyle, backgroundColor: '#d4edda', borderColor: '#c3e6cb', color: '#155724' };
      default:
        return baseStyle;
    }
  };

  const containerStyle: React.CSSProperties = {
    position: 'fixed',
    top: '20px',
    right: '20px',
    zIndex: 1000,
    maxWidth: '400px',
    minWidth: '300px'
  };

  return (
    <div style={containerStyle}>
      {notifications.map(notification => (
        <div key={notification.id} style={getNotificationStyle(notification.type)}>
          <div style={{ flex: 1 }}>
            <div style={{ fontWeight: 'bold', marginBottom: '4px' }}>{notification.title}</div>
            <div style={{ fontSize: '14px' }}>{notification.message}</div>
            {notification.actions && notification.actions.length > 0 && (
              <div style={{ marginTop: '8px' }}>
                {notification.actions.map((action, index) => (
                  <button
                    key={index}
                    onClick={action.onClick}
                    style={{
                      marginRight: '8px',
                      padding: '4px 8px',
                      border: 'none',
                      borderRadius: '3px',
                      cursor: 'pointer',
                      backgroundColor: action.primary ? '#007bff' : '#6c757d',
                      color: 'white',
                      fontSize: '12px'
                    }}
                  >
                    {action.label}
                  </button>
                ))}
              </div>
            )}
          </div>
          <button
            onClick={() => handleDismiss(notification.id)}
            style={{
              background: 'none',
              border: 'none',
              fontSize: '18px',
              cursor: 'pointer',
              marginLeft: '8px',
              color: 'inherit',
              opacity: 0.7
            }}
            aria-label="Close notification"
          >
            ├ù
          </button>
        </div>
      ))}
    </div>
  );
}

/**
 * Notification Container Component
 * Alias for ErrorNotification for compatibility
 */
export interface NotificationContainerProps {
  notifications: Notification[];
  onRemove: (id: string) => void;
  position?: 'top-right' | 'top-left' | 'bottom-right' | 'bottom-left';
}

export function NotificationContainer({
  notifications,
  onRemove,
  position = 'top-right',
}: NotificationContainerProps) {
  return <ErrorNotification notifications={notifications} onDismiss={onRemove} />;
}

/**
 * Field Highlight Component
 * 
 * Wrapper component and utility for highlighting form fields with errors
 */

import React from 'react';

export interface FieldHighlightProps {
  hasError?: boolean;
  children: React.ReactNode;
  className?: string;
  baseStyle?: React.CSSProperties;
}

export function FieldHighlight({ 
  hasError = false, 
  children, 
  className = '',
  baseStyle = {}
}: FieldHighlightProps) {
  const style: React.CSSProperties = hasError ? {
    ...baseStyle,
    borderColor: '#dc3545',
    boxShadow: '0 0 0 0.2rem rgba(220, 53, 69, 0.25)'
  } : baseStyle;

  return (
    <div className={className} style={style}>
      {children}
    </div>
  );
}

/**
 * Utility function to get field styles with error state
 */
export function getFieldStyle(hasError: boolean, baseStyle: React.CSSProperties = {}): React.CSSProperties {
  const defaultBaseStyle: React.CSSProperties = {
    width: '100%',
    padding: '8px',
    border: '1px solid #ccc',
    borderRadius: '4px'
  };

  const errorStyle: React.CSSProperties = {
    borderColor: '#dc3545'
  };

  return hasError
    ? { ...defaultBaseStyle, ...baseStyle, ...errorStyle }
    : { ...defaultBaseStyle, ...baseStyle };
}

/**
 * Enhanced Input component with error highlighting
 */
export interface EnhancedInputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  hasError?: boolean;
  baseStyle?: React.CSSProperties;
}

export function EnhancedInput({
  hasError = false,
  baseStyle = {},
  ...inputProps
}: EnhancedInputProps) {
  const style = getFieldStyle(hasError, baseStyle);
  return <input {...inputProps} style={style} />;
}

/**
 * ModalFramework Component
 *
 * Generic modal component that renders forms based on declarative schema configuration.
 * Integrates state management, validation, persistence, and connection testing.
 */

import React, { useCallback } from 'react';
import { Save, TestTube, Loader2, CheckCircle, XCircle } from 'lucide-react';
import { ModalOverlay } from './ModalOverlay';
import { FormField } from './FormField';
import { useModalState } from '@/hooks/useModalState';
import { useModalValidation } from '@/hooks/useModalValidation';
import { useModalConnectionTest } from '@/hooks/useModalConnectionTest';
import { useModalPersistence } from '@/hooks/useModalPersistence';
import type { GenericModalProps } from '@/types/modal';

/**
 * Generic modal framework component
 */
export function ModalFramework({
  schema,
  isOpen,
  onClose,
  onSubmit,
  initialData,
  persistence,
}: GenericModalProps) {
  // State management
  const modalState = useModalState(schema, initialData);

  // Validation
  const { validate } = useModalValidation(schema);

  // Connection testing
  const { testConnection, getConnectionTestMessages } = useModalConnectionTest(schema);
  const connectionMessages = getConnectionTestMessages();

  // Persistence
  const { saveDraft } = useModalPersistence(schema, persistence);

  // Submit handler
  const handleSubmit = useCallback(async (event: React.FormEvent) => {
    event.preventDefault();

    // Validate form
    const validationResult = validate(modalState.data);
    modalState.setValidationErrors(validationResult.errors);

    if (!validationResult.isValid) {
      return;
    }

    // Set loading state
    modalState.setLoadingState('submit', true);

    try {
      await onSubmit(modalState.data);
      modalState.close();
    } catch (error) {
      // Error handling is done by the parent component
    } finally {
      modalState.setLoadingState('submit', false);
    }
  }, [modalState, validate, onSubmit]);

  // Connection test handler
  const handleConnectionTest = useCallback(async () => {
    modalState.setLoadingState('connectionTest', true);
    modalState.setConnectionStatus('testing');

    try {
      const result = await testConnection(modalState.data);

      if (result.success) {
        modalState.setConnectionStatus('success');
      } else {
        modalState.setConnectionStatus('error');
      }
    } catch (error) {
      modalState.setConnectionStatus('error');
    } finally {
      modalState.setLoadingState('connectionTest', false);
    }
  }, [modalState, testConnection]);

  // Save draft handler
  const handleSaveDraft = useCallback(async () => {
    try {
      await saveDraft(modalState.data);
      // Could show a toast notification here
    } catch (error) {
      // Error handling for draft save
    }
  }, [modalState.data, saveDraft]);

  // Group fields by layout.group
  const groupedFields = schema.fields.reduce((groups, field) => {
    const group = field.layout?.group || 'default';
    if (!groups[group]) {
      groups[group] = [];
    }
    groups[group].push(field);
    return groups;
  }, {} as Record<string, typeof schema.fields>);

  // Get modal size classes
  const getSizeClasses = () => {
    switch (schema.size) {
      case 'sm': return 'max-w-md';
      case 'lg': return 'max-w-4xl';
      case 'xl': return 'max-w-7xl';
      default: return 'max-w-2xl';
    }
  };

  return (
    <ModalOverlay isOpen={isOpen} onClose={onClose}>
      <div className={`bg-white rounded-lg shadow-xl ${getSizeClasses()}`}>
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-gray-200">
          <h2 className="text-xl font-semibold text-gray-900">{schema.title}</h2>
        </div>

        {/* Description */}
        {schema.description && (
          <div className="px-6 py-4 bg-gray-50 border-b border-gray-200">
            <p className="text-sm text-gray-600">{schema.description}</p>
          </div>
        )}

        {/* Form */}
        <form onSubmit={handleSubmit} className="p-6">
          <div className="space-y-6">
            {Object.entries(groupedFields).map(([groupName, fields]) => (
              <div key={groupName} className="space-y-4">
                {groupName !== 'default' && (
                  <h3 className="text-lg font-medium text-gray-900 border-b border-gray-200 pb-2">
                    {groupName}
                  </h3>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {fields.map(field => (
                    <FormField
                      key={field.id}
                      field={field}
                      value={modalState.data[field.id]}
                      error={modalState.errors[field.id]}
                      onChange={(value) => modalState.updateField(field.id, value)}
                      disabled={modalState.loading.submit}
                    />
                  ))}
                </div>
              </div>
            ))}
          </div>

          {/* Connection Test Section */}
          {schema.enableConnectionTest && (
            <div className="mt-6 p-4 bg-gray-50 rounded-lg">
              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-3">
                  {modalState.connectionStatus === 'success' && (
                    <CheckCircle className="w-5 h-5 text-green-500" />
                  )}
                  {modalState.connectionStatus === 'error' && (
                    <XCircle className="w-5 h-5 text-red-500" />
                  )}
                  {modalState.connectionStatus === 'testing' && (
                    <Loader2 className="w-5 h-5 text-blue-500 animate-spin" />
                  )}

                  <span className="text-sm font-medium text-gray-700">
                    Test de connexion
                  </span>
                </div>

                <button
                  type="button"
                  onClick={handleConnectionTest}
                  disabled={modalState.loading.connectionTest || modalState.loading.submit}
                  className="flex items-center space-x-2 px-3 py-1.5 text-sm bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {modalState.loading.connectionTest ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : (
                    <TestTube className="w-4 h-4" />
                  )}
                  <span>Tester</span>
                </button>
              </div>

              {modalState.connectionStatus === 'success' && (
                <div className="mt-2 text-sm text-green-600">
                  {connectionMessages.successMessage}
                </div>
              )}

              {modalState.connectionStatus === 'error' && (
                <div className="mt-2 text-sm text-red-600">
                  {connectionMessages.errorMessage}
                </div>
              )}
            </div>
          )}

          {/* Actions */}
          <div className="flex items-center justify-between mt-8 pt-6 border-t border-gray-200">
            <div className="flex space-x-3">
              <button
                type="button"
                onClick={handleSaveDraft}
                disabled={modalState.loading.submit}
                className="flex items-center space-x-2 px-4 py-2 text-sm text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <Save className="w-4 h-4" />
                <span>Sauvegarder brouillon</span>
              </button>
            </div>

            <div className="flex space-x-3">
              <button
                type="button"
                onClick={onClose}
                disabled={modalState.loading.submit}
                className="px-4 py-2 text-sm text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {schema.cancelLabel || 'Annuler'}
              </button>

              <button
                type="submit"
                disabled={modalState.loading.submit}
                className="flex items-center space-x-2 px-4 py-2 text-sm text-white bg-blue-600 border border-transparent rounded-md hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {modalState.loading.submit && (
                  <Loader2 className="w-4 h-4 animate-spin" />
                )}
                <span>{schema.submitLabel || 'Soumettre'}</span>
              </button>
            </div>
          </div>
        </form>
      </div>
    </ModalOverlay>
  );
}

