interface PromptLibraryModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSelectPrompt: (prompt: string) => void;
  title?: string;
}

export function PromptLibraryModal({
  isOpen,
  onClose,
  onSelectPrompt,
  title = 'Prompt Library'
}: PromptLibraryModalProps) {
  if (!isOpen) return null;

  const handlePromptSelect = (prompt: string) => {
    onSelectPrompt(prompt);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      {/* Backdrop */}
      <div
        className="absolute inset-0 bg-black/50 backdrop-blur-sm"
        onClick={onClose}
        aria-hidden="true"
      />

      {/* Modal */}
      <div className="relative w-full max-w-7xl h-[90vh] mx-4 bg-white dark:bg-gray-900 rounded-lg shadow-2xl flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-gray-200 dark:border-gray-800">
          <div className="flex items-center gap-2">
            <BookOpen className="h-5 w-5 text-blue-600 dark:text-blue-400" />
            <h2 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
              {title}
            </h2>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
            aria-label="Close"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-hidden">
          <PromptLibraryBrowser onSelectPrompt={handlePromptSelect} />
        </div>
      </div>
    </div>
  );
}

// Export a hook to manage the modal state
export function usePromptLibraryModal() {
  const [isOpen, setIsOpen] = useState(false);

  return {
    isOpen,
    open: () => setIsOpen(true),
    close: () => setIsOpen(false),
    toggle: () => setIsOpen(prev => !prev)
  };
}

/**
 * PromptStyleTransfer
 * Component for configuring prompt-based style transfer
 */

import React, { useCallback, useState, useEffect } from 'react';
import { PromptStyleTransferProps, StylePresetName, STYLE_PRESETS } from '../../types/styleTransfer';
import { Card, CardContent, CardHeader, CardTitle } from '../../components/ui/card';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import { Label } from '../../components/ui/label';
import { Slider } from '../../components/ui/slider';
import { Textarea } from '../../components/ui/textarea';
import { Upload, Image as ImageIcon, Type, Settings2, X, Sparkles, Palette } from 'lucide-react';
import { cn } from '../../lib/utils';

export const PromptStyleTransfer: React.FC<PromptStyleTransferProps> = ({
  config,
  onConfigChange,
  sourceFile,
  onSourceFileChange,
  selectedPreset,
  onPresetChange,
  customPrompt,
  onCustomPromptChange
}) => {
  const [sourcePreview, setSourcePreview] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'preset' | 'custom'>(
    selectedPreset ? 'preset' : 'custom'
  );

  // Update config when preset changes
  useEffect(() => {
    if (selectedPreset && STYLE_PRESETS[selectedPreset]) {
      const preset = STYLE_PRESETS[selectedPreset];
      onConfigChange({
        ...config,
        prompt: preset.prompt
      });
    }
  }, [selectedPreset]);

  // Update config when custom prompt changes
  useEffect(() => {
    if (activeTab === 'custom' && customPrompt) {
      onConfigChange({
        ...config,
        prompt: customPrompt
      });
    }
  }, [customPrompt, activeTab]);

  const handleSourceFileSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      onSourceFileChange(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setSourcePreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  }, [onSourceFileChange]);

  const clearSourceFile = useCallback(() => {
    onSourceFileChange(undefined as any);
    setSourcePreview(null);
  }, [onSourceFileChange]);

  const updateConfig = useCallback((updates: Partial<typeof config>) => {
    onConfigChange({ ...config, ...updates });
  }, [config, onConfigChange]);

  const handlePresetSelect = useCallback((preset: StylePresetName) => {
    onPresetChange(preset);
    setActiveTab('preset');
  }, [onPresetChange]);

  const handleCustomTabClick = useCallback(() => {
    setActiveTab('custom');
    onPresetChange(undefined as any);
  }, [onPresetChange]);

  const categories = Array.from(new Set(Object.values(STYLE_PRESETS).map(p => p.category)));

  return (
    <div className="space-y-6">
      {/* Source Image Upload */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <ImageIcon className="w-4 h-4" />
            Source Image
          </CardTitle>
        </CardHeader>
        <CardContent>
          {sourcePreview ? (
            <div className="relative">
              <img 
                src={sourcePreview} 
                alt="Source" 
                className="w-full h-48 object-cover rounded-lg"
              />
              <button
                onClick={clearSourceFile}
                className="absolute top-2 right-2 p-1 bg-red-500 text-white rounded-full hover:bg-red-600"
                aria-label="Remove source image"
                title="Remove source image"
              >
                <X className="w-4 h-4" />
              </button>
              <p className="text-xs text-muted-foreground mt-2 text-center">
                {sourceFile?.name}
              </p>
            </div>
          ) : (
            <div className="border-2 border-dashed border-muted-foreground/25 rounded-lg p-8 text-center hover:border-primary/50 transition-colors">
              <input
                type="file"
                accept="image/*"
                onChange={handleSourceFileSelect}
                className="hidden"
                id="prompt-source-upload"
              />
              <label 
                htmlFor="prompt-source-upload"
                className="cursor-pointer flex flex-col items-center gap-2"
              >
                <Upload className="w-8 h-8 text-muted-foreground" />
                <span className="text-sm text-muted-foreground">
                  Click to upload source image
                </span>
                <span className="text-xs text-muted-foreground/60">
                  Supports: PNG, JPG, WEBP
                </span>
              </label>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Style Selection Tabs */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="text-base flex items-center gap-2">
              <Palette className="w-4 h-4" />
              Style Selection
            </CardTitle>
            <div className="flex gap-2">
              <Button
                variant={activeTab === 'preset' ? 'default' : 'outline'}
                size="sm"
                onClick={() => setActiveTab('preset')}
              >
                Presets
              </Button>
              <Button
                variant={activeTab === 'custom' ? 'default' : 'outline'}
                size="sm"
                onClick={handleCustomTabClick}
              >
                Custom
              </Button>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {activeTab === 'preset' ? (
            <div className="space-y-4">
              {categories.map(category => (
                <div key={category}>
                  <h4 className="text-sm font-medium text-muted-foreground mb-2">{category}</h4>
                  <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
                    {Object.entries(STYLE_PRESETS)
                      .filter(([_, preset]) => preset.category === category)
                      .map(([key, preset]) => (
                        <button
                          key={key}
                          onClick={() => handlePresetSelect(key as StylePresetName)}
                          className={cn(
                            'p-3 rounded-lg border text-left transition-all',
                            selectedPreset === key
                              ? 'border-primary bg-primary/5 ring-1 ring-primary'
                              : 'border-muted hover:border-primary/50 hover:bg-muted/50'
                          )}
                        >
                          <div className="font-medium text-sm">{preset.name}</div>
                          <div className="text-xs text-muted-foreground mt-1 line-clamp-2">
                            {preset.description}
                          </div>
                        </button>
                      ))}
                  </div>
                </div>
              ))}
              
              {selectedPreset && (
                <div className="mt-4 p-3 bg-muted rounded-lg">
                  <div className="flex items-center gap-2 mb-2">
                    <Sparkles className="w-4 h-4 text-primary" />
                    <span className="font-medium">Selected: {STYLE_PRESETS[selectedPreset].name}</span>
                  </div>
                  <p className="text-sm text-muted-foreground">
                    {STYLE_PRESETS[selectedPreset].prompt}
                  </p>
                </div>
              )}
            </div>
          ) : (
            <div className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="custom-prompt">Custom Style Prompt</Label>
                <Textarea
                  id="custom-prompt"
                  value={customPrompt || ''}
                  onChange={(e) => onCustomPromptChange(e.target.value)}
                  placeholder="Describe the style you want to apply... (e.g., 'oil painting style with thick brushstrokes and vibrant colors')"
                  rows={4}
                />
                <p className="text-xs text-muted-foreground">
                  Describe the artistic style, lighting, colors, and mood you want
                </p>
              </div>
              
              <div className="space-y-2">
                <Label htmlFor="negative-prompt">Negative Prompt (Optional)</Label>
                <Textarea
                  id="negative-prompt"
                  value={config.negativePrompt}
                  onChange={(e) => updateConfig({ negativePrompt: e.target.value })}
                  placeholder="Elements to avoid in the output..."
                  rows={2}
                />
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Configuration Section */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <Settings2 className="w-4 h-4" />
            Generation Settings
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Output Prefix */}
          <div className="space-y-2">
            <Label htmlFor="prompt-output-prefix">Output Filename Prefix</Label>
            <Input
              id="prompt-output-prefix"
              value={config.outputPrefix}
              onChange={(e) => updateConfig({ outputPrefix: e.target.value })}
              placeholder="prompt_style"
            />
          </div>

          {/* Steps Slider */}
          <div className="space-y-4">
            <div className="flex justify-between">
              <Label>Inference Steps</Label>
              <span className="text-sm text-muted-foreground">{config.steps}</span>
            </div>
            <Slider
              value={[config.steps]}
              onValueChange={([value]) => updateConfig({ steps: value })}
              min={1}
              max={50}
              step={1}
            />
            <p className="text-xs text-muted-foreground">
              More steps = higher quality but slower. Recommended: 10-20
            </p>
          </div>

          {/* CFG Scale Slider */}
          <div className="space-y-4">
            <div className="flex justify-between">
              <Label>CFG Scale</Label>
              <span className="text-sm text-muted-foreground">{config.cfgScale.toFixed(1)}</span>
            </div>
            <Slider
              value={[config.cfgScale]}
              onValueChange={([value]) => updateConfig({ cfgScale: value })}
              min={0.5}
              max={3.0}
              step={0.1}
            />
            <p className="text-xs text-muted-foreground">
              Higher = stronger prompt adherence. Recommended: 1.0-1.5
            </p>
          </div>

          {/* Dimensions */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="width">Width</Label>
              <Input
                id="width"
                type="number"
                value={config.width}
                onChange={(e) => updateConfig({ width: parseInt(e.target.value) || 1024 })}
                min={512}
                max={2048}
                step={64}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="height">Height</Label>
              <Input
                id="height"
                type="number"
                value={config.height}
                onChange={(e) => updateConfig({ height: parseInt(e.target.value) || 1024 })}
                min={512}
                max={2048}
                step={64}
              />
            </div>
          </div>
          <p className="text-xs text-muted-foreground">
            Output dimensions. Must be multiples of 64. Default: 1024x1024
          </p>

          {/* Seed Input */}
          <div className="space-y-2">
            <Label htmlFor="prompt-seed">Random Seed</Label>
            <Input
              id="prompt-seed"
              type="number"
              value={config.seed}
              onChange={(e) => updateConfig({ seed: parseInt(e.target.value) || -1 })}
              placeholder="-1 for random"
            />
            <p className="text-xs text-muted-foreground">
              -1 for random, or set for reproducible results
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Tips Card */}
      <Card className="bg-purple-50 border-purple-200">
        <CardContent className="p-4">
          <h4 className="font-medium text-purple-900 mb-2">Prompt Writing Tips</h4>
          <ul className="text-sm text-purple-800 space-y-1">
            <li>ÔÇó Be specific about art style (oil painting, watercolor, anime, etc.)</li>
            <li>ÔÇó Describe lighting (dramatic, soft, cinematic, natural)</li>
            <li>ÔÇó Mention color palette (vibrant, muted, warm, cool)</li>
            <li>ÔÇó Include texture details (smooth, rough, brushstrokes)</li>
            <li>ÔÇó Add mood/atmosphere (dreamy, mysterious, energetic)</li>
          </ul>
        </CardContent>
      </Card>
    </div>
  );
};

export default PromptStyleTransfer;

/**
 * Roger Wizard Modal
 *
 * Modal for the Roger Data Extractor wizard that allows users to select
 * text files and extract project data from stories, novels, or LLM discussions.
 */

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { X } from 'lucide-react';
import type { WizardDefinition } from '../../types/configuration';
import { WizardService } from '../../services/wizard/WizardService';
import { useAppStore } from '../../stores/useAppStore';
import { useEditorStore } from '../../stores/editorStore';
import './WizardModal.css';
import './RogerWizardModal.css';

interface RogerWizardModalProps {
  isOpen: boolean;
  wizard: WizardDefinition;
  onClose: () => void;
}

interface FilePreview {
  name: string;
  size: number;
  wordCount: number;
  charCount: number;
  estimatedChars: number;
  estimatedLocs: number;
  potential: string;
  preview: string;
  error?: string;
}

export function RogerWizardModal({ isOpen, wizard, onClose }: RogerWizardModalProps) {
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [filePreview, setFilePreview] = useState<FilePreview | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isExtracting, setIsExtracting] = useState(false);
  const [extractionResult, setExtractionResult] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);
  const [focusAreas, setFocusAreas] = useState<string[]>([]);
  const [currentStep, setCurrentStep] = useState<'select' | 'preview' | 'extract' | 'result'>('select');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const projectPath = useEditorStore((state) => state.projectPath);

  // Handle Escape key
  const handleKeyDown = useCallback(
    (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        onClose();
      }
    },
    [onClose]
  );

  useEffect(() => {
    if (isOpen) {
      window.addEventListener('keydown', handleKeyDown);
      document.body.style.overflow = 'hidden';
      
      // Reset state when modal opens
      setSelectedFile(null);
      setFilePreview(null);
      setIsAnalyzing(false);
      setIsExtracting(false);
      setExtractionResult(null);
      setError(null);
      setFocusAreas([]);
      setCurrentStep('select');
    } else {
      window.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = 'unset';
    }

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = 'unset';
    };
  }, [isOpen, handleKeyDown]);

  const handleFileSelect = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    // Validate file type
    if (!file.name.match(/\.(txt|md|story|novel|doc|docx)$/i)) {
      setError('Please select a text file (.txt, .md, .story, .novel, .doc, .docx)');
      return;
    }

    // Validate file size (max 10MB)
    if (file.size > 10 * 1024 * 1024) {
      setError('File size must be less than 10MB');
      return;
    }

    setSelectedFile(file);
    setError(null);
    setIsAnalyzing(true);

    try {
      // Get file preview using Electron API
      if (window.electronAPI?.fs?.readFile) {
        const content = await window.electronAPI.fs.readFile(file.path, 'utf-8');

        // Calculate basic stats
        const wordCount = content.split(/\s+/).length;
        const charCount = content.length;

        // Simple extraction estimates
        const nameMatches = (content.match(/\b[A-Z][a-z]+\b/g) || []).length;
        const locationMatches = (content.match(/\b[A-Z][a-z]+(?:\s+[A-Z][a-z]+)*\b/g) || []).length;

        const estimatedChars = Math.min(Math.floor(nameMatches / 3), 20);
        const estimatedLocs = Math.min(Math.floor(locationMatches / 5), 15);

        const potential = wordCount > 1000 ? 'high' :
                         wordCount > 500 ? 'medium' : 'low';

        const preview = content.substring(0, 300) +
                       (content.length > 300 ? '...' : '');

        setFilePreview({
          name: file.name,
          size: file.size,
          wordCount,
          charCount,
          estimatedChars,
          estimatedLocs,
          potential,
          preview
        });

        setCurrentStep('preview');
      } else {
        // Fallback for environments without Electron
        setFilePreview({
          name: file.name,
          size: file.size,
          wordCount: 0,
          charCount: file.size,
          estimatedChars: 5,
          estimatedLocs: 3,
          potential: 'unknown',
          preview: 'Preview not available in this environment',
          error: 'File preview requires Electron environment'
        });
        setCurrentStep('preview');
      }
    } catch (err) {
      setError(`Failed to analyze file: ${err instanceof Error ? err.message : 'Unknown error'}`);
      setFilePreview(null);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleFocusAreaChange = (area: string, checked: boolean) => {
    setFocusAreas(prev =>
      checked
        ? [...prev, area]
        : prev.filter(a => a !== area)
    );
  };

  const handleExtract = async () => {
    if (!selectedFile || !projectPath) return;

    setIsExtracting(true);
    setError(null);

    try {
      const wizardService = new WizardService();

      // For Roger wizard, we need to pass the file path
      // This would typically call the CLI command via Electron
      const result = await wizardService.launchWizard('roger-wizard', projectPath, {
        file: selectedFile.path,
        focus: focusAreas.length > 0 ? focusAreas : undefined,
        format: 'summary'
      });

      if (result.success) {
        // Parse the result output to extract structured data
        setExtractionResult({
          success: true,
          message: result.message,
          output: result.output,
          charactersExtracted: 0, // Would parse from output
          locationsExtracted: 0,
          worldElementsExtracted: 0,
          confidence: 7.5
        });
        setCurrentStep('result');
      } else {
        setError(result.error || result.message);
      }

    } catch (err) {
      setError(`Extraction failed: ${err instanceof Error ? err.message : 'Unknown error'}`);
    } finally {
      setIsExtracting(false);
    }
  };

  const handleBack = () => {
    if (currentStep === 'preview') {
      setCurrentStep('select');
      setFilePreview(null);
      setSelectedFile(null);
    } else if (currentStep === 'extract') {
      setCurrentStep('preview');
    } else if (currentStep === 'result') {
      setCurrentStep('preview');
      setExtractionResult(null);
    }
  };

  const handleFinish = () => {
    onClose();
    // Could trigger a refresh of project data here
    window.location.reload();
  };

  if (!isOpen) return null;

  return (
    <div className="wizard-modal-overlay" onClick={onClose}>
      <div className="wizard-modal-container" onClick={(e) => e.stopPropagation()}>
        <div className="wizard-modal-header">
           <div className="flex items-center gap-3">
            <div className="text-2xl">{wizard.icon}</div>
            <div className="flex flex-col">
              <h2 className="wizard-modal-title">{wizard.name}</h2>
              <span className="text-[10px] text-muted-foreground uppercase tracking-widest">{wizard.description}</span>
            </div>
          </div>
          <button
            className="wizard-modal-close"
            onClick={onClose}
            aria-label="Close"
          >
            <X size={20} />
          </button>
        </div>

        <div className="wizard-modal-content">
          <div className="roger-modal-body p-6">
            {/* Step 1: File Selection */}
            {currentStep === 'select' && (
              <div className="step-content">
                <h3>­ƒôä Select Text File</h3>
                <p>Choose a text file containing your story, novel, or discussion plan to extract project data from.</p>

                <div className="file-upload-area">
                  <input
                    ref={fileInputRef}
                    type="file"
                    accept=".txt,.md,.story,.novel,.doc,.docx"
                    onChange={handleFileSelect}
                    style={{ display: 'none' }}
                  />

                  <button
                    className="file-select-button"
                    onClick={() => fileInputRef.current?.click()}
                  >
                    ­ƒôü Choose File
                  </button>

                  <div className="file-info">
                    <p><strong>Supported formats:</strong> .txt, .md, .story, .novel, .doc, .docx</p>
                    <p><strong>Maximum size:</strong> 10MB</p>
                    <p><strong>Minimum content:</strong> 100 characters</p>
                  </div>
                </div>

                {error && (
                  <div className="error-message">
                    ÔØî {error}
                  </div>
                )}
              </div>
            )}

            {/* Step 2: File Preview */}
            {currentStep === 'preview' && filePreview && (
              <div className="step-content">
                <h3>­ƒæü´©Å File Preview</h3>

                <div className="file-stats">
                  <div className="stat-item">
                    <span className="stat-label">File:</span>
                    <span className="stat-value">{filePreview.name}</span>
                  </div>
                  <div className="stat-item">
                    <span className="stat-label">Size:</span>
                    <span className="stat-value">{(filePreview.size / 1024).toFixed(1)} KB</span>
                  </div>
                  <div className="stat-item">
                    <span className="stat-label">Words:</span>
                    <span className="stat-value">{filePreview.wordCount.toLocaleString()}</span>
                  </div>
                  <div className="stat-item">
                    <span className="stat-label">Extraction Potential:</span>
                    <span className={`stat-value potential-${filePreview.potential}`}>
                      {filePreview.potential.toUpperCase()}
                    </span>
                  </div>
                </div>

                <div className="extraction-estimates">
                  <h4>­ƒÄ» Estimated Extractions</h4>
                  <div className="estimates-grid">
                    <div className="estimate-item">
                      <span className="estimate-icon">­ƒæÑ</span>
                      <span className="estimate-label">Characters</span>
                      <span className="estimate-value">~{filePreview.estimatedChars}</span>
                    </div>
                    <div className="estimate-item">
                      <span className="estimate-icon">­ƒÅ░</span>
                      <span className="estimate-label">Locations</span>
                      <span className="estimate-value">~{filePreview.estimatedLocs}</span>
                    </div>
                    <div className="estimate-item">
                      <span className="estimate-icon">­ƒîì</span>
                      <span className="estimate-label">World Elements</span>
                      <span className="estimate-value">~{Math.floor(filePreview.estimatedChars / 2)}</span>
                    </div>
                  </div>
                </div>

                <div className="text-preview">
                  <h4>­ƒôØ Text Preview</h4>
                  <div className="preview-content">
                    {filePreview.preview}
                  </div>
                </div>

                <div className="focus-options">
                  <h4>­ƒÄ» Focus Areas (Optional)</h4>
                  <p>Select specific areas to focus extraction on:</p>
                  <div className="focus-checkboxes">
                    {[
                      { id: 'characters', label: 'Characters', icon: '­ƒæÑ' },
                      { id: 'locations', label: 'Locations', icon: '­ƒÅ░' },
                      { id: 'world_building', label: 'World Building', icon: '­ƒîì' },
                      { id: 'plot', label: 'Plot & Themes', icon: '­ƒôû' }
                    ].map(area => (
                      <label key={area.id} className="focus-checkbox">
                        <input
                          type="checkbox"
                          checked={focusAreas.includes(area.id)}
                          onChange={(e) => handleFocusAreaChange(area.id, e.target.checked)}
                        />
                        <span className="checkbox-icon">{area.icon}</span>
                        {area.label}
                      </label>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {/* Step 3: Extraction in Progress */}
            {currentStep === 'extract' && (
              <div className="step-content">
                <h3>ÔÜÖ´©Å Extracting Data</h3>
                <div className="extraction-progress">
                  <div className="progress-spinner"></div>
                  <p>Analyzing text file and extracting project data...</p>
                  <p className="progress-note">This may take a moment depending on file size.</p>
                </div>
              </div>
            )}

            {/* Step 4: Results */}
            {currentStep === 'result' && extractionResult && (
              <div className="step-content">
                <h3>Ô£à Extraction Complete</h3>

                <div className="extraction-results">
                  <div className="result-summary">
                    <div className="result-stat">
                      <span className="stat-icon">­ƒæÑ</span>
                      <span className="stat-label">Characters</span>
                      <span className="stat-value">{extractionResult.charactersExtracted || 0}</span>
                    </div>
                    <div className="result-stat">
                      <span className="stat-icon">­ƒÅ░</span>
                      <span className="stat-label">Locations</span>
                      <span className="stat-value">{extractionResult.locationsExtracted || 0}</span>
                    </div>
                    <div className="result-stat">
                      <span className="stat-icon">­ƒîì</span>
                      <span className="stat-label">World Elements</span>
                      <span className="stat-value">{extractionResult.worldElementsExtracted || 0}</span>
                    </div>
                    <div className="result-stat">
                      <span className="stat-icon">­ƒÄ»</span>
                      <span className="stat-label">Confidence</span>
                      <span className="stat-value">{extractionResult.confidence || 0}/10</span>
                    </div>
                  </div>

                  <div className="result-files">
                    <h4>­ƒÆ¥ Files Created</h4>
                    <ul>
                      <li><code>character_definitions.json</code> - Extracted character data</li>
                      <li><code>world_building.json</code> - World and location data</li>
                      <li><code>roger_extraction_report.json</code> - Complete extraction report</li>
                      <li><code>project.json</code> - Updated with extraction metadata</li>
                    </ul>
                  </div>

                  <div className="result-message">
                    <p>{extractionResult.message}</p>
                    {extractionResult.output && (
                      <details>
                        <summary>Detailed Output</summary>
                        <pre>{extractionResult.output}</pre>
                      </details>
                    )}
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
        
        <div className="wizard-modal-footer flex border-t border-primary/10 p-4 bg-black/40">
            {currentStep !== 'select' && (
              <button className="px-4 py-2 bg-slate-800 text-slate-300 rounded hover:bg-slate-700 transition-colors" onClick={handleBack}>
                ÔåÉ Back
              </button>
            )}

            <div className="flex-1"></div>

            {currentStep === 'select' && (
              <button className="px-4 py-2 text-slate-400 hover:text-white transition-colors" onClick={onClose}>
                Cancel
              </button>
            )}

            {currentStep === 'preview' && (
              <button
                className="px-6 py-2 bg-blue-600 text-white rounded hover:bg-blue-500 transition-all shadow-[0_0_15px_rgba(37,99,235,0.3)]"
                onClick={() => {
                  setCurrentStep('extract');
                  handleExtract();
                }}
                disabled={isExtracting}
              >
                {isExtracting ? 'Extracting...' : 'Extract Data'}
              </button>
            )}

            {currentStep === 'extract' && (
              <div className="flex items-center gap-2 text-blue-400 font-bold uppercase tracking-widest text-xs">
                <div className="w-4 h-4 border-2 border-blue-400 border-t-transparent rounded-full animate-spin"></div>
                Processing...
              </div>
            )}

            {currentStep === 'result' && (
              <button className="px-6 py-2 bg-green-600 text-white rounded hover:bg-green-500 transition-all" onClick={handleFinish}>
                Finish
              </button>
            )}
        </div>
      </div>
    </div>
  );
}

