        </button>
        <button className="wva-quick-btn" onClick={() => assistant.handleCommand('Remplis les champs manquants')}>
          Ô£¿ Compl├®ter
        </button>
        {entityType === 'character' && (
          <>
            <button className="wva-quick-btn" onClick={() => assistant.handleCommand('Mets les yeux en vert')}>
