import React, { useState } from 'react';
import { useWizard } from '@/contexts/WizardContext';
import { WizardFormLayout, FormField } from '../WizardFormLayout';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Sparkles, X, Zap, Scissors, Eye, User, Palette, Microscope, Activity } from 'lucide-react';
import { useLLMGeneration } from '@/hooks/useLLMGeneration';
import { LLMErrorDisplay, LLMLoadingState } from '../LLMErrorDisplay';
import { ServiceWarning, useServiceStatus } from '@/components/ui/service-warning';
import { useAppStore } from '@/stores/useAppStore';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  HAIR_COLORS,
  EYE_COLORS,
  SKIN_TONES,
  BODY_BUILDS,
  HEIGHT_CATEGORIES,
  POSTURE_OPTIONS,
} from '@/constants/characterOptions';
import { cn } from '@/lib/utils';
import type { Character } from '@/types/character';
import type { World } from '@/types/world';
import type { StoryContext } from './CharacterWizard';

// ============================================================================
// Step 2: Morphological Profile (Physical Appearance)
// ============================================================================

interface Step2PhysicalAppearanceProps {
  worldContext?: World;
  storyContext?: StoryContext;
}

export function Step2PhysicalAppearance({ worldContext }: Step2PhysicalAppearanceProps) {
  const { formData, updateFormData } = useWizard<Character>();
  const [newFeature, setNewFeature] = useState('');
  const [newColor, setNewColor] = useState('');
  const setShowLLMSettings = useAppStore((state) => state.setShowLLMSettings);

  // Use ref to always have access to latest formData and updateFormData in callbacks
  const formDataRef = React.useRef(formData);
  const updateFormDataRef = React.useRef(updateFormData);
  formDataRef.current = formData;
  updateFormDataRef.current = updateFormData;

  // Check if LLM service is configured
  const { llmConfigured, llmChecking } = useServiceStatus();

  // LLM generation for appearance suggestions
  const {
    generate,
    isLoading,
    error: llmError,
    clearError,
  } = useLLMGeneration({
    onSuccess: (response) => {
      const appearance = parseLLMAppearance(response.content);
      if (appearance) {
        const currentVisualIdentity = formDataRef.current.visual_identity || {};
        updateFormDataRef.current({
          visual_identity: {
            ...currentVisualIdentity,
            ...appearance,
          } as Character['visual_identity'],
        });
      }
    },
  });

  const handleGenerateAppearance = async () => {
    clearError();

    const uniqueEntropy = {
      timestamp: Date.now(),
      randomId: Math.random().toString(36).substring(2, 10),
      sessionSeed: Math.floor(Math.random() * 1000000),
    };

    const context = {
      characterName: formData.name || 'the character',
      archetype: formData.role?.archetype || 'character',
      ageRange: formData.visual_identity?.age_range || 'adult',
      gender: formData.visual_identity?.gender || 'unspecified',
      worldGenre: worldContext?.genre?.join(', ') || 'fantasy',
      worldTone: worldContext?.tone?.join(', ') || 'dramatic',
      entropy: uniqueEntropy,
    };

    const systemPrompt = 'You are a character design expert. Create detailed, coherent physical appearances that match the character\'s role and world setting.';

    const prompt = `Generate a detailed physical appearance for a character:
- Identity: ${context.characterName}
- Archetype: ${context.archetype}
- Maturity: ${context.ageRange}
- Matrix: ${context.gender}
- Genre: ${context.worldGenre}
- Tone: ${context.worldTone}
- Entropy: ${uniqueEntropy.sessionSeed}

Format as JSON with keys: hair_color, hair_style, hair_length, eye_color, eye_shape, skin_tone, facial_structure, height, build, posture, clothing_style, distinctive_features (array), color_palette (array)`;

    await generate({
      prompt,
      systemPrompt,
      temperature: 0.8,
      maxTokens: 800,
    });
  };

  const parseLLMAppearance = (response: string): Partial<Character['visual_identity']> | null => {
    try {
      const jsonMatch = response.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        const parsed = JSON.parse(jsonMatch[0]);
        const result: Partial<Character['visual_identity']> = {};
        if (parsed.hair_color || parsed.hairColor) result.hair_color = parsed.hair_color || parsed.hairColor;
        if (parsed.hair_style || parsed.hairStyle) result.hair_style = parsed.hair_style || parsed.hairStyle;
        if (parsed.hair_length || parsed.hairLength) result.hair_length = parsed.hair_length || parsed.hairLength;
        if (parsed.eye_color || parsed.eyeColor) result.eye_color = parsed.eye_color || parsed.eyeColor;
        if (parsed.eye_shape || parsed.eyeShape) result.eye_shape = parsed.eye_shape || parsed.eyeShape;
        if (parsed.skin_tone || parsed.skinTone) result.skin_tone = parsed.skin_tone || parsed.skinTone;
        if (parsed.facial_structure || parsed.facialStructure) result.facial_structure = parsed.facial_structure || parsed.facialStructure;
        if (parsed.height) result.height = parsed.height;
        if (parsed.build) result.build = parsed.build;
        if (parsed.posture) result.posture = parsed.posture;
        if (parsed.clothing_style || parsed.clothingStyle) result.clothing_style = parsed.clothing_style || parsed.clothingStyle;
        if (Array.isArray(parsed.distinctive_features) || Array.isArray(parsed.distinctiveFeatures)) {
          result.distinctive_features = parsed.distinctive_features || parsed.distinctiveFeatures;
        }
        if (Array.isArray(parsed.color_palette) || Array.isArray(parsed.colorPalette)) {
          result.color_palette = parsed.color_palette || parsed.colorPalette;
        }
        return result;
      }
    } catch (error) {
      console.error('Failed to parse LLM response:', error);
    }
    return null;
  };

  const updateVisualIdentity = (updates: Partial<Character['visual_identity']>) => {
    updateFormData({
      visual_identity: {
        ...(formData.visual_identity || {}),
        ...updates,
      } as Character['visual_identity']
    });
  };

  const handleAddFeature = () => {
    if (newFeature.trim()) {
      const features = formData.visual_identity?.distinctive_features || [];
      updateVisualIdentity({ distinctive_features: [...features, newFeature.trim()] });
      setNewFeature('');
    }
  };

  const handleRemoveFeature = (index: number) => {
    const features = formData.visual_identity?.distinctive_features || [];
    updateVisualIdentity({ distinctive_features: features.filter((_, i) => i !== index) });
  };

  const handleAddColor = () => {
    if (newColor.trim()) {
      const colors = formData.visual_identity?.color_palette || [];
      updateVisualIdentity({ color_palette: [...colors, newColor.trim()] });
      setNewColor('');
    }
  };

  const handleRemoveColor = (index: number) => {
    const colors = formData.visual_identity?.color_palette || [];
    updateVisualIdentity({ color_palette: colors.filter((_, i) => i !== index) });
  };

  return (
    <WizardFormLayout
      title="Morphological Profile"
      description="Synthesize the visual parameters and structural aesthetics of the entity"
    >
      {/* AI Assistance Section */}
      <div className="space-y-4 mb-8 p-4 rounded-lg border border-primary/20 bg-primary/5 backdrop-blur-sm shadow-[inset_0_0_10px_rgba(var(--primary-rgb),0.05)]">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-base font-bold text-primary neon-text uppercase tracking-widest text-[10px] font-mono mb-1">// Morph Synthesizer</h3>
            <p className="text-[10px] text-primary/60 uppercase tracking-wider">
              Synthesize a coherent visual profile from core identity datasets
            </p>
          </div>
          <Button
            onClick={handleGenerateAppearance}
            disabled={isLoading || llmChecking || !formData.role?.archetype || !llmConfigured}
            className="gap-2 btn-neon bg-primary/10 text-primary border-primary/20 hover:bg-primary/20"
            size="sm"
          >
            <Microscope className="h-3.5 w-3.5" />
            <span className="text-[10px] font-black uppercase tracking-widest">Synthesize Profile</span>
          </Button>
        </div>

        {!llmChecking && !llmConfigured && (
          <ServiceWarning
            service="llm"
            variant="inline"
            onConfigure={() => setShowLLMSettings(true)}
            className="bg-red-500/10 border-red-500/20 text-red-400"
          />
        )}

        {isLoading && (
          <LLMLoadingState message="Mapping morphological data..." showProgress />
        )}

        {llmError && (
          <LLMErrorDisplay
            error={llmError}
            onRetry={handleGenerateAppearance}
            onDismiss={clearError}
          />
        )}
      </div>

      <div className="space-y-10">
        {/* Follicular and Ocular Assets */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
          {/* Follicular Matrix */}
          <div className="space-y-6 p-4 border border-primary/10 bg-primary/20 relative group">
            <div className="absolute -top-3 left-3 bg-[#050b10] px-2 py-0.5 border border-primary/20">
              <span className="text-[9px] font-black text-primary uppercase tracking-widest font-mono">Follicular Assets</span>
            </div>

            <div className="grid grid-cols-1 gap-4 mt-2">
              <FormField label="Follicular Chroma" name="hair_color">
                <Select
                  value={HAIR_COLORS.includes(formData.visual_identity?.hair_color as any) ? formData.visual_identity?.hair_color : (formData.visual_identity?.hair_color ? 'Other' : '')}
                  onValueChange={(val) => updateVisualIdentity({ hair_color: val === 'Other' ? '' : val })}
                >
                  <SelectTrigger className="bg-primary/5 border-primary/20">
                    <SelectValue placeholder="Select chroma" />
                  </SelectTrigger>
                  <SelectContent className="bg-[#050b10] border-primary/30">
                    {HAIR_COLORS.map(color => (
                      <SelectItem key={color} value={color} className="focus:bg-primary/20 focus:text-primary uppercase text-[10px] font-mono">{color}</SelectItem>
                    ))}
                    <SelectItem value="Other" className="focus:bg-primary/20 focus:text-primary uppercase text-[10px] font-mono border-t border-primary/10 mt-1 pt-1 font-bold">Custom Signature</SelectItem>
                  </SelectContent>
                </Select>
                {(!HAIR_COLORS.includes(formData.visual_identity?.hair_color as any) && formData.visual_identity?.hair_color || formData.visual_identity?.hair_color === '') && (
                  <Input
                    value={formData.visual_identity?.hair_color || ''}
                    onChange={(e) => updateVisualIdentity({ hair_color: e.target.value })}
                    placeholder="MANUAL_OVERRIDE_CHROMA..."
                    className="mt-2 text-[10px]"
                  />
                )}
              </FormField>

              <div className="grid grid-cols-2 gap-4">
                <FormField label="Fiber Configuration" name="hair_style">
                  <Input
                    value={formData.visual_identity?.hair_style || ''}
                    onChange={(e) => updateVisualIdentity({ hair_style: e.target.value })}
                    placeholder="Configuration..."
                    className="bg-primary/5 border-primary/20"
                  />
                </FormField>
                <FormField label="Linear Extension" name="hair_length">
                  <Input
                    value={formData.visual_identity?.hair_length || ''}
                    onChange={(e) => updateVisualIdentity({ hair_length: e.target.value })}
                    placeholder="Extension..."
                    className="bg-primary/5 border-primary/20"
                  />
                </FormField>
              </div>
            </div>
          </div>

          {/* Ocular Matrix */}
          <div className="space-y-6 p-4 border border-primary/10 bg-primary/20 relative group">
            <div className="absolute -top-3 left-3 bg-[#050b10] px-2 py-0.5 border border-primary/20">
              <span className="text-[9px] font-black text-primary uppercase tracking-widest font-mono">Ocular Matrix</span>
            </div>

            <div className="grid grid-cols-1 gap-4 mt-2">
              <FormField label="Ocular Hue" name="eye_color">
                <Select
                  value={EYE_COLORS.includes(formData.visual_identity?.eye_color as any) ? formData.visual_identity?.eye_color : (formData.visual_identity?.eye_color ? 'Other' : '')}
                  onValueChange={(val) => updateVisualIdentity({ eye_color: val === 'Other' ? '' : val })}
                >
                  <SelectTrigger className="bg-primary/5 border-primary/20">
                    <SelectValue placeholder="Select hue" />
                  </SelectTrigger>
                  <SelectContent className="bg-[#050b10] border-primary/30">
                    {EYE_COLORS.map(color => (
                      <SelectItem key={color} value={color} className="focus:bg-primary/20 focus:text-primary uppercase text-[10px] font-mono">{color}</SelectItem>
                    ))}
                    <SelectItem value="Other" className="focus:bg-primary/20 focus:text-primary uppercase text-[10px] font-mono border-t border-primary/10 mt-1 pt-1 font-bold">Custom Hue</SelectItem>
                  </SelectContent>
                </Select>
                {(!EYE_COLORS.includes(formData.visual_identity?.eye_color as any) && formData.visual_identity?.eye_color || formData.visual_identity?.eye_color === '') && (
                  <Input
                    value={formData.visual_identity?.eye_color || ''}
                    onChange={(e) => updateVisualIdentity({ eye_color: e.target.value })}
                    placeholder="MANUAL_OVERRIDE_HUE..."
                    className="mt-2 text-[10px]"
                  />
                )}
              </FormField>

              <FormField label="Orbital Geometry" name="eye_shape">
                <Input
                  value={formData.visual_identity?.eye_shape || ''}
                  onChange={(e) => updateVisualIdentity({ eye_shape: e.target.value })}
                  placeholder="Geometric Profile..."
                  className="bg-primary/5 border-primary/20"
                />
              </FormField>
            </div>
          </div>
        </div>

        {/* Structural Matrix */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <FormField label="Vertical Amplitude" name="height">
            <Select
              value={HEIGHT_CATEGORIES.includes(formData.visual_identity?.height as any) ? formData.visual_identity?.height : (formData.visual_identity?.height ? 'Other' : '')}
              onValueChange={(val) => updateVisualIdentity({ height: val === 'Other' ? '' : val })}
            >
              <SelectTrigger className="bg-primary/5 border-primary/20">
                <SelectValue placeholder="Select scale" />
              </SelectTrigger>
              <SelectContent className="bg-[#050b10] border-primary/30">
                {HEIGHT_CATEGORIES.map(cat => (
                  <SelectItem key={cat} value={cat} className="focus:bg-primary/20 focus:text-primary uppercase text-[10px] font-mono">{cat}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </FormField>

          <FormField label="Structural Mass" name="build">
            <Select
              value={BODY_BUILDS.includes(formData.visual_identity?.build as any) ? formData.visual_identity?.build : (formData.visual_identity?.build ? 'Other' : '')}
              onValueChange={(val) => updateVisualIdentity({ build: val === 'Other' ? '' : val })}
            >
              <SelectTrigger className="bg-primary/5 border-primary/20">
                <SelectValue placeholder="Select build" />
              </SelectTrigger>
              <SelectContent className="bg-[#050b10] border-primary/30">
                {BODY_BUILDS.map(build => (
                  <SelectItem key={build} value={build} className="focus:bg-primary/20 focus:text-primary uppercase text-[10px] font-mono">{build}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </FormField>

          <FormField label="Kinetic Alignment" name="posture">
            <Select
              value={POSTURE_OPTIONS.includes(formData.visual_identity?.posture as any) ? formData.visual_identity?.posture : (formData.visual_identity?.posture ? 'Other' : '')}
              onValueChange={(val) => updateVisualIdentity({ posture: val === 'Other' ? '' : val })}
            >
              <SelectTrigger className="bg-primary/5 border-primary/20">
                <SelectValue placeholder="Select posture" />
              </SelectTrigger>
              <SelectContent className="bg-[#050b10] border-primary/30">
                {POSTURE_OPTIONS.map(opt => (
                  <SelectItem key={opt} value={opt} className="focus:bg-primary/20 focus:text-primary uppercase text-[10px] font-mono">{opt}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </FormField>
        </div>

        {/* Dermal and Cranial */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <FormField label="Dermal Surface Hue" name="skin_tone">
            <Select
              value={SKIN_TONES.includes(formData.visual_identity?.skin_tone as any) ? formData.visual_identity?.skin_tone : (formData.visual_identity?.skin_tone ? 'Other' : '')}
              onValueChange={(val) => updateVisualIdentity({ skin_tone: val === 'Other' ? '' : val })}
            >
              <SelectTrigger className="bg-primary/5 border-primary/20">
                <SelectValue placeholder="Select hue" />
              </SelectTrigger>
              <SelectContent className="bg-[#050b10] border-primary/30">
                {SKIN_TONES.map(tone => (
                  <SelectItem key={tone} value={tone} className="focus:bg-primary/20 focus:text-primary uppercase text-[10px] font-mono">{tone}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </FormField>

          <FormField label="Cranial Topology" name="facial_structure">
            <Input
              value={formData.visual_identity?.facial_structure || ''}
              onChange={(e) => updateVisualIdentity({ facial_structure: e.target.value })}
              placeholder="Facial Geometric Profile..."
              className="bg-primary/5 border-primary/20"
            />
          </FormField>
        </div>

        {/* Aesthetic Protocol */}
        <FormField label="Aesthetic Protocol (Clothing)" name="clothing_style">
          <div className="relative group">
            <Zap className="absolute left-3 top-3 h-5 w-5 text-primary/40 group-focus-within:text-primary transition-colors" />
            <Textarea
              value={formData.visual_identity?.clothing_style || ''}
              onChange={(e) => updateVisualIdentity({ clothing_style: e.target.value })}
              placeholder="Describe the aesthetic layer and functional attire..."
              rows={3}
              className="pl-10 bg-primary/5 border-primary/20"
            />
          </div>
        </FormField>

        {/* Anomalous Signatures */}
        <div className="space-y-4 p-4 border border-primary/20 bg-primary/5">
          <div className="flex items-center gap-2 mb-2">
            <Activity className="h-4 w-4 text-primary" />
            <span className="text-[10px] font-black uppercase tracking-[0.2em] text-primary">Anomalous Signatures</span>
          </div>

          <div className="flex gap-2">
            <Input
              value={newFeature}
              onChange={(e) => setNewFeature(e.target.value)}
              placeholder="Record anomalous feature..."
              onKeyPress={(e) => e.key === 'Enter' && handleAddFeature()}
              className="bg-primary/5 border-primary/20"
            />
            <Button onClick={handleAddFeature} className="btn-neon bg-primary/20 text-primary border-primary/20 px-4">
              <span className="text-[10px] font-black uppercase tracking-widest">Inject</span>
            </Button>
          </div>

          <div className="flex flex-wrap gap-2">
            {formData.visual_identity?.distinctive_features?.map((feature, index) => (
              <Badge key={index} variant="outline" className="bg-primary/10 border-primary/30 text-primary px-2 py-1 rounded-none group hover:border-red-500/50 transition-colors">
                <span className="text-[9px] font-mono uppercase tracking-wider">{feature}</span>
                <button
                  onClick={() => handleRemoveFeature(index)}
                  className="ml-2 text-primary/40 hover:text-red-500 transition-colors"
                >
                  <X className="w-3 h-3" />
                </button>
              </Badge>
            ))}
          </div>
        </div>

        {/* Spectral Signature */}
        <div className="space-y-4 p-4 border border-primary/20 bg-primary/5">
          <div className="flex items-center gap-2 mb-2">
            <Palette className="h-4 w-4 text-primary" />
            <span className="text-[10px] font-black uppercase tracking-[0.2em] text-primary">Spectral Signature (Colors)</span>
          </div>

          <div className="flex gap-2">
            <Input
              value={newColor}
              onChange={(e) => setNewColor(e.target.value)}
              placeholder="Record chroma signature..."
              onKeyPress={(e) => e.key === 'Enter' && handleAddColor()}
              className="bg-primary/5 border-primary/20"
            />
            <Button onClick={handleAddColor} className="btn-neon bg-primary/20 text-primary border-primary/20 px-4">
              <span className="text-[10px] font-black uppercase tracking-widest">Inject</span>
            </Button>
          </div>

          <div className="flex flex-wrap gap-2">
            {formData.visual_identity?.color_palette?.map((color, index) => (
              <Badge key={index} variant="outline" className="bg-primary/10 border-primary/30 text-primary px-2 py-1 rounded-none group hover:border-red-500/50 transition-colors">
                <span className="text-[9px] font-mono uppercase tracking-wider">{color}</span>
                <button
                  onClick={() => handleRemoveColor(index)}
                  className="ml-2 text-primary/40 hover:text-red-500 transition-colors"
                >
                  <X className="w-3 h-3" />
                </button>
              </Badge>
            ))}
          </div>
        </div>
      </div>
    </WizardFormLayout>
  );
}

import React, { useState } from 'react';
import { useWizard } from '@/contexts/WizardContext';
import { WizardFormLayout, FormField } from '../WizardFormLayout';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Sparkles, X, Brain, Cpu, Database, Zap, Activity, Layers, Settings, Microscope } from 'lucide-react';
import { useLLMGeneration } from '@/hooks/useLLMGeneration';
import { LLMErrorDisplay, LLMLoadingState } from '../LLMErrorDisplay';
import { ServiceWarning, useServiceStatus } from '@/components/ui/service-warning';
import { useAppStore } from '@/stores/useAppStore';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  TEMPERAMENTS,
  COMMUNICATION_STYLES,
} from '@/constants/characterOptions';
import type { Character } from '@/types/character';
import type { StoryContext } from './CharacterWizard';

// ============================================================================
// Step 3: Cognitive Matrix (Personality)
// ============================================================================

interface Step3PersonalityProps {
  storyContext?: StoryContext;
}

export function Step3Personality({ storyContext }: Step3PersonalityProps = {}) {
  const { formData, updateFormData, validationErrors } = useWizard<Character>();
  const [newTrait, setNewTrait] = useState('');
  const [newValue, setNewValue] = useState('');
  const [newFear, setNewFear] = useState('');
  const [newDesire, setNewDesire] = useState('');
  const [newFlaw, setNewFlaw] = useState('');
  const [newStrength, setNewStrength] = useState('');
  const setShowLLMSettings = useAppStore((state) => state.setShowLLMSettings);

  // Check if LLM service is configured
  const { llmConfigured, llmChecking } = useServiceStatus();

  // LLM generation for personality suggestions
  const {
    generate,
    isLoading,
    error: llmError,
    clearError,
  } = useLLMGeneration({
    onSuccess: (response) => {
      const personality = parseLLMPersonality(response.content);
      if (personality) {
        updateFormData({
          personality: {
            ...(formData.personality || {}),
            ...personality,
          } as Character['personality'],
        });
      }
    },
  });

  const handleGeneratePersonality = async () => {
    clearError();

    const uniqueEntropy = {
      timestamp: Date.now(),
      randomId: Math.random().toString(36).substring(2, 10),
      sessionSeed: Math.floor(Math.random() * 1000000),
    };

    const context = {
      characterName: formData.name || 'the character',
      archetype: formData.role?.archetype || 'character',
      ageRange: formData.visual_identity?.age_range || 'adult',
      appearance: formData.visual_identity,
      entropy: uniqueEntropy,
    };

    const systemPrompt = 'You are a character development expert. Create well-rounded, believable personalities.';

    const prompt = `Generate a detailed personality profile (Cognitive Matrix) for an entity:
- Name: ${context.characterName}
- Archetype: ${context.archetype}
- Maturity: ${context.ageRange}
- Features: ${context.appearance?.build || 'unspecified'}
- Entropy: ${uniqueEntropy.sessionSeed}

Format as JSON with keys: traits (array), values (array), fears (array), desires (array), flaws (array), strengths (array), temperament (string), communication_style (string)`;

    await generate({
      prompt,
      systemPrompt,
      temperature: 0.8,
      maxTokens: 1000,
    });
  };

  const parseLLMPersonality = (response: string): Partial<Character['personality']> | null => {
    try {
      const jsonMatch = response.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        const parsed = JSON.parse(jsonMatch[0]);
        const result: Partial<Character['personality']> = {};
        if (Array.isArray(parsed.traits)) result.traits = parsed.traits;
        if (Array.isArray(parsed.values)) result.values = parsed.values;
        if (Array.isArray(parsed.fears)) result.fears = parsed.fears;
        if (Array.isArray(parsed.desires)) result.desires = parsed.desires;
        if (Array.isArray(parsed.flaws)) result.flaws = parsed.flaws;
        if (Array.isArray(parsed.strengths)) result.strengths = parsed.strengths;
        if (parsed.temperament) result.temperament = parsed.temperament;
        if (parsed.communication_style || parsed.communicationStyle) {
          result.communication_style = parsed.communication_style || parsed.communicationStyle;
        }
        return result;
      }
    } catch (error) {
      console.error('Failed to parse LLM response:', error);
    }
    return null;
  };

  const handleAddItem = (
    field: keyof Character['personality'],
    value: string,
    setter: (value: string) => void
  ) => {
    if (value.trim()) {
      const currentArray = (formData.personality?.[field] as string[]) || [];
      updateFormData({
        personality: {
          ...(formData.personality || {}),
          [field]: [...currentArray, value.trim()],
        } as Character['personality'],
      });
      setter('');
    }
  };

  const handleRemoveItem = (field: keyof Character['personality'], index: number) => {
    const currentArray = (formData.personality?.[field] as string[]) || [];
    updateFormData({
      personality: {
        ...(formData.personality || {}),
        [field]: currentArray.filter((_, i) => i !== index),
      } as Character['personality'],
    });
  };

  const updatePersonality = (updates: Partial<Character['personality']>) => {
    updateFormData({
      personality: {
        ...(formData.personality || {}),
        ...updates,
      } as Character['personality']
    });
  };

  return (
    <WizardFormLayout
      title="Cognitive Matrix"
      description="Map the heuristic architecture and behavioral subroutines of the entity"
    >
      {/* AI Assistance Section */}
      <div className="space-y-4 mb-8 p-4 rounded-lg border border-primary/20 bg-primary/5 backdrop-blur-sm shadow-[inset_0_0_10px_rgba(var(--primary-rgb),0.05)]">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-base font-bold text-primary neon-text uppercase tracking-widest text-[10px] font-mono mb-1">// Neural Logic Synthesizer</h3>
            <p className="text-[10px] text-primary/60 uppercase tracking-wider">
              Synthesize a complex personality matrix from core identity datasets
            </p>
          </div>
          <Button
            onClick={handleGeneratePersonality}
            disabled={isLoading || llmChecking || !formData.role?.archetype || !llmConfigured}
            className="gap-2 btn-neon bg-primary/10 text-primary border-primary/20 hover:bg-primary/20"
            size="sm"
          >
            <Microscope className="h-3.5 w-3.5" />
            <span className="text-[10px] font-black uppercase tracking-widest">Synthesize Matrix</span>
          </Button>
        </div>

        {!llmChecking && !llmConfigured && (
          <ServiceWarning
            service="llm"
            variant="inline"
            onConfigure={() => setShowLLMSettings(true)}
            className="bg-red-500/10 border-red-500/20 text-red-400"
          />
        )}

        {isLoading && (
          <LLMLoadingState message="Synthesizing neural pathways..." showProgress />
        )}

        {llmError && (
          <LLMErrorDisplay
            error={llmError}
            onRetry={handleGeneratePersonality}
            onDismiss={clearError}
          />
        )}
      </div>

      <div className="space-y-10">
        {/* Core Heuristics */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {/* Traits & Values */}
          <div className="space-y-8">
            {/* Traits */}
            <div className="space-y-3 p-4 border border-primary/10 bg-primary/20 relative group">
              <div className="absolute -top-3 left-3 bg-[#050b10] px-2 py-0.5 border border-primary/20">
                <span className="text-[9px] font-black text-primary uppercase tracking-widest font-mono">Heuristic Attributes</span>
              </div>
              <div className="flex gap-2 mt-2">
                <Input
                  value={newTrait}
                  onChange={(e) => setNewTrait(e.target.value)}
                  placeholder="Add DEFINING_TRAIT..."
                  onKeyPress={(e) => e.key === 'Enter' && handleAddItem('traits', newTrait, setNewTrait)}
                  className="bg-primary/5 border-primary/20 text-[10px]"
                />
                <Button onClick={() => handleAddItem('traits', newTrait, setNewTrait)} className="btn-neon bg-primary/20 text-primary border-primary/20 px-3">
                  <span className="text-[10px] font-black uppercase tracking-widest">Inject</span>
                </Button>
              </div>
              <div className="flex flex-wrap gap-2">
                {formData.personality?.traits?.map((trait, index) => (
                  <Badge key={index} variant="outline" className="bg-primary/10 border-primary/30 text-primary px-2 py-1 rounded-none group hover:border-red-500/50 transition-colors">
                    <span className="text-[9px] font-mono uppercase tracking-wider">{trait}</span>
                    <button onClick={() => handleRemoveItem('traits', index)} className="ml-2 text-primary/40 hover:text-red-500 transition-colors">
                      <X className="w-3 h-3" />
                    </button>
                  </Badge>
                ))}
              </div>
            </div>

            {/* Values */}
            <div className="space-y-3 p-4 border border-primary/10 bg-primary/20 relative group">
              <div className="absolute -top-3 left-3 bg-[#050b10] px-2 py-0.5 border border-primary/20">
                <span className="text-[9px] font-black text-primary uppercase tracking-widest font-mono">Value Directives</span>
              </div>
              <div className="flex gap-2 mt-2">
                <Input
                  value={newValue}
                  onChange={(e) => setNewValue(e.target.value)}
                  placeholder="Add CORE_DIRECTIVE..."
                  onKeyPress={(e) => e.key === 'Enter' && handleAddItem('values', newValue, setNewValue)}
                  className="bg-primary/5 border-primary/20 text-[10px]"
                />
                <Button onClick={() => handleAddItem('values', newValue, setNewValue)} className="btn-neon bg-primary/20 text-primary border-primary/20 px-3">
                  <span className="text-[10px] font-black uppercase tracking-widest">Inject</span>
                </Button>
              </div>
              <div className="flex flex-wrap gap-2">
                {formData.personality?.values?.map((val, index) => (
                  <Badge key={index} variant="outline" className="bg-primary/10 border-primary/30 text-primary px-2 py-1 rounded-none group hover:border-red-500/50 transition-colors">
                    <span className="text-[9px] font-mono uppercase tracking-wider">{val}</span>
                    <button onClick={() => handleRemoveItem('values', index)} className="ml-2 text-primary/40 hover:text-red-500 transition-colors">
                      <X className="w-3 h-3" />
                    </button>
                  </Badge>
                ))}
              </div>
            </div>
          </div>

          {/* Inhibitors & Objectives */}
          <div className="space-y-8">
            {/* Fears */}
            <div className="space-y-3 p-4 border border-primary/10 bg-primary/20 relative group">
              <div className="absolute -top-3 left-3 bg-[#050b10] px-2 py-0.5 border border-primary/20">
                <span className="text-[9px] font-black text-primary uppercase tracking-widest font-mono">Inhibition Subroutines</span>
              </div>
              <div className="flex gap-2 mt-2">
                <Input
                  value={newFear}
                  onChange={(e) => setNewFear(e.target.value)}
                  placeholder="Add INHIBITOR..."
                  onKeyPress={(e) => e.key === 'Enter' && handleAddItem('fears', newFear, setNewFear)}
                  className="bg-primary/5 border-primary/20 text-[10px]"
                />
                <Button onClick={() => handleAddItem('fears', newFear, setNewFear)} className="btn-neon bg-primary/20 text-primary border-primary/20 px-3">
                  <span className="text-[10px] font-black uppercase tracking-widest">Inject</span>
                </Button>
              </div>
              <div className="flex flex-wrap gap-2">
                {formData.personality?.fears?.map((fear, index) => (
                  <Badge key={index} variant="outline" className="bg-primary/10 border-primary/30 text-primary px-2 py-1 rounded-none group hover:border-red-500/50 transition-colors">
                    <span className="text-[9px] font-mono uppercase tracking-wider">{fear}</span>
                    <button onClick={() => handleRemoveItem('fears', index)} className="ml-2 text-primary/40 hover:text-red-500 transition-colors">
                      <X className="w-3 h-3" />
                    </button>
                  </Badge>
                ))}
              </div>
            </div>

            {/* Desires */}
            <div className="space-y-3 p-4 border border-primary/10 bg-primary/20 relative group">
              <div className="absolute -top-3 left-3 bg-[#050b10] px-2 py-0.5 border border-primary/20">
                <span className="text-[9px] font-black text-primary uppercase tracking-widest font-mono">Expansion Objectives</span>
              </div>
              <div className="flex gap-2 mt-2">
                <Input
                  value={newDesire}
                  onChange={(e) => setNewDesire(e.target.value)}
                  placeholder="Add OBJECTIVE..."
                  onKeyPress={(e) => e.key === 'Enter' && handleAddItem('desires', newDesire, setNewDesire)}
                  className="bg-primary/5 border-primary/20 text-[10px]"
                />
                <Button onClick={() => handleAddItem('desires', newDesire, setNewDesire)} className="btn-neon bg-primary/20 text-primary border-primary/20 px-3">
                  <span className="text-[10px] font-black uppercase tracking-widest">Inject</span>
                </Button>
              </div>
              <div className="flex flex-wrap gap-2">
                {formData.personality?.desires?.map((desire, index) => (
                  <Badge key={index} variant="outline" className="bg-primary/10 border-primary/30 text-primary px-2 py-1 rounded-none group hover:border-red-500/50 transition-colors">
                    <span className="text-[9px] font-mono uppercase tracking-wider">{desire}</span>
                    <button onClick={() => handleRemoveItem('desires', index)} className="ml-2 text-primary/40 hover:text-red-500 transition-colors">
                      <X className="w-3 h-3" />
                    </button>
                  </Badge>
                ))}
              </div>
            </div>
          </div>
        </div>

        {/* Binary Balance: Strengths & Flaws */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mt-10">
          {/* Strengths */}
          <div className="space-y-3 p-4 border border-primary/10 bg-primary/20 relative group">
            <div className="absolute -top-3 left-3 bg-[#050b10] px-2 py-0.5 border border-primary/20">
              <span className="text-[9px] font-black text-primary uppercase tracking-widest font-mono">Functional Superiorities</span>
            </div>
            <div className="flex gap-2 mt-2">
              <Input
                value={newStrength}
                onChange={(e) => setNewStrength(e.target.value)}
                placeholder="Add SUPERIORITY..."
                onKeyPress={(e) => e.key === 'Enter' && handleAddItem('strengths', newStrength, setNewStrength)}
                className="bg-primary/5 border-primary/20 text-[10px]"
              />
              <Button onClick={() => handleAddItem('strengths', newStrength, setNewStrength)} className="btn-neon bg-primary/20 text-primary border-primary/20 px-3">
                <span className="text-[10px] font-black uppercase tracking-widest">Inject</span>
              </Button>
            </div>
            <div className="flex flex-wrap gap-2">
              {formData.personality?.strengths?.map((strength, index) => (
                <Badge key={index} variant="outline" className="bg-primary/10 border-primary/30 text-primary px-2 py-1 rounded-none group hover:border-red-500/50 transition-colors">
                  <span className="text-[9px] font-mono uppercase tracking-wider">{strength}</span>
                  <button onClick={() => handleRemoveItem('strengths', index)} className="ml-2 text-primary/40 hover:text-red-500 transition-colors">
                    <X className="w-3 h-3" />
                  </button>
                </Badge>
              ))}
            </div>
          </div>

          {/* Flaws */}
          <div className="space-y-3 p-4 border border-primary/10 bg-primary/20 relative group">
            <div className="absolute -top-3 left-3 bg-[#050b10] px-2 py-0.5 border border-primary/20">
              <span className="text-[9px] font-black text-primary uppercase tracking-widest font-mono">Logic Anomalies</span>
            </div>
            <div className="flex gap-2 mt-2">
              <Input
                value={newFlaw}
                onChange={(e) => setNewFlaw(e.target.value)}
                placeholder="Add ANOMALY..."
                onKeyPress={(e) => e.key === 'Enter' && handleAddItem('flaws', newFlaw, setNewFlaw)}
                className="bg-primary/5 border-primary/20 text-[10px]"
              />
              <Button onClick={() => handleAddItem('flaws', newFlaw, setNewFlaw)} className="btn-neon bg-primary/20 text-primary border-primary/20 px-3">
                <span className="text-[10px] font-black uppercase tracking-widest">Inject</span>
              </Button>
            </div>
            <div className="flex flex-wrap gap-2">
              {formData.personality?.flaws?.map((flaw, index) => (
                <Badge key={index} variant="outline" className="bg-primary/10 border-primary/30 text-primary px-2 py-1 rounded-none group hover:border-red-500/50 transition-colors">
                  <span className="text-[9px] font-mono uppercase tracking-wider">{flaw}</span>
                  <button onClick={() => handleRemoveItem('flaws', index)} className="ml-2 text-primary/40 hover:text-red-500 transition-colors">
                    <X className="w-3 h-3" />
                  </button>
                </Badge>
              ))}
            </div>
          </div>
        </div>

        {/* Baselines & Protocols */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <FormField label="Emotional Baseline" name="temperament">
            <Select
              value={TEMPERAMENTS.includes(formData.personality?.temperament as any) ? formData.personality?.temperament : (formData.personality?.temperament ? 'Other' : '')}
              onValueChange={(val) => updatePersonality({ temperament: val === 'Other' ? '' : val })}
            >
              <SelectTrigger className="bg-primary/5 border-primary/20">
                <SelectValue placeholder="Select baseline" />
              </SelectTrigger>
              <SelectContent className="bg-[#050b10] border-primary/30">
                {TEMPERAMENTS.map(t => (
                  <SelectItem key={t} value={t} className="focus:bg-primary/20 focus:text-primary uppercase text-[10px] font-mono">{t}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </FormField>

          <FormField label="Interface Protocol" name="communication_style">
            <Select
              value={COMMUNICATION_STYLES.includes(formData.personality?.communication_style as any) ? formData.personality?.communication_style : (formData.personality?.communication_style ? 'Other' : '')}
              onValueChange={(val) => updatePersonality({ communication_style: val === 'Other' ? '' : val })}
            >
              <SelectTrigger className="bg-primary/5 border-primary/20">
                <SelectValue placeholder="Select protocol" />
              </SelectTrigger>
              <SelectContent className="bg-[#050b10] border-primary/30">
                {COMMUNICATION_STYLES.map(s => (
                  <SelectItem key={s} value={s} className="focus:bg-primary/20 focus:text-primary uppercase text-[10px] font-mono">{s}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </FormField>
        </div>
      </div>
    </WizardFormLayout>
  );
}

import React, { useState } from 'react';
import { useWizard } from '@/contexts/WizardContext';
import { WizardFormLayout, FormField } from '../WizardFormLayout';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Sparkles, X, History, Calendar, Briefcase, GraduationCap, Users, Flag, Terminal, Microscope, Activity } from 'lucide-react';
import { useLLMGeneration } from '@/hooks/useLLMGeneration';
import { LLMErrorDisplay, LLMLoadingState } from '../LLMErrorDisplay';
import { ServiceWarning, useServiceStatus } from '@/components/ui/service-warning';
import { useAppStore } from '@/stores/useAppStore';
import type { Character } from '@/types/character';
import type { World } from '@/types/world';
import type { StoryContext } from './CharacterWizard';

// ============================================================================
// Step 4: Chronological Data (Background)
// ============================================================================

interface Step4BackgroundProps {
  worldContext?: World;
  storyContext?: StoryContext;
}

export function Step4Background({ worldContext }: Step4BackgroundProps) {
  const { formData, updateFormData } = useWizard<Character>();
  const [newEvent, setNewEvent] = useState('');
  const setShowLLMSettings = useAppStore((state) => state.setShowLLMSettings);

  // Check if LLM service is configured
  const { llmConfigured, llmChecking } = useServiceStatus();

  // LLM generation for background suggestions
  const {
    generate,
    isLoading,
    error: llmError,
    clearError,
  } = useLLMGeneration({
    onSuccess: (response) => {
      const background = parseLLMBackground(response.content);
      if (background) {
        updateFormData({
          background: {
            ...(formData.background || {}),
            ...background,
          } as Character['background'],
        });
      }
    },
  });

  const handleGenerateBackground = async () => {
    clearError();

    const context = {
      characterName: formData.name || 'the character',
      archetype: formData.role?.archetype || 'character',
      ageRange: formData.visual_identity?.age_range || 'adult',
      personality: formData.personality,
      worldGenre: worldContext?.genre?.join(', ') || 'fantasy',
      worldTone: worldContext?.tone?.join(', ') || 'dramatic',
      worldTimePeriod: worldContext?.timePeriod || 'medieval',
    };

    const systemPrompt = 'You are a character backstory specialist. Create detailed, believable backgrounds.';

    const prompt = `Generate a detailed background (Chronological Data) for an entity:
- Name: ${context.characterName}
- Archetype: ${context.archetype}
- Maturity: ${context.ageRange}
- Traits: ${context.personality?.traits?.join(', ') || 'unspecified'}
- Genre: ${context.worldGenre}
- Tone: ${context.worldTone}

Format as JSON with keys: origin (string), occupation (string), education (string), family (string), significant_events (array of strings), current_situation (string)`;

    await generate({
      prompt,
      systemPrompt,
      temperature: 0.8,
      maxTokens: 1200,
    });
  };

  const parseLLMBackground = (response: string): Partial<Character['background']> | null => {
    try {
      const jsonMatch = response.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        const parsed = JSON.parse(jsonMatch[0]);
        const result: Partial<Character['background']> = {};
        if (parsed.origin) result.origin = parsed.origin;
        if (parsed.occupation) result.occupation = parsed.occupation;
        if (parsed.education) result.education = parsed.education;
        if (parsed.family) result.family = parsed.family;
        if (Array.isArray(parsed.significant_events) || Array.isArray(parsed.significantEvents)) {
          result.significant_events = parsed.significant_events || parsed.significantEvents;
        }
        if (parsed.current_situation || parsed.currentSituation) {
          result.current_situation = parsed.current_situation || parsed.currentSituation;
        }
        return result;
      }
    } catch (error) {
      console.error('Failed to parse LLM response:', error);
    }
    return null;
  };

  const handleAddEvent = () => {
    if (newEvent.trim()) {
      const events = formData.background?.significant_events || [];
      updateBackground({ significant_events: [...events, newEvent.trim()] });
      setNewEvent('');
    }
  };

  const handleRemoveEvent = (index: number) => {
    const events = formData.background?.significant_events || [];
    updateBackground({ significant_events: events.filter((_, i) => i !== index) });
  };

  const updateBackground = (updates: Partial<Character['background']>) => {
    updateFormData({
      background: {
        ...(formData.background || {}),
        ...updates,
      } as Character['background']
    });
  };

  return (
    <WizardFormLayout
      title="Chronological Data"
      description="Access and reconstruct the historical datasets and causal events of the entity"
    >
      {/* AI Assistance Section */}
      <div className="space-y-4 mb-8 p-4 rounded-lg border border-primary/20 bg-primary/5 backdrop-blur-sm shadow-[inset_0_0_10px_rgba(var(--primary-rgb),0.05)]">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-base font-bold text-primary neon-text uppercase tracking-widest text-[10px] font-mono mb-1">// Timeline Synthesizer</h3>
            <p className="text-[10px] text-primary/60 uppercase tracking-wider">
              Reconstruct the entity's chronological trajectory from heuristic datasets
            </p>
          </div>
          <Button
            onClick={handleGenerateBackground}
            disabled={isLoading || llmChecking || !formData.personality?.traits?.length || !llmConfigured}
            className="gap-2 btn-neon bg-primary/10 text-primary border-primary/20 hover:bg-primary/20"
            size="sm"
          >
            <Microscope className="h-3.5 w-3.5" />
            <span className="text-[10px] font-black uppercase tracking-widest">Synthesize Timeline</span>
          </Button>
        </div>

        {!llmChecking && !llmConfigured && (
          <ServiceWarning
            service="llm"
            variant="inline"
            onConfigure={() => setShowLLMSettings(true)}
            className="bg-red-500/10 border-red-500/20 text-red-400"
          />
        )}

        {isLoading && (
          <LLMLoadingState message="Accessing chronological archives..." showProgress />
        )}

        {llmError && (
          <LLMErrorDisplay
            error={llmError}
            onRetry={handleGenerateBackground}
            onDismiss={clearError}
          />
        )}
      </div>

      <div className="space-y-10">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <FormField label="Causal Inception (Origin)" name="origin">
            <div className="relative group">
              <History className="absolute left-3 top-3 h-5 w-5 text-primary/40 group-focus-within:text-primary transition-colors" />
              <Textarea
                value={formData.background?.origin || ''}
                onChange={(e) => updateBackground({ origin: e.target.value })}
                placeholder="Define the causal origins and developmental environments..."
                rows={4}
                className="pl-10 bg-primary/5 border-primary/20"
              />
            </div>
          </FormField>

          <FormField label="Lineage Matrix (Family)" name="family">
            <div className="relative group">
              <Users className="absolute left-3 top-3 h-5 w-5 text-primary/40 group-focus-within:text-primary transition-colors" />
              <Textarea
                value={formData.background?.family || ''}
                onChange={(e) => updateBackground({ family: e.target.value })}
                placeholder="Map the interpersonal lineage and primary connections..."
                rows={4}
                className="pl-10 bg-primary/5 border-primary/20"
              />
            </div>
          </FormField>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <FormField label="Functional Designation (Occupation)" name="occupation">
            <div className="relative group">
              <Briefcase className="absolute left-3 top-3 h-5 w-5 text-primary/40 group-focus-within:text-primary transition-colors" />
              <Textarea
                value={formData.background?.occupation || ''}
                onChange={(e) => updateBackground({ occupation: e.target.value })}
                placeholder="Specify functional roles and developed skillsets..."
                rows={3}
                className="pl-10 bg-primary/5 border-primary/20"
              />
            </div>
          </FormField>

          <FormField label="Acquisition Profile (Education)" name="education">
            <div className="relative group">
              <GraduationCap className="absolute left-3 top-3 h-5 w-5 text-primary/40 group-focus-within:text-primary transition-colors" />
              <Textarea
                value={formData.background?.education || ''}
                onChange={(e) => updateBackground({ education: e.target.value })}
                placeholder="Reconstruct the knowledge acquisition trajectory..."
                rows={3}
                className="pl-10 bg-primary/5 border-primary/20"
              />
            </div>
          </FormField>
        </div>

        {/* Critical Iterations (Significant Events) */}
        <div className="space-y-4 p-4 border border-primary/20 bg-primary/5">
          <div className="flex items-center gap-2 mb-2">
            <Activity className="h-4 w-4 text-primary" />
            <span className="text-[10px] font-black uppercase tracking-[0.2em] text-primary">Critical Iterations (Significant Events)</span>
          </div>

          <div className="flex gap-2">
            <Input
              value={newEvent}
              onChange={(e) => setNewEvent(e.target.value)}
              placeholder="Record critical event..."
              onKeyPress={(e) => e.key === 'Enter' && handleAddEvent()}
              className="bg-primary/5 border-primary/20"
            />
            <Button onClick={handleAddEvent} className="btn-neon bg-primary/20 text-primary border-primary/20 px-4">
              <span className="text-[10px] font-black uppercase tracking-widest">Inject Moment</span>
            </Button>
          </div>

          <div className="space-y-2">
            {formData.background?.significant_events?.map((event, index) => (
              <div key={index} className="flex items-start gap-3 p-3 border border-primary/10 bg-primary/5 group">
                <Terminal className="h-4 w-4 text-primary/40 mt-0.5" />
                <span className="flex-1 text-[11px] font-mono text-primary/80">{event}</span>
                <button
                  onClick={() => handleRemoveEvent(index)}
                  className="text-primary/20 hover:text-red-500 transition-colors"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>
            ))}
            {(!formData.background?.significant_events || formData.background.significant_events.length === 0) && (
              <p className="text-[10px] text-primary/30 uppercase tracking-widest font-mono italic p-2 border border-dashed border-primary/10">No iterations recorded</p>
            )}
          </div>
        </div>

        <FormField label="Active Parameters (Current Situation)" name="current_situation">
          <div className="relative group">
            <Flag className="absolute left-3 top-3 h-5 w-5 text-primary/40 group-focus-within:text-primary transition-colors" />
            <Textarea
              value={formData.background?.current_situation || ''}
              onChange={(e) => updateBackground({ current_situation: e.target.value })}
              placeholder="Describe the active state and immediate contextual factors..."
              rows={4}
              className="pl-10 bg-primary/5 border-primary/20"
            />
          </div>
        </FormField>
      </div>
    </WizardFormLayout>
  );
}

import { useState } from 'react';
import { useWizard } from '@/contexts/WizardContext';
import { WizardFormLayout, FormField } from '../WizardFormLayout';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Plus, Trash2, AlertCircle, CheckCircle2, Share2, Users, Link2, GitCommit, Shield, Heart, Zap, ZapOff, Terminal, Activity } from 'lucide-react';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { useCharacters } from '@/store';
import { cn } from '@/lib/utils';
import type { Character, CharacterRelationship } from '@/types/character';
import type { StoryContext } from './CharacterWizard';

// ============================================================================
// Step 5: Social Linkages (Relationships)
// ============================================================================

interface Step5RelationshipsProps {
  storyContext?: StoryContext;
}

const RELATIONSHIP_TYPES = [
  'Genetic / Unit',
  'Allied Peer',
  'Symbiotic Partner',
  'Knowledge Node',
  'Processing Node',
  'Competitive Parallel',
  'Antagonistic Adversary',
  'Strategic Proxy',
  'Operational Associate',
  'Casual Node',
  'Other / Custom',
];

const RELATIONSHIP_DYNAMICS = [
  'Augmenting',
  'Subtractive',
  'Non-Linear',
  'High-Latency',
  'Low-Latency',
  'Adaptive',
  'Fragmented',
  'Synchronized',
  'Sustained',
  'Autonomous',
];

export function Step5Relationships({ storyContext }: Step5RelationshipsProps = {}) {
  const { formData, updateFormData, validationErrors } = useWizard<Character>();
  const existingCharacters = useCharacters();

  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [currentRelationship, setCurrentRelationship] = useState<CharacterRelationship>({
    character_id: '',
    character_name: '',
    relationship_type: '',
    description: '',
    dynamic: '',
  });
  const [useExistingCharacter, setUseExistingCharacter] = useState<boolean>(true);
  const [validationError, setValidationError] = useState<string>('');

  const validateCharacterExists = (characterId: string): boolean => {
    if (!characterId) return false;
    return existingCharacters.some((char) => char.character_id === characterId);
  };

  const getCharacterNameById = (characterId: string): string => {
    const character = existingCharacters.find((char) => char.character_id === characterId);
    return character?.name || '';
  };

  const handleAddRelationship = () => {
    if (useExistingCharacter && !validateCharacterExists(currentRelationship.character_id)) {
      setValidationError('Entity archival lookup failed: Selection required');
      return;
    }

    if (!useExistingCharacter && !currentRelationship.character_name.trim()) {
      setValidationError('Entity designation failed: Identifier required');
      return;
    }

    if (!currentRelationship.relationship_type) {
      setValidationError('Linkage protocol failed: Type required');
      return;
    }

    setValidationError('');

    const relationshipData: CharacterRelationship = {
      ...currentRelationship,
      character_id: useExistingCharacter
        ? currentRelationship.character_id
        : crypto.randomUUID(),
      character_name: useExistingCharacter
        ? getCharacterNameById(currentRelationship.character_id)
        : currentRelationship.character_name,
    };

    if (editingIndex !== null) {
      const relationships = [...(formData.relationships || [])];
      relationships[editingIndex] = relationshipData;
      updateFormData({ relationships });
      setEditingIndex(null);
    } else {
      const relationships = formData.relationships || [];
      updateFormData({
        relationships: [...relationships, relationshipData],
      });
    }

    setCurrentRelationship({
      character_id: '',
      character_name: '',
      relationship_type: '',
      description: '',
      dynamic: '',
    });
    setUseExistingCharacter(existingCharacters.length > 0);
  };

  const handleEditRelationship = (index: number) => {
    const relationship = formData.relationships?.[index];
    if (relationship) {
      setCurrentRelationship(relationship);
      setEditingIndex(index);
      const isExisting = validateCharacterExists(relationship.character_id);
      setUseExistingCharacter(isExisting);
      setValidationError('');
    }
  };

  const handleDeleteRelationship = (index: number) => {
    const relationships = formData.relationships || [];
    updateFormData({
      relationships: relationships.filter((_, i) => i !== index),
    });
  };

  const handleCancelEdit = () => {
    setEditingIndex(null);
    setCurrentRelationship({
      character_id: '',
      character_name: '',
      relationship_type: '',
      description: '',
      dynamic: '',
    });
    setUseExistingCharacter(existingCharacters.length > 0);
    setValidationError('');
  };

  const isFormValid = () => {
    if (useExistingCharacter) {
      return (
        currentRelationship.character_id !== '' &&
        currentRelationship.relationship_type !== '' &&
        validateCharacterExists(currentRelationship.character_id)
      );
    } else {
      return (
        currentRelationship.character_name.trim() !== '' &&
        currentRelationship.relationship_type !== ''
      );
    }
  };

  const isRelationshipValid = (relationship: CharacterRelationship): boolean => {
    return validateCharacterExists(relationship.character_id);
  };

  return (
    <WizardFormLayout
      title="SocialGrid Nexus"
      description="Initialize interpersonal linkages and map social proximity within the network"
    >
      <div className="space-y-10">
        {/* Connection Setup */}
        <div className="p-6 border border-primary/20 bg-primary/5 backdrop-blur-sm relative">
          <div className="absolute -top-3 left-6 bg-[#050b10] px-3 py-0.5 border border-primary/20">
            <span className="text-[10px] font-black text-primary neon-text uppercase tracking-widest font-mono">
              {editingIndex !== null ? '// Linkage Modification' : '// Linkage Initialization'}
            </span>
          </div>

          <div className="space-y-6 mt-2">
            {/* Source Selection */}
            {existingCharacters.length > 0 && (
              <div className="space-y-3">
                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-primary/60 font-mono italic">Select Entity Source:</span>
                <div className="flex gap-6">
                  <label className="flex items-center gap-3 cursor-pointer group">
                    <div className={cn(
                      "w-4 h-4 border flex items-center justify-center transition-all",
                      useExistingCharacter ? "border-primary bg-primary/20 shadow-[0_0_8px_rgba(var(--primary-rgb),0.5)]" : "border-primary/20 hover:border-primary/50"
                    )}>
                      {useExistingCharacter && <div className="w-1.5 h-1.5 bg-primary pulse-neon" />}
                      <input type="radio" checked={useExistingCharacter} onChange={() => { setUseExistingCharacter(true); setValidationError(''); }} className="hidden" />
                    </div>
                    <span className={cn("text-[11px] font-mono uppercase tracking-wider transition-colors", useExistingCharacter ? "text-primary" : "text-primary/40 group-hover:text-primary/60")}>Archive Entity</span>
                  </label>
                  <label className="flex items-center gap-2 cursor-pointer group">
                    <div className={cn(
                      "w-4 h-4 border flex items-center justify-center transition-all",
                      !useExistingCharacter ? "border-primary bg-primary/20 shadow-[0_0_8px_rgba(var(--primary-rgb),0.5)]" : "border-primary/20 hover:border-primary/50"
                    )}>
                      {!useExistingCharacter && <div className="w-1.5 h-1.5 bg-primary pulse-neon" />}
                      <input type="radio" checked={!useExistingCharacter} onChange={() => { setUseExistingCharacter(false); setValidationError(''); }} className="hidden" />
                    </div>
                    <span className={cn("text-[11px] font-mono uppercase tracking-wider transition-colors", !useExistingCharacter ? "text-primary" : "text-primary/40 group-hover:text-primary/60")}>Unregistered Entity</span>
                  </label>
                </div>
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {useExistingCharacter && existingCharacters.length > 0 ? (
                <FormField label="Target Archive Entity" name="character_id">
                  <Select
                    value={currentRelationship.character_id}
                    onValueChange={(value) => {
                      setCurrentRelationship({
                        ...currentRelationship,
                        character_id: value,
                        character_name: getCharacterNameById(value),
                      });
                      setValidationError('');
                    }}
                  >
                    <SelectTrigger className="bg-primary/5 border-primary/20 font-mono text-[10px]">
                      <SelectValue placeholder="Accessing archives..." />
                    </SelectTrigger>
                    <SelectContent className="bg-[#050b10] border-primary/30">
                      {existingCharacters
                        .filter((char) => char.character_id !== formData.character_id)
                        .map((character) => (
                          <SelectItem key={character.character_id} value={character.character_id} className="focus:bg-primary/20 text-[10px] font-mono uppercase">
                            {character.name} {character.role?.archetype && `[${character.role.archetype}]`}
                          </SelectItem>
                        ))
                      }
                    </SelectContent>
                  </Select>
                </FormField>
              ) : (
                <FormField label="Entity Designation" name="character_name">
                  <Input
                    value={currentRelationship.character_name}
                    onChange={(e) => { setCurrentRelationship({ ...currentRelationship, character_name: e.target.value }); setValidationError(''); }}
                    placeholder="Input identifier..."
                    className="bg-primary/5 border-primary/20 font-mono text-[10px]"
                  />
                </FormField>
              )}

              <FormField label="Linkage Protocol (Type)" name="relationship_type">
                <Select
                  value={currentRelationship.relationship_type}
                  onValueChange={(value) => setCurrentRelationship({ ...currentRelationship, relationship_type: value })}
                >
                  <SelectTrigger className="bg-primary/5 border-primary/20 font-mono text-[10px]">
                    <SelectValue placeholder="Protocol defined..." />
                  </SelectTrigger>
                  <SelectContent className="bg-[#050b10] border-primary/30">
                    {RELATIONSHIP_TYPES.map((type) => (
                      <SelectItem key={type} value={type} className="focus:bg-primary/20 text-[10px] font-mono uppercase">
                        {type}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </FormField>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <FormField label="Iterative Dynamic" name="dynamic">
                <Select
                  value={currentRelationship.dynamic}
                  onValueChange={(value) => setCurrentRelationship({ ...currentRelationship, dynamic: value })}
                >
                  <SelectTrigger className="bg-primary/5 border-primary/20 font-mono text-[10px]">
                    <SelectValue placeholder="Dynamic state..." />
                  </SelectTrigger>
                  <SelectContent className="bg-[#050b10] border-primary/30">
                    {RELATIONSHIP_DYNAMICS.map((dynamic) => (
                      <SelectItem key={dynamic} value={dynamic} className="focus:bg-primary/20 text-[10px] font-mono uppercase">
                        {dynamic}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </FormField>

              <FormField label="Operational History" name="description">
                <Textarea
                  value={currentRelationship.description}
                  onChange={(e) => setCurrentRelationship({ ...currentRelationship, description: e.target.value })}
                  placeholder="Detail the causal history of this linkage..."
                  rows={3}
                  className="bg-primary/5 border-primary/20 text-[10px]"
                />
              </FormField>
            </div>

            {validationError && (
              <div className="p-2 border border-red-500/30 bg-red-500/5 flex items-center gap-2">
                <AlertCircle className="w-3.5 h-3.5 text-red-500" />
                <span className="text-[10px] text-red-400 font-mono uppercase tracking-tighter">{validationError}</span>
              </div>
            )}

            <div className="flex gap-3">
              <Button
                onClick={handleAddRelationship}
                disabled={!isFormValid()}
                className="flex-1 btn-neon bg-primary/20 text-primary border-primary/20"
              >
                <Plus className="w-4 h-4 mr-2" />
                <span className="text-[10px] font-black uppercase tracking-widest">
                  {editingIndex !== null ? 'Modify Linkage' : 'Initialize Linkage'}
                </span>
              </Button>
              {editingIndex !== null && (
                <Button onClick={handleCancelEdit} variant="outline" className="border-primary/20 text-primary/60 hover:text-primary">
                  <span className="text-[10px] font-black uppercase tracking-widest">Abort</span>
                </Button>
              )}
            </div>
          </div>
        </div>

        {/* Linkage Archives */}
        <div className="space-y-4">
          <div className="flex items-center gap-2 text-primary/60">
            <Terminal className="h-4 w-4" />
            <span className="text-[10px] font-black uppercase tracking-[0.2em]">Active Linkage Archives</span>
          </div>

          {formData.relationships && formData.relationships.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {formData.relationships.map((rel, index) => {
                const isValid = isRelationshipValid(rel);
                return (
                  <div key={index} className={cn(
                    "p-4 border bg-primary/5 relative group transition-all",
                    isValid ? "border-primary/10 hover:border-primary/30" : "border-yellow-500/30 bg-yellow-500/5 hover:border-yellow-500/50"
                  )}>
                    <div className="flex justify-between items-start mb-2">
                      <div className="space-y-1">
                        <div className="flex items-center gap-2">
                          <span className="text-[11px] font-black uppercase text-primary tracking-wider">{rel.character_name}</span>
                          {isValid ? <CheckCircle2 className="w-3 h-3 text-green-500" /> : <AlertCircle className="w-3 h-3 text-yellow-500" />}
                        </div>
                        <div className="flex flex-wrap gap-2">
                          <span className="text-[9px] font-mono px-1.5 py-0.5 border border-primary/20 bg-primary/10 text-primary/80 uppercase tracking-tighter">{rel.relationship_type}</span>
                          {rel.dynamic && <span className="text-[9px] font-mono px-1.5 py-0.5 border border-primary/20 bg-primary/10 text-primary/60 uppercase tracking-tighter">{rel.dynamic}</span>}
                        </div>
                      </div>
                      <div className="flex gap-1">
                        <Button onClick={() => handleEditRelationship(index)} variant="ghost" size="icon" className="h-7 w-7 text-primary/40 hover:text-primary hover:bg-primary/10">
                          <Activity className="h-3.5 w-3.5" />
                        </Button>
                        <Button onClick={() => handleDeleteRelationship(index)} variant="ghost" size="icon" className="h-7 w-7 text-primary/20 hover:text-red-500 hover:bg-red-500/10">
                          <Trash2 className="h-3.5 w-3.5" />
                        </Button>
                      </div>
                    </div>
                    {rel.description && (
                      <p className="text-[10px] font-mono text-primary/60 italic line-clamp-2 mt-2 pt-2 border-t border-primary/5">
                        "{rel.description}"
                      </p>
                    )}
                    {!isValid && (
                      <div className="mt-2 text-[9px] text-yellow-600 font-mono uppercase tracking-tighter opacity-70">
                        [!] archival target unregistered [!]
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          ) : (
            <div className="p-8 border border-dashed border-primary/10 flex flex-col items-center justify-center opacity-40">
              <Share2 className="h-8 w-8 text-primary/20 mb-3" />
              <p className="text-[10px] font-mono uppercase tracking-widest text-primary/60">No linkages initialized</p>
            </div>
          )}
        </div>
      </div>
    </WizardFormLayout>
  );
}

import React, { useState } from 'react';
import { Palette, Brain, X, Plus } from 'lucide-react';
import type { Character } from '@/types/character';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  HAIR_COLORS,
  EYE_COLORS,
  SKIN_TONES,
  BODY_BUILDS,
  HEIGHT_CATEGORIES,
} from '@/constants/characterOptions';
import { EnhancedCharacterAssistant } from '../../character-creator/EnhancedCharacterAssistant';

interface EssenceStepProps {
  data: Partial<Character>;
  onUpdate: (data: Partial<Character>) => void;
  worldContext?: any;
}

export function EssenceStep({ data, onUpdate, worldContext }: EssenceStepProps) {
  const [newTrait, setNewTrait] = useState('');
  const [newColor, setNewColor] = useState('');
  const [newFeature, setNewFeature] = useState('');

  const updateVisual = (updates: Partial<Character['visual_identity']>) => {
    onUpdate({
      visual_identity: {
        ...data.visual_identity,
        ...updates,
      } as Character['visual_identity'],
    });
  };

  const updatePersonality = (updates: Partial<Character['personality']>) => {
    onUpdate({
      personality: {
        ...data.personality,
        ...updates,
      } as Character['personality'],
    });
  };

  const handleAddTrait = () => {
    if (newTrait.trim()) {
      const traits = data.personality?.traits || [];
      if (!traits.includes(newTrait.trim())) {
        updatePersonality({ traits: [...traits, newTrait.trim()] });
      }
      setNewTrait('');
    }
  };

  const handleRemoveTrait = (trait: string) => {
    const traits = data.personality?.traits || [];
    updatePersonality({ traits: traits.filter((t) => t !== trait) });
  };

  const handleAddColor = () => {
    if (newColor.trim()) {
      const colors = data.visual_identity?.color_palette || [];
      if (!colors.includes(newColor.trim())) {
        updateVisual({ color_palette: [...colors, newColor.trim()] });
      }
      setNewColor('');
    }
  };

  const handleRemoveColor = (color: string) => {
    const colors = data.visual_identity?.color_palette || [];
    updateVisual({ color_palette: colors.filter((c) => c !== color) });
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {/* Psychology Section */}
      <section className="bg-white dark:bg-gray-900 p-8 rounded-3xl border border-gray-100 dark:border-gray-800 shadow-xl space-y-6">
        <div className="flex items-center justify-between pb-4 border-b border-gray-100 dark:border-gray-800">
          <div className="flex items-center gap-3">
            <Brain className="w-5 h-5 text-purple-500" />
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-gray-400">Psychology & Essence</h3>
          </div>
          <EnhancedCharacterAssistant
            suggestionType="personality"
            characterData={data as any}
            worldContext={worldContext}
            onSuggestion={(field, val) => {
              if (field === 'personality') {
                 const currentTraits = data.personality?.traits || [];
                 const newTraits = Array.isArray(val) ? val : [val];
                 updatePersonality({ traits: Array.from(new Set([...currentTraits, ...newTraits])) as string[] });
              }
            }}
          />
        </div>

        <div className="space-y-4">
          <label className="text-[10px] font-black uppercase tracking-[0.2em] text-purple-500/70 ml-1">
            Personality Traits
          </label>
          <div className="flex gap-2">
            <Input
              value={newTrait}
              onChange={(e) => setNewTrait(e.target.value)}
              placeholder="Inject trait..."
              onKeyPress={(e) => e.key === 'Enter' && handleAddTrait()}
              className="flex-1 bg-gray-50 dark:bg-gray-800 border-transparent focus:border-purple-500 rounded-xl"
            />
            <Button onClick={handleAddTrait} className="bg-purple-100 text-purple-600 hover:bg-purple-200 border-none rounded-xl px-4">
              <Plus size={18} />
            </Button>
          </div>

          <div className="flex flex-wrap gap-2 pt-2">
            {data.personality?.traits?.map((trait) => (
              <Badge key={trait} className="bg-purple-50 dark:bg-purple-900/20 text-purple-600 dark:text-purple-300 border-purple-100 dark:border-purple-800/50 px-3 py-1.5 rounded-full flex items-center gap-2 hover:bg-purple-100 dark:hover:bg-purple-900/40 transition-colors">
                <span className="text-xs font-bold">{trait}</span>
                <button onClick={() => handleRemoveTrait(trait)} className="hover:text-red-500 transition-colors">
                  <X size={14} />
                </button>
              </Badge>
            ))}
            {!data.personality?.traits?.length && (
              <p className="text-xs text-gray-400 italic">No traits defined yet.</p>
            )}
          </div>
        </div>

        <div className="space-y-2 pt-4">
           <label className="text-[10px] font-black uppercase tracking-[0.2em] text-purple-500/70 ml-1">
              Temperament & Values
           </label>
           <textarea
              value={data.personality?.temperament || ''}
              onChange={(e) => updatePersonality({ temperament: e.target.value })}
              placeholder="Describe the internal drive and core values..."
              className="w-full p-4 min-h-[80px] bg-gray-50 dark:bg-gray-800 border-2 border-transparent focus:border-purple-500 focus:bg-white dark:focus:bg-gray-950 rounded-2xl transition-all outline-none resize-none"
           />
        </div>
      </section>

      {/* Morphological Section */}
      <section className="bg-white dark:bg-gray-900 p-8 rounded-3xl border border-gray-100 dark:border-gray-800 shadow-xl space-y-8">
        <div className="flex items-center justify-between pb-4 border-b border-gray-100 dark:border-gray-800">
          <div className="flex items-center gap-3">
            <Palette className="w-5 h-5 text-blue-500" />
            <h3 className="text-sm font-black uppercase tracking-[0.2em] text-gray-400">Morphology & Form</h3>
          </div>
          <EnhancedCharacterAssistant
            suggestionType="appearance"
            characterData={data as any}
            worldContext={worldContext}
            onSuggestion={(field, val) => {
              if (field === 'appearance') {
                updateVisual({ distinctive_features: Array.isArray(val) ? val : [String(val)] });
              }
            }}
          />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
           <div className="space-y-2">
              <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500/70 ml-1">Hair Logic</label>
              <Select value={data.visual_identity?.hair_color || ''} onValueChange={(val) => updateVisual({ hair_color: val })}>
                <SelectTrigger className="bg-gray-50 dark:bg-gray-800 border-transparent rounded-xl">
                  <SelectValue placeholder="Color" />
                </SelectTrigger>
                <SelectContent>
                  {HAIR_COLORS.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}
                </SelectContent>
              </Select>
           </div>
           <div className="space-y-2">
              <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500/70 ml-1">Ocular Hue</label>
              <Select value={data.visual_identity?.eye_color || ''} onValueChange={(val) => updateVisual({ eye_color: val })}>
                <SelectTrigger className="bg-gray-50 dark:bg-gray-800 border-transparent rounded-xl">
                  <SelectValue placeholder="Eyes" />
                </SelectTrigger>
                <SelectContent>
                  {EYE_COLORS.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}
                </SelectContent>
              </Select>
           </div>
           <div className="space-y-2">
              <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500/70 ml-1">Skin Tone</label>
              <Select value={data.visual_identity?.skin_tone || ''} onValueChange={(val) => updateVisual({ skin_tone: val })}>
                <SelectTrigger className="bg-gray-50 dark:bg-gray-800 border-transparent rounded-xl">
                  <SelectValue placeholder="Tone" />
                </SelectTrigger>
                <SelectContent>
                  {SKIN_TONES.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}
                </SelectContent>
              </Select>
           </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
           <div className="space-y-2">
              <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500/70 ml-1">Height Profile</label>
              <Select value={data.visual_identity?.height || ''} onValueChange={(val) => updateVisual({ height: val })}>
                <SelectTrigger className="bg-gray-50 dark:bg-gray-800 border-transparent rounded-xl">
                  <SelectValue placeholder="Height" />
                </SelectTrigger>
                <SelectContent>
                  {HEIGHT_CATEGORIES.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}
                </SelectContent>
              </Select>
           </div>
           <div className="space-y-2">
              <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500/70 ml-1">Structural Build</label>
              <Select value={data.visual_identity?.build || ''} onValueChange={(val) => updateVisual({ build: val })}>
                <SelectTrigger className="bg-gray-50 dark:bg-gray-800 border-transparent rounded-xl">
                  <SelectValue placeholder="Build" />
                </SelectTrigger>
                <SelectContent>
                  {BODY_BUILDS.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}
                </SelectContent>
              </Select>
           </div>
        </div>

        <div className="space-y-2">
           <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500/70 ml-1">Visual Metadata (Distinctive Features)</label>
           <Input
              value={newFeature}
              onChange={(e) => setNewFeature(e.target.value)}
              placeholder="Add scar, tattoo, cyberware..."
              onKeyPress={(e) => {
                if (e.key === 'Enter' && newFeature.trim()) {
                  const features = data.visual_identity?.distinctive_features || [];
                  updateVisual({ distinctive_features: [...features, newFeature.trim()] });
                  setNewFeature('');
                }
              }}
              className="bg-gray-50 dark:bg-gray-800 border-transparent rounded-xl mb-2"
           />
           <div className="flex flex-wrap gap-2">
             {data.visual_identity?.distinctive_features?.map((f, i) => (
                <Badge key={i} variant="outline" className="border-blue-200 dark:border-blue-800 text-blue-600 dark:text-blue-400 rounded-lg px-2 py-1 flex items-center gap-1">
                   {f}
                   <X size={12} className="cursor-pointer" onClick={() => {
                     const features = data.visual_identity?.distinctive_features || [];
                     updateVisual({ distinctive_features: features.filter((_, idx) => idx !== i) });
                   }} />
                </Badge>
             ))}
           </div>
        </div>

        <div className="space-y-2">
           <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500/70 ml-1">Aesthetic Attire</label>
           <textarea
              value={data.visual_identity?.clothing_style || ''}
              onChange={(e) => updateVisual({ clothing_style: e.target.value })}
              placeholder="Describe typical clothing and accessories..."
              className="w-full p-4 min-h-[80px] bg-gray-50 dark:bg-gray-800 border-2 border-transparent focus:border-blue-500 focus:bg-white dark:focus:bg-gray-950 rounded-2xl transition-all outline-none resize-none"
           />
        </div>
      </section>
    </div>
  );
}

import React, { useState } from 'react';
import { Sparkles, CheckCircle2, User, Fingerprint, Clock } from 'lucide-react';
import type { Character } from '@/types/character';
import { CHARACTER_ARCHETYPES, AGE_RANGES, GENDER_OPTIONS } from '@/constants/characterOptions';
import { CHARACTER_PRESETS, CharacterPreset, ICONS } from '../presets';
import { Input } from '@/components/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';

interface IdentityStepProps {
  data: Partial<Character>;
  onUpdate: (data: Partial<Character>) => void;
  onApplyPreset: (preset: CharacterPreset) => void;
}

export function IdentityStep({ data, onUpdate, onApplyPreset }: IdentityStepProps) {
  const [selectedPresetId, setSelectedPresetId] = useState<string | null>(null);

  const handleFieldChange = (field: string, value: any) => {
    if (field === 'archetype') {
      onUpdate({ role: { ...data.role, archetype: value } as Character['role'] });
    } else if (field === 'age_range' || field === 'gender') {
      onUpdate({ 
        visual_identity: { 
          ...data.visual_identity, 
          [field]: value 
        } as Character['visual_identity'] 
      });
    } else {
      onUpdate({ [field]: value });
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {/* Presets Grid */}
      <section>
        <div className="flex items-center gap-2 mb-4">
          <Sparkles className="w-5 h-5 text-amber-500" />
          <h3 className="text-xl font-bold text-gray-800 dark:text-gray-100 uppercase tracking-tight">
            Identity Template
          </h3>
        </div>
        
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {/* Start Fresh Option */}
          <button
            onClick={() => {
              setSelectedPresetId('fresh');
              onApplyPreset({
                id: 'fresh',
                name: 'Blank Slate',
                description: 'Define your character entirely from scratch.',
                icon: ICONS.fresh,
                archetype: '',
                traits: [],
              });
            }}
            className={`group relative p-5 rounded-2xl border-2 text-left transition-all duration-300 ${
              selectedPresetId === 'fresh' 
                ? 'border-blue-500 bg-blue-50/50 dark:bg-blue-900/20 shadow-lg' 
                : 'border-gray-200 dark:border-gray-800 hover:border-blue-300 dark:hover:border-blue-700 hover:shadow-md'
            }`}
          >
            <div className="flex justify-between items-start mb-3">
              <span className="text-4xl group-hover:scale-110 transition-transform duration-300">{ICONS.fresh}</span>
              {selectedPresetId === 'fresh' && <CheckCircle2 className="w-6 h-6 text-blue-500 fill-blue-50 dark:fill-blue-950" />}
            </div>
            <h4 className="text-lg font-bold mb-1">Blank Slate</h4>
            <p className="text-sm text-gray-500 dark:text-gray-400 leading-relaxed">
              Start with empty fields for total control.
            </p>
          </button>

          {/* Presets */}
          {CHARACTER_PRESETS.map((preset) => (
            <button
              key={preset.id}
              onClick={() => {
                setSelectedPresetId(preset.id);
                onApplyPreset(preset);
              }}
              className={`group relative p-5 rounded-2xl border-2 text-left transition-all duration-300 ${
                selectedPresetId === preset.id 
                  ? 'border-blue-500 bg-blue-50/50 dark:bg-blue-900/20 shadow-lg' 
                  : 'border-gray-200 dark:border-gray-800 hover:border-blue-300 dark:hover:border-blue-700 hover:shadow-md'
              }`}
            >
              <div className="flex justify-between items-start mb-3">
                <span className="text-4xl group-hover:scale-110 transition-transform duration-300">{preset.icon}</span>
                {selectedPresetId === preset.id && <CheckCircle2 className="w-6 h-6 text-blue-500 fill-blue-50 dark:fill-blue-950" />}
              </div>
              <h4 className="text-lg font-bold mb-1">{preset.name}</h4>
              <p className="text-sm text-gray-500 dark:text-gray-400 leading-relaxed">
                {preset.description}
              </p>
            </button>
          ))}
        </div>
      </section>

      {/* Core Identity Form */}
      <section className="bg-white dark:bg-gray-900 p-8 rounded-3xl border border-gray-100 dark:border-gray-800 shadow-xl space-y-8">
        <div className="flex items-center gap-3 pb-2 border-b border-gray-100 dark:border-gray-800">
           <Fingerprint className="w-5 h-5 text-blue-500" />
           <h3 className="text-sm font-black uppercase tracking-[0.2em] text-gray-400">Core Matrix</h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="space-y-2">
            <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500/70 ml-1">
              Character Name
            </label>
            <div className="relative group">
              <User className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400 group-focus-within:text-blue-500 transition-colors" />
              <Input
                value={data.name || ''}
                onChange={(e) => handleFieldChange('name', e.target.value)}
                placeholder="Name your creation..."
                className="pl-10 h-12 bg-gray-50 dark:bg-gray-800 border-transparent focus:border-blue-500 transition-all rounded-xl"
              />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500/70 ml-1">
              Archetype
            </label>
            <Select
              value={data.role?.archetype || ''}
              onValueChange={(val) => handleFieldChange('archetype', val)}
            >
              <SelectTrigger className="h-12 bg-gray-50 dark:bg-gray-800 border-transparent focus:border-blue-500 transition-all rounded-xl">
                <SelectValue placeholder="Select archetype" />
              </SelectTrigger>
              <SelectContent>
                {CHARACTER_ARCHETYPES.map((arch) => (
                  <SelectItem key={arch} value={arch}>{arch}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500/70 ml-1">
              Maturity Cycle
            </label>
            <div className="relative">
               <Clock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400 z-10" />
               <Select
                value={data.visual_identity?.age_range || ''}
                onValueChange={(val) => handleFieldChange('age_range', val)}
              >
                <SelectTrigger className="pl-10 h-12 bg-gray-50 dark:bg-gray-800 border-transparent focus:border-blue-500 transition-all rounded-xl">
                  <SelectValue placeholder="Select age range" />
                </SelectTrigger>
                <SelectContent>
                  {AGE_RANGES.map((range) => (
                    <SelectItem key={range} value={range}>{range}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500/70 ml-1">
              Identity Matrix (Gender)
            </label>
            <Select
              value={data.visual_identity?.gender || ''}
              onValueChange={(val) => handleFieldChange('gender', val)}
            >
              <SelectTrigger className="h-12 bg-gray-50 dark:bg-gray-800 border-transparent focus:border-blue-500 transition-all rounded-xl">
                <SelectValue placeholder="Select identity" />
              </SelectTrigger>
              <SelectContent>
                {GENDER_OPTIONS.map((opt) => (
                  <SelectItem key={opt} value={opt}>{opt}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>

        <div className="space-y-2 pt-4">
           <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500/70 ml-1">
              Narrative Purpose
           </label>
           <textarea
              value={data.role?.narrative_function || ''}
              onChange={(e) => handleFieldChange('narrative_function', e.target.value)}
              placeholder="What is this character's primary goal or purpose in the story?"
              className="w-full p-4 min-h-[100px] bg-gray-50 dark:bg-gray-800 border-2 border-transparent focus:border-blue-500 focus:bg-white dark:focus:bg-gray-950 rounded-2xl transition-all outline-none resize-none"
           />
        </div>
      </section>
    </div>
  );
}

/**
 * MarketingWizard - Assistant de creation de contenu marketing
 * 
 * Ce wizard guide l'utilisateur a travers le processus de creation
 * de contenus marketing (trailers, teasers, clips, thumbnails)
