export function MarketingWizard({ isOpen, onClose, onComplete, projectData }: MarketingWizardProps) {
  const [currentStep, setCurrentStep] = useState(0);
  const [data, setData] = useState<Partial<MarketingPlan>>({});
  const [error, setError] = useState<string | null>(null);

  const steps = [
    { title: 'Type de contenu', component: Step1ContentType },
    { title: 'Parametres', component: Step2Parameters },
    { title: 'Musique', component: Step3Music },
    { title: 'Generation', component: Step4Generate }
  ];

  const CurrentStepComponent = steps[currentStep].component;

  const handleNext = () => {
    // Validation basique
    if (currentStep === 0 && !data.type) {
      setError('Veuillez selectionner un type de contenu');
      return;
    }
    
    setError(null);
    
    if (currentStep < steps.length - 1) {
      setCurrentStep(currentStep + 1);
    } else {
      // Generer le plan final et fermer
      const platform = PLATFORMS.find(p => p.value === data.platform);
      const finalPlan: MarketingPlan = {
        type: data.type as MarketingContentType,
        duration: data.duration || 30,
        platform: data.platform as TargetPlatform,
        style: data.style as VisualStyle,
        musicMood: data.musicMood as MusicMood,
        sequences: data.sequences || [],
        exportSettings: data.exportSettings || {
          resolution: '1080p',
          format: 'mp4',
          quality: 'high',
          aspectRatio: platform?.aspectRatio || '16:9'
        },
        title: data.title,
        description: data.description
      };
      onComplete(finalPlan);
      onClose();
    }
  };

  const handleBack = () => {
    setError(null);
    if (currentStep > 0) {
      setCurrentStep(currentStep - 1);
    }
  };

  const handleClose = () => {
    setData({});
    setCurrentStep(0);
    setError(null);
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto" role="dialog" aria-modal="true">
      {/* Backdrop */}
      <div className="fixed inset-0 bg-black/50" onClick={handleClose} />

      {/* Modal */}
      <div className="flex min-h-full items-center justify-center p-4">
        <div className="relative w-full max-w-4xl bg-white dark:bg-gray-900 rounded-xl shadow-xl" onClick={e => e.stopPropagation()}>
          {/* Header */}
          <div className="px-6 py-4 border-b border-gray-200 dark:border-gray-700">
            <h2 className="text-xl font-semibold text-gray-900 dark:text-white">
              Marketing Wizard
            </h2>
            <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
              Creation de contenu promotionnel pour "{projectData.projectName}"
            </p>
          </div>

          {/* Progress Bar */}
          <div className="px-6 py-4 bg-gray-50 dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700">
            <WizardStepIndicator
              steps={steps.map((s, i) => ({ number: i + 1, title: s.title }))}
              currentStep={currentStep + 1}
            />
          </div>

          {/* Error Message */}
          {error && (
            <div className="mx-6 mt-4 p-4 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg">
              <div className="flex items-center justify-between">
                <p className="text-sm text-red-600 dark:text-red-400">{error}</p>
                <button
                  onClick={() => setError(null)}
                  className="text-red-400 hover:text-red-600 dark:hover:text-red-300"
                >
                  *
                </button>
              </div>
            </div>
          )}

          {/* Step Content */}
          <div className="p-6 min-h-[400px]">
            <CurrentStepComponent data={data} onUpdate={setData} projectData={projectData} />
          </div>

          {/* Navigation Buttons */}
          <div className="px-6 py-4 border-t border-gray-200 dark:border-gray-700 flex justify-between">
            <button
              onClick={handleBack}
              disabled={currentStep === 0}
              className="px-4 py-2 text-gray-700 dark:text-gray-300 bg-gray-100 dark:bg-gray-800 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-700 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Retour
            </button>
            <div className="flex gap-3">
              <button
                onClick={handleClose}
                className="px-4 py-2 text-gray-700 dark:text-gray-300 bg-gray-100 dark:bg-gray-800 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-700"
              >
                Annuler
              </button>
              <button
                onClick={handleNext}
                className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
              >
                {currentStep === steps.length - 1 ? 'Generer' : 'Suivant'}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default MarketingWizard;

/**
 * Object Wizard Component
 * 
 * Multi-step wizard for creating story objects (props, items, artifacts, etc.)
 * Follows the same pattern as CharacterWizard
 */

import React, { useCallback } from 'react';
import { WizardProvider, useWizard } from '@/contexts/WizardContext';
import { ProductionWizardContainer } from '../production-wizards/ProductionWizardContainer';
import type { WizardStep } from '../WizardStepIndicator';
import type { StoryObject } from '@/types/object';
import { createEmptyObject } from '@/types/object';
import { useServiceStatus } from '@/hooks/useServiceStatus';
import { Loader2, AlertCircle } from 'lucide-react';
import { Step1BasicInfo } from './Step1BasicInfo';
import { Step2Properties } from './Step2Properties';
import { Step3Abilities } from './Step3Abilities';
import { Step4Review } from './Step4Review';

export interface ObjectWizardProps {
  onComplete: (object: StoryObject) => void;
  onCancel: () => void;
  initialData?: Partial<StoryObject>;
}

const WIZARD_STEPS: WizardStep[] = [
  {
    number: 1,
    title: 'Basic Info',
    description: 'Name and type',
  },
  {
    number: 2,
    title: 'Properties',
    description: 'Physical details',
  },
  {
    number: 3,
    title: 'Abilities',
    description: 'Powers and effects',
  },
  {
    number: 4,
    title: 'Review',
    description: 'Finalize object',
  },
];

interface ObjectWizardContentProps {
  steps: WizardStep[];
  onCancel: () => void;
  renderStepContent: (step: number) => React.ReactNode;
  onComplete?: () => void;
}

function ObjectWizardContent({
  steps,
  onCancel,
  renderStepContent,
  onComplete,
}: ObjectWizardContentProps) {
  const { currentStep, nextStep, previousStep, goToStep, isDirty, submitWizard } = useWizard<StoryObject>();

  const handleComplete = async () => {
    await submitWizard();
    onComplete?.();
  };

  return (
    <ProductionWizardContainer
      title="Create Object"
      steps={steps}
      onCancel={onCancel}
      onComplete={handleComplete}
      allowJumpToStep={false}
      showAutoSaveIndicator={true}
      currentStep={currentStep}
      onNextStep={nextStep}
      onPreviousStep={previousStep}
      onGoToStep={goToStep}
      isDirty={isDirty}
    >
      {renderStepContent(currentStep)}
    </ProductionWizardContainer>
  );
}

export function ObjectWizard({
  onComplete,
  onCancel,
  initialData,
}: ObjectWizardProps) {
  // Check LLM service status
  const { ollama: llmStatus } = useServiceStatus();

  // Validation
  const validateStep = useCallback(
    async (step: number, data: Partial<StoryObject>): Promise<Record<string, string[]>> => {
      const errors: Record<string, string[]> = {};

      switch (step) {
        case 1: // Basic Info
          if (!data.name || data.name.trim() === '') {
            errors.name = ['Object name is required'];
          }
          if (!data.type) {
            errors.type = ['Object type is required'];
          }
          if (!data.description || data.description.trim() === '') {
            errors.description = ['Description is required'];
          }
          break;

        case 2: // Properties
          // Optional validation - properties can be empty
          break;

        case 3: // Abilities
          // Optional validation - abilities can be empty
          if (data.abilities && data.abilities.length > 0) {
            data.abilities.forEach((ability, index) => {
              if (!ability.name || ability.name.trim() === '') {
                errors[`ability-${index}-name`] = ['Ability name is required'];
              }
              if (!ability.description || ability.description.trim() === '') {
                errors[`ability-${index}-description`] = ['Ability description is required'];
              }
            });
          }
          break;

        case 4: // Review
          // Final validation
          if (!data.name || data.name.trim() === '') {
            errors.name = ['Object name is required'];
          }
          if (!data.type) {
            errors.type = ['Object type is required'];
          }
          break;
      }

      return errors;
    },
    []
  );

  // Submission
  const handleSubmit = useCallback(
    async (data: Partial<StoryObject>) => {
      try {
        // Generate UUID
        let objectId = data.id;
        if (!objectId) {
          if (typeof crypto !== 'undefined' && crypto.randomUUID) {
            objectId = crypto.randomUUID();
          } else {
            objectId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
              const r = (Math.random() * 16) | 0;
              const v = c === 'x' ? r : (r & 0x3) | 0x8;
              return v.toString(16);
            });
          }
        }

        const object: StoryObject = {
          id: objectId,
          name: data.name || '',
          type: data.type || 'prop',
          rarity: data.rarity || 'common',
          description: data.description || '',
          appearance: data.appearance || '',
          properties: data.properties || {},
          abilities: data.abilities || [],
          prompts: data.prompts || [],
          significance: data.significance || '',
          history: data.history,
          currentOwner: data.currentOwner,
          location: data.location,
          relatedCharacters: data.relatedCharacters || [],
          relatedLocations: data.relatedLocations || [],
          relatedObjects: data.relatedObjects || [],
          imageUrl: data.imageUrl,
          imagePrompt: data.imagePrompt,
          generatedBy: data.generatedBy || 'user',
          createdAt: data.createdAt || new Date(),
          updatedAt: new Date(),
          tags: data.tags || [],
        };

        console.log('[ObjectWizard] Object created:', object);
        onComplete(object);
      } catch (error) {
        console.error('Failed to create object:', error);
        alert('Failed to create object: ' + (error instanceof Error ? error.message : 'Unknown error'));
      }
    },
    [onComplete]
  );

  const handleWizardComplete = useCallback(() => {
    console.log('[ObjectWizard] Wizard completion confirmed');
  }, []);

  // Render step content
  const renderStepContent = (currentStep: number) => {
    switch (currentStep) {
      case 1:
        return <Step1BasicInfo />;
      case 2:
        return <Step2Properties />;
      case 3:
        return <Step3Abilities />;
      case 4:
        return <Step4Review />;
      default:
        return null;
    }
  };

  // Derived state
  const llmChecking = llmStatus === 'checking';
  const llmConfigured = llmStatus === 'connected';

  // Show loading state
  if (llmChecking) {
    return (
      <div className="flex flex-col items-center justify-center p-12 space-y-4 min-h-[400px]">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
        <p className="text-sm text-muted-foreground">Checking AI service status...</p>
      </div>
    );
  }

  // Show info if LLM not configured (info only, don't block)
  const showLLMWarning = !llmChecking && !llmConfigured;

  return (
    <WizardProvider<StoryObject>
      wizardType="object"
      totalSteps={4}
      initialData={initialData || createEmptyObject()}
      onSubmit={handleSubmit}
      onValidateStep={validateStep}
      autoSave={true}
      autoSaveDelay={2000}
    >
      <ObjectWizardContent
        steps={WIZARD_STEPS}
        onCancel={onCancel}
        onComplete={handleWizardComplete}
        renderStepContent={renderStepContent}
      />
    </WizardProvider>
  );
}

