/**
 * Test Suite: Production Wizard Components
 * Tests all UI components for Production Wizards
 */

import { describe, it, expect, vi } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import {
  ProductionWizardContainer,
  ProductionWizardNavigation,
  ProductionWizardStepIndicator,
  ProductionWizardErrorBoundary,
  ValidationDisplay,
  FieldValidation,
  LoadingState,
  InlineLoading,
  ButtonLoading,
} from '../index';
import { WizardStep } from '@/types';

// Mock console methods
const consoleErrorSpy = vi.spyOn(console, 'error').mockImplementation(() => {});

// ============================================================================
// ProductionWizardContainer Tests
// ============================================================================

describe('ProductionWizardContainer', () => {
  const mockSteps: WizardStep[] = [
    { number: 1, title: 'Step 1', description: 'First step' },
    { number: 2, title: 'Step 2', description: 'Second step' },
    { number: 3, title: 'Step 3', description: 'Final step' },
  ];

  it('should render with title and children', () => {
    render(
      <ProductionWizardContainer
        title="Test Wizard"
        steps={mockSteps}
        onCancel={vi.fn()}
      >
        <div>Wizard Content</div>
      </ProductionWizardContainer>
    );

    expect(screen.getByText('Test Wizard')).toBeInTheDocument();
    expect(screen.getByText('Wizard Content')).toBeInTheDocument();
  });

  it('should render step indicator', () => {
    render(
      <ProductionWizardContainer
        title="Test Wizard"
        steps={mockSteps}
        onCancel={vi.fn()}
      >
        <div>Content</div>
      </ProductionWizardContainer>
    );

    expect(screen.getByText('Step 1')).toBeInTheDocument();
    expect(screen.getByText('Step 2')).toBeInTheDocument();
    expect(screen.getByText('Step 3')).toBeInTheDocument();
  });

  it('should call onCancel when cancel button is clicked', async () => {
    const onCancel = vi.fn();
    const user = userEvent.setup();

    render(
      <ProductionWizardContainer
        title="Test Wizard"
        steps={mockSteps}
        onCancel={onCancel}
      >
        <div>Content</div>
      </ProductionWizardContainer>
    );

    await user.click(screen.getByRole('button', { name: /cancel/i }));
    expect(onCancel).toHaveBeenCalledTimes(1);
  });
});

// ============================================================================
// ProductionWizardNavigation Tests
// ============================================================================

describe('ProductionWizardNavigation', () => {
  it('should render navigation buttons', () => {
    const onPrevious = vi.fn();
    const onNext = vi.fn();
    const onCancel = vi.fn();

    render(
      <ProductionWizardNavigation
        currentStep={1}
        totalSteps={3}
        onPrevious={onPrevious}
        onNext={onNext}
        onCancel={onCancel}
      />
    );

    expect(screen.getByRole('button', { name: /cancel/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /back/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /continue/i })).toBeInTheDocument();
  });

  it('should show step progress', () => {
    render(
      <ProductionWizardNavigation
        currentStep={2}
        totalSteps={5}
        onPrevious={vi.fn()}
        onNext={vi.fn()}
        onCancel={vi.fn()}
      />
    );

    expect(screen.getByText('Step 3 of 5')).toBeInTheDocument();
  });

  it('should call onNext when continue button is clicked', async () => {
    const onNext = vi.fn();
    const user = userEvent.setup();

    render(
      <ProductionWizardNavigation
        currentStep={1}
        totalSteps={3}
        onPrevious={vi.fn()}
        onNext={onNext}
        onCancel={vi.fn()}
      />
    );

    await user.click(screen.getByRole('button', { name: /continue/i }));
    expect(onNext).toHaveBeenCalledTimes(1);
  });

  it('should disable previous button on first step', () => {
    render(
      <ProductionWizardNavigation
        currentStep={0}
        totalSteps={3}
        onPrevious={vi.fn()}
        onNext={vi.fn()}
        onCancel={vi.fn()}
      />
    );

    const previousButton = screen.getByRole('button', { name: /back/i });
    expect(previousButton).toBeDisabled();
  });

  it('should show complete button on last step', () => {
    render(
      <ProductionWizardNavigation
        currentStep={2}
        totalSteps={3}
        onPrevious={vi.fn()}
        onNext={vi.fn()}
        onCancel={vi.fn()}
      />
    );

    expect(screen.getByRole('button', { name: /complete/i })).toBeInTheDocument();
  });
});

// ============================================================================
// ProductionWizardStepIndicator Tests
// ============================================================================

describe('ProductionWizardStepIndicator', () => {
  const mockSteps: WizardStep[] = [
    { number: 1, title: 'Step 1' },
    { number: 2, title: 'Step 2' },
    { number: 3, title: 'Step 3' },
  ];

  it('should render step indicators', () => {
    render(
      <ProductionWizardStepIndicator
        steps={mockSteps}
        currentStep={1}
      />
    );

    expect(screen.getByText('Step 1')).toBeInTheDocument();
    expect(screen.getByText('Step 2')).toBeInTheDocument();
    expect(screen.getByText('Step 3')).toBeInTheDocument();
  });

  it('should highlight current step', () => {
    render(
      <ProductionWizardStepIndicator
        steps={mockSteps}
        currentStep={1}
      />
    );

    const currentStepIndicator = screen.getByRole('tab', { name: /step 2.*current/i });
    expect(currentStepIndicator).toBeInTheDocument();
  });

  it('should allow step clicking when allowJumpToStep is true', async () => {
    const onStepClick = vi.fn();
    const user = userEvent.setup();

    render(
      <ProductionWizardStepIndicator
        steps={mockSteps}
        currentStep={0}
        onStepClick={onStepClick}
        allowJumpToStep={true}
      />
    );

    const stepButton = screen.getByRole('button', { name: /step 1/i });
    await user.click(stepButton);

    expect(onStepClick).toHaveBeenCalledWith(0);
  });
});

// ============================================================================
// ValidationDisplay Tests
// ============================================================================

describe('ValidationDisplay', () => {
  it('should render validation errors', () => {
    const errors = {
      name: 'Name is required',
      email: 'Invalid email format',
    };

    render(<ValidationDisplay errors={errors} />);

    expect(screen.getByText('Name is required')).toBeInTheDocument();
    expect(screen.getByText('Invalid email format')).toBeInTheDocument();
  });

  it('should not render when no errors', () => {
    const { container } = render(<ValidationDisplay errors={{}} />);
    expect(container.firstChild).toBeNull();
  });
});

describe('FieldValidation', () => {
  it('should render error message', () => {
    render(<FieldValidation error="This field is required" />);

    expect(screen.getByText('This field is required')).toBeInTheDocument();
  });

  it('should render warning message', () => {
    render(<FieldValidation warning="This might cause issues" />);

    expect(screen.getByText('This might cause issues')).toBeInTheDocument();
  });

  it('should not render when no error or warning', () => {
    const { container } = render(<FieldValidation />);
    expect(container.firstChild).toBeNull();
  });
});

// ============================================================================
// LoadingState Tests
// ============================================================================

describe('LoadingState', () => {
  it('should render loading message', () => {
    render(<LoadingState message="Processing..." />);

    expect(screen.getByText('Processing...')).toBeInTheDocument();
  });

  it('should show progress bar when showProgress is true', () => {
    render(<LoadingState showProgress={true} progress={75} />);

    const progressBar = screen.getByRole('progressbar');
    expect(progressBar).toBeInTheDocument();
    expect(progressBar).toHaveAttribute('aria-valuenow', '75');
  });
});

describe('InlineLoading', () => {
  it('should render inline loading indicator', () => {
    render(<InlineLoading message="Saving..." />);

    expect(screen.getByText('Saving...')).toBeInTheDocument();
    expect(screen.getByRole('status')).toBeInTheDocument();
  });
});

describe('ButtonLoading', () => {
  it('should show loading state', () => {
    render(
      <ButtonLoading isLoading={true} loadingText="Saving...">
        <span>Save</span>
      </ButtonLoading>
    );

    expect(screen.getByText('Saving...')).toBeInTheDocument();
    expect(screen.queryByText('Save')).not.toBeInTheDocument();
  });

  it('should show children when not loading', () => {
    render(
      <ButtonLoading isLoading={false}>
        <span>Save</span>
      </ButtonLoading>
    );

    expect(screen.getByText('Save')).toBeInTheDocument();
  });
});

// ============================================================================
// ProductionWizardErrorBoundary Tests
// ============================================================================

describe('ProductionWizardErrorBoundary', () => {
  const ErrorComponent = () => {
    throw new Error('Test error');
  };

  it('should render error UI when error occurs', () => {
    render(
      <ProductionWizardErrorBoundary>
        <ErrorComponent />
      </ProductionWizardErrorBoundary>
    );

    expect(screen.getByText('Something went wrong')).toBeInTheDocument();
    expect(consoleErrorSpy).toHaveBeenCalled();
  });

  it('should render children when no error', () => {
    render(
      <ProductionWizardErrorBoundary>
        <div>No error here</div>
      </ProductionWizardErrorBoundary>
    );

    expect(screen.getByText('No error here')).toBeInTheDocument();
  });
});

import { useAppStore } from '@/stores/useAppStore';
import { useAudioRemixStore } from '@/stores/audioRemixStore';
import { AudioProductionWizard } from './AudioProductionWizard';
import { useToast } from '@/hooks/use-toast';

/**
 * Audio Production Wizard Modal
 * 
 * Wrapper component that connects the AudioProductionWizard to the app state
 * and handles completion/cancellation logic.
 */
export function AudioProductionWizardModal() {
  const { 
    showAudioProductionWizard,
    audioProductionWizardContext,
    closeAudioProductionWizard 
  } = useAppStore();
  
  const { 
    loadTrack, 
    analyzeStructure, 
    executeRemix, 
    export: exportAudio,
    reset,
    ...storeState
  } = useAudioRemixStore();
  
  const { toast } = useToast();

  const handleComplete = async () => {
    try {
      if (!storeState.remixResult && !storeState.exportedUrl) {
        // If no remix exists yet, execute the remix first
        await executeRemix();
      }
      
      const exportUrl = await exportAudio('mp3');
      
      toast({
        title: 'Audio Production Complete',
        description: `Audio has been exported successfully.`,
      });
      
      closeAudioProductionWizard();
      reset();
    } catch (error) {
      console.error('Failed to complete audio production:', error);
      toast({
        title: 'Error',
        description: error instanceof Error ? error.message : 'Failed to complete audio production',
        variant: 'destructive',
      });
    }
  };

  const handleClose = () => {
    closeAudioProductionWizard();
    reset();
  };

  return (
    <AudioProductionWizard
      isOpen={showAudioProductionWizard}
      onClose={handleClose}
      onComplete={handleComplete}
      initialAudioId={audioProductionWizardContext?.audioId}
      initialAudioUrl={audioProductionWizardContext?.audioUrl}
    />
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { ProductionWizardContainer } from '../production-wizards/ProductionWizardContainer';
import { WizardStep } from '@/types/wizard';
import { Image, List, ArrowRight, Music, Clock, Play, Save, Upload, Settings } from 'lucide-react';

// ============================================================================
// Wizard Steps Configuration
// ============================================================================

const COMIC_TO_SEQUENCE_STEPS: WizardStep[] = [
  { number: 1, title: 'Import Comic', description: 'Import comic pages or panels', icon: Upload },
  { number: 2, title: 'Panel Selection', description: 'Select and order panels', icon: List },
  { number: 3, title: 'Transitions', description: 'Choose transition effects between panels', icon: ArrowRight },
  { number: 4, title: 'Audio', description: 'Assign audio track to sequence', icon: Music },
  { number: 5, title: 'Timing', description: 'Adjust timing for each panel', icon: Clock },
  { number: 6, title: 'Generate', description: 'Generate video sequence', icon: Play },
];

// ============================================================================
// Local Storage Keys
// ============================================================================

const COMIC_TO_SEQUENCE_DRAFT_KEY = 'comic-to-sequence-draft';

// ============================================================================
// Types
// ============================================================================

interface ComicPanel {
  id: string;
  url: string;
  name: string;
  pageNumber: number;
  panelNumber: number;
  duration: number;
  transition: string;
}

interface ComicPage {
  id: string;
  url: string;
  name: string;
  pageNumber: number;
  panels: ComicPanel[];
}

interface ComicToSequenceDraft {
  currentStep: number;
  pages: ComicPage[];
  panels: ComicPanel[];
  audioTrack: string | null;
  timestamp: number;
}

interface ComicToSequenceResult {
  panels: ComicPanel[];
  audioTrack: string | null;
  totalDuration: number;
}

// ============================================================================
// Comic to Sequence Wizard Component
// ============================================================================

interface ComicToSequenceWizardProps {
  isOpen: boolean;
  onClose: () => void;
  onComplete: (result: ComicToSequenceResult) => void;
}

export function ComicToSequenceWizard({
  isOpen,
  onClose,
  onComplete,
}: ComicToSequenceWizardProps) {
  // ============================================================================
  // State Management
  // ============================================================================

  const [wizardState, setWizardState] = useState({
    currentStep: 0,
    pages: [] as ComicPage[],
    panels: [] as ComicPanel[],
    audioTrack: null as string | null,
    selectedPanelIds: [] as string[],
    defaultTransition: 'fade',
    defaultDuration: 3,
    validationErrors: {} as Record<string, string>,
    isDirty: false,
    lastSaved: 0,
  });

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // ============================================================================
  // Local Storage Helpers
  // ============================================================================

  const saveDraftToLocalStorage = useCallback((state: typeof wizardState) => {
    const draft: ComicToSequenceDraft = {
      currentStep: state.currentStep,
      pages: state.pages,
      panels: state.panels,
      audioTrack: state.audioTrack,
      timestamp: Date.now(),
    };
    localStorage.setItem(COMIC_TO_SEQUENCE_DRAFT_KEY, JSON.stringify(draft));
    setWizardState(prev => ({
      ...prev,
      lastSaved: Date.now(),
      isDirty: false,
    }));
  }, []);

  const loadDraftFromLocalStorage = useCallback((): ComicToSequenceDraft | null => {
    try {
      const saved = localStorage.getItem(COMIC_TO_SEQUENCE_DRAFT_KEY);
      if (saved) {
        return JSON.parse(saved);
      }
    } catch (e) {
      console.error('Failed to load draft:', e);
    }
    return null;
  }, []);

  const clearDraftFromLocalStorage = useCallback(() => {
    localStorage.removeItem(COMIC_TO_SEQUENCE_DRAFT_KEY);
  }, []);

  // ============================================================================
  // Initialization Effects
  // ============================================================================

  useEffect(() => {
    if (isOpen) {
      initializeWizard();
    }
  }, [isOpen]);

  const initializeWizard = async () => {
    try {
      setIsLoading(true);
      setError(null);

      let initialState = {
        currentStep: 0,
        pages: [] as ComicPage[],
        panels: [] as ComicPanel[],
        audioTrack: null as string | null,
        selectedPanelIds: [] as string[],
        defaultTransition: 'fade',
        defaultDuration: 3,
        validationErrors: {} as Record<string, string>,
        isDirty: false,
        lastSaved: 0,
      };

      const draft = loadDraftFromLocalStorage();
      if (draft) {
        initialState = {
          ...initialState,
          currentStep: draft.currentStep,
          pages: draft.pages,
          panels: draft.panels,
          audioTrack: draft.audioTrack,
        };
      }

      setWizardState(initialState);
    } catch (err) {
      console.error('Failed to initialize wizard:', err);
      setError(err instanceof Error ? err.message : 'Failed to initialize wizard');
    } finally {
      setIsLoading(false);
    }
  };

  // ============================================================================
  // Auto-save Effect
  // ============================================================================

  useEffect(() => {
    if (wizardState.isDirty) {
      const timer = setTimeout(() => {
        saveDraftToLocalStorage(wizardState);
      }, 30000);
      return () => clearTimeout(timer);
    }
  }, [wizardState.isDirty, wizardState, saveDraftToLocalStorage]);

  // ============================================================================
  // Navigation Handlers
  // ============================================================================

  const goToStep = useCallback((stepIndex: number) => {
    if (stepIndex >= 0 && stepIndex < COMIC_TO_SEQUENCE_STEPS.length) {
      setWizardState(prev => ({
        ...prev,
        currentStep: stepIndex,
      }));
    }
  }, []);

  const nextStep = useCallback(() => {
    if (wizardState.currentStep < COMIC_TO_SEQUENCE_STEPS.length - 1) {
      goToStep(wizardState.currentStep + 1);
    }
  }, [wizardState.currentStep, goToStep]);

  const previousStep = useCallback(() => {
    if (wizardState.currentStep > 0) {
      goToStep(wizardState.currentStep - 1);
    }
  }, [wizardState.currentStep, goToStep]);

  // ============================================================================
  // Panel Handlers
  // ============================================================================

  const togglePanelSelection = useCallback((panelId: string) => {
    setWizardState(prev => {
      const isSelected = prev.selectedPanelIds.includes(panelId);
      return {
        ...prev,
        selectedPanelIds: isSelected
          ? prev.selectedPanelIds.filter(id => id !== panelId)
          : [...prev.selectedPanelIds, panelId],
        isDirty: true,
      };
    });
  }, []);

  const updatePanelDuration = useCallback((panelId: string, duration: number) => {
    setWizardState(prev => ({
      ...prev,
      panels: prev.panels.map(p =>
        p.id === panelId ? { ...p, duration } : p
      ),
      isDirty: true,
    }));
  }, []);

  const updatePanelTransition = useCallback((panelId: string, transition: string) => {
    setWizardState(prev => ({
      ...prev,
      panels: prev.panels.map(p =>
        p.id === panelId ? { ...p, transition } : p
      ),
      isDirty: true,
    }));
  }, []);

  // ============================================================================
  // Completion Handler
  // ============================================================================

  const handleComplete = useCallback(() => {
    try {
      setIsLoading(true);
      
      const totalDuration = wizardState.panels.reduce((acc, panel) => {
        return acc + panel.duration;
      }, 0);

      const result: ComicToSequenceResult = {
        panels: wizardState.panels,
        audioTrack: wizardState.audioTrack,
        totalDuration,
      };

      clearDraftFromLocalStorage();
      onComplete(result);
    } catch (err) {
      console.error('Failed to complete sequence generation:', err);
      setError(err instanceof Error ? err.message : 'Failed to complete sequence generation');
    } finally {
      setIsLoading(false);
    }
  }, [wizardState, onComplete, clearDraftFromLocalStorage]);

  // ============================================================================
  // Cancel Handler with Confirmation
  // ============================================================================

  const handleCancel = useCallback(() => {
    if (wizardState.isDirty) {
      const confirmed = window.confirm(
        'You have unsaved changes. Are you sure you want to cancel?'
      );
      if (!confirmed) return;
    }

    clearDraftFromLocalStorage();
    onClose();
  }, [wizardState.isDirty, onClose, clearDraftFromLocalStorage]);

  // ============================================================================
  // Step Content Renderer
  // ============================================================================

  const renderStepContent = () => {
    const currentStepNumber = COMIC_TO_SEQUENCE_STEPS[wizardState.currentStep].number;

    switch (currentStepNumber) {
      case 1:
        return (
          <Step1ImportComic
            pages={wizardState.pages}
            onPagesLoad={(pages) => {
              setWizardState(prev => ({
                ...prev,
                pages,
                isDirty: true,
              }));
            }}
          />
        );

      case 2:
        return (
          <Step2PanelSelection
            pages={wizardState.pages}
            selectedPanelIds={wizardState.selectedPanelIds}
            onTogglePanel={togglePanelSelection}
            onSelectAll={() => {
              const allPanelIds = wizardState.pages.flatMap(p => p.panels).map(panel => panel.id);
              setWizardState(prev => ({
                ...prev,
                selectedPanelIds: allPanelIds,
                isDirty: true,
              }));
            }}
            onDeselectAll={() => {
              setWizardState(prev => ({
                ...prev,
                selectedPanelIds: [],
                isDirty: true,
              }));
            }}
          />
        );

      case 3:
        return (
          <Step3Transitions
            panels={wizardState.panels}
            defaultTransition={wizardState.defaultTransition}
            onDefaultTransitionChange={(transition) => {
              setWizardState(prev => ({
                ...prev,
                defaultTransition: transition,
                isDirty: true,
              }));
            }}
            onUpdatePanelTransition={updatePanelTransition}
          />
        );

      case 4:
        return (
          <Step4Audio
            audioTrack={wizardState.audioTrack}
            onAudioSelect={(url) => {
              setWizardState(prev => ({
                ...prev,
                audioTrack: url,
                isDirty: true,
              }));
            }}
          />
        );

      case 5:
        return (
          <Step5Timing
            panels={wizardState.panels}
            defaultDuration={wizardState.defaultDuration}
            onDefaultDurationChange={(duration) => {
              setWizardState(prev => ({
                ...prev,
                defaultDuration: duration,
                isDirty: true,
              }));
            }}
            onUpdatePanelDuration={updatePanelDuration}
          />
        );

      case 6:
        return (
          <Step6Generate
            panels={wizardState.panels}
            audioTrack={wizardState.audioTrack}
            totalDuration={wizardState.panels.reduce((acc, p) => acc + p.duration, 0)}
          />
        );

      default:
        return <div>Unknown step</div>;
    }
  };

  // ============================================================================
  // Render
  // ============================================================================

  return (
    <Dialog open={isOpen} onOpenChange={handleCancel}>
      <DialogContent className="max-w-4xl h-[85vh] overflow-hidden flex flex-col cyber-card border-primary/30 bg-card/95 backdrop-blur-sm">
        <DialogHeader className="border-b border-primary/30 bg-card/95 backdrop-blur-sm">
          <DialogTitle className="neon-text text-primary text-xl font-bold">
            Comic to Sequence Wizard
          </DialogTitle>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto min-h-0">
          <ProductionWizardContainer
            title="Comic to Sequence Wizard"
            steps={COMIC_TO_SEQUENCE_STEPS}
            currentStep={wizardState.currentStep}
            onNextStep={nextStep}
            onPreviousStep={previousStep}
            onGoToStep={goToStep}
            onCancel={handleCancel}
            onComplete={handleComplete}
            allowJumpToStep={false}
            showAutoSaveIndicator={true}
            canProceed={wizardState.panels.length > 0}
            isDirty={wizardState.isDirty}
            lastSaved={wizardState.lastSaved}
            className="h-full"
          >
            {isLoading ? (
              <div className="flex items-center justify-center h-64">
                <div className="text-center">
                  <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mx-auto mb-4"></div>
                  <p className="text-muted-foreground neon-text-blue">Loading...</p>
                </div>
              </div>
            ) : error ? (
              <div className="flex items-center justify-center h-64">
                <div className="text-center">
                  <p className="mb-4 text-destructive neon-text-pink">{error}</p>
                  <button
                    onClick={initializeWizard}
                    className="px-4 py-2 btn-neon rounded neon-border"
                  >
                    Retry
                  </button>
                </div>
              </div>
            ) : (
              renderStepContent()
            )}
          </ProductionWizardContainer>
        </div>
      </DialogContent>
    </Dialog>
  );
}

