        const panels: ComicPanel[] = [{
          id: `panel-${id}-0`,
          url,
          name: `${file.name} (Panel 1)`,
          pageNumber: index + 1,
          panelNumber: 1,
          duration: 3,
          transition: 'fade',
        }];

        return {
          id,
          url,
          name: file.name,
          pageNumber: index + 1,
          panels,
        };
      });

      onPagesLoad([...pages, ...newPages]);
    }
  };

  const handlePageReorder = (event: React.DragEvent, targetIndex: number) => {
    event.preventDefault();
    // Implementation for reordering pages
  };

  return (
