import React, { createContext, useContext, useState, useCallback, useEffect, ReactNode } from 'react';
import { z } from 'zod';

// ============================================================================
// Production Wizard Context Types
// ============================================================================

export interface ProductionWizardContextValue<T> {
  // State
  currentStep: number;
  totalSteps: number;
  formData: Partial<T>;
  validationErrors: Record<string, string>;
  isDirty: boolean;
  lastSaved: number;

  // Navigation
  goToStep: (step: number) => void;
  nextStep: () => void;
  previousStep: () => void;
  canProceed: boolean;

  // Data management
  updateFormData: (data: Partial<T>) => void;
  resetFormData: () => void;

  // Validation
  validateStep: (step: number) => Promise<boolean>;
  validateAll: () => Promise<boolean>;

  // Persistence
  saveDraft: () => Promise<void>;
  loadDraft: () => Promise<void>;
  clearDraft: () => Promise<void>;

  // Submission
  submit: () => Promise<void>;
}

interface ProductionWizardProviderProps<T> {
  children: ReactNode;
  wizardType: string; // 'sequence-plan' | 'shot'
  totalSteps: number;
  initialData?: Partial<T>;
  onSubmit: (data: T) => Promise<void>;
  onValidateStep?: (step: number, data: Partial<T>) => Promise<Record<string, string>>;
  schema?: z.ZodSchema<T>; // Zod schema for validation
  autoSaveInterval?: number; // milliseconds
}

// ============================================================================
// Context Creation
// ============================================================================

const ProductionWizardContext = createContext<ProductionWizardContextValue<any> | null>(null);

// ============================================================================
// Production Wizard Provider Component
// ============================================================================

export function ProductionWizardProvider<T>({
  children,
  wizardType,
  totalSteps,
  initialData = {},
  onSubmit,
  onValidateStep,
  schema,
  autoSaveInterval = 30000, // 30 seconds
}: ProductionWizardProviderProps<T>) {
  const [currentStep, setCurrentStep] = useState(0); // 0-based indexing
  const [formData, setFormData] = useState<Partial<T>>(initialData);
  const [validationErrors, setValidationErrors] = useState<Record<string, string>>({});
  const [isDirty, setIsDirty] = useState(false);
  const [lastSaved, setLastSaved] = useState(0);
  const [autoSaveTimeout, setAutoSaveTimeout] = useState<NodeJS.Timeout | null>(null);

  // ============================================================================
  // Navigation Methods
  // ============================================================================

  const goToStep = useCallback((step: number) => {
    if (step >= 0 && step < totalSteps) {
      setCurrentStep(step);
    }
  }, [totalSteps]);

  const nextStep = useCallback(() => {
    if (currentStep < totalSteps - 1) {
      setCurrentStep(currentStep + 1);
    }
  }, [currentStep, totalSteps]);

  const previousStep = useCallback(() => {
    if (currentStep > 0) {
      setCurrentStep(currentStep - 1);
    }
  }, [currentStep]);

  const canProceed = currentStep < totalSteps - 1 && Object.keys(validationErrors).length === 0;

  // ============================================================================
  // Form Data Management
  // ============================================================================

  const updateFormData = useCallback((data: Partial<T>) => {
    setFormData((prev) => ({ ...prev, ...data }));
    setIsDirty(true);

    // Clear validation errors for updated fields
    const updatedFields = Object.keys(data);
    setValidationErrors((prev) => {
      const newErrors = { ...prev };
      updatedFields.forEach((field) => {
        delete newErrors[field];
      });
      return newErrors;
    });
  }, []);

  const resetFormData = useCallback(() => {
    setFormData(initialData);
    setCurrentStep(0);
    setValidationErrors({});
    setIsDirty(false);
    setLastSaved(0);
  }, [initialData]);

  // ============================================================================
  // Validation System
  // ============================================================================

  const validateStep = useCallback(async (step: number): Promise<boolean> => {
    let errors: Record<string, string> = {};

    // Custom validation
    if (onValidateStep) {
      try {
        errors = await onValidateStep(step, formData);
      } catch (error) {
        console.error('Custom validation error:', error);
        errors = { general: 'Validation failed' };
      }
    }

    // Schema validation
    if (schema) {
      try {
        schema.parse(formData);
      } catch (error) {
        if (error instanceof z.ZodError) {
          error.issues.forEach((issue) => {
            const field = issue.path.join('.');
            errors[field] = issue.message;
          });
        }
      }
    }

    setValidationErrors(errors);
    return Object.keys(errors).length === 0;
  }, [formData, onValidateStep, schema]);

  const validateAll = useCallback(async (): Promise<boolean> => {
    let allValid = true;
    for (let step = 0; step < totalSteps; step++) {
      const stepValid = await validateStep(step);
      if (!stepValid) {
        allValid = false;
        setCurrentStep(step); // Go to first invalid step
        break;
      }
    }
    return allValid;
  }, [totalSteps, validateStep]);

  // ============================================================================
  // Persistence (Draft Storage)
  // ============================================================================

  const saveDraft = useCallback(async (): Promise<void> => {
    try {
      const draftData = {
        wizardType,
        timestamp: Date.now(),
        currentStep,
        formData,
        validationErrors,
      };

      // This would integrate with the draft storage service
      // For now, using localStorage as placeholder
      localStorage.setItem(`production-wizard-${wizardType}-draft`, JSON.stringify(draftData));

      setLastSaved(Date.now());
      setIsDirty(false);
    } catch (error) {
      console.error('Failed to save draft:', error);
      throw error;
    }
  }, [wizardType, currentStep, formData, validationErrors]);

  const loadDraft = useCallback(async (): Promise<void> => {
    try {
      const saved = localStorage.getItem(`production-wizard-${wizardType}-draft`);
      if (!saved) return;

      const draftData = JSON.parse(saved);

      // Check if draft is recent (within 24 hours)
      const isRecent = Date.now() - draftData.timestamp < 24 * 60 * 60 * 1000;
      if (!isRecent) {
        localStorage.removeItem(`production-wizard-${wizardType}-draft`);
        return;
      }

      setCurrentStep(draftData.currentStep);
      setFormData(draftData.formData);
      setValidationErrors(draftData.validationErrors || {});
      setLastSaved(draftData.timestamp);
      setIsDirty(true);
    } catch (error) {
      console.error('Failed to load draft:', error);
      // Clear corrupted draft
      localStorage.removeItem(`production-wizard-${wizardType}-draft`);
    }
  }, [wizardType]);

  const clearDraft = useCallback(async (): Promise<void> => {
    localStorage.removeItem(`production-wizard-${wizardType}-draft`);
    setLastSaved(0);
  }, [wizardType]);

  // ============================================================================
  // Auto-save Functionality
  // ============================================================================

  useEffect(() => {
    if (!isDirty) return;

    // Clear existing timeout
    if (autoSaveTimeout) {
      clearTimeout(autoSaveTimeout);
    }

    // Set new timeout
    const timeout = setTimeout(() => {
      saveDraft().catch(console.error);
    }, autoSaveInterval);

    setAutoSaveTimeout(timeout);

    return () => {
      if (timeout) clearTimeout(timeout);
    };
  }, [formData, isDirty, saveDraft, autoSaveInterval]);

  // Load draft on mount
  useEffect(() => {
    loadDraft().catch(console.error);
  }, [loadDraft]);

  // ============================================================================
  // Submission
  // ============================================================================

  const submit = useCallback(async (): Promise<void> => {
    // Validate all steps before submission
    const isValid = await validateAll();
    if (!isValid) {
      throw new Error('Validation failed');
    }

    try {
      await onSubmit(formData as T);

      // Clear draft on successful submission
      await clearDraft();

      // Reset form
      resetFormData();
    } catch (error) {
      console.error('Submission error:', error);
      throw error;
    }
  }, [formData, validateAll, onSubmit, clearDraft, resetFormData]);

  // ============================================================================
  // Context Value
  // ============================================================================

  const value: ProductionWizardContextValue<T> = {
    currentStep,
    totalSteps,
    formData,
    validationErrors,
    isDirty,
    lastSaved,
    goToStep,
    nextStep,
    previousStep,
    canProceed,
    updateFormData,
    resetFormData,
    validateStep,
    validateAll,
    saveDraft,
    loadDraft,
    clearDraft,
    submit,
  };

  return (
    <ProductionWizardContext.Provider value={value}>
      {children}
    </ProductionWizardContext.Provider>
  );
}

// ============================================================================
// Hook to use Production Wizard Context
// ============================================================================

export function useProductionWizard<T>(): ProductionWizardContextValue<T> {
  const context = useContext(ProductionWizardContext);

  if (!context) {
    throw new Error('useProductionWizard must be used within a ProductionWizardProvider');
  }

  return context as ProductionWizardContextValue<T>;
}

/**
 * ProjectContext - State management for ProjectDashboardNew
 * 
 * Provides centralized state management for project data, shots, dialogue phrases,
 * and generation status. Implements shot management, dialogue phrase management,
 * and validation functions.
 * 
 * Requirements: 1.2, 1.4, 9.3
 */

import React, { createContext, useContext, useState, useCallback, useEffect, useMemo, ReactNode } from 'react';
import type {
  Project as DashboardProject,
  Shot as DashboardShot,
  DialoguePhrase,
  GenerationStatus as DashboardGenerationStatus,
  GenerationResults,
} from '../types/projectDashboard';
import type { Project, Shot } from '../types';
import { memoizedValidatePrompt } from '../utils/performanceOptimizations';
import {
  projectPersistence,
  type SaveResult,
  type LoadResult,
} from '../services/persistence/projectPersistence';
import {
  generationStatePersistence,
} from '../services/persistence/generationStatePersistence';

// ============================================================================
// Context Value Interface
// ============================================================================

/**
 * ProjectContextValue defines all state and functions available through the context
 * Requirements: 1.2, 1.4, 9.3
 */
export interface ProjectContextValue {
  // State
  project: DashboardProject | null;
  selectedShot: DashboardShot | null;
  generationStatus: DashboardGenerationStatus;
  isGenerating: boolean;
  isLoading: boolean;
  isSaving: boolean;
  saveStatus: 'idle' | 'saving' | 'saved' | 'error';
  error: string | null;

  // Project Management
  loadProject: (projectId: string) => Promise<void>;
  saveProject: () => Promise<void>;

  // Shot Management (Task 3.2)
  updateShot: (shotId: string, updates: Partial<DashboardShot>) => void;
  deleteShot: (shotId: string, deletePhrases: boolean) => void;
  validateAllShots: () => { valid: boolean; invalidShots: DashboardShot[] };
  getPromptCompletionStatus: () => { complete: number; incomplete: number; total: number };

  // Dialogue Phrase Management (Task 3.3)
  addDialoguePhrase: (phrase: Omit<DialoguePhrase, 'id'>) => void;
  updateDialoguePhrase: (phraseId: string, updates: Partial<DialoguePhrase>) => void;
  deleteDialoguePhrase: (phraseId: string) => void;
  linkPhraseToShot: (phraseId: string, shotId: string) => void;

  // Generation Management
  generateSequence: () => Promise<GenerationResults | null>;
  cancelGeneration: () => void;

  // Selection Management
  selectShot: (shot: DashboardShot | null) => void;
}

// ============================================================================
// Context Creation
// ============================================================================

const ProjectContext = createContext<ProjectContextValue | null>(null);

// ============================================================================
// Provider Props
// ============================================================================

export interface ProjectProviderProps {
  children: ReactNode;
  projectId?: string;
  onProjectUpdate?: (project: Project) => void;
  onGenerationComplete?: (results: GenerationResults) => void;
}

// ============================================================================
// Provider Component
// ============================================================================

/**
 * ProjectProvider - Context provider for project state management
 * Requirements: 1.2, 1.4, 9.3
 */
export const ProjectProvider: React.FC<ProjectProviderProps> = ({
  children,
  projectId,
  onProjectUpdate,
  onGenerationComplete,
}) => {
  // ============================================================================
  // State
  // ============================================================================

  const [project, setProject] = useState<DashboardProject | null>(null);
  const [selectedShot, setSelectedShot] = useState<DashboardShot | null>(null);
  const [generationStatus, setGenerationStatus] = useState<DashboardGenerationStatus>({
    stage: 'idle',
    progress: 0,
  });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const [error, setError] = useState<string | null>(null);

  // ============================================================================
  // Project Management
  // ============================================================================

  /**
   * Load project data from storage or backend
   * Requirements: 9.3, 9.4
   */
  const loadProject = useCallback(async (id: string) => {
    try {
      setIsLoading(true);
      setError(null);

      // Load project from persistence layer
      const result: LoadResult = await projectPersistence.loadProject(id);

      if (result.success && result.project) {
        // If the project has a local path, initialize Rover backend for persistent memory
        if (result.project.path) {
          projectPersistence.useRover(result.project.path);
        }

        setProject(result.project as unknown as DashboardProject);
        setIsLoading(false);
      } else {
        // Project not found or failed to load - create new project
        const newProject: DashboardProject = {
          id,
          name: `Project ${id}`,
          schemaVersion: '1.0',
          sequences: [],
          shots: [],
          audioPhrases: [],
          generationHistory: [],
          capabilities: {
            gridGeneration: true,
            promotionEngine: true,
            qaEngine: true,
            autofixEngine: true,
            voiceGeneration: true,
          },
        };

        setProject(newProject);
        setIsLoading(false);

        // Save the new project
        await projectPersistence.saveProject(newProject as unknown as Project);
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to load project';
      setError(errorMessage);
      setIsLoading(false);

      // Log error for debugging in development only
      if (process.env.NODE_ENV === 'development') {
        console.error('Failed to load project:', err);
      }
    }
  }, []);

  /**
   * Save project data to storage
   * Requirements: 9.1, 9.2, 9.3, 9.5
   */
  const saveProject = useCallback(async () => {
    if (!project) return;

    try {
      setIsSaving(true);
      setSaveStatus('saving');
      setError(null);

      // Save project using persistence service
      const result: SaveResult = await projectPersistence.saveProject(project as unknown as Project);

      if (result.success) {
        setSaveStatus('saved');
        setIsSaving(false);
        onProjectUpdate?.(project);

        // Reset save status after 2 seconds
        setTimeout(() => {
          setSaveStatus('idle');
        }, 2000);

        // Log success for debugging in development only
        if (process.env.NODE_ENV === 'development') {
          ;
        }
      } else {
        // Save failed
        const errorMessage = result.error?.message || 'Failed to save project';
        setError(errorMessage);
        setSaveStatus('error');
        setIsSaving(false);

        // Log error for debugging in development only
        if (process.env.NODE_ENV === 'development') {
          console.error('Failed to save project:', result.error);
        }
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to save project';
      setError(errorMessage);
      setSaveStatus('error');
      setIsSaving(false);

      // Log error for debugging in development only
      if (process.env.NODE_ENV === 'development') {
        console.error('Failed to save project:', err);
      }
    }
  }, [project, onProjectUpdate]);

  // Auto-save on project changes with debouncing (Requirements: 9.1, 9.2)
  useEffect(() => {
    if (project) {
      // Schedule auto-save using persistence service
      projectPersistence.scheduleAutoSave(project as unknown as Project);
    }

    // Cleanup on unmount
    return () => {
      if (project) {
        projectPersistence.cancelAutoSave(project.id);
      }
    };
  }, [project]);

  // ============================================================================
  // Shot Management Functions (Task 3.2)
  // ============================================================================

  /**
   * Update shot properties including prompt
   * Requirements: 1.2, 1.4
   * Uses memoized validation for performance (Requirements: 10.1)
   */
  const updateShot = useCallback((shotId: string, updates: Partial<DashboardShot>) => {
    setProject(prev => {
      if (!prev) return prev;

      const updatedShots = prev.shots.map(shot => {
        if (shot.id === shotId) {
          const updatedShot = { ...shot, ...updates };

          // If prompt was updated, validate it using memoized validation
          if (updates.prompt !== undefined) {
            updatedShot.promptValidation = memoizedValidatePrompt(updates.prompt);
          }

          return updatedShot;
        }
        return shot;
      });

      return {
        ...prev,
        shots: updatedShots,
      };
    });
  }, []);

  /**
   * Delete shot with phrase handling
   * Requirements: 7.3
   * 
   * @param shotId - ID of the shot to delete
   * @param deletePhrases - If true, delete associated phrases; if false, unlink them
   */
  const deleteShot = useCallback((shotId: string, deletePhrases: boolean) => {
    setProject(prev => {
      if (!prev) return prev;

      // Verify shot exists
      const shotExists = prev.shots.some(shot => shot.id === shotId);
      if (!shotExists) {
        // Log warning for debugging in development only
        if (process.env.NODE_ENV === 'development') {
          console.warn(`Shot ${shotId} does not exist`);
        }
        return prev;
      }

      // Remove the shot
      const updatedShots = prev.shots.filter(shot => shot.id !== shotId);

      // Handle associated phrases
      let updatedPhrases: DialoguePhrase[];

      if (deletePhrases) {
        // Delete all phrases linked to this shot
        updatedPhrases = prev.audioPhrases.filter(phrase => phrase.shotId !== shotId);

        // Log for debugging in development only
        if (process.env.NODE_ENV === 'development') {
          ;
        }
      } else {
        // Unlink phrases by setting shotId to empty string
        // This ensures no orphaned references remain
        updatedPhrases = prev.audioPhrases.map(phrase =>
          phrase.shotId === shotId
            ? { ...phrase, shotId: '' }
            : phrase
        );

        // Log for debugging in development only
        if (process.env.NODE_ENV === 'development') {
          ;
        }
      }

      // Also remove shot from sequences
      const updatedSequences = prev.sequences.map(sequence => ({
        ...sequence,
        shotIds: sequence.shotIds.filter(id => id !== shotId),
      }));

      return {
        ...prev,
        shots: updatedShots,
        audioPhrases: updatedPhrases,
        sequences: updatedSequences,
      };
    });
  }, []);

  /**
   * Validate all shots have valid prompts
   * Requirements: 2.3, 6.1, 6.2
   * Uses memoized validation for performance (Requirements: 10.1)
   */
  const validateAllShots = useCallback((): { valid: boolean; invalidShots: DashboardShot[] } => {
    if (!project) {
      return { valid: true, invalidShots: [] };
    }

    const invalidShots = project.shots.filter(shot => {
      const validation = memoizedValidatePrompt(shot.prompt);
      return !validation.isValid;
    });

    return {
      valid: invalidShots.length === 0,
      invalidShots,
    };
  }, [project]);

  /**
   * Get prompt completion status counts
   * Requirements: 6.1, 6.2
   * Memoized for performance (Requirements: 10.1)
   */
  const getPromptCompletionStatus = useMemo((): (() => {
    complete: number;
    incomplete: number;
    total: number;
  }) => {
    return () => {
      if (!project) {
        return { complete: 0, incomplete: 0, total: 0 };
      }

      const total = project.shots.length;
      const complete = project.shots.filter(shot => {
        const validation = memoizedValidatePrompt(shot.prompt);
        return validation.isValid;
      }).length;
      const incomplete = total - complete;

      return { complete, incomplete, total };
    };
  }, [project]);

  // ============================================================================
  // Dialogue Phrase Management Functions (Task 3.3)
  // ============================================================================

  /**
   * Add new dialogue phrase
   * Requirements: 4.2
   */
  const addDialoguePhrase = useCallback((phrase: Omit<DialoguePhrase, 'id'>) => {
    setProject(prev => {
      if (!prev) return prev;

      // Generate unique ID
      const id = `phrase-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

      const newPhrase: DialoguePhrase = {
        ...phrase,
        id,
      };

      return {
        ...prev,
        audioPhrases: [...prev.audioPhrases, newPhrase],
      };
    });
  }, []);

  /**
   * Update existing dialogue phrase
   * Requirements: 4.3
   */
  const updateDialoguePhrase = useCallback((phraseId: string, updates: Partial<DialoguePhrase>) => {
    setProject(prev => {
      if (!prev) return prev;

      const updatedPhrases = prev.audioPhrases.map(phrase =>
        phrase.id === phraseId ? { ...phrase, ...updates } : phrase
      );

      return {
        ...prev,
        audioPhrases: updatedPhrases,
      };
    });
  }, []);

  /**
   * Delete dialogue phrase
   * Requirements: 4.4
   */
  const deleteDialoguePhrase = useCallback((phraseId: string) => {
    setProject(prev => {
      if (!prev) return prev;

      const filteredPhrases = prev.audioPhrases.filter(phrase => phrase.id !== phraseId);

      return {
        ...prev,
        audioPhrases: filteredPhrases,
      };
    });
  }, []);

  /**
   * Link dialogue phrase to shot
   * Requirements: 4.4
   */
  const linkPhraseToShot = useCallback((phraseId: string, shotId: string) => {
    setProject(prev => {
      if (!prev) return prev;

      // Verify shot exists
      const shotExists = prev.shots.some(shot => shot.id === shotId);
      if (!shotExists) {
        // Log warning for debugging in development only
        if (process.env.NODE_ENV === 'development') {
          console.warn(`Shot ${shotId} does not exist`);
        }
        return prev;
      }

      const updatedPhrases = prev.audioPhrases.map(phrase =>
        phrase.id === phraseId ? { ...phrase, shotId } : phrase
      );

      return {
        ...prev,
        audioPhrases: updatedPhrases,
      };
    });
  }, []);

  // ============================================================================
  // Generation Management
  // ============================================================================

  /**
   * Generate sequence through StoryCore pipeline
   * Requirements: 3.1, 3.2, 3.3, 3.4, 3.5
   */
  const generateSequence = useCallback(async (): Promise<GenerationResults | null> => {
    if (!project) return null;

    // Validate all shots have valid prompts
    const validation = validateAllShots();
    if (!validation.valid) {
      setError('Cannot generate: some shots have invalid prompts');
      return null;
    }

    try {
      setIsGenerating(true);
      setError(null);

      // Import sequence generation service dynamically
      const { sequenceGenerationService } = await import('../services/sequenceGenerationService');

      // Generate sequence with progress callbacks
      const results = await sequenceGenerationService.generateSequence(project, {
        onProgress: (status) => {
          setGenerationStatus(status);
        },
        onStageComplete: (stage, result) => {
          // Log stage completion for debugging in development only
          if (process.env.NODE_ENV === 'development') {
            ;
          }
        },
        onError: (error) => {
          // Log generation errors for debugging in development only
          if (process.env.NODE_ENV === 'development') {
            console.error(`Generation error at stage ${error.stage}:`, error.message);
          }
        },
        retryAttempts: 3,
        retryDelayMs: 2000,
      });

      if (results) {
        setGenerationStatus({
          stage: 'complete',
          progress: 100,
        });
        setIsGenerating(false);

        // Mark generation as complete in persistence
        if (project) {
          await generationStatePersistence.completeGeneration(project.id);
        }

        onGenerationComplete?.(results);
        return results;
      } else {
        // Generation was cancelled or failed
        setGenerationStatus({
          stage: 'idle',
          progress: 0,
        });
        setIsGenerating(false);

        // Mark generation as complete in persistence
        if (project) {
          await generationStatePersistence.completeGeneration(project.id);
        }

        return null;
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Generation failed';
      setError(errorMessage);
      setGenerationStatus({
        stage: 'error',
        progress: 0,
        error: errorMessage,
      });
      setIsGenerating(false);

      // Mark generation as complete in persistence
      if (project) {
        await generationStatePersistence.completeGeneration(project.id);
      }

      return null;
    }
  }, [project, validateAllShots, onGenerationComplete]);

  /**
   * Cancel ongoing generation
   * Requirements: 8.5
   */
  const cancelGeneration = useCallback(async () => {
    // Import sequence generation service dynamically
    const { sequenceGenerationService } = await import('../services/sequenceGenerationService');

    // Cancel the generation
    sequenceGenerationService.cancel();

    setIsGenerating(false);
    setGenerationStatus({
      stage: 'idle',
      progress: 0,
    });

    // Mark generation as complete in persistence
    if (project) {
      await generationStatePersistence.completeGeneration(project.id);
    }
  }, [project]);

  // ============================================================================
  // Selection Management
  // ============================================================================

  /**
   * Select a shot for editing
   * Requirements: 1.4
   */
  const selectShot = useCallback((shot: DashboardShot | null) => {
    setSelectedShot(shot);
  }, []);

  // ============================================================================
  // Load project on mount if projectId provided
  // ============================================================================

  useEffect(() => {
    if (projectId) {
      loadProject(projectId);
    }
  }, [projectId, loadProject]);

  // ============================================================================
  // Restore generation state on mount (Requirements: 10.5)
  // ============================================================================

  useEffect(() => {
    if (project) {
      // Check if there's an active generation for this project
      generationStatePersistence.loadGenerationState(project.id).then(state => {
        if (state && state.isActive) {
          // Restore generation status
          setGenerationStatus(state.status);
          setIsGenerating(true);

          // Log restoration for debugging in development only
          if (process.env.NODE_ENV === 'development') {
            ;
          }
        }
      }).catch(error => {
        // Log error for debugging in development only
        if (process.env.NODE_ENV === 'development') {
          console.error('Failed to restore generation state:', error);
        }
      });
    }
  }, [project?.id]);

  // ============================================================================
  // Save generation state periodically during generation (Requirements: 10.5)
  // ============================================================================

  useEffect(() => {
    if (project && isGenerating) {
      // Start periodic state updates
      generationStatePersistence.startPeriodicUpdates(
        project.id,
        () => generationStatus
      );

      // Cleanup on unmount or when generation stops
      return () => {
        generationStatePersistence.cancelPeriodicUpdates(project.id);
      };
    }
  }, [project?.id, isGenerating, generationStatus]);

  // ============================================================================
  // Context Value
  // ============================================================================

  const contextValue: ProjectContextValue = {
    // State
    project,
    selectedShot,
    generationStatus,
    isGenerating,
    isLoading,
    isSaving,
    saveStatus,
    error,

    // Project Management
    loadProject,
    saveProject,

    // Shot Management
    updateShot,
    deleteShot,
    validateAllShots,
    getPromptCompletionStatus,

    // Dialogue Phrase Management
    addDialoguePhrase,
    updateDialoguePhrase,
    deleteDialoguePhrase,
    linkPhraseToShot,

    // Generation Management
    generateSequence,
    cancelGeneration,

    // Selection Management
    selectShot,
  };

  return (
    <ProjectContext.Provider value={contextValue}>
      {children}
    </ProjectContext.Provider>
  );
};

