export const VideoEditorProvider: React.FC<VideoEditorProviderProps> = ({
  children,
  initialProject = null,
}) => {
  const [project, setProject] = useState<EditorProject | null>(initialProject);
  const [mediaLibrary, setMediaLibrary] = useState<MediaFile[]>([]);
