import { describe, it, expect, vi, beforeEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { usePanelVisibility } from '../usePanelVisibility';
import { useAppStore } from '@/stores/useAppStore';

// Mock the store
vi.mock('@/stores/useAppStore');

describe('usePanelVisibility', () => {
  const mockSetShowChat = vi.fn();
  const mockSetPanelSizes = vi.fn();

  beforeEach(() => {
    vi.clearAllMocks();
    (useAppStore as any).mockReturnValue({
      showChat: false,
      setShowChat: mockSetShowChat,
      panelSizes: {
        assetLibrary: 20,
        canvas: 50,
        propertiesOrChat: 30,
      },
      setPanelSizes: mockSetPanelSizes,
    });
  });

  describe('toggleChat', () => {
    it('toggles chat visibility', () => {
      const { result } = renderHook(() => usePanelVisibility());

      act(() => {
        result.current.toggleChat();
      });

      expect(mockSetShowChat).toHaveBeenCalledWith(true);
    });

    it('adjusts panel sizes when showing chat', () => {
      const { result } = renderHook(() => usePanelVisibility());

      act(() => {
        result.current.toggleChat();
      });

      expect(mockSetPanelSizes).toHaveBeenCalledWith({
        assetLibrary: 20,
        canvas: 40, // reduced from 50
        propertiesOrChat: 40, // increased from 30
      });
    });

    it('adjusts panel sizes when hiding chat', () => {
      (useAppStore as any).mockReturnValue({
        showChat: true,
        setShowChat: mockSetShowChat,
        panelSizes: {
          assetLibrary: 20,
          canvas: 40,
          propertiesOrChat: 40,
        },
        setPanelSizes: mockSetPanelSizes,
      });

      const { result } = renderHook(() => usePanelVisibility());

      act(() => {
        result.current.toggleChat();
      });

      expect(mockSetPanelSizes).toHaveBeenCalledWith({
        assetLibrary: 20,
        canvas: 50, // increased from 40
        propertiesOrChat: 30, // reduced from 40
      });
    });

    it('respects minimum canvas size', () => {
      (useAppStore as any).mockReturnValue({
        showChat: false,
        setShowChat: mockSetShowChat,
        panelSizes: {
          assetLibrary: 20,
          canvas: 35, // close to minimum
          propertiesOrChat: 45,
        },
        setPanelSizes: mockSetPanelSizes,
      });

      const { result } = renderHook(() => usePanelVisibility());

      act(() => {
        result.current.toggleChat();
      });

      const newSizes = mockSetPanelSizes.mock.calls[0][0];
      expect(newSizes.canvas).toBeGreaterThanOrEqual(30);
    });

    it('respects maximum propertiesOrChat size', () => {
      (useAppStore as any).mockReturnValue({
        showChat: false,
        setShowChat: mockSetShowChat,
        panelSizes: {
          assetLibrary: 20,
          canvas: 50,
          propertiesOrChat: 35, // close to maximum
        },
        setPanelSizes: mockSetPanelSizes,
      });

      const { result } = renderHook(() => usePanelVisibility());

      act(() => {
        result.current.toggleChat();
      });

      const newSizes = mockSetPanelSizes.mock.calls[0][0];
      expect(newSizes.propertiesOrChat).toBeLessThanOrEqual(40);
    });
  });

  describe('toggleAssetLibrary', () => {
    it('shows asset library', () => {
      const { result } = renderHook(() => usePanelVisibility());

      act(() => {
        result.current.toggleAssetLibrary(true);
      });

      expect(mockSetPanelSizes).toHaveBeenCalledWith({
        assetLibrary: 20,
        canvas: 40, // reduced from 50
        propertiesOrChat: 30,
      });
    });

    it('hides asset library', () => {
      const { result } = renderHook(() => usePanelVisibility());

      act(() => {
        result.current.toggleAssetLibrary(false);
      });

      expect(mockSetPanelSizes).toHaveBeenCalledWith({
        assetLibrary: 0,
        canvas: 60, // increased from 50
        propertiesOrChat: 30,
      });
    });

    it('respects minimum canvas size when showing', () => {
      (useAppStore as any).mockReturnValue({
        showChat: false,
        setShowChat: mockSetShowChat,
        panelSizes: {
          assetLibrary: 0,
          canvas: 45, // close to minimum
          propertiesOrChat: 55,
        },
        setPanelSizes: mockSetPanelSizes,
      });

      const { result } = renderHook(() => usePanelVisibility());

      act(() => {
        result.current.toggleAssetLibrary(true);
      });

      const newSizes = mockSetPanelSizes.mock.calls[0][0];
      expect(newSizes.canvas).toBeGreaterThanOrEqual(40);
    });

    it('respects maximum canvas size when hiding', () => {
      (useAppStore as any).mockReturnValue({
        showChat: false,
        setShowChat: mockSetShowChat,
        panelSizes: {
          assetLibrary: 20,
          canvas: 65, // close to maximum
          propertiesOrChat: 15,
        },
        setPanelSizes: mockSetPanelSizes,
      });

      const { result } = renderHook(() => usePanelVisibility());

      act(() => {
        result.current.toggleAssetLibrary(false);
      });

      const newSizes = mockSetPanelSizes.mock.calls[0][0];
      expect(newSizes.canvas).toBeLessThanOrEqual(70);
    });
  });

  describe('resetPanelSizes', () => {
    it('resets panel sizes to defaults', () => {
      (useAppStore as any).mockReturnValue({
        showChat: true,
        setShowChat: mockSetShowChat,
        panelSizes: {
          assetLibrary: 15,
          canvas: 45,
          propertiesOrChat: 40,
        },
        setPanelSizes: mockSetPanelSizes,
      });

      const { result } = renderHook(() => usePanelVisibility());

      act(() => {
        result.current.resetPanelSizes();
      });

      expect(mockSetPanelSizes).toHaveBeenCalledWith({
        assetLibrary: 20,
        canvas: 50,
        propertiesOrChat: 30,
      });
    });
  });

  describe('isAssetLibraryVisible', () => {
    it('returns true when asset library has size', () => {
      const { result } = renderHook(() => usePanelVisibility());

      expect(result.current.isAssetLibraryVisible).toBe(true);
    });

    it('returns false when asset library has zero size', () => {
      (useAppStore as any).mockReturnValue({
        showChat: false,
        setShowChat: mockSetShowChat,
        panelSizes: {
          assetLibrary: 0,
          canvas: 70,
          propertiesOrChat: 30,
        },
        setPanelSizes: mockSetPanelSizes,
      });

      const { result } = renderHook(() => usePanelVisibility());

      expect(result.current.isAssetLibraryVisible).toBe(false);
    });
  });

  describe('return values', () => {
    it('returns showChat from store', () => {
      const { result } = renderHook(() => usePanelVisibility());

      expect(result.current.showChat).toBe(false);
    });

    it('returns panelSizes from store', () => {
      const { result } = renderHook(() => usePanelVisibility());

      expect(result.current.panelSizes).toEqual({
        assetLibrary: 20,
        canvas: 50,
        propertiesOrChat: 30,
      });
    });
  });
});

/**
 * Tests for useProgressTracking Hook
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook, act, waitFor } from '@testing-library/react';
import { useProgressTracking } from '../useProgressTracking';
import { useAppStore } from '@/stores/useAppStore';
import type { GenerationTask } from '@/types';

// Mock the store
vi.mock('@/stores/useAppStore');

// Mock the service
vi.mock('@/services/progressTrackingService', () => ({
  createProgressTrackingService: vi.fn(() => ({
    startTracking: vi.fn(),
    stopTracking: vi.fn(),
    stopAllTracking: vi.fn(),
    isTracking: vi.fn(() => false),
    getTrackedTaskIds: vi.fn(() => []),
    fetchProgress: vi.fn(),
  })),
  ProgressTrackingService: vi.fn(),
  MockProgressTrackingService: vi.fn(),
}));

describe('useProgressTracking', () => {
  const mockTask: GenerationTask = {
    id: 'task-1',
    shotId: 'shot-1',
    type: 'grid',
    status: 'processing',
    priority: 1,
    createdAt: new Date(),
  };

  beforeEach(() => {
    vi.useFakeTimers();
    
    // Setup store mock
    (useAppStore as any).mockImplementation((selector: any) => {
      const state = {
        taskQueue: [mockTask],
        reorderTasks: vi.fn(),
      };
      return selector ? selector(state) : state;
    });

    (useAppStore as any).getState = vi.fn(() => ({
      taskQueue: [mockTask],
      reorderTasks: vi.fn(),
    }));
  });

  afterEach(() => {
    vi.restoreAllMocks();
    vi.useRealTimers();
  });

  describe('initialization', () => {
    it('should initialize with default options', () => {
      const { result } = renderHook(() => useProgressTracking());

      expect(result.current.progressUpdates).toBeInstanceOf(Map);
      expect(result.current.trackedTaskIds).toEqual([]);
    });

    it('should initialize with custom options', () => {
      const onProgress = vi.fn();
      const onComplete = vi.fn();
      const onError = vi.fn();

      const { result } = renderHook(() =>
        useProgressTracking({
          pollInterval: 5000,
          autoStart: false,
          useMock: true,
          onProgress,
          onComplete,
          onError,
        })
      );

      expect(result.current).toBeDefined();
    });
  });

  describe('startTracking', () => {
    it('should start tracking a task', () => {
      const { result } = renderHook(() => useProgressTracking({ autoStart: false }));

      act(() => {
        result.current.startTracking('task-1');
      });

      // Service should be called
      expect(result.current.isTracking).toBeDefined();
    });

    it('should call onProgress callback', async () => {
      const onProgress = vi.fn();
      const { result } = renderHook(() =>
        useProgressTracking({ autoStart: false, onProgress })
      );

      act(() => {
        result.current.startTracking('task-1');
      });

      // Callback should be set up
      expect(onProgress).toBeDefined();
    });

    it('should update progress state', async () => {
      const { result } = renderHook(() => useProgressTracking({ autoStart: false }));

      act(() => {
        result.current.startTracking('task-1');
      });

      await waitFor(() => {
        expect(result.current.progressUpdates).toBeInstanceOf(Map);
      });
    });
  });

  describe('stopTracking', () => {
    it('should stop tracking a task', () => {
      const { result } = renderHook(() => useProgressTracking({ autoStart: false }));

      act(() => {
        result.current.startTracking('task-1');
      });

      act(() => {
        result.current.stopTracking('task-1');
      });

      expect(result.current.stopTracking).toBeDefined();
    });
  });

  describe('startTrackingAll', () => {
    it('should start tracking all processing tasks', () => {
      const processingTask: GenerationTask = {
        ...mockTask,
        status: 'processing',
      };

      (useAppStore as any).mockImplementation((selector: any) => {
        const state = {
          taskQueue: [processingTask],
          reorderTasks: vi.fn(),
        };
        return selector ? selector(state) : state;
      });

      const { result } = renderHook(() => useProgressTracking({ autoStart: false }));

      act(() => {
        result.current.startTrackingAll();
      });

      expect(result.current.startTrackingAll).toBeDefined();
    });

    it('should not track non-processing tasks', () => {
      const pendingTask: GenerationTask = {
        ...mockTask,
        status: 'pending',
      };

      (useAppStore as any).mockImplementation((selector: any) => {
        const state = {
          taskQueue: [pendingTask],
          reorderTasks: vi.fn(),
        };
        return selector ? selector(state) : state;
      });

      const { result } = renderHook(() => useProgressTracking({ autoStart: false }));

      act(() => {
        result.current.startTrackingAll();
      });

      // Should not track pending tasks
      expect(result.current.trackedTaskIds).toEqual([]);
    });
  });

  describe('stopTrackingAll', () => {
    it('should stop tracking all tasks', () => {
      const { result } = renderHook(() => useProgressTracking({ autoStart: false }));

      act(() => {
        result.current.startTracking('task-1');
        result.current.startTracking('task-2');
      });

      act(() => {
        result.current.stopTrackingAll();
      });

      expect(result.current.stopTrackingAll).toBeDefined();
    });
  });

  describe('isTracking', () => {
    it('should return tracking status', () => {
      const { result } = renderHook(() => useProgressTracking({ autoStart: false }));

      expect(result.current.isTracking('task-1')).toBe(false);

      act(() => {
        result.current.startTracking('task-1');
      });

      // After starting, isTracking should be available
      expect(result.current.isTracking).toBeDefined();
    });
  });

  describe('getProgress', () => {
    it('should return progress for a task', () => {
      const { result } = renderHook(() => useProgressTracking({ autoStart: false }));

      const progress = result.current.getProgress('task-1');

      expect(progress).toBeUndefined(); // No progress yet
    });

    it('should return undefined for non-existent task', () => {
      const { result } = renderHook(() => useProgressTracking({ autoStart: false }));

      const progress = result.current.getProgress('non-existent');

      expect(progress).toBeUndefined();
    });
  });

  describe('autoStart', () => {
    it('should auto-start tracking processing tasks', async () => {
      const processingTask: GenerationTask = {
        ...mockTask,
        status: 'processing',
      };

      (useAppStore as any).mockImplementation((selector: any) => {
        const state = {
          taskQueue: [processingTask],
          reorderTasks: vi.fn(),
        };
        return selector ? selector(state) : state;
      });

      const { result } = renderHook(() => useProgressTracking({ autoStart: true }));

      await waitFor(() => {
        expect(result.current).toBeDefined();
      });
    });

    it('should not auto-start when disabled', () => {
      const processingTask: GenerationTask = {
        ...mockTask,
        status: 'processing',
      };

      (useAppStore as any).mockImplementation((selector: any) => {
        const state = {
          taskQueue: [processingTask],
          reorderTasks: vi.fn(),
        };
        return selector ? selector(state) : state;
      });

      const { result } = renderHook(() => useProgressTracking({ autoStart: false }));

      expect(result.current.trackedTaskIds).toEqual([]);
    });
  });

  describe('store integration', () => {
    it('should update store when task status changes', async () => {
      const reorderTasks = vi.fn();
      
      (useAppStore as any).getState = vi.fn(() => ({
        taskQueue: [mockTask],
        reorderTasks,
      }));

      const { result } = renderHook(() => useProgressTracking({ autoStart: false }));

      act(() => {
        result.current.startTracking('task-1');
      });

      // Store update should be available
      await waitFor(() => {
        expect(result.current).toBeDefined();
      });
    });
  });

  describe('callbacks', () => {
    it('should call onComplete when task completes', async () => {
      const onComplete = vi.fn();
      const { result } = renderHook(() =>
        useProgressTracking({ autoStart: false, onComplete })
      );

      act(() => {
        result.current.startTracking('task-1');
      });

      // Callback should be set up
      expect(onComplete).toBeDefined();
    });

    it('should call onError when task fails', async () => {
      const onError = vi.fn();
      const { result } = renderHook(() =>
        useProgressTracking({ autoStart: false, onError })
      );

      act(() => {
        result.current.startTracking('task-1');
      });

      // Callback should be set up
      expect(onError).toBeDefined();
    });

    it('should call onProgress on updates', async () => {
      const onProgress = vi.fn();
      const { result } = renderHook(() =>
        useProgressTracking({ autoStart: false, onProgress })
      );

      act(() => {
        result.current.startTracking('task-1');
      });

      // Callback should be set up
      expect(onProgress).toBeDefined();
    });
  });

  describe('cleanup', () => {
    it('should stop all tracking on unmount', () => {
      const { result, unmount } = renderHook(() => useProgressTracking({ autoStart: false }));

      act(() => {
        result.current.startTracking('task-1');
        result.current.startTracking('task-2');
      });

      unmount();

      // Cleanup should have been called
      expect(result.current).toBeDefined();
    });
  });

  describe('progressUpdates', () => {
    it('should maintain progress updates map', () => {
      const { result } = renderHook(() => useProgressTracking({ autoStart: false }));

      expect(result.current.progressUpdates).toBeInstanceOf(Map);
      expect(result.current.progressUpdates.size).toBe(0);
    });
  });

  describe('trackedTaskIds', () => {
    it('should maintain tracked task IDs list', () => {
      const { result } = renderHook(() => useProgressTracking({ autoStart: false }));

      expect(result.current.trackedTaskIds).toEqual([]);
    });
  });
});

/**
 * Tests for useProjectExport Hook
 */

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useProjectExport } from '../useProjectExport';
import { useAppStore } from '@/stores/useAppStore';
import type { Project, Shot, Asset } from '@/types';

// Mock the store
vi.mock('@/stores/useAppStore');

describe('useProjectExport', () => {
  let mockProject: Project;
  let mockShots: Shot[];
  let mockAssets: Asset[];
  let mockSetProject: ReturnType<typeof vi.fn>;
  let mockSetShots: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    mockShots = [
      {
        id: 'shot-1',
        title: 'Opening Scene',
        description: 'A beautiful sunrise',
        duration: 5,
        position: 0,
        audioTracks: [],
        effects: [],
        textLayers: [],
        animations: [],
      },
      {
        id: 'shot-2',
        title: 'Middle Scene',
        description: 'Action sequence',
        duration: 10,
        position: 1,
        audioTracks: [],
        effects: [],
        textLayers: [],
        animations: [],
      },
    ];

    mockAssets = [
      {
        id: 'asset-1',
        name: 'Background Music',
        type: 'audio',
        url: '/assets/music.mp3',
      },
    ];

    mockProject = {
      schema_version: '1.0',
      project_name: 'Test Project',
      shots: mockShots,
      assets: mockAssets,
      capabilities: {
        grid_generation: true,
        promotion_engine: true,
        qa_engine: true,
        autofix_engine: true,
      },
      generation_status: {
        grid: 'pending',
        promotion: 'pending',
      },
    };

    mockSetProject = vi.fn();
    mockSetShots = vi.fn();

    (useAppStore as unknown as ReturnType<typeof vi.fn>).mockReturnValue({
      project: mockProject,
      shots: mockShots,
      assets: mockAssets,
      setProject: mockSetProject,
      setShots: mockSetShots,
    });
  });

  describe('exportCurrentProject', () => {
    it('should export current project', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const exported = result.current.exportCurrentProject();
      
      expect(exported).not.toBeNull();
      expect(exported?.schema_version).toBe('1.0');
      expect(exported?.project_name).toBe('Test Project');
    });

    it('should return null when no project is loaded', () => {
      (useAppStore as unknown as ReturnType<typeof vi.fn>).mockReturnValue({
        project: null,
        shots: [],
        assets: [],
        setProject: mockSetProject,
        setShots: mockSetShots,
      });

      const { result } = renderHook(() => useProjectExport());
      
      const exported = result.current.exportCurrentProject();
      
      expect(exported).toBeNull();
    });

    it('should return null when validation fails', () => {
      (useAppStore as unknown as ReturnType<typeof vi.fn>).mockReturnValue({
        project: mockProject,
        shots: [], // Empty shots array will fail validation
        assets: mockAssets,
        setProject: mockSetProject,
        setShots: mockSetShots,
      });

      const { result } = renderHook(() => useProjectExport());
      
      const exported = result.current.exportCurrentProject();
      
      expect(exported).toBeNull();
    });

    it('should include all shots in export', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const exported = result.current.exportCurrentProject();
      
      expect(exported?.shots).toHaveLength(2);
      expect(exported?.shots[0].id).toBe('shot-1');
      expect(exported?.shots[1].id).toBe('shot-2');
    });

    it('should include all assets in export', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const exported = result.current.exportCurrentProject();
      
      expect(exported?.assets).toHaveLength(1);
      expect(exported?.assets[0].id).toBe('asset-1');
    });
  });

  describe('exportCurrentProjectToJSON', () => {
    it('should export project as JSON string', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const json = result.current.exportCurrentProjectToJSON();
      
      expect(typeof json).toBe('string');
      expect(() => JSON.parse(json!)).not.toThrow();
    });

    it('should export pretty-printed JSON by default', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const json = result.current.exportCurrentProjectToJSON();
      
      expect(json).toContain('\n');
      expect(json).toContain('  ');
    });

    it('should export minified JSON when pretty is false', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const json = result.current.exportCurrentProjectToJSON(false);
      
      expect(json).not.toContain('\n  ');
    });

    it('should return null when no project is loaded', () => {
      (useAppStore as unknown as ReturnType<typeof vi.fn>).mockReturnValue({
        project: null,
        shots: [],
        assets: [],
        setProject: mockSetProject,
        setShots: mockSetShots,
      });

      const { result } = renderHook(() => useProjectExport());
      
      const json = result.current.exportCurrentProjectToJSON();
      
      expect(json).toBeNull();
    });

    it('should return null when validation fails', () => {
      (useAppStore as unknown as ReturnType<typeof vi.fn>).mockReturnValue({
        project: mockProject,
        shots: [],
        assets: mockAssets,
        setProject: mockSetProject,
        setShots: mockSetShots,
      });

      const { result } = renderHook(() => useProjectExport());
      
      const json = result.current.exportCurrentProjectToJSON();
      
      expect(json).toBeNull();
    });
  });

  describe('downloadCurrentProject', () => {
    beforeEach(() => {
      // Mock DOM methods
      global.URL.createObjectURL = vi.fn(() => 'blob:mock-url');
      global.URL.revokeObjectURL = vi.fn();
      global.alert = vi.fn();
      
      const mockLink = {
        href: '',
        download: '',
        click: vi.fn(),
      };
      vi.spyOn(document, 'createElement').mockReturnValue(mockLink as any);
      vi.spyOn(document.body, 'appendChild').mockImplementation(() => mockLink as any);
      vi.spyOn(document.body, 'removeChild').mockImplementation(() => mockLink as any);
    });

    it('should trigger download', () => {
      const { result } = renderHook(() => useProjectExport());
      
      act(() => {
        result.current.downloadCurrentProject();
      });
      
      expect(document.createElement).toHaveBeenCalledWith('a');
    });

    it('should not download when no project is loaded', () => {
      (useAppStore as unknown as ReturnType<typeof vi.fn>).mockReturnValue({
        project: null,
        shots: [],
        assets: [],
        setProject: mockSetProject,
        setShots: mockSetShots,
      });

      const { result } = renderHook(() => useProjectExport());
      
      act(() => {
        result.current.downloadCurrentProject();
      });
      
      expect(document.createElement).not.toHaveBeenCalled();
    });

    it('should show alert when validation fails', () => {
      (useAppStore as unknown as ReturnType<typeof vi.fn>).mockReturnValue({
        project: mockProject,
        shots: [],
        assets: mockAssets,
        setProject: mockSetProject,
        setShots: mockSetShots,
      });

      const { result } = renderHook(() => useProjectExport());
      
      act(() => {
        result.current.downloadCurrentProject();
      });
      
      expect(global.alert).toHaveBeenCalled();
      expect(document.createElement).not.toHaveBeenCalled();
    });
  });

  describe('validateCurrentProject', () => {
    it('should validate valid project', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const validation = result.current.validateCurrentProject();
      
      expect(validation.valid).toBe(true);
      expect(validation.errors).toHaveLength(0);
    });

    it('should return invalid when no project is loaded', () => {
      (useAppStore as unknown as ReturnType<typeof vi.fn>).mockReturnValue({
        project: null,
        shots: [],
        assets: [],
        setProject: mockSetProject,
        setShots: mockSetShots,
      });

      const { result } = renderHook(() => useProjectExport());
      
      const validation = result.current.validateCurrentProject();
      
      expect(validation.valid).toBe(false);
      expect(validation.errors).toContain('No project loaded');
    });

    it('should return errors for invalid project', () => {
      (useAppStore as unknown as ReturnType<typeof vi.fn>).mockReturnValue({
        project: mockProject,
        shots: [],
        assets: mockAssets,
        setProject: mockSetProject,
        setShots: mockSetShots,
      });

      const { result } = renderHook(() => useProjectExport());
      
      const validation = result.current.validateCurrentProject();
      
      expect(validation.valid).toBe(false);
      expect(validation.errors.length).toBeGreaterThan(0);
    });
  });

  describe('importProject', () => {
    it('should import valid project JSON', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const validJSON = JSON.stringify(mockProject);
      const success = result.current.importProject(validJSON);
      
      expect(success).toBe(true);
      expect(mockSetProject).toHaveBeenCalledWith(mockProject);
      expect(mockSetShots).toHaveBeenCalledWith(mockProject.shots);
    });

    it('should return false for invalid JSON', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const success = result.current.importProject('invalid json');
      
      expect(success).toBe(false);
      expect(mockSetProject).not.toHaveBeenCalled();
      expect(mockSetShots).not.toHaveBeenCalled();
    });

    it('should return false for wrong schema version', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const invalidProject = { ...mockProject, schema_version: '2.0' };
      const success = result.current.importProject(JSON.stringify(invalidProject));
      
      expect(success).toBe(false);
      expect(mockSetProject).not.toHaveBeenCalled();
    });

    it('should update store with imported project', () => {
      const { result } = renderHook(() => useProjectExport());
      
      const validJSON = JSON.stringify(mockProject);
      result.current.importProject(validJSON);
      
      expect(mockSetProject).toHaveBeenCalledTimes(1);
      expect(mockSetShots).toHaveBeenCalledTimes(1);
    });
  });

  describe('importProjectFromFile', () => {
    it('should import project from file', async () => {
      const { result } = renderHook(() => useProjectExport());
      
      const validJSON = JSON.stringify(mockProject);
      const file = new File([validJSON], 'project.json', { type: 'application/json' });
      
      const success = await result.current.importProjectFromFile(file);
      
      expect(success).toBe(true);
      expect(mockSetProject).toHaveBeenCalled();
    });

    it('should return false for invalid file content', async () => {
      const { result } = renderHook(() => useProjectExport());
      
      const file = new File(['invalid json'], 'project.json', { type: 'application/json' });
      
      const success = await result.current.importProjectFromFile(file);
      
      expect(success).toBe(false);
      expect(mockSetProject).not.toHaveBeenCalled();
    });

    it('should handle file read errors', async () => {
      const { result } = renderHook(() => useProjectExport());
      
      const mockFile = {
        text: vi.fn().mockRejectedValue(new Error('Read error')),
      } as unknown as File;
      
      const success = await result.current.importProjectFromFile(mockFile);
      
      expect(success).toBe(false);
    });
  });

  describe('hook stability', () => {
    it('should maintain stable function references', () => {
      const { result, rerender } = renderHook(() => useProjectExport());
      
      const firstRender = {
        exportCurrentProject: result.current.exportCurrentProject,
        exportCurrentProjectToJSON: result.current.exportCurrentProjectToJSON,
        downloadCurrentProject: result.current.downloadCurrentProject,
        validateCurrentProject: result.current.validateCurrentProject,
        importProject: result.current.importProject,
        importProjectFromFile: result.current.importProjectFromFile,
      };
      
      rerender();
      
      expect(result.current.exportCurrentProject).toBe(firstRender.exportCurrentProject);
      expect(result.current.exportCurrentProjectToJSON).toBe(firstRender.exportCurrentProjectToJSON);
      expect(result.current.downloadCurrentProject).toBe(firstRender.downloadCurrentProject);
      expect(result.current.validateCurrentProject).toBe(firstRender.validateCurrentProject);
      expect(result.current.importProject).toBe(firstRender.importProject);
      expect(result.current.importProjectFromFile).toBe(firstRender.importProjectFromFile);
    });
  });
});

/**
 * useResultDisplay Hook Tests
 */

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { renderHook, waitFor, act } from '@testing-library/react';
import { useResultDisplay } from '../useResultDisplay';
import { useAppStore } from '@/stores/useAppStore';
import type { GeneratedResult, GeneratedAsset } from '@/services/resultService';

// Mock the store
vi.mock('@/stores/useAppStore');

// Mock the service
vi.mock('@/services/resultService', () => ({
  createResultService: vi.fn(() => ({
    fetchResult: vi.fn(),
    fetchMultipleResults: vi.fn(),
    fetchProjectResults: vi.fn(),
    downloadAsset: vi.fn(),
    downloadAllAssets: vi.fn(),
    deleteResult: vi.fn(),
    getPreviewUrl: vi.fn((asset: GeneratedAsset) => asset.url),
  })),
  ResultService: vi.fn(),
  MockResultService: vi.fn(),
}));

describe('useResultDisplay', () => {
  const mockResult: GeneratedResult = {
    taskId: 'task-1',
    shotId: 'shot-1',
    type: 'grid',
    status: 'success',
    assets: [
      {
        id: 'asset-1',
        type: 'image',
        name: 'test.png',
        url: 'http://localhost:3000/assets/test.png',
      },
    ],
    generatedAt: new Date(),
  };

  beforeEach(() => {
    vi.clearAllMocks();

    // Mock store state
    (useAppStore as any).mockImplementation((selector: any) => {
      const state = {
        taskQueue: [],
        project: { project_name: 'test-project' },
      };
      return selector(state);
    });
  });

  describe('initialization', () => {
    it('should initialize with empty results', () => {
      const { result } = renderHook(() => useResultDisplay({ autoFetch: false }));

      expect(result.current.results.size).toBe(0);
      expect(result.current.isLoading).toBe(false);
      expect(result.current.error).toBeNull();
    });

    it('should create service with useMock option', () => {
      const { createResultService } = require('@/services/resultService');
      
      renderHook(() => useResultDisplay({ useMock: true, autoFetch: false }));

      expect(createResultService).toHaveBeenCalledWith(true);
    });
  });

  describe('fetchResult', () => {
    it('should fetch result for a task', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      mockService.fetchResult.mockResolvedValueOnce(mockResult);

      const { result } = renderHook(() => useResultDisplay({ autoFetch: false }));

      let fetchedResult: GeneratedResult | null = null;
      await act(async () => {
        fetchedResult = await result.current.fetchResult('task-1');
      });

      expect(fetchedResult).toEqual(mockResult);
      expect(result.current.results.get('task-1')).toEqual(mockResult);
    });

    it('should set loading state during fetch', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      
      let resolvePromise: (value: GeneratedResult) => void;
      const promise = new Promise<GeneratedResult>((resolve) => {
        resolvePromise = resolve;
      });
      mockService.fetchResult.mockReturnValueOnce(promise);

      const { result } = renderHook(() => useResultDisplay({ autoFetch: false }));

      act(() => {
        result.current.fetchResult('task-1');
      });

      await waitFor(() => {
        expect(result.current.isLoading).toBe(true);
      });

      await act(async () => {
        resolvePromise!(mockResult);
        await promise;
      });

      expect(result.current.isLoading).toBe(false);
    });

    it('should handle fetch error', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      mockService.fetchResult.mockRejectedValueOnce(new Error('Network error'));

      const { result } = renderHook(() => useResultDisplay({ autoFetch: false }));

      await act(async () => {
        await result.current.fetchResult('task-1');
      });

      expect(result.current.error).toBe('Network error');
    });

    it('should call onResultFetched callback', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      mockService.fetchResult.mockResolvedValueOnce(mockResult);

      const onResultFetched = vi.fn();
      const { result } = renderHook(() =>
        useResultDisplay({ autoFetch: false, onResultFetched })
      );

      await act(async () => {
        await result.current.fetchResult('task-1');
      });

      expect(onResultFetched).toHaveBeenCalledWith(mockResult);
    });
  });

  describe('fetchMultipleResults', () => {
    it('should fetch multiple results', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      
      const results = [
        { ...mockResult, taskId: 'task-1' },
        { ...mockResult, taskId: 'task-2' },
      ];
      mockService.fetchMultipleResults.mockResolvedValueOnce(results);

      const { result } = renderHook(() => useResultDisplay({ autoFetch: false }));

      let fetchedResults: GeneratedResult[] = [];
      await act(async () => {
        fetchedResults = await result.current.fetchMultipleResults(['task-1', 'task-2']);
      });

      expect(fetchedResults).toHaveLength(2);
      expect(result.current.results.size).toBe(2);
    });
  });

  describe('fetchProjectResults', () => {
    it('should fetch all results for project', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      
      const results = [mockResult];
      mockService.fetchProjectResults.mockResolvedValueOnce(results);

      const { result } = renderHook(() => useResultDisplay({ autoFetch: false }));

      let fetchedResults: GeneratedResult[] = [];
      await act(async () => {
        fetchedResults = await result.current.fetchProjectResults();
      });

      expect(fetchedResults).toHaveLength(1);
      expect(mockService.fetchProjectResults).toHaveBeenCalledWith(
        'test-project',
        expect.any(Object)
      );
    });
  });

  describe('downloadAsset', () => {
    it('should download an asset', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      mockService.downloadAsset.mockResolvedValueOnce(undefined);

      const { result } = renderHook(() => useResultDisplay({ autoFetch: false }));

      const asset = mockResult.assets[0];
      await act(async () => {
        await result.current.downloadAsset(asset);
      });

      expect(mockService.downloadAsset).toHaveBeenCalledWith(asset, undefined);
    });

    it('should call onDownloadComplete callback', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      mockService.downloadAsset.mockResolvedValueOnce(undefined);

      const onDownloadComplete = vi.fn();
      const { result } = renderHook(() =>
        useResultDisplay({ autoFetch: false, onDownloadComplete })
      );

      const asset = mockResult.assets[0];
      await act(async () => {
        await result.current.downloadAsset(asset);
      });

      expect(onDownloadComplete).toHaveBeenCalledWith(asset);
    });
  });

  describe('downloadAllAssets', () => {
    it('should download all assets from result', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      mockService.downloadAllAssets.mockResolvedValueOnce(undefined);

      const { result } = renderHook(() => useResultDisplay({ autoFetch: false }));

      await act(async () => {
        await result.current.downloadAllAssets(mockResult);
      });

      expect(mockService.downloadAllAssets).toHaveBeenCalledWith(mockResult);
    });
  });

  describe('deleteResult', () => {
    it('should delete a result', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      mockService.fetchResult.mockResolvedValueOnce(mockResult);
      mockService.deleteResult.mockResolvedValueOnce(undefined);

      const { result } = renderHook(() => useResultDisplay({ autoFetch: false }));

      // First fetch to populate cache
      await act(async () => {
        await result.current.fetchResult('task-1');
      });

      expect(result.current.results.has('task-1')).toBe(true);

      // Then delete
      await act(async () => {
        await result.current.deleteResult('task-1');
      });

      expect(result.current.results.has('task-1')).toBe(false);
    });
  });

  describe('getResult', () => {
    it('should get result from cache', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      mockService.fetchResult.mockResolvedValueOnce(mockResult);

      const { result } = renderHook(() => useResultDisplay({ autoFetch: false }));

      await act(async () => {
        await result.current.fetchResult('task-1');
      });

      const cachedResult = result.current.getResult('task-1');
      expect(cachedResult).toEqual(mockResult);
    });

    it('should return undefined for non-existent result', () => {
      const { result } = renderHook(() => useResultDisplay({ autoFetch: false }));

      const cachedResult = result.current.getResult('non-existent');
      expect(cachedResult).toBeUndefined();
    });
  });

  describe('clearResults', () => {
    it('should clear all cached results', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      mockService.fetchResult.mockResolvedValueOnce(mockResult);

      const { result } = renderHook(() => useResultDisplay({ autoFetch: false }));

      await act(async () => {
        await result.current.fetchResult('task-1');
      });

      expect(result.current.results.size).toBe(1);

      act(() => {
        result.current.clearResults();
      });

      expect(result.current.results.size).toBe(0);
    });
  });

  describe('autoFetch', () => {
    it('should auto-fetch results for completed tasks', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      mockService.fetchMultipleResults.mockResolvedValueOnce([mockResult]);

      // Mock store with completed tasks
      (useAppStore as any).mockImplementation((selector: any) => {
        const state = {
          taskQueue: [
            { id: 'task-1', status: 'completed' },
            { id: 'task-2', status: 'pending' },
          ],
          project: { project_name: 'test-project' },
        };
        return selector(state);
      });

      renderHook(() => useResultDisplay({ autoFetch: true }));

      await waitFor(() => {
        expect(mockService.fetchMultipleResults).toHaveBeenCalledWith(['task-1']);
      });
    });

    it('should not auto-fetch when disabled', () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();

      (useAppStore as any).mockImplementation((selector: any) => {
        const state = {
          taskQueue: [{ id: 'task-1', status: 'completed' }],
          project: { project_name: 'test-project' },
        };
        return selector(state);
      });

      renderHook(() => useResultDisplay({ autoFetch: false }));

      expect(mockService.fetchMultipleResults).not.toHaveBeenCalled();
    });
  });

  describe('getPreviewUrl', () => {
    it('should get preview URL for asset', () => {
      const { result } = renderHook(() => useResultDisplay({ autoFetch: false }));

      const asset = mockResult.assets[0];
      const previewUrl = result.current.getPreviewUrl(asset);

      expect(previewUrl).toBe(asset.url);
    });
  });

  describe('error handling', () => {
    it('should call onError callback on fetch error', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      mockService.fetchResult.mockRejectedValueOnce(new Error('Network error'));

      const onError = vi.fn();
      const { result } = renderHook(() =>
        useResultDisplay({ autoFetch: false, onError })
      );

      await act(async () => {
        await result.current.fetchResult('task-1');
      });

      expect(onError).toHaveBeenCalledWith('Network error');
    });

    it('should call onError callback on download error', async () => {
      const { createResultService } = require('@/services/resultService');
      const mockService = createResultService();
      mockService.downloadAsset.mockRejectedValueOnce(new Error('Download failed'));

      const onError = vi.fn();
      const { result } = renderHook(() =>
        useResultDisplay({ autoFetch: false, onError })
      );

      const asset = mockResult.assets[0];
      await act(async () => {
        await result.current.downloadAsset(asset);
      });

      expect(onError).toHaveBeenCalledWith('Download failed');
    });
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useVoiceOverGenerator } from '../useVoiceOverGenerator';
import { ttsService } from '../../services/ttsService';
import { useStore } from '../../store';
import type { VoiceOver } from '../../types';

// Mock the TTS service
vi.mock('../../services/ttsService', () => ({
  ttsService: {
    generateVoiceOver: vi.fn(),
  },
}));

describe('useVoiceOverGenerator', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    useStore.setState({
      shots: [
        {
          id: 'shot-1',
          title: 'Test Shot',
          description: 'Test',
          duration: 10,
          position: 0,
          audioTracks: [],
          effects: [],
          textLayers: [],
          animations: [],
        },
      ],
    });
  });

  it('initializes with correct default state', () => {
    const { result } = renderHook(() => useVoiceOverGenerator());

    expect(result.current.isGenerating).toBe(false);
    expect(result.current.error).toBe(null);
    expect(typeof result.current.generateVoiceOver).toBe('function');
    expect(typeof result.current.clearError).toBe('function');
  });

  it('generates voiceover and adds audio track', async () => {
    const mockAudioUrl = 'blob:mock-audio-url';
    vi.mocked(ttsService.generateVoiceOver).mockResolvedValue(mockAudioUrl);

    const { result } = renderHook(() => useVoiceOverGenerator());

    const voiceOver: VoiceOver = {
      id: 'vo-1',
      text: 'Test voiceover text',
      voice: 'female',
      language: 'en-US',
      speed: 1.0,
      pitch: 0,
      emotion: 'neutral',
    };

    await act(async () => {
      await result.current.generateVoiceOver(voiceOver, 'shot-1');
    });

    // Check that TTS service was called
    expect(ttsService.generateVoiceOver).toHaveBeenCalledWith(voiceOver);

    // Check that audio track was added to store
    const shot = useStore.getState().shots.find((s) => s.id === 'shot-1');
    expect(shot?.audioTracks).toHaveLength(1);
    expect(shot?.audioTracks[0].type).toBe('voiceover');
    expect(shot?.audioTracks[0].url).toBe(mockAudioUrl);
  });

  it('sets isGenerating to true during generation', async () => {
    let resolveGeneration: (value: string) => void;
    const generationPromise = new Promise<string>((resolve) => {
      resolveGeneration = resolve;
    });
    vi.mocked(ttsService.generateVoiceOver).mockReturnValue(generationPromise);

    const { result } = renderHook(() => useVoiceOverGenerator());

    const voiceOver: VoiceOver = {
      id: 'vo-2',
      text: 'Test',
      voice: 'male',
      language: 'en-US',
      speed: 1.0,
      pitch: 0,
    };

    act(() => {
      result.current.generateVoiceOver(voiceOver, 'shot-1');
    });

    // Should be generating
    expect(result.current.isGenerating).toBe(true);

    // Resolve the generation
    await act(async () => {
      resolveGeneration!('blob:test-url');
      await generationPromise;
    });

    // Should no longer be generating
    expect(result.current.isGenerating).toBe(false);
  });

  it('handles generation errors', async () => {
    const errorMessage = 'TTS API error';
    vi.mocked(ttsService.generateVoiceOver).mockRejectedValue(new Error(errorMessage));

    const { result } = renderHook(() => useVoiceOverGenerator());

    const voiceOver: VoiceOver = {
      id: 'vo-3',
      text: 'Test',
      voice: 'female',
      language: 'en-US',
      speed: 1.0,
      pitch: 0,
    };

    await act(async () => {
      try {
        await result.current.generateVoiceOver(voiceOver, 'shot-1');
      } catch (error) {
        // Expected to throw
      }
    });

    expect(result.current.error).toBe(errorMessage);
    expect(result.current.isGenerating).toBe(false);
  });

  it('clears error when clearError is called', async () => {
    const errorMessage = 'Test error';
    vi.mocked(ttsService.generateVoiceOver).mockRejectedValue(new Error(errorMessage));

    const { result } = renderHook(() => useVoiceOverGenerator());

    const voiceOver: VoiceOver = {
      id: 'vo-4',
      text: 'Test',
      voice: 'neutral',
      language: 'en-US',
      speed: 1.0,
      pitch: 0,
    };

    // Generate error
    await act(async () => {
      try {
        await result.current.generateVoiceOver(voiceOver, 'shot-1');
      } catch (error) {
        // Expected
      }
    });

    expect(result.current.error).toBe(errorMessage);

    // Clear error
    act(() => {
      result.current.clearError();
    });

    expect(result.current.error).toBe(null);
  });

  it('creates audio track with correct properties', async () => {
    const mockAudioUrl = 'blob:mock-audio-url';
    vi.mocked(ttsService.generateVoiceOver).mockResolvedValue(mockAudioUrl);

    const { result } = renderHook(() => useVoiceOverGenerator());

    const voiceOver: VoiceOver = {
      id: 'vo-5',
      text: 'This is a test voiceover with some text',
      voice: 'male',
      language: 'en-GB',
      speed: 1.2,
      pitch: 3,
      emotion: 'excited',
    };

    await act(async () => {
      await result.current.generateVoiceOver(voiceOver, 'shot-1');
    });

    const shot = useStore.getState().shots.find((s) => s.id === 'shot-1');
    const audioTrack = shot?.audioTracks[0];

    expect(audioTrack).toBeDefined();
    expect(audioTrack?.type).toBe('voiceover');
    expect(audioTrack?.url).toBe(mockAudioUrl);
    expect(audioTrack?.volume).toBe(80);
    expect(audioTrack?.fadeIn).toBe(0.5);
    expect(audioTrack?.fadeOut).toBe(0.5);
    expect(audioTrack?.pan).toBe(0);
    expect(audioTrack?.muted).toBe(false);
    expect(audioTrack?.solo).toBe(false);
    expect(audioTrack?.name).toContain('Voiceover:');
  });
});

/**
 * Toast Hook
 * Toast notification system integrated with Radix UI Toast
 */

import { useState, useCallback, useEffect, useRef } from 'react';

export interface Toast {
  id: string;
  title: string;
  description?: string;
  variant?: 'default' | 'destructive' | 'success' | 'warning' | 'info';
  duration?: number;
  action?: {
    label: string;
    onClick: () => void;
  };
}

interface ToastState {
  toasts: Toast[];
}

const toastState: ToastState = {
  toasts: [],
};

const listeners = new Set<(state: ToastState) => void>();

// Counter for generating unique toast IDs (more reliable than Math.random)
let toastIdCounter = 0;

function notify() {
  listeners.forEach((listener) => listener(toastState));
}

export function useToast() {
  const [state, setState] = useState<ToastState>(toastState);
  const pendingTimeouts = useRef<Map<string, ReturnType<typeof setTimeout>>>(new Map());

  useEffect(() => {
    const listener = (newState: ToastState) => {
      setState({ ...newState });
    };
    listeners.add(listener);
    return () => {
      listeners.delete(listener);
    };
  }, []);

  const dismiss = useCallback((id: string) => {
    // Clear any pending timeout for this toast
    const timeout = pendingTimeouts.current.get(id);
    if (timeout) {
      clearTimeout(timeout);
      pendingTimeouts.current.delete(id);
    }
    toastState.toasts = toastState.toasts.filter((t) => t.id !== id);
    notify();
  }, []);

  const toast = useCallback(
    ({
      title,
      description,
      variant = 'default',
      duration = 5000,
      action,
    }: Omit<Toast, 'id'>) => {
      // Use counter for unique ID generation (avoids Math.random collisions)
      toastIdCounter++;
      const id = `toast-${toastIdCounter}-${Date.now()}`;

      const newToast: Toast = { id, title, description, variant, duration, action };

      toastState.toasts = [...toastState.toasts, newToast];
      notify();

      // Auto-dismiss after duration
      if (duration > 0) {
        const timeoutId = setTimeout(() => {
          dismiss(id);
        }, duration);
        pendingTimeouts.current.set(id, timeoutId);
      }

      return id;
    },
    [dismiss]
  );

  // Cleanup pending timeouts on unmount
  useEffect(() => {
    return () => {
      pendingTimeouts.current.forEach((timeout) => clearTimeout(timeout));
      pendingTimeouts.current.clear();
    };
  }, []);

  return {
    toast,
    dismiss,
    toasts: state.toasts,
  };
}

// Standalone toast function for use outside React components
export function toast({
  title,
  description,
  variant = 'default',
  duration = 5000,
  action,
}: Omit<Toast, 'id'>) {
  // Use counter for unique ID generation (avoids Math.random collisions)
  toastIdCounter++;
  const id = `toast-${toastIdCounter}-${Date.now()}`;

  const newToast: Toast = { id, title, description, variant, duration, action };

  toastState.toasts = [...toastState.toasts, newToast];
  notify();

  // Auto-dismiss after duration
  if (duration > 0) {
    setTimeout(() => {
      toastState.toasts = toastState.toasts.filter((t) => t.id !== id);
      notify();
    }, duration);
  }

  return id;
}

