/**
 * Accessibility Hooks
 * 
 * Custom hooks for managing accessibility features in the generation-buttons-ui.
 * Provides focus management, keyboard navigation, and ARIA live region support.
 * 
 * Requirements: 5.3, 5.4
 */

import { useState, useEffect, useRef, useCallback } from 'react';

/**
 * Hook for managing focus trap in dialogs
 * Ensures focus stays within the dialog when open
 * 
 * Requirements: 5.4
 */
export function useFocusTrap(isOpen: boolean) {
  const containerRef = useRef<HTMLDivElement>(null);
  const previousFocusRef = useRef<HTMLElement | null>(null);

  useEffect(() => {
    if (!isOpen) return;

    // Store the element that had focus before the dialog opened
    previousFocusRef.current = document.activeElement as HTMLElement;

    // Focus the first focusable element in the dialog
    const container = containerRef.current;
    if (!container) return;

    const focusableElements = container.querySelectorAll<HTMLElement>(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    );

    if (focusableElements.length > 0) {
      focusableElements[0].focus();
    }

    // Handle Tab key to trap focus
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Tab') return;

      const firstElement = focusableElements[0];
      const lastElement = focusableElements[focusableElements.length - 1];

      if (event.shiftKey) {
        // Shift + Tab
        if (document.activeElement === firstElement) {
          event.preventDefault();
          lastElement.focus();
        }
      } else {
        // Tab
        if (document.activeElement === lastElement) {
          event.preventDefault();
          firstElement.focus();
        }
      }
    };

    container.addEventListener('keydown', handleKeyDown);

    // Cleanup: restore focus when dialog closes
    return () => {
      container.removeEventListener('keydown', handleKeyDown);
      if (previousFocusRef.current) {
        previousFocusRef.current.focus();
      }
    };
  }, [isOpen]);

  return containerRef;
}

/**
 * Hook for announcing messages to screen readers
 * Uses ARIA live regions for dynamic content updates
 * 
 * Requirements: 5.3, 5.4
 */
export function useAnnouncer() {
  const announcerRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    // Create announcer element if it doesn't exist
    if (!announcerRef.current) {
      const announcer = document.createElement('div');
      announcer.setAttribute('role', 'status');
      announcer.setAttribute('aria-live', 'polite');
      announcer.setAttribute('aria-atomic', 'true');
      announcer.className = 'sr-only';
      announcer.style.position = 'absolute';
      announcer.style.left = '-10000px';
      announcer.style.width = '1px';
      announcer.style.height = '1px';
      announcer.style.overflow = 'hidden';
      document.body.appendChild(announcer);
      announcerRef.current = announcer;
    }

    return () => {
      if (announcerRef.current) {
        document.body.removeChild(announcerRef.current);
        announcerRef.current = null;
      }
    };
  }, []);

  const announce = useCallback((message: string, priority: 'polite' | 'assertive' = 'polite') => {
    if (!announcerRef.current) return;

    // Update aria-live attribute based on priority
    announcerRef.current.setAttribute('aria-live', priority);

    // Clear and set new message
    announcerRef.current.textContent = '';
    setTimeout(() => {
      if (announcerRef.current) {
        announcerRef.current.textContent = message;
      }
    }, 100);
  }, []);

  return announce;
}

/**
 * Hook for managing keyboard shortcuts with accessibility
 * Provides proper ARIA labels and keyboard event handling
 * 
 * Requirements: 13.1, 13.2, 13.3, 13.4, 13.5
 */
export function useKeyboardShortcut(
  key: string,
  callback: () => void,
  options: {
    ctrl?: boolean;
    shift?: boolean;
    alt?: boolean;
    enabled?: boolean;
  } = {}
) {
  const { ctrl = false, shift = false, alt = false, enabled = true } = options;

  useEffect(() => {
    if (!enabled) return;

    const handleKeyDown = (event: KeyboardEvent) => {
      const matchesModifiers =
        event.ctrlKey === ctrl &&
        event.shiftKey === shift &&
        event.altKey === alt;

      if (matchesModifiers && event.key === key) {
        event.preventDefault();
        callback();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [key, callback, ctrl, shift, alt, enabled]);

  // Return formatted shortcut string for display
  const shortcutString = [
    ctrl && 'Ctrl',
    shift && 'Shift',
    alt && 'Alt',
    key,
  ]
    .filter(Boolean)
    .join('+');

  return shortcutString;
}

/**
 * Hook for managing progress announcements
 * Announces progress updates at appropriate intervals
 * 
 * Requirements: 7.1, 7.3
 */
export function useProgressAnnouncer(
  progress: number,
  message: string,
  isActive: boolean
) {
  const announce = useAnnouncer();
  const lastAnnouncedRef = useRef<number>(0);
  const ANNOUNCEMENT_THRESHOLD = 25; // Announce every 25% progress

  useEffect(() => {
    if (!isActive) return;

    const currentMilestone = Math.floor(progress / ANNOUNCEMENT_THRESHOLD) * ANNOUNCEMENT_THRESHOLD;

    if (currentMilestone > lastAnnouncedRef.current && currentMilestone > 0) {
      announce(`${message}. ${currentMilestone}% complete.`, 'polite');
      lastAnnouncedRef.current = currentMilestone;
    }

    // Announce completion
    if (progress >= 100 && lastAnnouncedRef.current < 100) {
      announce(`${message} complete.`, 'assertive');
      lastAnnouncedRef.current = 100;
    }
  }, [progress, message, isActive, announce]);

  // Reset when inactive
  useEffect(() => {
    if (!isActive) {
      lastAnnouncedRef.current = 0;
    }
  }, [isActive]);
}

/**
 * Hook for managing error announcements
 * Announces errors immediately with assertive priority
 * 
 * Requirements: 8.5
 */
export function useErrorAnnouncer(error: string | null) {
  const announce = useAnnouncer();
  const previousErrorRef = useRef<string | null>(null);

  useEffect(() => {
    if (error && error !== previousErrorRef.current) {
      announce(`Error: ${error}`, 'assertive');
      previousErrorRef.current = error;
    } else if (!error) {
      previousErrorRef.current = null;
    }
  }, [error, announce]);
}

/**
 * Hook for managing button state announcements
 * Announces button state changes to screen readers
 * 
 * Requirements: 5.3, 5.4, 5.5
 */
export function useButtonStateAnnouncer(
  buttonName: string,
  isDisabled: boolean,
  disabledReason?: string
) {
  const announce = useAnnouncer();
  const previousStateRef = useRef<boolean>(isDisabled);

  useEffect(() => {
    if (isDisabled !== previousStateRef.current) {
      if (isDisabled && disabledReason) {
        announce(`${buttonName} disabled: ${disabledReason}`, 'polite');
      } else if (!isDisabled) {
        announce(`${buttonName} enabled`, 'polite');
      }
      previousStateRef.current = isDisabled;
    }
  }, [buttonName, isDisabled, disabledReason, announce]);
}

/**
 * Get ARIA description for generation button state
 * 
 * Requirements: 5.3, 5.4, 5.5
 */
export function getButtonAriaDescription(
  buttonType: 'prompt' | 'image' | 'video' | 'audio',
  isDisabled: boolean,
  isGenerating: boolean,
  isCompleted: boolean,
  isFailed: boolean,
  disabledReason?: string
): string {
  if (disabledReason) {
    return disabledReason;
  }

  if (isGenerating) {
    return `${buttonType} generation in progress`;
  }

  if (isFailed) {
    return `${buttonType} generation failed. Click to retry`;
  }

  if (isCompleted) {
    return `${buttonType} generated successfully. Click to regenerate`;
  }

  if (isDisabled) {
    return `${buttonType} generation not available. Complete previous steps first`;
  }

  return `Generate ${buttonType} content`;
}

/**
 * Get ARIA label for progress value
 * 
 * Requirements: 7.1, 7.3
 */
export function getProgressAriaLabel(
  progress: number,
  stage?: string
): string {
  const percentage = Math.round(progress);
  
  if (stage) {
    return `${stage}: ${percentage}% complete`;
  }
  
  return `${percentage}% complete`;
}

/**
 * Get ARIA label for time remaining
 * 
 * Requirements: 7.3, 7.4
 */
export function getTimeRemainingAriaLabel(milliseconds: number): string {
  const seconds = Math.floor(milliseconds / 1000);
  const minutes = Math.floor(seconds / 60);
  const hours = Math.floor(minutes / 60);

  if (hours > 0) {
    const remainingMinutes = minutes % 60;
    return `Estimated ${hours} hour${hours > 1 ? 's' : ''} and ${remainingMinutes} minute${remainingMinutes !== 1 ? 's' : ''} remaining`;
  }

  if (minutes > 0) {
    const remainingSeconds = seconds % 60;
    return `Estimated ${minutes} minute${minutes > 1 ? 's' : ''} and ${remainingSeconds} second${remainingSeconds !== 1 ? 's' : ''} remaining`;
  }

  return `Estimated ${seconds} second${seconds !== 1 ? 's' : ''} remaining`;
}

/**
 * Hook for detecting user's reduced motion preference
 * Requirements: 5.3
 */
export function useReducedMotion(): boolean {
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);
  
  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    setPrefersReducedMotion(mediaQuery.matches);
    
    const handler = (e: MediaQueryListEvent) => {
      setPrefersReducedMotion(e.matches);
    };
    
    mediaQuery.addEventListener('change', handler);
    return () => mediaQuery.removeEventListener('change', handler);
  }, []);
  
  return prefersReducedMotion;
}

// Alias for useAnnouncer for backward compatibility
export const useAnnounce = useAnnouncer;

/**
 * useAnimatedSprite Hook
 * 
 * Custom hook for managing animated sprites with orientation and effects.
 * Provides a simple API for sprite manipulation in components.
 */

import { useCallback, useEffect, useRef, useState } from 'react';
import {
  AnimatedSprite,
  SpriteOrientation,
  SpriteTransform,
  movementToOrientation,
  SPRITE_ORIENTATIONS
} from '@/types/sprite';

import {
  AnimeEffect,
  AnimeEffectPreset,
  ANIME_EFFECT_PRESETS
} from '@/types/animeEffect';


// ============================================================================
// Types
// ============================================================================

export interface UseAnimatedSpriteOptions {
  /** Initial sprite data */
  initialSprite?: AnimatedSprite;
  /** Initial orientation */
  initialOrientation?: SpriteOrientation;
  /** Auto-play animation on mount */
  autoPlay?: boolean;
  /** Loop animation */
  loop?: boolean;
  /** Animation speed multiplier */
  speed?: number;
  /** Initial effects */
  initialEffects?: AnimeEffect[];
}

export interface UseAnimatedSpriteReturn {
  // Sprite state
  sprite: AnimatedSprite | null;
  orientation: SpriteOrientation;
  transform: SpriteTransform;
  effects: AnimeEffect[];
  isPlaying: boolean;
  currentFrame: number;
  currentAnimation: string;

  // Sprite actions
  setSprite: (sprite: AnimatedSprite) => void;
  clearSprite: () => void;

  // Orientation actions
  setOrientation: (orientation: SpriteOrientation) => void;
  autoOrient: (dx: number, dy: number) => void;
  rotateCW: () => void;
  rotateCCW: () => void;

  // Animation actions
  play: () => void;
  pause: () => void;
  stop: () => void;
  playAnimation: (animationName: string) => void;
  setSpeed: (speed: number) => void;
  setFrame: (frame: number) => void;

  // Transform actions
  setPosition: (x: number, y: number) => void;
  move: (dx: number, dy: number) => void;
  setScale: (scale: number) => void;
  setRotation: (degrees: number) => void;
  rotate: (degrees: number) => void;
  flipHorizontal: () => void;
  flipVertical: () => void;
  setOpacity: (opacity: number) => void;

  // Effect actions
  addEffect: (effect: AnimeEffect) => void;
  removeEffect: (effectId: string) => void;
  updateEffect: (effectId: string, updates: Partial<AnimeEffect>) => void;
  clearEffects: () => void;
  applyPreset: (presetId: string) => void;

  // Utility
  availableAnimations: string[];
  availableOrientations: SpriteOrientation[];
  getEffectStack: () => AnimeEffect[];
}

// ============================================================================
// Hook Implementation
// ============================================================================

export function useAnimatedSprite(
  options: UseAnimatedSpriteOptions = {}
): UseAnimatedSpriteReturn {
  const {
    initialSprite,
    initialOrientation = 's',
    autoPlay = false,
    loop = true,
    speed = 1,
    initialEffects = []
  } = options;

  // Local state
  const [sprite, setSpriteState] = useState<AnimatedSprite | null>(initialSprite || null);
  const [orientation, setOrientationState] = useState<SpriteOrientation>(initialOrientation);
  const [transform, setTransform] = useState<SpriteTransform>({
    position: { x: 0, y: 0 },
    scale: { x: 1, y: 1 },
    rotation: 0,
    flipH: false,
    flipV: false,
    opacity: 1
  });
  const [effects, setEffects] = useState<AnimeEffect[]>(initialEffects);
  const [isPlaying, setIsPlaying] = useState(autoPlay);
  const [currentFrame, setCurrentFrame] = useState(0);
  const [currentAnimation, setCurrentAnimation] = useState('idle');

  // Animation frame reference
  const animationRef = useRef<number | null>(null);
  const lastTimeRef = useRef<number>(0);
  const frameTimeRef = useRef<number>(0);
  const currentSpeedRef = useRef<number>(speed);

  // ==========================================================================
  // Sprite Management
  // ==========================================================================

  const setSprite = useCallback((newSprite: AnimatedSprite) => {
    setSpriteState(newSprite);
    setCurrentAnimation(newSprite.animationList[0] || 'idle');
    setOrientationState(newSprite.currentOrientation);
    if (autoPlay) {
      setIsPlaying(true);
    }
  }, [autoPlay]);

  const clearSprite = useCallback(() => {
    setSpriteState(null);
    setIsPlaying(false);
    setCurrentFrame(0);
    setEffects([]);
  }, []);

  // ==========================================================================
  // Orientation Management
  // ==========================================================================

  const setOrientation = useCallback((newOrientation: SpriteOrientation) => {
    setOrientationState(newOrientation);
  }, []);

  const autoOrient = useCallback((dx: number, dy: number) => {
    const newOrientation = movementToOrientation(dx, dy);
    setOrientationState(newOrientation);
  }, []);

  const rotateCW = useCallback(() => {
    const currentIndex = SPRITE_ORIENTATIONS.indexOf(orientation);
    const nextIndex = (currentIndex + 1) % SPRITE_ORIENTATIONS.length;
    setOrientationState(SPRITE_ORIENTATIONS[nextIndex]);
  }, [orientation]);

  const rotateCCW = useCallback(() => {
    const currentIndex = SPRITE_ORIENTATIONS.indexOf(orientation);
    const prevIndex = (currentIndex - 1 + SPRITE_ORIENTATIONS.length) % SPRITE_ORIENTATIONS.length;
    setOrientationState(SPRITE_ORIENTATIONS[prevIndex]);
  }, [orientation]);

  // ==========================================================================
  // Animation Management
  // ==========================================================================

  const play = useCallback(() => {
    setIsPlaying(true);
  }, []);

  const pause = useCallback(() => {
    setIsPlaying(false);
  }, []);

  const stop = useCallback(() => {
    setIsPlaying(false);
    setCurrentFrame(0);
    frameTimeRef.current = 0;
  }, []);

  const playAnimation = useCallback((animationName: string) => {
    setCurrentAnimation(animationName);
    setCurrentFrame(0);
    frameTimeRef.current = 0;
    setIsPlaying(true);
  }, []);

  const setSpeed = useCallback((newSpeed: number) => {
    // Speed is applied in the animation loop
  }, []);

  const setFrame = useCallback((frame: number) => {
    if (sprite) {
      // Get max frames for current animation
      const maxFrames = 8; // Placeholder - should get from actual animation
      setCurrentFrame(Math.max(0, Math.min(frame, maxFrames - 1)));
    }
  }, [sprite]);

  // Animation loop
  useEffect(() => {
    if (!isPlaying || !sprite) return;

    const animate = (timestamp: number) => {
      if (!lastTimeRef.current) {
        lastTimeRef.current = timestamp;
      }

      const deltaTime = timestamp - lastTimeRef.current;
      lastTimeRef.current = timestamp;

      // Update frame based on delta time and speed
      frameTimeRef.current += deltaTime * speed;

      // Frame duration (100ms default, should get from actual animation)
      const frameDuration = 100;

      if (frameTimeRef.current >= frameDuration) {
        frameTimeRef.current -= frameDuration;
        
        // Get max frames for current animation
        const maxFrames = 8; // Placeholder
        
        setCurrentFrame(prev => {
          const nextFrame = prev + 1;
          if (nextFrame >= maxFrames) {
            if (loop) {
              return 0;
            } else {
              setIsPlaying(false);
              return maxFrames - 1;
            }
          }
          return nextFrame;
        });
      }

      animationRef.current = requestAnimationFrame(animate);
    };

    animationRef.current = requestAnimationFrame(animate);

    return () => {
      if (animationRef.current !== null) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [isPlaying, sprite, speed, loop]);

  // ==========================================================================
  // Transform Management
  // ==========================================================================

  const setPosition = useCallback((x: number, y: number) => {
    setTransform(prev => ({
      ...prev,
      position: { x, y }
    }));
  }, []);

  const move = useCallback((dx: number, dy: number) => {
    setTransform(prev => ({
      ...prev,
      position: {
        x: prev.position.x + dx,
        y: prev.position.y + dy
      }
    }));
  }, []);

  const setScale = useCallback((scale: number) => {
    setTransform(prev => ({
      ...prev,
      scale: { x: scale, y: scale }
    }));
  }, []);

  const setRotation = useCallback((degrees: number) => {
    setTransform(prev => ({
      ...prev,
      rotation: degrees
    }));
  }, []);

  const rotate = useCallback((degrees: number) => {
    setTransform(prev => ({
      ...prev,
      rotation: prev.rotation + degrees
    }));
  }, []);

  const flipHorizontal = useCallback(() => {
    setTransform(prev => ({
      ...prev,
      flipH: !prev.flipH
    }));
  }, []);

  const flipVertical = useCallback(() => {
    setTransform(prev => ({
      ...prev,
      flipV: !prev.flipV
    }));
  }, []);

  const setOpacity = useCallback((opacity: number) => {
    setTransform(prev => ({
      ...prev,
      opacity: Math.max(0, Math.min(1, opacity))
    }));
  }, []);

  // ==========================================================================
  // Effect Management
  // ==========================================================================

  const addEffect = useCallback((effect: AnimeEffect) => {
    setEffects(prev => [...prev, effect]);
  }, []);

  const removeEffect = useCallback((effectId: string) => {
    setEffects(prev => prev.filter(e => e.id !== effectId));
  }, []);

  const updateEffect = useCallback((effectId: string, updates: Partial<AnimeEffect>) => {
    setEffects(prev => prev.map(e => 
      e.id === effectId ? { ...e, ...updates } as AnimeEffect : e
    ));
  }, []);

  const clearEffects = useCallback(() => {
    setEffects([]);
  }, []);

  const applyPreset = useCallback((presetId: string) => {
    const preset = ANIME_EFFECT_PRESETS.find(p => p.id === presetId);
    if (preset) {
      const newEffects = preset.effects.map(e => ({
        ...e,
        id: `${e.type}_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
      }));
      setEffects(prev => [...prev, ...newEffects]);
    }
  }, []);

  const getEffectStack = useCallback(() => {
    return effects;
  }, [effects]);

  // ==========================================================================
  // Computed Values
  // ==========================================================================

  const availableAnimations = sprite?.animationList || [];
  
  const availableOrientations = SPRITE_ORIENTATIONS.filter(o => {
    if (!sprite) return false;
    // Check if animation exists for this orientation
    const key = `${currentAnimation}_${o}`;
    return sprite.animations.has(key);
  });

  // ==========================================================================
  // Return
  // ==========================================================================

  return {
    // State
    sprite,
    orientation,
    transform,
    effects,
    isPlaying,
    currentFrame,
    currentAnimation,

    // Sprite actions
    setSprite,
    clearSprite,

    // Orientation actions
    setOrientation,
    autoOrient,
    rotateCW,
    rotateCCW,

    // Animation actions
    play,
    pause,
    stop,
    playAnimation,
    setSpeed,
    setFrame,

    // Transform actions
    setPosition,
    move,
    setScale,
    setRotation,
    rotate,
    flipHorizontal,
    flipVertical,
    setOpacity,

    // Effect actions
    addEffect,
    removeEffect,
    updateEffect,
    clearEffects,
    applyPreset,

    // Utility
    availableAnimations,
    availableOrientations,
    getEffectStack
  };
}

// ============================================================================
// Utility Hooks
// ============================================================================

/**
 * Hook for managing multiple sprites
 */
export function useSpriteManager() {
  const [sprites, setSprites] = useState<Map<string, AnimatedSprite>>(new Map());
  const [activeSpriteId, setActiveSpriteId] = useState<string | null>(null);

  const addSprite = useCallback((sprite: AnimatedSprite) => {
    setSprites(prev => new Map(prev).set(sprite.id, sprite));
    setActiveSpriteId(sprite.id);
  }, []);

  const removeSprite = useCallback((id: string) => {
    setSprites(prev => {
      const newMap = new Map(prev);
      newMap.delete(id);
      return newMap;
    });
    if (activeSpriteId === id) {
      setActiveSpriteId(null);
    }
  }, [activeSpriteId]);

  const getSprite = useCallback((id: string) => {
    return sprites.get(id);
  }, [sprites]);

  const activeSprite = activeSpriteId ? sprites.get(activeSpriteId) : null;

  return {
    sprites: Array.from(sprites.values()),
    activeSprite,
    activeSpriteId,
    addSprite,
    removeSprite,
    getSprite,
    setActiveSpriteId
  };
}

/**
 * Hook for effect presets
 */
export function useEffectPresets() {
  const getPresets = useCallback(() => ANIME_EFFECT_PRESETS, []);
  
  const getPreset = useCallback((id: string) => {
    return ANIME_EFFECT_PRESETS.find(p => p.id === id);
  }, []);

  const getPresetsByCategory = useCallback((category: AnimeEffectPreset['category']) => {
    return ANIME_EFFECT_PRESETS.filter(p => p.category === category);
  }, []);

  const searchPresets = useCallback((query: string) => {
    const lowerQuery = query.toLowerCase();
    return ANIME_EFFECT_PRESETS.filter(p => 
      p.name.toLowerCase().includes(lowerQuery) ||
      p.description.toLowerCase().includes(lowerQuery) ||
      p.tags.some(t => t.toLowerCase().includes(lowerQuery))
    );
  }, []);

  return {
    presets: ANIME_EFFECT_PRESETS,
    getPresets,
    getPreset,
    getPresetsByCategory,
    searchPresets
  };
}

export default useAnimatedSprite;

