/**
 * useAnimationOrchestrator Hook
 * 
 * React hook for using the animation orchestrator.
 * Provides a simple API for orchestrating animations in components.
 * 
 * Validates: Requirements 11.8
 */

import { useCallback, useEffect, useRef } from 'react';
import {
  animationOrchestrator,
  createAnimationTask,
  AnimationOrchestrator,
} from '../services/animation/AnimationOrchestrator';

type AnimationPriority = 'low' | 'normal' | 'high' | 'critical';

interface UseAnimationOrchestratorOptions {
  priority?: AnimationPriority;
  canInterrupt?: boolean;
  conflictsWith?: string[];
}

/**
 * Hook to orchestrate animations
 * 
 * Validates: Requirements 11.8
 * 
 * @example
 * ```tsx
 * const { executeAnimation } = useAnimationOrchestrator();
 * 
 * const handleClick = async () => {
 *   await executeAnimation('my-animation', async () => {
 *     // Animation logic
 *   });
 * };
 * ```
 */
export function useAnimationOrchestrator(
  options: UseAnimationOrchestratorOptions = {}
) {
  const orchestratorRef = useRef<AnimationOrchestrator>(animationOrchestrator);
  const activeAnimationsRef = useRef<Set<string>>(new Set());

  /**
   * Execute an animation through the orchestrator
   */
  const executeAnimation = useCallback(
    async (
      id: string,
      execute: () => Promise<void> | void,
      overrideOptions?: UseAnimationOrchestratorOptions
    ) => {
      const finalOptions = { ...options, ...overrideOptions };

      const task = createAnimationTask(id, execute, {
        priority: finalOptions.priority,
        canInterrupt: finalOptions.canInterrupt,
        conflictsWith: finalOptions.conflictsWith,
      });

      activeAnimationsRef.current.add(id);

      try {
        await orchestratorRef.current.execute(task);
      } finally {
        activeAnimationsRef.current.delete(id);
      }
    },
    [options]
  );

  /**
   * Cancel a specific animation
   */
  const cancelAnimation = useCallback(async (id: string) => {
    if (activeAnimationsRef.current.has(id)) {
      // In a real implementation, we'd cancel the specific animation
      // For now, we just remove it from tracking
      activeAnimationsRef.current.delete(id);
    }
  }, []);

  /**
   * Cancel all animations from this component
   */
  const cancelAll = useCallback(async () => {
    const ids = Array.from(activeAnimationsRef.current);
    for (const id of ids) {
      await cancelAnimation(id);
    }
  }, [cancelAnimation]);

  /**
   * Get orchestrator status
   */
  const getStatus = useCallback(() => {
    return orchestratorRef.current.getStatus();
  }, []);

  /**
   * Cleanup on unmount
   */
  useEffect(() => {
    return () => {
      cancelAll();
    };
  }, [cancelAll]);

  return {
    executeAnimation,
    cancelAnimation,
    cancelAll,
    getStatus,
  };
}

/**
 * Hook for sequential animations
 * Ensures animations run one after another
 * 
 * Validates: Requirements 11.8
 */
export function useSequentialAnimations() {
  const { executeAnimation } = useAnimationOrchestrator({
    priority: 'normal',
    canInterrupt: false,
  });

  const sequenceRef = useRef<string[]>([]);
  const currentIndexRef = useRef(0);

  const executeSequence = useCallback(
    async (
      animations: Array<{
        id: string;
        execute: () => Promise<void> | void;
      }>
    ) => {
      sequenceRef.current = animations.map((a) => a.id);
      currentIndexRef.current = 0;

      for (const animation of animations) {
        await executeAnimation(animation.id, animation.execute, {
          conflictsWith: sequenceRef.current.filter(
            (id) => id !== animation.id
          ),
        });
        currentIndexRef.current++;
      }
    },
    [executeAnimation]
  );

  return {
    executeSequence,
    currentIndex: currentIndexRef.current,
    totalAnimations: sequenceRef.current.length,
  };
}

/**
 * Hook for parallel animations with coordination
 * Ensures animations don't conflict visually
 * 
 * Validates: Requirements 11.8
 */
export function useParallelAnimations() {
  const { executeAnimation } = useAnimationOrchestrator({
    priority: 'normal',
  });

  const executeParallel = useCallback(
    async (
      animations: Array<{
        id: string;
        execute: () => Promise<void> | void;
        conflictsWith?: string[];
      }>
    ) => {
      const promises = animations.map((animation) =>
        executeAnimation(animation.id, animation.execute, {
          conflictsWith: animation.conflictsWith,
        })
      );

      await Promise.all(promises);
    },
    [executeAnimation]
  );

  return {
    executeParallel,
  };
}

/**
 * Hook for staggered animations
 * Executes animations with a delay between each
 * 
 * Validates: Requirements 11.8
 */
export function useStaggeredAnimations(delayMs: number = 100) {
  const { executeAnimation } = useAnimationOrchestrator();

  const executeStaggered = useCallback(
    async (
      animations: Array<{
        id: string;
        execute: () => Promise<void> | void;
      }>
    ) => {
      for (let i = 0; i < animations.length; i++) {
        const animation = animations[i];

        // Start animation
        executeAnimation(animation.id, animation.execute);

        // Wait for stagger delay before starting next
        if (i < animations.length - 1) {
          await new Promise((resolve) => setTimeout(resolve, delayMs));
        }
      }
    },
    [executeAnimation, delayMs]
  );

  return {
    executeStaggered,
  };
}

import { useEffect, useRef, useState } from 'react';
import { getAudioEngine, AudioEngine } from '../audio/AudioEngine';
import type { AudioTrack } from '../types';

/**
 * React hook for using the AudioEngine
 */
export function useAudioEngine() {
  const engineRef = useRef<AudioEngine | null>(null);
  const [isReady, setIsReady] = useState(false);

  useEffect(() => {
    // Get or create audio engine instance
    engineRef.current = getAudioEngine();

    // Resume audio context (required for some browsers)
    engineRef.current.resumeContext().then(() => {
      setIsReady(true);
    });

    return () => {
      // Don't destroy the engine on unmount - it's a singleton
      // It will be destroyed when the app closes
    };
  }, []);

  const loadTrack = async (track: AudioTrack) => {
    if (!engineRef.current) return;
    await engineRef.current.loadTrack(track);
  };

  const play = (trackId: string, startTime?: number) => {
    if (!engineRef.current) return;
    engineRef.current.play(trackId, startTime);
  };

  const pause = (trackId: string) => {
    if (!engineRef.current) return;
    engineRef.current.pause(trackId);
  };

  const resume = (trackId: string) => {
    if (!engineRef.current) return;
    engineRef.current.resume(trackId);
  };

  const stop = (trackId: string) => {
    if (!engineRef.current) return;
    engineRef.current.stop(trackId);
  };

  const setVolume = (trackId: string, volume: number) => {
    if (!engineRef.current) return;
    engineRef.current.setVolume(trackId, volume);
  };

  const setPan = (trackId: string, pan: number) => {
    if (!engineRef.current) return;
    engineRef.current.setPan(trackId, pan);
  };

  const applyFades = (trackId: string, fadeIn: number, fadeOut: number, duration: number) => {
    if (!engineRef.current) return;
    engineRef.current.applyFades(trackId, fadeIn, fadeOut, duration);
  };

  const unloadTrack = (trackId: string) => {
    if (!engineRef.current) return;
    engineRef.current.unloadTrack(trackId);
  };

  const setMasterVolume = (volume: number) => {
    if (!engineRef.current) return;
    engineRef.current.setMasterVolume(volume);
  };

  const isPlaying = (trackId: string): boolean => {
    if (!engineRef.current) return false;
    return engineRef.current.isPlaying(trackId);
  };

  const getCurrentTime = (trackId: string): number => {
    if (!engineRef.current) return 0;
    return engineRef.current.getCurrentTime(trackId);
  };

  return {
    isReady,
    loadTrack,
    play,
    pause,
    resume,
    stop,
    setVolume,
    setPan,
    applyFades,
    unloadTrack,
    setMasterVolume,
    isPlaying,
    getCurrentTime,
  };
}

/**
 * Hook for managing a single audio track
 */
export function useAudioTrack(track: AudioTrack) {
  const audioEngine = useAudioEngine();
  const [isLoaded, setIsLoaded] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Load track when URL changes
  useEffect(() => {
    if (!track.url || !audioEngine.isReady) return;

    setIsLoaded(false);
    setError(null);

    audioEngine
      .loadTrack(track)
      .then(() => {
        setIsLoaded(true);
      })
      .catch((err) => {
        console.error('Error loading audio track:', err);
        setError(err.message || 'Failed to load audio');
      });

    return () => {
      // Unload track on unmount
      audioEngine.unloadTrack(track.id);
    };
  }, [track.url, track.id, audioEngine.isReady]);

  // Update volume when it changes
  useEffect(() => {
    if (!isLoaded) return;
    audioEngine.setVolume(track.id, track.volume);
  }, [track.volume, isLoaded, track.id]);

  // Update pan when it changes
  useEffect(() => {
    if (!isLoaded) return;
    audioEngine.setPan(track.id, track.pan);
  }, [track.pan, isLoaded, track.id]);

  // Apply fades when they change
  useEffect(() => {
    if (!isLoaded || !isPlaying) return;
    audioEngine.applyFades(track.id, track.fadeIn, track.fadeOut, track.duration);
  }, [track.fadeIn, track.fadeOut, track.duration, isLoaded, isPlaying, track.id]);

  const play = () => {
    if (!isLoaded) return;
    audioEngine.play(track.id, track.offset);
    setIsPlaying(true);
  };

  const pause = () => {
    if (!isLoaded) return;
    audioEngine.pause(track.id);
    setIsPlaying(false);
  };

  const resume = () => {
    if (!isLoaded) return;
    audioEngine.resume(track.id);
    setIsPlaying(true);
  };

  const stop = () => {
    if (!isLoaded) return;
    audioEngine.stop(track.id);
    setIsPlaying(false);
  };

  return {
    isLoaded,
    isPlaying,
    error,
    play,
    pause,
    resume,
    stop,
  };
}

