/**
 * useBatchOperationEstimate - Hook pour estimation de temps d'op├®rations par lots
 * 
 * Fournit des estimations de temps bas├®es sur l'historique:
 * - Calcul du temps estim├® pour une op├®ration
 * - Affichage format├® du temps
 * - Mise ├á jour en temps r├®el
 * 
 * Exigence: 8.8 - Estimation de temps
 */

import { useState, useEffect, useMemo } from 'react';
import type { BatchOperationType, Shot } from '../types';
import { BatchOperationsManager } from '../services/batchOperations';

/**
 * R├®sultat de l'estimation
 */
export interface BatchOperationEstimate {
  estimatedTime: number; // en millisecondes
  formattedTime: string; // format├® pour affichage
  confidence: 'low' | 'medium' | 'high'; // confiance dans l'estimation
  basedOnSamples: number; // nombre d'├®chantillons utilis├®s
}

/**
 * Options du hook
 */
export interface UseBatchOperationEstimateOptions {
  manager?: BatchOperationsManager;
  autoUpdate?: boolean; // Mettre ├á jour automatiquement
  updateInterval?: number; // Intervalle de mise ├á jour (ms)
}

/**
 * Hook pour estimation de temps d'op├®rations par lots
 * Exigence: 8.8 - Estimation de temps bas├®e sur l'historique
 */
export function useBatchOperationEstimate(
  type: BatchOperationType,
  items: Shot[],
  options: UseBatchOperationEstimateOptions = {}
): BatchOperationEstimate {
  const {
    manager: externalManager,
    autoUpdate = false,
    updateInterval = 5000
  } = options;
  
  // Cr├®er ou utiliser le gestionnaire fourni
  const manager = useMemo(
    () => externalManager || new BatchOperationsManager(),
    [externalManager]
  );
  
  // ├ëtat de l'estimation
  const [estimate, setEstimate] = useState<BatchOperationEstimate>(() =>
    calculateEstimate(manager, type, items.length)
  );
  
  // Mettre ├á jour l'estimation
  useEffect(() => {
    const updateEstimate = () => {
      setEstimate(calculateEstimate(manager, type, items.length));
    };
    
    // Mise ├á jour initiale
    updateEstimate();
    
    // Mise ├á jour automatique si activ├®e
    if (autoUpdate) {
      const interval = setInterval(updateEstimate, updateInterval);
      return () => clearInterval(interval);
    }
  }, [manager, type, items.length, autoUpdate, updateInterval]);
  
  return estimate;
}

/**
 * Calcule l'estimation pour une op├®ration
 */
function calculateEstimate(
  manager: BatchOperationsManager,
  type: BatchOperationType,
  itemCount: number
): BatchOperationEstimate {
  // Obtenir le temps estim├® en millisecondes
  const estimatedTime = manager.estimateTime(type, itemCount);
  
  // Formater le temps
  const formattedTime = formatTime(estimatedTime);
  
  // D├®terminer la confiance bas├®e sur l'historique
  const operations = manager.getAllOperations();
  const relevantOps = operations.filter(
    op => op.type === type && op.status === 'completed'
  );
  
  const basedOnSamples = relevantOps.length;
  
  let confidence: 'low' | 'medium' | 'high';
  if (basedOnSamples === 0) {
    confidence = 'low';
  } else if (basedOnSamples < 5) {
    confidence = 'medium';
  } else {
    confidence = 'high';
  }
  
  return {
    estimatedTime,
    formattedTime,
    confidence,
    basedOnSamples
  };
}

/**
 * Formate un temps en millisecondes pour affichage
 */
function formatTime(ms: number): string {
  if (ms < 1000) {
    return `${ms}ms`;
  } else if (ms < 60000) {
    const seconds = Math.ceil(ms / 1000);
    return `${seconds}s`;
  } else if (ms < 3600000) {
    const minutes = Math.floor(ms / 60000);
    const seconds = Math.ceil((ms % 60000) / 1000);
    if (seconds === 0) {
      return `${minutes}m`;
    }
    return `${minutes}m ${seconds}s`;
  } else {
    const hours = Math.floor(ms / 3600000);
    const minutes = Math.floor((ms % 3600000) / 60000);
    if (minutes === 0) {
      return `${hours}h`;
    }
    return `${hours}h ${minutes}m`;
  }
}

/**
 * Hook simplifi├® pour obtenir juste le temps format├®
 */
export function useBatchOperationTime(
  type: BatchOperationType,
  items: Shot[],
  options?: UseBatchOperationEstimateOptions
): string {
  const estimate = useBatchOperationEstimate(type, items, options);
  return estimate.formattedTime;
}

/**
 * Hook pour obtenir les estimations de toutes les op├®rations
 */
export function useAllBatchOperationEstimates(
  items: Shot[],
  options?: UseBatchOperationEstimateOptions
): Record<BatchOperationType, BatchOperationEstimate> {
  const types: BatchOperationType[] = ['duplicate', 'delete', 'export', 'transform', 'tag'];
  
  const estimates = useMemo(() => {
    const manager = options?.manager || new BatchOperationsManager();
    const result: Record<string, BatchOperationEstimate> = {};
    
    for (const type of types) {
      result[type] = calculateEstimate(manager, type, items.length);
    }
    
    return result as Record<BatchOperationType, BatchOperationEstimate>;
  }, [items.length, options?.manager]);
  
  return estimates;
}

// ============================================================================
// Character Manager Hook
// ============================================================================
// Provides a unified API for all character operations including CRUD,
// validation, dependency checking, and relationship management.
//
// Requirements: 2.3, 2.5, 7.1, 7.4, 11.1, 11.2, 11.3
// ============================================================================

import { useCallback } from 'react';
import { useStore } from '../store';
import { useAppStore } from '../stores/useAppStore';
import type { Character } from '../types/character';
import type { Story } from '../types/story';
import {
  addRelationship as addRelationshipToStore,
  updateRelationship as updateRelationshipInStore,
  removeRelationship as removeRelationshipFromStore,
  type RelationshipData,
  type CharacterStore,
  type CharacterEventEmitter,
} from '../services/RelationshipManager';
import { eventEmitter } from '../services/eventEmitter';
import {
  CharacterError,
  CharacterErrorType,
  handleCharacterError,
  showValidationErrors,
  logValidationFailure,
} from '../utils/characterErrorHandler';

// ============================================================================
// Types
// ============================================================================

/**
 * Validation result for character data.
 * Requirements: 11.1, 11.2, 11.3
 */
export interface ValidationResult {
  valid: boolean;
  errors: Record<string, string[]>;
}

/**
 * Character dependencies (stories and relationships).
 * Requirements: 7.1
 */
export interface CharacterDependencies {
  stories: Story[];
  relationships: Character[];
}

/**
 * Options for character deletion.
 * Requirements: 7.1, 7.4
 */
export interface DeleteOptions {
  force?: boolean; // Skip dependency check
  removeFromStories?: boolean; // Remove from stories automatically
}

// ============================================================================
// Validation Functions
// ============================================================================

/**
 * Validates character data before save.
 * 
 * Checks:
 * - Name is not empty (Requirement 11.1)
 * - Archetype is selected (Requirement 11.2)
 * - Age range is specified (Requirement 11.3)
 * - Relationship references point to existing characters (Requirement 11.4)
 * 
 * Requirements: 2.3, 11.1, 11.2, 11.3, 11.4
 * 
 * @param data - Character data to validate
 * @param existingCharacters - Optional array of existing characters for relationship validation
 */
export function validateCharacter(
  data: Partial<Character>,
  existingCharacters?: Character[]
): ValidationResult {
  const errors: Record<string, string[]> = {};

  // Validate name (Requirement 11.1)
  if (!data.name || data.name.trim() === '') {
    errors.name = ['Character name is required'];
  }

  // Validate archetype (Requirement 11.2)
  if (!data.role?.archetype || data.role.archetype.trim() === '') {
    errors.archetype = ['Character archetype is required'];
  }

  // Validate age range (Requirement 11.3)
  if (!data.visual_identity?.age_range || data.visual_identity.age_range.trim() === '') {
    errors.age_range = ['Character age range is required'];
  }

  // Validate relationship references (Requirement 11.4)
  if (data.relationships && data.relationships.length > 0 && existingCharacters) {
    const invalidRelationships: string[] = [];
    const characterIds = new Set(existingCharacters.map(c => c.character_id));

    // Also include the current character's ID if it exists (for updates)
    if (data.character_id) {
      characterIds.add(data.character_id);
    }

    data.relationships.forEach((rel, index) => {
      if (!characterIds.has(rel.character_id)) {
        invalidRelationships.push(
          `Relationship ${index + 1} references non-existent character: ${rel.character_id}`
        );
      }
    });

    if (invalidRelationships.length > 0) {
      errors.relationships = invalidRelationships;
    }
  }

  return {
    valid: Object.keys(errors).length === 0,
    errors,
  };
}

// ============================================================================
// Character Manager Hook
// ============================================================================

/**
 * Hook providing unified character management operations.
 * 
 * Provides:
 * - CRUD operations with validation
 * - Dependency checking
 * - Relationship management
 * - Search and filter functions
 * - Import/export functions
 * 
 * Requirements: 2.3, 2.5, 7.1, 7.4, 11.1, 11.2, 11.3
 */
export function useCharacterManager() {
  // Store actions
  const addCharacterToStore = useStore((state) => state.addCharacter);
  const updateCharacterInStore = useStore((state) => state.updateCharacter);
  const deleteCharacterFromStore = useStore((state) => state.deleteCharacter);
  const getCharacterFromStore = useStore((state) => state.getCharacterById);
  const getAllCharactersFromStore = useStore((state) => state.getAllCharacters);
  const getAllStories = useStore((state) => state.getAllStories);

  // ============================================================================
  // CRUD Operations
  // ============================================================================

  /**
   * Creates a new character with validation.
   * 
   * Steps:
   * 1. Validates character data (Requirements: 2.3, 11.1, 11.2, 11.3, 11.4)
   * 2. Generates character ID if not provided
   * 3. Adds character to store (Requirement: 2.5)
   * 4. Persists to localStorage (handled by store)
   * 5. Emits character-created event (handled by store)
   * 
   * Requirements: 2.3, 2.5, 11.1, 11.2, 11.3, 11.4
   */
  const createCharacter = useCallback(
    async (data: Partial<Character>): Promise<Character> => {
      try {
        // Get existing characters for relationship validation
        const existingCharacters = getAllCharactersFromStore();

        // Validate character data (Requirement: 2.3)
        const validation = validateCharacter(data, existingCharacters);
        if (!validation.valid) {
          // Log validation failure (Requirement: 2.4)
          logValidationFailure(
            data.character_id || 'new',
            data.name || 'Unnamed Character',
            validation
          );

          // Show validation errors to user (Requirements: 2.4, 11.5)
          showValidationErrors(validation, 'Character Creation');

          // Throw error with validation details
          const errorMessage = Object.entries(validation.errors)
            .map(([field, errors]) => `${field}: ${errors.join(', ')}`)
            .join('; ');
          throw new CharacterError(
            CharacterErrorType.VALIDATION_ERROR,
            `Character validation failed: ${errorMessage}`,
            { validation }
          );
        }

        // Generate character ID if not provided
        const character_id = data.character_id || crypto.randomUUID();

        // Create complete character object with defaults
        const character: Character = {
          character_id,
          name: data.name || '',
          creation_method: data.creation_method || 'manual',
          creation_timestamp: data.creation_timestamp || new Date().toISOString(),
          version: data.version || '1.0',
          visual_identity: {
            hair_color: data.visual_identity?.hair_color || '',
            hair_style: data.visual_identity?.hair_style || '',
            hair_length: data.visual_identity?.hair_length || '',
            eye_color: data.visual_identity?.eye_color || '',
            eye_shape: data.visual_identity?.eye_shape || '',
            skin_tone: data.visual_identity?.skin_tone || '',
            facial_structure: data.visual_identity?.facial_structure || '',
            distinctive_features: data.visual_identity?.distinctive_features || [],
            age_range: data.visual_identity?.age_range || '',
            height: data.visual_identity?.height || '',
            build: data.visual_identity?.build || '',
            posture: data.visual_identity?.posture || '',
            clothing_style: data.visual_identity?.clothing_style || '',
            color_palette: data.visual_identity?.color_palette || [],
            gender: data.visual_identity?.gender || 'neutral',
            reference_images: data.visual_identity?.reference_images || [],
            reference_sheet_images: data.visual_identity?.reference_sheet_images || [],
          },
          personality: {
            traits: data.personality?.traits || [],
            values: data.personality?.values || [],
            fears: data.personality?.fears || [],
            desires: data.personality?.desires || [],
            flaws: data.personality?.flaws || [],
            strengths: data.personality?.strengths || [],
            temperament: data.personality?.temperament || '',
            communication_style: data.personality?.communication_style || '',
          },
          background: {
            origin: data.background?.origin || '',
            occupation: data.background?.occupation || '',
            education: data.background?.education || '',
            family: data.background?.family || '',
            significant_events: data.background?.significant_events || [],
            current_situation: data.background?.current_situation || '',
          },
          relationships: data.relationships || [],
          role: {
            archetype: data.role?.archetype || '',
            narrative_function: data.role?.narrative_function || '',
            character_arc: data.role?.character_arc || '',
          },
        };

        // Add to store (Requirement: 2.5)
        // Store handles persistence to localStorage and event emission
        addCharacterToStore(character);

        // Also update the project in AppStore to ensure persistence
        const appStore = useAppStore.getState();
        const currentProject = appStore.project;
        if (currentProject) {
          const projectCharacters = currentProject.characters || [];
          appStore.setProject({
            ...currentProject,
            characters: [...projectCharacters, character]
          });
        }

        return character;
      } catch (error) {
        // Handle and display error
        handleCharacterError(error, 'Character Creation');
        throw error;
      }
    },
    [addCharacterToStore, getAllCharactersFromStore]
  );

  /**
   * Updates an existing character with validation.
   * 
   * Steps:
   * 1. Validates that character exists
   * 2. Validates updated data (Requirements: 2.3, 11.1, 11.2, 11.3, 11.4)
   * 3. Updates character in store (Requirement: 2.5)
   * 4. Persists to localStorage (handled by store)
   * 5. Emits character-updated event (handled by store)
   * 
   * Requirements: 2.3, 2.5, 11.1, 11.2, 11.3, 11.4
   */
  const updateCharacter = useCallback(
    async (id: string, updates: Partial<Character>): Promise<Character> => {
      try {
        // Check if character exists
        const existingCharacter = getCharacterFromStore(id);
        if (!existingCharacter) {
          throw new CharacterError(
            CharacterErrorType.NOT_FOUND,
            `Character with ID "${id}" not found`,
            { characterId: id }
          );
        }

        // Merge updates with existing character for validation
        const updatedData = {
          ...existingCharacter,
          ...updates,
        };

        // Get existing characters for relationship validation
        const existingCharacters = getAllCharactersFromStore();

        // Validate updated character data (Requirement: 2.3)
        const validation = validateCharacter(updatedData, existingCharacters);
        if (!validation.valid) {
          // Log validation failure (Requirement: 2.4)
          logValidationFailure(id, existingCharacter.name, validation);

          // Show validation errors to user (Requirements: 2.4, 11.5)
          showValidationErrors(validation, 'Character Update');

          // Throw error with validation details
          const errorMessage = Object.entries(validation.errors)
            .map(([field, errors]) => `${field}: ${errors.join(', ')}`)
            .join('; ');
          throw new CharacterError(
            CharacterErrorType.VALIDATION_ERROR,
            `Character validation failed: ${errorMessage}`,
            { validation }
          );
        }

        // Update in store (Requirement: 2.5)
        // Store handles persistence to localStorage and event emission
        updateCharacterInStore(id, updates);

        // Also update the project in AppStore to ensure persistence
        const appStore = useAppStore.getState();
        const currentProject = appStore.project;
        if (currentProject) {
          const projectCharacters = currentProject.characters || [];
          const updatedCharacters = projectCharacters.map((c) =>
            c.character_id === id ? { ...c, ...updates } : c
          );
          appStore.setProject({
            ...currentProject,
            characters: updatedCharacters
          });
        }

        // Get updated character
        const updatedCharacter = getCharacterFromStore(id);
        if (!updatedCharacter) {
          throw new CharacterError(
            CharacterErrorType.NOT_FOUND,
            `Failed to retrieve updated character with ID "${id}"`,
            { characterId: id }
          );
        }

        return updatedCharacter;
      } catch (error) {
        // Handle and display error
        handleCharacterError(error, 'Character Update');
        throw error;
      }
    },
    [getCharacterFromStore, updateCharacterInStore, getAllCharactersFromStore]
  );

  // ============================================================================
  // Dependency Checking
  // ============================================================================

  /**
   * Checks dependencies for a character (stories and relationships).
   * 
   * Requirements: 7.1
   */
  const checkDependencies = useCallback(
    (characterId: string): CharacterDependencies => {
      const character = getCharacterFromStore(characterId);
      if (!character) {
        return { stories: [], relationships: [] };
      }

      // Find stories that use this character
      const allStories = getAllStories();
      const storiesUsingCharacter = allStories.filter((story) =>
        (story.charactersUsed || []).some((charRef) => charRef.id === characterId)
      );

      // Find characters that have relationships with this character
      const allCharacters = getAllCharactersFromStore();
      const charactersWithRelationships = allCharacters.filter((otherCharacter) =>
        otherCharacter.character_id !== characterId &&
        otherCharacter.relationships.some((rel) => rel.character_id === characterId)
      );

      return {
        stories: storiesUsingCharacter,
        relationships: charactersWithRelationships,
      };
    },
    [getCharacterFromStore, getAllStories, getAllCharactersFromStore]
  );

  /**
   * Deletes a character with dependency checking.
   * 
   * Steps:
   * 1. Checks for dependencies (stories, relationships) (Requirement: 7.1)
   * 2. If dependencies exist and force=false, throws error
   * 3. If removeFromStories=true, removes character from stories
   * 4. Removes character from store (Requirement: 7.4)
   * 5. Removes from localStorage (handled by store)
   * 6. Emits character-deleted event (handled by store)
   * 
   * Requirements: 7.1, 7.4
   */
  const deleteCharacter = useCallback(
    async (id: string, options: DeleteOptions = {}): Promise<void> => {
      try {
        const { force = false, removeFromStories = false } = options;

        // Check if character exists
        const character = getCharacterFromStore(id);
        if (!character) {
          throw new CharacterError(
            CharacterErrorType.NOT_FOUND,
            `Character with ID "${id}" not found`,
            { characterId: id }
          );
        }

        // Check dependencies (Requirement: 7.1)
        if (!force) {
          const dependencies = checkDependencies(id);

          if (dependencies.stories.length > 0 && !removeFromStories) {
            const storyNames = dependencies.stories.map((s) => s.title).join(', ');
            throw new CharacterError(
              CharacterErrorType.DEPENDENCY_ERROR,
              `Cannot delete character "${character.name}". ` +
              `Character is used in the following stories: ${storyNames}. ` +
              `Use force=true or removeFromStories=true to proceed.`,
              { dependencies }
            );
          }

          if (dependencies.relationships.length > 0) {
            const relationshipNames = dependencies.relationships.map((c) => c.name).join(', ');
            console.warn(
              `Character "${character.name}" has relationships with: ${relationshipNames}. ` +
              `These relationships will be removed.`
            );
          }
        }

        // Remove from stories if requested
        if (removeFromStories) {
          const dependencies = checkDependencies(id);
          dependencies.stories.forEach((story) => {
            // Remove character from story's charactersUsed array
            const updatedCharactersUsed = (story.charactersUsed || []).filter(
              (charRef) => charRef.id !== id
            );
            // Note: This would require a updateStory action in the store
            // For now, we'll just log a warning
            console.warn(
              `Character "${character.name}" should be removed from story "${story.title}". ` +
              `Story update functionality needs to be implemented.`
            );
          });
        }

        // Remove relationships with other characters
        const allCharacters = getAllCharactersFromStore();
        allCharacters.forEach((otherCharacter) => {
          if (otherCharacter.character_id === id) return;

          // Check if this character has a relationship with the character being deleted
          const hasRelationship = otherCharacter.relationships.some(
            (rel) => rel.character_id === id
          );

          if (hasRelationship) {
            // Remove the relationship
            const updatedRelationships = otherCharacter.relationships.filter(
              (rel) => rel.character_id !== id
            );
            updateCharacterInStore(otherCharacter.character_id, {
              relationships: updatedRelationships,
            });
          }
        });

        // Delete from store (Requirement: 7.4)
        // Store handles removal from localStorage and event emission
        deleteCharacterFromStore(id);

        // Also update the project in AppStore to ensure persistence
        const appStore = useAppStore.getState();
        const currentProject = appStore.project;
        if (currentProject) {
          const projectCharacters = currentProject.characters || [];
          const updatedCharacters = projectCharacters.filter((c) => c.character_id !== id);
          appStore.setProject({
            ...currentProject,
            characters: updatedCharacters
          });
        }
      } catch (error) {
        // Handle and display error
        handleCharacterError(error, 'Character Deletion');
        throw error;
      }
    },
    [getCharacterFromStore, getAllCharactersFromStore, updateCharacterInStore, deleteCharacterFromStore, checkDependencies]
  );

  /**
   * Gets a character by ID.
   * 
   * Requirements: 2.5
   */
  const getCharacter = useCallback(
    (id: string): Character | undefined => {
      return getCharacterFromStore(id);
    },
    [getCharacterFromStore]
  );

  /**
   * Gets all characters.
   * 
   * Requirements: 2.5
   */
  const getAllCharacters = useCallback((): Character[] => {
    return getAllCharactersFromStore();
  }, [getAllCharactersFromStore]);

  // ============================================================================
  // Relationship Management
  // ============================================================================

  /**
   * Adds a bidirectional relationship between two characters.
   * 
   * Uses RelationshipManager to ensure bidirectional sync.
   * 
   * Requirements: 6.1, 6.4
   */
  const addRelationship = useCallback(
    async (
      fromCharacterId: string,
      toCharacterId: string,
      relationshipData: RelationshipData
    ): Promise<void> => {
      try {
        // Create store adapter for RelationshipManager
        const storeAdapter: CharacterStore = {
          getCharacter: getCharacterFromStore,
          updateCharacter: updateCharacterInStore,
          getAllCharacters: getAllCharactersFromStore,
        };

        // Create event emitter adapter
        const eventEmitterAdapter: CharacterEventEmitter = {
          emit: (eventType: string, payload: unknown) => {
            eventEmitter.emit(eventType as any, payload as any);
          },
        };

        // Use RelationshipManager to add relationship
        const result = addRelationshipToStore(
          storeAdapter,
          eventEmitterAdapter,
          fromCharacterId,
          toCharacterId,
          relationshipData
        );

        if (!result.success) {
          // Handle specific relationship errors (Requirement: 6.4)
          if (result.error?.includes('circular dependency')) {
            throw new CharacterError(
              CharacterErrorType.RELATIONSHIP_ERROR,
              result.error,
              { fromCharacterId, toCharacterId, relationshipData }
            );
          }
          throw new CharacterError(
            CharacterErrorType.RELATIONSHIP_ERROR,
            result.error || 'Failed to add relationship',
            { fromCharacterId, toCharacterId, relationshipData }
          );
        }
      } catch (error) {
        // Handle and display error
        handleCharacterError(error, 'Add Relationship');
        throw error;
      }
    },
    [getCharacterFromStore, updateCharacterInStore, getAllCharactersFromStore]
  );

  /**
   * Updates a bidirectional relationship between two characters.
   * 
   * Uses RelationshipManager to ensure bidirectional sync.
   * 
   * Requirements: 6.2
   */
  const updateRelationship = useCallback(
    async (
      fromCharacterId: string,
      toCharacterId: string,
      updates: Partial<RelationshipData>
    ): Promise<void> => {
      try {
        // Create store adapter for RelationshipManager
        const storeAdapter: CharacterStore = {
          getCharacter: getCharacterFromStore,
          updateCharacter: updateCharacterInStore,
          getAllCharacters: getAllCharactersFromStore,
        };

        // Create event emitter adapter
        const eventEmitterAdapter: CharacterEventEmitter = {
          emit: (eventType: string, payload: unknown) => {
            eventEmitter.emit(eventType as any, payload as any);
          },
        };

        // Use RelationshipManager to update relationship
        const result = updateRelationshipInStore(
          storeAdapter,
          eventEmitterAdapter,
          fromCharacterId,
          toCharacterId,
          updates
        );

        if (!result.success) {
          throw new CharacterError(
            CharacterErrorType.RELATIONSHIP_ERROR,
            result.error || 'Failed to update relationship',
            { fromCharacterId, toCharacterId, updates }
          );
        }
      } catch (error) {
        // Handle and display error
        handleCharacterError(error, 'Update Relationship');
        throw error;
      }
    },
    [getCharacterFromStore, updateCharacterInStore, getAllCharactersFromStore]
  );

  /**
   * Removes a bidirectional relationship between two characters.
   * 
   * Uses RelationshipManager to ensure bidirectional sync.
   * 
   * Requirements: 6.3
   */
  const removeRelationship = useCallback(
    async (fromCharacterId: string, toCharacterId: string): Promise<void> => {
      try {
        // Create store adapter for RelationshipManager
        const storeAdapter: CharacterStore = {
          getCharacter: getCharacterFromStore,
          updateCharacter: updateCharacterInStore,
          getAllCharacters: getAllCharactersFromStore,
        };

        // Create event emitter adapter
        const eventEmitterAdapter: CharacterEventEmitter = {
          emit: (eventType: string, payload: unknown) => {
            eventEmitter.emit(eventType as any, payload as any);
          },
        };

        // Use RelationshipManager to remove relationship
        const result = removeRelationshipFromStore(
          storeAdapter,
          eventEmitterAdapter,
          fromCharacterId,
          toCharacterId
        );

        if (!result.success) {
          throw new CharacterError(
            CharacterErrorType.RELATIONSHIP_ERROR,
            result.error || 'Failed to remove relationship',
            { fromCharacterId, toCharacterId }
          );
        }
      } catch (error) {
        // Handle and display error
        handleCharacterError(error, 'Remove Relationship');
        throw error;
      }
    },
    [getCharacterFromStore, updateCharacterInStore, getAllCharactersFromStore]
  );

  // ============================================================================
  // Search and Filter Functions
  // ============================================================================

  /**
   * Searches characters by name, archetype, or traits (case-insensitive).
   * 
   * Requirements: 4.4, 9.2
   */
  const searchCharacters = useCallback(
    (query: string): Character[] => {
      if (!query || query.trim() === '') {
        return getAllCharactersFromStore();
      }

      const normalizedQuery = query.toLowerCase().trim();
      const allCharacters = getAllCharactersFromStore();

      return allCharacters.filter((character) => {
        // Search in name
        const matchesName = character.name.toLowerCase().includes(normalizedQuery);

        // Search in archetype
        const matchesArchetype = character.role.archetype.toLowerCase().includes(normalizedQuery);

        // Search in traits
        const matchesTraits = character.personality.traits.some((trait) =>
          trait.toLowerCase().includes(normalizedQuery)
        );

        return matchesName || matchesArchetype || matchesTraits;
      });
    },
    [getAllCharactersFromStore]
  );

  /**
   * Filters characters by multiple criteria.
   * 
   * Requirements: 9.3, 9.4
   */
  const filterCharacters = useCallback(
    (filters: {
      archetype?: string[];
      ageRange?: string[];
      creationMethod?: ('wizard' | 'auto_generated' | 'manual')[];
    }): Character[] => {
      const allCharacters = getAllCharactersFromStore();

      return allCharacters.filter((character) => {
        // Filter by archetype
        if (filters.archetype && filters.archetype.length > 0) {
          const matchesArchetype = filters.archetype.some(
            (archetype) => character.role.archetype.toLowerCase() === archetype.toLowerCase()
          );
          if (!matchesArchetype) return false;
        }

        // Filter by age range
        if (filters.ageRange && filters.ageRange.length > 0) {
          const matchesAgeRange = filters.ageRange.some(
            (ageRange) => character.visual_identity.age_range.toLowerCase() === ageRange.toLowerCase()
          );
          if (!matchesAgeRange) return false;
        }

        // Filter by creation method
        if (filters.creationMethod && filters.creationMethod.length > 0) {
          const matchesCreationMethod = filters.creationMethod.includes(character.creation_method);
          if (!matchesCreationMethod) return false;
        }

        return true;
      });
    },
    [getAllCharactersFromStore]
  );

  // ============================================================================
  // Import/Export Functions
  // ============================================================================

  /**
   * Exports a character as JSON string.
   * 
   * Requirements: 10.2
   */
  const exportCharacter = useCallback(
    async (id: string): Promise<string> => {
      const character = getCharacterFromStore(id);
      if (!character) {
        throw new Error(`Character with ID "${id}" not found`);
      }

      // Serialize character to JSON with pretty formatting
      return JSON.stringify(character, null, 2);
    },
    [getCharacterFromStore]
  );

  /**
   * Imports a character from JSON string.
   * 
   * Steps:
   * 1. Validates JSON format (Requirement: 10.4)
   * 2. Validates character schema (Requirement: 10.4)
   * 3. Checks for ID conflicts (Requirement: 10.5)
   * 4. Creates character in store
   * 
   * Requirements: 10.2, 10.4, 10.5
   */
  const importCharacter = useCallback(
    async (jsonData: string): Promise<Character> => {
      try {
        // Parse JSON (Requirement: 10.4)
        let parsedData: unknown;
        try {
          parsedData = JSON.parse(jsonData);
        } catch (error) {
          throw new CharacterError(
            CharacterErrorType.VALIDATION_ERROR,
            'Invalid JSON format: ' + (error as Error).message,
            { originalError: error }
          );
        }

        // Validate character schema (Requirement: 10.4)
        const validation = validateCharacter(parsedData, getAllCharactersFromStore());
        if (!validation.valid) {
          // Show validation errors to user
          showValidationErrors(validation, 'Character Import');

          const errorMessage = Object.entries(validation.errors)
            .map(([field, errors]) => `${field}: ${errors.join(', ')}`)
            .join('; ');
          throw new CharacterError(
            CharacterErrorType.VALIDATION_ERROR,
            `Character validation failed: ${errorMessage}`,
            { validation }
          );
        }

        // Check for ID conflicts (Requirement: 10.5)
        const id = (parsedData as any).character_id;
        const existingCharacter = getCharacterFromStore(id);
        if (existingCharacter) {
          throw new CharacterError(
            CharacterErrorType.DUPLICATE_ID,
            `Character with ID "${id}" already exists. ` +
            `Please rename or delete the existing character before importing.`,
            { existingCharacter, importedCharacter: parsedData }
          );
        }

        // Create character
        return await createCharacter(parsedData);
      } catch (error) {
        // Handle and display error
        handleCharacterError(error, 'Character Import');
        throw error;
      }
    },
    [getCharacterFromStore, getAllCharactersFromStore, createCharacter]
  );

  // ============================================================================
  // Return Hook API
  // ============================================================================

  return {
    // CRUD operations
    createCharacter,
    updateCharacter,
    deleteCharacter,
    getCharacter,
    getAllCharacters,

    // Search and filter
    searchCharacters,
    filterCharacters,

    // Validation
    validateCharacter,

    // Dependency checking
    checkDependencies,

    // Relationship management
    addRelationship,
    updateRelationship,
    removeRelationship,

    // Import/export
    exportCharacter,
    importCharacter,
  };
}

// ============================================================================
// Character Persistence Hook
// ============================================================================
// Handles saving and loading characters to/from localStorage and JSON files
// Integrates with Zustand store for state management
// Implements schema validation, conflict resolution, and error handling
//
// Requirements: 8.1, 8.2, 8.3, 8.4, 8.5
// ============================================================================

import { useCallback } from 'react';
import { useStore } from '../store';
import { useEditorStore } from '../stores/editorStore';
import type { Character } from '../types/character';
import { toast } from '../utils/toast';

// ============================================================================
// Types
// ============================================================================

/**
 * Persistence error types for better error handling
 */
export const PersistenceErrorType = {
  VALIDATION_ERROR: 'VALIDATION_ERROR',
  STORAGE_QUOTA_EXCEEDED: 'STORAGE_QUOTA_EXCEEDED',
  FILE_SYSTEM_ERROR: 'FILE_SYSTEM_ERROR',
  CORRUPTED_DATA: 'CORRUPTED_DATA',
  CONFLICT_ERROR: 'CONFLICT_ERROR',
} as const;

export type PersistenceErrorType = typeof PersistenceErrorType[keyof typeof PersistenceErrorType];

/**
 * Persistence error with detailed information
 */
export class PersistenceError extends Error {
  public type: PersistenceErrorType;
  public details?: unknown;
  constructor(
    type: PersistenceErrorType,
    message: string,
    details?: unknown
  ) {
    super(message);
    this.type = type;
    this.details = details;
    this.name = 'PersistenceError';
  }
}

/**
 * Character with persistence metadata
 */
export interface PersistedCharacter extends Character {
  last_modified?: number; // timestamp in ms
  thumbnail_url?: string;
  tags?: string[];
  notes?: string;
  version_number?: number; // For concurrent modification detection
}

/**
 * Retry configuration
 */
export interface RetryConfig {
  maxAttempts: number;
  delayMs: number;
  backoffMultiplier: number;
}

/**
 * Conflict resolution result
 */
export interface ConflictResolution {
  hasConflict: boolean;
  localCharacter?: PersistedCharacter;
  remoteCharacter?: PersistedCharacter;
  resolvedCharacter?: PersistedCharacter;
}

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Generate UUID
 */
function generateUUID(): string {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  // Fallback UUID generation
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

/**
 * Retry a function with exponential backoff
 * Requirements: 8.2
 */
async function _retryWithBackoff<T>(
  fn: () => Promise<T>,
  config: RetryConfig = {
    maxAttempts: 3,
    delayMs: 1000,
    backoffMultiplier: 2,
  }
): Promise<T> {
  let lastError: Error | null = null;

  for (let attempt = 1; attempt <= config.maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error as Error;

      if (attempt < config.maxAttempts) {
        const delay = config.delayMs * Math.pow(config.backoffMultiplier, attempt - 1);
        console.warn(`Attempt ${attempt} failed, retrying in ${delay}ms...`, error);
        await new Promise((resolve) => setTimeout(resolve, delay));
      }
    }
  }

  throw lastError || new Error('Retry failed');
}

/**
 * Handle localStorage quota exceeded error
 * Requirements: 8.1
 */
function handleQuotaExceeded(): void {
  toast.error(
    'Storage Quota Exceeded',
    'Your browser storage is full. Please export some characters to free up space, or clear old data.',
    10000
  );

  // Log storage usage for debugging
  if (typeof navigator !== 'undefined' && 'storage' in navigator && 'estimate' in navigator.storage) {
    navigator.storage.estimate().then((estimate) => {
      console.error('Storage quota exceeded:', {
        usage: estimate.usage,
        quota: estimate.quota,
        percentUsed: estimate.quota ? ((estimate.usage || 0) / estimate.quota * 100).toFixed(2) + '%' : 'unknown',
      });
    });
  }
}

/**
 * Handle file system errors
 * Requirements: 8.2
 */
function handleFileSystemError(error: Error, operation: string): void {
  console.error(`File system ${operation} error:`, error);

  toast.warning(
    'File System Error',
    `Failed to ${operation} character file. Data is saved in browser storage only.`,
    7000
  );
}

/**
 * Detect concurrent modifications by comparing version numbers
 * Requirements: 2.5
 */
function _detectConcurrentModification(
  localChar: PersistedCharacter,
  remoteChar: PersistedCharacter
): boolean {
  // If both have version numbers, compare them
  if (localChar.version_number !== undefined && remoteChar.version_number !== undefined) {
    return localChar.version_number !== remoteChar.version_number;
  }

  // If version numbers are not available, compare timestamps
  const localTime = new Date(localChar.last_modified || localChar.creation_timestamp).getTime();
  const remoteTime = new Date(remoteChar.last_modified || remoteChar.creation_timestamp).getTime();

  // If timestamps are very close (within 1 second), consider it a concurrent modification
  const timeDiff = Math.abs(localTime - remoteTime);
  return timeDiff < 1000 && localTime !== remoteTime;
}

/**
 * Validates character data against schema
 * Requirements: 8.3
 */
function validateCharacterSchema(data: unknown): { valid: boolean; errors: string[] } {
  const errors: string[] = [];
  const d = data as Record<string, unknown>;

  // Check required fields
  if (!d.character_id || typeof d.character_id !== 'string') {
    errors.push('character_id is required and must be a string');
  }
  if (!d.name || typeof d.name !== 'string') {
    errors.push('name is required and must be a string');
  }
  if (!d.creation_method || !['wizard', 'auto_generated', 'manual'].includes(d.creation_method as string)) {
    errors.push('creation_method must be one of: wizard, auto_generated, manual');
  }
  if (!d.creation_timestamp || (typeof d.creation_timestamp !== 'string' && typeof d.creation_timestamp !== 'number')) {
    errors.push('creation_timestamp is required and must be a string or number');
  }
  if (!d.version || typeof d.version !== 'string') {
    errors.push('version is required and must be a string');
  }

  // Check nested objects
  if (!d.visual_identity || typeof d.visual_identity !== 'object') {
    errors.push('visual_identity is required and must be an object');
  }
  if (!d.personality || typeof d.personality !== 'object') {
    errors.push('personality is required and must be an object');
  }
  if (!d.background || typeof d.background !== 'object') {
    errors.push('background is required and must be an object');
  }
  if (!d.role || typeof d.role !== 'object') {
    errors.push('role is required and must be an object');
  }
  if (!Array.isArray(d.relationships)) {
    errors.push('relationships must be an array');
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

/**
 * Resolves conflicts between two character versions by timestamp
 * Requirements: 8.5
 */
function _resolveConflictByTimestamp(
  localChar: PersistedCharacter,
  remoteChar: PersistedCharacter
): PersistedCharacter {
  const localTime = new Date(localChar.last_modified || localChar.creation_timestamp).getTime();
  const remoteTime = new Date(remoteChar.last_modified || remoteChar.creation_timestamp).getTime();

  // Return the most recent version
  return localTime > remoteTime ? localChar : remoteChar;
}

// ============================================================================
// Character Persistence Hook
// ============================================================================

export function useCharacterPersistence() {
  // ============================================================================
  // Store Selectors - All hooks at top level
  // ============================================================================
  const addCharacter = useStore((state) => state.addCharacter);
  const updateCharacter = useStore((state) => state.updateCharacter);
  const deleteCharacter = useStore((state) => state.deleteCharacter);
  const getAllCharacters = useStore((state) => state.getAllCharacters);
  const setCharacters = useStore((state) => state.setCharacters);

  // ============================================================================
  // File System Operations - All useCallback hooks at top level
  // ============================================================================

  /**
   * Save character to JSON file via File System Access API
   * Requirements: 8.2, 8.3
   */
  const saveToFile = useCallback(
    async (character: PersistedCharacter): Promise<void> => {
      try {
        // Validate schema before saving (Requirement: 8.3)
        const validation = validateCharacterSchema(character);
        if (!validation.valid) {
          throw new PersistenceError(
            PersistenceErrorType.VALIDATION_ERROR,
            `Schema validation failed: ${validation.errors.join(', ')}`,
            { errors: validation.errors }
          );
        }

        // Use File System Access API if available
        if ('showSaveFilePicker' in window) {
          const options = {
            suggestedName: `${character.name.replace(/[^a-z0-9]/gi, '_').toLowerCase()}_character.json`,
            types: [
              {
                description: 'JSON Files',
                accept: { 'application/json': ['.json'] },
              },
            ],
          };

          const fileHandle = await (window as unknown as Record<string, (o: unknown) => Promise<{ createWritable: () => Promise<{ write: (d: string) => Promise<void>; close: () => Promise<void> }> }>>)['showSaveFilePicker'](options);
          const writable = await fileHandle.createWritable();
          await writable.write(JSON.stringify(character, null, 2));
          await writable.close();
        } else {
          // Fallback: download file via anchor element
          const blob = new Blob([JSON.stringify(character, null, 2)], { type: 'application/json' });
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `${character.name.replace(/[^a-z0-9]/gi, '_').toLowerCase()}_character.json`;
          document.body.appendChild(a);
          a.click();
          document.body.removeChild(a);
          URL.revokeObjectURL(url);
        }
      } catch (error) {
        // Check if user cancelled the save dialog - don't treat as error
        if ((error as Error).name === 'AbortError') {
          console.log('User cancelled file save');
          return;
        }

        // Log error and show user-friendly message (Requirement: 8.2)
        handleFileSystemError(error as Error, 'save');
        throw new PersistenceError(
          PersistenceErrorType.FILE_SYSTEM_ERROR,
          'Failed to save character to file system',
          { originalError: error }
        );
      }
    },
    []
  );

  /**
   * Save character directly to project directory via Electron API
   * This saves automatically without showing a file picker dialog
   * Requirements: 8.2, 8.3
   */
  const saveToProjectDirectory = useCallback(
    async (character: PersistedCharacter, projectPath: string): Promise<void> => {
      try {
        // Validate schema before saving (Requirement: 8.3)
        const validation = validateCharacterSchema(character);
        if (!validation.valid) {
          throw new PersistenceError(
            PersistenceErrorType.VALIDATION_ERROR,
            `Schema validation failed: ${validation.errors.join(', ')}`,
            { errors: validation.errors }
          );
        }

        // Check if we're running in Electron environment
        if (window.electronAPI?.fs?.writeFile) {
          const charactersDir = `${projectPath}/characters`;
          const fileName = `character_${character.character_id}.json`;
          const filePath = `${charactersDir}/${fileName}`;

          // Ensure the characters directory exists
          if (window.electronAPI.fs.mkdir) {
            await window.electronAPI.fs.mkdir(charactersDir, { recursive: true });
          }

          const jsonData = JSON.stringify(character, null, 2);

          // Convert string to Uint8Array for browser compatibility
          const encoder = new TextEncoder();
          const dataBuffer = encoder.encode(jsonData);

          // Convert Uint8Array to string for writeFile (Node.js style)
          const dataString = new TextDecoder().decode(dataBuffer);
          await window.electronAPI.fs.writeFile(filePath, dataString);
          console.log(`[useCharacterPersistence] Character saved to: ${filePath}`);
        } else {
          // Fallback: use the file picker method
          console.warn('[useCharacterPersistence] Electron API not available, falling back to file picker');
          await saveToFile(character);
        }
      } catch (error) {
        console.error('[useCharacterPersistence] Failed to save character to project directory:', error);
        handleFileSystemError(error as Error, 'save');
        throw new PersistenceError(
          PersistenceErrorType.FILE_SYSTEM_ERROR,
          'Failed to save character to project directory',
          { originalError: error }
        );
      }
    },
    []
  );

  /**
   * Load all characters from project directory
   * Requirements: 8.2, 8.4
   */
  const loadCharactersFromProjectDirectory = useCallback(
    async (projectPath: string): Promise<PersistedCharacter[]> => {
      const characters: PersistedCharacter[] = [];

      try {
        // Check if we're running in Electron environment
        if (window.electronAPI?.fs?.readdir) {
          const charactersDir = `${projectPath}/characters`;

          // Check if directory exists
          try {
            const files = await window.electronAPI.fs.readdir(charactersDir);

            for (const file of files) {
              if (file.endsWith('.json') && file.startsWith('character_')) {
                try {
                  const filePath = `${charactersDir}/${file}`;
                  const buffer = await window.electronAPI.fs.readFile(filePath);
                  const content = new TextDecoder().decode(buffer);
                  const character = JSON.parse(content);

                  // Validate loaded data
                  const validation = validateCharacterSchema(character);
                  if (validation.valid) {
                    characters.push(character);
                  } else {
                    console.warn(`[useCharacterPersistence] Invalid character file: ${file}`, validation.errors);
                  }
                } catch (fileError) {
                  console.warn(`[useCharacterPersistence] Failed to load character file: ${file}`, fileError);
                }
              }
            }
          } catch (_dirError) {
            // Directory doesn't exist yet, return empty array
            console.log('[useCharacterPersistence] Characters directory does not exist yet');
          }
        } else {
          console.warn('[useCharacterPersistence] Electron API not available for loading characters from directory');
        }
      } catch (error) {
        console.error('[useCharacterPersistence] Failed to load characters from project directory:', error);
      }

      return characters;
    },
    []
  );



  // ============================================================================
  // LocalStorage Operations - All useCallback hooks at top level
  // ============================================================================

  /**
   * Save character to localStorage
   * Requirements: 8.1
   */
  const saveToLocalStorage = useCallback(
    (character: PersistedCharacter): void => {
      try {
        // Save individual character
        localStorage.setItem(
          `character-${character.character_id}`,
          JSON.stringify(character)
        );

        // Update master list
        const allCharacterIds = JSON.parse(
          localStorage.getItem('character-ids') || '[]'
        ) as string[];

        if (!allCharacterIds.includes(character.character_id)) {
          allCharacterIds.push(character.character_id);
          localStorage.setItem('character-ids', JSON.stringify(allCharacterIds));
        }
      } catch (error) {
        if (error instanceof DOMException && error.name === 'QuotaExceededError') {
          // Handle quota exceeded (Requirement: 8.1)
          handleQuotaExceeded();
          throw new PersistenceError(
            PersistenceErrorType.STORAGE_QUOTA_EXCEEDED,
            'localStorage quota exceeded. Please export some characters to free up space.',
            { originalError: error }
          );
        }
        throw error;
      }
    },
    []
  );

  /**
   * Load character from localStorage
   * Requirements: 8.1
   */
  const loadFromLocalStorage = useCallback(
    (character_id: string): PersistedCharacter | null => {
      try {
        const stored = localStorage.getItem(`character-${character_id}`);
        if (!stored) {
          return null;
        }

        const character = JSON.parse(stored);

        // Validate loaded data
        const validation = validateCharacterSchema(character);
        if (!validation.valid) {
          console.error(`Corrupted character data in localStorage: ${character_id}`, validation.errors);
          throw new PersistenceError(
            PersistenceErrorType.CORRUPTED_DATA,
            `Character data is corrupted: ${validation.errors.join(', ')}`,
            { characterId: character_id, errors: validation.errors }
          );
        }

        return character;
      } catch (error) {
        if (error instanceof PersistenceError) {
          throw error;
        }
        console.error('Failed to parse character from localStorage:', error);
        throw new PersistenceError(
          PersistenceErrorType.CORRUPTED_DATA,
          'Failed to parse character data',
          { characterId: character_id, originalError: error }
        );
      }
    },
    []
  );

  // ============================================================================
  // Main Persistence Operations - All useCallback hooks at top level
  // ============================================================================

  /**
   * Save a character with dual persistence and conflict resolution
   * Automatically saves to project directory if available
   * Requirements: 8.1, 8.2, 8.3, 8.5
   */
  const saveCharacter = useCallback(
    async (characterData: Partial<Character>): Promise<Character> => {
      // Get project path from editor store
      const projectPath = useEditorStore.getState().projectPath;

      // Generate UUID if not provided
      const character_id = characterData.character_id || generateUUID();

      // Add persistence metadata
      const existingChar = loadFromLocalStorage(character_id);
      const currentVersionNumber = (existingChar as PersistedCharacter)?.version_number || 0;

      const character: PersistedCharacter = {
        character_id,
        name: characterData.name || '',
        creation_method: characterData.creation_method || 'wizard',
        creation_timestamp: characterData.creation_timestamp || Date.now(),
        version: characterData.version || '1.0',
        last_modified: Date.now(), // Add modification timestamp
        version_number: currentVersionNumber + 1, // Increment version for concurrent modification detection
        visual_identity: {
          hair_color: characterData.visual_identity?.hair_color || '',
          hair_style: characterData.visual_identity?.hair_style || '',
          hair_length: characterData.visual_identity?.hair_length || '',
          eye_color: characterData.visual_identity?.eye_color || '',
          eye_shape: characterData.visual_identity?.eye_shape || '',
          skin_tone: characterData.visual_identity?.skin_tone || '',
          facial_structure: characterData.visual_identity?.facial_structure || '',
          distinctive_features: characterData.visual_identity?.distinctive_features || [],
          age_range: characterData.visual_identity?.age_range || '',
          gender: characterData.visual_identity?.gender || 'neutral',
          height: characterData.visual_identity?.height || '',
          build: characterData.visual_identity?.build || '',
          posture: characterData.visual_identity?.posture || '',
          clothing_style: characterData.visual_identity?.clothing_style || '',
          color_palette: characterData.visual_identity?.color_palette || [],
          reference_images: characterData.visual_identity?.reference_images || [],
          reference_sheet_images: characterData.visual_identity?.reference_sheet_images || [],
        },
        personality: {
          traits: characterData.personality?.traits || [],
          values: characterData.personality?.values || [],
          fears: characterData.personality?.fears || [],
          desires: characterData.personality?.desires || [],
          flaws: characterData.personality?.flaws || [],
          strengths: characterData.personality?.strengths || [],
          temperament: characterData.personality?.temperament || '',
          communication_style: characterData.personality?.communication_style || '',
        },
        background: {
          origin: characterData.background?.origin || '',
          occupation: characterData.background?.occupation || '',
          education: characterData.background?.education || '',
          family: characterData.background?.family || '',
          significant_events: characterData.background?.significant_events || [],
          current_situation: characterData.background?.current_situation || '',
        },
        relationships: characterData.relationships || [],
        role: {
          archetype: characterData.role?.archetype || '',
          narrative_function: characterData.role?.narrative_function || '',
          character_arc: characterData.role?.character_arc || '',
        },
        prompts: characterData.prompts || [],
        // Optional metadata
        thumbnail_url: (characterData as PersistedCharacter).thumbnail_url,
        tags: (characterData as PersistedCharacter).tags,
        notes: (characterData as PersistedCharacter).notes,
      };

      // Update store first
      const existingCharacters = getAllCharacters();
      const characterIndex = existingCharacters.findIndex(
        (c) => c.character_id === character_id
      );

      if (characterIndex >= 0) {
        updateCharacter(character_id, character);
      } else {
        addCharacter(character);
      }

      // Save to localStorage (Requirement: 8.1)
      try {
        saveToLocalStorage(character);
      } catch (error) {
        if (error instanceof PersistenceError &&
          error.type === PersistenceErrorType.STORAGE_QUOTA_EXCEEDED) {
          // Try to save to file system as fallback
          console.warn('localStorage quota exceeded, attempting file system save');
          await saveToFile(character);
        } else {
          throw error;
        }
      }

      // Save to project directory if projectPath is available (Requirement: 8.2)
      if (projectPath) {
        try {
          await saveToProjectDirectory(character, projectPath);
          console.log(`[useCharacterPersistence] Character saved to project directory: ${projectPath}`);
        } catch (error) {
          console.warn('[useCharacterPersistence] Project directory save failed, falling back to file picker:', error);
          // Fallback to file picker if project directory save fails
          try {
            await saveToFile(character);
          } catch (fileError) {
            console.warn('File picker save also failed:', fileError);
          }
        }
      } else {
        // No project path, use file picker
        console.log('[useCharacterPersistence] No project path available, using file picker');
        try {
          await saveToFile(character);
        } catch (_error) {
          // File system save failed, but localStorage succeeded
          console.warn('File system save failed, character saved to localStorage only');
        }
      }

      return character;
    },
    [addCharacter, updateCharacter, getAllCharacters, saveToLocalStorage, saveToFile, saveToProjectDirectory, loadFromLocalStorage]
  );

  /**
   * Load a character from localStorage
   * Requirements: 8.1, 8.2, 8.4
   */
  const loadCharacter = useCallback(
    async (character_id: string): Promise<Character | null> => {
      try {
        const character = loadFromLocalStorage(character_id);

        if (character) {
          // Add to store
          addCharacter(character);
          return character;
        }

        console.warn(`Character not found: ${character_id}`);
        return null;
      } catch (error) {
        if (error instanceof PersistenceError) {
          console.error('Persistence error loading character:', error.message, error.details);

          // For corrupted data, try to recover or skip
          if (error.type === PersistenceErrorType.CORRUPTED_DATA) {
            console.warn(`Skipping corrupted character: ${character_id}`);
            return null;
          }
        }
        console.error('Error loading character:', error);
        return null;
      }
    },
    [addCharacter, loadFromLocalStorage]
  );

  /**
   * Load all characters from localStorage
   * Requirements: 8.1, 8.2, 8.4
   */
  const loadAllCharacters = useCallback(async (): Promise<Character[]> => {
    try {
      const characterIds = JSON.parse(
        localStorage.getItem('character-ids') || '[]'
      ) as string[];

      const characters: Character[] = [];
      const errors: Array<{ id: string; error: unknown }> = [];

      for (const id of characterIds) {
        try {
          const character = await loadCharacter(id);
          if (character) {
            characters.push(character);
          }
        } catch (error) {
          errors.push({ id, error });
          console.error(`Failed to load character ${id}:`, error);
        }
      }

      // Log summary of errors
      if (errors.length > 0) {
        console.warn(
          `Failed to load ${errors.length} character(s). ` +
          `Successfully loaded ${characters.length} character(s).`
        );
      }

      return characters;
    } catch (error) {
      console.error('Error loading characters:', error);
      return [];
    }
  }, [loadCharacter]);

  /**
   * Load and sync characters when a project is loaded
   * This should be called after a project is loaded to ensure all characters
   * from the project directory are properly loaded into the store
   * Requirements: 8.2, 8.4
   */
  const loadAndSyncCharacters = useCallback(async (): Promise<{ loaded: number; errors: number }> => {
    const projectPath = useEditorStore.getState().projectPath;

    if (!projectPath) {
      console.log('[useCharacterPersistence] No project path available for loading characters');
      return { loaded: 0, errors: 0 };
    }

    let loaded = 0;
    let errors = 0;

    try {
      // First, load characters from project directory
      const projectCharacters = await loadCharactersFromProjectDirectory(projectPath);

      if (projectCharacters.length > 0) {
        // Use setCharacters to bulk set all characters at once (more efficient)
        const existingCharacters = getAllCharacters();
        const allCharacters = [...existingCharacters];

        for (const character of projectCharacters) {
          try {
            // Check if character already exists in store
            const existingIndex = allCharacters.findIndex(
              (c) => c.character_id === character.character_id
            );

            if (existingIndex >= 0) {
              // Update existing character
              allCharacters[existingIndex] = character;
            } else {
              // Add new character
              allCharacters.push(character);
            }

            // Also save to localStorage
            saveToLocalStorage(character);
            loaded++;
          } catch (error) {
            console.error(`[useCharacterPersistence] Failed to sync character ${character.character_id}:`, error);
            errors++;
          }
        }

        // Bulk update store with all characters
        setCharacters(allCharacters);

        console.log(`[useCharacterPersistence] Loaded and synced ${loaded} characters from project directory`);
      }

      /* 
      // DISABLED: Indiscriminate loading from localStorage causes characters from other projects to appear
      // also check localStorage for any characters not in project directory
      const characterIds = JSON.parse(
        localStorage.getItem('character-ids') || '[]'
      ) as string[];

      for (const id of characterIds) {
        try {
          // Check if character is already loaded from project directory
          const alreadyLoaded = projectCharacters.some((c) => c.character_id === id);
          if (!alreadyLoaded) {
            const character = loadFromLocalStorage(id);
            if (character) {
              const existingCharacters = getAllCharacters();
              const existingIndex = existingCharacters.findIndex(
                (c) => c.character_id === id
              );

              if (existingIndex >= 0) {
                // Update with localStorage version
                updateCharacter(id, character);
              } else {
                // Add new character from localStorage
                addCharacter(character);
              }
            }
          }
        } catch (error) {
          console.error(`[useCharacterPersistence] Failed to load character ${id} from localStorage:`, error);
        }
      }
      */

      return { loaded, errors };
    } catch (error) {
      console.error('[useCharacterPersistence] Failed to load and sync characters:', error);
      return { loaded, errors };
    }
  }, [loadCharactersFromProjectDirectory, getAllCharacters, setCharacters, saveToLocalStorage, addCharacter, updateCharacter, loadFromLocalStorage]);

  /**
   * Delete a character from localStorage, file system, and store
   * Requirements: 8.1, 8.2
   */
  const removeCharacter = useCallback(
    async (character_id: string): Promise<void> => {
      try {
        // Get project path from editor store
        const projectPath = useEditorStore.getState().projectPath;

        // Remove from Zustand store
        deleteCharacter(character_id);

        // Remove from localStorage
        try {
          localStorage.removeItem(`character-${character_id}`);

          // Update character IDs list
          const characterIds = JSON.parse(
            localStorage.getItem('character-ids') || '[]'
          ) as string[];

          const updatedIds = characterIds.filter((id) => id !== character_id);
          localStorage.setItem('character-ids', JSON.stringify(updatedIds));
        } catch (error) {
          console.error('Failed to remove from localStorage:', error);
        }

        // Remove from project directory if available
        if (projectPath && window.electronAPI?.fs?.unlink) {
          try {
            const filePath = `${projectPath}/characters/character_${character_id}.json`;
            await window.electronAPI.fs.unlink(filePath);
            console.log(`[useCharacterPersistence] Deleted character file: ${filePath}`);
          } catch (error) {
            console.warn('[useCharacterPersistence] Failed to delete character from project directory:', error);
          }
        }

      } catch (error) {
        console.error('Error deleting character:', error);
        throw new PersistenceError(
          PersistenceErrorType.FILE_SYSTEM_ERROR,
          'Failed to delete character',
          { originalError: error }
        );
      }
    },
    [deleteCharacter]
  );

  /**
   * Sync characters from project directory to store
   * Loads all characters from the project's characters folder
   * Requirements: 8.2, 8.4
   */
  const syncCharactersFromProject = useCallback(
    async (): Promise<{ loaded: number; errors: number }> => {
      const projectPath = useEditorStore.getState().projectPath;

      if (!projectPath) {
        console.log('[useCharacterPersistence] No project path available for sync');
        return { loaded: 0, errors: 0 };
      }

      let loaded = 0;
      let errors = 0;

      try {
        const characters = await loadCharactersFromProjectDirectory(projectPath);

        for (const character of characters) {
          try {
            // Check if character already exists in store
            const existingCharacters = getAllCharacters();
            const existingIndex = existingCharacters.findIndex(
              (c) => c.character_id === character.character_id
            );

            if (existingIndex >= 0) {
              // Update existing character
              updateCharacter(character.character_id, character);
            } else {
              // Add new character
              addCharacter(character);
            }

            // Also save to localStorage
            saveToLocalStorage(character);

            loaded++;
          } catch (error) {
            console.error(`[useCharacterPersistence] Failed to sync character ${character.character_id}:`, error);
            errors++;
          }
        }

        if (loaded > 0) {
          toast.success(
            'Characters Synchronized',
            `Loaded ${loaded} character${loaded > 1 ? 's' : ''} from project directory`,
            3000
          );
        }

        return { loaded, errors };
      } catch (error) {
        console.error('[useCharacterPersistence] Failed to sync characters from project:', error);
        return { loaded, errors };
      }
    },
    [addCharacter, updateCharacter, getAllCharacters, loadCharactersFromProjectDirectory, saveToLocalStorage]
  );

  return {
    saveCharacter,
    loadCharacter,
    loadAllCharacters,
    loadAndSyncCharacters,
    removeCharacter,
    syncCharactersFromProject,
    saveToProjectDirectory,
    loadCharactersFromProjectDirectory,
  };
}

// ============================================================================
// Character Persistence Hook (Optimized)
// ============================================================================
// Performance-optimized version with:
// - Debounced localStorage writes to reduce I/O operations
// - Batched file system operations for multiple saves
// - In-memory caching layer to reduce localStorage reads
// - Optimized conflict resolution with caching
// - Background sync for non-critical operations
//
// Requirements: 8.1, 8.2, 8.3, 8.4, 8.5
// ============================================================================

import { useCallback, useRef, useEffect } from 'react';
import { useStore } from '../store';
import type { Character } from '../types/character';
import { toast } from '../utils/toast';
import {
  PersistenceError,
  PersistenceErrorType,
  PersistedCharacter,
  RetryConfig,
  type ConflictResolution,
} from './useCharacterPersistence';

// ============================================================================
// Configuration
// ============================================================================

/** Debounce delay for localStorage writes (ms) */
const LOCALSTORAGE_DEBOUNCE_DELAY = 500;

/** Batch delay for file system operations (ms) */
const FILE_SYSTEM_BATCH_DELAY = 1000;

/** Maximum batch size for file operations */
const MAX_BATCH_SIZE = 10;

/** Cache TTL in milliseconds (5 minutes) */
const CACHE_TTL = 5 * 60 * 1000;

/** Maximum cache size (number of characters) */
const MAX_CACHE_SIZE = 100;

// ============================================================================
// Types
// ============================================================================

/**
 * Cache entry with TTL
 */
interface CacheEntry {
  character: PersistedCharacter;
  timestamp: number;
}

/**
 * Pending save operation
 */
interface PendingSave {
  character: PersistedCharacter;
  resolve: (value: Character) => void;
  reject: (error: Error) => void;
}

/**
 * Batched file operation
 */
interface BatchedFileOperation {
  type: 'save' | 'delete';
  characterId: string;
  character?: PersistedCharacter;
}

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Generate UUID
 */
function generateUUID(): string {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

/**
 * Retry with exponential backoff
 */
async function retryWithBackoff<T>(
  fn: () => Promise<T>,
  config: RetryConfig = {
    maxAttempts: 3,
    delayMs: 1000,
    backoffMultiplier: 2,
  }
): Promise<T> {
  let lastError: Error | null = null;

  for (let attempt = 1; attempt <= config.maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error as Error;

      if (attempt < config.maxAttempts) {
        const delay = config.delayMs * Math.pow(config.backoffMultiplier, attempt - 1);
        await new Promise((resolve) => setTimeout(resolve, delay));
      }
    }
  }

  throw lastError || new Error('Retry failed');
}

/**
 * Validate character schema
 */
function validateCharacterSchema(data: any): { valid: boolean; errors: string[] } {
  const errors: string[] = [];

  if (!data.character_id || typeof data.character_id !== 'string') {
    errors.push('character_id is required and must be a string');
  }
  if (!data.name || typeof data.name !== 'string') {
    errors.push('name is required and must be a string');
  }
  if (!data.creation_method || !['wizard', 'auto_generated', 'manual'].includes(data.creation_method)) {
    errors.push('creation_method must be one of: wizard, auto_generated, manual');
  }
  if (!data.creation_timestamp || (typeof data.creation_timestamp !== 'string' && typeof data.creation_timestamp !== 'number')) {
    errors.push('creation_timestamp is required and must be a string or number');
  }
  if (!data.version || typeof data.version !== 'string') {
    errors.push('version is required and must be a string');
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

/**
 * Resolve conflict by timestamp
 */
function resolveConflictByTimestamp(
  localChar: PersistedCharacter,
  remoteChar: PersistedCharacter
): PersistedCharacter {
  const localTime = new Date(localChar.last_modified || localChar.creation_timestamp).getTime();
  const remoteTime = new Date(remoteChar.last_modified || remoteChar.creation_timestamp).getTime();
  return localTime > remoteTime ? localChar : remoteChar;
}

// ============================================================================
// Optimized Character Persistence Hook
// ============================================================================

export function useCharacterPersistenceOptimized() {
  const addCharacter = useStore((state) => state.addCharacter);
  const updateCharacter = useStore((state) => state.updateCharacter);
  const deleteCharacter = useStore((state) => state.deleteCharacter);
  const getAllCharacters = useStore((state) => state.getAllCharacters);

  // ============================================================================
  // Cache Management
  // ============================================================================

  const cache = useRef<Map<string, CacheEntry>>(new Map());

  /**
   * Get character from cache
   */
  const getFromCache = useCallback((characterId: string): PersistedCharacter | null => {
    const entry = cache.current.get(characterId);
    if (!entry) return null;

    // Check if cache entry is still valid
    const now = Date.now();
    if (now - entry.timestamp > CACHE_TTL) {
      cache.current.delete(characterId);
      return null;
    }

    return entry.character;
  }, []);

  /**
   * Add character to cache
   */
  const addToCache = useCallback((character: PersistedCharacter): void => {
    // Enforce cache size limit (LRU eviction)
    if (cache.current.size >= MAX_CACHE_SIZE) {
      // Remove oldest entry
      const oldestKey = cache.current.keys().next().value;
      if (oldestKey) {
        cache.current.delete(oldestKey);
      }
    }

    cache.current.set(character.character_id, {
      character,
      timestamp: Date.now(),
    });
  }, []);

  /**
   * Remove character from cache
   */
  const removeFromCache = useCallback((characterId: string): void => {
    cache.current.delete(characterId);
  }, []);

  /**
   * Clear entire cache
   */
  const clearCache = useCallback((): void => {
    cache.current.clear();
  }, []);

  // ============================================================================
  // Debounced localStorage Operations
  // ============================================================================

  const pendingSaves = useRef<Map<string, PendingSave>>(new Map());
  const saveTimers = useRef<Map<string, NodeJS.Timeout>>(new Map());

  /**
   * Save to localStorage with debouncing
   */
  const saveToLocalStorageDebounced = useCallback(
    (character: PersistedCharacter): Promise<void> => {
      return new Promise((resolve, reject) => {
        const characterId = character.character_id;

        // Clear existing timer
        const existingTimer = saveTimers.current.get(characterId);
        if (existingTimer) {
          clearTimeout(existingTimer);
        }

        // Store pending save
        const existingPending = pendingSaves.current.get(characterId);
        if (existingPending) {
          // Reject previous pending save (it will be superseded)
          existingPending.reject(new Error('Superseded by newer save'));
        }

        pendingSaves.current.set(characterId, {
          character,
          resolve: resolve as any,
          reject,
        });

        // Set new timer
        const timer = setTimeout(() => {
          const pending = pendingSaves.current.get(characterId);
          if (!pending) return;

          try {
            // Perform actual localStorage write
            localStorage.setItem(
              `character-${characterId}`,
              JSON.stringify(pending.character)
            );

            // Update master list
            const allCharacterIds = JSON.parse(
              localStorage.getItem('character-ids') || '[]'
            ) as string[];

            if (!allCharacterIds.includes(characterId)) {
              allCharacterIds.push(characterId);
              localStorage.setItem('character-ids', JSON.stringify(allCharacterIds));
            }

            // Update cache
            addToCache(pending.character);

            // Resolve promise
            pending.resolve(pending.character);
            pendingSaves.current.delete(characterId);
            saveTimers.current.delete(characterId);
          } catch (error) {
            if (error instanceof DOMException && error.name === 'QuotaExceededError') {
              toast.error(
                'Storage Quota Exceeded',
                'Your browser storage is full. Please export some characters.',
                10000
              );
              pending.reject(
                new PersistenceError(
                  PersistenceErrorType.STORAGE_QUOTA_EXCEEDED,
                  'localStorage quota exceeded',
                  { originalError: error }
                )
              );
            } else {
              pending.reject(error as Error);
            }
            pendingSaves.current.delete(characterId);
            saveTimers.current.delete(characterId);
          }
        }, LOCALSTORAGE_DEBOUNCE_DELAY);

        saveTimers.current.set(characterId, timer);
      });
    },
    [addToCache]
  );

  /**
   * Flush all pending localStorage saves immediately
   */
  const flushLocalStorageSaves = useCallback((): Promise<void[]> => {
    const promises: Promise<void>[] = [];

    // Clear all timers and execute saves immediately
    for (const [characterId, timer] of saveTimers.current.entries()) {
      clearTimeout(timer);
      const pending = pendingSaves.current.get(characterId);
      if (pending) {
        const promise = new Promise<void>((resolve, reject) => {
          try {
            localStorage.setItem(
              `character-${characterId}`,
              JSON.stringify(pending.character)
            );
            addToCache(pending.character);
            pending.resolve(pending.character);
            resolve();
          } catch (error) {
            pending.reject(error as Error);
            reject(error);
          }
        });
        promises.push(promise);
      }
    }

    pendingSaves.current.clear();
    saveTimers.current.clear();

    return Promise.all(promises);
  }, [addToCache]);

  // ============================================================================
  // Batched File System Operations
  // ============================================================================

  const fileOperationQueue = useRef<BatchedFileOperation[]>([]);
  const fileOperationTimer = useRef<NodeJS.Timeout | null>(null);

  /**
   * Process batched file operations
   */
  const processFileOperationBatch = useCallback(async (): Promise<void> => {
    if (fileOperationTimer.current) {
      clearTimeout(fileOperationTimer.current);
      fileOperationTimer.current = null;
    }

    if (fileOperationQueue.current.length === 0) {
      return;
    }

    const batch = fileOperationQueue.current.splice(0, MAX_BATCH_SIZE);

    try {
      // Send batch request to backend
      const response = await fetch('/api/characters/batch', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ operations: batch }),
      });

      if (!response.ok) {
        console.warn('Batch file operation failed:', response.statusText);
      }
    } catch (error) {
      console.warn('Failed to process file operation batch:', error);
    }

    // If there are more operations, schedule another batch
    if (fileOperationQueue.current.length > 0) {
      fileOperationTimer.current = setTimeout(
        processFileOperationBatch,
        FILE_SYSTEM_BATCH_DELAY
      );
    }
  }, []);

  /**
   * Queue file operation for batching
   */
  const queueFileOperation = useCallback(
    (operation: BatchedFileOperation): void => {
      fileOperationQueue.current.push(operation);

      // Process immediately if batch is full
      if (fileOperationQueue.current.length >= MAX_BATCH_SIZE) {
        processFileOperationBatch();
        return;
      }

      // Schedule batch processing
      if (!fileOperationTimer.current) {
        fileOperationTimer.current = setTimeout(
          processFileOperationBatch,
          FILE_SYSTEM_BATCH_DELAY
        );
      }
    },
    [processFileOperationBatch]
  );

  /**
   * Flush all pending file operations immediately
   */
  const flushFileOperations = useCallback(async (): Promise<void> => {
    while (fileOperationQueue.current.length > 0) {
      await processFileOperationBatch();
    }
  }, [processFileOperationBatch]);

  // ============================================================================
  // Optimized Load Operations
  // ============================================================================

  /**
   * Load character from localStorage with caching
   */
  const loadFromLocalStorage = useCallback(
    (characterId: string): PersistedCharacter | null => {
      // Check cache first
      const cached = getFromCache(characterId);
      if (cached) {
        return cached;
      }

      try {
        const stored = localStorage.getItem(`character-${characterId}`);
        if (!stored) {
          return null;
        }

        const character = JSON.parse(stored);

        // Validate
        const validation = validateCharacterSchema(character);
        if (!validation.valid) {
          console.error(`Corrupted character data: ${characterId}`, validation.errors);
          return null;
        }

        // Add to cache
        addToCache(character);

        return character;
      } catch (error) {
        console.error('Failed to load character from localStorage:', error);
        return null;
      }
    },
    [getFromCache, addToCache]
  );

  // ============================================================================
  // Public API
  // ============================================================================

  /**
   * Save character with optimized persistence
   */
  const saveCharacter = useCallback(
    async (characterData: Partial<Character>): Promise<Character> => {
      const character_id = characterData.character_id || generateUUID();

      // Get existing version number
      const existingChar = loadFromLocalStorage(character_id);
      const currentVersionNumber = (existingChar as PersistedCharacter)?.version_number || 0;

      // Create persisted character
      const character: PersistedCharacter = {
        character_id,
        name: characterData.name || '',
        creation_method: characterData.creation_method || 'wizard',
        creation_timestamp: characterData.creation_timestamp || Date.now(),
        version: characterData.version || '1.0',
        last_modified: Date.now(),
        version_number: currentVersionNumber + 1,
        visual_identity: characterData.visual_identity || {} as any,
        personality: characterData.personality || {} as any,
        background: characterData.background || {} as any,
        relationships: characterData.relationships || [],
        role: characterData.role || {} as any,
        thumbnail_url: (characterData as PersistedCharacter).thumbnail_url,
        tags: (characterData as PersistedCharacter).tags,
        notes: (characterData as PersistedCharacter).notes,
      };

      // Validate schema
      const validation = validateCharacterSchema(character);
      if (!validation.valid) {
        throw new PersistenceError(
          PersistenceErrorType.VALIDATION_ERROR,
          `Schema validation failed: ${validation.errors.join(', ')}`,
          { errors: validation.errors }
        );
      }

      // Update store
      const existingCharacters = getAllCharacters();
      const characterIndex = existingCharacters.findIndex(
        (c) => c.character_id === character_id
      );

      if (characterIndex >= 0) {
        updateCharacter(character_id, character);
      } else {
        addCharacter(character);
      }

      // Save to localStorage (debounced)
      await saveToLocalStorageDebounced(character);

      // Queue file system save (batched)
      queueFileOperation({
        type: 'save',
        characterId: character_id,
        character,
      });

      return character;
    },
    [
      loadFromLocalStorage,
      getAllCharacters,
      updateCharacter,
      addCharacter,
      saveToLocalStorageDebounced,
      queueFileOperation,
    ]
  );

  /**
   * Load character with caching
   */
  const loadCharacter = useCallback(
    async (characterId: string): Promise<Character | null> => {
      const character = loadFromLocalStorage(characterId);
      if (character) {
        addCharacter(character);
        return character;
      }
      return null;
    },
    [loadFromLocalStorage, addCharacter]
  );

  /**
   * Load all characters with caching
   */
  const loadAllCharacters = useCallback(async (): Promise<Character[]> => {
    try {
      const characterIds = JSON.parse(
        localStorage.getItem('character-ids') || '[]'
      ) as string[];

      const characters: Character[] = [];

      for (const id of characterIds) {
        const character = loadFromLocalStorage(id);
        if (character) {
          characters.push(character);
          addCharacter(character);
        }
      }

      return characters;
    } catch (error) {
      console.error('Error loading characters:', error);
      return [];
    }
  }, [loadFromLocalStorage, addCharacter]);

  /**
   * Delete character with batched file operations
   */
  const removeCharacter = useCallback(
    async (characterId: string): Promise<void> => {
      // Remove from store
      deleteCharacter(characterId);

      // Remove from cache
      removeFromCache(characterId);

      // Remove from localStorage
      try {
        localStorage.removeItem(`character-${characterId}`);

        const characterIds = JSON.parse(
          localStorage.getItem('character-ids') || '[]'
        ) as string[];

        const updatedIds = characterIds.filter((id) => id !== characterId);
        localStorage.setItem('character-ids', JSON.stringify(updatedIds));
      } catch (error) {
        console.error('Failed to remove from localStorage:', error);
      }

      // Queue file system delete (batched)
      queueFileOperation({
        type: 'delete',
        characterId,
      });
    },
    [deleteCharacter, removeFromCache, queueFileOperation]
  );

  // ============================================================================
  // Cleanup on Unmount
  // ============================================================================

  useEffect(() => {
    return () => {
      // Flush all pending operations on unmount
      flushLocalStorageSaves();
      flushFileOperations();
    };
  }, [flushLocalStorageSaves, flushFileOperations]);

  return {
    saveCharacter,
    loadCharacter,
    loadAllCharacters,
    removeCharacter,
    flushLocalStorageSaves,
    flushFileOperations,
    clearCache,
  };
}

// ============================================================================
// Character Sync Hook - Unified Character State Management
// ============================================================================
// Ensures characters are stored in a SINGLE source of truth
// Prevents duplication between project.characters and store.characters
//
// Problem: Characters were being stored in two places causing:
// - Data inconsistency between project state and store state
// - Lost characters when switching projects
// - Duplicate characters in UI
//
// Solution: All characters go through the store, project references store characters
//
// Requirements: 8.1, 8.4
// ============================================================================

import { useEffect, useCallback, useMemo, useState } from 'react';
import { useStore } from '../store';
import type { Character } from '../types/character';
import { logger as Logger } from '../utils/logger';

// ============================================================================
// Types
// ============================================================================

export interface CharacterSyncState {
  isLoading: boolean;
  error: string | null;
  lastSynced: Date | null;
}

export interface CharacterSyncActions {
  addCharacter: (character: Character) => void;
  updateCharacter: (id: string, updates: Partial<Character>) => void;
  deleteCharacter: (id: string) => void;
  getCharacterById: (id: string) => Character | undefined;
  getAllCharacters: () => Character[];
  initializeFromProject: (projectCharacters: Character[]) => void;
  clearAllCharacters: () => void;
  syncToProject: () => void;
  validateCharacters: () => { valid: Character[]; invalid: string[] };
}

export interface CharacterSyncResult extends CharacterSyncState, CharacterSyncActions {
  characters: Character[];
  characterCount: number;
  hasCharacters: boolean;
  projectHasCharacters: boolean;
  isInSync: boolean;
}

// ============================================================================
// Character Sync Hook
// ============================================================================

/**
 * Hook that provides unified character state management
 * Prevents duplication between project.characters and store.characters
 *
 * All character operations should go through this hook to ensure
 * a single source of truth.
 *
 * Requirements: 8.1, 8.4
 */
export function useCharacterSync(): CharacterSyncResult {
  // ============================================================================
  // Store Selectors
  // ============================================================================
  const characters = useStore((state) => state.characters);
  const project = useStore((state) => state.project);
  const setProject = useStore((state) => state.setProject);
  const addCharacterStore = useStore((state) => state.addCharacter);
  const updateCharacterStore = useStore((state) => state.updateCharacter);
  const deleteCharacterStore = useStore((state) => state.deleteCharacter);
  const getCharacterByIdStore = useStore((state) => state.getCharacterById);
  const setCharactersStore = useStore((state) => state.setCharacters);

  // ============================================================================
  // Local State for Sync Status
  // ============================================================================
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [lastSynced, setLastSynced] = useState<Date | null>(null);

  // ============================================================================
  // Validation Helper
  // ============================================================================
  const validateCharacter = useCallback((char: unknown): char is Character => {
    if (!char || typeof char !== 'object') return false;
    
    const c = char as Record<string, unknown>;
    return (
      typeof c.character_id === 'string' &&
      typeof c.name === 'string' &&
      typeof c.creation_method === 'string' &&
      typeof c.creation_timestamp === 'string' &&
      typeof c.version === 'string' &&
      c.visual_identity !== null &&
      typeof c.visual_identity === 'object' &&
      c.personality !== null &&
      typeof c.personality === 'object' &&
      c.background !== null &&
      typeof c.background === 'object' &&
      c.role !== null &&
      typeof c.role === 'object' &&
      Array.isArray(c.relationships)
    );
  }, []);

  // Type for reducer state
  type SyncState = {
    characters: Character[];
    project: typeof project;
  };

  // ============================================================================
  // Sync Effect - Ensure project.characters matches store.characters
  // ============================================================================
  useEffect(() => {
    if (!project) return;

    // Check if sync is needed
    const projectChars = project.characters;
    const storeCharIds = new Set(characters.map(c => c.character_id));
    
    let needsSync = false;
    if (!projectChars || projectChars.length !== characters.length) {
      needsSync = true;
    } else {
      // Check if any character is missing from project
      for (const pc of projectChars) {
        const pcAny = pc as { character_id?: string };
        if (!storeCharIds.has(pcAny.character_id || '')) {
          needsSync = true;
          break;
        }
      }
    }

    if (needsSync) {
      Logger.info('[useCharacterSync] Syncing characters to project:', characters.length);
      setProject({
        ...project,
        characters: characters,
      });
      setLastSynced(new Date());
    }
  }, [characters, project, setProject]);

  // ============================================================================
  // Character Operations
  // ============================================================================

  /**
   * Add a character to the store (single source of truth)
   * Automatically syncs to project.characters
   */
  const addCharacter = useCallback((character: Character) => {
    try {
      // Validate character before adding
      if (!validateCharacter(character)) {
        throw new Error('Invalid character data structure');
      }

      Logger.info('[useCharacterSync] Adding character:', character.name);
      addCharacterStore(character);
      setLastSynced(new Date());
      setError(null);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to add character';
      Logger.error('[useCharacterSync] Error adding character:', message);
      setError(message);
      throw err;
    }
  }, [addCharacterStore, validateCharacter]);

  /**
   * Update a character in the store
   */
  const updateCharacter = useCallback((id: string, updates: Partial<Character>) => {
    try {
      if (!id) {
        throw new Error('Character ID is required');
      }

      Logger.info('[useCharacterSync] Updating character:', id);
      updateCharacterStore(id, updates);
      setLastSynced(new Date());
      setError(null);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to update character';
      Logger.error('[useCharacterSync] Error updating character:', message);
      setError(message);
      throw err;
    }
  }, [updateCharacterStore]);

  /**
   * Delete a character from the store
   */
  const deleteCharacter = useCallback((id: string) => {
    try {
      if (!id) {
        throw new Error('Character ID is required');
      }

      Logger.info('[useCharacterSync] Deleting character:', id);
      deleteCharacterStore(id);
      setLastSynced(new Date());
      setError(null);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to delete character';
      Logger.error('[useCharacterSync] Error deleting character:', message);
      setError(message);
      throw err;
    }
  }, [deleteCharacterStore]);

  /**
   * Get a character by ID from store
   */
  const getCharacterById = useCallback((id: string) => {
    if (!id) return undefined;
    return getCharacterByIdStore(id);
  }, [getCharacterByIdStore]);

  /**
   * Get all characters from store
   */
  const getAllCharacters = useCallback(() => {
    return characters;
  }, [characters]);

  /**
   * Initialize characters from project to store
   * Should be called when loading a project
   */
  const initializeFromProject = useCallback((projectCharacters: Character[]) => {
    setIsLoading(true);
    try {
      Logger.info('[useCharacterSync] Initializing from project:', projectCharacters.length, 'characters');

      // Validate all characters before adding
      const validCharacters: Character[] = [];
      const invalidIds: string[] = [];

      projectCharacters.forEach((char) => {
        if (validateCharacter(char)) {
          validCharacters.push(char);
        } else {
          const c = char as Record<string, unknown>;
          invalidIds.push(String(c.character_id || 'unknown'));
          Logger.warn('[useCharacterSync] Invalid character found:', c.character_id);
        }
      });

      if (invalidIds.length > 0) {
        Logger.warn('[useCharacterSync] Skipped', invalidIds.length, 'invalid characters');
        setError(`Skipped ${invalidIds.length} invalid characters`);
      }

      // Clear existing characters and add project characters
      setCharactersStore(validCharacters);
      setLastSynced(new Date());
      setError(null);
      
      Logger.info('[useCharacterSync] Successfully initialized', validCharacters.length, 'characters');
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to initialize characters';
      Logger.error('[useCharacterSync] Error initializing characters:', message);
      setError(message);
    } finally {
      setIsLoading(false);
    }
  }, [setCharactersStore, validateCharacter]);

  /**
   * Clear all characters from store
   * Should be called when closing a project
   */
  const clearAllCharacters = useCallback(() => {
    try {
      Logger.info('[useCharacterSync] Clearing all characters');
      setCharactersStore([]);
      setLastSynced(new Date());
      setError(null);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to clear characters';
      Logger.error('[useCharacterSync] Error clearing characters:', message);
      setError(message);
      throw err;
    }
  }, [setCharactersStore]);

  /**
   * Force sync to project
   * Can be called manually to ensure project is in sync
   */
  const syncToProject = useCallback(() => {
    if (!project) {
      Logger.warn('[useCharacterSync] No project to sync to');
      return;
    }

    try {
      Logger.info('[useCharacterSync] Force syncing characters to project');
      setProject({
        ...project,
        characters: characters,
      });
      setLastSynced(new Date());
      setError(null);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to sync to project';
      Logger.error('[useCharacterSync] Error syncing to project:', message);
      setError(message);
      throw err;
    }
  }, [project, characters, setProject]);

  /**
   * Validate all characters in store
   * Returns valid and invalid character IDs
   */
  const validateCharacters = useCallback((): { valid: Character[]; invalid: string[] } => {
    const valid: Character[] = [];
    const invalid: string[] = [];

    for (const char of characters) {
      const charAsUnknown = char as unknown;
      if (validateCharacter(charAsUnknown)) {
        valid.push(char);
      } else {
        invalid.push(char.character_id);
      }
    }

    return { valid, invalid };
  }, [characters, validateCharacter]);

  // ============================================================================
  // Derived State
  // ============================================================================
  const characterCount = characters.length;
  const hasCharacters = characters.length > 0;
  const projectHasCharacters = (project?.characters?.length || 0) > 0;

  // Check if store and project are in sync
   
  const isInSync = useMemo(() => {
    if (!project) return true; // No project, always in sync
    const projectCharacters = project.characters as any[];
    if (!projectCharacters || !Array.isArray(projectCharacters)) return characters.length === 0;
    if (projectCharacters.length !== characters.length) return false;
    
    // Check if all characters match - use any to bypass type narrowing
    const charIds = new Set(characters.map(c => c.character_id));
    const projectCharIds = new Set(projectCharacters.map((pc: any) => pc.character_id));
    
    if (charIds.size !== projectCharIds.size) return false;
    
    for (const id of charIds) {
      if (!projectCharIds.has(id)) return false;
    }
    
    return true;
  }, [characters, project]);

  // ============================================================================
  // Return
  // ============================================================================
  return {
    // State
    characters,
    characterCount,
    isLoading,
    error,
    lastSynced,
    hasCharacters,
    projectHasCharacters,
    isInSync,

    // Actions
    addCharacter,
    updateCharacter,
    deleteCharacter,
    getCharacterById,
    getAllCharacters,
    initializeFromProject,
    clearAllCharacters,
    syncToProject,
    validateCharacters,
  };
}

import { useEffect, useRef, useState } from 'react';
import { useAppStore } from '@/stores/useAppStore';
import { ChatService, createChatService } from '@/services/chatService';
import type { ChatMessage } from '@/types';

/**
 * Custom hook for managing chat service with project context awareness
 */
export function useChatService() {
  const {
    project,
    shots,
    assets,
    selectedShotId,
    chatMessages,
    addChatMessage,
    addShot,
    updateShot,
    deleteShot,
  } = useAppStore();

  const chatServiceRef = useRef<ChatService | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  // Initialize chat service
  useEffect(() => {
    if (!chatServiceRef.current) {
      chatServiceRef.current = createChatService({
        project,
        shots,
        assets,
        selectedShotId,
      });
    }
  }, []);

  // Update context when project state changes
  useEffect(() => {
    if (chatServiceRef.current) {
      chatServiceRef.current.updateContext({
        project,
        shots,
        assets,
        selectedShotId,
      });
    }
  }, [project, shots, assets, selectedShotId]);

  /**
   * Send a message and get AI response
   */
  const sendMessage = async (content: string): Promise<void> => {
    if (!content.trim() || isProcessing || !chatServiceRef.current) return;

    setIsProcessing(true);

    // Add user message
    const userMessage: ChatMessage = {
      id: `msg-${Date.now()}`,
      role: 'user',
      content: content.trim(),
      timestamp: new Date(),
    };

    addChatMessage(userMessage);
    chatServiceRef.current.addToHistory(userMessage);

    try {
      // Process message and get AI response
      const response = await chatServiceRef.current.processMessage(content);

      // Add assistant message
      const assistantMessage: ChatMessage = {
        id: `msg-${Date.now()}-assistant`,
        role: 'assistant',
        content: response.message,
        timestamp: new Date(),
        suggestions: response.suggestions,
      };

      addChatMessage(assistantMessage);
      chatServiceRef.current.addToHistory(assistantMessage);

      // Execute actions
      if (response.actions) {
        response.actions.forEach((action) => {
          switch (action.type) {
            case 'addShot':
              addShot(action.payload);
              break;
            case 'updateShot':
              updateShot(action.payload.id, action.payload.updates);
              break;
            case 'deleteShot':
              deleteShot(action.payload.id);
              break;
            // Add more action handlers as needed
          }
        });
      }
    } catch (error) {
      console.error('Error processing chat message:', error);

      // Add error message
      const errorMessage: ChatMessage = {
        id: `msg-${Date.now()}-error`,
        role: 'assistant',
        content: 'Sorry, I encountered an error processing your request. Please try again.',
        timestamp: new Date(),
      };

      addChatMessage(errorMessage);
    } finally {
      setIsProcessing(false);
    }
  };

  /**
   * Get conversation history
   */
  const getHistory = (): ChatMessage[] => {
    return chatServiceRef.current?.getHistory() || [];
  };

  /**
   * Clear conversation history
   */
  const clearHistory = (): void => {
    chatServiceRef.current?.clearHistory();
  };

  return {
    sendMessage,
    isProcessing,
    messages: chatMessages,
    getHistory,
    clearHistory,
  };
}

/**
 * useDebouncedPanelSizes Hook
 * 
 * Provides a debounced version of setPanelSizes to prevent excessive re-renders
 * during panel resizing operations.
 */

import { useCallback, useRef } from 'react';
import { useStore } from '@/store';
import { debounce } from '@/utils/debounce';
import type { PanelSizes } from '@/types';

/**
 * Hook that returns a debounced setPanelSizes function
 * Useful for resize handlers that fire frequently
 */
export function useDebouncedPanelSizes(wait: number = 100) {
  const setPanelSizes = useStore((state) => state.setPanelSizes);
  const debouncedSetPanelSizes = useRef(
    debounce((sizes: PanelSizes) => {
      setPanelSizes(sizes);
    }, wait)
  ).current;

  return useCallback(
    (sizes: PanelSizes) => {
      debouncedSetPanelSizes(sizes);
    },
    [debouncedSetPanelSizes]
  );
}

/**
 * Hook that returns both immediate and debounced setPanelSizes
 * Useful when you want immediate visual feedback but debounced state updates
 */
export function usePanelSizesWithDebounce(wait: number = 100) {
  const setPanelSizes = useStore((state) => state.setPanelSizes);
  const debouncedSetPanelSizes = useRef(
    debounce((sizes: PanelSizes) => {
      setPanelSizes(sizes);
    }, wait)
  ).current;

  return {
    // Immediate update for UI feedback
    setImmediate: useCallback(
      (sizes: PanelSizes) => {
        // Update UI immediately (if you have local state)
        // This is handled by the component's local state
      },
      []
    ),
    // Debounced update for store
    setDebounced: useCallback(
      (sizes: PanelSizes) => {
        debouncedSetPanelSizes(sizes);
      },
      [debouncedSetPanelSizes]
    ),
  };
}

