/**
 * useDragCancel Hook - Cancel Drag with Escape Key
 * 
 * Features:
 * - Detect Escape key during drag
 * - Restore initial state with animation
 * - Clean up drag operation
 * 
 * Validates: Requirement 2.8
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import type { Position } from '../types/gridEditorAdvanced';

interface UseDragCancelOptions {
  onCancel?: () => void;
  animationDuration?: number;
}

interface DragCancelState {
  isDragging: boolean;
  initialPosition: Position | null;
  currentPosition: Position | null;
  isCancelling: boolean;
}

export function useDragCancel(options: UseDragCancelOptions = {}) {
  const { onCancel, animationDuration = 300 } = options;
  
  const [state, setState] = useState<DragCancelState>({
    isDragging: false,
    initialPosition: null,
    currentPosition: null,
    isCancelling: false,
  });

  const cancelTimeoutRef = useRef<number | null>(null);

  /**
   * Handle Escape key press
   */
  const handleKeyDown = useCallback((event: KeyboardEvent) => {
    if (event.key === 'Escape' && state.isDragging && !state.isCancelling) {
      event.preventDefault();
      cancelDrag();
    }
  }, [state.isDragging, state.isCancelling]);

  /**
   * Set up event listeners
   */
  useEffect(() => {
    if (state.isDragging) {
      window.addEventListener('keydown', handleKeyDown);
      return () => {
        window.removeEventListener('keydown', handleKeyDown);
      };
    }
  }, [state.isDragging, handleKeyDown]);

  /**
   * Clean up timeout on unmount
   */
  useEffect(() => {
    return () => {
      if (cancelTimeoutRef.current) {
        clearTimeout(cancelTimeoutRef.current);
      }
    };
  }, []);

  /**
   * Start drag operation
   */
  const startDrag = useCallback((initialPosition: Position) => {
    setState({
      isDragging: true,
      initialPosition,
      currentPosition: initialPosition,
      isCancelling: false,
    });
  }, []);

  /**
   * Update current position during drag
   */
  const updatePosition = useCallback((position: Position) => {
    setState(prev => ({
      ...prev,
      currentPosition: position,
    }));
  }, []);

  /**
   * Cancel drag operation
   */
  const cancelDrag = useCallback(() => {
    if (!state.isDragging || state.isCancelling) return;

    setState(prev => ({
      ...prev,
      isCancelling: true,
    }));

    // Call cancel callback
    onCancel?.();

    // Reset state after animation
    cancelTimeoutRef.current = window.setTimeout(() => {
      setState({
        isDragging: false,
        initialPosition: null,
        currentPosition: null,
        isCancelling: false,
      });
    }, animationDuration);
  }, [state.isDragging, state.isCancelling, onCancel, animationDuration]);

  /**
   * End drag operation normally
   */
  const endDrag = useCallback(() => {
    setState({
      isDragging: false,
      initialPosition: null,
      currentPosition: null,
      isCancelling: false,
    });
  }, []);

  return {
    isDragging: state.isDragging,
    isCancelling: state.isCancelling,
    initialPosition: state.initialPosition,
    currentPosition: state.currentPosition,
    startDrag,
    updatePosition,
    cancelDrag,
    endDrag,
  };
}

/**
 * Cancel Animation Component
 * 
 * Validates: Requirement 2.8 - Restore initial state with animation
 */
interface CancelAnimationProps {
  isVisible: boolean;
  initialPosition: Position | null;
  currentPosition: Position | null;
  children: React.ReactNode;
}

export function CancelAnimation({
  isVisible,
  initialPosition,
  currentPosition,
  children,
}: CancelAnimationProps) {
  if (!isVisible || !initialPosition || !currentPosition) {
    return <>{children}</>;
  }

  const deltaX = initialPosition.x - currentPosition.x;
  const deltaY = initialPosition.y - currentPosition.y;

  return (
    <motion.div
      animate={{
        x: deltaX,
        y: deltaY,
        opacity: [1, 0.8, 1],
        scale: [1, 0.95, 1],
      }}
      transition={{
        duration: 0.3,
        ease: 'easeOut',
      }}
    >
      {children}
    </motion.div>
  );
}

/**
 * Cancel Notification Component
 * 
 * Shows a brief notification when drag is cancelled
 */
interface CancelNotificationProps {
  isVisible: boolean;
}

export function CancelNotification({ isVisible }: CancelNotificationProps) {
  return (
    <AnimatePresence>
      {isVisible && (
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -20 }}
          transition={{ duration: 0.2 }}
          style={{
            position: 'fixed',
            top: '24px',
            left: '50%',
            transform: 'translateX(-50%)',
            backgroundColor: '#6b7280',
            color: 'white',
            padding: '12px 20px',
            borderRadius: '8px',
            boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
            display: 'flex',
            alignItems: 'center',
            gap: '12px',
            zIndex: 9999,
            fontWeight: '600',
            fontSize: '14px',
          }}
        >
          {/* Cancel Icon */}
          <svg
            width="20"
            height="20"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <circle cx="12" cy="12" r="10" />
            <line x1="15" y1="9" x2="9" y2="15" />
            <line x1="9" y1="9" x2="15" y2="15" />
          </svg>

          {/* Text */}
          <span>Drag Cancelled</span>

          {/* Keyboard Hint */}
          <div
            style={{
              backgroundColor: 'rgba(255,255,255,0.2)',
              padding: '4px 8px',
              borderRadius: '4px',
              fontSize: '12px',
              fontFamily: 'monospace',
            }}
          >
            Esc
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

/**
 * useDragCopy Hook - Copy Mode Detection with Ctrl Key
 * 
 * Features:
 * - Detect Ctrl/Cmd key during drag
 * - Create copy instead of move
 * - Visual indicator for copy mode
 * 
 * Validates: Requirement 2.6
 */

import { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import type { ProductionShot } from '../types/shot';

interface UseDragCopyOptions {
  onCopy?: (items: ProductionShot[]) => ProductionShot[];
  onMove?: (items: ProductionShot[]) => void;
}

export function useDragCopy(options: UseDragCopyOptions = {}) {
  const [isCopyMode, setIsCopyMode] = useState(false);
  const [isDragging, setIsDragging] = useState(false);

  // Handle key down events
  const handleKeyDown = useCallback((event: KeyboardEvent) => {
    if (event.key === 'Control' || event.key === 'Meta') {
      setIsCopyMode(true);
    }
  }, []);

  // Handle key up events
  const handleKeyUp = useCallback((event: KeyboardEvent) => {
    if (event.key === 'Control' || event.key === 'Meta') {
      setIsCopyMode(false);
    }
  }, []);

  // Set up event listeners
  useEffect(() => {
    if (isDragging) {
      window.addEventListener('keydown', handleKeyDown);
      window.addEventListener('keyup', handleKeyUp);

      return () => {
        window.removeEventListener('keydown', handleKeyDown);
        window.removeEventListener('keyup', handleKeyUp);
      };
    }
  }, [isDragging, handleKeyDown, handleKeyUp]);

  /**
   * Start drag operation
   */
  const startDrag = useCallback((event: React.DragEvent | DragEvent) => {
    setIsDragging(true);
    setIsCopyMode(event.ctrlKey || event.metaKey);
  }, []);

  /**
   * End drag operation
   */
  const endDrag = useCallback(
    (items: ProductionShot[]) => {
      if (isCopyMode && options.onCopy) {
        const copiedItems = options.onCopy(items);
        setIsDragging(false);
        setIsCopyMode(false);
        return copiedItems;
      } else if (options.onMove) {
        options.onMove(items);
      }

      setIsDragging(false);
      setIsCopyMode(false);
      return items;
    },
    [isCopyMode, options]
  );

  /**
   * Create a copy of a shot with new ID
   */
  const createCopy = useCallback((shot: ProductionShot): ProductionShot => {
    const newId = `${shot.id}-copy-${Date.now()}`;
    
    return {
      ...shot,
      id: newId,
      number: shot.number + 1, // Increment shot number
      status: 'planned' as const,
      thumbnailUrl: shot.thumbnailUrl,
      generatedAssetUrl: undefined, // Clear generated asset for copy
    };
  }, []);

  /**
   * Create copies of multiple shots
   */
  const createCopies = useCallback(
    (shots: ProductionShot[]): ProductionShot[] => {
      return shots.map(shot => createCopy(shot));
    },
    [createCopy]
  );

  return {
    isCopyMode,
    isDragging,
    startDrag,
    endDrag,
    createCopy,
    createCopies,
  };
}

/**
 * Copy Mode Indicator Component
 * 
 * Validates: Requirement 2.6 - Visual indicator for copy mode
 */
interface CopyModeIndicatorProps {
  isVisible: boolean;
  itemCount?: number;
}

export function CopyModeIndicator({ isVisible, itemCount = 1 }: CopyModeIndicatorProps) {
  return (
    <AnimatePresence>
      {isVisible && (
        <motion.div
          initial={{ opacity: 0, scale: 0.8, y: 20 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.8, y: 20 }}
          transition={{ duration: 0.2 }}
          style={{
            position: 'fixed',
            bottom: '24px',
            right: '24px',
            backgroundColor: '#3b82f6',
            color: 'white',
            padding: '12px 20px',
            borderRadius: '8px',
            boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
            display: 'flex',
            alignItems: 'center',
            gap: '12px',
            zIndex: 9999,
            fontWeight: '600',
            fontSize: '14px',
          }}
        >
          {/* Copy Icon */}
          <svg
            width="20"
            height="20"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <rect x="9" y="9" width="13" height="13" rx="2" ry="2" />
            <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
          </svg>

          {/* Text */}
          <span>
            Copy Mode {itemCount > 1 ? `(${itemCount} items)` : ''}
          </span>

          {/* Keyboard Hint */}
          <div
            style={{
              backgroundColor: 'rgba(255,255,255,0.2)',
              padding: '4px 8px',
              borderRadius: '4px',
              fontSize: '12px',
              fontFamily: 'monospace',
            }}
          >
            Ctrl
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

/**
 * Enhanced LLM Hook
 * 
 * React hook for using the Confucian LLM Assistant services
 * across different wizard components.
 */

import { useState, useEffect, useCallback } from 'react';
import {
  MultiModelManager,
  PromptEngineeringEngine,
  ResponseParser,
  OllamaClient,
  type ReasoningResponse,
  type ModelMetadata,
  type TaskType,
} from '../services/llm';

export interface EnhancedLLMConfig {
  taskType?: TaskType;
  reasoningMode?: boolean;
  confucianPrinciples?: ('ren' | 'li' | 'yi' | 'zhi')[];
}

export interface UseEnhancedLLMReturn {
  // State
  isLoading: boolean;
  error: string | null;
  response: ReasoningResponse | null;
  availableModels: ModelMetadata[];
  currentModel: string;
  reasoningMode: boolean;
  
  // Actions
  generate: (prompt: string, systemPrompt?: string) => Promise<void>;
  setCurrentModel: (model: string) => void;
  setReasoningMode: (enabled: boolean) => void;
  clearResponse: () => void;
  clearError: () => void;
  
  // Services (for advanced usage)
  modelManager: MultiModelManager | null;
  promptEngine: PromptEngineeringEngine;
  parser: ResponseParser;
}

export function useEnhancedLLM(config: EnhancedLLMConfig = {}): UseEnhancedLLMReturn {
  const {
    taskType = 'general',
    reasoningMode: initialReasoningMode = true,
    confucianPrinciples = ['ren', 'li', 'yi', 'zhi'],
  } = config;

  // State
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [response, setResponse] = useState<ReasoningResponse | null>(null);
  const [availableModels, setAvailableModels] = useState<ModelMetadata[]>([]);
  const [currentModel, setCurrentModel] = useState('gemma3:4b');
  const [reasoningMode, setReasoningMode] = useState(initialReasoningMode);

  // Services (stable references)
  const [modelManager, setModelManager] = useState<MultiModelManager | null>(null);
  const [promptEngine] = useState(() => new PromptEngineeringEngine());
  const [parser] = useState(() => new ResponseParser());
  const [ollamaClient] = useState(() => new OllamaClient());

  // Initialize services
  useEffect(() => {
    const initializeServices = async () => {
      try {
        // Check Ollama health
        const isHealthy = await ollamaClient.healthCheck();
        if (!isHealthy) {
          setError('Ollama is not running. Please start Ollama to use AI assistance.');
          return;
        }

        // Initialize model manager
        const llmConfig = {
          provider: 'local' as const,
          model: currentModel,
          apiEndpoint: 'http://localhost:11434',
          availableModels: {
            vision: ['qwen3-vl:8b'],
            storytelling: ['llama3.1:8b', 'mistral:7b'],
            quick: ['gemma3:4b', 'gemma3:1b'],
            default: 'gemma3:4b',
          },
        };

        const manager = new MultiModelManager(llmConfig);
        setModelManager(manager);

        // Detect available models
        const models = await manager.detectAvailableModels();
        setAvailableModels(models);

        // Select best model for task type
        const recommendedModel = manager.getModelForTask(taskType);
        setCurrentModel(recommendedModel);
      } catch (err) {
        console.error('[useEnhancedLLM] Initialization error:', err);
        setError('Failed to initialize AI assistant');
      }
    };

    initializeServices();
  }, [ollamaClient, taskType]);

  // Generate response
  const generate = useCallback(
    async (prompt: string, systemPrompt?: string) => {
      if (!prompt.trim() || !modelManager) {
        setError('Invalid prompt or model manager not initialized');
        return;
      }

      setIsLoading(true);
      setError(null);
      setResponse(null);

      try {
        // Build enhanced prompt if reasoning mode is enabled
        const finalPrompt = reasoningMode && systemPrompt
          ? promptEngine.buildEnhancedPrompt(
              systemPrompt,
              taskType === 'storytelling' ? 'story' : 'world',
              prompt,
              {
                showThinking: true,
                principles: confucianPrinciples,
                includeExamples: true,
              }
            )
          : systemPrompt
          ? `${systemPrompt}\n\nUser Request: ${prompt}`
          : prompt;

        // Generate response
        const rawResponse = await ollamaClient.generate(
          currentModel,
          finalPrompt,
          { temperature: 0.7, maxTokens: 2000 }
        );

        // Parse response
        const parsedResponse = reasoningMode
          ? parser.parseResponse(rawResponse, currentModel)
          : {
              thinking: undefined,
              summary: rawResponse,
              rawResponse,
              modelUsed: currentModel,
              formatValid: false,
              timestamp: Date.now(),
            };

        setResponse(parsedResponse);
      } catch (err) {
        console.error('[useEnhancedLLM] Generation error:', err);
        setError(err instanceof Error ? err.message : 'Failed to generate response');
      } finally {
        setIsLoading(false);
      }
    },
    [
      modelManager,
      currentModel,
      reasoningMode,
      promptEngine,
      parser,
      ollamaClient,
      taskType,
      confucianPrinciples,
    ]
  );

  const clearResponse = useCallback(() => {
    setResponse(null);
  }, []);

  const clearError = useCallback(() => {
    setError(null);
  }, []);

  return {
    // State
    isLoading,
    error,
    response,
    availableModels,
    currentModel,
    reasoningMode,

    // Actions
    generate,
    setCurrentModel,
    setReasoningMode,
    clearResponse,
    clearError,

    // Services
    modelManager,
    promptEngine,
    parser,
  };
}

