// ============================================================================
// Error Handler Hook - Centralized Error Management for UI
// ============================================================================
// Provides centralized error handling for React components
// Supports error tracking, display, and recovery
//
// Features:
// - Centralized error state management
// - Error logging with context
// - Error recovery actions
// - User-friendly error messages
//
// Requirements: 7.1, 7.2, 7.3
// ============================================================================

import { useCallback, useState, useRef, useEffect } from 'react';
import { logger as Logger } from '../utils/logger';

// ============================================================================
// Types
// ============================================================================

export interface ErrorInfo {
  id: string;
  message: string;
  code?: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  context?: Record<string, unknown>;
  timestamp: Date;
  handled: boolean;
}

export interface ErrorHandlerState {
  errors: ErrorInfo[];
  currentError: ErrorInfo | null;
  hasErrors: boolean;
  errorCount: number;
}

export interface ErrorHandlerActions {
  addError: (error: Omit<ErrorInfo, 'id' | 'timestamp' | 'handled'>) => string;
  removeError: (id: string) => void;
  clearErrors: () => void;
  handleError: (error: unknown, context?: Record<string, unknown>) => string;
  dismissCurrentError: () => void;
  retryAction: (action: () => void) => void;
}

// ============================================================================
// Error Handler Hook
// ============================================================================

/**
 * Hook that provides centralized error management
 * 
 * Features:
 * - Track multiple errors with unique IDs
 * - Automatic error logging
 * - Error severity levels
 * - Recovery actions
 *
 * Requirements: 7.1, 7.2, 7.3
 */
export function useErrorHandler() {
  const [errors, setErrors] = useState<ErrorInfo[]>([]);
  const [currentError, setCurrentError] = useState<ErrorInfo | null>(null);
  const errorIdCounter = useRef(0);

  const generateErrorId = useCallback(() => {
    errorIdCounter.current += 1;
    return `error_${Date.now()}_${errorIdCounter.current}`;
  }, []);

  const addError = useCallback((error: Omit<ErrorInfo, 'id' | 'timestamp' | 'handled'>): string => {
    const id = generateErrorId();
    const newError: ErrorInfo = {
      ...error,
      id,
      timestamp: new Date(),
      handled: false,
    };

    Logger.error(`[ErrorHandler] ${error.severity.toUpperCase()} Error:`, {
      id,
      message: error.message,
      code: error.code,
      context: error.context,
    });

    setErrors((prev) => [...prev, newError]);
    
    if (error.severity === 'high' || error.severity === 'critical') {
      setCurrentError(newError);
    }

    return id;
  }, [generateErrorId]);

  const removeError = useCallback((id: string) => {
    setErrors((prev) => {
      const filtered = prev.filter((e) => e.id !== id);
      if (currentError?.id === id) {
        setCurrentError(filtered.length > 0 ? filtered[filtered.length - 1] : null);
      }
      return filtered;
    });
  }, [currentError]);

  const clearErrors = useCallback(() => {
    Logger.info('[ErrorHandler] Clearing all errors');
    setErrors([]);
    setCurrentError(null);
  }, []);

  const handleError = useCallback((error: unknown, context?: Record<string, unknown>): string => {
    let message: string;
    let severity: ErrorInfo['severity'] = 'medium';
    let code: string | undefined;

    if (error instanceof Error) {
      message = error.message;
      if (message.includes('network') || message.includes('fetch')) {
        severity = 'high';
        code = 'NETWORK_ERROR';
      } else if (message.includes('permission') || message.includes('access')) {
        severity = 'high';
        code = 'PERMISSION_DENIED';
      } else if (message.includes('validation') || message.includes('invalid')) {
        severity = 'low';
        code = 'VALIDATION_ERROR';
      } else if (message.includes('critical') || message.includes('fatal')) {
        severity = 'critical';
        code = 'CRITICAL_ERROR';
      }
    } else {
      message = String(error);
    }

    return addError({ message, code, severity, context });
  }, [addError]);

  const dismissCurrentError = useCallback(() => {
    if (currentError) {
      removeError(currentError.id);
    }
  }, [currentError, removeError]);

  const retryAction = useCallback((action: () => void) => {
    try {
      action();
    } catch (error) {
      handleError(error);
    }
  }, [handleError]);

  useEffect(() => {
    const fiveMinutesAgo = new Date(Date.now() - 5 * 60 * 1000);
    setErrors((prev) => {
      const filtered = prev.filter((e) => !e.handled || e.timestamp >= fiveMinutesAgo);
      if (currentError && !filtered.find((e) => e.id === currentError.id)) {
        setCurrentError(filtered.length > 0 ? filtered[filtered.length - 1] : null);
      }
      return filtered;
    });
  }, [currentError]);

  return {
    errors,
    currentError,
    hasErrors: errors.length > 0,
    errorCount: errors.length,
    addError,
    removeError,
    clearErrors,
    handleError,
    dismissCurrentError,
    retryAction,
  };
}

/**
 * useErrorHandling Hook
 * 
 * React hook for error handling with retry strategies and user notifications.
 */

import { useState, useCallback, useRef, useEffect } from 'react';
import {
  ErrorHandlingService,
  getErrorHandlingService,
  type AppError,
  type RetryConfig,
  type ErrorRecoveryAction,
} from '../services/errorHandlingService';

export interface UseErrorHandlingOptions {
  /**
   * Callback when error occurs
   */
  onError?: (error: AppError) => void;

  /**
   * Callback when error is recovered
   */
  onRecover?: () => void;

  /**
   * Auto-dismiss errors after timeout (ms)
   */
  autoDismissTimeout?: number;

  /**
   * Custom retry configuration
   */
  retryConfig?: Partial<RetryConfig>;
}

export interface UseErrorHandlingReturn {
  /**
   * Current error (if any)
   */
  error: AppError | null;

  /**
   * All errors in log
   */
  errors: AppError[];

  /**
   * Execute function with retry logic
   */
  withRetry: <T>(fn: () => Promise<T>, options?: Partial<RetryConfig>) => Promise<T>;

  /**
   * Execute function with timeout
   */
  withTimeout: <T>(fn: () => Promise<T>, timeoutMs: number) => Promise<T>;

  /**
   * Execute function with retry and timeout
   */
  withRetryAndTimeout: <T>(
    fn: () => Promise<T>,
    timeoutMs: number,
    retryOptions?: Partial<RetryConfig>
  ) => Promise<T>;

  /**
   * Handle error manually
   */
  handleError: (error: Error | string, context?: Record<string, unknown>) => AppError;

  /**
   * Clear current error
   */
  clearError: () => void;

  /**
   * Clear all errors
   */
  clearAllErrors: () => void;

  /**
   * Get recovery actions for current error
   */
  getRecoveryActions: () => ErrorRecoveryAction[];

  /**
   * Retry last failed operation
   */
  retry: () => Promise<void>;

  /**
   * Check if currently retrying
   */
  isRetrying: boolean;
}

export function useErrorHandling(
  options: UseErrorHandlingOptions = {}
): UseErrorHandlingReturn {
  const {
    onError,
    onRecover,
    autoDismissTimeout,
    retryConfig,
  } = options;

  // Service instance
  const serviceRef = useRef<ErrorHandlingService | null>(null);

  // State
  const [error, setError] = useState<AppError | null>(null);
  const [errors, setErrors] = useState<AppError[]>([]);
  const [isRetrying, setIsRetrying] = useState(false);

  // Last failed operation for retry
  const lastOperationRef = useRef<(() => Promise<any>) | null>(null);

  // Auto-dismiss timer
  const dismissTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Initialize service
  useEffect(() => {
    serviceRef.current = getErrorHandlingService();
  }, []);

  /**
   * Update errors from service
   */
  const updateErrors = useCallback(() => {
    if (serviceRef.current) {
      setErrors(serviceRef.current.getErrorLog());
    }
  }, []);

  /**
   * Handle error
   */
  const handleError = useCallback(
    (err: Error | string, context?: Record<string, unknown>): AppError => {
      if (!serviceRef.current) {
        const fallbackError: AppError = {
          id: 'fallback',
          message: typeof err === 'string' ? err : err.message,
          userMessage: 'An error occurred',
          severity: 'error',
          category: 'unknown',
          timestamp: new Date(),
          context,
          originalError: typeof err === 'string' ? new Error(err) : err,
          recoverable: false,
          retryable: false,
        };
        setError(fallbackError);
        return fallbackError;
      }

      const appError = serviceRef.current.createError(err, 'unknown', context);
      setError(appError);
      updateErrors();

      // Call onError callback
      if (onError) {
        onError(appError);
      }

      // Set auto-dismiss timer
      if (autoDismissTimeout && autoDismissTimeout > 0) {
        if (dismissTimerRef.current) {
          clearTimeout(dismissTimerRef.current);
        }
        dismissTimerRef.current = setTimeout(() => {
          setError(null);
        }, autoDismissTimeout);
      }

      return appError;
    },
    [onError, autoDismissTimeout, updateErrors]
  );

  /**
   * Execute with retry
   */
  const withRetry = useCallback(
    async <T,>(
      fn: () => Promise<T>,
      options?: Partial<RetryConfig>
    ): Promise<T> => {
      if (!serviceRef.current) {
        throw new Error('Error handling service not initialized');
      }

      // Store operation for retry
      lastOperationRef.current = fn;

      try {
        const config = { ...retryConfig, ...options };
        return await serviceRef.current.withRetry(fn, config);
      } catch (err) {
        if (err instanceof Error || typeof err === 'string') {
          handleError(err);
        }
        throw err;
      }
    },
    [retryConfig, handleError]
  );

  /**
   * Execute with timeout
   */
  const withTimeout = useCallback(
    async <T,>(fn: () => Promise<T>, timeoutMs: number): Promise<T> => {
      if (!serviceRef.current) {
        throw new Error('Error handling service not initialized');
      }

      try {
        return await serviceRef.current.withTimeout(fn, timeoutMs);
      } catch (err) {
        if (err instanceof Error || typeof err === 'string') {
          handleError(err);
        }
        throw err;
      }
    },
    [handleError]
  );

  /**
   * Execute with retry and timeout
   */
  const withRetryAndTimeout = useCallback(
    async <T,>(
      fn: () => Promise<T>,
      timeoutMs: number,
      retryOptions?: Partial<RetryConfig>
    ): Promise<T> => {
      if (!serviceRef.current) {
        throw new Error('Error handling service not initialized');
      }

      // Store operation for retry
      lastOperationRef.current = fn;

      try {
        const config = { ...retryConfig, ...retryOptions };
        return await serviceRef.current.withRetryAndTimeout(fn, timeoutMs, config);
      } catch (err) {
        if (err instanceof Error || typeof err === 'string') {
          handleError(err);
        }
        throw err;
      }
    },
    [retryConfig, handleError]
  );

  /**
   * Clear current error
   */
  const clearError = useCallback(() => {
    setError(null);
    if (dismissTimerRef.current) {
      clearTimeout(dismissTimerRef.current);
      dismissTimerRef.current = null;
    }
  }, []);

  /**
   * Clear all errors
   */
  const clearAllErrors = useCallback(() => {
    if (serviceRef.current) {
      serviceRef.current.clearErrorLog();
      updateErrors();
    }
    clearError();
  }, [clearError, updateErrors]);

  /**
   * Get recovery actions
   */
  const getRecoveryActions = useCallback((): ErrorRecoveryAction[] => {
    if (!error || !serviceRef.current) {
      return [];
    }

    const actions = serviceRef.current.getRecoveryActions(error);

    // Bind retry action
    const retryAction = actions.find((a) => a.label === 'Retry');
    if (retryAction) {
      retryAction.action = async () => {
        await retry();
      };
    }

    // Bind dismiss action
    const dismissAction = actions.find((a) => a.label === 'Dismiss');
    if (dismissAction) {
      dismissAction.action = clearError;
    }

    return actions;
  }, [error, clearError]);

  /**
   * Retry last operation
   */
  const retry = useCallback(async (): Promise<void> => {
    if (!lastOperationRef.current) {
      return;
    }

    setIsRetrying(true);
    clearError();

    try {
      await lastOperationRef.current();
      
      // Call onRecover callback
      if (onRecover) {
        onRecover();
      }
    } catch (err) {
      // Error will be handled by withRetry
    } finally {
      setIsRetrying(false);
    }
  }, [clearError, onRecover]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (dismissTimerRef.current) {
        clearTimeout(dismissTimerRef.current);
      }
    };
  }, []);

  return {
    error,
    errors,
    withRetry,
    withTimeout,
    withRetryAndTimeout,
    handleError,
    clearError,
    clearAllErrors,
    getRecoveryActions,
    retry,
    isRetrying,
  };
}

/**
 * useEventListener Hook
 * 
 * Safely attach and cleanup event listeners
 */

import { useEffect, useRef } from 'react';

/**
 * Hook to attach event listeners with automatic cleanup
 */
export function useEventListener<K extends keyof WindowEventMap>(
  eventName: K,
  handler: (this: Window, ev: WindowEventMap[K]) => unknown,
  element: Window | Document | HTMLElement = window,
  options?: boolean | AddEventListenerOptions
) {
  const savedHandler = useRef(handler);

  useEffect(() => {
    savedHandler.current = handler;
  }, [handler]);

  useEffect(() => {
    const isSupported = element && element.addEventListener;
    if (!isSupported) return;

    const eventListener = (event: Event) => savedHandler.current(event as any);

    element.addEventListener(eventName, eventListener, options);

    return () => {
      element.removeEventListener(eventName, eventListener, options);
    };
  }, [eventName, element, options]);
}

/**
 * Hook to attach multiple event listeners
 */
export function useEventListeners(
  listeners: Array<{
    eventName: keyof WindowEventMap;
    handler: (this: Window, ev: WindowEventMap[keyof WindowEventMap]) => unknown;
    element?: Window | Document | HTMLElement;
    options?: boolean | AddEventListenerOptions;
  }>
) {
  useEffect(() => {
    const cleanups: Array<() => void> = [];

    listeners.forEach(({ eventName, handler, element = window, options }) => {
      const eventListener = (event: Event) => handler(event as any);
      element.addEventListener(eventName, eventListener, options);
      cleanups.push(() => {
        element.removeEventListener(eventName, eventListener, options);
      });
    });

    return () => {
      cleanups.forEach((cleanup) => cleanup());
    };
  }, [listeners]);
}

/**
 * Hook to attach a resize listener with automatic cleanup
 */
export function useResizeListener(handler: () => void, element: Window | HTMLElement = window) {
  useEventListener('resize', () => handler(), element);
}

/**
 * Hook to attach a keyboard listener with automatic cleanup
 */
export function useKeyboardListener(
  handler: (event: KeyboardEvent) => void,
  options?: boolean | AddEventListenerOptions
) {
  useEventListener('keydown', (event) => handler(event as KeyboardEvent), window, options);
}

/**
 * Hook to attach a storage listener with automatic cleanup
 */
export function useStorageListener(handler: (event: StorageEvent) => void) {
  useEventListener('storage', (event) => handler(event as StorageEvent), window);
}

/**
 * Hook to attach a visibility change listener
 */
export function useVisibilityListener(handler: () => void) {
  useEventListener('visibilitychange', () => handler(), document);
}

/**
 * Hook to attach a beforeunload listener
 */
export function useBeforeUnloadListener(handler: (event: BeforeUnloadEvent) => void) {
  useEventListener('beforeunload', (event) => handler(event as BeforeUnloadEvent), window);
}

