/**
 * React Hook for Project Template Service
 * 
 * Provides real-time synchronization with ProjectTemplateService
 * using the Observer pattern.
 */

import { useState, useEffect, useCallback } from 'react';
import { ProjectTemplateService } from '@/services/asset-integration/ProjectTemplateService';
import type { ProjectTemplate } from '@/types/asset-integration';

// Get singleton instance
const templateService = ProjectTemplateService.getInstance();

// ============================================================================
// Hook: useProjectTemplate
// ============================================================================

export interface UseProjectTemplateReturn {
  template: ProjectTemplate | null;
  isLoading: boolean;
  error: Error | null;
  loadTemplate: (path: string) => Promise<void>;
  saveTemplate: (template: ProjectTemplate, path: string) => Promise<void>;
  createNewTemplate: (baseTemplate?: ProjectTemplate) => Promise<void>;
  clearCache: () => void;
}

/**
 * Hook for managing project templates with real-time synchronization
 * 
 * @param initialPath - Optional path to load template on mount
 * 
 * @example
 * ```typescript
 * function TemplateEditor() {
 *   const { 
 *     template, 
 *     isLoading, 
 *     loadTemplate, 
 *     saveTemplate 
 *   } = useProjectTemplate('/path/to/template.json');
 *   
 *   if (isLoading) return <div>Loading...</div>;
 *   if (!template) return <div>No template loaded</div>;
 *   
 *   return (
 *     <div>
 *       <h2>{template.project.name}</h2>
 *       <p>Version: {template.project.version}</p>
 *     </div>
 *   );
 * }
 * ```
 */
export function useProjectTemplate(initialPath?: string): UseProjectTemplateReturn {
  const [template, setTemplate] = useState<ProjectTemplate | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [currentPath, setCurrentPath] = useState<string | null>(initialPath || null);

  // Load initial template
  useEffect(() => {
    if (initialPath) {
      loadTemplate(initialPath);
    }
     
    // Only run when initialPath changes - loadTemplate is intentionally excluded
  }, [initialPath]);

  // Subscribe to template updates
  useEffect(() => {
    const unsubscribe = templateService.subscribeToTemplateUpdates((path, updatedTemplate) => {
      
      // Update if it's the current template
      if (currentPath && path === currentPath) {
        setTemplate(updatedTemplate);
      }
    });

    return unsubscribe;
  }, [currentPath]);

  // Load template
  const loadTemplate = useCallback(async (path: string) => {
    try {
      setIsLoading(true);
      setError(null);
      setCurrentPath(path);
      const loadedTemplate = await templateService.loadProjectTemplate(path);
      setTemplate(loadedTemplate);
    } catch (err) {
      console.error('[useProjectTemplate] Failed to load template:', err);
      setError(err as Error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Save template
  const saveTemplate = useCallback(async (templateToSave: ProjectTemplate, path: string) => {
    try {
      setIsLoading(true);
      setError(null);
      await templateService.saveProjectTemplate(templateToSave, path);
      setTemplate(templateToSave);
      setCurrentPath(path);
    } catch (err) {
      console.error('[useProjectTemplate] Failed to save template:', err);
      setError(err as Error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Create new template
  const createNewTemplate = useCallback(async (baseTemplate?: ProjectTemplate) => {
    try {
      setIsLoading(true);
      setError(null);
      const newTemplate = await templateService.createNewTemplate(baseTemplate);
      setTemplate(newTemplate);
      setCurrentPath(null); // New template doesn't have a path yet
    } catch (err) {
      console.error('[useProjectTemplate] Failed to create template:', err);
      setError(err as Error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Clear cache
  const clearCache = useCallback(() => {
    templateService.clearCache();
  }, []);

  return {
    template,
    isLoading,
    error,
    loadTemplate,
    saveTemplate,
    createNewTemplate,
    clearCache,
  };
}

// ============================================================================
// Hook: useTemplateCache
// ============================================================================

export interface UseTemplateCacheReturn {
  clearCache: () => void;
  cacheCleared: boolean;
}

/**
 * Hook for managing template cache
 * 
 * @example
 * ```typescript
 * function CacheManager() {
 *   const { clearCache, cacheCleared } = useTemplateCache();
 *   
 *   return (
 *     <div>
 *       <button onClick={clearCache}>Clear Cache</button>
 *       {cacheCleared && <p>Cache cleared!</p>}
 *     </div>
 *   );
 * }
 * ```
 */
export function useTemplateCache(): UseTemplateCacheReturn {
  const [cacheCleared, setCacheCleared] = useState(false);

  // Subscribe to cache updates
  useEffect(() => {
    const unsubscribe = templateService.subscribeToCacheUpdates((cleared) => {
      setCacheCleared(cleared);
      
      // Reset flag after 3 seconds
      if (cleared) {
        setTimeout(() => setCacheCleared(false), 3000);
      }
    });

    return unsubscribe;
  }, []);

  const clearCache = useCallback(() => {
    templateService.clearCache();
  }, []);

  return {
    clearCache,
    cacheCleared,
  };
}

// ============================================================================
// Hook: useTemplateList
// ============================================================================

export interface UseTemplateListReturn {
  templates: string[];
  isLoading: boolean;
  error: Error | null;
  refresh: () => Promise<void>;
}

/**
 * Hook for listing available templates
 * 
 * @example
 * ```typescript
 * function TemplateList() {
 *   const { templates, isLoading, refresh } = useTemplateList();
 *   
 *   if (isLoading) return <div>Loading...</div>;
 *   
 *   return (
 *     <div>
 *       <button onClick={refresh}>Refresh</button>
 *       <ul>
 *         {templates.map(path => <li key={path}>{path}</li>)}
 *       </ul>
 *     </div>
 *   );
 * }
 * ```
 */
export function useTemplateList(): UseTemplateListReturn {
  const [templates, setTemplates] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  const loadTemplates = useCallback(async () => {
    try {
      setIsLoading(true);
      setError(null);
      const availableTemplates = await templateService.listAvailableTemplates();
      setTemplates(availableTemplates);
    } catch (err) {
      console.error('[useTemplateList] Failed to load templates:', err);
      setError(err as Error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Load templates on mount
  useEffect(() => {
    loadTemplates();
  }, [loadTemplates]);

  return {
    templates,
    isLoading,
    error,
    refresh: loadTemplates,
  };
}

// ============================================================================
// Hook: useTemplateMetadata
// ============================================================================

export interface UseTemplateMetadataReturn {
  metadata: ProjectTemplate['project'] | null;
  updateMetadata: (updates: Partial<ProjectTemplate['project']>) => void;
}

/**
 * Hook for managing template metadata
 * 
 * @param template - Current template
 * @param onUpdate - Callback when metadata is updated
 * 
 * @example
 * ```typescript
 * function MetadataEditor({ template }: { template: ProjectTemplate }) {
 *   const { metadata, updateMetadata } = useTemplateMetadata(
 *     template,
 *   );
 *   
 *   return (
 *     <div>
 *       <input 
 *         value={metadata?.name || ''} 
 *         onChange={(e) => updateMetadata({ name: e.target.value })}
 *       />
 *     </div>
 *   );
 * }
 * ```
 */
export function useTemplateMetadata(
  template: ProjectTemplate | null,
  onUpdate?: (metadata: ProjectTemplate['project']) => void
): UseTemplateMetadataReturn {
  const [metadata, setMetadata] = useState<ProjectTemplate['project'] | null>(
    template?.project || null
  );

  // Update metadata when template changes
  useEffect(() => {
    if (template) {
      setMetadata(template.project);
    }
  }, [template]);

  const updateMetadata = useCallback((updates: Partial<ProjectTemplate['project']>) => {
    if (!metadata) return;
    
    const updatedMetadata = {
      ...metadata,
      ...updates,
      updated_at: new Date().toISOString(),
    };
    
    setMetadata(updatedMetadata);
    onUpdate?.(updatedMetadata);
  }, [metadata, onUpdate]);

  return {
    metadata,
    updateMetadata,
  };
}

/**
 * useReducedMotion Hook
 * 
 * Detects the user's prefers-reduced-motion system preference
 * and provides a boolean flag for conditional animation rendering.
 * 
 * Validates: Requirements 11.7
 */

import { useEffect, useState } from 'react';

/**
 * Hook to detect prefers-reduced-motion preference
 * 
 * @returns {boolean} true if user prefers reduced motion, false otherwise
 * 
 * @example
 * ```tsx
 * const prefersReducedMotion = useReducedMotion();
 * 
 * <motion.div
 *   animate={prefersReducedMotion ? { opacity: 1 } : { opacity: 1, scale: 1.1 }}
 * />
 * ```
 */
export function useReducedMotion(): boolean {
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);

  useEffect(() => {
    // Check if matchMedia is supported
    if (typeof window === 'undefined' || !window.matchMedia) {
      return;
    }

    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    
    // Set initial value
    setPrefersReducedMotion(mediaQuery.matches);

    // Listen for changes
    const handleChange = (event: MediaQueryListEvent) => {
      setPrefersReducedMotion(event.matches);
    };

    // Modern browsers
    if (mediaQuery.addEventListener) {
      mediaQuery.addEventListener('change', handleChange);
      return () => mediaQuery.removeEventListener('change', handleChange);
    }
    // Legacy browsers
    else if (mediaQuery.addListener) {
      mediaQuery.addListener(handleChange);
      return () => mediaQuery.removeListener(handleChange);
    }
  }, []);

  return prefersReducedMotion;
}

/**
 * Get animation duration based on reduced motion preference
 * 
 * @param normalDuration - Duration in seconds for normal motion
 * @param reducedDuration - Duration in seconds for reduced motion (default: 0)
 * @returns Duration to use based on user preference
 */
export function getAnimationDuration(
  normalDuration: number,
  reducedDuration: number = 0
): number {
  const prefersReducedMotion = useReducedMotion();
  return prefersReducedMotion ? reducedDuration : normalDuration;
}

/**
 * Get transition configuration based on reduced motion preference
 * 
 * @param normalTransition - Transition config for normal motion
 * @returns Transition config adjusted for user preference
 */
export function useAccessibleTransition(normalTransition: unknown): unknown {
  const prefersReducedMotion = useReducedMotion();
  
  if (prefersReducedMotion) {
    return {
      duration: 0,
      ease: 'linear',
    };
  }
  
  return normalTransition;
}

/**
 * useResponsiveGrid Hook
 * 
 * Manages responsive grid behavior based on viewport width.
 * Automatically adjusts columns, switches to list mode, and handles orientation changes.
 * 
 * Exigences: 12.1, 12.2, 12.3, 12.4, 12.7
 */

import { useState, useEffect, useCallback } from 'react';

export interface ResponsiveBreakpoint {
  name: 'mobile' | 'tablet' | 'desktop' | 'large';
  minWidth: number;
  maxWidth?: number;
  columns: number;
  useListMode: boolean;
}

export interface ResponsiveGridState {
  breakpoint: ResponsiveBreakpoint;
  columns: number;
  useListMode: boolean;
  width: number;
  height: number;
  orientation: 'portrait' | 'landscape';
  isFullscreen: boolean;
}

// Breakpoints configuration (Exigence 12.2, 12.3, 12.4)
export const BREAKPOINTS: ResponsiveBreakpoint[] = [
  {
    name: 'mobile',
    minWidth: 320,
    maxWidth: 767,
    columns: 1,
    useListMode: true
  },
  {
    name: 'tablet',
    minWidth: 768,
    maxWidth: 1023,
    columns: 2,
    useListMode: true
  },
  {
    name: 'desktop',
    minWidth: 1024,
    maxWidth: 1919,
    columns: 3,
    useListMode: false
  },
  {
    name: 'large',
    minWidth: 1920,
    columns: 4,
    useListMode: false
  }
];

/**
 * Get breakpoint for given width
 */
const getBreakpoint = (width: number): ResponsiveBreakpoint => {
  for (const breakpoint of BREAKPOINTS) {
    if (width >= breakpoint.minWidth && (!breakpoint.maxWidth || width <= breakpoint.maxWidth)) {
      return breakpoint;
    }
  }
  // Default to largest breakpoint
  return BREAKPOINTS[BREAKPOINTS.length - 1];
};

/**
 * Get orientation from dimensions
 * Exigence: 12.7
 */
const getOrientation = (width: number, height: number): 'portrait' | 'landscape' => {
  return width > height ? 'landscape' : 'portrait';
};

/**
 * Check if fullscreen
 * Exigence: 12.5
 */
const checkFullscreen = (): boolean => {
  return !!(
    document.fullscreenElement ||
    (document as any).webkitFullscreenElement ||
    (document as any).mozFullScreenElement ||
    (document as any).msFullscreenElement
  );
};

/**
 * Hook for responsive grid management
 */
export const useResponsiveGrid = (): ResponsiveGridState => {
  const [state, setState] = useState<ResponsiveGridState>(() => {
    const width = window.innerWidth;
    const height = window.innerHeight;
    const breakpoint = getBreakpoint(width);
    
    return {
      breakpoint,
      columns: breakpoint.columns,
      useListMode: breakpoint.useListMode,
      width,
      height,
      orientation: getOrientation(width, height),
      isFullscreen: checkFullscreen()
    };
  });

  /**
   * Handle window resize
   * Exigence: 12.1
   */
  const handleResize = useCallback(() => {
    const width = window.innerWidth;
    const height = window.innerHeight;
    const breakpoint = getBreakpoint(width);
    const orientation = getOrientation(width, height);
    const isFullscreen = checkFullscreen();

    setState(prev => {
      // Only update if something changed
      if (
        prev.width === width &&
        prev.height === height &&
        prev.breakpoint.name === breakpoint.name &&
        prev.isFullscreen === isFullscreen
      ) {
        return prev;
      }

      return {
        breakpoint,
        columns: breakpoint.columns,
        useListMode: breakpoint.useListMode,
        width,
        height,
        orientation,
        isFullscreen
      };
    });
  }, []);

  /**
   * Handle fullscreen change
   * Exigence: 12.5
   */
  const handleFullscreenChange = useCallback(() => {
    setState(prev => ({
      ...prev,
      isFullscreen: checkFullscreen()
    }));
  }, []);

  // Set up event listeners
  useEffect(() => {
    // Debounce resize events for performance
    let timeoutId: NodeJS.Timeout;
    const debouncedResize = () => {
      clearTimeout(timeoutId);
      timeoutId = setTimeout(handleResize, 150);
    };

    window.addEventListener('resize', debouncedResize);
    window.addEventListener('orientationchange', handleResize); // Exigence 12.7
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    document.addEventListener('webkitfullscreenchange', handleFullscreenChange);
    document.addEventListener('mozfullscreenchange', handleFullscreenChange);
    document.addEventListener('MSFullscreenChange', handleFullscreenChange);

    return () => {
      clearTimeout(timeoutId);
      window.removeEventListener('resize', debouncedResize);
      window.removeEventListener('orientationchange', handleResize);
      document.removeEventListener('fullscreenchange', handleFullscreenChange);
      document.removeEventListener('webkitfullscreenchange', handleFullscreenChange);
      document.removeEventListener('mozfullscreenchange', handleFullscreenChange);
      document.removeEventListener('MSFullscreenChange', handleFullscreenChange);
    };
  }, [handleResize, handleFullscreenChange]);

  return state;
};

/**
 * Hook for responsive grid with custom breakpoints
 */
export const useResponsiveGridWithBreakpoints = (
  customBreakpoints: ResponsiveBreakpoint[]
): ResponsiveGridState => {
  const [state, setState] = useState<ResponsiveGridState>(() => {
    const width = window.innerWidth;
    const height = window.innerHeight;
    const breakpoint = getBreakpoint(width);
    
    return {
      breakpoint,
      columns: breakpoint.columns,
      useListMode: breakpoint.useListMode,
      width,
      height,
      orientation: getOrientation(width, height),
      isFullscreen: checkFullscreen()
    };
  });

  const handleResize = useCallback(() => {
    const width = window.innerWidth;
    const height = window.innerHeight;
    
    // Find matching custom breakpoint
    let breakpoint = customBreakpoints.find(bp => 
      width >= bp.minWidth && (!bp.maxWidth || width <= bp.maxWidth)
    );
    
    if (!breakpoint) {
      breakpoint = customBreakpoints[customBreakpoints.length - 1];
    }
    
    const orientation = getOrientation(width, height);
    const isFullscreen = checkFullscreen();

    setState({
      breakpoint,
      columns: breakpoint.columns,
      useListMode: breakpoint.useListMode,
      width,
      height,
      orientation,
      isFullscreen
    });
  }, [customBreakpoints]);

  useEffect(() => {
    let timeoutId: NodeJS.Timeout;
    const debouncedResize = () => {
      clearTimeout(timeoutId);
      timeoutId = setTimeout(handleResize, 150);
    };

    window.addEventListener('resize', debouncedResize);
    window.addEventListener('orientationchange', handleResize);

    return () => {
      clearTimeout(timeoutId);
      window.removeEventListener('resize', debouncedResize);
      window.removeEventListener('orientationchange', handleResize);
    };
  }, [handleResize]);

  return state;
};

/**
 * Service Status Hook
 * 
 * Shared hook for checking Ollama and ComfyUI service connection status
 * Polls services every 30 seconds to keep status updated
 */

import { useState, useEffect } from 'react';

export type ServiceStatus = 'connected' | 'disconnected' | 'checking';

export interface ServiceState {
  ollama: ServiceStatus;
  comfyui: ServiceStatus;
}

/**
 * Hook to check and monitor service connection status
 * @returns Current status of Ollama and ComfyUI services
 */
export function useServiceStatus(): ServiceState {
  const [status, setStatus] = useState<ServiceState>({
    ollama: 'checking',
    comfyui: 'checking',
  });

  useEffect(() => {
    const checkServices = async () => {
      // Check Ollama status
      try {
        const ollamaResponse = await fetch('http://localhost:11434/api/tags', {
          method: 'GET',
          signal: AbortSignal.timeout(5000),
        });
        setStatus(prev => ({
          ...prev,
          ollama: ollamaResponse.ok ? 'connected' : 'disconnected',
        }));
      } catch (error) {
        // Silent failure - service not available
        setStatus(prev => ({ ...prev, ollama: 'disconnected' }));
      }

      // Check ComfyUI status
      try {
        // Import service dynamically to avoid circular dependencies
        const { getComfyUIServersService } = await import('@/services/comfyuiServersService');
        const service = getComfyUIServersService();
        const activeServer = service.getActiveServer();
        
        // Only check if a server is configured
        if (!activeServer) {
          setStatus(prev => ({ ...prev, comfyui: 'disconnected' }));
          return;
        }
        
        const serverUrl = activeServer.serverUrl.replace(/\/$/, '');

        const comfyResponse = await fetch(`${serverUrl}/system_stats`, {
          method: 'GET',
          signal: AbortSignal.timeout(5000),
        });
        setStatus(prev => ({
          ...prev,
          comfyui: comfyResponse.ok ? 'connected' : 'disconnected',
        }));
      } catch (error) {
        // Silent failure - service not available
        setStatus(prev => ({ ...prev, comfyui: 'disconnected' }));
      }
    };

    // Check immediately on mount
    checkServices();

    // Check every 30 seconds
    const interval = setInterval(checkServices, 30000);

    // Cleanup interval on unmount
    return () => clearInterval(interval);
  }, []);

  return status;
}

