/**
 * useSpring Hook
 * 
 * React hook for spring physics animations.
 * Provides declarative spring animations inspired by React Spring and Remotion.
 * 
 * Validates: Requirements 11.8 - Animation System
 * 
 * @example
 * ```tsx
 * const { value } = useSpring({
 *   from: { opacity: 0, transform: { scale: 0 } },
 *   to: { opacity: 1, transform: { scale: 1 } },
 *   config: Spring.gentle
 * });
 * 
 * return <div style={{ opacity: value.opacity, transform: `scale(${value.transform.scale})` }} />;
 * ```
 */

import { 
  useCallback, 
  useEffect, 
  useMemo, 
  useRef, 
  useState 
} from 'react';
import { 
  SpringConfig, 
  SpringAnimationConfig, 
  AnimationInstance,
  EasingFunction,
  Spring 
} from '../services/animation/AnimationTypes';
import { createSpringAnimation } from '../services/animation/SpringEngine';

/**
 * Animated value type - can be single value or object with nested values
 */
export type AnimatedValue<T> = T extends number 
  ? number 
  : T extends object 
    ? { [K in keyof T]: AnimatedValue<T[K]> }
    : T;

/**
 * Spring animation hook return type
 */
export interface UseSpringReturn<T> {
  value: AnimatedValue<T>;
  isAnimating: boolean;
  start: () => void;
  stop: () => void;
  reset: () => void;
}

/**
 * Configuration for single spring value
 */
export interface UseSpringSingleConfig {
  from: number;
  to: number;
  config?: Partial<SpringConfig>;
  delay?: number;
  loop?: boolean | number;
  direction?: 'normal' | 'reverse' | 'alternate';
  immediate?: boolean;
}

/**
 * Configuration for object spring values
 */
export interface UseSpringObjectConfig<T extends object> {
  from: T;
  to: T;
  config?: SpringConfig | { [K in keyof T]?: Partial<SpringConfig> };
  delay?: number | { [K in keyof T]?: number };
  loop?: boolean | number;
  direction?: 'normal' | 'reverse' | 'alternate';
  immediate?: boolean;
}

/**
 * Hook for single value spring animation
 */
export function useSpring(
  config: UseSpringSingleConfig
): UseSpringReturn<number> {
  const [value, setValue] = useState(config.from);
  const [isAnimating, setIsAnimating] = useState(false);
  const animationRef = useRef<AnimationInstance<number> | null>(null);
  const currentFromRef = useRef(config.from);
  const currentToRef = useRef(config.to);

  // Create animation instance
  const createAnimation = useCallback((from: number, to: number) => {
    return createSpringAnimation({
      id: `spring-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      from,
      to,
      config: config.config as Partial<SpringConfig>,
      delay: config.delay,
      loop: config.loop,
      direction: config.direction,
      duration: undefined // Spring animations don't use fixed duration
    });
  }, [config.config, config.delay, config.loop, config.direction]);

  // Start animation
  const start = useCallback(() => {
    // Cancel any existing animation
    if (animationRef.current) {
      animationRef.current.stop();
    }

    const animation = createAnimation(currentFromRef.current, currentToRef.current);
    animationRef.current = animation;

    animation.onUpdate = (newValue: number) => {
      setValue(newValue);
    };

    animation.onComplete = () => {
      setIsAnimating(false);
    };

    setIsAnimating(true);
    animation.start();
  }, [createAnimation]);

  // Stop animation
  const stop = useCallback(() => {
    if (animationRef.current) {
      animationRef.current.stop();
      animationRef.current = null;
    }
    setIsAnimating(false);
  }, []);

  // Reset animation
  const reset = useCallback(() => {
    stop();
    setValue(config.from);
    currentFromRef.current = config.from;
    currentToRef.current = config.to;
  }, [config.from, config.to, stop]);

  // Effect to handle immediate animations
  useEffect(() => {
    if (config.immediate) {
      setValue(config.to);
      currentFromRef.current = config.to;
      currentToRef.current = config.to;
    }
  }, [config.to, config.immediate]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (animationRef.current) {
        animationRef.current.stop();
      }
    };
  }, []);

  return {
    value: value as number,
    isAnimating,
    start,
    stop,
    reset
  };
}

/**
 * Hook for object value spring animations
 */
export function useSpringObject<T extends object>(
  config: UseSpringObjectConfig<T>
): UseSpringReturn<T> {
  const [values, setValues] = useState<T>(config.from);
  const [isAnimating, setIsAnimating] = useState(false);
  const animationRefs = useRef<Map<keyof T, AnimationInstance<number>>>(new Map());
  const currentFromRef = useRef<T>(config.from);
  const currentToRef = useRef<T>(config.to);

  // Get config for a specific key
  const getConfigForKey = useCallback((key: keyof T): Partial<SpringConfig> => {
    if (!config.config) return {};
    if (config.config instanceof Object && !(config.config as SpringConfig).mass) {
      // config is object with per-key configs
      return (config.config as { [K in keyof T]?: Partial<SpringConfig> })[key] || {};
    }
    // config is a single SpringConfig
    return config.config as Partial<SpringConfig>;
  }, [config.config]);

  // Get delay for a specific key
  const getDelayForKey = useCallback((key: keyof T): number | undefined => {
    if (!config.delay) return undefined;
    if (typeof config.delay === 'number') return config.delay;
    return config.delay[key];
  }, [config.delay]);

  // Create animation for a specific key
  const createAnimationForKey = useCallback((key: keyof T, from: number, to: number) => {
    return createSpringAnimation({
      id: `spring-${String(key)}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      from,
      to,
      config: getConfigForKey(key),
      delay: getDelayForKey(key),
      loop: config.loop,
      direction: config.direction
    });
  }, [getConfigForKey, getDelayForKey, config.loop, config.direction]);

  // Start animation for all keys
  const start = useCallback(() => {
    // Stop any existing animations
    animationRefs.current.forEach(anim => anim.stop());
    animationRefs.current.clear();

    const keys = Object.keys(config.to) as (keyof T)[];
    let completedCount = 0;
    const totalCount = keys.length;

    keys.forEach((key) => {
      const fromValue = currentFromRef.current[key] as number;
      const toValue = currentToRef.current[key] as number;

      const animation = createAnimationForKey(key, fromValue, toValue);
      animationRefs.current.set(key, animation);

      animation.onUpdate = (newValue: number) => {
        setValues(prev => ({
          ...prev,
          [key]: newValue
        }));
      };

      animation.onComplete = () => {
        completedCount++;
        if (completedCount === totalCount) {
          setIsAnimating(false);
        }
      };

      setIsAnimating(true);
      animation.start();
    });
  }, [config.to, createAnimationForKey]);

  // Stop all animations
  const stop = useCallback(() => {
    animationRefs.current.forEach(anim => anim.stop());
    animationRefs.current.clear();
    setIsAnimating(false);
  }, []);

  // Reset to initial values
  const reset = useCallback(() => {
    stop();
    setValues(config.from);
    currentFromRef.current = config.from;
    currentToRef.current = config.to;
  }, [config.from, config.to, stop]);

  // Effect to handle immediate animations
  useEffect(() => {
    if (config.immediate) {
      setValues(config.to);
      currentFromRef.current = config.to;
      currentToRef.current = config.to;
    }
  }, [config.to, config.immediate]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      animationRefs.current.forEach(anim => anim.stop());
    };
  }, []);

  return {
    value: values,
    isAnimating,
    start,
    stop,
    reset
  };
}

/**
 * Trail animation - stagger animations for multiple children
 */
export function useSpringTrail<T>(
  items: T[],
  config: {
    from: T extends object ? { [K in keyof T]: number } : number;
    to: T extends object ? { [K in keyof T]: number } : number;
    config?: Partial<SpringConfig>;
    delay?: number;
    stagger?: number;
  }
): {
  values: Array<T extends object ? { [K in keyof T]: number } : number>;
  starts: (() => void)[];
  stops: (() => void)[];
} {
  const [values, setValues] = useState<Array<T extends object ? { [K in keyof T]: number } : number>>(
    items.map(() => config.from as any)
  );
  
  const animationRefs = useRef<Map<number, AnimationInstance<number>>>(new Map());
  const startsRef = useRef<Array<() => void>>([]);
  const stopsRef = useRef<Array<() => void>>([]);

  // Create animations for each item
  useMemo(() => {
    startsRef.current = [];
    stopsRef.current = [];

    items.forEach((_, index) => {
      const from = config.from as any;
      const to = config.to as any;
      const delay = (config.delay || 0) + (config.stagger || 0) * index;

      const animation = createSpringAnimation({
        id: `trail-${index}-${Date.now()}`,
        from: typeof from === 'number' ? from : Object.values(from)[0] as number,
        to: typeof to === 'number' ? to : Object.values(to)[0] as number,
        config: config.config,
        delay
      });

      animationRefs.current.set(index, animation);

      startsRef.current.push(() => {
        animation.onUpdate = (newValue: number) => {
          setValues(prev => {
            const newValues = [...prev];
            if (typeof config.from === 'object' && config.from !== null) {
              const keys = Object.keys(config.from) as (keyof typeof config.from)[];
              newValues[index] = { ...newValues[index], [keys[0]]: newValue } as any;
            } else {
              newValues[index] = newValue as any;
            }
            return newValues;
          });
        };

        animation.start();
      });

      stopsRef.current.push(() => {
        animation.stop();
      });
    });
  }, [items.length]);

  return {
    values,
    starts: startsRef.current,
    stops: stopsRef.current
  };
}

/**
 * Transition - animate elements entering/exiting
 */
export interface UseSpringTransitionConfig<T> {
  items: T[];
  keys: (item: T) => string;
  from?: { [K in keyof T]?: number } | number;
  enter?: { [K in keyof T]?: number } | number;
  leave?: { [K in keyof T]?: number } | number;
  config?: Partial<SpringConfig>;
  stagger?: number;
}

export function useSpringTransition<T>(config: UseSpringTransitionConfig<T>) {
  const [mountedItems, setMountedItems] = useState<Map<string, T>>(new Map());
  
  // Add items
  const add = useCallback((item: T) => {
    setMountedItems(prev => new Map(prev).set(config.keys(item), item));
  }, [config.keys]);

  // Remove items
  const remove = useCallback((key: string) => {
    setMountedItems(prev => {
      const newMap = new Map(prev);
      newMap.delete(key);
      return newMap;
    });
  }, []);

  return {
    mountedItems: Array.from(mountedItems.entries()).map(([key, item]) => ({
      key,
      item,
      add: () => add(item),
      remove: () => remove(key)
    }))
  };
}

export { Spring };

/**
 * useStateRecovery Hook
 * 
 * React hook for managing wizard state recovery.
 * 
 * Requirements: 5.6
 */

import { useState, useEffect, useCallback } from 'react';
import {
  loadWizardStateWithValidation,
  clearWizardState,
  type LoadStateResult,
} from '../utils/wizardStorage';
import {
  getStateValidationService,
  type ValidationResult,
} from '../services/wizard/stateValidationService';

export interface UseStateRecoveryOptions {
  /**
   * Wizard type
   */
  wizardType: 'world' | 'character' | 'sequence-plan';

  /**
   * Auto-check on mount
   */
  autoCheck?: boolean;

  /**
   * Callback when corruption is detected
   */
  onCorruptionDetected?: (result: LoadStateResult<any>) => void;

  /**
   * Callback when recovery is successful
   */
  onRecoverySuccess?: () => void;

  /**
   * Callback when recovery fails
   */
  onRecoveryFailed?: (error: Error) => void;
}

export interface UseStateRecoveryReturn {
  /**
   * Whether state is corrupted
   */
  isCorrupted: boolean;

  /**
   * Validation result
   */
  validationResult: ValidationResult | null;

  /**
   * Load state result
   */
  loadResult: LoadStateResult<any> | null;

  /**
   * Check for corruption
   */
  checkForCorruption: () => Promise<void>;

  /**
   * Attempt to recover state
   */
  attemptRecovery: () => Promise<boolean>;

  /**
   * Reset to clean state
   */
  resetState: () => void;

  /**
   * Dismiss corruption warning
   */
  dismissWarning: () => void;

  /**
   * Show recovery dialog
   */
  showRecoveryDialog: boolean;

  /**
   * Set show recovery dialog
   */
  setShowRecoveryDialog: (show: boolean) => void;
}

export function useStateRecovery(
  options: UseStateRecoveryOptions
): UseStateRecoveryReturn {
  const {
    wizardType,
    autoCheck = true,
    onCorruptionDetected,
    onRecoverySuccess,
    onRecoveryFailed,
  } = options;

  const [isCorrupted, setIsCorrupted] = useState(false);
  const [validationResult, setValidationResult] = useState<ValidationResult | null>(null);
  const [loadResult, setLoadResult] = useState<LoadStateResult<any> | null>(null);
  const [showRecoveryDialog, setShowRecoveryDialog] = useState(false);

  const validationService = getStateValidationService();

  /**
   * Check for corruption
   */
  const checkForCorruption = useCallback(async () => {
    const result = loadWizardStateWithValidation(wizardType);
    setLoadResult(result);

    if (result.isCorrupted) {
      setIsCorrupted(true);

      // Perform detailed validation if state exists
      if (result.state) {
        const validation = validationService.validateState(result.state);
        setValidationResult(validation);
      } else {
        // Create validation result from load result
        setValidationResult({
          isValid: false,
          errors: result.errors,
          warnings: result.warnings,
          canRecover: result.canRecover,
          recoveryStrategy: result.canRecover ? 'partial' : 'reset',
        });
      }

      setShowRecoveryDialog(true);

      if (onCorruptionDetected) {
        onCorruptionDetected(result);
      }
    } else {
      setIsCorrupted(false);
      setValidationResult(null);
    }
  }, [wizardType, validationService, onCorruptionDetected]);

  /**
   * Attempt to recover state
   */
  const attemptRecovery = useCallback(async (): Promise<boolean> => {
    if (!loadResult?.state) {
      return false;
    }

    try {
      const recovered = validationService.recoverState(loadResult.state);

      if (!recovered) {
        throw new Error('Recovery failed: unable to recover state');
      }

      // State was recovered successfully
      setIsCorrupted(false);
      setValidationResult(null);
      setShowRecoveryDialog(false);

      if (onRecoverySuccess) {
        onRecoverySuccess();
      }

      return true;
    } catch (error) {
      console.error('State recovery failed:', error);

      if (onRecoveryFailed && error instanceof Error) {
        onRecoveryFailed(error);
      }

      return false;
    }
  }, [loadResult, validationService, onRecoverySuccess, onRecoveryFailed]);

  /**
   * Reset to clean state
   */
  const resetState = useCallback(() => {
    clearWizardState(wizardType);
    setIsCorrupted(false);
    setValidationResult(null);
    setLoadResult(null);
    setShowRecoveryDialog(false);
  }, [wizardType]);

  /**
   * Dismiss warning
   */
  const dismissWarning = useCallback(() => {
    setShowRecoveryDialog(false);
  }, []);

  // Auto-check on mount
  useEffect(() => {
    if (autoCheck) {
      checkForCorruption();
    }
  }, [autoCheck, checkForCorruption]);

  return {
    isCorrupted,
    validationResult,
    loadResult,
    checkForCorruption,
    attemptRecovery,
    resetState,
    dismissWarning,
    showRecoveryDialog,
    setShowRecoveryDialog,
  };
}

import { useEffect, useRef } from 'react';
import { useAppStore } from '@/stores/useAppStore';
import type { GenerationTask } from '@/types';

/**
 * Hook for executing tasks in queue order
 * Processes pending tasks sequentially
 */
export function useTaskExecution() {
  const { taskQueue, updateTask } = useAppStore();
  const isProcessingRef = useRef(false);

  useEffect(() => {
    // Find the next pending task
    const nextTask = taskQueue.find((task) => task.status === 'pending');

    // If there's a pending task and we're not already processing
    if (nextTask && !isProcessingRef.current) {
      // Check if there's already a processing task
      const hasProcessingTask = taskQueue.some((task) => task.status === 'processing');

      if (!hasProcessingTask) {
        executeTask(nextTask);
      }
    }
  }, [taskQueue]);

  const executeTask = async (task: GenerationTask) => {
    isProcessingRef.current = true;

    try {
      // Update task status to processing
      const updatedTask: GenerationTask = {
        ...task,
        status: 'processing',
        startedAt: new Date(),
      };

      // In a real implementation, this would call the backend
      // For now, we'll simulate task execution
      await simulateTaskExecution(updatedTask);

      // Update task status to completed
      const completedTask: GenerationTask = {
        ...updatedTask,
        status: 'completed',
        completedAt: new Date(),
      };

      // Note: In real implementation, updateTask would be called here
      // updateTask(completedTask.id, completedTask);
    } catch (error) {
      // Update task status to failed
      const failedTask: GenerationTask = {
        ...task,
        status: 'failed',
        error: error instanceof Error ? error.message : 'Unknown error',
      };

      // Note: In real implementation, updateTask would be called here
      // updateTask(failedTask.id, failedTask);
    } finally {
      isProcessingRef.current = false;
    }
  };

  /**
   * Simulate task execution (replace with real backend calls)
   */
  const simulateTaskExecution = async (task: GenerationTask): Promise<void> => {
    return new Promise((resolve, reject) => {
      // Simulate processing time based on task type
      const processingTime = {
        grid: 3000,
        promotion: 2000,
        refine: 2500,
        qa: 1500,
      }[task.type];

      setTimeout(() => {
        // Simulate 90% success rate
        if (Math.random() > 0.1) {
          resolve();
        } else {
          reject(new Error('Simulated task failure'));
        }
      }, processingTime);
    });
  };

  return {
    isProcessing: isProcessingRef.current,
  };
}

/**
 * React Hook for Text Typography
 * 
 * Provides a convenient React hook for integrating text typography
 * animations into StoryCore components.
 */

import { useState, useEffect, useCallback, useMemo } from 'react';
import {
  TextAnimationConfig,
  TextAnimationType,
  TextPreset,
  TextTypographyState,
  EasingType
} from '../services/text-typography/TextTypographyTypes';
import {
  textTypographyService,
  defaultTextAnimationConfig
} from '../services/text-typography/TextTypographyService';

// ============================================================================
// Hook Return Type
// ============================================================================

interface UseTextTypographyReturn {
  // State
  state: TextTypographyState;
  presets: TextPreset[];
  animationProgress: number;
  isComplete: boolean;
  
  // Preset Management
  getPreset: (id: string) => TextPreset | undefined;
  applyPreset: (text: string, presetId: string) => { style: React.CSSProperties; config: TextAnimationConfig };
  
  // Animation Control
  playAnimation: (text: string, config?: Partial<TextAnimationConfig>) => void;
  playWithPreset: (text: string, presetId: string) => void;
  pauseAnimation: () => void;
  resumeAnimation: () => void;
  stopAnimation: () => void;
  setAnimationProgress: (progress: number) => void;
  
  // Utility
  getAnimationCSS: (config: TextAnimationConfig) => string;
  getAnimationStyle: (config: TextAnimationConfig, text: string) => React.CSSProperties;
}

// ============================================================================
// Hook Implementation
// ============================================================================

export function useTextTypography(): UseTextTypographyReturn {
  // State
  const [state, setState] = useState<TextTypographyState>(textTypographyService.getState());
  const [animationProgress, setAnimationProgress] = useState(0);
  const [isComplete, setIsComplete] = useState(false);

  // ==========================================================================
  // Sync State
  // ==========================================================================

  useEffect(() => {
    const interval = setInterval(() => {
      setState(textTypographyService.getState());
      setAnimationProgress(textTypographyService.getAnimationProgress());
      setIsComplete(textTypographyService.isAnimationComplete());
    }, 50);

    return () => clearInterval(interval);
     
    // Intentionally run only on mount - state sync interval should start once
  }, []);

  // ==========================================================================
  // Preset Management
  // ==========================================================================

  const getPreset = useCallback((id: string) => {
    return textTypographyService.getPreset(id);
  }, []);

  const presets = useMemo(() => {
    return textTypographyService.getAllPresets();
  }, []);

  const applyPreset = useCallback((text: string, presetId: string) => {
    try {
      const result = textTypographyService.applyPreset(text, presetId);
      return {
        style: result as unknown as React.CSSProperties,
        config: result as unknown as TextAnimationConfig
      };
    } catch {
      // Return default if preset not found
      return {
        style: {},
        config: defaultTextAnimationConfig
      };
    }
  }, []);

  // ==========================================================================
  // Animation Control
  // ==========================================================================

  const playAnimation = useCallback((text: string, config?: Partial<TextAnimationConfig>) => {
    const fullConfig: TextAnimationConfig = {
      ...defaultTextAnimationConfig,
      ...config,
      type: config?.type || 'fadeIn'
    };
    textTypographyService.playAnimation(text, fullConfig);
  }, []);

  const playWithPreset = useCallback((text: string, presetId: string) => {
    const preset = textTypographyService.getPreset(presetId);
    if (!preset) return;

    const config: TextAnimationConfig = {
      ...defaultTextAnimationConfig,
      ...preset.animation,
      type: preset.animation.type || 'fadeIn'
    };
    textTypographyService.playAnimation(text, config);
  }, []);

  const pauseAnimation = useCallback(() => {
    textTypographyService.pauseAnimation();
  }, []);

  const resumeAnimation = useCallback(() => {
    textTypographyService.resumeAnimation();
  }, []);

  const stopAnimation = useCallback(() => {
    textTypographyService.stopAnimation();
    setAnimationProgress(0);
    setIsComplete(false);
  }, []);

  const setAnimationProgressCallback = useCallback((progress: number) => {
    textTypographyService.setAnimationProgress(progress);
    setAnimationProgress(progress);
  }, []);

  // ==========================================================================
  // Utility
  // ==========================================================================

  const getAnimationCSS = useCallback((config: TextAnimationConfig) => {
    return textTypographyService.getAnimationCSS(config, '');
  }, []);

  const getAnimationStyle = useCallback((config: TextAnimationConfig, text: string): React.CSSProperties => {
    const progress = animationProgress;
    const easing = getEasingFunction(config.easing);
    const easedProgress = easing(progress);

    const styles: React.CSSProperties = {};

    switch (config.type) {
      case 'fadeIn':
        styles.opacity = easedProgress;
        break;
      case 'fadeOut':
        styles.opacity = 1 - easedProgress;
        break;
      case 'slideUp':
        styles.opacity = easedProgress;
        styles.transform = `translateY(${(1 - easedProgress) * 50}px)`;
        break;
      case 'slideDown':
        styles.opacity = easedProgress;
        styles.transform = `translateY(${(1 - easedProgress) * -50}px)`;
        break;
      case 'slideLeft':
        styles.opacity = easedProgress;
        styles.transform = `translateX(${(1 - easedProgress) * 50}px)`;
        break;
      case 'slideRight':
        styles.opacity = easedProgress;
        styles.transform = `translateX(${(1 - easedProgress) * -50}px)`;
        break;
      case 'scaleIn':
        styles.opacity = easedProgress;
        styles.transform = `scale(${0.5 + easedProgress * 0.5})`;
        break;
      case 'scaleOut':
        styles.opacity = 1 - easedProgress;
        styles.transform = `scale(${1 + easedProgress * 0.5})`;
        break;
      case 'blurIn':
        styles.opacity = easedProgress;
        styles.filter = `blur(${(1 - easedProgress) * 10}px)`;
        break;
      case 'bounce':
        if (progress < 0.6) {
          styles.opacity = progress / 0.6;
          styles.transform = `translateY(${(1 - progress / 0.6) * -50}px)`;
        } else if (progress < 0.8) {
          styles.transform = `translateY(${(progress - 0.6) * 50}px)`;
        } else if (progress < 1) {
          styles.transform = `translateY(${(1 - progress) * -5}px)`;
        } else {
          styles.transform = 'translateY(0)';
        }
        styles.opacity = Math.min(1, progress * 1.67);
        break;
      default:
        styles.opacity = easedProgress;
    }

    if (config.fillMode === 'forwards' && isComplete) {
      // Apply final state
      switch (config.type) {
        case 'slideUp':
        case 'slideDown':
        case 'slideLeft':
        case 'slideRight':
          styles.transform = 'translateX(0) translateY(0)';
          break;
        case 'scaleIn':
          styles.transform = 'scale(1)';
          break;
        case 'scaleOut':
          styles.transform = 'scale(1)';
          styles.opacity = 0;
          break;
        case 'blurIn':
          styles.filter = 'blur(0)';
          break;
      }
    }

    return styles;
  }, [animationProgress, isComplete]);

  // ==========================================================================
  // Return
  // ==========================================================================

  return {
    state,
    presets,
    animationProgress,
    isComplete,
    getPreset,
    applyPreset,
    playAnimation,
    playWithPreset,
    pauseAnimation,
    resumeAnimation,
    stopAnimation,
    setAnimationProgress: setAnimationProgressCallback,
    getAnimationCSS,
    getAnimationStyle
  };
}

// ============================================================================
// Easing Function Helper
// ============================================================================

function getEasingFunction(easing: EasingType): (t: number) => number {
  const functions: Record<EasingType, (t: number) => number> = {
    linear: (t: number) => t,
    ease: (t: number) => t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t,
    easeIn: (t: number) => t * t,
    easeOut: (t: number) => t * (2 - t),
    easeInOut: (t: number) => t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t,
    easeInQuad: (t: number) => t * t,
    easeOutQuad: (t: number) => t * (2 - t),
    easeInOutQuad: (t: number) => t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t,
    easeInCubic: (t: number) => t * t * t,
    easeOutCubic: (t: number) => (--t) * t * t + 1,
    easeInOutCubic: (t: number) => t < 0.5 ? 4 * t * t * t : (t - 1) * (2 * t - 2) * (2 * t - 2) + 1,
    easeInQuart: (t: number) => t * t * t * t,
    easeOutQuart: (t: number) => 1 - (--t) * t * t * t,
    easeInOutQuart: (t: number) => t < 0.5 ? 8 * t * t * t * t : 1 - 8 * (--t) * t * t * t,
    elastic: (t: number) => {
      const c4 = (2 * Math.PI) / 3;
      return t === 0 ? 0 : t === 1 ? 1 : Math.pow(2, -10 * t) * Math.sin((t * 10 - 0.75) * c4) + 1;
    },
    bounce: (t: number) => {
      const n1 = 7.5625;
      const d1 = 2.75;
      if (t < 1 / d1) return n1 * t * t;
      if (t < 2 / d1) return n1 * (t -= 1.5 / d1) * t + 0.75;
      if (t < 2.5 / d1) return n1 * (t -= 2.25 / d1) * t + 0.9375;
      return n1 * (t -= 2.625 / d1) * t + 0.984375;
    },
    smoothstep: (t: number) => t * t * (3 - 2 * t),
    smootherstep: (t: number) => t * t * t * (t * (t * 6 - 15) + 10)
  };

  return functions[easing] || functions.linear;
}

// ============================================================================
// Hook for Animated Text
// ============================================================================

export function useAnimatedText(
  text: string,
  animationType: TextAnimationType = 'fadeIn',
  duration: number = 1000
) {
  const {
    animationProgress,
    isComplete,
    playAnimation,
    stopAnimation,
    getAnimationStyle
  } = useTextTypography();

  useEffect(() => {
    playAnimation(text, {
      type: animationType,
      duration
    });
    return stopAnimation;
  }, [text, animationType, duration, playAnimation, stopAnimation]);

  const displayedText = text;
  
  const style = useMemo(() => {
    const config: TextAnimationConfig = {
      type: animationType,
      duration,
      delay: 0,
      easing: 'easeOut',
      direction: 'normal',
      fillMode: 'forwards',
      iterations: 1,
      trigger: 'auto'
    };
    return getAnimationStyle(config, text);
  }, [animationType, duration, text, getAnimationStyle]);

  return {
    displayedText,
    progress: animationProgress,
    isComplete,
    style
  };
}

// ============================================================================
// Default Export
// ============================================================================

export { defaultTextAnimationConfig };
export default useTextTypography;

