/**
 * React Hook for Three.js Integration
 * 
 * Provides a convenient React hook for integrating Three.js 3D scenes
 * into StoryCore components with automatic lifecycle management.
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { 
  ThreeJsSceneConfig, 
  CameraConfig, 
  ModelConfig, 
  AnimationConfig,
  CameraAnimationConfig,
  EffectComposerConfig,
  ThreeJsViewerProps,
  ThreeJsState,
  ModelLoadResult
} from '../services/threejs/ThreeJsTypes';
import { 
  threeJsService, 
  defaultSceneConfig, 
  defaultCameraConfig 
} from '../services/threejs/ThreeJsService';

// ============================================================================
// Hook Return Type
// ============================================================================

interface UseThreeJsReturn {
  // State
  state: ThreeJsState;
  canvasRef: React.RefObject<HTMLCanvasElement | null>;
  isReady: boolean;
  error: string | null;
  
  // Scene Management
  initializeScene: (config?: Partial<ThreeJsSceneConfig>) => Promise<void>;
  disposeScene: () => void;
  
  // Model Management
  loadModel: (id: string, config: ModelConfig) => Promise<ModelLoadResult>;
  unloadModel: (id: string) => void;
  
  // Animation
  playAnimation: (modelId: string, config: AnimationConfig) => void;
  stopAnimation: (modelId: string) => void;
  
  // Camera
  animateCamera: (config: CameraAnimationConfig) => void;
  stopCameraAnimation: () => void;
  updateCameraPosition: (position: [number, number, number]) => void;
  
  // Rendering
  renderFrame: () => void;
  startRendering: () => void;
  stopRendering: () => void;
  
  // Effects
  updateEffects: (config: Partial<EffectComposerConfig>) => void;
}

// ============================================================================
// Hook Implementation
// ============================================================================

export function useThreeJs(props: ThreeJsViewerProps = {}): UseThreeJsReturn {
  // State
  const [state, setState] = useState<ThreeJsState>({
    sceneConfig: null,
    models: new Map(),
    cameraConfig: null,
    activeAnimation: null,
    isReady: false,
    isRendering: false,
    error: null
  });

  // Refs
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const initializedRef = useRef(false);
  const frameCountRef = useRef(0);

  // ==========================================================================
  // Event Handlers
  // ==========================================================================

  const handleSceneReady = useCallback(() => {
    setState(prev => ({ ...prev, isReady: true, error: null }));
    props.onReady?.();
  }, [props.onReady]);

  const handleSceneError = useCallback((error: string) => {
    setState(prev => ({ ...prev, error, isReady: false }));
    props.onError?.(error);
  }, [props.onError]);

  const handleFrameRendered = useCallback(() => {
    frameCountRef.current += 1;
    if (props.onFrameRendered) {
      props.onFrameRendered(frameCountRef.current);
    }
  }, [props.onFrameRendered]);

  // ==========================================================================
  // Event Subscription
  // ==========================================================================

  useEffect(() => {
    threeJsService.on('scene:ready', handleSceneReady as () => void);
    threeJsService.on('scene:error', handleSceneError as (error: string) => void);
    threeJsService.on('frame:rendered', handleFrameRendered as () => void);

    return () => {
      threeJsService.off('scene:ready', handleSceneReady as () => void);
      threeJsService.off('scene:error', handleSceneError as (error: string) => void);
      threeJsService.off('frame:rendered', handleFrameRendered as () => void);
    };
  }, [handleSceneReady, handleSceneError, handleFrameRendered]);

  // ==========================================================================
  // Scene Initialization
  // ==========================================================================

  const initializeScene = useCallback(async (config?: Partial<ThreeJsSceneConfig>) => {
    if (initializedRef.current) {
      return;
    }

    const mergedConfig: ThreeJsSceneConfig = {
      ...defaultSceneConfig,
      ...config,
      width: config?.width || 1920,
      height: config?.height || 1080
    };

    await threeJsService.initializeScene(mergedConfig);

    // Attach canvas if available
    const canvas = canvasRef.current;
    if (canvas && threeJsService.getRenderer()) {
      // Canvas will be attached by the renderer
    }

    initializedRef.current = true;
  }, []);

  const disposeScene = useCallback(() => {
    threeJsService.disposeScene();
    initializedRef.current = false;
    setState({
      sceneConfig: null,
      models: new Map(),
      cameraConfig: null,
      activeAnimation: null,
      isReady: false,
      isRendering: false,
      error: null
    });
  }, []);

  // ==========================================================================
  // Model Management
  // ==========================================================================

  const loadModel = useCallback(async (id: string, config: ModelConfig) => {
    return threeJsService.loadModel(id, config);
  }, []);

  const unloadModel = useCallback((id: string) => {
    threeJsService.unloadModel(id);
  }, []);

  // ==========================================================================
  // Animation
  // ==========================================================================

  const playAnimation = useCallback((modelId: string, config: AnimationConfig) => {
    threeJsService.playAnimation(modelId, config);
  }, []);

  const stopAnimation = useCallback((modelId: string) => {
    threeJsService.stopAnimation(modelId);
  }, []);

  // ==========================================================================
  // Camera
  // ==========================================================================

  const animateCamera = useCallback((config: CameraAnimationConfig) => {
    threeJsService.animateCamera(config);
  }, []);

  const stopCameraAnimation = useCallback(() => {
    threeJsService.stopCameraAnimation();
  }, []);

  const updateCameraPosition = useCallback((position: [number, number, number]) => {
    threeJsService.updateCameraPosition(position);
  }, []);

  // ==========================================================================
  // Rendering
  // ==========================================================================

  const renderFrame = useCallback(() => {
    threeJsService.renderFrame();
  }, []);

  const startRendering = useCallback(() => {
    threeJsService.startRendering();
    setState(prev => ({ ...prev, isRendering: true }));
  }, []);

  const stopRendering = useCallback(() => {
    threeJsService.stopRendering();
    setState(prev => ({ ...prev, isRendering: false }));
  }, []);

  // ==========================================================================
  // Effects
  // ==========================================================================

  const updateEffects = useCallback((config: Partial<EffectComposerConfig>) => {
    threeJsService.updateEffects(config);
  }, []);

  // ==========================================================================
  // Auto-initialization
  // ==========================================================================

  useEffect(() => {
    if (props.sceneConfig && !initializedRef.current) {
      initializeScene(props.sceneConfig);
    }

    return () => {
      // Cleanup is handled by the component using this hook
    };
  }, [props.sceneConfig, initializeScene]);

  // ==========================================================================
  // Sync state periodically
  // ==========================================================================

  useEffect(() => {
    const interval = setInterval(() => {
      setState(threeJsService.getState());
    }, 100);

    return () => clearInterval(interval);
     
    // Intentionally run only on mount - state sync interval should start once
  }, []);

  // ==========================================================================
  // Return
  // ==========================================================================

  return {
    state: threeJsService.getState(),
    canvasRef,
    isReady: state.isReady,
    error: state.error,
    initializeScene,
    disposeScene,
    loadModel,
    unloadModel,
    playAnimation,
    stopAnimation,
    animateCamera,
    stopCameraAnimation,
    updateCameraPosition,
    renderFrame,
    startRendering,
    stopRendering,
    updateEffects
  };
}

// ============================================================================
// Hook for Scene Configuration
// ============================================================================

export function useThreeJsScene() {
  const [sceneConfig, setSceneConfig] = useState<ThreeJsSceneConfig | null>(null);
  const [cameraConfig, setCameraConfig] = useState<CameraConfig | null>(null);

  const updateSceneConfig = useCallback((config: Partial<ThreeJsSceneConfig>) => {
    setSceneConfig(prev => prev ? { ...prev, ...config } : { ...defaultSceneConfig, ...config });
  }, []);

  const updateCameraConfig = useCallback((config: Partial<CameraConfig>) => {
    setCameraConfig(prev => prev ? { ...prev, ...config } : { ...defaultCameraConfig, ...config });
  }, []);

  return {
    sceneConfig,
    cameraConfig,
    updateSceneConfig,
    updateCameraConfig
  };
}

// ============================================================================
// Hook for Model Loading
// ============================================================================

export function useThreeJsModel(modelId: string) {
  const [model, setModel] = useState<ModelLoadResult | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async (config: ModelConfig) => {
    setIsLoading(true);
    setError(null);
    try {
      const result = await threeJsService.loadModel(modelId, config);
      setModel(result);
      return result;
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, [modelId]);

  const unload = useCallback(() => {
    threeJsService.unloadModel(modelId);
    setModel(null);
  }, [modelId]);

  return {
    model,
    isLoading,
    error,
    load,
    unload
  };
}

// ============================================================================
// Hook for Camera Animation
// ============================================================================

export function useCameraAnimation() {
  const [isAnimating, setIsAnimating] = useState(false);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const handleAnimating = (p: number) => {
      setProgress(p);
      setIsAnimating(true);
    };

    threeJsService.on('camera:animating', handleAnimating as (progress: number) => void);

    return () => {
      threeJsService.off('camera:animating', handleAnimating as (progress: number) => void);
    };
  }, []);

  const start = useCallback((config: CameraAnimationConfig) => {
    threeJsService.animateCamera(config);
  }, []);

  const stop = useCallback(() => {
    threeJsService.stopCameraAnimation();
    setIsAnimating(false);
    setProgress(0);
  }, []);

  return {
    isAnimating,
    progress,
    start,
    stop
  };
}

export default useThreeJs;

/**
 * React Hook for Thumbnail Cache Service
 * 
 * Provides real-time synchronization with ThumbnailCache
 * using the Observer pattern.
 */

import { useState, useEffect, useCallback } from 'react';
import {
  ThumbnailCache,
  type ThumbnailCacheConfig,
  type CacheEntry,
  type CacheStats
} from '@/services/ThumbnailCache';

// ============================================================================
// Hook: useThumbnailCache
// ============================================================================

export interface UseThumbnailCacheReturn {
  cache: ThumbnailCache;
  stats: CacheStats;
  getThumbnail: (videoUrl: string, time: number, quality?: string) => Promise<Blob | null>;
  setThumbnail: (videoUrl: string, time: number, blob: Blob, quality?: string) => Promise<void>;
  clearCache: () => Promise<void>;
  preloadThumbnails: (videoUrl: string, times: number[], quality?: string) => Promise<void>;
  preloadAdjacent: (videoUrl: string, currentTime: number, framerate: number, quality?: string) => Promise<void>;
}

/**
 * Hook for managing thumbnail cache with real-time synchronization
 * 
 * @param config - Optional cache configuration
 * 
 * @example
 * ```typescript
 * function VideoPlayer() {
 *   const { 
 *     getThumbnail, 
 *     setThumbnail, 
 *     stats,
 *     preloadAdjacent 
 *   } = useThumbnailCache();
 *   
 *   const handleSeek = async (time: number) => {
 *     const thumbnail = await getThumbnail(videoUrl, time);
 *     if (thumbnail) {
 *       // Display thumbnail
 *     }
 *     
 *     // Preload adjacent thumbnails
 *     await preloadAdjacent(videoUrl, time, 24);
 *   };
 *   
 *   return (
 *     <div>
 *       <p>Cache usage: {stats.memoryUsage.toFixed(1)}%</p>
 *       <p>Cached thumbnails: {stats.memoryCount}</p>
 *     </div>
 *   );
 * }
 * ```
 */
export function useThumbnailCache(config?: ThumbnailCacheConfig): UseThumbnailCacheReturn {
  const [cache] = useState(() => ThumbnailCache.getInstance(config));
  const [stats, setStats] = useState<CacheStats>(() => cache.getStats());

  // Subscribe to cache stats updates
  useEffect(() => {
    const unsubscribe = cache.subscribeToCacheStats((updatedStats) => {
      setStats(updatedStats);
    });

    return unsubscribe;
  }, [cache]);

  // Initialize IndexedDB
  useEffect(() => {
    cache.initIndexedDB().catch(err => {
      console.error('[useThumbnailCache] Failed to initialize IndexedDB:', err);
    });
  }, [cache]);

  // Get thumbnail
  const getThumbnail = useCallback(async (videoUrl: string, time: number, quality?: string) => {
    try {
      return await cache.get(videoUrl, time, quality);
    } catch (err) {
      console.error('[useThumbnailCache] Failed to get thumbnail:', err);
      return null;
    }
  }, [cache]);

  // Set thumbnail
  const setThumbnail = useCallback(async (videoUrl: string, time: number, blob: Blob, quality?: string) => {
    try {
      await cache.set(videoUrl, time, blob, quality);
    } catch (err) {
      console.error('[useThumbnailCache] Failed to set thumbnail:', err);
    }
  }, [cache]);

  // Clear cache
  const clearCache = useCallback(async () => {
    try {
      await cache.clear();
    } catch (err) {
      console.error('[useThumbnailCache] Failed to clear cache:', err);
    }
  }, [cache]);

  // Preload thumbnails
  const preloadThumbnails = useCallback(async (videoUrl: string, times: number[], quality?: string) => {
    try {
      await cache.preload(videoUrl, times, quality);
    } catch (err) {
      console.error('[useThumbnailCache] Failed to preload thumbnails:', err);
    }
  }, [cache]);

  // Preload adjacent thumbnails
  const preloadAdjacent = useCallback(async (videoUrl: string, currentTime: number, framerate: number, quality?: string) => {
    try {
      await cache.preloadAdjacent(videoUrl, currentTime, framerate, quality);
    } catch (err) {
      console.error('[useThumbnailCache] Failed to preload adjacent thumbnails:', err);
    }
  }, [cache]);

  return {
    cache,
    stats,
    getThumbnail,
    setThumbnail,
    clearCache,
    preloadThumbnails,
    preloadAdjacent,
  };
}

/**
 * Hook for fetching a specific video thumbnail
 * Matches the signature expected by ThumbnailPreview
 */
export function useVideoThumbnail(
  videoUrl: string,
  time: number,
  options: {
    quality?: string;
    preloadAdjacent?: boolean;
    framerate?: number
  } = {}
) {
  const { getThumbnail, preloadAdjacent } = useThumbnailCache();
  const [thumbnailUrl, setThumbnailUrl] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  const load = useCallback(async () => {
    if (!videoUrl) {
      setThumbnailUrl(null);
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      const blob = await getThumbnail(videoUrl, time, options.quality);
      if (blob) {
        const url = URL.createObjectURL(blob);
        setThumbnailUrl(prev => {
          if (prev) URL.revokeObjectURL(prev);
          return url;
        });
      } else {
        setThumbnailUrl(null);
      }

      if (options.preloadAdjacent && options.framerate) {
        // Fire and forget preload
        preloadAdjacent(videoUrl, time, options.framerate, options.quality).catch(console.error);
      }
    } catch (err) {
      setError(err instanceof Error ? err : new Error(String(err)));
    } finally {
      setIsLoading(false);
    }
  }, [videoUrl, time, options.quality, options.preloadAdjacent, options.framerate, getThumbnail, preloadAdjacent]);

  useEffect(() => {
    load();
    return () => {
      // Cleanup is handled in state updater or new load
    };
  }, [load]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      setThumbnailUrl(prev => {
        if (prev) URL.revokeObjectURL(prev);
        return null;
      });
    };
  }, []);

  return { thumbnailUrl, isLoading, error, reload: load };
}

// ============================================================================
// Hook: useThumbnailCacheStats
// ============================================================================

export interface UseThumbnailCacheStatsReturn {
  stats: CacheStats;
  refresh: () => void;
}

/**
 * Hook for monitoring thumbnail cache statistics
 * 
 * @example
 * ```typescript
 * function CacheMonitor() {
 *   const { stats, refresh } = useThumbnailCacheStats();
 *   
 *   return (
 *     <div>
 *       <h3>Cache Statistics</h3>
 *       <p>Memory Usage: {stats.memoryUsage.toFixed(1)}%</p>
 *       <p>Cached Items: {stats.memoryCount}</p>
 *       <p>Memory Size: {(stats.memorySize / 1024 / 1024).toFixed(2)} MB</p>
 *       <button onClick={refresh}>Refresh</button>
 *     </div>
 *   );
 * }
 * ```
 */
export function useThumbnailCacheStats(): UseThumbnailCacheStatsReturn {
  const cache = ThumbnailCache.getInstance();
  const [stats, setStats] = useState<CacheStats>(() => cache.getStats());

  // Subscribe to cache stats updates
  useEffect(() => {
    const unsubscribe = cache.subscribeToCacheStats((updatedStats) => {
      setStats(updatedStats);
    });

    return unsubscribe;
  }, [cache]);

  const refresh = useCallback(() => {
    setStats(cache.getStats());
  }, [cache]);

  return {
    stats,
    refresh,
  };
}

// ============================================================================
// Hook: useThumbnailPreloader
// ============================================================================

export interface UseThumbnailPreloaderReturn {
  isPreloading: boolean;
  preloadVisible: (videoUrl: string, visibleTimes: number[], adjacentTimes: number[], quality?: string) => Promise<void>;
  preloadRange: (videoUrl: string, startTime: number, endTime: number, interval: number, quality?: string) => Promise<void>;
}

/**
 * Hook for preloading thumbnails with loading state
 * 
 * @example
 * ```typescript
 * function ThumbnailPreloader({ videoUrl }: { videoUrl: string }) {
 *   const { isPreloading, preloadRange } = useThumbnailPreloader();
 *   
 *   const handlePreload = async () => {
 *     // Preload thumbnails every 1 second from 0 to 60 seconds
 *     await preloadRange(videoUrl, 0, 60, 1);
 *   };
 *   
 *   return (
 *     <div>
 *       <button onClick={handlePreload} disabled={isPreloading}>
 *         {isPreloading ? 'Preloading...' : 'Preload Thumbnails'}
 *       </button>
 *     </div>
 *   );
 * }
 * ```
 */
export function useThumbnailPreloader(): UseThumbnailPreloaderReturn {
  const cache = ThumbnailCache.getInstance();
  const [isPreloading, setIsPreloading] = useState(false);

  // Preload visible thumbnails
  const preloadVisible = useCallback(async (
    videoUrl: string,
    visibleTimes: number[],
    adjacentTimes: number[],
    quality?: string
  ) => {
    try {
      setIsPreloading(true);
      await cache.preloadVisible(videoUrl, visibleTimes, adjacentTimes, quality);
    } catch (err) {
      console.error('[useThumbnailPreloader] Failed to preload visible:', err);
    } finally {
      setIsPreloading(false);
    }
  }, [cache]);

  // Preload range of thumbnails
  const preloadRange = useCallback(async (
    videoUrl: string,
    startTime: number,
    endTime: number,
    interval: number,
    quality?: string
  ) => {
    try {
      setIsPreloading(true);
      const times: number[] = [];
      for (let time = startTime; time <= endTime; time += interval) {
        times.push(time);
      }
      await cache.preload(videoUrl, times, quality);
    } catch (err) {
      console.error('[useThumbnailPreloader] Failed to preload range:', err);
    } finally {
      setIsPreloading(false);
    }
  }, [cache]);

  return {
    isPreloading,
    preloadVisible,
    preloadRange,
  };
}

// ============================================================================
// Hook: useThumbnailCacheClear
// ============================================================================

export interface UseThumbnailCacheClearReturn {
  clearCache: () => Promise<void>;
  isClearing: boolean;
  cacheCleared: boolean;
}

/**
 * Hook for clearing thumbnail cache with state management
 * 
 * @example
 * ```typescript
 * function CacheClearButton() {
 *   const { clearCache, isClearing, cacheCleared } = useThumbnailCacheClear();
 *   
 *   return (
 *     <div>
 *       <button onClick={clearCache} disabled={isClearing}>
 *         {isClearing ? 'Clearing...' : 'Clear Cache'}
 *       </button>
 *       {cacheCleared && <p>Cache cleared successfully!</p>}
 *     </div>
 *   );
 * }
 * ```
 */
export function useThumbnailCacheClear(): UseThumbnailCacheClearReturn {
  const cache = ThumbnailCache.getInstance();
  const [isClearing, setIsClearing] = useState(false);
  const [cacheCleared, setCacheCleared] = useState(false);

  // Subscribe to cache clear events
  useEffect(() => {
    const unsubscribe = cache.subscribeToCacheClear((cleared) => {
      setCacheCleared(cleared);

      // Reset flag after 3 seconds
      if (cleared) {
        setTimeout(() => setCacheCleared(false), 3000);
      }
    });

    return unsubscribe;
  }, [cache]);

  const clearCache = useCallback(async () => {
    try {
      setIsClearing(true);
      await cache.clear();
    } catch (err) {
      console.error('[useThumbnailCacheClear] Failed to clear cache:', err);
    } finally {
      setIsClearing(false);
    }
  }, [cache]);

  return {
    clearCache,
    isClearing,
    cacheCleared,
  };
}

