/**
 * Wizard Error Handler Hook
 * 
 * Provides error handling utilities for wizards with consistent error recovery.
 */

import { useState, useCallback, useRef } from 'react';
import type { WizardType } from '../../utils/wizardStorage';

export interface WizardErrorInfo {
  error: Error;
  componentStack?: string;
  timestamp: Date;
  wizardType: WizardType;
}

export interface WizardErrorHandlerResult {
  error: WizardErrorInfo | null;
  hasError: boolean;
  dataExported: boolean;
  setError: (error: Error, componentStack?: string) => void;
  clearError: () => void;
  exportOnError: () => void;
  getErrorMessage: () => string;
  getErrorDescription: () => string;
}

export function useWizardErrorHandler(wizardType: WizardType): WizardErrorHandlerResult {
  const [error, setErrorState] = useState<WizardErrorInfo | null>(null);
  const [dataExported, setDataExported] = useState(false);
  const wizardTypeRef = useRef(wizardType);
  
  // Update ref when wizardType changes
  wizardTypeRef.current = wizardType;

  const setError = useCallback((err: Error, componentStack?: string) => {
    const errorInfo: WizardErrorInfo = {
      error: err,
      componentStack,
      timestamp: new Date(),
      wizardType: wizardTypeRef.current,
    };
    setErrorState(errorInfo);
    
    // Auto-export data
    try {
      // emergencyExportWizardState(wizardTypeRef.current, err);
      setDataExported(true);
    } catch (exportError) {
      console.error('Failed to export wizard data:', exportError);
    }
  }, []);

  const clearError = useCallback(() => {
    setErrorState(null);
    setDataExported(false);
  }, []);

  const exportOnError = useCallback(() => {
    if (error) {
      try {
        // emergencyExportWizardState(error.wizardType, error.error);
        setDataExported(true);
      } catch (err) {
        console.error('Failed to export wizard data:', err);
      }
    }
  }, [error]);

  const getErrorMessage = useCallback(() => {
    if (!error) return '';
    return error.error.message || 'An unexpected error occurred';
  }, [error]);

  const getErrorDescription = useCallback(() => {
    if (!error) return '';
    
    const message = error.error.message || '';
    
    if (message.includes('network') || message.includes('fetch')) {
      return 'Unable to connect to the server. Please check your internet connection and try again.';
    }
    if (message.includes('timeout')) {
      return 'The operation timed out. Please try again.';
    }
    if (message.includes('validation')) {
      return 'There was an issue with the data you entered. Please review your input and try again.';
    }
    if (message.includes('permission') || message.includes('access')) {
      return 'You do not have permission to perform this action. Please check your access rights.';
    }
    if (message.includes('storage') || message.includes('localStorage')) {
      return 'There was an issue saving your progress.';
    }
    
    return 'Something went wrong while processing your request. Please try again.';
  }, [error]);

  return {
    error,
    hasError: error !== null,
    dataExported,
    setError,
    clearError,
    exportOnError,
    getErrorMessage,
    getErrorDescription,
  };
}

export interface ErrorRecoveryOption {
  label: string;
  action: () => void;
  variant?: 'default' | 'destructive' | 'outline';
}

export interface WizardErrorRecoveryProps {
  error: WizardErrorInfo | null;
  dataExported: boolean;
  onRetry: () => void;
  onReload: () => void;
  onExport?: () => void;
  customOptions?: ErrorRecoveryOption[];
}

export function getDefaultRecoveryOptions(
  dataExported: boolean,
  onRetry: () => void,
  onReload: () => void,
  onExport?: () => void
): ErrorRecoveryOption[] {
  const options: ErrorRecoveryOption[] = [
    {
      label: 'Try Again',
      action: onRetry,
      variant: 'default',
    },
    {
      label: 'Reload Page',
      action: onReload,
      variant: 'outline',
    },
  ];

  if (!dataExported && onExport) {
    options.push({
      label: 'Export Data',
      action: onExport,
      variant: 'outline',
    });
  }

  return options;
}

/**
 * useWorkerPool - Hook React pour utiliser le WorkerPool
 * 
 * Ce hook fournit une interface simple pour ex├®cuter des t├óches
 * dans un pool de Web Workers avec gestion automatique du cycle de vie.
 */

import { useEffect, useRef, useState, useCallback } from 'react';
import { WorkerPool } from '../utils/workers/WorkerPool';

export interface WorkerPoolStats {
  queueSize: number;
  availableWorkers: number;
  busyWorkers: number;
  totalWorkers: number;
}

export interface UseWorkerPoolOptions {
  poolSize?: number;
  workerUrl?: string;
}

export interface UseWorkerPoolReturn {
  execute: <T, R>(type: string, data: T, priority?: number) => Promise<R>;
  cancel: (taskId: string) => boolean;
  cancelAll: () => void;
  stats: WorkerPoolStats;
  isReady: boolean;
}

/**
 * Hook pour utiliser un pool de Web Workers
 * 
 * @param options - Options de configuration du pool
 * @returns Interface pour ex├®cuter des t├óches et g├®rer le pool
 * 
 * @example
 * ```tsx
 * const { execute, stats, cancelAll } = useWorkerPool({ poolSize: 4 });
 * 
 * const handleGenerateThumbnail = async () => {
 *   try {
 *     const blob = await execute('generateThumbnail', {
 *       videoUrl: 'video.mp4',
 *       time: 5.0
 *     });
 *     // Utiliser le blob
 *   } catch (error) {
 *     console.error('Failed to generate thumbnail:', error);
 *   }
 * };
 * ```
 */
export function useWorkerPool(options: UseWorkerPoolOptions = {}): UseWorkerPoolReturn {
  const poolRef = useRef<WorkerPool | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [stats, setStats] = useState<WorkerPoolStats>({
    queueSize: 0,
    availableWorkers: 0,
    busyWorkers: 0,
    totalWorkers: 0
  });

  // Initialiser le pool
  useEffect(() => {
    const pool = new WorkerPool(options.poolSize, options.workerUrl);
    poolRef.current = pool;
    setIsReady(true);

    // Mettre ├á jour les stats initiales
    updateStats();

    // Nettoyer ├á la destruction
    return () => {
      if (poolRef.current) {
        poolRef.current.terminate();
        poolRef.current = null;
      }
      setIsReady(false);
    };
  }, [options.poolSize, options.workerUrl]);

  // Mettre ├á jour les statistiques
  const updateStats = useCallback(() => {
    if (poolRef.current) {
      setStats({
        queueSize: poolRef.current.getQueueSize(),
        availableWorkers: poolRef.current.getAvailableWorkers(),
        busyWorkers: poolRef.current.getBusyWorkers(),
        totalWorkers: poolRef.current.size
      });
    }
  }, []);

  // Ex├®cuter une t├óche
  const execute = useCallback(async <T, R>(
    type: string,
    data: T,
    priority: number = 0
  ): Promise<R> => {
    if (!poolRef.current) {
      throw new Error('WorkerPool not initialized');
    }

    updateStats();

    try {
      const result = await poolRef.current.execute<T, R>(type, data, priority);
      updateStats();
      return result;
    } catch (error) {
      updateStats();
      throw error;
    }
  }, [updateStats]);

  // Annuler une t├óche sp├®cifique
  const cancel = useCallback((taskId: string): boolean => {
    if (!poolRef.current) {
      return false;
    }

    const result = poolRef.current.cancel(taskId);
    updateStats();
    return result;
  }, [updateStats]);

  // Annuler toutes les t├óches
  const cancelAll = useCallback(() => {
    if (poolRef.current) {
      poolRef.current.cancelAll();
      updateStats();
    }
  }, [updateStats]);

  return {
    execute,
    cancel,
    cancelAll,
    stats,
    isReady
  };
}

/**
 * Hook pour ex├®cuter une t├óche unique dans un worker
 * 
 * @param type - Type de t├óche ├á ex├®cuter
 * @param data - Donn├®es ├á traiter
 * @param options - Options d'ex├®cution
 * @returns ├ëtat de l'ex├®cution et r├®sultat
 * 
 * @example
 * ```tsx
 * const { result, loading, error } = useWorkerTask('generateThumbnail', {
 *   videoUrl: 'video.mp4',
 *   time: 5.0
 * });
 * ```
 */
export function useWorkerTask<T, R>(
  type: string,
  data: T,
  options: { enabled?: boolean; priority?: number } = {}
) {
  const { enabled = true, priority = 0 } = options;
  const { execute } = useWorkerPool();
  const [result, setResult] = useState<R | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    if (!enabled) {
      return;
    }

    let cancelled = false;

    const runTask = async () => {
      setLoading(true);
      setError(null);

      try {
        const taskResult = await execute<T, R>(type, data, priority);
        if (!cancelled) {
          setResult(taskResult);
        }
      } catch (err) {
        if (!cancelled) {
          setError(err as Error);
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    };

    runTask();

    return () => {
      cancelled = true;
    };
  }, [type, JSON.stringify(data), enabled, priority, execute]);

  return { result, loading, error };
}

