/**
 * Props interface for TOSDialog component
 */
export interface TOSDialogProps {
  // No props needed - self-contained component
}

/**
 * State interface for TOSDialog component
 * Requirements: 2.1
 */
export interface TOSDialogState {
  /** Tracks whether the user has checked the acceptance checkbox */
  isAccepted: boolean;
  /** Tracks IPC communication errors */
  ipcError: string | null;
}

/**
 * TOS Dialog Component
 * 
 * Renders the Terms of Service dialog with message text and action buttons.
 * Handles user interactions and communicates with main process via IPC.
 * 
 * Features:
 * - Semantic HTML structure with proper ARIA attributes
 * - Checkbox-based acceptance mechanism
 * - IPC communication with main process
 * - Keyboard navigation support (Enter/Escape/Tab)
 * 
 * Requirements: 2.1, 6.1, 6.2
 */
export const TOSDialog: React.FC<TOSDialogProps> = () => {
  // Component state for managing acceptance checkbox
  const [state, setState] = React.useState<TOSDialogState>({
    isAccepted: false,
    ipcError: null,
  });

  // Refs for interactive elements to manage focus
  const checkboxRef = React.useRef<HTMLInputElement>(null);
  const exitButtonRef = React.useRef<HTMLButtonElement>(null);
  const acceptButtonRef = React.useRef<HTMLButtonElement>(null);

  /**
   * Handle checkbox change
   * 
   * Updates the isAccepted state when the user toggles the checkbox.
   * 
   * Requirements: 2.1, 2.2
   */
  const handleCheckboxChange = (event: React.ChangeEvent<HTMLInputElement>): void => {
    setState({
      ...state,
      isAccepted: event.target.checked,
    });
  };

  /**
   * Handle acceptance button click
   * 
   * Sends acceptance message to main process via IPC only if checkbox is checked.
   * Includes error handling for missing IPC API.
   * 
   * Requirements: 2.3, 2.4, 2.5, 5.3
   */
  const handleAccept = (): void => {
    // Only proceed if checkbox is checked
    if (!state.isAccepted) {
      console.warn('Accept button clicked but checkbox is not checked');
      return;
    }
    
    // Verify IPC API is available
    if (!window.tosAPI) {
      const errorMsg = 'Communication error. Please restart the application.';
      console.error('window.tosAPI is not available. IPC communication failed.');
      setState({
        ...state,
        ipcError: errorMsg,
      });
      return;
    }
    
    try {
      // Send acceptance to main process via IPC
      ;
      window.tosAPI.sendAcceptance();
    } catch (error) {
      const errorMsg = 'Communication error. Please restart the application.';
      console.error('Failed to send acceptance via IPC:', error);
      setState({
        ...state,
        ipcError: errorMsg,
      });
    }
  };

  /**
   * Handle exit button click
   * 
   * Sends exit message to main process via IPC at all times.
   * Includes error handling for missing IPC API.
   * 
   * Requirements: 5.2, 5.3, 5.4
   */
  const handleExit = (): void => {
    // Verify IPC API is available
    if (!window.tosAPI) {
      const errorMsg = 'Communication error. Please restart the application.';
      console.error('window.tosAPI is not available. IPC communication failed.');
      setState({
        ...state,
        ipcError: errorMsg,
      });
      return;
    }
    
    try {
      // Send exit to main process via IPC
      ;
      window.tosAPI.sendExit();
    } catch (error) {
      const errorMsg = 'Communication error. Please restart the application.';
      console.error('Failed to send exit via IPC:', error);
      setState({
        ...state,
        ipcError: errorMsg,
      });
    }
  };

  /**
   * Handle keyboard events for accessibility
   * 
   * Supports:
   * - Space: Toggle checkbox when focused on checkbox
   * - Enter: Trigger acceptance (only if checkbox is checked)
   * - Escape: Trigger exit
   * - Tab: Cycle focus between interactive elements (checkbox, buttons)
   * - Shift+Tab: Reverse cycle focus between interactive elements
   * 
   * Requirements: 7.1, 7.2, 7.3, 7.4, 7.5
   */
  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>): void => {
    const activeElement = document.activeElement;
    
    switch (event.key) {
      case ' ':
      case 'Spacebar': // For older browsers
        // Space key toggles checkbox when it's focused
        if (activeElement === checkboxRef.current) {
          event.preventDefault();
          setState({
            ...state,
            isAccepted: !state.isAccepted,
          });
        }
        break;
      
      case 'Enter':
        // Enter key triggers acceptance only if checkbox is checked
        // Prevent default to avoid triggering button clicks twice
        if (activeElement === acceptButtonRef.current && state.isAccepted) {
          event.preventDefault();
          handleAccept();
        } else if (activeElement === exitButtonRef.current) {
          event.preventDefault();
          handleExit();
        } else if (activeElement === checkboxRef.current) {
          // Enter on checkbox toggles it
          event.preventDefault();
          setState({
            ...state,
            isAccepted: !state.isAccepted,
          });
        }
        break;
      
      case 'Escape':
        // Escape key triggers exit
        event.preventDefault();
        handleExit();
        break;
      
      case 'Tab':
        // Tab key cycles focus between interactive elements
        event.preventDefault();
        
        if (event.shiftKey) {
          // Shift+Tab: Reverse cycle (Accept -> Exit -> Checkbox -> Accept)
          if (activeElement === acceptButtonRef.current) {
            exitButtonRef.current?.focus();
          } else if (activeElement === exitButtonRef.current) {
            checkboxRef.current?.focus();
          } else {
            acceptButtonRef.current?.focus();
          }
        } else {
          // Tab: Forward cycle (Checkbox -> Exit -> Accept -> Checkbox)
          if (activeElement === checkboxRef.current) {
            exitButtonRef.current?.focus();
          } else if (activeElement === exitButtonRef.current) {
            acceptButtonRef.current?.focus();
          } else {
            checkboxRef.current?.focus();
          }
        }
        break;
    }
  };

  /**
   * Render the TOS dialog with semantic HTML structure
   * 
   * Structure:
   * - Container div with role="dialog" and aria-modal="true"
   * - Content card with title, message, and action buttons
   * - Proper ARIA labels for accessibility
   * - Auto-focus on OK button for keyboard navigation
   * - Keyboard event handler for Enter/Escape/Tab navigation
   * 
   * Requirements: 1.2, 2.1, 3.1, 3.3, 4.1, 4.3, 7.2
   */
  return (
    <div 
      className="tos-dialog-container" 
      role="dialog" 
      aria-modal="true" 
      aria-labelledby="tos-title"
      onKeyDown={handleKeyDown}
    >
      <div className="tos-dialog-content">
        {/* Dialog title with semantic heading */}
        <h1 id="tos-title" className="tos-dialog-title">
          Terms of Service
        </h1>
        
        {/* Scrollable content area with license text */}
        <div className="tos-scrollable-content" role="document">
          <pre className="tos-license-text">
            {LICENSE_TEXT.mitLicense}
            {'\n\n'}
            {LICENSE_TEXT.usageDisclaimer}
          </pre>
        </div>
        
        {/* Acceptance checkbox section */}
        <div className="tos-acceptance-section">
          {/* Display IPC error message if present */}
          {state.ipcError && (
            <div className="tos-error-message" role="alert" aria-live="assertive">
              {state.ipcError}
            </div>
          )}
          
          <label className="tos-checkbox-label">
            <input
              ref={checkboxRef}
              type="checkbox"
              className="tos-checkbox"
              checked={state.isAccepted}
              onChange={handleCheckboxChange}
              aria-label="Accept terms of service"
            />
            <span className="tos-checkbox-text">
              I have read and accept the Terms of Service
            </span>
          </label>
        </div>
        
        {/* Action buttons container */}
        <div className="tos-dialog-actions">
          <button 
            ref={exitButtonRef}
            className="tos-button tos-button-exit"
            onClick={handleExit}
            disabled={!!state.ipcError}
            aria-label="Exit application"
          >
            Exit
          </button>
          <button 
            ref={acceptButtonRef}
            className="tos-button tos-button-accept"
            onClick={handleAccept}
            disabled={!state.isAccepted || !!state.ipcError}
            aria-label="Accept terms and continue"
            autoFocus
          >
            OK
          </button>
        </div>
      </div>
    </div>
  );
};

export default TOSDialog;

#!/usr/bin/env tsx

/**
 * Verification script for the Modal Framework
 *
 * This script runs automated tests and checks for the modal framework
 * to ensure it meets production requirements.
 */

import { execSync } from 'child_process';
import { readFileSync, existsSync } from 'fs';
import { join } from 'path';

// Colors for console output
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
};

function log(color: keyof typeof colors, message: string) {
}

async function runCommand(command: string): Promise<boolean> {
  try {
    execSync(command, { stdio: 'pipe' });
    return true;
  } catch (error) {
    return false;
  }
}

async function checkFileExists(filePath: string): Promise<boolean> {
  return existsSync(join(process.cwd(), filePath));
}

async function checkTypeScriptCompilation(): Promise<boolean> {
  log('blue', '­ƒöì Checking TypeScript compilation...');
  return runCommand('npx tsc --noEmit --skipLibCheck');
}

async function runUnitTests(): Promise<boolean> {
  log('blue', '­ƒº¬ Running unit tests...');
  return runCommand('npm test -- --run --reporter=verbose');
}

async function checkEslint(): Promise<boolean> {
  log('blue', '­ƒôÅ Checking ESLint...');
  return runCommand('npx eslint "src/hooks/useModal*.ts" "src/components/ui/Modal*.tsx" "src/types/modal.ts" --ext .ts,.tsx');
}

async function checkBundleSize(): Promise<boolean> {
  log('blue', '­ƒôª Checking bundle size...');

  // Simple check - ensure files are not too large
  const files = [
    'src/hooks/useModalState.ts',
    'src/hooks/useModalValidation.ts',
    'src/hooks/useModalConnectionTest.ts',
    'src/hooks/useModalPersistence.ts',
    'src/components/ui/ModalFramework.tsx',
    'src/types/modal.ts',
  ];

  for (const file of files) {
    try {
      const content = readFileSync(join(process.cwd(), file), 'utf-8');
      const sizeKB = content.length / 1024;

      if (sizeKB > 50) {
        log('yellow', `ÔÜá´©Å  ${file} is ${sizeKB.toFixed(1)}KB - consider splitting`);
      } else {
        log('green', `Ô£à ${file} size OK (${sizeKB.toFixed(1)}KB)`);
      }
    } catch (error) {
      log('red', `ÔØî Cannot read ${file}`);
      return false;
    }
  }

  return true;
}

async function checkPerformance(): Promise<boolean> {
  log('blue', 'ÔÜí Checking performance patterns...');

  // Check for potential performance issues
  const patterns = [
    { regex: /any/, message: 'any type found - use strict types' },
    { regex: /unknown/, message: 'unknown type found - use specific types' },
    { regex: /useEffect\(\(\) => \{/, message: 'useEffect without dependencies - potential infinite loop' },
  ];

  const files = [
    'src/hooks/useModalState.ts',
    'src/hooks/useModalValidation.ts',
    'src/hooks/useModalConnectionTest.ts',
    'src/hooks/useModalPersistence.ts',
    'src/components/ui/ModalFramework.tsx',
  ];

  let hasIssues = false;

  for (const file of files) {
    try {
      const content = readFileSync(join(process.cwd(), file), 'utf-8');

      for (const pattern of patterns) {
        if (pattern.regex.test(content)) {
          log('red', `ÔØî ${file}: ${pattern.message}`);
          hasIssues = true;
        }
      }
    } catch (error) {
      log('red', `ÔØî Cannot read ${file}`);
      hasIssues = true;
    }
  }

  if (!hasIssues) {
    log('green', 'Ô£à No performance issues found');
  }

  return !hasIssues;
}

async function checkMaintainability(): Promise<boolean> {
  log('blue', '­ƒöº Checking maintainability...');

  // Check for good practices
  const checks = [
    {
      name: 'TypeScript strict mode',
      check: () => {
        const tsconfig = JSON.parse(readFileSync('tsconfig.json', 'utf-8'));
        return tsconfig.compilerOptions?.strict === true;
      },
    },
    {
      name: 'Hook exports',
      check: () => checkFileExists('src/hooks/index.ts'),
    },
    {
      name: 'Component exports',
      check: () => checkFileExists('src/components/ui/index.ts'),
    },
    {
      name: 'Test coverage',
      check: async () => {
        const testFiles = [
          'src/hooks/__tests__/useModalState.test.ts',
          'src/hooks/__tests__/useModalValidation.test.ts',
        ];

        for (const file of testFiles) {
          if (!await checkFileExists(file)) {
            return false;
          }
        }
        return true;
      },
    },
  ];

  let passed = 0;
  const total = checks.length;

  for (const check of checks) {
    try {
      const result = await check.check();
      if (result) {
        log('green', `Ô£à ${check.name}`);
        passed++;
      } else {
        log('red', `ÔØî ${check.name}`);
      }
    } catch (error) {
      log('red', `ÔØî ${check.name} - Error: ${error}`);
    }
  }

  const score = (passed / total) * 100;
  log('blue', `­ƒôè Maintainability score: ${score.toFixed(1)}%`);

  return score >= 80;
}

async function main() {
  log('blue', '­ƒÜÇ Starting Modal Framework verification...\n');

  const checks = [
    { name: 'File existence', fn: checkFileExists.bind(null, 'src/types/modal.ts') },
    { name: 'TypeScript compilation', fn: checkTypeScriptCompilation },
    { name: 'ESLint', fn: checkEslint },
    { name: 'Unit tests', fn: runUnitTests },
    { name: 'Bundle size', fn: checkBundleSize },
    { name: 'Performance', fn: checkPerformance },
    { name: 'Maintainability', fn: checkMaintainability },
  ];

  let passed = 0;
  const total = checks.length;

  for (const check of checks) {
    try {
      const result = await check.fn();
      if (result) {
        passed++;
      }
    } catch (error) {
      log('red', `ÔØî ${check.name} failed with error: ${error}`);
    }
  }

  const successRate = (passed / total) * 100;

  if (successRate === 100) {
    log('green', `­ƒÄë All checks passed! (${passed}/${total})`);
    log('green', 'Ô£à Modal Framework is ready for production');
  } else if (successRate >= 75) {
    log('yellow', `ÔÜá´©Å  Most checks passed (${passed}/${total})`);
    log('yellow', '­ƒöä Modal Framework needs minor fixes');
  } else {
    log('red', `ÔØî Many checks failed (${passed}/${total})`);
    log('red', '­ƒøæ Modal Framework needs significant work');
  }

  process.exit(successRate === 100 ? 0 : 1);
}

main().catch(error => {
  log('red', `­ƒÆÑ Verification failed: ${error}`);
  process.exit(1);
});

/**
 * Sequence Editor - Main Component
 *
 * Professional-grade sequence editing interface for StoryCore-Engine
 * Requirements: 19.6, 20.1, 22.1
 */

import React, { useEffect, useState } from 'react';
import { Provider } from 'react-redux';
import { DndProvider } from 'react-dnd';
import { HTML5Backend } from 'react-dnd-html5-backend';
import { store } from '@/sequence-editor/store';
import { useAppSelector, useAppDispatch } from '@/sequence-editor/store';
import { reorderShots, addShot } from '@/sequence-editor/store/slices/timelineSlice';
import { updateMetadata } from '@/sequence-editor/store/slices/projectSlice';

// Import components
import { ToolBar } from '@/sequence-editor/components/ToolBar/ToolBar';
import { AssetLibrary } from '@/sequence-editor/components/AssetLibrary/AssetLibrary';
import { PreviewFrame } from '@/sequence-editor/components/PreviewFrame/PreviewFrame';
import { ShotConfigPanel } from '@/sequence-editor/components/ShotConfig/ShotConfigPanel';
import { Timeline } from '@/sequence-editor/components/Timeline/Timeline';
import { StatusBar } from '@/sequence-editor/components/StatusBar/StatusBar';
import { ResizablePanel } from '@/sequence-editor/components/Panels/ResizablePanel';
import { RecoveryDialog } from '@/sequence-editor/components/RecoveryDialog/RecoveryDialog';
import { UnsavedChangesDialog } from '@/sequence-editor/components/UnsavedChangesDialog/UnsavedChangesDialog';
import { LayerManager } from '@/sequence-editor/components/LayerManager/LayerManager';
import { LayerPropertiesPanel } from '@/sequence-editor/components/LayerPropertiesPanel/LayerPropertiesPanel';

// Import new enhancement panels
import { TransitionsPanel } from '@/sequence-editor/components/TransitionsPanel';
import { AIFeaturesPanel } from '@/sequence-editor/components/AIFeaturesPanel';
import { AudioMixerPanel } from '@/sequence-editor/components/AudioMixerPanel';
import { ExportPanel } from '@/sequence-editor/components/ExportPanel';
import { EffectsPanel } from '@/sequence-editor/components/EffectsPanel';

// Import LLM Assistant Sidebar
import { LLMAssistantSidebar } from '@/components/LLMAssistantSidebar';

// Import R&D Phase 2/3 panels
import { VideoEffectsPanel } from '@/sequence-editor/components/VideoEffectsPanel/VideoEffectsPanel';
import { CompositionTemplateBrowser } from '@/sequence-editor/components/CompositionTemplateBrowser/CompositionTemplateBrowser';

// Import hooks
import { useProjectRecovery } from '@/sequence-editor/hooks/useProjectRecovery';
import { useProjectFile } from '@/sequence-editor/hooks/useProjectFile';
import { useAccessibilityInit } from '@/sequence-editor/hooks/useAccessibility';

// Import utilities
import { initializeBrowserCompat } from '@/sequence-editor/utils/browserCompat';

// Import styles
import './styles/variables.css';
import './styles/layout.css';
import './styles/animations.css';

export interface SequenceEditorProps {
  sequenceId?: string;
  onBack?: () => void;
}

export const SequenceEditor: React.FC<SequenceEditorProps> = ({ sequenceId, onBack }) => {
  return (
    <Provider store={store}>
      <DndProvider backend={HTML5Backend}>
        <SequenceEditorContent sequenceId={sequenceId} onBack={onBack} />
      </DndProvider>
    </Provider>
  );
};

const SequenceEditorContent: React.FC<SequenceEditorProps> = ({ sequenceId, onBack }) => {
  const dispatch = useAppDispatch();
  const { selectedElements, shots, playheadPosition } = useAppSelector((state) => state.timeline);
  const { showLayerManager } = useAppSelector((state) => state.panels);

  // State for right panel tabs (new enhancement panels)
  const [activeRightPanel, setActiveRightPanel] = useState<'shotConfig' | 'transitions' | 'aiFeatures' | 'effects' | 'videoFx' | 'templates'>('shotConfig');

  // State for bottom panel (audio mixer and export)
  const [activeBottomPanel, setActiveBottomPanel] = useState<'timeline' | 'audioMixer' | 'export'>('timeline');

  // Initialize sequence from global store
  useEffect(() => {
    if (sequenceId) {
      console.log(`[SequenceEditor] Initializing sequence: ${sequenceId}`);

      // 1. Access global state (Zustand)
      // Note: We use a dynamic check for useStore to avoid circular dependencies or import issues
      const gStore = (window as any).useStore;
      if (!gStore) {
        console.warn('[SequenceEditor] Global store (window.useStore) not found. Synchronization might fail.');
        return;
      }

      const { shots: globalShots, project: globalProject } = gStore.getState();

      // 2. Filter shots for this sequence
      const sequenceShots = globalShots.filter((s: any) => s.sequence_id === sequenceId || s.sequenceId === sequenceId);

      if (sequenceShots.length > 0) {
        // 3. Map to Redux Format (Data Contract v1)
        const FPS = 24; // Default to 24 FPS

        const mappedShots = sequenceShots.map((s: any) => ({
          id: s.id,
          name: s.title || s.name || 'Untitled Shot',
          startTime: Math.round((s.start_time || 0) * FPS),
          duration: Math.round((s.duration || 1) * FPS),
          layers: s.layers || [],
          referenceImages: s.referenceImages || [],
          prompt: s.description || s.prompt || '',
          parameters: s.generation?.parameters || {
            seed: -1,
            denoising: 0.7,
            steps: 20,
            guidance: 7.0,
            sampler: 'euler',
            scheduler: 'normal'
          },
          generationStatus: (s.status === 'done' || s.status === 'completed') ? 'complete' : 'pending',
          outputPath: s.generated_image_url || s.image || '',
        }));

        // 4. Dispatch to Redux
        dispatch(reorderShots(mappedShots));

        // 5. Update Project Metadata in Redux
        dispatch(updateMetadata({
          id: sequenceId,
          name: sequenceShots[0]?.name || `Sequence ${sequenceId}`,
          path: globalProject?.path || '',
          modified: Date.now()
        }));
      }
    }
  }, [sequenceId, dispatch]);

  // Initialize accessibility features
  useAccessibilityInit();

  // Initialize browser compatibility
  useEffect(() => {
    initializeBrowserCompat();
  }, []);

  // Get selected shot ID for shot configuration panel
  const selectedShotId = selectedElements.length > 0 ? selectedElements[0] : null;

  // Get the selected shot object for LayerManager and LayerPropertiesPanel
  const selectedShot = selectedShotId ? shots.find(shot => shot.id === selectedShotId) : undefined;

  // Get selected layer IDs from the selected elements (filter to only layer IDs)
  const selectedLayerIds = selectedElements.filter(id =>
    shots.some(shot => shot.layers.some(layer => layer.id === id))
  );

  // Initialize project recovery
  const {
    hasCrashedSession,
    recoverySnapshots,
    showRecoveryDialog,
    setShowRecoveryDialog,
    handleRecover,
    handleDismiss,
    deleteSnapshot,
    formatTimestamp,
    isRecovering,
    error,
  } = useProjectRecovery();

  // Initialize project file management
  const {
    showUnsavedDialog,
    handleSave,
    handleDiscard,
    handleCancel,
  } = useProjectFile();

  // Keyboard shortcuts for accessibility
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Skip if user is typing in an input field
      if (
        e.target instanceof HTMLInputElement ||
        e.target instanceof HTMLTextAreaElement
      ) {
        return;
      }

      // Ctrl/Cmd + S for save
      if ((e.ctrlKey || e.metaKey) && e.key === 's') {
        e.preventDefault();
        handleSave();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleSave]);

  return (
    <div
      className="sequence-editor-root"
      role="application"
      aria-label="Sequence Editor"
    >
      {/* Recovery Dialog */}
      {showRecoveryDialog && (
        <RecoveryDialog
          onClose={() => setShowRecoveryDialog(false)}
          hasCrashedSession={hasCrashedSession}
          recoverySnapshots={recoverySnapshots}
          recoverFromSnapshot={handleRecover}
          dismissCrashRecovery={handleDismiss}
          deleteSnapshot={deleteSnapshot}
          formatTimestamp={formatTimestamp}
          isRecovering={isRecovering}
          error={error}
        />
      )}

      {/* Unsaved Changes Dialog */}
      {showUnsavedDialog && (
        <UnsavedChangesDialog
          onSave={handleSave}
          onDiscard={handleDiscard}
          onCancel={handleCancel}
        />
      )}

      {/* Top Toolbar */}
      <div className="sequence-editor-toolbar" role="toolbar" aria-label="Main toolbar">
        <ToolBar onBack={onBack} />
      </div>

      {/* Main Content Area */}
      <div className="sequence-editor-main" role="main">
        {/* Left Panel - Asset Library */}
        <ResizablePanel
          panelId="assetLibrary"
          resizeDirection="horizontal"
          minWidth={200}
          className="sequence-editor-asset-library"
          ariaLabel="Asset Library Panel"
        >
          <AssetLibrary />
        </ResizablePanel>

        {/* Center Panel - Preview Frame */}
        <div className="sequence-editor-center" role="region" aria-label="Preview area">
          <PreviewFrame />
        </div>

        {/* Right Panel - Shot Configuration or Layer Manager */}
        <ResizablePanel
          panelId="shotConfig"
          resizeDirection="horizontal"
          minWidth={200}
          className="sequence-editor-shot-config"
          ariaLabel="Right Panel"
        >
          {/* Right Panel Tabs for Enhancement Panels */}
          <div className="right-panel-tabs">
            <button
              className={`panel-tab ${activeRightPanel === 'shotConfig' ? 'active' : ''}`}
              onClick={() => setActiveRightPanel('shotConfig')}
            >
              Shot
            </button>
            <button
              className={`panel-tab ${activeRightPanel === 'transitions' ? 'active' : ''}`}
              onClick={() => setActiveRightPanel('transitions')}
            >
              Transitions
            </button>
            <button
              className={`panel-tab ${activeRightPanel === 'aiFeatures' ? 'active' : ''}`}
              onClick={() => setActiveRightPanel('aiFeatures')}
            >
              AI Features
            </button>
            <button
              className={`panel-tab ${activeRightPanel === 'effects' ? 'active' : ''}`}
              onClick={() => setActiveRightPanel('effects')}
            >
              Effects
            </button>
            <button
              className={`panel-tab ${activeRightPanel === 'videoFx' ? 'active' : ''}`}
              onClick={() => setActiveRightPanel('videoFx')}
            >
              Video FX
            </button>
            <button
              className={`panel-tab ${activeRightPanel === 'templates' ? 'active' : ''}`}
              onClick={() => setActiveRightPanel('templates')}
            >
              Templates
            </button>
          </div>

          {/* Panel Content */}
          <div className="right-panel-content">
            {showLayerManager ? (
              <>
                {selectedShot ? (
                  <>
                    <LayerManager shot={selectedShot} selectedLayerIds={selectedLayerIds} />
                    <LayerPropertiesPanel shot={selectedShot} selectedLayerId={selectedLayerIds[0] || null} />
                  </>
                ) : (
                  <div className="layer-manager-empty">
                    <p>No shot selected</p>
                    <p className="hint">Select a shot to manage its layers</p>
                  </div>
                )}
              </>
            ) : activeRightPanel === 'shotConfig' ? (
              <ShotConfigPanel />
            ) : activeRightPanel === 'transitions' ? (
              <TransitionsPanel />
            ) : activeRightPanel === 'aiFeatures' ? (
              <AIFeaturesPanel />
            ) : activeRightPanel === 'effects' ? (
              <EffectsPanel />
            ) : activeRightPanel === 'videoFx' ? (
              <VideoEffectsPanel shot={null as any} selectedLayerId={null} />
            ) : activeRightPanel === 'templates' ? (
              <CompositionTemplateBrowser
                insertionFrame={playheadPosition}
                onInsertLayers={(layers) => {
                  console.log('[SequenceEditor] Insert template layers:', layers);
                  // Find the selected shot or create a new one
                  const targetShot = selectedShotId ? shots.find(s => s.id === selectedShotId) : null;
                  if (targetShot) {
                    // Add layers to existing shot
                    layers.forEach(layer => {
                      dispatch({
                        type: 'timeline/addLayer',
                        payload: { shotId: targetShot.id, layer }
                      });
                    });
                  } else {
                    // Create a new shot with the template layers
                    const newShot = {
                      id: `shot-${Date.now()}`,
                      name: 'Template Shot',
                      startTime: playheadPosition,
                      duration: Math.max(...layers.map(l => l.startTime + l.duration)),
                      layers: layers,
                      referenceImages: [],
                      prompt: '',
                      parameters: {
                        seed: -1,
                        denoising: 0.7,
                        steps: 20,
                        guidance: 7.0,
                        sampler: 'euler',
                        scheduler: 'normal'
                      },
                      generationStatus: 'pending' as const,
                    };
                    dispatch(addShot(newShot));
                  }
                }}
              />
            ) : null}
          </div>
        </ResizablePanel>
      </div>

      {/* Bottom Panel - Timeline / Audio Mixer / Export */}
      <ResizablePanel
        panelId="timeline"
        resizeDirection="vertical"
        minHeight={150}
        className="sequence-editor-timeline"
        ariaLabel="Bottom Panel"
      >
        {/* Bottom Panel Tabs */}
        <div className="bottom-panel-tabs">
          <button
            className={`panel-tab ${activeBottomPanel === 'timeline' ? 'active' : ''}`}
            onClick={() => setActiveBottomPanel('timeline')}
          >
            Timeline
          </button>
          <button
            className={`panel-tab ${activeBottomPanel === 'audioMixer' ? 'active' : ''}`}
            onClick={() => setActiveBottomPanel('audioMixer')}
          >
            Audio Mixer
          </button>
          <button
            className={`panel-tab ${activeBottomPanel === 'export' ? 'active' : ''}`}
            onClick={() => setActiveBottomPanel('export')}
          >
            Export
          </button>
        </div>

        {/* Bottom Panel Content */}
        <div className="bottom-panel-content">
          {activeBottomPanel === 'timeline' && <Timeline />}
          {activeBottomPanel === 'audioMixer' && <AudioMixerPanel />}
          {activeBottomPanel === 'export' && <ExportPanel />}
        </div>
      </ResizablePanel>

      {/* Status Bar */}
      <div className="sequence-editor-status-bar" role="status" aria-label="Project status">
        <StatusBar />
      </div>

      {/* LLM Assistant Sidebar - Voice Commands Helper */}
      <LLMAssistantSidebar />
    </div>
  );
};

