/**
 * Camera Preset Preview Component
 * 
 * Displays camera preset with preview animation and metadata.
 * Requirements: 12.2, 12.5
 */

import React, { useState, useRef, useEffect } from 'react';
import type { CameraPreset } from '../../services/cameraPresetService';
import './cameraPresetPreview.css';

// ============================================================================
// Types
// ============================================================================

interface CameraPresetPreviewProps {
  preset: CameraPreset;
  onApply?: (preset: CameraPreset) => void;
  onClose?: () => void;
  showApplyButton?: boolean;
}

// ============================================================================
// Component
// ============================================================================

export const CameraPresetPreview: React.FC<CameraPresetPreviewProps> = ({
  preset,
  onApply,
  onClose,
  showApplyButton = true,
}) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const { cameraMetadata } = preset.metadata;

  // Auto-play preview when component mounts
  useEffect(() => {
    if (videoRef.current && preset.previewUrl) {
      videoRef.current.play().catch(() => {
        // Autoplay might be blocked by browser
        setIsPlaying(false);
      });
      setIsPlaying(true);
    }
  }, [preset.previewUrl]);

  const handlePlayPause = () => {
    if (videoRef.current) {
      if (isPlaying) {
        videoRef.current.pause();
      } else {
        videoRef.current.play();
      }
      setIsPlaying(!isPlaying);
    }
  };

  const handleApply = () => {
    if (onApply) {
      onApply(preset);
    }
  };

  return (
    <div className="camera-preset-preview">
      {/* Header */}
      <div className="camera-preset-preview-header">
        <h3 className="camera-preset-preview-title">{preset.name}</h3>
        {onClose && (
          <button
            className="camera-preset-preview-close"
            onClick={onClose}
            aria-label="Close preview"
          >
            Ô£ò
          </button>
        )}
      </div>

      {/* Preview Animation */}
      <div className="camera-preset-preview-animation">
        {preset.previewUrl ? (
          <div className="camera-preset-video-container">
            <video
              ref={videoRef}
              src={preset.previewUrl}
              loop
              muted
              className="camera-preset-video"
              onPlay={() => setIsPlaying(true)}
              onPause={() => setIsPlaying(false)}
            />
            <button
              className="camera-preset-play-button"
              onClick={handlePlayPause}
              aria-label={isPlaying ? 'Pause preview' : 'Play preview'}
            >
              {isPlaying ? 'ÔÅ©' : 'ÔûÂ'}
            </button>
          </div>
        ) : (
          <div className="camera-preset-placeholder">
            <span className="camera-preset-placeholder-icon">­ƒôÀ</span>
            <span className="camera-preset-placeholder-text">
              {cameraMetadata.movementType.toUpperCase()}
            </span>
          </div>
        )}
      </div>

      {/* Description */}
      <div className="camera-preset-preview-description">
        <p>{preset.metadata.description}</p>
      </div>

      {/* Metadata */}
      <div className="camera-preset-preview-metadata">
        <div className="camera-preset-metadata-grid">
          <div className="camera-preset-metadata-item">
            <span className="camera-preset-metadata-label">Movement Type</span>
            <span className="camera-preset-metadata-value">
              {cameraMetadata.movementType}
            </span>
          </div>
          <div className="camera-preset-metadata-item">
            <span className="camera-preset-metadata-label">Duration</span>
            <span className="camera-preset-metadata-value">
              {cameraMetadata.duration}s
            </span>
          </div>
          <div className="camera-preset-metadata-item">
            <span className="camera-preset-metadata-label">Focal Length</span>
            <span className="camera-preset-metadata-value">
              {cameraMetadata.focalLength}mm
            </span>
          </div>
          <div className="camera-preset-metadata-item">
            <span className="camera-preset-metadata-label">Trajectory</span>
            <span className="camera-preset-metadata-value">
              {cameraMetadata.trajectory}
            </span>
          </div>
        </div>
      </div>

      {/* Recommended Use Cases */}
      {cameraMetadata.recommendedUseCases && cameraMetadata.recommendedUseCases.length > 0 && (
        <div className="camera-preset-preview-use-cases">
          <h4 className="camera-preset-use-cases-title">Recommended Use Cases</h4>
          <ul className="camera-preset-use-cases-list">
            {cameraMetadata.recommendedUseCases.map((useCase, index) => (
              <li key={index} className="camera-preset-use-case-item">
                {useCase}
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Tags */}
      {preset.tags && preset.tags.length > 0 && (
        <div className="camera-preset-preview-tags">
          {preset.tags.map((tag, index) => (
            <span key={index} className="camera-preset-tag">
              {tag}
            </span>
          ))}
        </div>
      )}

      {/* Actions */}
      {showApplyButton && (
        <div className="camera-preset-preview-actions">
          <button
            className="camera-preset-apply-button"
            onClick={handleApply}
          >
            Apply Preset
          </button>
        </div>
      )}
    </div>
  );
};

export default CameraPresetPreview;

/**
 * CompositionTemplateBrowser Component
 *
 * A browsable panel that lists all available composition templates
 * (Lower Thirds, Title Cards, CTAs, etc.) and lets the user:
 *  1. Preview them (thumbnail + animated preview)
 *  2. Drop them onto the timeline with one click
 *  3. Create new templates from selected layers
 *
 * Similar to CapCut's "Templates" panel and Canva's "Elements" panel.
 *
 * Requirements: Phase 3 of R&D plan
 */

import React, { useState, useMemo, useCallback } from 'react';
import {
    compositionTemplateService,
    type CompositionTemplate,
    type CompositionCategory,
} from '../../../services/templates/CompositionTemplateService';
import './compositionTemplateBrowser.css';

interface CompositionTemplateBrowserProps {
    /** Current playhead position in frames ÔÇö templates are inserted here */
    insertionFrame: number;
    /** Called when the user wants to add layers from a template */
    onInsertLayers: (layers: any[]) => void;
}

const CATEGORY_LABELS: Record<CompositionCategory, string> = {
    'intro': '­ƒÄ¼ Intro',
    'outro': '­ƒÅü Outro',
    'lower-third': '­ƒôØ Lower Third',
    'title-card': '­ƒÄ» Title Card',
    'call-to-action': '­ƒôú CTA',
    'transition': '­ƒöä Transition',
    'social-media': '­ƒô▒ Social',
    'subtitle-style': '­ƒÆ¼ Subtitles',
    'overlay': 'Ô£¿ Overlay',
    'custom': '­ƒÄ¿ Custom',
};

const ALL_CATEGORIES: CompositionCategory[] = [
    'lower-third',
    'title-card',
    'intro',
    'outro',
    'call-to-action',
    'social-media',
    'overlay',
    'transition',
    'subtitle-style',
    'custom',
];

export const CompositionTemplateBrowser: React.FC<CompositionTemplateBrowserProps> = ({
    insertionFrame,
    onInsertLayers,
}) => {
    const [selectedCategory, setSelectedCategory] = useState<CompositionCategory | 'all'>('all');
    const [searchQuery, setSearchQuery] = useState('');
    const [hoveredTemplate, setHoveredTemplate] = useState<string | null>(null);

    const allTemplates = useMemo(
        () => compositionTemplateService.getAllTemplates(),
        [],
    );

    const filteredTemplates = useMemo(() => {
        let templates = allTemplates;

        if (selectedCategory !== 'all') {
            templates = templates.filter(t => t.category === selectedCategory);
        }

        if (searchQuery.trim()) {
            const q = searchQuery.toLowerCase();
            templates = templates.filter(
                t =>
                    t.name.toLowerCase().includes(q) ||
                    t.description.toLowerCase().includes(q) ||
                    t.tags.some(tag => tag.toLowerCase().includes(q)),
            );
        }

        return templates;
    }, [allTemplates, selectedCategory, searchQuery]);

    const handleInsertTemplate = useCallback(
        (template: CompositionTemplate) => {
            const layers = compositionTemplateService.instantiate(template.id, insertionFrame);
            onInsertLayers(layers);
        },
        [insertionFrame, onInsertLayers],
    );

    return (
        <div className="comp-template-browser">
            {/* Header */}
            <div className="comp-browser-header">
                <h3>Templates</h3>
                <div className="comp-browser-search">
                    <input
                        type="text"
                        placeholder="Search templates..."
                        value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)}
                    />
                </div>
            </div>

            {/* Category Pills */}
            <div className="comp-browser-categories">
                <button
                    className={`comp-cat-pill ${selectedCategory === 'all' ? 'active' : ''}`}
                    onClick={() => setSelectedCategory('all')}
                >
                    All
                </button>
                {ALL_CATEGORIES.map(cat => {
                    const count = allTemplates.filter(t => t.category === cat).length;
                    if (count === 0) return null;
                    return (
                        <button
                            key={cat}
                            className={`comp-cat-pill ${selectedCategory === cat ? 'active' : ''}`}
                            onClick={() => setSelectedCategory(cat)}
                        >
                            {CATEGORY_LABELS[cat]}
                            <span className="comp-cat-count">{count}</span>
                        </button>
                    );
                })}
            </div>

            {/* Grid */}
            <div className="comp-browser-grid">
                {filteredTemplates.length === 0 && (
                    <div className="comp-browser-empty">No templates found</div>
                )}

                {filteredTemplates.map(template => (
                    <div
                        key={template.id}
                        className="comp-template-card"
                        onMouseEnter={() => setHoveredTemplate(template.id)}
                        onMouseLeave={() => setHoveredTemplate(null)}
                    >
                        {/* Thumbnail */}
                        <div className="comp-template-thumb">
                            {template.thumbnailUrl ? (
                                <img src={template.thumbnailUrl} alt={template.name} />
                            ) : (
                                <div className="comp-template-thumb-placeholder">
                                    {CATEGORY_LABELS[template.category]?.split(' ')[0] ?? '­ƒôª'}
                                </div>
                            )}

                            {/* Hover overlay with insert button */}
                            {hoveredTemplate === template.id && (
                                <div className="comp-template-overlay">
                                    <button
                                        className="comp-template-insert-btn"
                                        onClick={() => handleInsertTemplate(template)}
                                        title="Insert at playhead"
                                    >
                                        + Add
                                    </button>
                                </div>
                            )}
                        </div>

                        {/* Info */}
                        <div className="comp-template-info">
                            <div className="comp-template-name">{template.name}</div>
                            <div className="comp-template-meta">
                                {template.layers.length} layers ┬À {Math.round(template.totalDuration / 30)}s
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

/**
 * Export Panel Component
 * 
 * Provides UI for video export with:
 * - Full preset selection (YouTube, TikTok, Instagram, Twitter)
 * - Custom resolution/quality settings
 * - Progress tracking
 * - Download management
 * 
 * Requirements: Phase 3 - Enhance export functionality
 */

import React, { useState, useCallback } from 'react';
import { useAppDispatch, useAppSelector } from '../../store';
import './exportPanel.css';

// =============================================================================
// Types
// =============================================================================

interface ExportPreset {
  id: string;
  name: string;
  platform: string;
  resolution: string;
  width: number;
  height: number;
  aspectRatio: string;
  format: string;
  quality: string;
  description: string;
}

const EXPORT_PRESETS: ExportPreset[] = [
  { id: 'youtube_1080p', name: 'YouTube 1080p', platform: 'YouTube', resolution: '1920x1080', width: 1920, height: 1080, aspectRatio: '16:9', format: 'mp4', quality: 'high', description: 'Best for YouTube, standard HD' },
  { id: 'youtube_4k', name: 'YouTube 4K', platform: 'YouTube', resolution: '3840x2160', width: 3840, height: 2160, aspectRatio: '16:9', format: 'mp4', quality: 'ultra', description: '4K Ultra HD for YouTube' },
  { id: 'youtube_720p', name: 'YouTube 720p', platform: 'YouTube', resolution: '1280x720', width: 1280, height: 720, aspectRatio: '16:9', format: 'mp4', quality: 'medium', description: 'HD, faster upload' },
  { id: 'tiktok', name: 'TikTok/Reels', platform: 'TikTok', resolution: '1080x1920', width: 1080, height: 1920, aspectRatio: '9:16', format: 'mp4', quality: 'high', description: 'Vertical video for TikTok, Instagram Reels' },
  { id: 'instagram_feed', name: 'Instagram Feed', platform: 'Instagram', resolution: '1080x1080', width: 1080, height: 1080, aspectRatio: '1:1', format: 'mp4', quality: 'high', description: 'Square format for Instagram Feed' },
  { id: 'instagram_story', name: 'Instagram Story', platform: 'Instagram', resolution: '1080x1920', width: 1080, height: 1920, aspectRatio: '9:16', format: 'mp4', quality: 'high', description: 'Vertical for Instagram Stories' },
  { id: 'instagram_portrait', name: 'Instagram Portrait', platform: 'Instagram', resolution: '1080x1350', width: 1080, height: 1350, aspectRatio: '4:5', format: 'mp4', quality: 'high', description: 'Portrait for Instagram Feed' },
  { id: 'twitter', name: 'Twitter/X', platform: 'Twitter', resolution: '1280x720', width: 1280, height: 720, aspectRatio: '16:9', format: 'mp4', quality: 'medium', description: 'Standard Twitter video' },
  { id: 'facebook', name: 'Facebook', platform: 'Facebook', resolution: '1920x1080', width: 1920, height: 1080, aspectRatio: '16:9', format: 'mp4', quality: 'high', description: 'Best for Facebook' },
  { id: 'linkedin', name: 'LinkedIn', platform: 'LinkedIn', resolution: '1920x1080', width: 1920, height: 1080, aspectRatio: '16:9', format: 'mp4', quality: 'high', description: 'Professional content' },
  { id: 'custom', name: 'Custom', platform: 'Custom', resolution: 'Custom', width: 1920, height: 1080, aspectRatio: 'custom', format: 'mp4', quality: 'custom', description: 'Custom settings' },
];

interface ExportFormat {
  id: string;
  name: string;
  extension: string;
}

const EXPORT_FORMATS: ExportFormat[] = [
  { id: 'mp4', name: 'MP4 (H.264)', extension: '.mp4' },
  { id: 'webm', name: 'WebM (VP9)', extension: '.webm' },
  { id: 'mov', name: 'MOV (QuickTime)', extension: '.mov' },
  { id: 'avi', name: 'AVI', extension: '.avi' },
];

interface ExportQuality {
  id: string;
  name: string;
  bitrate: string;
}

const QUALITY_LEVELS: ExportQuality[] = [
  { id: 'low', name: 'Low', bitrate: '2 Mbps' },
  { id: 'medium', name: 'Medium', bitrate: '5 Mbps' },
  { id: 'high', name: 'High', bitrate: '10 Mbps' },
  { id: 'ultra', name: 'Ultra', bitrate: '20 Mbps' },
];

// =============================================================================
// Component
// =============================================================================

export const ExportPanel: React.FC = () => {
  const dispatch = useAppDispatch();
  const projectId = useAppSelector((state) => state.project.metadata?.id);
  const shots = useAppSelector((state) => state.timeline.shots);
  
  // Selected preset
  const [selectedPreset, setSelectedPreset] = useState<string>('youtube_1080p');
  
  // Custom settings
  const [customWidth, setCustomWidth] = useState(1920);
  const [customHeight, setCustomHeight] = useState(1080);
  const [customFormat, setCustomFormat] = useState('mp4');
  const [customQuality, setCustomQuality] = useState('high');
  
  // Export state
  const [isExporting, setIsExporting] = useState(false);
  const [exportProgress, setExportProgress] = useState(0);
  const [exportJobId, setExportJobId] = useState<string | null>(null);
  const [exportError, setExportError] = useState<string | null>(null);
  
  // Get selected preset details
  const currentPreset = EXPORT_PRESETS.find(p => p.id === selectedPreset) || EXPORT_PRESETS[0];
  
  // =============================================================================
  // Handlers
  // =============================================================================
  
  const handleStartExport = useCallback(async () => {
    setIsExporting(true);
    setExportProgress(0);
    setExportError(null);
    
    const resolution = selectedPreset === 'custom' 
      ? `${customWidth}x${customHeight}`
      : currentPreset.resolution;
    
    try {
      const response = await fetch('/api/video-editor/export', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          project_id: projectId || 'default',
          format: customFormat,
          preset: selectedPreset,
          resolution,
          quality: customQuality,
        }),
      });
      
      if (response.ok) {
        const data = await response.json();
        setExportJobId(data.job_id);
        
        // Poll for progress
        const pollProgress = async () => {
          const statusResponse = await fetch(`/api/video-editor/export/${data.job_id}/status`);
          const statusData = await statusResponse.json();
          
          setExportProgress(statusData.progress);
          
          if (statusData.status === 'completed') {
            setIsExporting(false);
          } else if (statusData.status === 'failed') {
            setExportError(statusData.error || 'Export failed');
            setIsExporting(false);
          } else {
            setTimeout(pollProgress, 1000);
          }
        };
        
        setTimeout(pollProgress, 1000);
      } else {
        setExportError('Failed to start export');
        setIsExporting(false);
      }
    } catch (error) {
      setExportError('Export error: ' + (error as Error).message);
      setIsExporting(false);
    }
  }, [projectId, selectedPreset, currentPreset, customWidth, customHeight, customFormat, customQuality]);
  
  const handleCancelExport = useCallback(() => {
    if (exportJobId) {
      fetch(`/api/video-editor/export/${exportJobId}/cancel`, { method: 'POST' });
    }
    setIsExporting(false);
    setExportProgress(0);
    setExportJobId(null);
  }, [exportJobId]);
  
  const handleDownload = useCallback(() => {
    if (exportJobId) {
      window.open(`/api/video-editor/export/${exportJobId}/download`, '_blank');
    }
  }, [exportJobId]);
  
  // =============================================================================
  // Render
  // =============================================================================
  
  // Group presets by platform
  const presetsByPlatform = EXPORT_PRESETS.reduce((acc, preset) => {
    if (!acc[preset.platform]) {
      acc[preset.platform] = [];
    }
    acc[preset.platform].push(preset);
    return acc;
  }, {} as Record<string, ExportPreset[]>);
  
  return (
    <div className="export-panel">
      <div className="export-panel-header">
        <h3>Export Video</h3>
      </div>
      
      {/* Preset Selection */}
      <div className="export-section">
        <h4>Platform Presets</h4>
        
        {Object.entries(presetsByPlatform).map(([platform, presets]) => (
          <div key={platform} className="platform-group">
            <div className="platform-label">{platform}</div>
            <div className="preset-grid">
              {presets.map(preset => (
                <button
                  key={preset.id}
                  className={`preset-btn ${selectedPreset === preset.id ? 'selected' : ''}`}
                  onClick={() => setSelectedPreset(preset.id)}
                  disabled={isExporting}
                >
                  <span className="preset-name">{preset.name}</span>
                  <span className="preset-resolution">{preset.resolution}</span>
                </button>
              ))}
            </div>
          </div>
        ))}
      </div>
      
      {/* Custom Settings (if custom selected) */}
      {selectedPreset === 'custom' && (
        <div className="export-section">
          <h4>Custom Settings</h4>
          
          <div className="custom-row">
            <div className="custom-field">
              <label>Width</label>
              <input
                type="number"
                value={customWidth}
                onChange={(e) => setCustomWidth(parseInt(e.target.value) || 1920)}
                min={320}
                max={7680}
                className="custom-input"
                disabled={isExporting}
                title="Video width in pixels"
              />
            </div>
            <span className="custom-separator">├ù</span>
            <div className="custom-field">
              <label>Height</label>
              <input
                type="number"
                value={customHeight}
                onChange={(e) => setCustomHeight(parseInt(e.target.value) || 1080)}
                min={240}
                max={4320}
                className="custom-input"
                disabled={isExporting}
                title="Video height in pixels"
              />
            </div>
          </div>
          
          <div className="custom-field">
            <label>Format</label>
            <select
              value={customFormat}
              onChange={(e) => setCustomFormat(e.target.value)}
              className="custom-select"
              disabled={isExporting}
              title="Select output video format"
            >
              {EXPORT_FORMATS.map(fmt => (
                <option key={fmt.id} value={fmt.id}>{fmt.name}</option>
              ))}
            </select>
          </div>
          
          <div className="custom-field">
            <label>Quality</label>
            <select
              value={customQuality}
              onChange={(e) => setCustomQuality(e.target.value)}
              className="custom-select"
              disabled={isExporting}
              title="Select output video quality"
            >
              {QUALITY_LEVELS.map(q => (
                <option key={q.id} value={q.id}>{q.name} ({q.bitrate})</option>
              ))}
            </select>
          </div>
        </div>
      )}
      
      {/* Export Summary */}
      <div className="export-summary">
        <div className="summary-row">
          <span className="summary-label">Resolution</span>
          <span className="summary-value">
            {selectedPreset === 'custom' ? `${customWidth}├ù${customHeight}` : currentPreset.resolution}
          </span>
        </div>
        <div className="summary-row">
          <span className="summary-label">Aspect Ratio</span>
          <span className="summary-value">{currentPreset.aspectRatio}</span>
        </div>
        <div className="summary-row">
          <span className="summary-label">Format</span>
          <span className="summary-value">{customFormat.toUpperCase()}</span>
        </div>
        <div className="summary-row">
          <span className="summary-label">Quality</span>
          <span className="summary-value">{customQuality.charAt(0).toUpperCase() + customQuality.slice(1)}</span>
        </div>
        <div className="summary-row">
          <span className="summary-label">Shots</span>
          <span className="summary-value">{shots.length}</span>
        </div>
      </div>
      
      {/* Progress */}
      {isExporting && (
        <div className="export-progress">
          <div className="progress-header">
            <span>Exporting...</span>
            <span>{exportProgress}%</span>
          </div>
          <div className="progress-bar">
            <div 
              className="progress-fill" 
              style={{ '--progress-width': `${exportProgress}%` } as React.CSSProperties}
            />
          </div>
        </div>
      )}
      
      {/* Error */}
      {exportError && (
        <div className="export-error">
          {exportError}
        </div>
      )}
      
      {/* Actions */}
      <div className="export-actions">
        {!isExporting ? (
          <button
            className="export-btn"
            onClick={handleStartExport}
            disabled={shots.length === 0}
          >
            Start Export
          </button>
        ) : (
          <button
            className="cancel-btn"
            onClick={handleCancelExport}
          >
            Cancel
          </button>
        )}
        
        {exportProgress === 100 && (
          <button
            className="download-btn"
            onClick={handleDownload}
          >
            Download
          </button>
        )}
      </div>
    </div>
  );
};

export default ExportPanel;

/**
 * GenerateButton Component
 * Button to generate sequence from timeline with status feedback.
 * Requirements: 7.1, 7.6
 */

import React, { useCallback, useEffect } from 'react';
import { useAppSelector, useAppDispatch } from '../../store';
import { setGenerationStatus } from '../../store/slices/projectSlice';
import { executeGenerationPipeline, validateProjectForGeneration, type ProjectData } from '../../services/storycoreService';
import './GenerateButton.css';

export const GenerateButton: React.FC = () => {
  const dispatch = useAppDispatch();
  const { shots, tracks } = useAppSelector((state) => state.timeline);
  const { generationStatus, metadata, settings } = useAppSelector((state) => state.project);
  
  const canGenerate = shots.length > 0 && tracks.length > 0;
  const isGenerating = generationStatus.state === 'processing';
  
  const handleGenerate = useCallback(async () => {
    if (!canGenerate || isGenerating) return;
    
    // Prepare project data
    const projectData: ProjectData = {
      name: metadata?.name || 'Untitled Project',
      shots: shots.map(shot => ({
        id: shot.id,
        prompt: shot.prompt,
        parameters: shot.parameters,
        referenceImages: shot.referenceImages.map(img => img.url),
      })),
      settings: {
        resolution: settings.resolution,
        fps: settings.fps,
        format: settings.format,
      },
    };

    // Validate project before generation
    const validation = validateProjectForGeneration(projectData);
    if (!validation.valid) {
      dispatch(setGenerationStatus({
        state: 'error',
        error: validation.errors.join(', '),
      }));
      return;
    }

    // Set to processing state
    dispatch(setGenerationStatus({
      state: 'processing',
      stage: 'grid',
      progress: 0,
    }));
    
    try {
      // Execute pipeline with progress updates
      const result = await executeGenerationPipeline(projectData, (progress) => {
        dispatch(setGenerationStatus({
          state: 'processing',
          stage: progress.stage,
          progress: progress.progress,
        }));
      });

      if (result.success) {
        dispatch(setGenerationStatus({
          state: 'complete',
          progress: 100,
        }));
        
        // Reset to idle after 3 seconds
        setTimeout(() => {
          dispatch(setGenerationStatus({
            state: 'idle',
          }));
        }, 3000);
      } else {
        dispatch(setGenerationStatus({
          state: 'error',
          error: result.error || 'Generation failed',
        }));
      }
    } catch (error) {
      dispatch(setGenerationStatus({
        state: 'error',
        error: error instanceof Error ? error.message : 'Unknown error occurred',
      }));
    }
  }, [canGenerate, isGenerating, dispatch, shots, metadata, settings]);

  const handleCancel = useCallback(() => {
    dispatch(setGenerationStatus({
      state: 'idle',
    }));
  }, [dispatch]);

  const getButtonText = () => {
    switch (generationStatus.state) {
      case 'processing':
        return `Generating (${generationStatus.stage})...`;
      case 'complete':
        return 'Generated!';
      case 'error':
        return 'Error';
      default:
        return 'Generate Sequence';
    }
  };

  const getButtonIcon = () => {
    switch (generationStatus.state) {
      case 'complete':
        return 'Ô£ô';
      case 'error':
        return '!';
      default:
        return 'ÔûÂ';
    }
  };

  return (
    <div className="generate-button-container" data-testid="generate-button-container">
      <button
        className={`generate-button ${generationStatus.state}`}
        onClick={handleGenerate}
        disabled={!canGenerate || isGenerating}
        aria-busy={isGenerating}
        aria-label={getButtonText()}
        data-testid="generate-button"
      >
        <span className="button-icon" data-testid="button-icon">
          {getButtonIcon()}
        </span>
        <span className="button-text" data-testid="button-text">
          {getButtonText()}
        </span>
        
        {isGenerating && (
          <div className="progress-bar" data-testid="progress-bar">
            <div 
              className="progress-fill" 
              style={{ width: `${generationStatus.progress || 0}%` }}
              data-testid="progress-fill"
            />
          </div>
        )}
      </button>

      {isGenerating && (
        <button 
          className="cancel-button" 
          onClick={handleCancel}
          aria-label="Cancel generation"
          data-testid="cancel-button"
        >
          Cancel
        </button>
      )}

      {!canGenerate && (
        <div className="generate-hint" data-testid="generate-hint">
          Add shots and tracks to generate
        </div>
      )}
      
      {generationStatus.state === 'error' && generationStatus.error && (
        <div className="generate-error" data-testid="generate-error">
          {generationStatus.error}
        </div>
      )}
    </div>
  );
};

export default GenerateButton;

