                        const val = e.target.value;
                        const currentData = selectedLayer.data as any;
                        const currentStyle = currentData.style || {};
                        const newStyle = { ...currentStyle, fillColor: val };

                        dispatch(
                          updateLayer({
                            shotId: shot.id,
                            layerId: selectedLayer.id,
                            updates: {
                              data: {
                                ...currentData,
                                style: newStyle,
                                color: val // Legacy sync
                              },
                            },
                          })
                        );
                      }}
