import React, { useState, useCallback } from 'react';
import { motionTrackingService, TrackingOptions, TrackingData, TrackingProgress } from '../../services/motionTrackingService';
import './motionTrackingPanel.css';

interface MotionTrackingPanelProps {
  shotId: string;
  onTrackingComplete?: () => void;
}

export const MotionTrackingPanel: React.FC<MotionTrackingPanelProps> = ({
  shotId,
  onTrackingComplete
}) => {
  const [trackingPoint, setTrackingPoint] = useState<{ x: number; y: number }>({ x: 960, y: 540 });
  const [startFrame, setStartFrame] = useState<number>(0);
  const [endFrame, setEndFrame] = useState<number>(100);
  const [options, setOptions] = useState<TrackingOptions>({
    method: 'point',
    algorithm: 'optical-flow',
    sensitivity: 0.7,
    adaptiveTracking: true
  });
  const [isTracking, setIsTracking] = useState(false);
  const [progress, setProgress] = useState<TrackingProgress | null>(null);
  const [activeTracks, setActiveTracks] = useState<TrackingData[]>([]);
  const [selectedTrack, setSelectedTrack] = useState<string | null>(null);

  const handleStartTracking = useCallback(async () => {
    setIsTracking(true);
    setProgress(null);

    try {
      const trackData = await motionTrackingService.startTracking(
        shotId,
        startFrame,
        endFrame,
        trackingPoint,
        options,
        (prog) => setProgress(prog)
      );

      setActiveTracks([...motionTrackingService.getActiveTracks()]);

      if (onTrackingComplete) {
        onTrackingComplete();
      }
    } catch (error) {
      console.error('Motion tracking failed:', error);
    } finally {
      setIsTracking(false);
    }
  }, [shotId, startFrame, endFrame, trackingPoint, options, onTrackingComplete]);

  const handleExportTrack = useCallback((trackId: string, format: 'json' | 'csv' | 'after-effects' | 'nuke') => {
    try {
      const exportData = motionTrackingService.exportTrackingData(trackId, format);
      
      // Create download
      const blob = new Blob([exportData.data], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `track-${trackId}.${format === 'after-effects' ? 'txt' : format}`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (error) {
      console.error('Export failed:', error);
    }
  }, []);

  const handleDeleteTrack = useCallback((trackId: string) => {
    motionTrackingService.deleteTrack(trackId);
    setActiveTracks([...motionTrackingService.getActiveTracks()]);
    if (selectedTrack === trackId) {
      setSelectedTrack(null);
    }
  }, [selectedTrack]);

  const handleUpdateTrackName = useCallback((trackId: string, newName: string) => {
    motionTrackingService.updateTrackName(trackId, newName);
    setActiveTracks([...motionTrackingService.getActiveTracks()]);
  }, []);

  return (
    <div className="motion-tracking-panel">
      <div className="tracking-header">
        <h3>AI Motion Tracking</h3>
      </div>

      <div className="tracking-setup">
        <h4>Tracking Setup</h4>
        
        <div className="tracking-point">
          <label>Tracking Point:</label>
          <div className="point-inputs">
            <input
              type="number"
              placeholder="X"
              value={trackingPoint.x}
              onChange={(e) => setTrackingPoint({ ...trackingPoint, x: parseInt(e.target.value) })}
            />
            <input
              type="number"
              placeholder="Y"
              value={trackingPoint.y}
              onChange={(e) => setTrackingPoint({ ...trackingPoint, y: parseInt(e.target.value) })}
            />
          </div>
        </div>

        <div className="frame-range">
          <div className="range-input">
            <label>Start Frame:</label>
            <input
              type="number"
              value={startFrame}
              onChange={(e) => setStartFrame(parseInt(e.target.value))}
              min={0}
            />
          </div>
          <div className="range-input">
            <label>End Frame:</label>
            <input
              type="number"
              value={endFrame}
              onChange={(e) => setEndFrame(parseInt(e.target.value))}
              min={startFrame}
            />
          </div>
        </div>

        <div className="tracking-options">
          <div className="option-group">
            <label>Method:</label>
            <select
              value={options.method}
              onChange={(e) => setOptions({
                ...options,
                method: e.target.value as 'point' | 'object' | 'feature'
              })}
            >
              <option value="point">Point Tracking</option>
              <option value="object">Object Tracking</option>
              <option value="feature">Feature Tracking</option>
            </select>
          </div>

          <div className="option-group">
            <label>Algorithm:</label>
            <select
              value={options.algorithm}
              onChange={(e) => setOptions({
                ...options,
                algorithm: e.target.value as 'optical-flow' | 'feature-matching' | 'deep-learning'
              })}
            >
              <option value="optical-flow">Optical Flow</option>
              <option value="feature-matching">Feature Matching</option>
              <option value="deep-learning">Deep Learning</option>
            </select>
          </div>

          <div className="option-group">
            <label>Sensitivity: {(options.sensitivity * 100).toFixed(0)}%</label>
            <input
              type="range"
              min={0}
              max={1}
              step={0.01}
              value={options.sensitivity}
              onChange={(e) => setOptions({
                ...options,
                sensitivity: parseFloat(e.target.value)
              })}
            />
          </div>

          <div className="option-group checkbox">
            <label>
              <input
                type="checkbox"
                checked={options.adaptiveTracking}
                onChange={(e) => setOptions({
                  ...options,
                  adaptiveTracking: e.target.checked
                })}
              />
              Adaptive Tracking
            </label>
          </div>
        </div>

        <button
          className="start-tracking-btn"
          onClick={handleStartTracking}
          disabled={isTracking}
        >
          {isTracking ? 'Tracking...' : 'Start Tracking'}
        </button>

        {progress && (
          <div className="tracking-progress">
            <div className="progress-bar">
              <div
                className="progress-fill"
                style={{ width: `${progress.percentage}%` }}
              />
            </div>
            <div className="progress-info">
              <span>Frame {progress.currentFrame} / {progress.totalFrames}</span>
              <span className={`status-${progress.status}`}>{progress.status}</span>
            </div>
            {progress.error && (
              <div className="error-message">{progress.error}</div>
            )}
          </div>
        )}
      </div>

      <div className="active-tracks">
        <h4>Active Tracks ({activeTracks.length})</h4>
        
        {activeTracks.length === 0 ? (
          <div className="no-tracks">No active tracks. Start tracking to create one.</div>
        ) : (
          <div className="tracks-list">
            {activeTracks.map((track) => (
              <div
                key={track.trackId}
                className={`track-item ${selectedTrack === track.trackId ? 'selected' : ''}`}
                onClick={() => setSelectedTrack(track.trackId)}
              >
                <div className="track-info">
                  <input
                    type="text"
                    value={track.objectName}
                    onChange={(e) => handleUpdateTrackName(track.trackId, e.target.value)}
                    onClick={(e) => e.stopPropagation()}
                  />
                  <div className="track-stats">
                    <span>{track.frames.size} frames</span>
                    <span>Confidence: {(track.confidence * 100).toFixed(0)}%</span>
                  </div>
                </div>
                <div className="track-actions">
                  <button
                    className="export-btn"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleExportTrack(track.trackId, 'json');
                    }}
                    title="Export as JSON"
                  >
                    JSON
                  </button>
                  <button
                    className="export-btn"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleExportTrack(track.trackId, 'csv');
                    }}
                    title="Export as CSV"
                  >
                    CSV
                  </button>
                  <button
                    className="export-btn"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleExportTrack(track.trackId, 'after-effects');
                    }}
                    title="Export for After Effects"
                  >
                    AE
                  </button>
                  <button
                    className="delete-btn"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleDeleteTrack(track.trackId);
                    }}
                    title="Delete track"
                  >
                    ├ù
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

/**
 * Frame Cache System
 * 
 * Implements efficient frame caching with:
 * - LRU cache with 30 frames before/after current position
 * - Adaptive quality (reduced during playback, full when paused)
 * - Debounced frame updates
 * - 200ms render target
 * 
 * Requirements: 3.2, 3.3
 */

export interface CachedFrame {
  frameNumber: number;
  imageData: ImageData | null;
  quality: 'low' | 'high';
  timestamp: number;
  renderTime: number;
}

export interface FrameCacheOptions {
  cacheRadius: number; // Frames to cache before/after current position
  maxCacheSize: number; // Maximum number of frames to cache
  lowQualityScale: number; // Scale factor for low quality (0-1)
  debounceDelay: number; // Debounce delay in ms
  renderTimeout: number; // Maximum render time in ms
}

const DEFAULT_OPTIONS: FrameCacheOptions = {
  cacheRadius: 30,
  maxCacheSize: 100,
  lowQualityScale: 0.5,
  debounceDelay: 100,
  renderTimeout: 200,
};

/**
 * Frame Cache Manager
 * 
 * Manages frame caching with LRU eviction and adaptive quality.
 */
export class FrameCache {
  private cache: Map<number, CachedFrame>;
  private options: FrameCacheOptions;
  private accessOrder: number[];
  private pendingRenders: Map<number, AbortController>;
  private debounceTimer: number | null;
  
  constructor(options: Partial<FrameCacheOptions> = {}) {
    this.cache = new Map();
    this.options = { ...DEFAULT_OPTIONS, ...options };
    this.accessOrder = [];
    this.pendingRenders = new Map();
    this.debounceTimer = null;
  }
  
  /**
   * Get a frame from cache or render it
   */
  async getFrame(
    frameNumber: number,
    quality: 'low' | 'high',
    renderFn: (frame: number, quality: 'low' | 'high', signal: AbortSignal) => Promise<ImageData | null>
  ): Promise<ImageData | null> {
    // Check cache first
    const cached = this.cache.get(frameNumber);
    
    if (cached) {
      // Update access order
      this.updateAccessOrder(frameNumber);
      
      // Return cached frame if quality matches or better
      if (cached.quality === quality || (cached.quality === 'high' && quality === 'low')) {
        return cached.imageData;
      }
      
      // If we need higher quality, re-render
      if (cached.quality === 'low' && quality === 'high') {
        return this.renderFrame(frameNumber, quality, renderFn);
      }
    }
    
    // Render new frame
    return this.renderFrame(frameNumber, quality, renderFn);
  }
  
  /**
   * Render a frame with timeout and caching
   */
  private async renderFrame(
    frameNumber: number,
    quality: 'low' | 'high',
    renderFn: (frame: number, quality: 'low' | 'high', signal: AbortSignal) => Promise<ImageData | null>
  ): Promise<ImageData | null> {
    // Cancel any pending render for this frame
    const existingController = this.pendingRenders.get(frameNumber);
    if (existingController) {
      existingController.abort();
    }
    
    // Create abort controller for this render
    const controller = new AbortController();
    this.pendingRenders.set(frameNumber, controller);
    
    const startTime = performance.now();
    
    try {
      // Render with timeout
      const imageData = await Promise.race([
        renderFn(frameNumber, quality, controller.signal),
        this.createTimeout(this.options.renderTimeout),
      ]);
      
      const renderTime = performance.now() - startTime;
      
      // Cache the result
      if (imageData && !controller.signal.aborted) {
        this.cacheFrame({
          frameNumber,
          imageData,
          quality,
          timestamp: Date.now(),
          renderTime,
        });
      }
      
      return imageData;
    } catch (error) {
      if (error instanceof Error && error.name === 'AbortError') {
        // Render was cancelled, return null
        return null;
      }
      console.error(`Frame render error for frame ${frameNumber}:`, error);
      return null;
    } finally {
      this.pendingRenders.delete(frameNumber);
    }
  }
  
  /**
   * Create a timeout promise
   */
  private createTimeout(ms: number): Promise<never> {
    return new Promise((_, reject) => {
      setTimeout(() => reject(new Error('Render timeout')), ms);
    });
  }
  
  /**
   * Cache a frame with LRU eviction
   */
  private cacheFrame(frame: CachedFrame): void {
    // Add to cache
    this.cache.set(frame.frameNumber, frame);
    this.updateAccessOrder(frame.frameNumber);
    
    // Evict old frames if cache is full
    while (this.cache.size > this.options.maxCacheSize) {
      const oldestFrame = this.accessOrder.shift();
      if (oldestFrame !== undefined) {
        this.cache.delete(oldestFrame);
      }
    }
  }
  
  /**
   * Update access order for LRU
   */
  private updateAccessOrder(frameNumber: number): void {
    // Remove from current position
    const index = this.accessOrder.indexOf(frameNumber);
    if (index !== -1) {
      this.accessOrder.splice(index, 1);
    }
    
    // Add to end (most recently used)
    this.accessOrder.push(frameNumber);
  }
  
  /**
   * Preload frames around current position
   */
  async preloadFrames(
    centerFrame: number,
    quality: 'low' | 'high',
    renderFn: (frame: number, quality: 'low' | 'high', signal: AbortSignal) => Promise<ImageData | null>
  ): Promise<void> {
    const { cacheRadius } = this.options;
    const startFrame = Math.max(0, centerFrame - cacheRadius);
    const endFrame = centerFrame + cacheRadius;
    
    // Preload frames in order of proximity to center
    const framesToLoad: number[] = [];
    for (let i = 0; i <= cacheRadius; i++) {
      if (centerFrame + i <= endFrame) {
        framesToLoad.push(centerFrame + i);
      }
      if (centerFrame - i >= startFrame && i > 0) {
        framesToLoad.push(centerFrame - i);
      }
    }
    
    // Load frames that aren't already cached
    const loadPromises = framesToLoad
      .filter((frame) => !this.cache.has(frame))
      .map((frame) => this.getFrame(frame, quality, renderFn));
    
    // Load in background (don't await)
    Promise.all(loadPromises).catch((error) => {
      console.warn('Preload error:', error);
    });
  }
  
  /**
   * Debounced frame update
   */
  debouncedUpdate(
    frameNumber: number,
    quality: 'low' | 'high',
    renderFn: (frame: number, quality: 'low' | 'high', signal: AbortSignal) => Promise<ImageData | null>,
    callback: (imageData: ImageData | null) => void
  ): void {
    // Clear existing timer
    if (this.debounceTimer !== null) {
      window.clearTimeout(this.debounceTimer);
    }
    
    // Set new timer
    this.debounceTimer = window.setTimeout(async () => {
      const imageData = await this.getFrame(frameNumber, quality, renderFn);
      callback(imageData);
      this.debounceTimer = null;
    }, this.options.debounceDelay);
  }
  
  /**
   * Clear all cached frames
   */
  clear(): void {
    // Cancel all pending renders
    this.pendingRenders.forEach((controller) => controller.abort());
    this.pendingRenders.clear();
    
    // Clear cache
    this.cache.clear();
    this.accessOrder = [];
    
    // Clear debounce timer
    if (this.debounceTimer !== null) {
      window.clearTimeout(this.debounceTimer);
      this.debounceTimer = null;
    }
  }
  
  /**
   * Get cache statistics
   */
  getStats(): {
    size: number;
    maxSize: number;
    hitRate: number;
    avgRenderTime: number;
  } {
    const frames = Array.from(this.cache.values());
    const avgRenderTime = frames.length > 0
      ? frames.reduce((sum, f) => sum + f.renderTime, 0) / frames.length
      : 0;
    
    return {
      size: this.cache.size,
      maxSize: this.options.maxCacheSize,
      hitRate: 0, // TODO: Track hits/misses
      avgRenderTime,
    };
  }
  
  /**
   * Invalidate frames in a range
   */
  invalidateRange(startFrame: number, endFrame: number): void {
    for (let frame = startFrame; frame <= endFrame; frame++) {
      this.cache.delete(frame);
      const index = this.accessOrder.indexOf(frame);
      if (index !== -1) {
        this.accessOrder.splice(index, 1);
      }
    }
  }
  
  /**
   * Invalidate all frames
   */
  invalidateAll(): void {
    this.cache.clear();
    this.accessOrder = [];
  }
}

/**
 * Create a frame render function for canvas
 */
export function createCanvasRenderFunction(
  canvas: HTMLCanvasElement,
  shots: unknown[],
  zoomLevel: number,
  fps: number = 24
): (frame: number, quality: 'low' | 'high', signal: AbortSignal) => Promise<ImageData | null> {
  return async (frame: number, quality: 'low' | 'high', signal: AbortSignal): Promise<ImageData | null> => {
    if (signal.aborted) {
      return null;
    }
    
    const ctx = canvas.getContext('2d');
    if (!ctx) {
      return null;
    }
    
    // Find shot at this frame
    const framePosition = frame * zoomLevel;
    const currentShot = shots.find((shot) =>
      framePosition >= shot.startTime * zoomLevel &&
      framePosition < (shot.startTime + shot.duration) * zoomLevel
    );
    
    // Determine render scale based on quality
    const scale = quality === 'low' ? 0.5 : 1.0;
    const width = Math.floor(canvas.width * scale);
    const height = Math.floor(canvas.height * scale);
    
    // Create temporary canvas for rendering
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = width;
    tempCanvas.height = height;
    const tempCtx = tempCanvas.getContext('2d');
    
    if (!tempCtx) {
      return null;
    }
    
    // Check for abort before rendering
    if (signal.aborted) {
      return null;
    }
    
    // Render frame
    tempCtx.fillStyle = '#000000';
    tempCtx.fillRect(0, 0, width, height);
    
    if (currentShot) {
      // Draw shot content
      const gradient = tempCtx.createLinearGradient(0, 0, width, height);
      gradient.addColorStop(0, '#1a1a2e');
      gradient.addColorStop(1, '#16213e');
      tempCtx.fillStyle = gradient;
      tempCtx.fillRect(0, 0, width, height);
      
      // Draw shot info (scaled)
      const fontSize = Math.floor(24 * scale);
      tempCtx.fillStyle = '#ffffff';
      tempCtx.font = `${fontSize}px sans-serif`;
      tempCtx.textAlign = 'center';
      tempCtx.fillText(currentShot.name, width / 2, height / 2 - 20 * scale);
      
      const smallFontSize = Math.floor(16 * scale);
      tempCtx.font = `${smallFontSize}px sans-serif`;
      tempCtx.fillStyle = '#aaaaaa';
      tempCtx.fillText(`Frame: ${frame}`, width / 2, height / 2 + 20 * scale);
    }
    
    // Check for abort before returning
    if (signal.aborted) {
      return null;
    }
    
    // Get image data
    return tempCtx.getImageData(0, 0, width, height);
  };
}

/**
 * Format timecode from frame number
 */
export function formatTimecode(frames: number, fps: number = 24): string {
  const totalSeconds = Math.floor(frames / fps);
  const remainingFrames = frames % fps;
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}:${remainingFrames.toString().padStart(2, '0')}`;
}

/**
 * Preview Frame Drop Target Component
 * 
 * Provides drop zone for preview frame to accept dragged assets.
 * Enhanced with multi-select support, validation, and undo/redo integration.
 * Requirements: 15.6, 15.7 - Apply assets to selected shot via preview frame with multi-select
 */

import React, { useCallback } from 'react';
import { useDrop } from 'react-dnd';
import { DND_ITEM_TYPES, type DraggedAssetItem } from '../AssetLibrary/DraggableAsset';
import { useAppDispatch, useAppSelector } from '../../store';
import { addReferenceImage, updateShot } from '../../store/slices/timelineSlice';
import type { Asset, Shot } from '../../types';

// ============================================================================
// Types
// ============================================================================

interface PreviewDropTargetProps {
  children: React.ReactNode;
  onAssetDrop?: (assets: Asset[]) => void;
}

/**
 * Applies an asset to a shot based on asset type
 */
function applyAssetToShot(
  asset: Asset,
  shot: Shot,
  dispatch: ReturnType<typeof useAppDispatch>
): void {
  switch (asset.type) {
    case 'character':
    case 'environment':
    case 'prop':
      // Add as reference image
      dispatch(addReferenceImage({
        shotId: shot.id,
        image: {
          id: `ref-${Date.now()}-${Math.random()}`,
          url: asset.thumbnailUrl,
          weight: 0.7,
          source: 'library',
        },
      }));
      break;

    case 'visual-style':
      // Apply visual style to shot
      dispatch(updateShot({
        id: shot.id,
        updates: {
          prompt: shot.prompt + ` in ${asset.name} style`,
        },
      }));
      
      // Add as reference image with lower weight
      dispatch(addReferenceImage({
        shotId: shot.id,
        image: {
          id: `ref-${Date.now()}-${Math.random()}`,
          url: asset.thumbnailUrl,
          weight: 0.5,
          source: 'library',
        },
      }));
      break;

    case 'camera-preset':
      // Apply camera preset parameters
      if (asset.metadata.cameraMetadata) {
        dispatch(updateShot({
          id: shot.id,
          updates: {
            prompt: shot.prompt + ` with ${asset.name} camera movement`,
          },
        }));
      }
      break;

    case 'lighting-rig':
      // Apply lighting rig parameters
      if (asset.metadata.lightingMetadata) {
        dispatch(updateShot({
          id: shot.id,
          updates: {
            prompt: shot.prompt + ` with ${asset.name} lighting`,
          },
        }));
      }
      break;

    case 'template':
      // Templates are handled differently (not applicable to single shots)
      console.warn('Templates should be dropped on timeline, not preview frame');
      break;

    default:
      // Default: add as reference image
      dispatch(addReferenceImage({
        shotId: shot.id,
        image: {
          id: `ref-${Date.now()}-${Math.random()}`,
          url: asset.thumbnailUrl,
          weight: 0.7,
          source: 'library',
        },
      }));
  }
}

// ============================================================================
// Component
// ============================================================================

export const PreviewDropTarget: React.FC<PreviewDropTargetProps> = ({
  children,
  onAssetDrop,
}) => {
  const dispatch = useAppDispatch();
  const { shots, selectedElements, playheadPosition, zoomLevel } = useAppSelector((state) => state.timeline);

  // Get currently selected shot or shot at playhead
  const getCurrentShot = useCallback(() => {
    // First, try to get selected shot
    if (selectedElements.length > 0) {
      const selectedShot = shots.find((s: Shot) => s.id === selectedElements[0]);
      if (selectedShot) return selectedShot;
    }

    // Otherwise, get shot at playhead position
    const currentShot = shots.find((shot: Shot) =>
      playheadPosition >= shot.startTime &&
      playheadPosition < (shot.startTime + shot.duration)
    );

    return currentShot;
  }, [shots, selectedElements, playheadPosition]);

  // Handle asset drop
  const handleDrop = useCallback((item: DraggedAssetItem) => {
    const currentShot = getCurrentShot();
    
    if (!currentShot) {
      console.warn('No shot selected or at playhead position');
      return;
    }

    // Support multi-select in the future by wrapping single asset in array
    const assets = [item.asset];

    console.log('Asset(s) dropped on preview frame:', {
      assets: assets.map(a => a.name),
      shot: currentShot.name,
      assetTypes: assets.map(a => a.type),
    });

    // Call custom handler if provided
    if (onAssetDrop) {
      onAssetDrop(assets);
      return;
    }

    // Apply each asset to the current shot
    assets.forEach((asset) => {
      applyAssetToShot(asset, currentShot, dispatch);
    });
  }, [dispatch, getCurrentShot, onAssetDrop]);

  // Set up drop target
  const [{ isOver, canDrop }, drop] = useDrop<
    DraggedAssetItem,
    void,
    { isOver: boolean; canDrop: boolean }
  >(
    () => ({
      accept: DND_ITEM_TYPES.ASSET,
      drop: handleDrop,
      canDrop: () => {
        // Can only drop if there's a shot selected or at playhead
        return getCurrentShot() !== undefined;
      },
      collect: (monitor) => ({
        isOver: monitor.isOver(),
        canDrop: monitor.canDrop(),
      }),
    }),
    [handleDrop, getCurrentShot]
  );

  // Determine drop target state
  const isActive = isOver && canDrop;
  const isInvalid = isOver && !canDrop;
  const currentShot = getCurrentShot();

  return (
    <div
      ref={drop as any}
      className={`preview-drop-target ${isActive ? 'drop-active' : ''} ${isInvalid ? 'drop-invalid' : ''} ${canDrop && !isOver ? 'drop-ready' : ''}`}
      style={{
        position: 'relative',
        width: '100%',
        height: '100%',
      }}
    >
      {children}
      
      {/* Drop indicator overlay */}
      {isActive && currentShot && (
        <div className="drop-indicator">
          <div className="drop-indicator-content">
            <span className="drop-icon">­ƒÄ»</span>
            <span className="drop-text">Apply to {currentShot.name}</span>
          </div>
        </div>
      )}
      
      {/* Invalid drop indicator */}
      {isInvalid && (
        <div className="drop-indicator invalid">
          <div className="drop-indicator-content">
            <span className="drop-icon">­ƒÜ½</span>
            <span className="drop-text">No shot at playhead</span>
          </div>
        </div>
      )}
    </div>
  );
};

export default PreviewDropTarget;

/**
 * Preview Frame Component
 * 
 * Real-time video preview with playback controls and frame rendering.
 * Requirements: 3.1, 3.2, 3.3, 3.4, 3.5, 3.6, 3.7, 15.6
 */

import React, { useRef, useState, useCallback, useEffect, useMemo } from 'react';
import { useAppDispatch, useAppSelector } from '../../store';
import { setPlayheadPosition } from '../../store/slices/timelineSlice';
import { setPlaybackState, setPlaybackSpeed } from '../../store/slices/previewSlice';
import { PreviewDropTarget } from './PreviewDropTarget';
import { ViewModeToggle, type ViewMode } from './ViewModeToggle';
import { SceneView3D } from './SceneView3D';
import { FrameCache, createCanvasRenderFunction } from './FrameCache';
import { TransformOverlay } from './TransformOverlay';
import type { PlaybackState, Shot, Layer } from '../../types';
import './previewFrame.css';
import './previewDropTarget.css';
import './viewModeToggle.css';
import './sceneView3D.css';

// ============================================================================
// Constants
// ============================================================================

const MIN_RESOLUTION = { width: 640, height: 360 };
const PLAYBACK_SPEEDS = [0.25, 0.5, 1, 1.5, 2];
const DEFAULT_FPS = 24;

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Format frames to timecode (HH:MM:SS:FF)
 */
function formatTimecode(frames: number, fps: number = DEFAULT_FPS): string {
  const totalSeconds = Math.floor(frames / fps);
  const remainingFrames = frames % fps;
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}:${remainingFrames.toString().padStart(2, '0')}`;
}

/**
 * Calculate frame from position
 */
function getFrameFromPosition(position: number, zoomLevel: number): number {
  return Math.floor(position / zoomLevel);
}

// ============================================================================
// Component
// ============================================================================

export const PreviewFrame: React.FC = () => {
  const dispatch = useAppDispatch();

  // Redux state
  const { playheadPosition, zoomLevel, duration, shots, selectedElements } = useAppSelector((state) => state.timeline);
  const { playbackState, playbackSpeed } = useAppSelector((state) => state.preview);
  const { settings } = useAppSelector((state) => state.project);

  // Local state
  const [viewMode, setViewMode] = useState<ViewMode>('video');
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showSafeZones, setShowSafeZones] = useState(false);
  const [zoom, setZoom] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [cachedImageData, setCachedImageData] = useState<ImageData | null>(null);

  // Refs
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const animationFrameRef = useRef<number | null>(null);
  const lastFrameTimeRef = useRef<number>(0);
  const frameCacheRef = useRef<FrameCache | null>(null);

  // Calculate current frame
  const currentFrame = useMemo(() => {
    return getFrameFromPosition(playheadPosition, zoomLevel);
  }, [playheadPosition, zoomLevel]);

  // Get current shot for preview
  const currentShot = useMemo(() => {
    return shots.find((shot: Shot) =>
      playheadPosition >= shot.startTime * zoomLevel &&
      playheadPosition < (shot.startTime + shot.duration) * zoomLevel
    );
  }, [shots, playheadPosition, zoomLevel]);

  // Get selected layer for transform overlay
  const selectedLayer = useMemo(() => {
    if (selectedElements.length === 0) return null;
    const targetId = selectedElements[0];

    // Check if it's a layer ID within a shot
    for (const shot of shots) {
      const layer = shot.layers.find((l: Layer) => l.id === targetId);
      if (layer) return layer;
    }
    return null;
  }, [shots, selectedElements]);

  // Calculate total frames
  const totalFrames = useMemo(() => {
    return Math.ceil(duration / zoomLevel);
  }, [duration, zoomLevel]);

  // Canvas dimensions
  const canvasWidth = settings?.resolution?.width || 1280;
  const canvasHeight = settings?.resolution?.height || 720;
  const aspectRatio = canvasWidth / canvasHeight;

  // Initialize frame cache
  useEffect(() => {
    if (!frameCacheRef.current) {
      frameCacheRef.current = new FrameCache({
        cacheRadius: 30,
        maxCacheSize: 100,
        lowQualityScale: 0.5,
        debounceDelay: 100,
        renderTimeout: 200,
      });
    }

    return () => {
      frameCacheRef.current?.clear();
    };
  }, []);

  // Create render function
  const renderFunction = useMemo(() => {
    if (!canvasRef.current) return null;
    return createCanvasRenderFunction(
      canvasRef.current,
      shots,
      zoomLevel,
      settings?.fps || DEFAULT_FPS
    );
  }, [shots, zoomLevel, settings?.fps]);

  // Render frame to canvas
  const renderFrame = useCallback((frame: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Use cached image data if available
    if (cachedImageData) {
      // Clear canvas
      ctx.fillStyle = '#000000';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Draw cached image data
      ctx.putImageData(cachedImageData, 0, 0);

      // Draw shot info overlay
      if (currentShot) {
        ctx.fillStyle = '#ffffff';
        ctx.font = '24px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(currentShot.name, canvas.width / 2, canvas.height / 2 - 20);

        ctx.font = '16px sans-serif';
        ctx.fillStyle = '#aaaaaa';
        ctx.fillText(`Frame: ${frame} | Time: ${formatTimecode(frame)}`, canvas.width / 2, canvas.height / 2 + 20);
      }
    } else {
      // Fallback rendering (placeholder)
      ctx.fillStyle = '#000000';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      if (currentShot) {
        const gradient = ctx.createLinearGradient(0, 0, canvas.width, canvas.height);
        gradient.addColorStop(0, '#1a1a2e');
        gradient.addColorStop(1, '#16213e');
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        ctx.fillStyle = '#ffffff';
        ctx.font = '24px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(currentShot.name, canvas.width / 2, canvas.height / 2 - 20);

        ctx.font = '16px sans-serif';
        ctx.fillStyle = '#aaaaaa';
        ctx.fillText(`Frame: ${frame} | Time: ${formatTimecode(frame)}`, canvas.width / 2, canvas.height / 2 + 20);

        if (currentShot.prompt) {
          ctx.font = '14px sans-serif';
          const words = currentShot.prompt.split(' ');
          const lines: string[] = [];
          let currentLine = '';

          words.forEach((word: string) => {
            if ((currentLine + word).length < 50) {
              currentLine += word + ' ';
            } else {
              lines.push(currentLine);
              currentLine = word + ' ';
            }
          });
          if (currentLine) lines.push(currentLine);

          ctx.fillStyle = '#888888';
          ctx.textAlign = 'left';
          lines.slice(0, 3).forEach((line, i) => {
            ctx.fillText(line.trim(), 20, canvas.height - 60 + i * 20);
          });
        }
      } else {
        ctx.fillStyle = '#333333';
        ctx.font = '18px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('No shot at current position', canvas.width / 2, canvas.height / 2);
      }
    }

    // Draw safe zones if enabled
    if (showSafeZones) {
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
      ctx.lineWidth = 1;

      // Action safe (90%)
      const actionSafeMargin = 0.05;
      ctx.strokeRect(
        canvas.width * actionSafeMargin,
        canvas.height * actionSafeMargin,
        canvas.width * (1 - actionSafeMargin * 2),
        canvas.height * (1 - actionSafeMargin * 2)
      );

      // Title safe (80%)
      const titleSafeMargin = 0.1;
      ctx.strokeRect(
        canvas.width * titleSafeMargin,
        canvas.height * titleSafeMargin,
        canvas.width * (1 - titleSafeMargin * 2),
        canvas.height * (1 - titleSafeMargin * 2)
      );

      // Center cross
      ctx.beginPath();
      ctx.moveTo(canvas.width / 2 - 20, canvas.height / 2);
      ctx.lineTo(canvas.width / 2 + 20, canvas.height / 2);
      ctx.moveTo(canvas.width / 2, canvas.height / 2 - 20);
      ctx.lineTo(canvas.width / 2, canvas.height / 2 + 20);
      ctx.stroke();
    }
  }, [currentShot, showSafeZones, cachedImageData]);

  // Render frame when playhead changes
  useEffect(() => {
    renderFrame(currentFrame);
  }, [currentFrame, renderFrame]);

  // Update cached frame with debouncing and adaptive quality
  useEffect(() => {
    const frameCache = frameCacheRef.current;
    const renderFn = renderFunction;

    if (!frameCache || !renderFn) return;

    // Determine quality based on playback state
    const quality = playbackState === 'playing' ? 'low' : 'high';

    // Debounced update for current frame
    frameCache.debouncedUpdate(currentFrame, quality, renderFn, (imageData) => {
      setCachedImageData(imageData);
    });

    // Preload frames around current position when paused
    if (playbackState === 'paused' || playbackState === 'stopped') {
      frameCache.preloadFrames(currentFrame, 'high', renderFn);
    }
  }, [currentFrame, playbackState, renderFunction]);

  // Invalidate cache when shots change
  useEffect(() => {
    const frameCache = frameCacheRef.current;
    if (frameCache) {
      frameCache.invalidateAll();
      setCachedImageData(null);
    }
  }, [shots]);

  // Playback loop
  const playbackLoop = useCallback((timestamp: number) => {
    if (playbackState !== 'playing') return;

    const fps = settings?.fps || DEFAULT_FPS;
    const frameInterval = 1000 / fps;
    const elapsed = timestamp - lastFrameTimeRef.current;

    if (elapsed >= frameInterval) {
      const framesToAdvance = Math.floor(elapsed / frameInterval);
      const newPosition = playheadPosition + framesToAdvance * zoomLevel * playbackSpeed;

      if (newPosition >= duration * zoomLevel) {
        // Loop or stop at end
        dispatch(setPlayheadPosition(0));
        dispatch(setPlaybackState('stopped'));
        return;
      }

      dispatch(setPlayheadPosition(newPosition));
      lastFrameTimeRef.current = timestamp - (elapsed % frameInterval);
    }

    animationFrameRef.current = requestAnimationFrame(playbackLoop);
  }, [playbackState, playheadPosition, zoomLevel, duration, playbackSpeed, settings, dispatch]);

  // Start/stop playback
  useEffect(() => {
    if (playbackState === 'playing') {
      lastFrameTimeRef.current = performance.now();
      animationFrameRef.current = requestAnimationFrame(playbackLoop);
    } else {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    }

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, [playbackState, playbackLoop]);

  // Playback controls
  const handlePlayPause = useCallback(() => {
    const newState: PlaybackState = playbackState === 'playing' ? 'paused' : 'playing';
    dispatch(setPlaybackState(newState));
  }, [playbackState, dispatch]);

  const handleStop = useCallback(() => {
    dispatch(setPlaybackState('stopped'));
    dispatch(setPlayheadPosition(0));
  }, [dispatch]);

  const handleFrameStep = useCallback((direction: 'forward' | 'backward') => {
    const frameAdvance = direction === 'forward' ? zoomLevel : -zoomLevel;
    dispatch(setPlayheadPosition(Math.max(0, playheadPosition + frameAdvance)));
  }, [dispatch, playheadPosition, zoomLevel]);

  const handleSeek = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const progress = parseFloat(e.target.value);
    const newPosition = (progress / 100) * duration * zoomLevel;
    dispatch(setPlayheadPosition(newPosition));
  }, [dispatch, duration, zoomLevel]);

  // Zoom controls
  const handleZoomIn = useCallback(() => {
    setZoom((prev) => Math.min(prev * 1.25, 4));
  }, []);

  const handleZoomOut = useCallback(() => {
    setZoom((prev) => Math.max(prev / 1.25, 0.25));
  }, []);

  const handleZoomReset = useCallback(() => {
    setZoom(1);
    setPan({ x: 0, y: 0 });
  }, []);

  // Pan controls
  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    if (e.button === 0) { // Left click for pan
      setIsDragging(true);
      setDragStart({ x: e.clientX - pan.x, y: e.clientY - pan.y });
    }
  }, [pan]);

  const handleMouseMove = useCallback((e: React.MouseEvent) => {
    if (isDragging) {
      setPan({
        x: e.clientX - dragStart.x,
        y: e.clientY - dragStart.y,
      });
    }
  }, [isDragging, dragStart]);

  const handleMouseUp = useCallback(() => {
    setIsDragging(false);
  }, []);

  // Fullscreen
  const toggleFullscreen = useCallback(() => {
    if (!document.fullscreenElement) {
      containerRef.current?.requestFullscreen();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  }, []);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Ignore if typing in input
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) {
        return;
      }

      switch (e.code) {
        case 'Space':
          e.preventDefault();
          handlePlayPause();
          break;
        case 'KeyK':
        case 'KeyJ':
          if (e.shiftKey) {
            // Reverse playback
            handlePlayPause();
          }
          break;
        case 'ArrowLeft':
          e.preventDefault();
          handleFrameStep('backward');
          break;
        case 'ArrowRight':
          e.preventDefault();
          handleFrameStep('forward');
          break;
        case 'Home':
          e.preventDefault();
          dispatch(setPlayheadPosition(0));
          break;
        case 'End':
          e.preventDefault();
          dispatch(setPlayheadPosition(duration * zoomLevel));
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handlePlayPause, handleFrameStep, dispatch, duration, zoomLevel]);

  // Calculate canvas display size
  const containerWidth = 640;
  const containerHeight = 360;

  // Handle view mode change
