        onPuppetUpdate(puppet);
      }
    }
  }, [selectedPuppet, puppets, onPuppetUpdate]);

  // Camera controls
  const handleCameraReset = useCallback(() => {
    setCamera({
      position: { x: 0, y: 1.5, z: 5 },
      rotation: { x: 0, y: 0, z: 0 },
      fov: 60,
    });
  }, []);

  const handleCameraMove = useCallback((direction: 'forward' | 'backward' | 'left' | 'right' | 'up' | 'down') => {
    setCamera((prev) => {
      const speed = 0.5;
      const newPosition = { ...prev.position };

      switch (direction) {
        case 'forward':
          newPosition.z -= speed;
          break;
        case 'backward':
          newPosition.z += speed;
          break;
        case 'left':
          newPosition.x -= speed;
          break;
        case 'right':
          newPosition.x += speed;
          break;
        case 'up':
          newPosition.y += speed;
          break;
        case 'down':
          newPosition.y -= speed;
          break;
      }

      return { ...prev, position: newPosition };
    });
  }, []);

