    setEnvironment((prev) => ({ ...prev, lighting }));
  }, []);

  const handleAddProp = useCallback((type: string) => {
    setEnvironment((prev) => ({
      ...prev,
      props: [
        ...prev.props,
        {
          id: `prop-${Date.now()}`,
          type,
          position: { x: Math.random() * 2 - 1, y: 0, z: Math.random() * 2 - 1 },
        },
