  { value: 'important', label: 'Important', icon: 'Ô¡É' },
  { value: 'bookmark', label: 'Bookmark', icon: '­ƒöû' },
  { value: 'custom', label: 'Custom', icon: '­ƒôî' },
];

export const MarkerDialog: React.FC<MarkerDialogProps> = ({
  isOpen,
  onClose,
  onSave,
  onDelete,
  marker,
  defaultPosition = 0,
}) => {
  const [label, setLabel] = useState('');
  const [description, setDescription] = useState('');
  const [type, setType] = useState<MarkerType>('info');
  const [color, setColor] = useState(MARKER_COLORS.info);
  const [isCustomColor, setIsCustomColor] = useState(false);
  const [showConfirmDelete, setShowConfirmDelete] = useState(false);

  // Initialize form when opened
  useEffect(() => {
    if (isOpen) {
      if (marker) {
        setLabel(marker.label || '');
        setDescription(marker.description || '');
        setType(marker.type || 'info');
        setColor(marker.color || MARKER_COLORS[marker.type || 'info']);
        
        // Detect if color is custom
        const isStandardColor = Object.values(MARKER_COLORS).includes(marker.color);
        setIsCustomColor(marker.color ? !isStandardColor : false);
      } else {
        setLabel('');
        setDescription('');
        setType('info');
        setColor(MARKER_COLORS.info);
        setIsCustomColor(false);
      }
      setShowConfirmDelete(false);
    }
  }, [isOpen, marker]);

  // Handle type change and update color if not using custom color
  const handleTypeChange = (newType: MarkerType) => {
    setType(newType);
    if (!isCustomColor) {
      setColor(MARKER_COLORS[newType]);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      label,
      description,
      type,
      color,
      position: marker ? marker.position : defaultPosition,
    });
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="timeline-dialog-overlay" onClick={onClose} role="dialog" aria-modal="true" aria-labelledby="marker-dialog-title">
      <div className="timeline-dialog marker-dialog" onClick={(e) => e.stopPropagation()}>
        
        <div className="dialog-header">
          <h2 id="marker-dialog-title">{marker ? 'Edit Marker' : 'Create Marker'}</h2>
          <button className="close-btn" onClick={onClose} aria-label="Close dialog">├ù</button>
        </div>

        <form onSubmit={handleSubmit} className="dialog-content">
          <div className="form-group">
            <label htmlFor="marker-label">Label</label>
            <input
              id="marker-label"
              type="text"
              value={label}
              onChange={(e) => setLabel(e.target.value)}
              placeholder="e.g., Fix lighting here"
              autoFocus
              required
            />
          </div>

          <div className="form-group">
            <label htmlFor="marker-description">Description (Optional)</label>
            <textarea
              id="marker-description"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Add more details about this marker..."
              rows={3}
            />
          </div>

          <div className="form-group">
            <label>Marker Type</label>
            <div className="marker-type-selector">
              {MARKER_TYPES.map((t) => (
                <button
                  key={t.value}
                  type="button"
                  className={`type-btn ${type === t.value ? 'selected' : ''}`}
                  onClick={() => handleTypeChange(t.value)}
                  title={t.label}
                >
                  <span className="type-icon">{t.icon}</span>
                  <span className="type-label">{t.label}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="form-group">
            <label htmlFor="marker-color">Color</label>
            <div className="color-picker-container">
              <input
                id="marker-color"
                type="color"
                value={color}
                onChange={(e) => {
                  setColor(e.target.value);
                  setIsCustomColor(true);
                }}
              />
              <span className="color-hex">{color}</span>
              {isCustomColor && (
                <button 
                  type="button" 
                  className="reset-color-btn"
                  onClick={() => {
                    setIsCustomColor(false);
                    setColor(MARKER_COLORS[type]);
                  }}
                >
                  Reset to default
                </button>
              )}
            </div>
          </div>

          <div className="dialog-footer">
            {marker && onDelete && (
              <div className="delete-container">
                {showConfirmDelete ? (
                  <div className="delete-confirm">
                    <span>Are you sure?</span>
                    <button type="button" className="btn btn-danger" onClick={() => { onDelete(); onClose(); }}>Yes, Delete</button>
                    <button type="button" className="btn btn-ghost" onClick={() => setShowConfirmDelete(false)}>Cancel</button>
                  </div>
                ) : (
                  <button type="button" className="btn btn-danger-outline" onClick={() => setShowConfirmDelete(true)}>
                    Delete Marker
                  </button>
                )}
              </div>
            )}
            
            <div className="primary-actions">
              <button type="button" className="btn btn-secondary" onClick={onClose}>
                Cancel
              </button>
              <button type="submit" className="btn btn-primary" disabled={!label.trim()}>
                {marker ? 'Save Changes' : 'Create Marker'}
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
};

export default MarkerDialog;

/**
 * Minimap Component
 * 
 * Overview of the entire timeline sequence with a viewport indicator
 * showing the currently visible region. Allows quick navigation by
 * dragging the viewport or clicking on the overview.
 * 
 * Requirements: 16.6, 16.7, 16.8
 */

import React, { useCallback, useRef, useEffect, useState } from 'react';
import type { Track, Shot } from '../../types';

interface MinimapProps {
  tracks: Track[];
  shots: Shot[];
  zoomLevel: number;
  scrollLeft: number;
  containerWidth: number;
  timelineWidth: number;
  totalTracksHeight: number;
  onViewportChange: (viewportX: number, viewportWidth: number) => void;
  visibleShots?: Shot[]; // For highlighting visible shots
}

export const Minimap: React.FC<MinimapProps> = ({
  tracks,
  shots,
  zoomLevel,
  scrollLeft,
  containerWidth,
  timelineWidth,
  totalTracksHeight,
  onViewportChange,
  visibleShots,
}) => {
  const minimapRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [dragStartX, setDragStartX] = useState(0);
  const [viewportStart, setViewportStart] = useState(0);
  
  // Calculate minimap dimensions
  const MINIMAP_HEIGHT = 80;
  const MINIMAP_WIDTH = 200;
  const HEIGHT_SCALE = totalTracksHeight > 0 
    ? MINIMAP_HEIGHT / totalTracksHeight 
    : 1;
  
  // Calculate visible region on minimap
  const viewportWidth = Math.max(20, containerWidth / zoomLevel * (timelineWidth / containerWidth));
  const viewportX = scrollLeft / zoomLevel * (MINIMAP_WIDTH / timelineWidth) * containerWidth;

  // Handle click on minimap to jump to position
  const handleMinimapClick = useCallback((e: React.MouseEvent) => {
    if (!minimapRef.current || isDragging) return;
    
    const rect = minimapRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    
    // Convert minimap position to timeline position
    const timelinePosition = (x / rect.width) * timelineWidth;
    const newScrollLeft = Math.max(0, Math.min(timelineWidth - containerWidth, 
      timelinePosition - containerWidth / 2));
    
    onViewportChange(newScrollLeft, containerWidth);
  }, [isDragging, timelineWidth, containerWidth, onViewportChange]);

  // Handle viewport drag
  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    setIsDragging(true);
    setDragStartX(e.clientX);
    setViewportStart(scrollLeft);
  }, [scrollLeft]);

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!isDragging || !minimapRef.current) return;
    
    const rect = minimapRef.current.getBoundingClientRect();
    const deltaX = e.clientX - dragStartX;
    const deltaTimeline = (deltaX / rect.width) * timelineWidth;
    
    const newScrollLeft = Math.max(0, Math.min(timelineWidth - containerWidth, viewportStart + deltaTimeline));
    onViewportChange(newScrollLeft, containerWidth);
  }, [isDragging, dragStartX, timelineWidth, containerWidth, viewportStart, onViewportChange]);

  const handleMouseUp = useCallback(() => {
    setIsDragging(false);
  }, []);

  // Add/remove global mouse event listeners
  useEffect(() => {
    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    }
    
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, handleMouseMove, handleMouseUp]);

  // Calculate shot positions for minimap
  const getShotStyle = (shot: Shot) => {
    const left = (shot.startTime / timelineWidth) * 100;
    const width = (shot.duration / timelineWidth) * 100;
    const trackColor = getTrackColor(shot);
    
    return {
      left: `${left}%`,
      width: `${width}%`,
      backgroundColor: trackColor,
    };
  };

  // Get track color for a shot
  const getTrackColor = (shot: Shot): string => {
    const mediaLayer = shot.layers.find(l => l.type === 'media');
    if (mediaLayer) {
      const trackColors: Record<string, string> = {
        media: '#4A90E2',
        audio: '#50C878',
        effects: '#9B59B6',
        transitions: '#E67E22',
        text: '#F39C12',
        keyframes: '#E74C3C',
      };
      return trackColors[mediaLayer.type] || '#666';
    }
    return '#666';
  };

  // Filter visible tracks
  const visibleTracks = tracks.filter(t => !t.hidden);
  
  // Calculate track heights for minimap
  const trackHeightPercentage = visibleTracks.length > 0
    ? (1 / visibleTracks.length) * 100
    : 10;

  return (
    <div className="minimap-container">
      <div className="minimap-header">
        <span className="minimap-title">Minimap</span>
        <span className="minimap-info">
          {Math.round((containerWidth / timelineWidth) * 100)}% visible
        </span>
      </div>
      
      <div
        ref={minimapRef}
        className={`minimap-canvas ${isDragging ? 'dragging' : ''}`}
        onClick={handleMinimapClick}
        style={{ height: MINIMAP_HEIGHT }}
        role="slider"
        aria-label="Timeline navigation minimap"
        aria-valuenow={scrollLeft}
        aria-valuemin={0}
        aria-valuemax={timelineWidth - containerWidth}
        tabIndex={0}
      >
        {/* Tracks overview */}
        <div className="minimap-tracks">
          {visibleTracks.map((track, index) => (
            <div
              key={track.id}
              className="minimap-track"
              style={{
                height: `${Math.max(HEIGHT_SCALE * track.height, 3)}px`,
                top: `${visibleTracks.slice(0, index).reduce((sum, t) => sum + HEIGHT_SCALE * t.height, 0)}px`,
                backgroundColor: track.color + '30',
              }}
            />
          ))}
        </div>

        {/* Shots overview */}
        <div className="minimap-shots">
          {shots.map((shot) => {
            const isVisible = visibleShots?.includes(shot);
            return (
              <div
                key={shot.id}
                className={`minimap-shot ${isVisible ? 'visible' : ''}`}
                style={getShotStyle(shot)}
                title={shot.name}
              />
            );
          })}
        </div>

        {/* Visible region indicator (viewport) */}
        <div
          className={`minimap-viewport ${isDragging ? 'dragging' : ''}`}
          style={{
            left: `${(scrollLeft / timelineWidth) * 100}%`,
            width: `${(containerWidth / timelineWidth) * 100}%`,
          }}
          onMouseDown={handleMouseDown}
        >
          <div className="viewport-handle left" />
          <div className="viewport-handle right" />
          <div className="viewport-fill" />
        </div>
      </div>
      
      {/* Time scale reference */}
      <div className="minimap-time-scale">
        <span>0:00</span>
        <span>{formatTimecode(timelineWidth / zoomLevel)}</span>
      </div>
    </div>
  );
};

// Utility function to format timecode
function formatTimecode(frames: number, fps: number = 24): string {
  const totalSeconds = Math.floor(frames / fps);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `${minutes}:${String(seconds).padStart(2, '0')}`;
}

export default Minimap;

