/**
 * ZoomSlider Component
 * 
 * Precision zoom control with slider for timeline zooming.
 * Provides smooth zoom experience with keyboard shortcuts support.
 * 
 * Requirements: 16.1, 16.2, 16.3, 16.4, 16.5
 */

import React, { useCallback, useState, useEffect } from 'react';

interface ZoomSliderProps {
  zoomLevel: number;
  onZoomChange: (zoom: number) => void;
  minZoom?: number;
  maxZoom?: number;
}

export const ZoomSlider: React.FC<ZoomSliderProps> = ({
  zoomLevel,
  onZoomChange,
  minZoom = 1,
  maxZoom = 100,
}) => {
  const [isDragging, setIsDragging] = useState(false);
  const [sliderValue, setSliderValue] = useState(zoomLevel);

  // Convert zoom level to percentage for display
  const zoomPercentage = Math.round(zoomLevel * 10);
  const minPercentage = minZoom * 10;
  const maxPercentage = maxZoom * 10;

  // Convert slider position to zoom level
  const positionToZoom = (position: number) => {
    const percentage = minPercentage + (position / 100) * (maxPercentage - minPercentage);
    return percentage / 10;
  };

  // Convert zoom level to slider position
  const zoomToPosition = (zoom: number) => {
    const percentage = zoom * 10;
    return ((percentage - minPercentage) / (maxPercentage - minPercentage)) * 100;
  };

  // Handle slider input change
  const handleSliderChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const value = parseFloat(e.target.value);
    const newZoom = positionToZoom(value);
    setSliderValue(newZoom);
    onZoomChange(newZoom);
  }, [onZoomChange]);

  // Handle zoom in button
  const handleZoomIn = useCallback(() => {
    const newZoom = Math.min(maxZoom, zoomLevel * 1.25);
    onZoomChange(newZoom);
    setSliderValue(newZoom);
  }, [zoomLevel, maxZoom, onZoomChange]);

  // Handle zoom out button
  const handleZoomOut = useCallback(() => {
    const newZoom = Math.max(minZoom, zoomLevel / 1.25);
    onZoomChange(newZoom);
    setSliderValue(newZoom);
  }, [zoomLevel, minZoom, onZoomChange]);

  // Handle fit to window
  const handleFitToWindow = useCallback(() => {
    onZoomChange(10); // Default zoom level
  }, [onZoomChange]);

  // Update slider value when zoom level changes externally
  useEffect(() => {
    if (!isDragging) {
      setSliderValue(zoomLevel);
    }
  }, [zoomLevel, isDragging]);

  // Keyboard shortcuts
  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (e.key === '=' || e.key === '+') {
      e.preventDefault();
      handleZoomIn();
    } else if (e.key === '-') {
      e.preventDefault();
      handleZoomOut();
    } else if (e.key === '0' && (e.ctrlKey || e.metaKey)) {
      e.preventDefault();
      handleFitToWindow();
    }
  }, [handleZoomIn, handleZoomOut, handleFitToWindow]);

  return (
    <div 
      className="zoom-slider-container"
      onKeyDown={handleKeyDown}
      tabIndex={0}
      role="slider"
      aria-label="Timeline zoom"
      aria-valuenow={zoomPercentage}
      aria-valuemin={minPercentage}
      aria-valuemax={maxPercentage}
    >
      {/* Zoom out button */}
      <button
        className="zoom-btn zoom-out-btn"
        onClick={handleZoomOut}
        title="Zoom out (Ctrl/Cmd + -)"
        disabled={zoomLevel <= minZoom}
      >
        ÔêÆ
      </button>

      {/* Zoom percentage display */}
      <div className="zoom-percentage-display" title={`Zoom: ${zoomPercentage}%`}>
        {zoomPercentage}%
      </div>

      {/* Zoom slider track */}
      <div className="zoom-slider-track">
        <input
          type="range"
          className="zoom-slider-input"
          min="0"
          max="100"
          step="0.5"
          value={zoomToPosition(sliderValue)}
          onChange={handleSliderChange}
          onMouseDown={() => setIsDragging(true)}
          onMouseUp={() => setIsDragging(false)}
          onMouseLeave={() => setIsDragging(false)}
        />
        
        {/* Track fill */}
        <div 
          className="zoom-slider-track-fill"
          style={{ width: `${zoomToPosition(sliderValue)}%` }}
        />
        
        {/* Track markers */}
        <div className="zoom-slider-markers">
          {[0, 25, 50, 75, 100].map((pos) => (
            <div
              key={pos}
              className="zoom-slider-marker"
              style={{ left: `${pos}%` }}
            />
          ))}
        </div>
      </div>

      {/* Zoom in button */}
      <button
        className="zoom-btn zoom-in-btn"
        onClick={handleZoomIn}
        title="Zoom in (Ctrl/Cmd + +)"
        disabled={zoomLevel >= maxZoom}
      >
        +
      </button>

      {/* Fit to window button */}
      <button
        className="zoom-btn fit-btn"
        onClick={handleFitToWindow}
        title="Fit to window (Ctrl/Cmd + 0)"
      >
        Ôèí
      </button>
    </div>
  );
};

export default ZoomSlider;

/**
 * Playhead Scrubbing Tests
 * 
 * Tests for enhanced playhead scrubbing functionality including:
 * - Draggable playhead with smooth scrubbing
 * - Click-to-seek on timeline ruler
 * - Vertical line indicator across all tracks
 * - Timecode tooltip during scrubbing
 * - Snap-to-grid behavior
 * 
 * Requirements: 1.8, 3.2, 4.5, 4.6
 */

import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, beforeEach, vi } from 'vitest';
import { PlayheadIndicator } from '../PlayheadIndicator';
import { TimeRuler } from '../TimeRuler';

describe('PlayheadIndicator - Enhanced Scrubbing', () => {
  const defaultProps = {
    position: 100,
    height: 500,
    zoomLevel: 10,
    fps: 24,
    isDragging: false,
    isPlaying: false,
    snapToGrid: true,
    onMouseDown: vi.fn(),
    onPositionChange: vi.fn(),
    onDragStart: vi.fn(),
    onDragEnd: vi.fn(),
  };

  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('Draggable Playhead', () => {
    it('should render playhead indicator at correct position', () => {
      const { container } = render(<PlayheadIndicator {...defaultProps} />);
      const playhead = container.querySelector('.playhead-indicator');
      
      expect(playhead).toBeInTheDocument();
      expect(playhead).toHaveStyle({ left: '100px' });
    });

    it('should call onMouseDown when playhead handle is clicked', () => {
      const { container } = render(<PlayheadIndicator {...defaultProps} />);
      const handle = container.querySelector('.playhead-handle');
      
      fireEvent.mouseDown(handle!);
      
      expect(defaultProps.onMouseDown).toHaveBeenCalled();
    });

    it('should call onDragStart when dragging begins', () => {
      const { container } = render(<PlayheadIndicator {...defaultProps} />);
      const handle = container.querySelector('.playhead-handle');
      
      fireEvent.mouseDown(handle!);
      
      expect(defaultProps.onDragStart).toHaveBeenCalled();
    });

    it('should show dragging state when isDragging is true', () => {
      const { container } = render(
        <PlayheadIndicator {...defaultProps} isDragging={true} />
      );
      const playhead = container.querySelector('.playhead-indicator');
      
      expect(playhead).toHaveClass('dragging');
    });

    it('should display scrubbing indicator when dragging', () => {
      const { container } = render(
        <PlayheadIndicator {...defaultProps} isDragging={true} />
      );
      
      expect(container.querySelector('.playhead-scrubbing-indicator')).toBeInTheDocument();
      expect(screen.getByText('SCRUB')).toBeInTheDocument();
    });
  });

  describe('Timecode Tooltip', () => {
    it('should show tooltip on hover', async () => {
      const { container } = render(<PlayheadIndicator {...defaultProps} />);
      const playhead = container.querySelector('.playhead-indicator');
      
      fireEvent.mouseEnter(playhead!);
      
      await waitFor(() => {
        expect(container.querySelector('.playhead-tooltip')).toBeInTheDocument();
      });
    });

    it('should display correct timecode in tooltip', async () => {
      // position 100 / zoomLevel 10 = frame 10
      // frame 10 at 24fps = 00:00:10
      const { container } = render(<PlayheadIndicator {...defaultProps} />);
      const playhead = container.querySelector('.playhead-indicator');
      
      fireEvent.mouseEnter(playhead!);
      
      await waitFor(() => {
        const tooltip = container.querySelector('.playhead-tooltip-timecode');
        expect(tooltip).toHaveTextContent('00:00:10');
      });
    });

    it('should show tooltip during dragging', () => {
      const { container } = render(
        <PlayheadIndicator {...defaultProps} isDragging={true} />
      );
      
      expect(container.querySelector('.playhead-tooltip')).toBeInTheDocument();
    });

    it('should display snap state in tooltip when dragging', () => {
      const { container } = render(
        <PlayheadIndicator {...defaultProps} isDragging={true} snapToGrid={true} />
      );
      
      const hint = container.querySelector('.playhead-tooltip-hint');
      expect(hint).toHaveTextContent('­ƒöÆ Snapped');
    });

    it('should display free state in tooltip when snap is disabled', () => {
      const { container } = render(
        <PlayheadIndicator {...defaultProps} isDragging={true} snapToGrid={false} />
      );
      
      const hint = container.querySelector('.playhead-tooltip-hint');
      expect(hint).toHaveTextContent('­ƒöô Free');
    });

    it('should hide tooltip after mouse leave with delay', async () => {
      const { container } = render(<PlayheadIndicator {...defaultProps} />);
      const playhead = container.querySelector('.playhead-indicator');
      
      fireEvent.mouseEnter(playhead!);
      await waitFor(() => {
        expect(container.querySelector('.playhead-tooltip')).toBeInTheDocument();
      });
      
      fireEvent.mouseLeave(playhead!);
      
      // Tooltip should still be visible immediately after leave
      expect(container.querySelector('.playhead-tooltip')).toBeInTheDocument();
      
      // Wait for delay (200ms)
      await waitFor(() => {
        expect(container.querySelector('.playhead-tooltip')).not.toBeInTheDocument();
      }, { timeout: 300 });
    });
  });

  describe('Vertical Line Indicator', () => {
    it('should render vertical line across all tracks', () => {
      const { container } = render(<PlayheadIndicator {...defaultProps} />);
      const line = container.querySelector('.playhead-line');
      
      expect(line).toBeInTheDocument();
      expect(line).toHaveStyle({ height: '500px' });
    });

    it('should render line glow effect', () => {
      const { container } = render(<PlayheadIndicator {...defaultProps} />);
      
      expect(container.querySelector('.playhead-line-glow')).toBeInTheDocument();
    });

    it('should enhance glow when dragging', () => {
      const { container } = render(
        <PlayheadIndicator {...defaultProps} isDragging={true} />
      );
