/**
 * StoryCore Service Tests
 * Requirements: 7.2
 */

import { describe, it, expect, vi } from 'vitest';
import {
  executeGenerationPipeline,
  parseProgressOutput,
  formatPipelineError,
  exportProjectToStorycore,
  validateProjectForGeneration,
  type ProjectData,
} from '../storycoreService';

describe('StoryCore Service', () => {
  const mockProjectData: ProjectData = {
    name: 'Test Project',
    shots: [
      {
        id: '1',
        prompt: 'A beautiful sunset',
        parameters: { seed: 42, denoising: 0.7 },
        referenceImages: ['/path/to/image.jpg'],
      },
    ],
    settings: {
      resolution: { width: 1920, height: 1080 },
      fps: 30,
      format: 'mp4',
    },
  };

  describe('executeGenerationPipeline', () => {
    it('should execute pipeline and report progress', async () => {
      const progressUpdates: any[] = [];
      
      const result = await executeGenerationPipeline(mockProjectData, (progress) => {
        progressUpdates.push(progress);
      });

      expect(result.success).toBe(true);
      expect(progressUpdates.length).toBeGreaterThan(0);
      expect(progressUpdates[0].stage).toBe('grid');
    });

    it('should complete all pipeline stages', async () => {
      const stages = new Set<string>();
      
      await executeGenerationPipeline(mockProjectData, (progress) => {
        stages.add(progress.stage!);
      });

      expect(stages.has('grid')).toBe(true);
      expect(stages.has('promotion')).toBe(true);
      expect(stages.has('qa')).toBe(true);
      expect(stages.has('export')).toBe(true);
    });
  });

  describe('parseProgressOutput', () => {
    it('should parse grid stage progress', () => {
      const output = '[GRID] Generating master coherence sheet... 25%';
      const progress = parseProgressOutput(output);

      expect(progress).not.toBeNull();
      expect(progress?.stage).toBe('grid');
      expect(progress?.progress).toBe(25);
    });

    it('should parse promotion stage progress', () => {
      const output = '[PROMOTION] Processing panel 3/9... 33%';
      const progress = parseProgressOutput(output);

      expect(progress).not.toBeNull();
      expect(progress?.stage).toBe('promotion');
      expect(progress?.progress).toBe(33);
    });

    it('should parse QA stage progress', () => {
      const output = '[QA] Analyzing quality... 75%';
      const progress = parseProgressOutput(output);

      expect(progress).not.toBeNull();
      expect(progress?.stage).toBe('qa');
      expect(progress?.progress).toBe(75);
    });

    it('should parse export stage progress', () => {
      const output = '[EXPORT] Encoding video... 90%';
      const progress = parseProgressOutput(output);

      expect(progress).not.toBeNull();
      expect(progress?.stage).toBe('export');
      expect(progress?.progress).toBe(90);
    });

    it('should return null for invalid output', () => {
      const output = 'Some random output';
      const progress = parseProgressOutput(output);

      expect(progress).toBeNull();
    });
  });

  describe('formatPipelineError', () => {
    it('should format file not found error', () => {
      const error = 'FileNotFoundError: config.json not found';
      const formatted = formatPipelineError(error);

      expect(formatted).toContain('Required files are missing');
    });

    it('should format permission error', () => {
      const error = 'PermissionError: Access denied';
      const formatted = formatPipelineError(error);

      expect(formatted).toContain('Permission denied');
    });

    it('should format ComfyUI connection error', () => {
      const error = 'ComfyUI connection failed: timeout';
      const formatted = formatPipelineError(error);

      expect(formatted).toContain('Cannot connect to ComfyUI');
    });

    it('should format memory error', () => {
      const error = 'CUDA out of memory';
      const formatted = formatPipelineError(error);

      expect(formatted).toContain('GPU memory exhausted');
    });

    it('should return original error for unknown errors', () => {
      const error = 'Unknown error occurred';
      const formatted = formatPipelineError(error);

      expect(formatted).toContain('Unknown error occurred');
    });
  });

  describe('exportProjectToStorycore', () => {
    it('should export project in Data Contract v1 format', () => {
      const exported = exportProjectToStorycore(mockProjectData);
      const parsed = JSON.parse(exported);

      expect(parsed.schema_version).toBe('1.0');
      expect(parsed.project_name).toBe('Test Project');
      expect(parsed.capabilities).toBeDefined();
      expect(parsed.shots).toHaveLength(1);
      expect(parsed.settings).toBeDefined();
    });

    it('should include all required capabilities', () => {
      const exported = exportProjectToStorycore(mockProjectData);
      const parsed = JSON.parse(exported);

      expect(parsed.capabilities.grid_generation).toBe(true);
      expect(parsed.capabilities.promotion_engine).toBe(true);
      expect(parsed.capabilities.qa_engine).toBe(true);
      expect(parsed.capabilities.autofix_engine).toBe(true);
    });

    it('should convert shots correctly', () => {
      const exported = exportProjectToStorycore(mockProjectData);
      const parsed = JSON.parse(exported);

      expect(parsed.shots[0].id).toBe('1');
      expect(parsed.shots[0].prompt).toBe('A beautiful sunset');
      expect(parsed.shots[0].parameters.seed).toBe(42);
      expect(parsed.shots[0].reference_images).toHaveLength(1);
    });
  });

  describe('validateProjectForGeneration', () => {
    it('should validate valid project', () => {
      const validation = validateProjectForGeneration(mockProjectData);

      expect(validation.valid).toBe(true);
      expect(validation.errors).toHaveLength(0);
    });

    it('should reject project without name', () => {
      const invalidProject = { ...mockProjectData, name: '' };
      const validation = validateProjectForGeneration(invalidProject);

      expect(validation.valid).toBe(false);
      expect(validation.errors).toContain('Project name is required');
    });

    it('should reject project without shots', () => {
      const invalidProject = { ...mockProjectData, shots: [] };
      const validation = validateProjectForGeneration(invalidProject);

      expect(validation.valid).toBe(false);
      expect(validation.errors).toContain('At least one shot is required');
    });

    it('should reject shots without prompts', () => {
      const invalidProject = {
        ...mockProjectData,
        shots: [{ ...mockProjectData.shots[0], prompt: '' }],
      };
      const validation = validateProjectForGeneration(invalidProject);

      expect(validation.valid).toBe(false);
      expect(validation.errors.some(e => e.includes('missing a prompt'))).toBe(true);
    });

    it('should reject invalid resolution', () => {
      const invalidProject = {
        ...mockProjectData,
        settings: { ...mockProjectData.settings, resolution: { width: 0, height: 0 } },
      };
      const validation = validateProjectForGeneration(invalidProject);

      expect(validation.valid).toBe(false);
      expect(validation.errors).toContain('Invalid resolution settings');
    });

    it('should reject invalid FPS', () => {
      const invalidProject = {
        ...mockProjectData,
        settings: { ...mockProjectData.settings, fps: 0 },
      };
      const validation = validateProjectForGeneration(invalidProject);

      expect(validation.valid).toBe(false);
      expect(validation.errors).toContain('Invalid FPS setting');
    });
  });
});

/**
 * Visual Style Service Tests
 * 
 * Tests for visual style application functionality
 * Requirements: 11.1, 11.2, 11.3, 11.5, 11.6
 */

import { describe, it, expect } from 'vitest';
import {
  applyStyleToShot,
  applyStyleToMultipleShots,
  removeStyleFromShot,
  updateStyleIntensity,
  updateStyleParameters,
  haveShotsConsistentStyle,
  getStylePreviewData,
  validateStyleParameters,
  createDefaultStyleParameters,
  mergeStyleParameters,
} from '../visualStyleService';
import type { Asset, Shot, StyleMetadata } from '../../types';

// ============================================================================
// Test Data
// ============================================================================

const mockStyleAsset: Asset = {
  id: 'style-1',
  name: 'Cinematic Blue',
  type: 'visual-style',
  category: 'visual-styles',
  thumbnailUrl: '/assets/styles/cinematic-blue.jpg',
  metadata: {
    description: 'Cool cinematic blue tone',
    styleMetadata: {
      intensity: 80,
      colorPalette: ['#1a2a3a', '#2a4a6a', '#3a6a9a'],
      artisticStyle: 'Cinematic',
    },
  },
  tags: ['cinematic', 'blue', 'cool'],
  source: 'builtin',
  createdAt: new Date('2024-01-01'),
};

const mockShot: Shot = {
  id: 'shot-1',
  name: 'Opening Scene',
  startTime: 0,
  duration: 120,
  layers: [],
  referenceImages: [],
  prompt: 'A beautiful landscape',
  parameters: {
    seed: 12345,
    denoising: 0.75,
    steps: 30,
    guidance: 7.5,
    sampler: 'euler',
    scheduler: 'normal',
  },
  generationStatus: 'pending',
};

// ============================================================================
// Tests
// ============================================================================

describe('visualStyleService', () => {
  describe('applyStyleToShot', () => {
    it('should apply style to shot with default intensity', () => {
      const result = applyStyleToShot(mockShot, mockStyleAsset);

      expect(result.visualStyle).toBeDefined();
      expect(result.visualStyle?.styleId).toBe('style-1');
      expect(result.visualStyle?.styleName).toBe('Cinematic Blue');
      expect(result.visualStyle?.intensity).toBe(100);
      expect(result.modified).toBe(true);
    });

    it('should apply style with custom intensity', () => {
      const result = applyStyleToShot(mockShot, mockStyleAsset, 50);

      expect(result.visualStyle?.intensity).toBe(50);
    });

    it('should include style parameters', () => {
      const result = applyStyleToShot(mockShot, mockStyleAsset);

      expect(result.visualStyle?.parameters).toBeDefined();
      expect(result.visualStyle?.parameters.colorPalette).toEqual([
        '#1a2a3a',
        '#2a4a6a',
        '#3a6a9a',
      ]);
      expect(result.visualStyle?.parameters.artisticStyle).toBe('Cinematic');
    });

    it('should throw error for non-style asset', () => {
      const nonStyleAsset = { ...mockStyleAsset, type: 'character' as const };

      expect(() => applyStyleToShot(mockShot, nonStyleAsset)).toThrow(
        'Asset must be of type visual-style'
      );
    });

    it('should throw error for asset without styleMetadata', () => {
      const assetWithoutMetadata = {
        ...mockStyleAsset,
        metadata: { description: 'Test' },
      };

      expect(() => applyStyleToShot(mockShot, assetWithoutMetadata)).toThrow(
        'Style asset missing styleMetadata'
      );
    });
  });

  describe('applyStyleToMultipleShots', () => {
    it('should apply style to multiple shots', () => {
      const shots = [
        mockShot,
        { ...mockShot, id: 'shot-2', name: 'Scene 2' },
        { ...mockShot, id: 'shot-3', name: 'Scene 3' },
      ];

      const results = applyStyleToMultipleShots(shots, mockStyleAsset, 75);

      expect(results).toHaveLength(3);
      results.forEach((shot) => {
        expect(shot.visualStyle).toBeDefined();
        expect(shot.visualStyle?.styleId).toBe('style-1');
        expect(shot.visualStyle?.intensity).toBe(75);
        expect(shot.modified).toBe(true);
      });
    });

    it('should handle empty array', () => {
      const results = applyStyleToMultipleShots([], mockStyleAsset);

      expect(results).toHaveLength(0);
    });
  });

  describe('removeStyleFromShot', () => {
    it('should remove style from shot', () => {
      const styledShot = applyStyleToShot(mockShot, mockStyleAsset);
      const result = removeStyleFromShot(styledShot);

      expect(result.visualStyle).toBeUndefined();
      expect(result.modified).toBe(true);
    });
  });

  describe('updateStyleIntensity', () => {
    it('should update style intensity', () => {
      const styledShot = applyStyleToShot(mockShot, mockStyleAsset, 100);
      const result = updateStyleIntensity(styledShot, 50);

      expect(result.visualStyle?.intensity).toBe(50);
      expect(result.modified).toBe(true);
    });

    it('should clamp intensity to 0-100 range', () => {
      const styledShot = applyStyleToShot(mockShot, mockStyleAsset);

      const resultLow = updateStyleIntensity(styledShot, -10);
      expect(resultLow.visualStyle?.intensity).toBe(0);

      const resultHigh = updateStyleIntensity(styledShot, 150);
      expect(resultHigh.visualStyle?.intensity).toBe(100);
    });

    it('should throw error if shot has no style', () => {
      expect(() => updateStyleIntensity(mockShot, 50)).toThrow(
        'Shot does not have a visual style applied'
      );
    });
  });

  describe('updateStyleParameters', () => {
    it('should update style parameters', () => {
      const styledShot = applyStyleToShot(mockShot, mockStyleAsset);
      const result = updateStyleParameters(styledShot, {
        saturation: 75,
        contrast: 60,
      });

      expect(result.visualStyle?.parameters.saturation).toBe(75);
      expect(result.visualStyle?.parameters.contrast).toBe(60);
      expect(result.modified).toBe(true);
    });

    it('should throw error if shot has no style', () => {
      expect(() =>
        updateStyleParameters(mockShot, { saturation: 50 })
      ).toThrow('Shot does not have a visual style applied');
    });
  });

  describe('haveShotsConsistentStyle', () => {
    it('should return true for empty array', () => {
      expect(haveShotsConsistentStyle([])).toBe(true);
    });

    it('should return true for single shot', () => {
      expect(haveShotsConsistentStyle([mockShot])).toBe(true);
    });

    it('should return true for shots with same style', () => {
