    it('should return false for mixed styled and unstyled shots', () => {
      const shot1 = applyStyleToShot(mockShot, mockStyleAsset);
      const shot2 = { ...mockShot, id: 'shot-2' };

      expect(haveShotsConsistentStyle([shot1, shot2])).toBe(false);
