/**
 * Export project data to StoryCore-Engine format
 * 
 * @param projectData - Project configuration
 * @returns JSON string for StoryCore-Engine
 */
export function exportProjectToStorycore(projectData: ProjectData): string {
  // Convert to StoryCore-Engine Data Contract v1 format
  const storycoreProject = {
    schema_version: '1.0',
    project_name: projectData.name,
    capabilities: {
      grid_generation: true,
      promotion_engine: true,
      qa_engine: true,
      autofix_engine: true,
    },
    shots: projectData.shots.map((shot, index) => ({
      id: shot.id,
      index,
      prompt: shot.prompt,
      parameters: shot.parameters,
      reference_images: shot.referenceImages,
    })),
    settings: {
      resolution: projectData.settings.resolution,
      fps: projectData.settings.fps,
      format: projectData.settings.format,
    },
  };

  return JSON.stringify(storycoreProject, null, 2);
}

// ============================================================================
// Validation
// ============================================================================

/**
 * Validate project data before generation
 * 
 * @param projectData - Project to validate
 * @returns Validation result with errors if any
 */
export function validateProjectForGeneration(
  projectData: ProjectData
): { valid: boolean; errors: string[] } {
  const errors: string[] = [];

  if (!projectData.name || projectData.name.trim() === '') {
    errors.push('Project name is required');
  }

  if (!projectData.shots || projectData.shots.length === 0) {
    errors.push('At least one shot is required');
  }

  projectData.shots.forEach((shot, index) => {
    if (!shot.prompt || shot.prompt.trim() === '') {
      errors.push(`Shot ${index + 1} is missing a prompt`);
    }
  });

  if (!projectData.settings.resolution.width || !projectData.settings.resolution.height) {
    errors.push('Invalid resolution settings');
  }

  if (!projectData.settings.fps || projectData.settings.fps <= 0) {
    errors.push('Invalid FPS setting');
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

/**
 * Template Service
 * 
 * Handles template application, creation, and management.
 * Requirements: 10.1, 10.2, 10.3, 10.4, 10.5, 10.6
 */

import type { Asset, Shot, TemplateMetadata } from '../types';

// ============================================================================
// Types
// ============================================================================

export interface TemplateShot {
  name: string;
  duration: number; // in frames
  prompt: string;
  parameters: {
    seed?: number;
    denoising?: number;
    steps?: number;
    guidance?: number;
  };
  referenceImages?: string[];
  cameraPreset?: string;
  lightingRig?: string;
  visualStyle?: string;
}

export interface SceneTemplate {
  id: string;
  name: string;
  description: string;
  shots: TemplateShot[];
  metadata: TemplateMetadata;
  tags: string[];
  createdAt: number;
}

export interface NarrativePreset {
  id: string;
  name: string;
  description: string;
  styleParameters: {
    visualStyle?: string;
    colorPalette?: string[];
    mood?: string;
    cinematicStyle?: string;
  };
  shotDefaults: {
    denoising?: number;
    steps?: number;
    guidance?: number;
  };
  tags: string[];
  createdAt: number;
}

// ============================================================================
// Template Application
// ============================================================================

/**
 * Apply a scene template to create multiple shots
 */
export function applySceneTemplate(
  template: SceneTemplate,
  startTime: number,
  fps: number = 24
): Shot[] {
  const shots: Shot[] = [];
  let currentTime = startTime;

  template.shots.forEach((templateShot, index) => {
    const shot: Shot = {
      id: `shot-${Date.now()}-${index}`,
      name: templateShot.name || `Shot ${index + 1}`,
      startTime: currentTime,
      duration: templateShot.duration,
      layers: [
        {
          id: `layer-${Date.now()}-${index}`,
          type: 'media',
          startTime: 0,
          duration: templateShot.duration,
          locked: false,
          hidden: false,
          opacity: 1,
          blendMode: 'normal',
          data: {
            sourceUrl: '',
            trim: { start: 0, end: templateShot.duration },
            transform: {
              position: { x: 0, y: 0 },
              scale: { x: 1, y: 1 },
              rotation: 0,
              anchor: { x: 0.5, y: 0.5 },
            },
          },
        },
      ],
      referenceImages: (templateShot.referenceImages || []).map((url, imgIndex) => ({
        id: `ref-${Date.now()}-${index}-${imgIndex}`,
        url,
        weight: 1,
        source: 'library' as const,
      })),
      prompt: templateShot.prompt,
      parameters: {
        seed: templateShot.parameters.seed || Math.floor(Math.random() * 1000000),
        denoising: templateShot.parameters.denoising || 0.75,
        steps: templateShot.parameters.steps || 20,
        guidance: templateShot.parameters.guidance || 7.5,
        sampler: 'euler_a',
        scheduler: 'normal',
      },
      generationStatus: 'pending',
    };

    shots.push(shot);
    currentTime += templateShot.duration;
  });

  return shots;
}

/**
 * Apply a narrative preset to multiple shots
 */
export function applyNarrativePreset(
  preset: NarrativePreset,
  shots: Shot[]
): Shot[] {
  return shots.map((shot) => ({
    ...shot,
    parameters: {
      ...shot.parameters,
      ...(preset.shotDefaults.denoising !== undefined && { denoising: preset.shotDefaults.denoising }),
      ...(preset.shotDefaults.steps !== undefined && { steps: preset.shotDefaults.steps }),
      ...(preset.shotDefaults.guidance !== undefined && { guidance: preset.shotDefaults.guidance }),
    },
    // Add style information to prompt if available
    prompt: preset.styleParameters.mood
      ? `${shot.prompt}, ${preset.styleParameters.mood} mood`
      : shot.prompt,
  }));
}

/**
 * Extract template metadata from an asset
 */
export function getTemplateMetadata(asset: Asset): TemplateMetadata | null {
  if (asset.type !== 'template' || !asset.metadata.templateMetadata) {
    return null;
  }
  return asset.metadata.templateMetadata;
}

/**
 * Check if an asset is a scene template
 */
export function isSceneTemplate(asset: Asset): boolean {
  return asset.type === 'template' && asset.subcategory === 'scene';
}

/**
 * Check if an asset is a narrative preset
 */
export function isNarrativePreset(asset: Asset): boolean {
  return asset.type === 'template' && asset.subcategory === 'narrative';
}

/**
 * Check if an asset is a shot template
 */
export function isShotTemplate(asset: Asset): boolean {
  return asset.type === 'template' && asset.subcategory === 'shot';
}

// ============================================================================
// Template Creation
// ============================================================================

/**
 * Create a custom template from existing shots
 */
export function createTemplateFromShots(
  shots: Shot[],
  name: string,
  description: string,
  genre: string,
  tags: string[] = []
): SceneTemplate {
  const templateShots: TemplateShot[] = shots.map((shot) => ({
    name: shot.name,
    duration: shot.duration,
    prompt: shot.prompt,
    parameters: {
      seed: shot.parameters.seed,
      denoising: shot.parameters.denoising,
      steps: shot.parameters.steps,
      guidance: shot.parameters.guidance,
    },
    referenceImages: shot.referenceImages.map((ref) => ref.url),
  }));

  const totalDuration = shots.reduce((sum, shot) => sum + shot.duration, 0);

  // Determine complexity based on shot count and parameters
  let complexity: 'simple' | 'moderate' | 'complex' = 'simple';
  if (shots.length > 10) {
    complexity = 'complex';
  } else if (shots.length > 5) {
    complexity = 'moderate';
  }

  return {
    id: `template-${Date.now()}`,
    name,
    description,
    shots: templateShots,
    metadata: {
      shotCount: shots.length,
      totalDuration,
      genre,
      complexity,
    },
    tags,
    createdAt: Date.now(),
  };
}

/**
 * Create a narrative preset from shot parameters
 */
export function createNarrativePreset(
  name: string,
  description: string,
  styleParameters: NarrativePreset['styleParameters'],
  shotDefaults: NarrativePreset['shotDefaults'],
  tags: string[] = []
): NarrativePreset {
  return {
    id: `preset-${Date.now()}`,
    name,
    description,
    styleParameters,
    shotDefaults,
    tags,
    createdAt: Date.now(),
  };
}

