/**
 * useUndoRedo Hook - Provides undo/redo functionality with state restoration
 * 
 * This hook handles the complex logic of restoring state from snapshots
 * when undo/redo operations are performed.
 * 
 * Requirements: 18.1, 18.3, 18.4, 18.6
 */

import { useCallback } from 'react';
import { useAppDispatch, useAppSelector } from '../index';
import { undo as undoAction, redo as redoAction } from '../slices/historySlice';
import { setProject, updateSettings } from '../slices/projectSlice';
import { reorderShots, reorderTracks } from '../slices/timelineSlice';
import { loadAssets } from '../slices/assetsSlice';
import { setPanelLayout } from '../slices/panelsSlice';

/**
 * Hook for undo/redo operations with state restoration
 */
export function useUndoRedo() {
  const dispatch = useAppDispatch();
  const { undoStack, redoStack } = useAppSelector((state) => state.history);
  
  /**
   * Restore state from a snapshot
   */
  const restoreState = useCallback((snapshot: unknown) => {
    if (!snapshot) return;
    
    // Restore project state
    if (snapshot.project) {
      if (snapshot.project.metadata) {
        dispatch(setProject(snapshot.project.metadata));
      }
      if (snapshot.project.settings) {
        dispatch(updateSettings(snapshot.project.settings));
      }
    }
    
    // Restore timeline state
    if (snapshot.timeline) {
      if (snapshot.timeline.shots) {
        dispatch(reorderShots(snapshot.timeline.shots));
      }
      if (snapshot.timeline.tracks) {
        dispatch(reorderTracks(snapshot.timeline.tracks));
      }
    }
    
    // Restore assets state
    if (snapshot.assets?.categories) {
      dispatch(loadAssets(snapshot.assets.categories));
    }
    
    // Restore panels state
    if (snapshot.panels?.layout) {
      dispatch(setPanelLayout(snapshot.panels.layout));
    }
  }, [dispatch]);
  
  /**
   * Perform undo operation
   * Requirement 18.3: Revert last action and update interface state
   */
  const undo = useCallback(() => {
    if (undoStack.length === 0) return;
    
    // Get the snapshot to restore
    const snapshot = undoStack[undoStack.length - 1];
    
    // Dispatch undo action (moves snapshot to redo stack)
    dispatch(undoAction());
    
    // Restore the state
    if (snapshot?.state) {
      restoreState(snapshot.state);
    }
  }, [dispatch, undoStack, restoreState]);
  
  /**
   * Perform redo operation
   * Requirement 18.4: Reapply last undone action
   */
  const redo = useCallback(() => {
    if (redoStack.length === 0) return;
    
    // Get the snapshot to restore
    const snapshot = redoStack[redoStack.length - 1];
    
    // Dispatch redo action (moves snapshot back to undo stack)
    dispatch(redoAction());
    
    // Note: For redo, we don't restore the snapshot state because
    // the action will be re-executed naturally
  }, [dispatch, redoStack]);
  
  /**
   * Check if undo is available
   * Requirement 18.6: Display current undo/redo state
   */
  const canUndo = undoStack.length > 0;
  
  /**
   * Check if redo is available
   * Requirement 18.6: Display current undo/redo state
   */
  const canRedo = redoStack.length > 0;
  
  /**
   * Get description of next undo action
   */
  const undoDescription = undoStack.length > 0
    ? undoStack[undoStack.length - 1].description
    : null;
  
  /**
   * Get description of next redo action
   */
  const redoDescription = redoStack.length > 0
    ? redoStack[redoStack.length - 1].description
    : null;
  
  return {
    undo,
    redo,
    canUndo,
    canRedo,
    undoDescription,
    redoDescription,
  };
}

/**
 * Auto-Save Middleware - Automatically saves project state to localStorage
 * 
 * This middleware monitors state changes and triggers auto-save every 60 seconds
 * when modifications are detected. It uses debouncing to prevent excessive saves.
 * 
 * Requirements: 19.2, 19.3, 19.4, 19.6
 */

import { Middleware } from '@reduxjs/toolkit';
import type { RootState } from '../index';
import { setSaveStatus, markSaved } from '../slices/projectSlice';

// Auto-save interval: 60 seconds (Requirement 19.2)
const AUTO_SAVE_INTERVAL = 60000;

// Debounce delay for save operations: 500ms
const SAVE_DEBOUNCE_DELAY = 500;

// Actions that should trigger auto-save
const SAVE_TRIGGERING_ACTIONS = [
  // Timeline actions
  'timeline/addShot',
  'timeline/updateShot',
  'timeline/deleteShot',
  'timeline/reorderShots',
  'timeline/addTrack',
  'timeline/updateTrack',
  'timeline/deleteTrack',
  'timeline/reorderTracks',
  
  // Asset actions
  'assets/addAsset',
  'assets/updateAsset',
  'assets/deleteAsset',
  
  // Panel actions
  'panels/setPanelLayout',
  
  // Project actions
  'project/updateMetadata',
  'project/updateSettings',
];

/**
 * Save project state to localStorage
 * Requirement 19.6: Save complete project state
 */
function saveToLocalStorage(state: RootState): void {
  try {
    const projectState = {
      version: '1.0',
      timestamp: new Date().toISOString(),
      project: state.project,
      timeline: state.timeline,
      assets: state.assets,
      panels: state.panels,
      tools: state.tools,
    };
    
    localStorage.setItem('sequence-editor-project', JSON.stringify(projectState));
  } catch (error) {
    console.error('Failed to save project to localStorage:', error);
    throw error;
  }
}

/**
 * Load project state from localStorage
 */
export function loadFromLocalStorage(): unknown | null {
  try {
    const saved = localStorage.getItem('sequence-editor-project');
    if (saved) {
      return JSON.parse(saved);
    }
  } catch (error) {
    console.error('Failed to load project from localStorage:', error);
  }
  return null;
}

/**
 * Auto-save middleware that triggers periodic saves
 */
export const autoSaveMiddleware: Middleware<{}, RootState> = (store) => {
  let autoSaveTimer: NodeJS.Timeout | null = null;
  let debounceTimer: NodeJS.Timeout | null = null;
  let hasModifications = false;
  
  /**
   * Perform the actual save operation
   * Requirement 19.3: Update save timestamp on completion
   */
  const performSave = () => {
    const state = store.getState();
    
    // Only save if there are modifications
    if (!hasModifications || state.project.saveStatus.state !== 'modified') {
      return;
    }
    
    // Set saving status
    store.dispatch(setSaveStatus({
      state: 'saving',
    }));
    
    try {
      // Save to localStorage
      saveToLocalStorage(state);
      
      // Mark as saved with timestamp (Requirement 19.3)
      store.dispatch(markSaved());
      
      hasModifications = false;
    } catch (error) {
      // Set error status
      store.dispatch(setSaveStatus({
        state: 'error',
        error: error instanceof Error ? error.message : 'Unknown error',
      }));
    }
  };
  
  /**
   * Debounced save function
   */
  const debouncedSave = () => {
    if (debounceTimer) {
      clearTimeout(debounceTimer);
    }
    
    debounceTimer = setTimeout(() => {
      performSave();
    }, SAVE_DEBOUNCE_DELAY);
  };
  
  /**
   * Start auto-save timer
   * Requirement 19.2: Auto-save every 60 seconds when modifications exist
   */
  const startAutoSaveTimer = () => {
    if (autoSaveTimer) {
      clearInterval(autoSaveTimer);
    }
    
    autoSaveTimer = setInterval(() => {
      if (hasModifications) {
        performSave();
      }
    }, AUTO_SAVE_INTERVAL);
  };
  
  // Start the auto-save timer
  startAutoSaveTimer();
  
  return (next) => (action: unknown) => {
    // Skip save-related actions to prevent loops
    if (
      action.type === 'project/setSaveStatus' ||
      action.type === 'project/markSaved' ||
      action.type === 'project/markModified'
    ) {
      return next(action);
    }
    
    // Execute the action
    const result = next(action);
    
    // Check if this action should trigger save
    if (SAVE_TRIGGERING_ACTIONS.includes(action.type)) {
      hasModifications = true;
      
      // Trigger debounced save
      debouncedSave();
    }
    
    return result;
  };
};

/**
 * Clear auto-save data from localStorage
 */
export function clearAutoSave(): void {
  try {
    localStorage.removeItem('sequence-editor-project');
  } catch (error) {
    console.error('Failed to clear auto-save data:', error);
  }
}

/**
 * History Middleware - Captures undoable actions and manages state snapshots
 * 
 * This middleware intercepts actions that should be undoable and creates
 * state snapshots for the undo/redo system.
 * 
 * Requirements: 18.1, 18.2, 18.3, 18.4, 18.5, 18.6, 18.7
 */

import { Middleware, AnyAction } from '@reduxjs/toolkit';
import { pushHistory } from '../slices/historySlice';
import { markModified } from '../slices/projectSlice';

// Actions that should trigger undo history
const UNDOABLE_ACTIONS = [
  // Timeline actions
  'timeline/addShot',
  'timeline/updateShot',
  'timeline/deleteShot',
  'timeline/reorderShots',
  'timeline/addTrack',
  'timeline/updateTrack',
  'timeline/deleteTrack',
  'timeline/reorderTracks',
  'timeline/addTransition', // Phase 1 - R&D
  'timeline/removeTransition', // Phase 1 - R&D
  'timeline/updateTransition', // Phase 1 - R&D

  // Effects actions (Phase 1 - R&D)
  'effects/addEffect',
  'effects/removeEffect',
  'effects/updateEffect',
  'effects/toggleEffect',

  // Audio actions (Phase 1 - R&D)
  'audio/setTrackVolume',
  'audio/setTrackPan',
  'audio/toggleTrackMute',
  'audio/toggleTrackSolo',

  // Asset actions
  'assets/addAsset',
  'assets/updateAsset',
  'assets/deleteAsset',

  // Panel actions
  'panels/setPanelLayout',

  // Project actions
  'project/updateMetadata',
  'project/updateSettings',
];

// Human-readable descriptions for actions
const ACTION_DESCRIPTIONS: Record<string, string> = {
  'timeline/addShot': 'Add shot',
  'timeline/updateShot': 'Update shot',
  'timeline/deleteShot': 'Delete shot',
  'timeline/reorderShots': 'Reorder shots',
  'timeline/addTrack': 'Add track',
  'timeline/updateTrack': 'Update track',
  'timeline/deleteTrack': 'Delete track',
  'timeline/reorderTracks': 'Reorder tracks',
  'timeline/addTransition': 'Add transition',
  'timeline/removeTransition': 'Remove transition',
  'timeline/updateTransition': 'Update transition',
  'effects/addEffect': 'Add effect',
  'effects/removeEffect': 'Remove effect',
  'effects/updateEffect': 'Update effect',
  'effects/toggleEffect': 'Toggle effect',
  'audio/setTrackVolume': 'Set track volume',
  'audio/setTrackPan': 'Set track pan',
  'audio/toggleTrackMute': 'Toggle mute',
  'audio/toggleTrackSolo': 'Toggle solo',
  'assets/addAsset': 'Add asset',
  'assets/updateAsset': 'Update asset',
  'assets/deleteAsset': 'Delete asset',
  'panels/setPanelLayout': 'Resize panel',
  'project/updateMetadata': 'Update project metadata',
  'project/updateSettings': 'Update project settings',
};

/**
 * Creates a state snapshot for undo/redo
 */
function createSnapshot(state: Record<string, unknown>): Record<string, unknown> {
  return {
    project: state.project,
    timeline: state.timeline,
    assets: state.assets,
    panels: state.panels,
  };
}

/**
 * History middleware that captures undoable actions
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const historyMiddleware: Middleware = (store) => (next) => (action: any) => {
  // Check if this action should be captured in history
  const isUndoable = UNDOABLE_ACTIONS.includes(action?.type);

  // Skip undo/redo actions themselves
  if (action?.type === 'history/undo' || action?.type === 'history/redo') {
    return next(action);
  }

  // Capture state before action
  let previousState: unknown = null;
  if (isUndoable) {
    previousState = createSnapshot(store.getState() as Record<string, unknown>);
  }

  // Execute the action
  const result = next(action);

  // After action, create snapshot and push to history
  if (isUndoable && previousState) {
    const description = ACTION_DESCRIPTIONS[action.type] || action.type;

    store.dispatch(pushHistory({
      timestamp: Date.now(),
      action: action.type,
      state: previousState,
      description,
    }));

    // Mark project as modified
    store.dispatch(markModified());
  }

  return result;
};

/**
 * Timeline Slice - Redux state management for timeline, shots, tracks, markers, and regions
 * Requirements: 1.1, 1.3, 1.8, 19.1
 */

import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import type { TimelineState, Shot, Track, ReferenceImage, TimelineMarker, TimelineRegion, Layer, StyleApplication, StyleParameters, Annotation, AnnotationReply } from '../../types';

// Default track configuration
const DEFAULT_TRACKS: Track[] = [
  { id: 'media', type: 'media', height: 60, locked: false, hidden: false, color: '#4A90E2', icon: 'film' },
  { id: 'audio', type: 'audio', height: 40, locked: false, hidden: false, color: '#50C878', icon: 'volume' },
  { id: 'effects', type: 'effects', height: 40, locked: false, hidden: false, color: '#9B59B6', icon: 'magic' },
  { id: 'transitions', type: 'transitions', height: 30, locked: false, hidden: false, color: '#E67E22', icon: 'shuffle' },
  { id: 'text', type: 'text', height: 40, locked: false, hidden: false, color: '#F39C12', icon: 'text' },
  { id: 'keyframes', type: 'keyframes', height: 30, locked: false, hidden: false, color: '#E74C3C', icon: 'key' },
];

const initialState: TimelineState = {
  projectId: '',
  shots: [],
  tracks: DEFAULT_TRACKS,
  playheadPosition: 0,
  zoomLevel: 1, // 1 pixel per frame
  selectedElements: [],
  duration: 0,
  markers: [],
  regions: [],
  annotations: [],
  selectedMarkers: [],
  selectedRegions: [],
};

const timelineSlice = createSlice({
  name: 'timeline',
  initialState,
  reducers: {
    addShot: (state, action: PayloadAction<Shot>) => {
      state.shots.push(action.payload);
      // Update total duration
      const shotEnd = action.payload.startTime + action.payload.duration;
      if (shotEnd > state.duration) {
        state.duration = shotEnd;
      }
    },
    updateShot: (state, action: PayloadAction<{ id: string; updates: Partial<Shot> }>) => {
      const { id, updates } = action.payload;
      const index = state.shots.findIndex((shot) => shot.id === id);
      if (index !== -1) {
        state.shots[index] = { ...state.shots[index], ...updates };
        // Recalculate duration if needed
        const maxEnd = Math.max(
          ...state.shots.map((shot) => shot.startTime + shot.duration)
        );
        state.duration = maxEnd;
      }
    },
    deleteShot: (state, action: PayloadAction<string>) => {
      state.shots = state.shots.filter((shot) => shot.id !== action.payload);
      state.selectedElements = state.selectedElements.filter((id) => id !== action.payload);
      // Recalculate duration
      const maxEnd = state.shots.length > 0
        ? Math.max(...state.shots.map((shot) => shot.startTime + shot.duration))
        : 0;
      state.duration = maxEnd;
    },
    reorderShots: (state, action: PayloadAction<Shot[]>) => {
      state.shots = action.payload;
    },
    addTrack: (state, action: PayloadAction<Track>) => {
      state.tracks.push(action.payload);
    },
    updateTrack: (state, action: PayloadAction<{ id: string; updates: Partial<Track> }>) => {
      const { id, updates } = action.payload;
      const index = state.tracks.findIndex((track) => track.id === id);
      if (index !== -1) {
        state.tracks[index] = { ...state.tracks[index], ...updates };
      }
    },
    deleteTrack: (state, action: PayloadAction<string>) => {
      state.tracks = state.tracks.filter((track) => track.id !== action.payload);
    },
    reorderTracks: (state, action: PayloadAction<Track[]>) => {
      state.tracks = action.payload;
    },
    setPlayheadPosition: (state, action: PayloadAction<number>) => {
      state.playheadPosition = action.payload;
    },
    setZoomLevel: (state, action: PayloadAction<number>) => {
      state.zoomLevel = action.payload;
    },
    selectElement: (state, action: PayloadAction<string>) => {
      if (!state.selectedElements.includes(action.payload)) {
        state.selectedElements.push(action.payload);
      }
    },
    deselectElement: (state, action: PayloadAction<string>) => {
      state.selectedElements = state.selectedElements.filter((id) => id !== action.payload);
    },
    setSelectedElements: (state, action: PayloadAction<string[]>) => {
      state.selectedElements = action.payload;
    },
    clearSelection: (state) => {
      state.selectedElements = [];
    },
    toggleTrackLock: (state, action: PayloadAction<string>) => {
      const track = state.tracks.find((t) => t.id === action.payload);
      if (track) {
        track.locked = !track.locked;
      }
    },
    toggleTrackHidden: (state, action: PayloadAction<string>) => {
      const track = state.tracks.find((t) => t.id === action.payload);
      if (track) {
        track.hidden = !track.hidden;
      }
    },
    addReferenceImage: (state, action: PayloadAction<{ shotId: string; image: ReferenceImage }>) => {
      const { shotId, image } = action.payload;
      const shot = state.shots.find((s) => s.id === shotId);
      if (shot) {
        shot.referenceImages.push(image);
      }
    },
    removeReferenceImage: (state, action: PayloadAction<{ shotId: string; imageIndex: number }>) => {
      const { shotId, imageIndex } = action.payload;
      const shot = state.shots.find((s) => s.id === shotId);
      if (shot && shot.referenceImages[imageIndex]) {
        shot.referenceImages.splice(imageIndex, 1);
      }
    },
    // Marker actions
    addMarker: (state, action: PayloadAction<TimelineMarker>) => {
      state.markers.push(action.payload);
    },
    updateMarker: (state, action: PayloadAction<{ id: string; updates: Partial<TimelineMarker> }>) => {
      const { id, updates } = action.payload;
      const index = state.markers.findIndex((marker) => marker.id === id);
      if (index !== -1) {
        state.markers[index] = { ...state.markers[index], ...updates, updatedAt: Date.now() };
      }
    },
    deleteMarker: (state, action: PayloadAction<string>) => {
      state.markers = state.markers.filter((marker) => marker.id !== action.payload);
      state.selectedMarkers = state.selectedMarkers.filter((id) => id !== action.payload);
    },
    selectMarker: (state, action: PayloadAction<string>) => {
      if (!state.selectedMarkers.includes(action.payload)) {
        state.selectedMarkers.push(action.payload);
      }
    },
    deselectMarker: (state, action: PayloadAction<string>) => {
      state.selectedMarkers = state.selectedMarkers.filter((id) => id !== action.payload);
    },
    setSelectedMarkers: (state, action: PayloadAction<string[]>) => {
      state.selectedMarkers = action.payload;
    },
    clearMarkerSelection: (state) => {
      state.selectedMarkers = [];
    },
    // Region actions
    addRegion: (state, action: PayloadAction<TimelineRegion>) => {
      state.regions.push(action.payload);
    },
    updateRegion: (state, action: PayloadAction<{ id: string; updates: Partial<TimelineRegion> }>) => {
      const { id, updates } = action.payload;
      const index = state.regions.findIndex((region) => region.id === id);
      if (index !== -1) {
        state.regions[index] = { ...state.regions[index], ...updates, updatedAt: Date.now() };
      }
    },
    deleteRegion: (state, action: PayloadAction<string>) => {
      state.regions = state.regions.filter((region) => region.id !== action.payload);
      state.selectedRegions = state.selectedRegions.filter((id) => id !== action.payload);
    },
    selectRegion: (state, action: PayloadAction<string>) => {
      if (!state.selectedRegions.includes(action.payload)) {
        state.selectedRegions.push(action.payload);
      }
    },
    deselectRegion: (state, action: PayloadAction<string>) => {
      state.selectedRegions = state.selectedRegions.filter((id) => id !== action.payload);
    },
    setSelectedRegions: (state, action: PayloadAction<string[]>) => {
      state.selectedRegions = action.payload;
    },
    clearRegionSelection: (state) => {
      state.selectedRegions = [];
    },
    // Annotation actions
    addAnnotation: (state, action: PayloadAction<Annotation>) => {
      state.annotations.push(action.payload);
    },
    updateAnnotation: (state, action: PayloadAction<{ id: string; updates: Partial<Annotation> }>) => {
      const { id, updates } = action.payload;
      const index = state.annotations.findIndex((ann) => ann.id === id);
      if (index !== -1) {
        state.annotations[index] = { ...state.annotations[index], ...updates, updatedAt: Date.now() };
      }
    },
    deleteAnnotation: (state, action: PayloadAction<string>) => {
      state.annotations = state.annotations.filter((ann) => ann.id !== action.payload);
    },
    addAnnotationReply: (state, action: PayloadAction<{ annotationId: string; reply: AnnotationReply }>) => {
      const { annotationId, reply } = action.payload;
      const index = state.annotations.findIndex((ann) => ann.id === annotationId);
      if (index !== -1) {
        if (!state.annotations[index].replies) {
          state.annotations[index].replies = [];
        }
        state.annotations[index].replies!.push(reply);
        state.annotations[index].updatedAt = Date.now();
      }
    },
    // Layer actions
    addLayer: (state, action: PayloadAction<{ shotId: string; layer: Layer }>) => {
      const { shotId, layer } = action.payload;
      const shot = state.shots.find((s) => s.id === shotId);
      if (shot) {
        shot.layers.push(layer);
      }
    },
    updateLayer: (state, action: PayloadAction<{ shotId: string; layerId: string; updates: Partial<Layer> }>) => {
      const { shotId, layerId, updates } = action.payload;
      const shot = state.shots.find((s) => s.id === shotId);
      if (shot) {
        const layerIndex = shot.layers.findIndex((l) => l.id === layerId);
        if (layerIndex !== -1) {
          shot.layers[layerIndex] = { ...shot.layers[layerIndex], ...updates };
        }
      }
    },
    splitShot: (state, action: PayloadAction<{ shotId: string; leftShot: Shot; rightShot: Shot }>) => {
      const { shotId, leftShot, rightShot } = action.payload;
      const index = state.shots.findIndex((s) => s.id === shotId);
      if (index !== -1) {
        state.shots.splice(index, 1, leftShot, rightShot);
      }
    },
    deleteLayer: (state, action: PayloadAction<{ shotId: string; layerId: string }>) => {
      const { shotId, layerId } = action.payload;
      const shot = state.shots.find((s) => s.id === shotId);
      if (shot) {
        shot.layers = shot.layers.filter((l) => l.id !== layerId);
        // Remove from selection if selected
        state.selectedElements = state.selectedElements.filter((id) => id !== layerId);
      }
    },
    reorderLayers: (state, action: PayloadAction<{ shotId: string; layers: Layer[] }>) => {
      const { shotId, layers } = action.payload;
      const shot = state.shots.find((s) => s.id === shotId);
      if (shot) {
        shot.layers = layers;
      }
    },
    toggleLayerLock: (state, action: PayloadAction<{ shotId: string; layerId: string }>) => {
      const { shotId, layerId } = action.payload;
      const shot = state.shots.find((s) => s.id === shotId);
      if (shot) {
        const layer = shot.layers.find((l) => l.id === layerId);
        if (layer) {
          layer.locked = !layer.locked;
        }
      }
    },
    toggleLayerHidden: (state, action: PayloadAction<{ shotId: string; layerId: string }>) => {
      const { shotId, layerId } = action.payload;
      const shot = state.shots.find((s) => s.id === shotId);
      if (shot) {
        const layer = shot.layers.find((l) => l.id === layerId);
        if (layer) {
          layer.hidden = !layer.hidden;
        }
      }
    },
    setLayerOpacity: (state, action: PayloadAction<{ shotId: string; layerId: string; opacity: number }>) => {
      const { shotId, layerId, opacity } = action.payload;
      const shot = state.shots.find((s) => s.id === shotId);
      if (shot) {
        const layer = shot.layers.find((l) => l.id === layerId);
        if (layer) {
          layer.opacity = Math.max(0, Math.min(1, opacity)); // Clamp to 0-1
        }
      }
    },
    setLayerBlendMode: (state, action: PayloadAction<{ shotId: string; layerId: string; blendMode: string }>) => {
      const { shotId, layerId, blendMode } = action.payload;
      const shot = state.shots.find((s) => s.id === shotId);
      if (shot) {
        const layer = shot.layers.find((l) => l.id === layerId);
        if (layer) {
          layer.blendMode = blendMode;
        }
      }
    },
    // Visual style actions
    applyStyleToShot: (state, action: PayloadAction<{ shotId: string; styleApplication: StyleApplication }>) => {
      const { shotId, styleApplication } = action.payload;
      const shot = state.shots.find((s) => s.id === shotId);
      if (shot) {
        shot.visualStyle = styleApplication;
        shot.modified = true;
      }
    },
    applyStyleToMultipleShots: (state, action: PayloadAction<{ shotIds: string[]; styleApplication: StyleApplication }>) => {
      const { shotIds, styleApplication } = action.payload;
      shotIds.forEach((shotId) => {
        const shot = state.shots.find((s) => s.id === shotId);
        if (shot) {
          shot.visualStyle = { ...styleApplication, shotId } as any;
          shot.modified = true;
        }
      });
    },
    removeStyleFromShot: (state, action: PayloadAction<string>) => {
      const shot = state.shots.find((s) => s.id === action.payload);
      if (shot) {
        shot.visualStyle = undefined;
        shot.modified = true;
      }
    },
    updateStyleIntensity: (state, action: PayloadAction<{ shotId: string; intensity: number }>) => {
      const { shotId, intensity } = action.payload;
      const shot = state.shots.find((s) => s.id === shotId);
      if (shot && shot.visualStyle) {
        shot.visualStyle.intensity = Math.max(0, Math.min(100, intensity));
        shot.modified = true;
      }
    },
    updateStyleParameters: (state, action: PayloadAction<{ shotId: string; parameters: Partial<StyleParameters> }>) => {
      const { shotId, parameters } = action.payload;
      const shot = state.shots.find((s) => s.id === shotId);
      if (shot && shot.visualStyle) {
        shot.visualStyle.parameters = { ...shot.visualStyle.parameters, ...parameters } as any;
        shot.modified = true;
      }
    },
    // Transition actions (Phase 1 - R&D)
    addTransition: (state, action: PayloadAction<{ clipId: string; transitionType: string; position: 'in' | 'out'; duration: number }>) => {
      const { clipId, transitionType, position, duration } = action.payload;
      const shot = state.shots.find((s) => s.id === clipId);
      if (shot) {
        if (!shot.transitions) {
          shot.transitions = {};
        }
        shot.transitions[position] = {
          type: transitionType,
          duration,
          appliedAt: Date.now(),
        };
        shot.modified = true;
      }
    },
    removeTransition: (state, action: PayloadAction<{ clipId: string; position: 'in' | 'out' }>) => {
      const { clipId, position } = action.payload;
      const shot = state.shots.find((s) => s.id === clipId);
      if (shot && shot.transitions) {
        delete shot.transitions[position];
        shot.modified = true;
      }
    },
    updateTransition: (state, action: PayloadAction<{ clipId: string; position: 'in' | 'out'; updates: { transitionType?: string; duration?: number } }>) => {
      const { clipId, position, updates } = action.payload;
      const shot = state.shots.find((s) => s.id === clipId);
      if (shot && shot.transitions && shot.transitions[position]) {
        Object.assign(shot.transitions[position]!, {
          ...updates,
          appliedAt: Date.now()
        });
        shot.modified = true;
      }
    },
  },
});

