/**
 * Convert dB to linear gain
 */
export function dbToLinear(db: number): number {
  return Math.pow(10, db / 20);
}

/**
 * Convert linear gain to dB
 */
export function linearToDb(linear: number): number {
  return 20 * Math.log10(linear);
}

/**
 * Calculate RMS (Root Mean Square) of audio samples
 */
export function calculateRMS(samples: number[]): number {
  const sumSquares = samples.reduce((sum, sample) => sum + sample * sample, 0);
  return Math.sqrt(sumSquares / samples.length);
}

/**
 * Calculate peak amplitude of audio samples
 */
export function calculatePeak(samples: number[]): number {
  return Math.max(...samples.map(Math.abs));
}

/**
 * Get volume meter color based on dB level
 */
export function getVolumeMeterColor(db: number): string {
  if (db > -3) {
    return '#FF0000'; // Red for clipping
  } else if (db > -6) {
    return '#FFA500'; // Orange for high
  } else if (db > -12) {
    return '#FFFF00'; // Yellow for medium-high
  } else if (db > -18) {
    return '#00FF00'; // Green for good
  } else {
    return '#008000'; // Dark green for low
  }
}

/**
 * Browser Compatibility Utilities
 * 
 * Provides utilities for detecting browser capabilities and
 * implementing cross-browser compatible features.
 * 
 * Requirements: 22.4
 */

// ============================================================================
// Browser Detection
// ============================================================================

export interface BrowserInfo {
  name: string;
  version: string;
  isChrome: boolean;
  isFirefox: boolean;
  isSafari: boolean;
  isEdge: boolean;
  isIE: boolean;
  isOpera: boolean;
  isMobile: boolean;
  isIOS: boolean;
  isAndroid: boolean;
}

/**
 * Detect browser information
 */
export function detectBrowser(): BrowserInfo {
  const ua = navigator.userAgent;
  
  const isChrome = /Chrome/.test(ua) && /Google Inc/.test(navigator.vendor);
  const isFirefox = /Firefox/.test(ua);
  const isSafari = /Safari/.test(ua) && /Apple Computer/.test(navigator.vendor);
  const isEdge = /Edg/.test(ua);
  const isIE = /MSIE|Trident/.test(ua);
  const isOpera = /OPR/.test(ua) || /Opera/.test(ua);
  
  const isIOS = /iPad|iPhone|iPod/.test(ua);
  const isAndroid = /Android/.test(ua);
  const isMobile = isIOS || isAndroid || /Mobile/.test(ua);
  
  let name = 'Unknown';
  let version = 'Unknown';
  
  if (isChrome) {
    name = 'Chrome';
    const match = ua.match(/Chrome\/(\d+)/);
    version = match ? match[1] : 'Unknown';
  } else if (isFirefox) {
    name = 'Firefox';
    const match = ua.match(/Firefox\/(\d+)/);
    version = match ? match[1] : 'Unknown';
  } else if (isSafari) {
    name = 'Safari';
    const match = ua.match(/Version\/(\d+)/);
    version = match ? match[1] : 'Unknown';
  } else if (isEdge) {
    name = 'Edge';
    const match = ua.match(/Edg\/(\d+)/);
    version = match ? match[1] : 'Unknown';
  } else if (isIE) {
    name = 'Internet Explorer';
    const match = ua.match(/(?:MSIE |rv:)(\d+)/);
    version = match ? match[1] : 'Unknown';
  } else if (isOpera) {
    name = 'Opera';
    const match = ua.match(/(?:OPR|Opera)\/(\d+)/);
    version = match ? match[1] : 'Unknown';
  }
  
  return {
    name,
    version,
    isChrome,
    isFirefox,
    isSafari,
    isEdge,
    isIE,
    isOpera,
    isMobile,
    isIOS,
    isAndroid,
  };
}

// ============================================================================
// Feature Detection
// ============================================================================

/**
 * Check if browser supports a specific feature
 */
export const features = {
  // CSS Features
  cssGrid: () => CSS.supports('display', 'grid'),
  cssFlexbox: () => CSS.supports('display', 'flex'),
  cssVariables: () => CSS.supports('--test', '0'),
  cssBackdropFilter: () => CSS.supports('backdrop-filter', 'blur(10px)'),
  
  // JavaScript Features
  intersectionObserver: () => 'IntersectionObserver' in window,
  resizeObserver: () => 'ResizeObserver' in window,
  mutationObserver: () => 'MutationObserver' in window,
  requestIdleCallback: () => 'requestIdleCallback' in window,
  requestAnimationFrame: () => 'requestAnimationFrame' in window,
  
  // Web APIs
  webGL: () => {
    try {
      const canvas = document.createElement('canvas');
      return !!(
        canvas.getContext('webgl') ||
        canvas.getContext('experimental-webgl')
      );
    } catch (e) {
      return false;
    }
  },
  webGL2: () => {
    try {
      const canvas = document.createElement('canvas');
      return !!canvas.getContext('webgl2');
    } catch (e) {
      return false;
    }
  },
  webWorkers: () => 'Worker' in window,
  serviceWorker: () => 'serviceWorker' in navigator,
  indexedDB: () => 'indexedDB' in window,
  localStorage: () => {
    try {
      const test = '__test__';
      localStorage.setItem(test, test);
      localStorage.removeItem(test);
      return true;
    } catch (e) {
      return false;
    }
  },
  
  // Media Features
  mediaRecorder: () => 'MediaRecorder' in window,
  getUserMedia: () => !!(navigator.mediaDevices && navigator.mediaDevices.getUserMedia),
  webAudio: () => 'AudioContext' in window || 'webkitAudioContext' in window,
  
  // Drag and Drop
  dragAndDrop: () => 'draggable' in document.createElement('div'),
  
  // Touch Events
  touchEvents: () => 'ontouchstart' in window || navigator.maxTouchPoints > 0,
  
  // Pointer Events
  pointerEvents: () => 'PointerEvent' in window,
};

/**
 * Get all feature support information
 */
export function getFeatureSupport(): Record<string, boolean> {
  const support: Record<string, boolean> = {};
  
  for (const [key, check] of Object.entries(features)) {
    try {
      support[key] = check();
    } catch (e) {
      support[key] = false;
    }
  }
  
  return support;
}

