/**
 * Get all tracks in a group
 */
export function getTracksInGroup(
  groupId: string,
  groups: TrackGroup[],
  tracks: Track[]
): Track[] {
  const group = groups.find((g) => g.id === groupId);
  if (!group) return [];
  
  return tracks.filter((track) => group.trackIds.includes(track.id));
}

/**
 * Get track by ID
 */
export function getTrackById(
  trackId: string,
  tracks: Track[]
): Track | null {
  return tracks.find((track) => track.id === trackId) || null;
}

/**
 * Check if track is in any group
 */
export function isTrackInGroup(
  trackId: string,
  groups: TrackGroup[]
): boolean {
  return groups.some((group) => group.trackIds.includes(trackId));
}

/**
 * Get group containing track
 */
export function getGroupContainingTrack(
  trackId: string,
  groups: TrackGroup[]
): TrackGroup | null {
  return groups.find((group) => group.trackIds.includes(trackId)) || null;
}

/**
 * Lock/unlock all tracks in group
 */
export function toggleGroupLock(
  groupId: string,
  groups: TrackGroup[],
  tracks: Track[]
): { groups: TrackGroup[]; tracks: Track[] } {
  const group = groups.find((g) => g.id === groupId);
  if (!group) return { groups, tracks };
  
  const newLockState = !group.locked;
  
  const updatedGroups = groups.map((g) => {
    if (g.id === groupId) {
      return { ...g, locked: newLockState };
    }
    return g;
  });
  
  const updatedTracks = tracks.map((track) => {
    if (group.trackIds.includes(track.id)) {
      return { ...track, locked: newLockState };
    }
    return track;
  });
  
  return { groups: updatedGroups, tracks: updatedTracks };
}

/**
 * Hide/show all tracks in group
 */
export function toggleGroupVisibility(
  groupId: string,
  groups: TrackGroup[],
  tracks: Track[]
): { groups: TrackGroup[]; tracks: Track[] } {
  const group = groups.find((g) => g.id === groupId);
  if (!group) return { groups, tracks };
  
  const newHiddenState = !group.hidden;
  
  const updatedGroups = groups.map((g) => {
    if (g.id === groupId) {
      return { ...g, hidden: newHiddenState };
    }
    return g;
  });
  
  const updatedTracks = tracks.map((track) => {
    if (group.trackIds.includes(track.id)) {
      return { ...track, hidden: newHiddenState };
    }
    return track;
  });
  
  return { groups: updatedGroups, tracks: updatedTracks };
}

/**
 * Video Effects Utility
 * 
 * Handles video effects and processing tools including speed control,
 * stabilization, color grading, blend modes, and resolution management.
 * 
 * Requirements: 9.1, 11.1, 9.2, 3.7, 3.6
 */

import type { Shot, Layer, EffectsLayerData } from '../types';

// ============================================================================
// Types
// ============================================================================

export interface SpeedControlData {
  speed: number; // 0.1 to 10.0
  timeRemapping?: TimeRemappingCurve;
}

export interface TimeRemappingCurve {
  points: TimeRemappingPoint[];
  interpolation: 'linear' | 'ease' | 'ease-in' | 'ease-out' | 'ease-in-out';
}

export interface TimeRemappingPoint {
  inputTime: number; // Frame number in original
  outputTime: number; // Frame number in output
}

export interface StabilizationData {
  enabled: boolean;
  strength: number; // 0 to 100
  smoothness: number; // 0 to 100
  cropRatio: number; // 0 to 1 (percentage of frame to crop)
  method: 'automatic' | 'manual';
}

export interface ColorGradingData {
  lut?: string; // Path to LUT file
  contrast: number; // -100 to 100
  saturation: number; // -100 to 100
  brightness: number; // -100 to 100
  colorWheels: {
    shadows: ColorWheel;
    midtones: ColorWheel;
    highlights: ColorWheel;
  };
  curves?: ColorCurves;
  preset?: string;
}

export interface ColorWheel {
  hue: number; // 0 to 360
  saturation: number; // 0 to 100
  luminance: number; // -100 to 100
}

export interface ColorCurves {
  master: CurvePoints[];
  red: CurvePoints[];
  green: CurvePoints[];
  blue: CurvePoints[];
}

export interface CurvePoints {
  x: number; // 0 to 1
  y: number; // 0 to 1
}

export interface BlendModeData {
  mode: BlendMode;
  opacity: number; // 0 to 1
}

export type BlendMode =
  | 'normal'
  | 'multiply'
  | 'screen'
  | 'overlay'
  | 'darken'
  | 'lighten'
  | 'color-dodge'
  | 'color-burn'
  | 'hard-light'
  | 'soft-light'
  | 'difference'
  | 'exclusion'
  | 'hue'
  | 'saturation'
  | 'color'
  | 'luminosity';

export interface MaskData {
  type: 'rectangle' | 'ellipse' | 'polygon' | 'bezier';
  points: { x: number; y: number }[];
  feather: number; // 0 to 100
  invert: boolean;
  opacity: number; // 0 to 1
}

export interface ChromaKeyData {
  enabled: boolean;
  keyColor: string; // Hex color
  tolerance: number; // 0 to 100
  softness: number; // 0 to 100
  spillSuppression: number; // 0 to 100
}

export interface ResolutionData {
  width: number;
  height: number;
  aspectRatio: '16:9' | '9:16' | '1:1' | '4:3' | '21:9' | 'custom';
  scaleMode: 'fit' | 'fill' | 'stretch' | 'crop';
  safeAreas: {
    action: boolean; // 90% safe area
    title: boolean; // 80% safe area
  };
}

export interface PreviewQualityData {
  quality: 'high' | 'medium' | 'low' | 'proxy';
  adaptiveQuality: boolean;
  proxyScale: number; // 0.25, 0.5, 0.75
}

// ============================================================================
// Speed Control (10A.1)
// ============================================================================

/**
 * Apply speed adjustment to shot
 */
export function applySpeedControl(
  shotId: string,
  speed: number,
  shots: Shot[]
): { shotId: string; newDuration: number; effectLayer: Layer } | null {
  const shot = shots.find((s) => s.id === shotId);
  if (!shot) return null;
  
  // Clamp speed to valid range
  const clampedSpeed = Math.max(0.1, Math.min(10.0, speed));
  
  // Calculate new duration based on speed
  const newDuration = Math.round(shot.duration / clampedSpeed);
  
  // Create speed effect layer
  const effectLayer: Layer = {
    id: `speed-${Date.now()}`,
    type: 'effects',
    startTime: 0,
    duration: newDuration,
    locked: false,
    hidden: false,
    opacity: 1,
    blendMode: 'normal',
    data: {
      effectType: 'speed',
      parameters: {
        speed: clampedSpeed,
      } as SpeedControlData,
    } as EffectsLayerData,
  };
  
  return {
    shotId,
    newDuration,
    effectLayer,
  };
}

/**
 * Create time remapping curve for variable speed
 */
export function createTimeRemappingCurve(
  points: TimeRemappingPoint[],
  interpolation: TimeRemappingCurve['interpolation'] = 'ease-in-out'
): TimeRemappingCurve {
  // Sort points by input time
  const sortedPoints = [...points].sort((a, b) => a.inputTime - b.inputTime);
  
  return {
    points: sortedPoints,
    interpolation,
  };
}

/**
 * Apply time remapping to shot
 */
export function applyTimeRemapping(
  shotId: string,
  curve: TimeRemappingCurve,
  shots: Shot[]
): { shotId: string; effectLayer: Layer } | null {
  const shot = shots.find((s) => s.id === shotId);
  if (!shot) return null;
  
  const effectLayer: Layer = {
    id: `time-remap-${Date.now()}`,
    type: 'effects',
    startTime: 0,
    duration: shot.duration,
    locked: false,
    hidden: false,
    opacity: 1,
    blendMode: 'normal',
    data: {
      effectType: 'time-remapping',
      parameters: {
        timeRemapping: curve,
      } as SpeedControlData,
    } as EffectsLayerData,
  };
  
  return {
    shotId,
    effectLayer,
  };
}

