/**
 * Apply blend mode to layer
 */
export function applyBlendMode(
  layerId: string,
  blendMode: BlendMode,
  opacity: number,
  shot: Shot
): Layer | null {
  const layer = shot.layers.find((l) => l.id === layerId);
  if (!layer) return null;
  
  return {
    ...layer,
    blendMode,
    opacity: Math.max(0, Math.min(1, opacity)),
  };
}

