): { shotId: string; layerId: string; mask: MaskData } | null {
  const shot = shots.find((s) => s.id === shotId);
  if (!shot) return null;
  
  const layer = shot.layers.find((l) => l.id === layerId);
  if (!layer) return null;
  
  return {
    shotId,
    layerId,
    mask: maskData,
  };
}

