/**
 * SyncManager - Bidirectional synchronization manager
 *
 * Synchronizes data between Zustand store and JSON files
 * with automatic conflict detection and resolution
 */

import { persistenceService } from './PersistenceService';
import { logger } from '@/utils/logger';
import type { World } from '@/types/world';

export interface SyncConflict {
  entityType: string;
  entityId: string;
  storeVersion: unknown;
  fileVersion: unknown;
  conflictType: 'modified' | 'deleted' | 'created';
  resolution: 'store-wins' | 'file-wins' | 'merge' | 'manual';
  timestamp: Date;
}

export interface SyncResult {
  synced: number;
  conflicts: SyncConflict[];
  errors: string[];
  duration: number;
}

// Type guard function to check if value is a plain object
function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Gestionnaire de synchronisation bidirectionnelle
 */
export class SyncManager {
  private static instance: SyncManager;
  private syncInProgress = false;
  private lastSyncTime: Date | null = null;
  private conflicts: SyncConflict[] = [];

  private constructor() {
    // D├®marrer la synchronisation automatique
    this.startAutoSync();
  }

  static getInstance(): SyncManager {
    if (!SyncManager.instance) {
      SyncManager.instance = new SyncManager();
    }
    return SyncManager.instance;
  }

  /**
   * Synchronisation compl├¿te bidirectionnelle
   */
  async fullSync(projectPath?: string): Promise<SyncResult> {
    if (this.syncInProgress) {
      logger.warn('[SyncManager] Sync already in progress, skipping...');
      return { synced: 0, conflicts: [], errors: ['Sync already in progress'], duration: 0 };
    }

    const startTime = Date.now();
    this.syncInProgress = true;

    try {

      const results = await Promise.allSettled([
        this.syncWorlds(projectPath),
        this.syncCharacters(projectPath),
        this.syncSequences(projectPath),
        this.syncScenes(projectPath),
        this.syncShots(projectPath),
      ]);

      const synced = results.reduce((acc, result) => {
        if (result.status === 'fulfilled') {
          return acc + result.value.synced;
        }
        return acc;
      }, 0);

      const allConflicts = results.flatMap(result =>
        result.status === 'fulfilled' ? result.value.conflicts : []
      );

      const errors = results.flatMap(result =>
        result.status === 'rejected' ? [result.reason?.message || 'Unknown error'] : []
      );

      const duration = Date.now() - startTime;


      this.lastSyncTime = new Date();
      this.conflicts.push(...allConflicts);

      return {
        synced,
        conflicts: allConflicts,
        errors,
        duration
      };

    } finally {
      this.syncInProgress = false;
    }
  }

  /**
   * Synchronisation des mondes
   */
  private async syncWorlds(projectPath?: string): Promise<{ synced: number, conflicts: SyncConflict[] }> {
    try {
      // Importer dynamiquement pour ├®viter les d├®pendances circulaires
      const { useStore } = await import('@/store');
      const store = useStore.getState();

      const storeWorlds = store.worlds || [];
      let synced = 0;
      const conflicts: SyncConflict[] = [];

      for (const world of storeWorlds) {
        try {
          // Essayer de charger depuis le fichier
          const fileWorld = await persistenceService.loadWorld(world.id, projectPath);

          if (!fileWorld) {
            // Monde existe dans store mais pas dans fichier - sauvegarder
            await persistenceService.saveWorld(world, projectPath);
            synced++;
          } else {
            // Les deux existent - v├®rifier les conflits
            const conflict = this.detectConflict(world, fileWorld, 'world');
            if (conflict) {
              conflicts.push(conflict);
              // R├®soudre automatiquement : store wins (plus r├®cent)
              await persistenceService.saveWorld(world, projectPath);
            }
          }
        } catch (error) {
          logger.error(`[SyncManager] Error syncing world ${world.id}:`, error);
        }
      }

      // V├®rifier les mondes qui existent dans les fichiers mais pas dans le store
      // Cette logique serait plus complexe et n├®cessiterait de scanner les fichiers

      return { synced, conflicts };
    } catch (error) {
      logger.error('[SyncManager] Error syncing worlds:', error);
      return { synced: 0, conflicts: [] };
    }
  }

  /**
   * Synchronisation des personnages
   */
  private async syncCharacters(projectPath?: string): Promise<{ synced: number, conflicts: SyncConflict[] }> {
    try {
      const { useStore } = await import('@/store');
      const store = useStore.getState();

      const storeCharacters = store.characters || [];
      let synced = 0;
      const conflicts: SyncConflict[] = [];

      // Synchroniser chaque personnage avec la m├®thode appropri├®e
      for (const character of storeCharacters) {
        try {
          // Utiliser saveCharacter au lieu de saveWorld
          await persistenceService.saveCharacter(character, projectPath);
          synced++;
        } catch (error) {
          logger.error(`[SyncManager] Error syncing character ${character.character_id}:`, error);
        }
      }

      return { synced, conflicts };
    } catch (error) {
      logger.error('[SyncManager] Error syncing characters:', error);
      return { synced: 0, conflicts: [] };
    }
  }

  /**
   * Synchronisation des s├®quences
   */
  private async syncSequences(projectPath?: string): Promise<{ synced: number, conflicts: SyncConflict[] }> {
    // Logique similaire pour les s├®quences
    return { synced: 0, conflicts: [] };
  }

  /**
   * Synchronisation des sc├¿nes
   */
  private async syncScenes(projectPath?: string): Promise<{ synced: number, conflicts: SyncConflict[] }> {
    // Logique similaire pour les sc├¿nes
    return { synced: 0, conflicts: [] };
  }

  /**
   * Synchronisation des plans
   */
  private async syncShots(projectPath?: string): Promise<{ synced: number, conflicts: SyncConflict[] }> {
    // Logique similaire pour les plans
    return { synced: 0, conflicts: [] };
  }

  /**
   * D├®tection de conflits entre versions
   */
  private detectConflict(storeVersion: unknown, fileVersion: unknown, entityType: string): SyncConflict | null {
    // Type guard to check if it's a valid object with timestamps
    if (!isObject(storeVersion) || !isObject(fileVersion)) {
      return null;
    }

    // Comparer les timestamps de mise ├á jour
    const storeTime = (storeVersion as Record<string, unknown>).updatedAt || (storeVersion as Record<string, unknown>).createdAt;
    const fileTime = (fileVersion as Record<string, unknown>).updatedAt || (fileVersion as Record<string, unknown>).createdAt;

    if (!storeTime || !fileTime) {
      return null; // Impossible de d├®terminer
    }

    const storeTimestamp = new Date(storeTime as string).getTime();
    const fileTimestamp = new Date(fileTime as string).getTime();
    const diff = Math.abs(storeTimestamp - fileTimestamp);

    // Si la diff├®rence est sup├®rieure ├á 5 secondes, consid├®rer comme conflit
    if (diff > 5000) {
      return {
        entityType,
        entityId: String((storeVersion as Record<string, unknown>).id || (storeVersion as Record<string, unknown>).character_id || ''),
        storeVersion,
        fileVersion,
        conflictType: 'modified',
        resolution: 'store-wins', // Par d├®faut, store gagne
        timestamp: new Date()
      };
    }

    return null;
  }

  /**
   * R├®soudre un conflit manuellement
   */
  async resolveConflict(conflict: SyncConflict, resolution: SyncConflict['resolution'], customData?: unknown): Promise<void> {
    try {
      let finalData: unknown;

      switch (resolution) {
        case 'store-wins':
          finalData = conflict.storeVersion;
          break;
        case 'file-wins':
          finalData = conflict.fileVersion;
          break;
        case 'merge':
          finalData = this.mergeVersions(conflict.storeVersion, conflict.fileVersion);
          break;
        case 'manual':
          finalData = customData;
          break;
      }

      // Sauvegarder la version r├®solue
      if (conflict.entityType === 'world' && isObject(finalData)) {
        await persistenceService.saveWorld(finalData as unknown as World);
      }
      // Ajouter d'autres types d'entit├®s selon les besoins

      // Marquer le conflit comme r├®solu
      this.conflicts = this.conflicts.filter(c => c !== conflict);

    } catch (error) {
      logger.error(`[SyncManager] Error resolving conflict:`, error);
      throw error;
    }
  }

  /**
   * Fusionner deux versions automatiquement
   */
  private mergeVersions(version1: unknown, version2: unknown): unknown {
    // Strat├®gie de fusion simple : prendre la version la plus r├®cente pour chaque champ
    if (!isObject(version1)) {
      return version2;
    }
    const obj1 = version1 as Record<string, unknown>;
    const merged: Record<string, unknown> = { ...obj1 };

    if (isObject(version2)) {
      const obj2 = version2 as Record<string, unknown>;
      for (const [key, value] of Object.entries(obj2)) {
        if (!(key in merged) || this.isNewer(value, merged[key])) {
          merged[key] = value;
        }
      }
    }

    // Mettre ├á jour le timestamp
    merged.updatedAt = new Date();

    return merged;
  }

  /**
   * D├®terminer si une valeur est "plus r├®cente"
   */
  private isNewer(value1: unknown, value2: unknown): boolean {
    // Pour les dates
    if (value1 instanceof Date && value2 instanceof Date) {
      return value1 > value2;
    }

    // Pour les cha├«nes de date
    if (typeof value1 === 'string' && typeof value2 === 'string') {
      try {
        const date1 = new Date(value1);
        const date2 = new Date(value2);
        if (!Number.isNaN(date1.getTime()) && !Number.isNaN(date2.getTime())) {
          return date1 > date2;
        }
      } catch {
        // Pas des dates valides
      }
    }

    // Par d├®faut, consid├®rer la premi├¿re valeur comme plus r├®cente
    return true;
  }

  /**
   * Cr├®er un backup automatique
   */
  async createBackup(projectPath?: string): Promise<string> {
    try {
      const timestamp = new Date().toISOString().replaceAll(':', '-').replaceAll('.', '-');
      const backupId = `backup-${timestamp}`;

      // Sauvegarder toutes les entit├®s
      const { useStore } = await import('@/store');
      const store = useStore.getState();

      const backupData = {
        id: backupId,
        timestamp: new Date(),
        data: {
          worlds: store.worlds,
          characters: store.characters,
          project: store.project
        }
      };

      // Sauvegarder dans localStorage avec une cl├® sp├®ciale
      const backupKey = `backup_${backupId}`;
      localStorage.setItem(backupKey, JSON.stringify(backupData));

      return backupId;
    } catch (error) {
      logger.error('[SyncManager] Error creating backup:', error);
      throw error;
    }
  }

  /**
   * Restaurer depuis un backup
   */
  async restoreFromBackup(backupId: string): Promise<void> {
    try {
      const backupKey = `backup_${backupId}`;
      const backupDataStr = localStorage.getItem(backupKey);

      if (!backupDataStr) {
        throw new Error(`Backup ${backupId} not found`);
      }

      const backupData = JSON.parse(backupDataStr);

      // Restaurer les donn├®es dans le store
      const { useStore } = await import('@/store');
      const store = useStore.getState();

      // Restaurer mondes
      for (const world of backupData.data.worlds || []) {
        await store.addWorld(world);
      }

      // Restaurer personnages
      for (const character of backupData.data.characters || []) {
        await store.addCharacter(character);
      }

    } catch (error) {
      logger.error(`[SyncManager] Error restoring backup ${backupId}:`, error);
      throw error;
    }
  }

  /**
   * D├®marrer la synchronisation automatique
   */
  private startAutoSync(): void {
    // Synchroniser toutes les 5 minutes
    setInterval(async () => {
      try {
        // Obtenir le chemin du projet actuel
        const { useAppStore } = await import('@/stores/useAppStore');
        const appStore = useAppStore.getState();
        const projectPath = appStore.project?.metadata?.path as string | undefined;

        await this.fullSync(projectPath);
      } catch (error) {
        logger.error('[SyncManager] Auto-sync failed:', error);
      }
    }, 5 * 60 * 1000); // 5 minutes

    // ├ëcouter les changements de projet
    globalThis.addEventListener('project-changed', async () => {
      try {
        const { useAppStore } = await import('@/stores/useAppStore');
        const appStore = useAppStore.getState();
        const projectPath = appStore.project?.metadata?.path as string | undefined;

        await this.fullSync(projectPath);
      } catch (error) {
        logger.error('[SyncManager] Project change sync failed:', error);
      }
    });
  }

  /**
   * Obtenir l'├®tat actuel de la synchronisation
   */
  getSyncStatus(): {
    inProgress: boolean;
    lastSyncTime: Date | null;
    conflictCount: number;
    recentConflicts: SyncConflict[];
  } {
    return {
      inProgress: this.syncInProgress,
      lastSyncTime: this.lastSyncTime,
      conflictCount: this.conflicts.length,
      recentConflicts: this.conflicts.slice(-5) // Derniers 5 conflits
    };
  }

  /**
   * Nettoyer les anciens conflits r├®solus
   */
  cleanupOldConflicts(maxAge: number = 24 * 60 * 60 * 1000): void { // 24h par d├®faut
    const cutoff = Date.now() - maxAge;
    this.conflicts = this.conflicts.filter(conflict => conflict.timestamp.getTime() > cutoff);
  }
}

// Export de l'instance singleton
export const syncManager = SyncManager.getInstance();

/**
 * ThumbnailCache Service
 * 
 * Implements a two-tier caching system for video thumbnails:
 * - Memory cache with LRU eviction policy
 * - Persistent disk cache using IndexedDB
 * 
 * Now with Observer pattern for real-time synchronization
 * 
 * Validates: Requirements 5.1, 5.2, 5.3, 5.8
 */

export interface ThumbnailCacheConfig {
  maxMemorySize: number; // in MB
  maxDiskSize: number; // in MB
  quality: 'low' | 'medium' | 'high';
  preloadDistance: number; // number of thumbnails to preload
}

export interface CacheEntry {
  key: string;
  blob: Blob;
  size: number;
  lastAccessed: number;
  quality: string;
}

/**
 * Callback type for cache updates
 */
export type CacheUpdateCallback = (key: string, entry: CacheEntry) => void;

/**
 * Callback type for cache clear events
 */
export type CacheClearCallback = (cleared: boolean) => void;

/**
 * Callback type for cache stats updates
 */
export type CacheStatsCallback = (stats: CacheStats) => void;

export interface CacheStats {
  memorySize: number;
  memoryUsage: number;
  memoryCount: number;
  maxMemorySize: number;
}

export class ThumbnailCache {
  private memoryCache: Map<string, CacheEntry>;
  private db: IDBDatabase | null = null;
  private config: ThumbnailCacheConfig;
  private currentMemorySize: number;
  private static instance: ThumbnailCache | null = null;
  private initPromise: Promise<void> | null = null;
  
  // Subscribers for different events
  private cacheUpdateSubscribers: Set<CacheUpdateCallback> = new Set();
  private cacheClearSubscribers: Set<CacheClearCallback> = new Set();
  private cacheStatsSubscribers: Set<CacheStatsCallback> = new Set();

  private constructor(config: ThumbnailCacheConfig) {
    this.memoryCache = new Map();
    this.config = config;
    this.currentMemorySize = 0;
  }

  /**
   * Get singleton instance of ThumbnailCache
   */
  static getInstance(config?: ThumbnailCacheConfig): ThumbnailCache {
    if (!ThumbnailCache.instance) {
      const defaultConfig: ThumbnailCacheConfig = {
        maxMemorySize: 100, // 100 MB
        maxDiskSize: 500, // 500 MB
        quality: 'medium',
        preloadDistance: 5
      };
      ThumbnailCache.instance = new ThumbnailCache(config || defaultConfig);
    }
    return ThumbnailCache.instance;
  }

  /**
   * Subscribe to cache updates
   * Returns unsubscribe function
   */
  public subscribeToCacheUpdates(callback: CacheUpdateCallback): () => void {
    this.cacheUpdateSubscribers.add(callback);
    return () => {
      this.cacheUpdateSubscribers.delete(callback);
    };
  }

  /**
   * Subscribe to cache clear events
   * Returns unsubscribe function
   */
  public subscribeToCacheClear(callback: CacheClearCallback): () => void {
    this.cacheClearSubscribers.add(callback);
    return () => {
      this.cacheClearSubscribers.delete(callback);
    };
  }

  /**
   * Subscribe to cache stats updates
   * Returns unsubscribe function
   */
  public subscribeToCacheStats(callback: CacheStatsCallback): () => void {
    this.cacheStatsSubscribers.add(callback);
    return () => {
      this.cacheStatsSubscribers.delete(callback);
    };
  }

  /**
   * Notify subscribers of cache update
   */
  private notifyCacheUpdate(key: string, entry: CacheEntry): void {
    this.cacheUpdateSubscribers.forEach(callback => {
      try {
        callback(key, entry);
      } catch (error) {
        console.error('[ThumbnailCache] Error in cache update subscriber:', error);
      }
    });
  }

  /**
   * Notify subscribers of cache clear
   */
  private notifyCacheClear(cleared: boolean): void {
    this.cacheClearSubscribers.forEach(callback => {
      try {
        callback(cleared);
      } catch (error) {
        console.error('[ThumbnailCache] Error in cache clear subscriber:', error);
      }
    });
  }

  /**
   * Notify subscribers of cache stats update
   */
  private notifyCacheStats(): void {
    const stats = this.getStats();
    this.cacheStatsSubscribers.forEach(callback => {
      try {
        callback(stats);
      } catch (error) {
        console.error('[ThumbnailCache] Error in cache stats subscriber:', error);
      }
    });
  }

  /**
   * Initialize IndexedDB for persistent storage
   * Validates: Requirement 5.8
   */
  async initIndexedDB(): Promise<void> {
    if (this.initPromise) {
      return this.initPromise;
    }

    this.initPromise = new Promise((resolve, reject) => {
      const request = indexedDB.open('ThumbnailCacheDB', 1);

      request.onerror = () => {
        reject(new Error('Failed to open IndexedDB'));
      };

      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        
        if (!db.objectStoreNames.contains('thumbnails')) {
          const objectStore = db.createObjectStore('thumbnails', { keyPath: 'key' });
          objectStore.createIndex('lastAccessed', 'lastAccessed', { unique: false });
          objectStore.createIndex('size', 'size', { unique: false });
        }
      };
    });

    return this.initPromise;
  }

  /**
   * Get thumbnail from cache (memory first, then disk)
   * Validates: Requirements 5.1, 5.2
   */
  async get(videoUrl: string, time: number, quality?: string): Promise<Blob | null> {
    const key = this.generateKey(videoUrl, time, quality);

    // Check memory cache first (Requirement 5.1)
    const memoryEntry = this.memoryCache.get(key);
    if (memoryEntry) {
      memoryEntry.lastAccessed = Date.now();
      return memoryEntry.blob;
    }

    // Check IndexedDB (Requirement 5.2)
    const diskEntry = await this.getFromDisk(key);
    if (diskEntry) {
      this.addToMemory(key, diskEntry);
      return diskEntry.blob;
    }

    return null;
  }

  /**
   * Set thumbnail in cache (both memory and disk)
   * Validates: Requirements 5.1, 5.3
   */
  async set(videoUrl: string, time: number, blob: Blob, quality?: string): Promise<void> {
    const key = this.generateKey(videoUrl, time, quality);
    const entry: CacheEntry = {
      key,
      blob,
      size: blob.size,
      lastAccessed: Date.now(),
      quality: quality || this.config.quality
    };

    // Add to memory cache with LRU eviction (Requirement 5.3)
    this.addToMemory(key, entry);

    // Persist to disk
    await this.saveToDisk(key, entry);
    
    // Notify subscribers
    this.notifyCacheUpdate(key, entry);
    this.notifyCacheStats();
  }

  /**
   * Add entry to memory cache with LRU eviction
   * Validates: Requirement 5.3
   */
  private addToMemory(key: string, entry: CacheEntry): void {
    const maxMemoryBytes = this.config.maxMemorySize * 1024 * 1024;

    // Evict LRU entries if necessary (Requirement 5.3)
    while (this.currentMemorySize + entry.size > maxMemoryBytes && this.memoryCache.size > 0) {
      this.evictLRU();
    }

    // Only add if there's space
    if (this.currentMemorySize + entry.size <= maxMemoryBytes) {
      this.memoryCache.set(key, entry);
      this.currentMemorySize += entry.size;
    }
  }

  /**
   * Evict least recently used entry from memory cache
   * Validates: Requirement 5.3 (LRU eviction policy)
   */
  private evictLRU(): void {
    let oldestKey: string | null = null;
    let oldestTime = Infinity;

    for (const [key, entry] of this.memoryCache.entries()) {
      if (entry.lastAccessed < oldestTime) {
        oldestTime = entry.lastAccessed;
        oldestKey = key;
      }
    }

    if (oldestKey) {
      const entry = this.memoryCache.get(oldestKey)!;
      this.currentMemorySize -= entry.size;
      this.memoryCache.delete(oldestKey);
    }
  }

  /**
   * Get entry from IndexedDB
   * Validates: Requirement 5.8
   */
  private async getFromDisk(key: string): Promise<CacheEntry | null> {
    if (!this.db) {
      await this.initIndexedDB();
    }

    return new Promise((resolve, reject) => {
      if (!this.db) {
        resolve(null);
        return;
      }

      const transaction = this.db.transaction(['thumbnails'], 'readonly');
      const objectStore = transaction.objectStore('thumbnails');
      const request = objectStore.get(key);

      request.onsuccess = () => {
        resolve(request.result || null);
      };

      request.onerror = () => {
        reject(new Error(`Failed to get entry from disk: ${key}`));
      };
    });
  }

  /**
   * Save entry to IndexedDB
   * Validates: Requirement 5.8
   */
  private async saveToDisk(key: string, entry: CacheEntry): Promise<void> {
    if (!this.db) {
      await this.initIndexedDB();
    }

    return new Promise((resolve, reject) => {
      if (!this.db) {
        reject(new Error('IndexedDB not initialized'));
        return;
      }

      const transaction = this.db.transaction(['thumbnails'], 'readwrite');
      const objectStore = transaction.objectStore('thumbnails');
      const request = objectStore.put(entry);

      request.onsuccess = () => {
        resolve();
      };

      request.onerror = () => {
        // Handle quota exceeded error
        if (request.error?.name === 'QuotaExceededError') {
          this.handleQuotaExceeded().then(() => {
            // Retry after cleanup
            this.saveToDisk(key, entry).then(resolve).catch(reject);
          }).catch(reject);
        } else {
          reject(new Error(`Failed to save entry to disk: ${key}`));
        }
      };
    });
  }

  /**
   * Handle quota exceeded error by removing oldest entries
   * Validates: Requirement 5.8
   */
  private async handleQuotaExceeded(): Promise<void> {
    if (!this.db) {
      return;
    }

    return new Promise((resolve, reject) => {
      if (!this.db) {
        reject(new Error('IndexedDB not initialized'));
        return;
      }

      const transaction = this.db.transaction(['thumbnails'], 'readwrite');
      const objectStore = transaction.objectStore('thumbnails');
      const index = objectStore.index('lastAccessed');
      const request = index.openCursor();

      let deletedCount = 0;
      const maxToDelete = 10; // Delete 10 oldest entries

      request.onsuccess = (event) => {
        const cursor = (event.target as IDBRequest).result;
        if (cursor && deletedCount < maxToDelete) {
          cursor.delete();
          deletedCount++;
          cursor.continue();
        } else {
          resolve();
        }
      };

      request.onerror = () => {
        reject(new Error('Failed to handle quota exceeded'));
      };
    });
  }

  /**
   * Generate cache key from video URL, time, and quality
   */
  private generateKey(videoUrl: string, time: number, quality?: string): string {
    return `${videoUrl}:${time}:${quality || this.config.quality}`;
  }

  /**
   * Check if key exists in cache
   */
  has(key: string): boolean {
    return this.memoryCache.has(key);
  }

  /**
   * Get current memory cache size
   */
  size(): number {
    return this.memoryCache.size;
  }

  /**
   * Get current memory usage in bytes
   */
  getMemoryUsage(): number {
    return this.currentMemorySize;
  }

  /**
   * Clear all caches (memory and disk)
   */
  async clear(): Promise<void> {
    // Clear memory cache
    this.memoryCache.clear();
    this.currentMemorySize = 0;

    // Clear disk cache
    if (!this.db) {
      await this.initIndexedDB();
    }

    return new Promise((resolve, reject) => {
      if (!this.db) {
        reject(new Error('IndexedDB not initialized'));
        return;
      }

      const transaction = this.db.transaction(['thumbnails'], 'readwrite');
      const objectStore = transaction.objectStore('thumbnails');
      const request = objectStore.clear();

      request.onsuccess = () => {
        // Notify subscribers
        this.notifyCacheClear(true);
        this.notifyCacheStats();
        resolve();
      };

      request.onerror = () => {
        reject(new Error('Failed to clear disk cache'));
      };
    });
  }

  /**
   * Preload thumbnails for given times
   * Validates: Requirements 5.5, 5.7
   */
  async preload(videoUrl: string, times: number[], quality?: string): Promise<void> {
    const promises = times.map(time => 
      this.generateAndCache(videoUrl, time, quality)
    );
    await Promise.all(promises);
  }

  /**
   * Preload adjacent thumbnails based on current position
   * Validates: Requirements 5.5, 5.7
   */
  async preloadAdjacent(
    videoUrl: string,
    currentTime: number,
    framerate: number,
    quality?: string
  ): Promise<void> {
    const frameTime = 1 / framerate;
    const times: number[] = [];

    // Preload thumbnails before and after current position
    for (let i = 1; i <= this.config.preloadDistance; i++) {
      times.push(currentTime + (i * frameTime));
      times.push(Math.max(0, currentTime - (i * frameTime)));
    }

    await this.preload(videoUrl, times, quality);
  }

  /**
   * Preload thumbnails for visible range with priority
   * Validates: Requirements 5.5, 5.7
   */
  async preloadVisible(
    videoUrl: string,
    visibleTimes: number[],
    adjacentTimes: number[],
    quality?: string
  ): Promise<void> {
    // Prioritize visible thumbnails
    const visiblePromises = visibleTimes.map(time =>
      this.generateAndCache(videoUrl, time, quality)
    );

    // Wait for visible thumbnails first
    await Promise.all(visiblePromises);

    // Then preload adjacent thumbnails in background
    const adjacentPromises = adjacentTimes.map(time =>
      this.generateAndCache(videoUrl, time, quality)
    );

    // Don't wait for adjacent thumbnails
    Promise.all(adjacentPromises).catch(err => {
      console.warn('Failed to preload adjacent thumbnails:', err);
    });
  }

  /**
   * Generate thumbnail and cache it
   * Validates: Requirements 5.5, 5.7
   */
  async generateAndCache(
    videoUrl: string,
    time: number,
    quality?: string
  ): Promise<Blob> {
    const key = this.generateKey(videoUrl, time, quality);

    // Check if already in cache
    const cached = await this.get(videoUrl, time, quality);
    if (cached) {
      return cached;
    }

    // Generate thumbnail (this would be implemented by the video player)
    const blob = await this.generateThumbnail(videoUrl, time, quality);
    await this.set(videoUrl, time, blob, quality);
    return blob;
  }

  /**
   * Generate thumbnail from video at specific time
   * This is a placeholder - actual implementation would use video element
   */
  private async generateThumbnail(
    videoUrl: string,
    time: number,
    quality?: string
  ): Promise<Blob> {
    return new Promise((resolve, reject) => {
      const video = document.createElement('video');
      video.crossOrigin = 'anonymous';
      video.src = videoUrl;

      video.addEventListener('loadedmetadata', () => {
        video.currentTime = time;
      });

      video.addEventListener('seeked', () => {
        const canvas = document.createElement('canvas');
        const qualitySettings = {
          low: { width: 160, height: 90 },
          medium: { width: 320, height: 180 },
          high: { width: 640, height: 360 }
        };

        const settings = qualitySettings[quality as keyof typeof qualitySettings] || qualitySettings.medium;
        canvas.width = settings.width;
        canvas.height = settings.height;

        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          canvas.toBlob((blob) => {
            if (blob) {
              resolve(blob);
            } else {
              reject(new Error('Failed to generate thumbnail blob'));
            }
          }, 'image/jpeg', 0.8);
        } else {
          reject(new Error('Failed to get canvas context'));
        }
      });

      video.addEventListener('error', () => {
        reject(new Error(`Failed to load video: ${videoUrl}`));
      });
    });
  }

  /**
   * Get cache statistics
   */
  getStats(): {
    memorySize: number;
    memoryUsage: number;
    memoryCount: number;
    maxMemorySize: number;
  } {
    return {
      memorySize: this.currentMemorySize,
      memoryUsage: (this.currentMemorySize / (this.config.maxMemorySize * 1024 * 1024)) * 100,
      memoryCount: this.memoryCache.size,
      maxMemorySize: this.config.maxMemorySize * 1024 * 1024
    };
  }
}

/**
 * Workflow Orchestrator - Logic layer for end-to-end workflow synchronization
 * 
 * This service listens to multiple stores and updates the workflowStore
 * to provide a unified view of the project's progress.
 */

import { useWorkflowStore, WorkflowStage } from '../stores/workflowStore';
import { useAppStore } from '../stores/useAppStore';
import { useGenerationStore } from '../stores/generationStore';

export class WorkflowOrchestrator {
    private static instance: WorkflowOrchestrator;
    private unsubscribe: (() => void)[] = [];

    private constructor() {
        this.setupListeners();
    }

    public static getInstance(): WorkflowOrchestrator {
        if (!WorkflowOrchestrator.instance) {
            WorkflowOrchestrator.instance = new WorkflowOrchestrator();
        }
        return WorkflowOrchestrator.instance;
    }

    /**
     * Setup listeners for all relevant stores
     */
    private setupListeners() {
        // 1. Listen to AppStore (Wizards, Projects, Shots)
        const subApp = useAppStore.subscribe((state, prevState) => {
            // World creation check
            if (state.worlds.length > prevState.worlds.length) {
                this.completeTask('preparation', 'create_world');
            }

            // Character creation check
            if (state.characters.length > prevState.characters.length) {
                this.completeTask('preparation', 'create_main_character');
            }

            // Project setup
            if (state.project && !prevState.project) {
                this.completeTask('preparation', 'create_world'); // Assume project creation is part of world/setting
            }

            // Storyteller / Story generation
            // This is harder since we don't have a direct "story" type in AppStore yet (it's in StorytellerWizard)
            // We can check if shots are added
            if (state.shots.length > 0 && prevState.shots.length === 0) {
                this.completeTask('storytelling', 'generate_story');
                this.completeTask('storytelling', 'list_shots');
            }
        });

        // 2. Listen to GenerationStore (AI Assets)
        const subGen = useGenerationStore.subscribe((state, prevState) => {
            const { currentPipeline } = state;
            if (!currentPipeline) return;

            // Completion of generation stages
            if (currentPipeline.stages.image.status === 'completed') {
                this.completeTask('generation', 'generate_images');
            }
            if (currentPipeline.stages.video.status === 'completed') {
                this.completeTask('generation', 'generate_videos');
            }
            if (currentPipeline.stages.audio.status === 'completed') {
                this.completeTask('generation', 'generate_audio');
            }

            // Transition to post-prod when everything is generated once
            if (
                currentPipeline.stages.image.status === 'completed' &&
                currentPipeline.stages.audio.status === 'completed'
            ) {
                useWorkflowStore.getState().setStage('post_prod');
            }
        });

        this.unsubscribe.push(subApp, subGen);
    }

    /**
     * Helper to complete a task and recalculate progress
     */
    private completeTask(stage: WorkflowStage, taskId: string) {
        const store = useWorkflowStore.getState();
        store.completeTask(stage, taskId);
        store.calculateGlobalProgress();

        // Auto-advance stage if complete
        const stageData = store.stageProgress[stage];
        if (stageData.percentage === 100) {
            this.advanceToNextStage(stage);
        }
    }

    /**
     * Automatically advance to the next logical stage
     */
    private advanceToNextStage(currentStage: WorkflowStage) {
        const store = useWorkflowStore.getState();
        switch (currentStage) {
            case 'preparation':
                store.setStage('storytelling');
                break;
            case 'storytelling':
                store.setStage('generation');
                break;
            case 'generation':
                store.setStage('post_prod');
                break;
            case 'post_prod':
                // delivery is manual
                break;
        }
    }

    /**
     * Suggest the next best action for the user
     */
    public getNextAction(): { label: string; action: () => void } | null {
        const store = useWorkflowStore.getState();
        const appStore = useAppStore.getState();
        const current = store.currentStage;
        const progress = store.stageProgress[current];

        // Find the first incomplete task in current stage
        const nextTask = progress.requiredTasks.find(id => !progress.completedTasks.includes(id));

        if (!nextTask) return null;

        switch (nextTask) {
            case 'create_world':
                return { label: 'B├ótir le Monde', action: () => appStore.setShowWorldWizard(true) };
            case 'create_main_character':
                return { label: 'Cr├®er un Personnage', action: () => appStore.setShowCharacterWizard(true) };
            case 'generate_story':
                return { label: 'G├®n├®rer une Histoire', action: () => appStore.setShowStorytellerWizard(true) };
            case 'plan_sequences':
                return { label: 'Planifier les S├®quences', action: () => appStore.openSequencePlanWizard() };
            case 'list_shots':
                return { label: 'Pr├®parer les Plans', action: () => appStore.openShotWizard() };
            // Additionnal mappings...
        }

        return null;
    }

    public destroy() {
        this.unsubscribe.forEach(unsub => unsub());
        this.unsubscribe = [];
    }
}

