        const method = Object.getOwnPropertyNames(Object.getPrototypeOf(service))
          .find(name => name === 'ensureDirectoryExists');
        if (method) {
          return (service as any)[method](path);
        }
        throw new Error('ensureDirectoryExists method not found');
      };
