    const intensityMultipliers: Record<string, number> = {
      'low': 0.9,
      'medium': 1.0,
      'high': 1.15,
      'evolving': 1.0
    };
    
    const base = baseBPM[type] || 100;
    const multiplier = intensityMultipliers[intensity] || 1.0;
    
    return Math.round(base * multiplier);
  }

