        trackType: 'action',
        prompt: 'G├®n├¿re les sons de d├®bris et r├®sonance secondaire pour enrichir l\'impact',
        parameters: { intensity: 'medium' },
        enabled: true,
        volume: -6,
        pan: 0,
        muted: false,
        solo: false,
        effects: [],
        automation: [],
        muffling: { ...defaultMuffling, enabled: true, mufflingType: 'reverb_muffled' }
      });
    }
    
    if (this.profile.actionType === 'whoosh' || this.profile.actionType === 'transition') {
      tracks.push({
        id: `sfx_whoosh_${this.projectId}`,
        name: 'Whoosh Principal',
        trackType: 'action',
        prompt: this.generateWhooshPrompt(),
        parameters: { intensity: this.profile.intensity || 'medium' },
        enabled: true,
        volume: 0,
        pan: 0,
        muted: false,
        solo: false,
        effects: [],
        automation: [],
        muffling: this.profile.muffling || defaultMuffling
      });
    }
    
    return tracks;
  }

  private generateImpactPrompt(): string {
    return `G├®n├¿re un SFX d'impact pour une sc├¿ne de ${this.profile.environment || 'action'}.
Intensit├®: ${this.profile.intensity}
Type: ${this.profile.actionType}
R├¿gles: +3-6 dB pour impacts, compression forte, limiter ├á -1 dB
Muffling: ${this.profile.muffling?.enabled ? 'activ├® avec cutoff ├á ' + this.profile.muffling?.cutoffFrequency + 'Hz' : 'd├®sactiv├®'}
Sync: ${this.profile.sync?.alignWithAction ? 'align├® avec l\'action' : 'non align├®'}
Duration: 0.5-2 secondes`;
  }

  private generateWhooshPrompt(): string {
    return `G├®n├¿re un whoosh/transition pour une sc├¿ne de ${this.profile.environment || 'action'}.
Intensit├®: ${this.profile.intensity}
Type: ${this.profile.actionType}
R├¿gles: Fades fluides, EQ dynamique, compression l├®g├¿re
Sync: ${this.profile.sync?.alignWithMusic ? 'align├® avec la musique' : 'libre'}
Duration: 1-4 secondes`;
