/**
 * StoryCore-Engine Audio-Sequence Integration Service
 */

import type {
  MusicProfile,
  SFXProfile,
  VoiceProfile,
  MixConfiguration
} from '../types/audioMultitrack';
import { audioMultitrackService } from './audioMultitrack';

export type IntegrationAudioType = 'music' | 'sfx' | 'voice' | 'all';
export type IntegrationStatus = 'pending' | 'processing' | 'completed' | 'failed';

export interface SequenceAudioContext {
  projectId: string;
  projectType?: string;
  location?: string;
  themes: string[];
  visualStyle?: string;
  emotionalIntensity: string;
  shotId?: string;
  shotType: string;
  shotDescription?: string;
  shotDuration: number;
  actionType?: string;
  actionIntensity?: string;
  visualRhythm?: string;
  autoMix: boolean;
  ducking: boolean;
}

export interface IntegratedAudioResult {
  success: boolean;
  status: IntegrationStatus;
  musicPrompts: TrackPrompt[];
  sfxPrompts: TrackPrompt[];
  voicePrompts: TrackPrompt[];
  errors: string[];
  generatedAt: string;
}

export interface TrackPrompt {
  trackName: string;
  trackType: string;
  prompt: string;
  shotId?: string;
}

export interface TimelineTrack {
  id: string;
  name: string;
  type: string;
  clips: TimelineClip[];
  muted: boolean;
  volume: number;
  height: number;
}

export interface TimelineClip {
  id: string;
  name: string;
  startTime: number;
  duration: number;
  audioTrackId: string;
  prompt: string;
  regeneratable: boolean;
}

export interface TimelineSyncData {
  sequenceId: string;
  projectId: string;
  totalDuration: number;
  tracks: TimelineTrack[];
  generatedAt: string;
  audioPrompts: {
    music: TrackPrompt[];
    sfx: TrackPrompt[];
    voice: TrackPrompt[];
  };
}

export class AudioSequenceIntegrationService {
  /**
   * Extract audio contexts from a generated sequence
   */
  extractContextsFromSequence(
    sequence: unknown,
    projectContext?: Record<string, unknown>
  ): SequenceAudioContext[] {
    const contexts: SequenceAudioContext[] = [];
    const projectId = sequence.project_id || '';
    const shots = sequence.shots || [];
    const projType = projectContext?.project_type || '';
    const location = projectContext?.location || '';
    const themes = projectContext?.themes || [];
    const style = projectContext?.visual_style || '';
    const intensity = projectContext?.emotional_intensity || 'medium';

    for (const shot of shots) {
      contexts.push({
        projectId,
        projectType: projType,
        location,
        themes: [...themes],
        visualStyle: style,
        emotionalIntensity: intensity,
        shotId: shot.id,
        shotType: shot.shot_type || 'action',
        shotDescription: shot.prompt || '',
        shotDuration: shot.duration_seconds || 5.0,
        autoMix: true,
        ducking: true
      });
    }
    return contexts;
  }

  /**
   * Generate all audio for a complete sequence
   */
  async generateAudioForSequence(
    sequence: unknown,
    projectContext?: Record<string, unknown>,
    audioTypes: IntegrationAudioType[] = ['all']
  ): Promise<IntegratedAudioResult> {
    const result: IntegratedAudioResult = {
      success: true,
      status: 'completed',
      musicPrompts: [],
      sfxPrompts: [],
      voicePrompts: [],
      errors: [],
      generatedAt: new Date().toISOString()
    };

    const contexts = this.extractContextsFromSequence(sequence, projectContext);
    const shouldGenerateMusic = audioTypes.includes('all') || audioTypes.includes('music');
    const shouldGenerateSFX = audioTypes.includes('all') || audioTypes.includes('sfx');
    const shouldGenerateVoice = audioTypes.includes('all') || audioTypes.includes('voice');

    if (shouldGenerateMusic) {
      for (const context of contexts) {
        result.musicPrompts.push(
          { trackName: 'Base', trackType: 'base', prompt: `Music base for ${context.shotType}`, shotId: context.shotId },
          { trackName: 'Melody', trackType: 'melody', prompt: `Music melody for ${context.shotType}`, shotId: context.shotId },
          { trackName: 'Percussion', trackType: 'percussion', prompt: `Percussion for ${context.shotType}`, shotId: context.shotId },
          { trackName: 'Bass', trackType: 'bass', prompt: `Bass for ${context.shotType}`, shotId: context.shotId },
          { trackName: 'FX', trackType: 'fx', prompt: `Music FX for ${context.shotType}`, shotId: context.shotId },
          { trackName: 'Drones', trackType: 'drones', prompt: `Drones for ${context.shotType}`, shotId: context.shotId }
        );
      }
    }

    if (shouldGenerateSFX) {
      for (const context of contexts) {
        result.sfxPrompts.push(
          { trackName: 'Action', trackType: 'action', prompt: `SFX for ${context.shotType} action`, shotId: context.shotId },
          { trackName: 'Environment', trackType: 'environment', prompt: `Environment sounds for ${context.location || 'scene'}`, shotId: context.shotId },
          { trackName: 'Stylized', trackType: 'stylized', prompt: `Stylized SFX for ${context.shotType}`, shotId: context.shotId },
          { trackName: 'Bullet Time', trackType: 'bullet_time', prompt: `Bullet time SFX for ${context.shotType}`, shotId: context.shotId }
        );
      }
    }

    if (shouldGenerateVoice) {
      for (const context of contexts) {
        result.voicePrompts.push({
          trackName: 'Voice',
          trackType: context.shotType === 'narration' ? 'whisper' : 'raw',
          prompt: context.shotDescription || '',
          shotId: context.shotId
        });
      }
    }

    result.status = result.success ? 'completed' : 'failed';
    return result;
  }

  /**
   * Attach generated audio to a shot
   */
  attachAudioToShot(
    shot: unknown,
    audioResult: IntegratedAudioResult,
    audioType: IntegrationAudioType = 'all'
  ): unknown {
    const shotId = shot.id;
    const musicTracks = audioResult.musicPrompts.filter(p => p.shotId === shotId);
    const sfxTracks = audioResult.sfxPrompts.filter(p => p.shotId === shotId);
    const voiceTracks = audioResult.voicePrompts.filter(p => p.shotId === shotId);
    const audioTracks: unknown[] = [];
    const duration = shot.duration_seconds || 5.0;

    if (audioType === 'all' || audioType === 'music') {
      for (const track of musicTracks) {
        audioTracks.push({
          id: `${shotId}_music_${track.trackName.toLowerCase().replace(' ', '_')}`,
          name: track.trackName,
          type: 'music',
          prompt: track.prompt,
          startTime: 0,
          duration,
          volume: -6.0,
          muted: false,
          regeneratable: true
        });
      }
    }

    if (audioType === 'all' || audioType === 'sfx') {
      for (const track of sfxTracks) {
        audioTracks.push({
          id: `${shotId}_sfx_${track.trackName.toLowerCase().replace(' ', '_')}`,
          name: track.trackName,
          type: 'sfx',
          prompt: track.prompt,
          startTime: 0,
          duration,
          volume: 0.0,
          muted: false,
          regeneratable: true
        });
      }
    }

    if (audioType === 'all' || audioType === 'voice') {
      for (const track of voiceTracks) {
        audioTracks.push({
          id: `${shotId}_voice_${track.trackName.toLowerCase().replace(' ', '_')}`,
          name: track.trackName,
          type: 'voice',
          prompt: track.prompt,
          startTime: 0,
          duration,
          volume: 0.0,
          muted: false,
          regeneratable: true
        });
      }
    }

    return { ...shot, audio_tracks: audioTracks, audio_generated: audioTracks.length > 0 };
  }

  /**
   * Generate timeline synchronization data
   */
  generateTimelineSyncData(sequence: unknown, audioResult: IntegratedAudioResult): TimelineSyncData {
    const shots = sequence.shots || [];
    const timelineTracks: TimelineTrack[] = [
      { id: 'timeline_dialogue', name: 'Dialogue', type: 'voice', clips: [], muted: false, volume: 0, height: 40 },
      { id: 'timeline_sfx_action', name: 'SFX - Action', type: 'sfx', clips: [], muted: false, volume: 0, height: 40 },
      { id: 'timeline_sfx_environment', name: 'SFX - Environment', type: 'sfx', clips: [], muted: false, volume: 0, height: 40 },
      { id: 'timeline_music_base', name: 'Music - Base', type: 'music', clips: [], muted: false, volume: 0, height: 40 },
      { id: 'timeline_music_melody', name: 'Music - Melody', type: 'music', clips: [], muted: false, volume: 0, height: 40 },
      { id: 'timeline_music_percussion', name: 'Music - Percussion', type: 'music', clips: [], muted: false, volume: 0, height: 40 },
      { id: 'timeline_music_bass', name: 'Music - Bass', type: 'music', clips: [], muted: false, volume: 0, height: 40 },
      { id: 'timeline_music_fx', name: 'Music - FX', type: 'music', clips: [], muted: false, volume: 0, height: 40 }
    ];

    let currentTime = 0;
    for (const shot of shots) {
      const shotDuration = shot.duration_seconds || 5.0;
      const shotId = shot.id || '';
      const audioTracks = shot.audio_tracks || [];

      for (const audioTrack of audioTracks) {
        const trackType = audioTrack.type || 'music';
        const trackName = audioTrack.name || '';
        let timelineTrackId = '';

        if (trackType === 'voice') {
          timelineTrackId = 'timeline_dialogue';
        } else if (trackType === 'sfx') {
          timelineTrackId = trackName.toLowerCase().includes('action') ? 'timeline_sfx_action' : 'timeline_sfx_environment';
        } else {
          const nameLower = trackName.toLowerCase();
          if (nameLower.includes('base')) timelineTrackId = 'timeline_music_base';
          else if (nameLower.includes('melody')) timelineTrackId = 'timeline_music_melody';
          else if (nameLower.includes('percussion')) timelineTrackId = 'timeline_music_percussion';
          else if (nameLower.includes('bass')) timelineTrackId = 'timeline_music_bass';
          else if (nameLower.includes('fx')) timelineTrackId = 'timeline_music_fx';
          else timelineTrackId = 'timeline_music_base';
        }

        for (const track of timelineTracks) {
          if (track.id === timelineTrackId) {
            track.clips.push({
              id: audioTrack.id,
              name: trackName,
              startTime: currentTime,
              duration: shotDuration,
              audioTrackId: audioTrack.id,
              prompt: audioTrack.prompt || '',
              regeneratable: audioTrack.regeneratable !== false
            });
            break;
          }
        }
      }
      currentTime += shotDuration;
    }

    return {
      sequenceId: sequence.id || '',
      projectId: sequence.project_id || '',
      totalDuration: currentTime,
      tracks: timelineTracks,
      generatedAt: new Date().toISOString(),
      audioPrompts: { music: audioResult.musicPrompts, sfx: audioResult.sfxPrompts, voice: audioResult.voicePrompts }
    };
  }

  /**
   * Apply audio to entire sequence
   */
  async applyAudioToSequence(
    sequence: unknown,
    projectContext?: Record<string, unknown>,
    audioTypes: IntegrationAudioType[] = ['all']
  ): Promise<{ sequence: unknown; timeline: TimelineSyncData }> {
    const audioResult = await this.generateAudioForSequence(sequence, projectContext, audioTypes);
    const type = audioTypes.includes('all') ? 'all' : audioTypes[0];
    const updatedShots = (sequence.shots || []).map((shot: unknown) => this.attachAudioToShot(shot, audioResult, type));
    const updatedSequence = { ...sequence, shots: updatedShots, audio_generated: audioResult.success, audio_generation_result: audioResult };
    const timeline = this.generateTimelineSyncData(updatedSequence, audioResult);
    return { sequence: updatedSequence, timeline };
  }
}

export const audioSequenceIntegrationService = new AudioSequenceIntegrationService();

export function getDefaultAudioForShotType(shotType: string): { musicIntensity: string; sfxIntensity: string; enableVoice: boolean } {
  const mapping: Record<string, { musicIntensity: string; sfxIntensity: string; enableVoice: boolean }> = {
    'action': { musicIntensity: 'high', sfxIntensity: 'high', enableVoice: false },
    'dialogue': { musicIntensity: 'low', sfxIntensity: 'low', enableVoice: true },
    'ambient': { musicIntensity: 'medium', sfxIntensity: 'medium', enableVoice: false },
    'transition': { musicIntensity: 'low', sfxIntensity: 'low', enableVoice: false },
    'narration': { musicIntensity: 'low', sfxIntensity: 'low', enableVoice: true }
  };
  return mapping[shotType] || { musicIntensity: 'medium', sfxIntensity: 'medium', enableVoice: false };
}

export function estimateAudioGenerationTime(shotCount: number, audioTypes: IntegrationAudioType[]): number {
  return 30 + (shotCount * 10 * audioTypes.length);
}

/**
 * WorkerPool - Pool de Web Workers pour traitement parall├¿le
 * 
 * G├¿re un pool de workers pour ex├®cuter des t├óches en parall├¿le:
 * - Allocation et lib├®ration de workers
 * - File d'attente de t├óches
 * - Gestion des erreurs
 * - Annulation de t├óches
 * 
 * Exigences: 10.1, 10.6
 */

import type { WorkerTask, WorkerMessage } from '../../types';

/**
 * Configuration du pool de workers
 */
export interface WorkerPoolConfig {
  size?: number;
  workerUrl?: string;
}

/**
 * Pool de Web Workers
 * Exigence: 10.1 - Traitement non-bloquant
 * Exigence: 10.6 - Traitement parall├¿le avec file d'attente
 */
export class WorkerPool {
  private workers: Worker[] = [];
  private availableWorkers: Worker[] = [];
  private taskQueue: WorkerTask[] = [];
  public readonly size: number;
  
  constructor(config: WorkerPoolConfig = {}) {
    this.size = config.size || navigator.hardwareConcurrency || 4;
    this.initializeWorkers();
  }
  
  /**
   * Initialise les workers
   */
  private initializeWorkers(): void {
    for (let i = 0; i < this.size; i++) {
      try {
        const worker = new Worker(
          new URL('../../workers/processing.worker.ts', import.meta.url),
          { type: 'module' }
        );
        
        worker.onmessage = (event) => {
          this.handleWorkerMessage(worker, event.data);
        };
        
        worker.onerror = (error) => {
          this.handleWorkerError(worker, error);
        };
        
        this.workers.push(worker);
        this.availableWorkers.push(worker);
      } catch (error) {
        console.error(`Failed to create worker ${i}:`, error);
      }
    }
  }
  
  /**
   * Ex├®cute une t├óche
   * Exigence: 10.1 - Traitement non-bloquant
   */
  async execute<T>(type: string, data: unknown): Promise<T> {
    return new Promise((resolve, reject) => {
      const task: WorkerTask = {
        id: this.generateId(),
        type,
        data,
        resolve,
        reject
      };
      
      const worker = this.availableWorkers.pop();
      
      if (worker) {
        this.executeTask(worker, task);
      } else {
        // Aucun worker disponible, ajouter ├á la file d'attente
        this.taskQueue.push(task);
      }
    });
  }
  
  /**
   * Ex├®cute une t├óche sur un worker
   */
  private executeTask(worker: Worker, task: WorkerTask): void {
    const message: WorkerMessage = {
      id: task.id,
      type: task.type as WorkerMessage['type'],
      data: task.data
    };
    
    worker.postMessage(message);
    
    // Stocker la t├óche pour la r├®solution
    (worker as any).__currentTask = task;
  }
  
  /**
   * G├¿re les messages des workers
   */
  private handleWorkerMessage(worker: Worker, message: unknown): void {
    const task = (worker as any).__currentTask as WorkerTask;
    
    if (task && message.id === task.id) {
      if (message.status === 'completed') {
        task.resolve(message.result);
        this.releaseWorker(worker);
      } else if (message.status === 'error') {
        task.reject(new Error(message.error));
        this.releaseWorker(worker);
      } else if (message.status === 'progress') {
        // Progression - ne pas lib├®rer le worker
        // Peut ├¬tre g├®r├® par un callback si n├®cessaire
      }
    }
  }
  
  /**
   * G├¿re les erreurs des workers
   */
  private handleWorkerError(worker: Worker, error: ErrorEvent): void {
    const task = (worker as any).__currentTask as WorkerTask;
    
    if (task) {
      task.reject(new Error(error.message));
      delete (worker as any).__currentTask;
    }
    
    // Recr├®er le worker
    const index = this.workers.indexOf(worker);
    if (index !== -1) {
      worker.terminate();
      this.workers.splice(index, 1);
      
      try {
        const newWorker = new Worker(
          new URL('../../workers/processing.worker.ts', import.meta.url),
          { type: 'module' }
        );
        
        newWorker.onmessage = (event) => {
          this.handleWorkerMessage(newWorker, event.data);
        };
        
        newWorker.onerror = (error) => {
          this.handleWorkerError(newWorker, error);
        };
        
        this.workers.push(newWorker);
        this.availableWorkers.push(newWorker);
      } catch (error) {
        console.error('Failed to recreate worker:', error);
      }
    }
  }
  
  /**
   * Lib├¿re un worker et traite la prochaine t├óche
   * Exigence: 10.6 - File d'attente de t├óches
   */
  private releaseWorker(worker: Worker): void {
    delete (worker as any).__currentTask;
    
    // Traiter la prochaine t├óche en attente
    const nextTask = this.taskQueue.shift();
    if (nextTask) {
      this.executeTask(worker, nextTask);
    } else {
      // Aucune t├óche en attente, rendre le worker disponible
      this.availableWorkers.push(worker);
    }
  }
  
  /**
   * Annule toutes les t├óches en cours
   * Exigence: 10.5 - Annulation de t├óches
   */
  cancelAll(): void {
    // Vider la file d'attente
    for (const task of this.taskQueue) {
      task.reject(new Error('Task cancelled'));
    }
    this.taskQueue = [];
    
    // Annuler les t├óches en cours
    for (const worker of this.workers) {
      const task = (worker as any).__currentTask as WorkerTask;
      if (task) {
        // Envoyer un message d'annulation au worker
        worker.postMessage({ id: task.id, type: 'cancel' });
        task.reject(new Error('Task cancelled'));
        delete (worker as any).__currentTask;
      }
    }
    
    // Tous les workers sont maintenant disponibles
    this.availableWorkers = [...this.workers];
  }
  
  /**
   * Termine tous les workers
   */
  terminate(): void {
    this.cancelAll();
    
    for (const worker of this.workers) {
      worker.terminate();
    }
    
    this.workers = [];
    this.availableWorkers = [];
  }
  
  /**
   * R├®cup├¿re le nombre de t├óches en attente
   */
  getQueueSize(): number {
    return this.taskQueue.length;
  }
  
  /**
   * R├®cup├¿re le nombre de workers disponibles
   */
  getAvailableWorkers(): number {
    return this.availableWorkers.length;
  }
  
  /**
   * R├®cup├¿re le nombre de workers occup├®s
   */
  getBusyWorkers(): number {
    return this.workers.length - this.availableWorkers.length;
  }
  
  /**
   * G├®n├¿re un ID unique
   */
  private generateId(): string {
    return `task_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
}

/**
 * CineProductionAPI Service
 * 
 * Communication with the High-Fidelity Cinematic Production API.
 * Handles workflows like Image -> Video -> Audio with context-aware prompting.
 */

import { BACKEND_URL } from '../config/apiConfig';
import { getComfyUIServersService } from './comfyuiServersService';

export type CineChainType = 'generate_scene' | 'music_pro' | 'one_character' | 'storyboard_only' | 'audio_remix';

export interface CineProductionRequest {
    projectId: string;
    sceneId?: string;
    chainType: CineChainType;
    sceneDescription: string;
    imagePrompt?: string;
    videoPrompt?: string;
    audioPrompt?: string;
    genre?: string;
    style?: string;
    tone?: string;
    preferredEngine?: string;
    comfyuiUrl?: string;
    overrides?: Record<string, any>;
}

export interface CineProductionJob {
    jobId: string;
    request: CineProductionRequest;
    status: 'pending' | 'processing' | 'completed' | 'failed';
    progress: number;
    results: Array<{
        step: string;
        output: any;
    }>;
    error?: string;
    startTime: string;
    endTime?: string;
}

export interface WorkflowInfo {
    id: string;
    name: string;
    description: string;
    isCustom: boolean;
}

class CineProductionAPI {
    private baseUrl: string;

    constructor() {
        this.baseUrl = (import.meta.env.VITE_BACKEND_URL || BACKEND_URL) + '/api/cine-production';
    }

    private async request<T>(endpoint: string, options: RequestInit = {}): Promise<T> {
        const response = await fetch(`${this.baseUrl}${endpoint}`, {
            headers: {
                'Content-Type': 'application/json',
                ...options.headers,
            },
            ...options,
        });

        if (!response.ok) {
            const error = await response.json().catch(() => ({ detail: 'Request failed' }));
            throw new Error(error.detail || `HTTP ${response.status}`);
        }

        return response.json();
    }

    /**
     * Start a new production job
     */
    async startProduction(request: CineProductionRequest): Promise<{ jobId: string }> {
        // Automatically inject active ComfyUI server URL if not provided
        if (!request.comfyuiUrl) {
            try {
                const activeUrl = getComfyUIServersService().getActiveServerUrl();
                if (activeUrl) {
                    request.comfyuiUrl = activeUrl;
                }
            } catch (error) {
                console.warn('[CineProductionAPI] Failed to get active ComfyUI server:', error);
            }
        }

        return this.request<{ jobId: string }>('/start', {
            method: 'POST',
            body: JSON.stringify(request),
        });
    }

    /**
     * Get production job status and results
     */
    async getJob(jobId: string): Promise<CineProductionJob> {
        return this.request<CineProductionJob>(`/job/${jobId}`);
    }

    /**
     * Get list of available production workflows
     */
    async listWorkflows(): Promise<WorkflowInfo[]> {
        return this.request<WorkflowInfo[]>('/workflows');
    }

    /**
     * Monitor a job until completion
     */
    async monitorJob(
        jobId: string,
        onProgress?: (progress: number, step?: string) => void,
        intervalMs: number = 2000
    ): Promise<CineProductionJob> {
        return new Promise((resolve, reject) => {
            const poll = async () => {
                try {
                    const job = await this.getJob(jobId);

                    if (onProgress) {
                        const lastStep = job.results.length > 0 ? job.results[job.results.length - 1].step : undefined;
                        onProgress(job.progress, lastStep);
                    }

                    if (job.status === 'completed') {
                        resolve(job);
                    } else if (job.status === 'failed') {
                        reject(new Error(job.results.find(r => r.step === 'error')?.output || 'Job failed'));
                    } else {
                        setTimeout(poll, intervalMs);
                    }
                } catch (error) {
                    reject(error);
                }
            };
            poll();
        });
    }
}

export const cineProductionAPI = new CineProductionAPI();
export default cineProductionAPI;

/**
 * Clipboard Manager - Manages copy/paste operations for shots
 * 
 * This service handles:
 * - Internal clipboard for shots
 * - Copy, cut, and paste operations
 * - ID uniqueness generation
 * - Metadata preservation
 * - Cross-sequence compatibility validation
 * 
 * Requirements: 13.1, 13.2, 13.3, 13.5
 */

import type { Shot } from '../../types';
import { generateId } from '../../utils/idGenerator';

// ============================================================================
// Types
// ============================================================================

export interface ClipboardData {
  shots: Shot[];
  operation: 'copy' | 'cut';
  timestamp: number;
  sourceSequenceId?: string;
}

export interface PasteOptions {
  targetSequenceId?: string;
  position?: number;
  validateCompatibility?: boolean;
}

export interface PasteResult {
  success: boolean;
  pastedShots: Shot[];
  errors?: string[];
}

// ============================================================================
// Clipboard Manager Class
// ============================================================================

export class ClipboardManager {
  private static instance: ClipboardManager;
  private clipboard: ClipboardData | null = null;
  private listeners: Set<(data: ClipboardData | null) => void> = new Set();

  private constructor() {
    // Initialize keyboard shortcuts
    this.initializeKeyboardShortcuts();
  }

  /**
   * Get singleton instance
   */
  public static getInstance(): ClipboardManager {
    if (!ClipboardManager.instance) {
      ClipboardManager.instance = new ClipboardManager();
    }
    return ClipboardManager.instance;
  }

  /**
   * Initialize keyboard shortcuts for copy/paste
   * Requirements: 13.1
   */
  private initializeKeyboardShortcuts(): void {
    if (typeof window === 'undefined') return;

    window.addEventListener('keydown', (event: KeyboardEvent) => {
      // Check if we're in an input field
      const target = event.target as HTMLElement;
      if (
        target.tagName === 'INPUT' ||
        target.tagName === 'TEXTAREA' ||
        target.isContentEditable
      ) {
        return;
      }

      const isMac = navigator.platform.toUpperCase().indexOf('MAC') >= 0;
      const ctrlKey = isMac ? event.metaKey : event.ctrlKey;

      // Ctrl+C - Copy
      if (ctrlKey && event.key === 'c' && !event.shiftKey) {
        event.preventDefault();
        this.triggerCopyEvent();
      }

      // Ctrl+X - Cut
      if (ctrlKey && event.key === 'x' && !event.shiftKey) {
        event.preventDefault();
        this.triggerCutEvent();
      }

      // Ctrl+V - Paste
      if (ctrlKey && event.key === 'v' && !event.shiftKey) {
        event.preventDefault();
        this.triggerPasteEvent();
      }
    });
  }

  /**
   * Trigger copy event (to be handled by components)
   */
  private triggerCopyEvent(): void {
    window.dispatchEvent(new CustomEvent('clipboard:copy'));
  }

  /**
   * Trigger cut event (to be handled by components)
   */
  private triggerCutEvent(): void {
    window.dispatchEvent(new CustomEvent('clipboard:cut'));
  }

  /**
   * Trigger paste event (to be handled by components)
   */
  private triggerPasteEvent(): void {
    window.dispatchEvent(new CustomEvent('clipboard:paste'));
  }

  /**
   * Copy shots to clipboard
   * Requirements: 13.1, 13.2
   */
  public copy(shots: Shot[], sourceSequenceId?: string): void {
    if (shots.length === 0) return;

    this.clipboard = {
      shots: shots.map(shot => ({ ...shot })), // Deep copy
      operation: 'copy',
      timestamp: Date.now(),
      sourceSequenceId,
    };

    this.notifyListeners();
  }

  /**
   * Cut shots to clipboard
   * Requirements: 13.1, 13.5
   */
  public cut(shots: Shot[], sourceSequenceId?: string): void {
    if (shots.length === 0) return;

    this.clipboard = {
      shots: shots.map(shot => ({ ...shot })), // Deep copy
      operation: 'cut',
      timestamp: Date.now(),
      sourceSequenceId,
    };

    this.notifyListeners();
  }

  /**
   * Paste shots from clipboard
   * Requirements: 13.2, 13.3, 13.4
   */
  public paste(options: PasteOptions = {}): PasteResult {
    if (!this.clipboard || this.clipboard.shots.length === 0) {
      return {
        success: false,
        pastedShots: [],
        errors: ['Clipboard is empty'],
      };
    }

    const errors: string[] = [];

    // Validate compatibility if requested
    if (options.validateCompatibility && options.targetSequenceId) {
      const compatibilityErrors = this.validateCompatibility(
        this.clipboard.shots,
        options.targetSequenceId
      );
      if (compatibilityErrors.length > 0) {
        return {
          success: false,
          pastedShots: [],
          errors: compatibilityErrors,
        };
      }
    }

    // Create new instances with unique IDs
    const pastedShots = this.clipboard.shots.map((shot, index) => {
      const newShot = this.createShotCopy(shot);
      
      // Set position if specified
      if (options.position !== undefined) {
        newShot.position = options.position + index;
      }

      return newShot;
    });

    return {
      success: true,
      pastedShots,
      errors: errors.length > 0 ? errors : undefined,
    };
  }

  /**
   * Create a copy of a shot with unique ID and updated timestamps
   * Requirements: 13.3, 13.4
   * 
   * Preserves all metadata except:
   * - id: New unique ID generated
   * - Nested IDs (audioTracks, effects, textLayers, animations, keyframes, transitions)
   * 
   * Preserved metadata:
   * - title, description, duration, position
   * - image URL
   * - All audioTrack properties (with new IDs)
   * - All effect properties (with new IDs)
   * - All textLayer properties (with new IDs)
   * - All animation properties (with new IDs)
   * - All transition properties (with new ID)
   * - Custom metadata fields
   */
  private createShotCopy(shot: Shot): Shot {
    const newShot: Shot = {
      ...shot,
      id: generateId(), // Generate unique ID
      // Preserve all metadata except ID and timestamps
      audioTracks: shot.audioTracks.map(track => ({
        ...track,
        id: generateId(), // New ID for audio track
        // Preserve all track properties including effects
        effects: track.effects.map(effect => ({
          ...effect,
          id: generateId(), // New ID for audio effect
          // Preserve automation curves with new keyframe IDs
          automationCurve: effect.automationCurve ? {
            ...effect.automationCurve,
            id: generateId(),
            keyframes: effect.automationCurve.keyframes.map(kf => ({
              ...kf,
              id: generateId(),
            })),
          } : undefined,
        })),
      })),
      effects: shot.effects.map(effect => ({
        ...effect,
        id: generateId(), // New ID for effect
      })),
      textLayers: shot.textLayers.map(layer => ({
        ...layer,
        id: generateId(), // New ID for text layer
      })),
      animations: shot.animations.map(animation => ({
        ...animation,
        id: generateId(), // New ID for animation
        keyframes: animation.keyframes.map(keyframe => ({
          ...keyframe,
          id: generateId(), // New ID for keyframe
        })),
      })),
      transitionOut: shot.transitionOut ? {
        ...shot.transitionOut,
        id: generateId(), // New ID for transition
      } : undefined,
    };

    return newShot;
  }

  /**
   * Validate compatibility with target sequence
   * Requirements: 13.8
   * 
   * Validates:
   * - Shot duration compatibility
   * - Effect support
   * - Audio format compatibility
   * - Text layer compatibility
   * - Animation compatibility
   */
  private validateCompatibility(
    shots: Shot[],
    targetSequenceId: string
  ): string[] {
    const errors: string[] = [];

    for (const shot of shots) {
      // Validate shot duration (example: must be between 0.1 and 60 seconds)
      if (shot.duration < 0.1 || shot.duration > 60) {
        errors.push(`Shot "${shot.title}" has invalid duration: ${shot.duration}s`);
      }

      // Validate audio tracks
      for (const track of shot.audioTracks) {
        // Check if audio format is supported (example validation)
        if (track.url && !this.isSupportedAudioFormat(track.url)) {
          errors.push(`Audio track "${track.name}" has unsupported format`);
        }

        // Validate audio effects
        for (const effect of track.effects) {
          if (!this.isSupportedAudioEffect(effect.type)) {
            errors.push(`Audio effect "${effect.type}" is not supported`);
          }
        }
      }

      // Validate visual effects
      for (const effect of shot.effects) {
        if (!this.isSupportedVisualEffect(effect.type)) {
          errors.push(`Visual effect "${effect.type}" is not supported`);
        }
      }

      // Validate text layers
      for (const layer of shot.textLayers) {
        if (layer.fontSize < 8 || layer.fontSize > 200) {
          errors.push(`Text layer has invalid font size: ${layer.fontSize}px`);
        }
      }

      // Validate animations
      for (const animation of shot.animations) {
        if (animation.keyframes.length < 2) {
          errors.push(`Animation must have at least 2 keyframes`);
        }
      }
    }

    return errors;
  }

  /**
   * Check if audio format is supported
   */
  private isSupportedAudioFormat(url: string): boolean {
    const supportedFormats = ['.mp3', '.wav', '.ogg', '.m4a', '.aac'];
    return supportedFormats.some(format => url.toLowerCase().endsWith(format));
  }

  /**
   * Check if audio effect is supported
   */
  private isSupportedAudioEffect(effectType: string): boolean {
    const supportedEffects = [
      'limiter',
      'eq',
      'compressor',
      'voice-clarity',
      'noise-reduction',
      'reverb',
      'distortion',
      'bass-boost',
      'treble-boost',
      'gain',
    ];
    return supportedEffects.includes(effectType);
  }

  /**
   * Check if visual effect is supported
   */
  private isSupportedVisualEffect(effectType: string): boolean {
    const supportedEffects = ['filter', 'adjustment', 'overlay'];
    return supportedEffects.includes(effectType);
  }

  /**
   * Check if clipboard content can be pasted into target sequence
   * Requirements: 13.6
   */
  public canPasteIntoSequence(targetSequenceId: string): {
    canPaste: boolean;
    errors?: string[];
  } {
    if (!this.clipboard || this.clipboard.shots.length === 0) {
      return {
        canPaste: false,
        errors: ['Clipboard is empty'],
      };
    }

    const errors = this.validateCompatibility(this.clipboard.shots, targetSequenceId);

    return {
      canPaste: errors.length === 0,
      errors: errors.length > 0 ? errors : undefined,
    };
  }

  /**
   * Get source sequence ID of clipboard content
   */
  public getSourceSequenceId(): string | undefined {
    return this.clipboard?.sourceSequenceId;
  }

  /**
   * Check if pasting between different sequences
   */
  public isCrossSequencePaste(targetSequenceId: string): boolean {
    if (!this.clipboard) return false;
    return (
      this.clipboard.sourceSequenceId !== undefined &&
      this.clipboard.sourceSequenceId !== targetSequenceId
    );
  }

  /**
   * Get clipboard content
   */
  public getContent(): ClipboardData | null {
    return this.clipboard;
  }

  /**
   * Get number of shots in clipboard
   */
  public getCount(): number {
    return this.clipboard?.shots.length || 0;
  }

  /**
   * Get clipboard operation type
   */
  public getOperation(): 'copy' | 'cut' | null {
    return this.clipboard?.operation || null;
  }

  /**
   * Clear clipboard
   */
  public clear(): void {
    this.clipboard = null;
    this.notifyListeners();
  }

  /**
   * Subscribe to clipboard changes
   */
  public subscribe(listener: (data: ClipboardData | null) => void): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  /**
   * Notify all listeners of clipboard changes
   */
  private notifyListeners(): void {
    this.listeners.forEach(listener => {
      listener(this.clipboard);
    });
  }

  /**
   * Export clipboard content as JSON
   */
  public exportToJSON(): string | null {
    if (!this.clipboard) return null;
    return JSON.stringify(this.clipboard, null, 2);
  }

  /**
   * Import clipboard content from JSON
   */
  public importFromJSON(json: string): boolean {
    try {
      const data = JSON.parse(json) as ClipboardData;
      if (data.shots && Array.isArray(data.shots)) {
        this.clipboard = data;
        this.notifyListeners();
        return true;
      }
      return false;
    } catch (error) {
      console.error('Failed to import clipboard data:', error);
      return false;
    }
  }
}

// Export singleton instance
export const clipboardManager = ClipboardManager.getInstance();

/**
 * CommentDrivenGenerationService
 * Interprets plain-language comments and generates new visual/video results
 */

// ============================================================================
// Types
// ============================================================================

export type ModificationType =
  | 'visual_adjustment'
  | 'character_change'
  | 'location_change'
  | 'style_transfer'
  | 'lighting_adjustment'
  | 'color_adjustment'
  | 'composition_change'
  | 'regenerate';

export interface ParsedIntent {
  modificationType: ModificationType;
  parameters: Record<string, unknown>;
  targetElements: string[];
  intent: 'improve' | 'change' | 'regenerate' | 'refine';
  confidence: number;
}

export interface GenerationIntent {
  type: ModificationType;
  prompt: string;
  parameters: GenerationParameters;
  referenceIds: string[];
  constraints: string[];
}

export interface GenerationParameters {
  strength?: number;
  preserve?: string[];
  style?: string;
  mood?: string;
  lighting?: string;
  composition?: string;
  colorPalette?: string[];
  aspectRatio?: string;
  duration?: number;
  fps?: number;
}

export interface ShotComment {
  id: string;
  shotId: string;
  content: string;
  parsedIntent: ParsedIntent;
  createdAt: Date;
  resolved: boolean;
  resultShotId?: string;
}

export interface VisualModification {
  type: ModificationType;
  parameters: GenerationParameters;
  preserveConsistency: boolean;
  affectedElements: string[];
}

export interface GenerationResult {
  success: boolean;
  newShotId?: string;
  previewUrl?: string;
  message?: string;
  error?: string;
}

export interface CommentParseResult {
  intent: ParsedIntent;
  originalComment: string;
  suggestions: string[];
}

// ============================================================================
// Project Store Interface (for dependency injection)
// ============================================================================

interface ProjectStore {
  getShot(shotId: string): {
    id: string;
    sequenceId: string;
    generatedImageUrls?: string[];
    referenceImageUrls?: string[];
    prompt?: string;
    styleOverrides?: Record<string, string>;
  } | undefined;
  updateShot(shotId: string, updates: Record<string, unknown>): void;
  addShot(shot: { id: string; sequenceId: string; prompt?: string }): void;
  getAllSequences(): { id: string; shotIds: string[] }[];
  getSequence(sequenceId: string): { id: string; shotIds: string[] } | undefined;
}

interface GenerationService {
  generateFromPrompt(prompt: string, parameters?: Record<string, unknown>): Promise<{ success: boolean; shotId?: string; previewUrl?: string }>;
  applyStyleTransfer(sourceShotId: string, targetShotId: string, intensity: number): Promise<{ success: boolean; newShotId?: string }>;
  modifyShot(shotId: string, modifications: VisualModification): Promise<GenerationResult>;
}

// ============================================================================
// CommentDrivenGenerationService Class
// ============================================================================

export class CommentDrivenGenerationService {
  private projectStore: ProjectStore;
  private generationService: GenerationService;
  private comments: Map<string, ShotComment[]> = new Map();
  private parseCache: Map<string, CommentParseResult> = new Map();

  constructor(projectStore: ProjectStore, generationService: GenerationService) {
    this.projectStore = projectStore;
    this.generationService = generationService;
  }

  // ============================================================================
  // Comment Parsing
  // ============================================================================

  /**
   * Parse plain-language comment into structured intent
   */
  parseComment(comment: string): ParsedIntent {
    const normalizedComment = comment.toLowerCase().trim();
    
    // Check cache first
    if (this.parseCache.has(normalizedComment)) {
      return this.parseCache.get(normalizedComment)!.intent;
    }

    const modificationType = this.extractModificationType(comment);
    const parameters = this.extractParameters(comment);
    const targetElements = this.extractTargetElements(comment);
    const intent = this.classifyIntentType(comment);
    const confidence = this.calculateConfidence(modificationType, intent, targetElements);

    const result: ParsedIntent = {
      modificationType,
      parameters,
      targetElements,
      intent,
      confidence
    };

    // Cache the result
    this.parseCache.set(normalizedComment, {
      intent: result,
      originalComment: comment,
      suggestions: this.generateSuggestions(comment, result)
    });

    return result;
  }

  /**
   * Extract type of modification from comment
   */
  extractModificationType(comment: string): ModificationType {
    const normalizedComment = comment.toLowerCase();

    // Regenerate patterns
    if (/\bregenerate\b|\bredo\b|\brecreate\b|\bstart over\b|\btry again\b/i.test(normalizedComment)) {
      return 'regenerate';
    }

    // Visual adjustment patterns
    if (/\b(sharpen|blur|enhance|improve|adjust|modify|tweak|fine-tune)\b/i.test(normalizedComment)) {
      return 'visual_adjustment';
    }

    // Character change patterns
    if (/\b(character|person|figure|actor|subject|dress|outfit|clothes|hair|face|expression|pose)\b/i.test(normalizedComment)) {
      return 'character_change';
    }

    // Location change patterns
    if (/\b(location|place|setting|scene|environment|background|around|where)\b/i.test(normalizedComment)) {
      return 'location_change';
    }

    // Style transfer patterns
    if (/\b(style|artistic|painting|sketch|watercolor|oil painting|illustrate|art style)\b/i.test(normalizedComment)) {
      return 'style_transfer';
    }

    // Lighting adjustment patterns
    if (/\b(lighting|light|dark|bright|dramatic|soft|shadow|highlight|exposure)\b/i.test(normalizedComment)) {
      return 'lighting_adjustment';
    }

    // Color adjustment patterns
    if (/\b(color|colour|saturation|vibrant|muted|tint|hue|temperature)\b/i.test(normalizedComment)) {
      return 'color_adjustment';
    }

    // Composition change patterns
    if (/\b(composition|angle|view|perspective|close-up|wide|shot framing|crop|center|balance)\b/i.test(normalizedComment)) {
      return 'composition_change';
    }

    return 'visual_adjustment'; // Default to visual adjustment
  }

  /**
   * Extract parameters from comment
   */
  extractParameters(comment: string): Record<string, unknown> {
    const parameters: Record<string, unknown> = {};
    const normalizedComment = comment.toLowerCase();

    // Extract intensity/strength
    const intensityMatch = normalizedComment.match(/\b(more|less|slightly|a bit|a little|very|extremely)\s*(intense|strong|subtle|pronounced)\b/i);
    if (intensityMatch) {
      parameters.intensity = intensityMatch[1].toLowerCase() === 'more' || intensityMatch[1].toLowerCase() === 'very' ? 0.8 : 0.3;
    }

    // Extract style preferences
    const styleMatch = normalizedComment.match(/\b(in the style of|like|similar to)\s+([^\.,]+)/i);
    if (styleMatch) {
      parameters.styleReference = styleMatch[2].trim();
    }

    // Extract lighting type
    if (/\bsoft lighting\b/i.test(normalizedComment)) parameters.lighting = 'soft';
    else if (/\bdrama(tic)? lighting\b/i.test(normalizedComment)) parameters.lighting = 'dramatic';
    else if (/\bnatural lighting\b/i.test(normalizedComment)) parameters.lighting = 'natural';
    else if (/\bneon lighting\b/i.test(normalizedComment)) parameters.lighting = 'neon';
    else if (/\bgolden hour\b/i.test(normalizedComment)) parameters.lighting = 'golden_hour';

    // Extract mood/emotion
    const moodMatch = normalizedComment.match(/\b(mood|feeling|atmosphere)\s+(?:of\s+)?([^\.,]+)/i);
    if (moodMatch) {
      parameters.mood = moodMatch[2].trim();
    }

    // Extract color preferences
    if (/\bwarm(?:er)? tones?\b/i.test(normalizedComment)) parameters.colorTemperature = 'warm';
    if (/\bcool(?:er)? tones?\b/i.test(normalizedComment)) parameters.colorTemperature = 'cool';
    if (/\bvibrant\b/i.test(normalizedComment)) parameters.saturation = 'high';
    if (/\bmuted\b/i.test(normalizedComment)) parameters.saturation = 'low';

    // Extract aspect ratio
    if (/\bportrait\b/i.test(normalizedComment)) parameters.aspectRatio = '9:16';
    else if (/\blandscape\b/i.test(normalizedComment)) parameters.aspectRatio = '16:9';
    else if (/\bsquare\b/i.test(normalizedComment)) parameters.aspectRatio = '1:1';

    // Extract specific character/element references
    const characterMatch = normalizedComment.match(/\b(character|person|man|woman|child)\s+(?:named|called|as|with)\s+([^\.,]+)/i);
    if (characterMatch) {
      parameters.characterDescription = characterMatch[2].trim();
    }

    return parameters;
  }

  /**
   * Extract target elements from comment
   */
  private extractTargetElements(comment: string): string[] {
    const targets: string[] = [];
    const normalizedComment = comment.toLowerCase();

    const elementPatterns: [RegExp, string][] = [
      [/\b(background|backdrop|setting)\b/i, 'background'],
      [/\b(foreground|subject|main focus)\b/i, 'foreground'],
      [/\b(lighting|lights?|shadows?)\b/i, 'lighting'],
      [/\b(colors?|colours?)\b/i, 'colors'],
      [/\b(character|figure|person)\b/i, 'character'],
      [/\b(wardrobe|outfit|clothes|dress)\b/i, 'wardrobe'],
      [/\b(hairst?yle|hair)\b/i, 'hair'],
      [/\b(facial expression|face|expression)\b/i, 'face'],
      [/\b(pose|posture|position)\b/i, 'pose'],
      [/\b(atmosphere|mood|ambience)\b/i, 'atmosphere'],
      [/\b(composition|frame|shot)\b/i, 'composition']
    ];

    for (const [pattern, label] of elementPatterns) {
      if (pattern.test(normalizedComment)) {
        targets.push(label);
      }
    }

    return targets.length > 0 ? targets : ['general'];
  }

  /**
   * Calculate confidence score for parsed intent
   */
  private calculateConfidence(modificationType: ModificationType, intent: string, targetElements: string[]): number {
    let confidence = 0.5;

    // Increase confidence based on specificity
    if (targetElements.length > 0 && targetElements[0] !== 'general') {
      confidence += 0.2;
    }
    if (intent === 'regenerate') {
      confidence += 0.3;
    }
    if (modificationType !== 'visual_adjustment') {
      confidence += 0.15;
    }

    return Math.min(1, Math.max(0, confidence));
  }

  /**
   * Generate suggestions based on parsed comment
   */
  private generateSuggestions(comment: string, intent: ParsedIntent): string[] {
    const suggestions: string[] = [];

    if (intent.modificationType === 'regenerate') {
      suggestions.push('Consider providing more specific details for the new generation');
      suggestions.push('You could include style preferences or mood descriptions');
    } else if (intent.modificationType === 'character_change') {
      suggestions.push('You might want to specify the character\'s appearance more precisely');
    } else if (intent.modificationType === 'style_transfer') {
      suggestions.push('Mentioning a reference style or artist could help');
    }

    return suggestions;
  }

  // ============================================================================
  // Intent Classification
  // ============================================================================

  /**
   * Classify the generation intent
   */
  classifyIntent(comment: string): GenerationIntent {
    const parsedIntent = this.parseComment(comment);
    const modificationType = parsedIntent.modificationType;
    const parameters = parsedIntent.parameters;

    // Build prompt based on parsed intent
    const prompt = this.buildPromptFromIntent(comment, parsedIntent);

    // Set up reference IDs
    const referenceIds: string[] = [];

    // Set up constraints
    const constraints: string[] = [];
    if (parsedIntent.targetElements.length > 0) {
      constraints.push(`preserve: ${parsedIntent.targetElements.filter(e => e !== 'general').join(', ')}`);
    }

    return {
      type: modificationType,
      prompt,
      parameters: this.mapToGenerationParameters(parameters),
      referenceIds,
      constraints
    };
  }

  /**
   * Check if comment asks for regeneration
   */
  isRegenerateRequest(comment: string): boolean {
    const normalizedComment = comment.toLowerCase();
    return /\bregenerate\b|\bredo\b|\brecreate\b|\bstart over\b|\btry again\b/i.test(normalizedComment);
  }

  /**
   * Check if comment asks for modification
   */
  isModificationRequest(comment: string): boolean {
    const normalizedComment = comment.toLowerCase();
    const modifyPatterns = /\b(change|modify|adjust|tweak|improve|enhance|alter|different|instead)\b/i;
    return modifyPatterns.test(normalizedComment) && !this.isRegenerateRequest(normalizedComment);
  }

  /**
   * Classify the intent type from comment
   */
  private classifyIntentType(comment: string): 'improve' | 'change' | 'regenerate' | 'refine' {
    const normalizedComment = comment.toLowerCase();

    if (this.isRegenerateRequest(normalizedComment)) {
      return 'regenerate';
    }

    if (/\b(improve|better|enhance|perfect|refine|polish)\b/i.test(normalizedComment)) {
      return 'improve';
    }

    if (/\b(change|different|modify|alter|switch)\b/i.test(normalizedComment)) {
      return 'change';
    }

    return 'refine';
  }

  /**
   * Build prompt from parsed intent
   */
  private buildPromptFromIntent(comment: string, intent: ParsedIntent): string {
    const parts: string[] = [];

    // Add modification context based on type
    switch (intent.modificationType) {
      case 'character_change':
        parts.push('Modified character appearance');
        break;
      case 'location_change':
        parts.push('Changed scene location');
        break;
      case 'style_transfer':
        parts.push('Applied new artistic style');
        break;
      case 'lighting_adjustment':
        parts.push('Adjusted lighting');
        break;
      case 'color_adjustment':
        parts.push('Modified color palette');
        break;
      case 'composition_change':
        parts.push('Changed composition');
        break;
      case 'regenerate':
        return comment; // Use original comment for regeneration
      default:
        parts.push('Visual adjustment');
    }

    // Add original comment context if provided
    if (comment && !this.isRegenerateRequest(comment)) {
      parts.push(`Original request: ${comment}`);
    }

    // Add parameters
    if (intent.parameters.styleReference) {
      parts.push(`Style reference: ${intent.parameters.styleReference}`);
    }
    if (intent.parameters.mood) {
      parts.push(`Mood: ${intent.parameters.mood}`);
    }

    return parts.join('. ');
  }

  /**
   * Map extracted parameters to GenerationParameters
   */
  private mapToGenerationParameters(params: Record<string, unknown>): GenerationParameters {
    return {
      strength: typeof params.intensity === 'number' ? params.intensity : 0.7,
      style: params.styleReference as string,
      mood: params.mood as string,
      lighting: params.lighting as string,
      colorPalette: params.colorPalette as string[],
      aspectRatio: params.aspectRatio as string
    };
  }

  // ============================================================================
  // Generation Execution
  // ============================================================================

  /**
   * Execute generation based on comment
   */
  async executeGeneration(shotId: string, comment: string, intent?: GenerationIntent): Promise<GenerationResult> {
    try {
      const generationIntent = intent || this.classifyIntent(comment);
      const parsedIntent = this.parseComment(comment);

      // Get original shot
      const originalShot = this.projectStore.getShot(shotId);
      if (!originalShot) {
        return {
          success: false,
          message: 'Shot not found',
          error: 'Shot not found in project store'
        };
      }

      // Handle regeneration
      if (generationIntent.type === 'regenerate' || parsedIntent.intent === 'regenerate') {
        return await this.handleRegeneration(shotId, comment, originalShot);
      }

      // Handle modifications
      const modification: VisualModification = {
        type: generationIntent.type,
        parameters: generationIntent.parameters,
        preserveConsistency: true,
        affectedElements: parsedIntent.targetElements
      };

      return await this.applyModification(shotId, modification);
    } catch (error) {
      return {
        success: false,
        message: 'Generation failed',
        error: error instanceof Error ? error.message : String(error)
      };
    }
  }

  /**
   * Handle regeneration request
   */
  private async handleRegeneration(
    shotId: string,
    comment: string,
    originalShot: { id: string; sequenceId: string; prompt?: string }
  ): Promise<GenerationResult> {
    // Build regeneration prompt
    const basePrompt = originalShot.prompt || '';
    const modifiedPrompt = comment.replace(/\b(regenerate|redo|recreate)\b/gi, '').trim();
    const finalPrompt = modifiedPrompt ? `${basePrompt}, ${modifiedPrompt}` : basePrompt;

    // Call generation service
    const result = await this.generationService.generateFromPrompt(finalPrompt, {
      preserveStyle: true,
      preserveCharacters: true
    });

    if (result.success && result.shotId) {
      // Add new shot to store
      this.projectStore.addShot({
        id: result.shotId,
        sequenceId: originalShot.sequenceId,
        prompt: finalPrompt
      });

      return {
        success: true,
        newShotId: result.shotId,
        previewUrl: result.previewUrl,
        message: 'Successfully regenerated shot'
      };
    }

    return {
      success: false,
      message: 'Regeneration failed',
      error: 'Generation service returned failure'
    };
  }

  /**
   * Generate multiple variations based on comment
   */
  async generateVariations(shotId: string, comment: string): Promise<string[]> {
    const variations: string[] = [];
    const baseIntent = this.classifyIntent(comment);

    // Generate variations with different parameter strengths
    const strengths = [0.3, 0.5, 0.7, 0.9];

    for (const strength of strengths) {
      const modifiedParams = {
        ...baseIntent.parameters,
        strength
      };

      const result = await this.generationService.generateFromPrompt(baseIntent.prompt, modifiedParams);
      if (result.success && result.shotId) {
        variations.push(result.shotId);
      }
    }

    return variations;
  }

  /**
   * Apply specific modification to shot
   */
  async applyModification(shotId: string, modification: VisualModification): Promise<GenerationResult> {
    try {
      // Get the shot to modify
      const shot = this.projectStore.getShot(shotId);
      if (!shot) {
        return {
          success: false,
          message: 'Shot not found',
          error: 'Cannot modify non-existent shot'
        };
      }

      // Apply modification based on type
      switch (modification.type) {
        case 'style_transfer':
          return await this.applyStyleTransferModification(shotId, modification);
        case 'character_change':
          return await this.applyCharacterModification(shotId, modification);
        case 'lighting_adjustment':
          return await this.applyLightingModification(shotId, modification);
        case 'color_adjustment':
          return await this.applyColorModification(shotId, modification);
        case 'composition_change':
          return await this.applyCompositionModification(shotId, modification);
        default:
          return await this.applyVisualAdjustment(shotId, modification);
      }
    } catch (error) {
      return {
        success: false,
        message: 'Modification failed',
        error: error instanceof Error ? error.message : String(error)
      };
    }
  }

  /**
   * Apply style transfer modification
   */
  private async applyStyleTransferModification(shotId: string, modification: VisualModification): Promise<GenerationResult> {
    const result = await this.generationService.applyStyleTransfer(shotId, shotId, 0.7);
    if (result.success && result.newShotId) {
      return {
        success: true,
        newShotId: result.newShotId,
        message: 'Style transfer applied successfully'
      };
    }
    return { success: false, message: 'Style transfer failed' };
  }

  /**
   * Apply character modification
   */
  private async applyCharacterModification(shotId: string, modification: VisualModification): Promise<GenerationResult> {
    const result = await this.generationService.modifyShot(shotId, modification);
    return result;
  }

  /**
   * Apply lighting modification
   */
  private async applyLightingModification(shotId: string, modification: VisualModification): Promise<GenerationResult> {
    const result = await this.generationService.modifyShot(shotId, modification);
    return result;
  }

  /**
   * Apply color modification
   */
  private async applyColorModification(shotId: string, modification: VisualModification): Promise<GenerationResult> {
    const result = await this.generationService.modifyShot(shotId, modification);
    return result;
  }

  /**
   * Apply composition modification
   */
  private async applyCompositionModification(shotId: string, modification: VisualModification): Promise<GenerationResult> {
    const result = await this.generationService.modifyShot(shotId, modification);
    return result;
  }

  /**
   * Apply general visual adjustment
   */
  private async applyVisualAdjustment(shotId: string, modification: VisualModification): Promise<GenerationResult> {
    const result = await this.generationService.modifyShot(shotId, modification);
    return result;
  }

  // ============================================================================
  // Comment Management
  // ============================================================================

  /**
   * Add comment to shot
   */
  addComment(shotId: string, comment: string): string {
    const commentId = `comment_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    const parsedIntent = this.parseComment(comment);

    const newComment: ShotComment = {
      id: commentId,
      shotId,
      content: comment,
      parsedIntent,
      createdAt: new Date(),
      resolved: false
    };

    // Get existing comments for this shot
    const existingComments = this.comments.get(shotId) || [];
    existingComments.push(newComment);
    this.comments.set(shotId, existingComments);

    return commentId;
  }

  /**
   * Get all comments for a shot
   */
  getComments(shotId: string): ShotComment[] {
    return this.comments.get(shotId) || [];
  }

  /**
   * Mark comment as resolved
   */
  resolveComment(commentId: string): void {
    for (const [shotId, comments] of this.comments.entries()) {
      const commentIndex = comments.findIndex(c => c.id === commentId);
      if (commentIndex !== -1) {
        comments[commentIndex].resolved = true;
        this.comments.set(shotId, comments);
        return;
      }
    }
  }

  /**
   * Get unresolved comments for a shot
   */
  getUnresolvedComments(shotId: string): ShotComment[] {
    return this.getComments(shotId).filter(c => !c.resolved);
  }

  /**
   * Get comment by ID
   */
  getCommentById(commentId: string): ShotComment | undefined {
    for (const comments of this.comments.values()) {
      const found = comments.find(c => c.id === commentId);
      if (found) return found;
    }
    return undefined;
  }

  /**
   * Link result shot to comment
   */
  linkResultToComment(commentId: string, resultShotId: string): void {
    const comment = this.getCommentById(commentId);
    if (comment) {
      comment.resultShotId = resultShotId;
      comment.resolved = true;
    }
  }

  /**
   * Clear all comments for a shot
   */
  clearComments(shotId: string): void {
    this.comments.delete(shotId);
  }

  /**
   * Get cache statistics
   */
  getCacheStats(): { size: number; hits: number; misses: number } {
    return {
      size: this.parseCache.size,
      hits: 0,
      misses: 0
    };
  }

  /**
   * Clear parse cache
   */
  clearCache(): void {
    this.parseCache.clear();
  }
}

