/**
 * Installation API Service
 * 
 * Handles communication with backend for ComfyUI installation wizard
 * Provides WebSocket support for real-time progress updates
 */

import type {
  InitializeResponse,
  FileCheckResponse,
  InstallRequest,
  ProgressUpdate,
  VerificationResponse,
} from '@/types/installation';

/**
 * Installation API configuration
 */
export interface InstallationApiConfig {
  baseUrl: string;
  timeout: number;
  wsUrl: string;
}

/**
 * Default configuration
 */
const DEFAULT_CONFIG: InstallationApiConfig = {
  baseUrl: import.meta.env.VITE_BACKEND_URL || 'http://localhost:5000',
  timeout: 300000, // 5 minutes for installation
  wsUrl: import.meta.env.VITE_WS_URL || 'ws://localhost:5000',
};

/**
 * API response wrapper
 */
export interface ApiResponse<T = any> {
  success: boolean;
  data?: T;
  error?: string;
}

/**
 * Installation API Service Class
 */
export class InstallationApiService {
  private config: InstallationApiConfig;
  private ws: WebSocket | null = null;

  constructor(config?: Partial<InstallationApiConfig>) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Initialize installation wizard
   * Creates download zone and returns configuration
   */
  async initialize(): Promise<ApiResponse<InitializeResponse>> {
    try {
      const response = await this.fetchWithTimeout('/api/installation/initialize', {
        method: 'POST',
      });

      if (!response.ok) {
        const error = await response.json();
        return {
          success: false,
          error: error.message || 'Failed to initialize installation',
        };
      }

      const data = await response.json();
      return {
        success: true,
        data,
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  /**
   * Check if ZIP file exists and is valid
   */
  async checkFile(path: string): Promise<ApiResponse<FileCheckResponse>> {
    try {
      const response = await this.fetchWithTimeout(
        `/api/installation/check-file?path=${encodeURIComponent(path)}`
      );

      if (!response.ok) {
        const error = await response.json();
        return {
          success: false,
          error: error.message || 'Failed to check file',
        };
      }

      const data = await response.json();
      return {
        success: true,
        data,
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  /**
   * Start installation with WebSocket progress updates
   */
  async install(
    request: InstallRequest,
    onProgress: (update: ProgressUpdate) => void,
    onError?: (error: Error) => void
  ): Promise<() => void> {
    // Close existing WebSocket if any
    if (this.ws) {
      this.ws.close();
    }

    // Create WebSocket connection
    const wsUrl = `${this.config.wsUrl}/api/installation/install`;
    this.ws = new WebSocket(wsUrl);

    this.ws.onopen = () => {
      // Send installation request
      this.ws?.send(JSON.stringify(request));
    };

    this.ws.onmessage = (event) => {
      try {
        const update: ProgressUpdate = JSON.parse(event.data);
        onProgress(update);

        // Close connection when installation completes or fails
        if (update.error || update.progress >= 100) {
          this.ws?.close();
        }
      } catch (error) {
        onError?.(
          error instanceof Error ? error : new Error('Failed to parse progress update')
        );
      }
    };

    this.ws.onerror = (_event) => {
      onError?.(new Error('WebSocket connection failed'));
      this.ws?.close();
    };

    this.ws.onclose = () => {
      this.ws = null;
    };

    // Return cleanup function
    return () => {
      if (this.ws) {
        this.ws.close();
        this.ws = null;
      }
    };
  }

  /**
   * Verify installation and CORS configuration
   */
  async verify(): Promise<ApiResponse<VerificationResponse>> {
    try {
      const response = await this.fetchWithTimeout('/api/installation/verify');

      if (!response.ok) {
        const error = await response.json();
        return {
          success: false,
          error: error.message || 'Failed to verify installation',
        };
      }

      const data = await response.json();
      return {
        success: true,
        data,
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  /**
   * Fetch with timeout
   */
  private async fetchWithTimeout(
    url: string,
    options?: RequestInit
  ): Promise<Response> {
    const fullUrl = `${this.config.baseUrl}${url}`;
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), this.config.timeout);

    try {
      const response = await fetch(fullUrl, {
        ...options,
        signal: controller.signal,
      });

      clearTimeout(timeoutId);
      return response;
    } catch (error) {
      clearTimeout(timeoutId);
      if (error instanceof Error && error.name === 'AbortError') {
        throw new Error('Request timeout');
      }
      throw error;
    }
  }

  /**
   * Update configuration
   */
  updateConfig(config: Partial<InstallationApiConfig>): void {
    this.config = { ...this.config, ...config };
  }

  /**
   * Get current configuration
   */
  getConfig(): InstallationApiConfig {
    return { ...this.config };
  }

  /**
   * Close WebSocket connection
   */
  disconnect(): void {
    if (this.ws) {
      this.ws.close();
      this.ws = null;
    }
  }
}

/**
 * Default installation API service instance
 */
export const installationApi = new InstallationApiService();

/**
 * Mock installation API service for development/testing
 */
export class MockInstallationApiService extends InstallationApiService {
  private mockDelayMs: number = 1000;

  async initialize(): Promise<ApiResponse<InitializeResponse>> {
    await this.wait(this.mockDelayMs);

    return {
      success: true,
      data: {
        downloadZonePath: 'C:\\Users\\User\\Downloads\\comfyui_download_zone',
        downloadUrl: 'https://github.com/comfyanonymous/ComfyUI/releases/download/latest/ComfyUI_windows_portable_nvidia.7z',
        expectedFileName: 'ComfyUI_windows_portable_nvidia.7z',
        expectedFileSize: 2500000000,
      },
    };
  }

  async checkFile(_path: string): Promise<ApiResponse<FileCheckResponse>> {
    await this.wait(this.mockDelayMs / 2);

    // Simulate random file detection
    const exists = Math.random() > 0.5;
    const valid = exists && Math.random() > 0.3;

    return {
      success: true,
      data: {
        exists,
        valid,
        fileName: exists ? 'ComfyUI_windows_portable_nvidia.7z' : null,
        fileSize: exists ? 2500000000 : null,
        validationError: !valid && exists ? 'File size mismatch' : null,
      },
    };
  }

  async install(
    _request: InstallRequest,
    onProgress: (update: ProgressUpdate) => void,
    _onError?: (error: Error) => void
  ): Promise<() => void> {
    // Simulate installation progress
    let progress = 0;
    const steps = [
      'Extracting ComfyUI Portable...',
      'Configuring CORS settings...',
      'Downloading models...',
      'Installing workflows...',
      'Verifying installation...',
      'Installation complete!',
    ];

    const interval = setInterval(() => {
      if (progress >= 100) {
        clearInterval(interval);
        return;
      }

      progress += 20;
      const stepIndex = Math.floor((progress / 100) * steps.length);
      const step = steps[Math.min(stepIndex, steps.length - 1)];

      onProgress({
        step,
        progress: Math.min(progress, 100),
        message: step,
        error: null,
      });
    }, this.mockDelayMs);

    return () => {
      clearInterval(interval);
    };
  }

  async verify(): Promise<ApiResponse<VerificationResponse>> {
    await this.wait(this.mockDelayMs);

    return {
      success: true,
      data: {
        installed: true,
        running: true,
        corsEnabled: true,
        url: 'http://localhost:8000', // ComfyUI Desktop default
        models: ['sd_xl_base_1.0.safetensors', 'sd_xl_refiner_1.0.safetensors'],
        workflows: ['text2img.json', 'img2img.json'],
        errors: [],
      },
    };
  }

  private wait(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  setMockDelay(ms: number): void {
    this.mockDelayMs = ms;
  }
}

/**
 * Create installation API service based on environment
 */
export function createInstallationApi(useMock: boolean = false): InstallationApiService {
  if (useMock || import.meta.env.MODE === 'test') {
    return new MockInstallationApiService();
  }
  return new InstallationApiService();
}

/**
 * Multi-Model Manager Service
 * 
 * Manages multiple Ollama models, handles model selection,
 * fallback chains, and availability checking.
 */

import { OllamaClient, type ModelMetadata } from './OllamaClient';
import { logger } from '@/utils/logger';

export interface LLMConfig {
  provider: 'local' | 'openai' | 'anthropic' | 'custom';
  model: string;
  apiEndpoint?: string;
  availableModels?: {
    vision: string[];
    storytelling: string[];
    quick: string[];
    default: string;
  };
}

export type TaskType = 'vision' | 'storytelling' | 'quick' | 'general';

/**
 * Multi-Model Manager
 */
export class MultiModelManager {
  private config: LLMConfig;
  private ollamaClient: OllamaClient;
  private availableModels: Map<string, ModelMetadata>;
  private modelCache: Map<string, boolean>;

  constructor(config: LLMConfig) {
    this.config = config;
    this.ollamaClient = new OllamaClient(config.apiEndpoint || 'http://localhost:11434');
    this.availableModels = new Map();
    this.modelCache = new Map();
  }

  /**
   * Detect available models from Ollama
   */
  async detectAvailableModels(): Promise<ModelMetadata[]> {
    try {
      const models = await this.ollamaClient.listModels();
      
      // Update available models map
      this.availableModels.clear();
      models.forEach(model => {
        this.availableModels.set(model.name, model);
        this.modelCache.set(model.name, true);
      });

      logger.debug(`[MultiModelManager] Detected ${models.length} models`);
      return models;
    } catch (error) {
      logger.error('[MultiModelManager] Failed to detect models:', error);
      return [];
    }
  }

  /**
   * Get model for specific task type (manual selection for MVP)
   */
  getModelForTask(taskType: TaskType): string {
    const models = this.config.availableModels;
    
    if (!models) {
      return this.config.model;
    }

    // Get models for this task type
    let taskModels: string[] = [];
    
    switch (taskType) {
      case 'vision':
        taskModels = models.vision || [];
        break;
      case 'storytelling':
        taskModels = models.storytelling || [];
        break;
      case 'quick':
        taskModels = models.quick || [];
        break;
      default:
        return models.default || this.config.model;
    }

    // Find first available model
    for (const model of taskModels) {
      if (this.isModelAvailable(model)) {
        return model;
      }
    }

    // Fallback to default
    return models.default || this.config.model;
  }

  /**
   * Check if a specific model is available
   */
  isModelAvailable(modelName: string): boolean {
    // Check cache first
    if (this.modelCache.has(modelName)) {
      return this.modelCache.get(modelName)!;
    }

    // Check in available models map
    return this.availableModels.has(modelName);
  }

  /**
   * Get fallback chain for a model
   * Returns array of models to try in order
   */
  getFallbackChain(preferredModel: string): string[] {
    const chain: string[] = [preferredModel];
    
    // Determine task type from model name
    const metadata = this.availableModels.get(preferredModel);
    const taskType = metadata?.category || 'general';

    // Add alternatives from same category
    const models = this.config.availableModels;
    if (models) {
      let alternatives: string[] = [];
      
      switch (taskType) {
        case 'vision':
          alternatives = models.vision || [];
          break;
        case 'storytelling':
          alternatives = models.storytelling || [];
          break;
        case 'quick':
          alternatives = models.quick || [];
          break;
      }

      // Add available alternatives
      alternatives.forEach(model => {
        if (model !== preferredModel && this.isModelAvailable(model)) {
          chain.push(model);
        }
      });

      // Add default as final fallback
      if (models.default && !chain.includes(models.default)) {
        chain.push(models.default);
      }
    }

    return chain;
  }

  /**
   * Get model metadata
   */
  getModelMetadata(modelName: string): ModelMetadata | undefined {
    return this.availableModels.get(modelName);
  }

  /**
   * Get all available models by category
   */
  getModelsByCategory(category: ModelMetadata['category']): ModelMetadata[] {
    return Array.from(this.availableModels.values())
      .filter(model => model.category === category);
  }

  /**
   * Update configuration
   */
  updateConfig(config: Partial<LLMConfig>): void {
    this.config = { ...this.config, ...config };
    
    if (config.apiEndpoint) {
      this.ollamaClient = new OllamaClient(config.apiEndpoint);
    }
  }

  /**
   * Get current configuration
   */
  getConfig(): LLMConfig {
    return { ...this.config };
  }

  /**
   * Check Ollama health
   */
  async checkHealth(): Promise<boolean> {
    return await this.ollamaClient.healthCheck();
  }

  /**
   * Get model usage statistics (placeholder for future implementation)
   */
  getModelStats(modelName: string): {
    usageCount: number;
    lastUsed?: Date;
    averageLatency?: number;
  } {
    // TODO: Implement usage tracking
    return {
      usageCount: 0,
      lastUsed: undefined,
      averageLatency: undefined,
    };
  }

  /**
   * Refresh model cache
   */
  async refreshCache(): Promise<void> {
    this.modelCache.clear();
    await this.detectAvailableModels();
  }

  /**
   * Get recommended model for task
   */
  getRecommendedModel(taskType: TaskType): {
    model: string;
    reason: string;
    alternatives: string[];
  } {
    const model = this.getModelForTask(taskType);
    const metadata = this.getModelMetadata(model);
    const fallbackChain = this.getFallbackChain(model);

    return {
      model,
      reason: metadata 
        ? `Recommended for ${taskType}: ${metadata.recommendedFor.join(', ')}`
        : `Default model for ${taskType} tasks`,
      alternatives: fallbackChain.slice(1),
    };
  }
}

/**
 * PipelineAwareLLM ÔÇö Context-aware LLM service for StoryCore Assistant
 *
 * This service bridges the generation pipeline state with the LLM assistant,
 * enabling the assistant to provide context-aware suggestions, trigger
 * re-generation, and guide the user through the creative workflow.
 *
 * @module PipelineAwareLLM
 */

import { useGenerationStore } from '../../stores/generationStore';
import { useAppStore } from '../../stores/useAppStore';
import { useEditorStore } from '../../stores/editorStore';
import type { GenerationPipelineState, GeneratedAsset } from '../../types/generation';

// =============================================================================
// Types
// =============================================================================

export type GenerationAssetType = 'prompt' | 'image' | 'video' | 'audio';

export interface PipelineStatus {
    isActive: boolean;
    currentStage: GenerationAssetType | null;
    completedStages: GenerationAssetType[];
    failedStages: GenerationAssetType[];
    pendingStages: GenerationAssetType[];
    overallProgress: number; // 0-100
    queueLength: number;
    activeBatchCount: number;
}

export interface ProjectCompletionStatus {
    hasCharacters: boolean;
    hasShots: boolean;
    hasSequences: boolean;
    hasGeneratedImages: boolean;
    hasGeneratedVideos: boolean;
    hasGeneratedAudio: boolean;
    hasExportedFilm: boolean;
    completionPercentage: number;
    missingSteps: string[];
    nextAction: ContextualSuggestion | null;
}

export interface ContextualSuggestion {
    id: string;
    type: 'generate' | 'regenerate' | 'wizard' | 'export' | 'review';
    title: string;
    description: string;
    priority: 'critical' | 'high' | 'medium' | 'low';
    assetType?: GenerationAssetType;
    targetId?: string; // shot ID, character ID, etc.
    actionLabel: string;
}

export interface RegenerationRequest {
    type: GenerationAssetType;
    targetId: string;
    targetName: string;
    reason?: string;
    style?: string;
}

// =============================================================================
// PipelineAwareLLM Service
// =============================================================================

export class PipelineAwareLLM {
    /**
     * Get the current pipeline status from the generation store
     */
    static getPipelineStatus(): PipelineStatus {
        const store = useGenerationStore.getState();
        const pipeline = store.currentPipeline;

        if (!pipeline) {
            return {
                isActive: false,
                currentStage: null,
                completedStages: [],
                failedStages: [],
                pendingStages: ['prompt', 'image', 'video', 'audio'],
                overallProgress: 0,
                queueLength: store.queue.tasks.length,
                activeBatchCount: store.activeBatch ? 1 : 0,
            };
        }

        const stages: GenerationAssetType[] = ['prompt', 'image', 'video', 'audio'];
        const completedStages: GenerationAssetType[] = [];
        const failedStages: GenerationAssetType[] = [];
        const pendingStages: GenerationAssetType[] = [];
        let currentStage: GenerationAssetType | null = null;

        for (const stage of stages) {
            const stageState = pipeline.stages[stage];
            if (!stageState) {
                pendingStages.push(stage);
                continue;
            }
            switch (stageState.status) {
                case 'completed':
                    completedStages.push(stage);
                    break;
                case 'in_progress':
                    currentStage = stage;
                    break;
                case 'failed':
                    failedStages.push(stage);
                    break;
                default:
                    pendingStages.push(stage);
            }
        }

        const totalStages = stages.length;
        const overallProgress = Math.round(
            ((completedStages.length + (currentStage ? 0.5 : 0)) / totalStages) * 100
        );

        return {
            isActive: currentStage !== null,
            currentStage,
            completedStages,
            failedStages,
            pendingStages,
            overallProgress,
            queueLength: store.queue.tasks.length,
            activeBatchCount: store.activeBatch ? 1 : 0,
        };
    }

    /**
     * Analyze the project and return completion status with smart suggestions
     */
    static getProjectCompletionStatus(): ProjectCompletionStatus {
        const appState = useAppStore.getState();
        const genState = useGenerationStore.getState();
        const project = appState.project;

        const hasCharacters = Boolean(project?.characters && project.characters.length > 0);
        const hasShots = Boolean(project?.shots && project.shots.length > 0);
        const hasSequences = Boolean(project?.sequences && project.sequences.length > 0);

        // Check pipeline asset graph for generated content
        const assets = Array.from(genState.assetGraph.nodes.values());
        const hasGeneratedImages = assets.some((a) => a.type === 'image');
        const hasGeneratedVideos = assets.some((a) => a.type === 'video');
        const hasGeneratedAudio = assets.some((a) => a.type === 'audio');
        const hasExportedFilm = false; // TODO: connect to export state

        const missingSteps: string[] = [];
        if (!hasCharacters) missingSteps.push('Cr├®er des personnages');
        if (!hasShots) missingSteps.push('Planifier les shots');
        if (!hasSequences) missingSteps.push('Organiser les s├®quences');
        if (!hasGeneratedImages) missingSteps.push('G├®n├®rer les images des shots');
        if (!hasGeneratedVideos) missingSteps.push('G├®n├®rer les vid├®os');
        if (!hasGeneratedAudio) missingSteps.push('G├®n├®rer l\'audio et les voix');
        if (!hasExportedFilm) missingSteps.push('Exporter le film final');

        const totalSteps = 7;
        const completedSteps = totalSteps - missingSteps.length;
        const completionPercentage = Math.round((completedSteps / totalSteps) * 100);

        // Determine the next logical action
        let nextAction: ContextualSuggestion | null = null;
        if (!hasCharacters) {
            nextAction = {
                id: 'create-characters',
                type: 'wizard',
                title: '­ƒæñ Cr├®er des personnages',
                description: 'Commencez par d├®finir vos personnages pour donner vie ├á votre histoire',
                priority: 'critical',
                actionLabel: 'Lancer le Wizard Personnages',
            };
        } else if (!hasShots) {
            nextAction = {
                id: 'plan-shots',
                type: 'wizard',
                title: '­ƒÄÑ Planifier les shots',
                description: 'Transformez votre histoire en plans cin├®matiques',
                priority: 'critical',
                actionLabel: 'Lancer le Wizard Shots',
            };
        } else if (!hasGeneratedImages) {
            nextAction = {
                id: 'generate-images',
                type: 'generate',
                title: '­ƒû╝´©Å G├®n├®rer les images',
                description: `${project?.shots?.length || 0} shots en attente de g├®n├®ration d'images`,
                priority: 'high',
                assetType: 'image',
                actionLabel: 'G├®n├®rer les images',
            };
        } else if (!hasGeneratedAudio) {
            nextAction = {
                id: 'generate-audio',
                type: 'generate',
                title: '­ƒöè G├®n├®rer l\'audio',
                description: 'Ajoutez les voix et effets sonores ├á vos shots',
                priority: 'high',
                assetType: 'audio',
                actionLabel: 'G├®n├®rer l\'audio',
            };
        } else if (!hasGeneratedVideos) {
            nextAction = {
                id: 'generate-videos',
                type: 'generate',
                title: '­ƒÄ¼ G├®n├®rer les vid├®os',
                description: 'Animez vos images en vid├®os pour chaque shot',
                priority: 'high',
                assetType: 'video',
                actionLabel: 'G├®n├®rer les vid├®os',
            };
        } else if (!hasExportedFilm) {
            nextAction = {
                id: 'export-film',
                type: 'export',
                title: '­ƒÄ×´©Å Exporter le film',
                description: 'Assemblez le tout en un film final',
                priority: 'high',
                actionLabel: 'Exporter le film',
            };
        }

        return {
            hasCharacters,
            hasShots,
            hasSequences,
            hasGeneratedImages,
            hasGeneratedVideos,
            hasGeneratedAudio,
            hasExportedFilm,
            completionPercentage,
            missingSteps,
            nextAction,
        };
    }

    /**
     * Generate contextual suggestions based on current state
     */
    static getContextualSuggestions(): ContextualSuggestion[] {
        const pipelineStatus = this.getPipelineStatus();
        const projectStatus = this.getProjectCompletionStatus();
        const suggestions: ContextualSuggestion[] = [];

        // Failed stages ÔåÆ suggest retry
        for (const stage of pipelineStatus.failedStages) {
            suggestions.push({
                id: `retry-${stage}`,
                type: 'regenerate',
                title: `­ƒöä Relancer ${this.stageLabel(stage)}`,
                description: `La g├®n├®ration ${this.stageLabel(stage)} a ├®chou├®. Voulez-vous r├®essayer ?`,
                priority: 'critical',
                assetType: stage,
                actionLabel: 'R├®g├®n├®rer',
            });
        }

        // Completed stages ÔåÆ suggest next step
        if (
            pipelineStatus.completedStages.includes('prompt') &&
            !pipelineStatus.completedStages.includes('image')
        ) {
            suggestions.push({
                id: 'prompt-to-image',
                type: 'generate',
                title: '­ƒû╝´©Å Prompts pr├¬ts ÔåÆ G├®n├®rer les images',
                description: 'Vos prompts sont g├®n├®r├®s, passez ├á la g├®n├®ration d\'images',
                priority: 'high',
                assetType: 'image',
                actionLabel: 'G├®n├®rer les images',
            });
        }

        if (
            pipelineStatus.completedStages.includes('image') &&
            !pipelineStatus.completedStages.includes('video')
        ) {
            suggestions.push({
                id: 'image-to-video',
                type: 'generate',
                title: '­ƒÄ¼ Images pr├¬tes ÔåÆ G├®n├®rer les vid├®os',
                description: 'Vos images sont g├®n├®r├®es, passez ├á l\'animation vid├®o',
                priority: 'high',
                assetType: 'video',
                actionLabel: 'G├®n├®rer les vid├®os',
            });
        }

        if (
            pipelineStatus.completedStages.includes('video') &&
            !pipelineStatus.completedStages.includes('audio')
        ) {
            suggestions.push({
                id: 'video-to-audio',
                type: 'generate',
                title: '­ƒöè Vid├®os pr├¬tes ÔåÆ Ajouter l\'audio',
                description: 'Ajoutez les voix, musique et effets sonores',
                priority: 'high',
                assetType: 'audio',
                actionLabel: 'G├®n├®rer l\'audio',
            });
        }

        // All stages complete ÔåÆ suggest export
        const allComplete = ['prompt', 'image', 'video', 'audio'].every((s) =>
            pipelineStatus.completedStages.includes(s as GenerationAssetType)
        );
        if (allComplete) {
            suggestions.push({
                id: 'export-film',
                type: 'export',
                title: '­ƒÄ×´©Å Tout est pr├¬t ÔåÆ Exporter le film !',
                description: 'Toutes les ├®tapes sont termin├®es. Assemblez votre film final.',
                priority: 'critical',
                actionLabel: 'Exporter le film',
            });
        }

        // Next action from project completion
        if (projectStatus.nextAction && suggestions.length === 0) {
            suggestions.push(projectStatus.nextAction);
        }

        return suggestions;
    }

    /**
     * Build a context-aware system prompt for the LLM
     */
    static buildContextualSystemPrompt(): string {
        const appState = useAppStore.getState();
        const project = appState.project;
        const pipelineStatus = this.getPipelineStatus();
        const projectStatus = this.getProjectCompletionStatus();

        let prompt = `Tu es l'Assistant StoryCore, un expert IA en narration cin├®matique, design de personnages, et production vid├®o.
Tu aides les utilisateurs ├á cr├®er des films et vid├®os avec le syst├¿me StoryCore-Engine.

CONTEXTE DU PROJET:
- Nom: "${project?.project_name || 'Sans titre'}"
- Compl├®tion: ${projectStatus.completionPercentage}%
- Personnages: ${project?.characters?.length || 0}
