import type { StorageBackend } from './projectPersistence';
import type { Project } from '../../types';

/**
 * RoverBackend implementation of StorageBackend
 * Bridges the UI persistence to the Electron Rover Service
 */
export class RoverBackend implements StorageBackend {
    private projectPath: string;

    constructor(projectPath: string) {
        this.projectPath = projectPath;
    }

    /**
     * Save project data and create a Rover checkpoint
     */
    async save(key: string, data: string): Promise<void> {
        try {
            const parsedData = JSON.parse(data) as Project;
            const projectId = parsedData.id || (parsedData as any).project_id;

            // Use Rover API if available
            if (window.electronAPI?.rover?.sync) {
                await window.electronAPI.rover.sync(
                    this.projectPath,
                    projectId,
                    'Auto-save checkpoint',
                    parsedData as unknown as Record<string, unknown>
                );
            } else {
                console.warn('[RoverBackend] Rover API sync not available, using basic FS');
            }

            // Always write the main project.json for compatibility with the rest of the app
            if (window.electronAPI?.fs?.writeFile) {
                await window.electronAPI.fs.writeFile(pathJoin(this.projectPath, 'project.json'), data);
            } else {
                console.error('[RoverBackend] FS API not available for save');
                throw new Error('No persistence available');
            }
        } catch (error) {
            console.error('[RoverBackend] Save failed:', error);
            throw error;
        }
    }

    /**
     * Load project data
     */
    async load(key: string): Promise<string | null> {
        if (!window.electronAPI?.fs?.readFile) {
            console.error('[RoverBackend] FS API not available for load');
            return null;
        }

        try {
            const filePath = pathJoin(this.projectPath, 'project.json');
            const exists = await window.electronAPI.fs.exists(filePath);

            if (!exists) return null;

            const buffer = await window.electronAPI.fs.readFile(filePath);
            return buffer.toString('utf-8');
        } catch (error) {
            console.error('[RoverBackend] Load failed:', error);
            return null;
        }
    }

    /**
     * Check if project exists
     */
    async exists(key: string): Promise<boolean> {
        if (!window.electronAPI?.fs?.exists) return false;
        try {
            return await window.electronAPI.fs.exists(pathJoin(this.projectPath, 'project.json'));
        } catch (error) {
            return false;
        }
    }

    /**
     * Delete project file
     */
    async delete(key: string): Promise<void> {
        if (!window.electronAPI?.fs?.unlink) {
            throw new Error('FS API not available for delete operation');
        }

        try {
            const filePath = pathJoin(this.projectPath, 'project.json');
            const exists = await window.electronAPI.fs.exists(filePath);

            if (exists) {
                await window.electronAPI.fs.unlink(filePath);
                console.log('[RoverBackend] Project deleted:', filePath);
            }
        } catch (error) {
            console.error('[RoverBackend] Delete failed:', error);
            throw error;
        }
    }

    /**
     * List projects (not supported via RoverBackend for now)
     */
    async list(): Promise<string[]> {
        return [];
    }
}

/**
 * Helper to join paths safely in the renderer
 */
function pathJoin(base: string, part: string): string {
    // Simple path joining for renderer (assumes forward or backward slashes depending on OS)
    const separator = base.includes('\\') ? '\\' : '/';
    return base.endsWith(separator) ? base + part : base + separator + part;
}

/**
 * Phrase Synchronization Manager
 * 
 * Manages synchronization between voice recordings and phrase data
 * Coordinates with VoiceHttpClient for backend communication
 */

import { VoiceHttpClient, VoiceApiResponse } from './voiceHttpClient';
import type { VoiceRecording, PhraseData, SyncStatus } from '@/types';

/**
 * Phrase Synchronization Manager Configuration
 */
export interface PhraseSyncConfig {
  autoSync: boolean;
  syncInterval: number;
  maxRetries: number;
}

/**
 * Default configuration for Phrase Synchronization Manager
 */
const DEFAULT_SYNC_CONFIG: PhraseSyncConfig = {
  autoSync: true,
  syncInterval: 5000, // 5 seconds
  maxRetries: 3,
};

/**
 * Synchronization result
 */
export interface SyncResult {
  success: boolean;
  phraseId?: string;
  recordingId?: string;
  error?: string;
  timestamp: string;
}

/**
 * Phrase Synchronization Manager Class
 */
export class PhraseSyncManager {
  private voiceClient: VoiceHttpClient;
  private config: PhraseSyncConfig;
  private syncQueue: Array<{ phrase: PhraseData; recording: VoiceRecording }>;
  private isProcessing: boolean;
  private intervalId?: NodeJS.Timeout;

  constructor(
    voiceClient?: VoiceHttpClient,
    config?: Partial<PhraseSyncConfig>
  ) {
    this.voiceClient = voiceClient || new VoiceHttpClient();
    this.config = { ...DEFAULT_SYNC_CONFIG, ...config };
    this.syncQueue = [];
    this.isProcessing = false;

    if (this.config.autoSync) {
      this.startAutoSync();
    }
  }

  /**
   * Start automatic synchronization
   */
  startAutoSync(): void {
    if (this.intervalId) {
      clearInterval(this.intervalId);
    }

    this.intervalId = setInterval(() => {
      if (this.syncQueue.length > 0 && !this.isProcessing) {
        this.processQueue();
      }
    }, this.config.syncInterval);
  }

  /**
   * Stop automatic synchronization
   */
  stopAutoSync(): void {
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = undefined;
    }
  }

  /**
   * Add phrase and recording to synchronization queue
   * 
   * @param phrase - Phrase data to synchronize
   * @param recording - Voice recording to associate
   */
  addToSyncQueue(phrase: PhraseData, recording: VoiceRecording): void {
    this.syncQueue.push({ phrase, recording });
  }

  /**
   * Process synchronization queue
   */
  private async processQueue(): Promise<void> {
    if (this.isProcessing || this.syncQueue.length === 0) {
      return;
    }

    this.isProcessing = true;

    try {
      // Process items in queue
      while (this.syncQueue.length > 0) {
        const item = this.syncQueue.shift();
        if (item) {
          await this.syncPhraseWithRecording(item.phrase, item.recording);
        }
      }
    } finally {
      this.isProcessing = false;
    }
  }

  /**
   * Synchronize phrase with voice recording
   * 
   * @param phrase - Phrase data
   * @param recording - Voice recording
   * @returns Synchronization result
   */
  async syncPhraseWithRecording(
    phrase: PhraseData,
    recording: VoiceRecording
  ): Promise<SyncResult> {
    try {
      // First upload the voice recording
      const uploadResponse = await this.voiceClient.uploadVoiceRecording(
        recording
      );

      if (!uploadResponse.success) {
        throw new Error(
          uploadResponse.error || 'Failed to upload voice recording'
        );
      }

      // Associate recording ID with phrase
      const phraseWithRecording: PhraseData = {
        ...phrase,
        recordingId: uploadResponse.data?.recordingId,
      };

      // Synchronize phrase data with backend
      const syncResponse = await this.voiceClient.syncPhraseData(
        phraseWithRecording
      );

      if (!syncResponse.success) {
        throw new Error(
          syncResponse.error || 'Failed to synchronize phrase data'
        );
      }

      return {
        success: true,
        phraseId: phrase.id,
        recordingId: uploadResponse.data?.recordingId,
        timestamp: new Date().toISOString(),
      };
    } catch (error) {
      return {
        success: false,
        phraseId: phrase.id,
        error: error instanceof Error ? error.message : 'Unknown error',
        timestamp: new Date().toISOString(),
      };
    }
  }

  /**
   * Get synchronization status for a phrase
   * 
   * @param phraseId - ID of the phrase to check
   * @returns Current synchronization status
   */
  async getSyncStatus(phraseId: string): Promise<SyncStatus> {
    // In a real implementation, this would check backend status
    // For now, return a default status
    return {
      phraseId,
      status: 'synced',
      lastUpdated: new Date().toISOString(),
      retries: 0,
    };
  }

  /**
   * Get all pending synchronizations
   * 
   * @returns Array of pending synchronization items
   */
  getPendingSyncs(): Array<{ phrase: PhraseData; recording: VoiceRecording }> {
    return [...this.syncQueue];
  }

  /**
   * Clear synchronization queue
   */
  clearQueue(): void {
    this.syncQueue = [];
  }

  /**
   * Update synchronization configuration
   * 
   * @param config - New configuration
   */
  updateConfig(config: Partial<PhraseSyncConfig>): void {
    this.config = { ...this.config, ...config };

    if (this.config.autoSync && !this.intervalId) {
      this.startAutoSync();
    } else if (!this.config.autoSync && this.intervalId) {
      this.stopAutoSync();
    }
  }

  /**
   * Get current configuration
   * 
   * @returns Current synchronization configuration
   */
  getConfig(): PhraseSyncConfig {
    return { ...this.config };
  }

  /**
   * Cleanup resources
   */
  destroy(): void {
    this.stopAutoSync();
    this.clearQueue();
  }
}

