/**
 * LayoutPreferences Service
 * 
 * Manages persistence of layout preferences per screen size.
 * Saves and restores user preferences for different breakpoints.
 * 
 * Exigence: 12.8
 */

import type { ResponsiveBreakpoint } from '../../hooks/useResponsiveGrid';

export interface LayoutPreference {
  breakpointName: string;
  columns?: number;
  useListMode?: boolean;
  gridSize?: number;
  showGridLines?: boolean;
  snapEnabled?: boolean;
  customSettings?: Record<string, unknown>;
  lastUpdated: number;
}

export interface LayoutPreferencesState {
  preferences: Record<string, LayoutPreference>;
  version: string;
}

const STORAGE_KEY = 'storycore_layout_preferences';
const STORAGE_VERSION = '1.0';

/**
 * Layout Preferences Manager
 */
export class LayoutPreferencesManager {
  private preferences: Map<string, LayoutPreference> = new Map();
  private storageAvailable: boolean;

  constructor() {
    this.storageAvailable = this.checkStorageAvailable();
    this.loadPreferences();
  }

  /**
   * Check if localStorage is available
   */
  private checkStorageAvailable(): boolean {
    try {
      const test = '__storage_test__';
      localStorage.setItem(test, test);
      localStorage.removeItem(test);
      return true;
    } catch (e) {
      return false;
    }
  }

  /**
   * Load preferences from localStorage
   * Exigence: 12.8
   */
  private loadPreferences(): void {
    if (!this.storageAvailable) return;

    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (!stored) return;

      const state: LayoutPreferencesState = JSON.parse(stored);
      
      // Check version compatibility
      if (state.version !== STORAGE_VERSION) {
        console.warn('Layout preferences version mismatch, resetting preferences');
        this.clearPreferences();
        return;
      }

      // Load preferences into map
      Object.entries(state.preferences).forEach(([key, pref]) => {
        this.preferences.set(key, pref);
      });
    } catch (error) {
      console.error('Failed to load layout preferences:', error);
      this.clearPreferences();
    }
  }

  /**
   * Save preferences to localStorage
   * Exigence: 12.8
   */
  private savePreferences(): void {
    if (!this.storageAvailable) return;

    try {
      const state: LayoutPreferencesState = {
        version: STORAGE_VERSION,
        preferences: Object.fromEntries(this.preferences)
      };

      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (error) {
      console.error('Failed to save layout preferences:', error);
    }
  }

  /**
   * Get preference for a breakpoint
   * Exigence: 12.8
   */
  getPreference(breakpoint: ResponsiveBreakpoint): LayoutPreference | null {
    return this.preferences.get(breakpoint.name) || null;
  }

  /**
   * Set preference for a breakpoint
   * Exigence: 12.8
   */
  setPreference(breakpoint: ResponsiveBreakpoint, preference: Partial<LayoutPreference>): void {
    const existing = this.preferences.get(breakpoint.name);
    
    const updated: LayoutPreference = {
      breakpointName: breakpoint.name,
      ...existing,
      ...preference,
      lastUpdated: Date.now()
    };

    this.preferences.set(breakpoint.name, updated);
    this.savePreferences();
  }

  /**
   * Update specific preference field
   */
  updatePreference(
    breakpoint: ResponsiveBreakpoint,
    field: keyof LayoutPreference,
    value: unknown
  ): void {
    const existing = this.preferences.get(breakpoint.name) || {
      breakpointName: breakpoint.name,
      lastUpdated: Date.now()
    };

    const updated = {
      ...existing,
      [field]: value,
      lastUpdated: Date.now()
    };

    this.preferences.set(breakpoint.name, updated);
    this.savePreferences();
  }

  /**
   * Clear all preferences
   */
  clearPreferences(): void {
    this.preferences.clear();
    if (this.storageAvailable) {
      localStorage.removeItem(STORAGE_KEY);
    }
  }

  /**
   * Clear preference for specific breakpoint
   */
  clearPreference(breakpoint: ResponsiveBreakpoint): void {
    this.preferences.delete(breakpoint.name);
    this.savePreferences();
  }

  /**
   * Get all preferences
   */
  getAllPreferences(): Map<string, LayoutPreference> {
    return new Map(this.preferences);
  }

  /**
   * Export preferences as JSON
   */
  exportPreferences(): string {
    const state: LayoutPreferencesState = {
      version: STORAGE_VERSION,
      preferences: Object.fromEntries(this.preferences)
    };
    return JSON.stringify(state, null, 2);
  }

  /**
   * Import preferences from JSON
   */
  importPreferences(json: string): boolean {
    try {
      const state: LayoutPreferencesState = JSON.parse(json);
      
      if (state.version !== STORAGE_VERSION) {
        console.error('Version mismatch in imported preferences');
        return false;
      }

      this.preferences.clear();
      Object.entries(state.preferences).forEach(([key, pref]) => {
        this.preferences.set(key, pref);
      });

      this.savePreferences();
      return true;
    } catch (error) {
      console.error('Failed to import preferences:', error);
      return false;
    }
  }
}

// Singleton instance
let instance: LayoutPreferencesManager | null = null;

/**
 * Get singleton instance of LayoutPreferencesManager
 */
export const getLayoutPreferencesManager = (): LayoutPreferencesManager => {
  if (!instance) {
    instance = new LayoutPreferencesManager();
  }
  return instance;
};

/**
 * Result Service
 * 
 * Manages fetching and displaying generated results from the backend.
 * Supports result retrieval, preview, and download functionality.
 */

import type { GenerationTask } from '../types';
import { getCachedPlaceholder } from '../utils/placeholderImage';

export interface GeneratedResult {
  taskId: string;
  shotId: string;
  type: GenerationTask['type'];
  status: 'success' | 'failed';

  // Generated assets
  assets: GeneratedAsset[];

  // Metadata
  generatedAt: Date;
  processingTime?: number; // seconds

  // Quality metrics (if available)
  qualityScore?: number; // 0-100
  metrics?: Record<string, number>;

  // Error information (if failed)
  error?: string;
}

export interface GeneratedAsset {
  id: string;
  type: 'image' | 'video' | 'audio' | 'data';
  name: string;
  url: string;
  thumbnail?: string;
  size?: number; // bytes
  format?: string; // e.g., 'png', 'mp4', 'wav', 'json'
  dimensions?: { width: number; height: number };
  duration?: number; // seconds (for video/audio)
  metadata?: Record<string, unknown>;
}

export interface ResultFetchOptions {
  includeAssets?: boolean; // Include asset URLs (default: true)
  includeThumbnails?: boolean; // Include thumbnails (default: true)
  includeMetrics?: boolean; // Include quality metrics (default: false)
}

export class ResultService {
  private baseUrl: string;

  constructor(baseUrl: string = import.meta.env.VITE_BACKEND_URL || 'http://localhost:3000') {
    this.baseUrl = baseUrl;
  }

  /**
   * Generate a placeholder image as data URI to avoid CSP violations
   */
  protected generatePlaceholderImage(width: number, height: number, text: string): string {
    return getCachedPlaceholder(width, height, text);
  }

  /**
   * Fetch result for a completed task
   */
  async fetchResult(taskId: string, options: ResultFetchOptions = {}): Promise<GeneratedResult> {
    const {
      includeAssets = true,
      includeThumbnails = true,
      includeMetrics = false,
    } = options;

    const params = new URLSearchParams({
      includeAssets: String(includeAssets),
      includeThumbnails: String(includeThumbnails),
      includeMetrics: String(includeMetrics),
    });

    const response = await fetch(`${this.baseUrl}/api/tasks/${taskId}/result?${params}`);

    if (!response.ok) {
      throw new Error(`Failed to fetch result: ${response.statusText}`);
    }

    const data = await response.json();

    return {
      taskId: data.taskId,
      shotId: data.shotId,
      type: data.type,
      status: data.status,
      assets: data.assets || [],
      generatedAt: new Date(data.generatedAt),
      processingTime: data.processingTime,
      qualityScore: data.qualityScore,
      metrics: data.metrics,
      error: data.error,
    };
  }

  /**
   * Fetch results for multiple tasks
   */
  async fetchMultipleResults(taskIds: string[], options: ResultFetchOptions = {}): Promise<GeneratedResult[]> {
    const promises = taskIds.map((taskId) => this.fetchResult(taskId, options));
    return Promise.all(promises);
  }

  /**
   * Fetch all results for a project
   */
  async fetchProjectResults(projectName: string, options: ResultFetchOptions = {}): Promise<GeneratedResult[]> {
    const {
      includeAssets = true,
      includeThumbnails = true,
      includeMetrics = false,
    } = options;

    const params = new URLSearchParams({
      includeAssets: String(includeAssets),
      includeThumbnails: String(includeThumbnails),
      includeMetrics: String(includeMetrics),
    });

    const response = await fetch(`${this.baseUrl}/api/projects/${projectName}/results?${params}`);

    if (!response.ok) {
      throw new Error(`Failed to fetch project results: ${response.statusText}`);
    }

    const data = await response.json();

    return data.results.map((result: any) => ({
      taskId: result.taskId,
      shotId: result.shotId,
      type: result.type,
      status: result.status,
      assets: result.assets || [],
      generatedAt: new Date(result.generatedAt),
      processingTime: result.processingTime,
      qualityScore: result.qualityScore,
      metrics: result.metrics,
      error: result.error,
    }));
  }

  /**
   * Download an asset
   */
  async downloadAsset(asset: GeneratedAsset, filename?: string): Promise<void> {
    const response = await fetch(asset.url);

    if (!response.ok) {
      throw new Error(`Failed to download asset: ${response.statusText}`);
    }

    const blob = await response.blob();
    const url = URL.createObjectURL(blob);

    const link = document.createElement('a');
    link.href = url;
    link.download = filename || asset.name;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    URL.revokeObjectURL(url);
  }

  /**
   * Download all assets from a result
   */
  async downloadAllAssets(result: GeneratedResult): Promise<void> {
    for (const asset of result.assets) {
      await this.downloadAsset(asset);
    }
  }

  /**
   * Get preview URL for an asset
   */
  getPreviewUrl(asset: GeneratedAsset): string {
    if (asset.thumbnail) {
      return asset.thumbnail;
    }

    // For images, use the asset URL directly
    if (asset.type === 'image') {
      return asset.url;
    }

    // For other types, return a placeholder or generate thumbnail URL
    return `${this.baseUrl}/api/assets/${asset.id}/thumbnail`;
  }

  /**
   * Delete a result
   */
  async deleteResult(taskId: string): Promise<void> {
    const response = await fetch(`${this.baseUrl}/api/tasks/${taskId}/result`, {
      method: 'DELETE',
    });

    if (!response.ok) {
      throw new Error(`Failed to delete result: ${response.statusText}`);
    }
  }
}

/**
 * Mock Result Service for development/testing
 */
export class MockResultService extends ResultService {
  private mockResults: Map<string, GeneratedResult> = new Map();
  private mockDelay: number = 500;

  setMockResult(taskId: string, result: GeneratedResult): void {
    this.mockResults.set(taskId, result);
  }

  setMockDelay(delay: number): void {
    this.mockDelay = delay;
  }

  async fetchResult(taskId: string, _options: ResultFetchOptions = {}): Promise<GeneratedResult> {
    // Simulate network delay
    await new Promise((resolve) => setTimeout(resolve, this.mockDelay));

    // Return mock result if available
    if (this.mockResults.has(taskId)) {
      return this.mockResults.get(taskId)!;
    }

    // Generate mock result
    const mockResult: GeneratedResult = {
      taskId,
      shotId: `shot-${taskId}`,
      type: 'grid',
      status: 'success',
      assets: [
        {
          id: `asset-${taskId}-1`,
          type: 'image',
          name: `generated-image-${taskId}.png`,
          url: this.generatePlaceholderImage(800, 600, `Generated Image ${taskId}`),
          thumbnail: this.generatePlaceholderImage(200, 150, `Thumbnail ${taskId}`),
          size: 1024 * 500,
          format: 'png',
          dimensions: { width: 800, height: 600 },
        },
        {
          id: `asset-${taskId}-2`,
          type: 'data',
          name: `metadata-${taskId}.json`,
          url: `data:application/json,${encodeURIComponent(JSON.stringify({ taskId, generated: true }))}`,
          size: 256,
          format: 'json',
        },
      ],
      generatedAt: new Date(),
      processingTime: 45,
      qualityScore: 85,
      metrics: {
        sharpness: 92,
        colorBalance: 88,
        composition: 85,
      },
    };

    this.mockResults.set(taskId, mockResult);
    return mockResult;
  }

  async downloadAsset(asset: GeneratedAsset, filename?: string): Promise<void> {
    // Simulate download delay
    await new Promise((resolve) => setTimeout(resolve, this.mockDelay));

    // Use the parent's real download implementation
    // This ensures downloads work even in mock mode
    await super.downloadAsset(asset, filename);
  }

  async deleteResult(taskId: string): Promise<void> {
    await new Promise((resolve) => setTimeout(resolve, this.mockDelay));
    this.mockResults.delete(taskId);
  }
}

/**
 * Factory function to create the appropriate service
 */
export function createResultService(useMock: boolean = false): ResultService {
  if (useMock || import.meta.env.VITE_USE_MOCK_BACKEND === 'true') {
    return new MockResultService();
  }
  return new ResultService();
}

/**
 * SAPI TTS Provider for Windows Speech API
 * 
 * Provides Text-to-Speech using Windows native SAPI voices.
 * Integrates with the existing TTS service architecture.
 */

import type { VoiceOver, Voice } from '../types';

interface SapiTTSProviderConfig {
  defaultVoice?: string;
  useCoquiTTS?: boolean;
}

interface SapiVoice {
  id: string;
  name: string;
  displayName: string;
  gender: 'male' | 'female' | 'neutral';
  language: string;
  localService: boolean;
  supported: boolean;
  default?: boolean;
}

class SapiTTSProvider {
  name = 'SAPI';
  private config: SapiTTSProviderConfig;
  private cachedVoices: SapiVoice[] | null = null;

  constructor(config: SapiTTSProviderConfig = {}) {
    this.config = config;
  }

  /**
   * Get all available SAPI voices
   */
  async getAvailableVoices(): Promise<Voice[]> {
    // Try to get voices from Coqui TTS first (if configured)
    if (this.config.useCoquiTTS) {
      try {
        const coquiVoices = await this.getCoquiTTSVoices();
        if (coquiVoices.length > 0) {
          return coquiVoices;
        }
      } catch {
        console.warn('Coqui TTS not available, falling back to SAPI');
      }
    }

    // Fall back to native SAPI voices via Web Speech API
    return this.getSapiVoices();
  }

  /**
   * Get voices from Coqui TTS (if available)
   */
  private async getCoquiTTSVoices(): Promise<Voice[]> {
    // Check if Coqui TTS is available
    if (!(window as any).coquiTTS) {
      throw new Error('Coqui TTS not loaded');
    }

    const tts = (window as any).coquiTTS;
    const speakers = await tts.getSpeakers?.() || [];
    
    return speakers.map((speaker: unknown) => ({
      id: speaker.id || speaker.name,
      name: speaker.name || speaker.id,
      gender: this.inferGender(speaker.name || speaker.id),
      language: speaker.language || 'en-US',
    }));
  }

  /**
   * Get native SAPI voices via Web Speech API
   */
  private async getSapiVoices(): Promise<Voice[]> {
    if (!('speechSynthesis' in window)) {
      console.warn('Web Speech API not available');
      return this.getMockVoices();
    }

    // Wait for voices to be loaded
    await this.waitForVoices();

    const voices = window.speechSynthesis.getVoices();
    
    if (voices.length === 0) {
      console.warn('No SAPI voices available');
      return this.getMockVoices();
    }

    // Filter and map SAPI voices
    const sapiVoices = voices
      .filter(voice => voice.localService || voice.lang.startsWith('en'))
      .map(voice => ({
        id: voice.voiceURI || voice.name,
        name: voice.name,
        gender: this.inferGender(voice.name),
        language: voice.lang,
      }));

    return sapiVoices.length > 0 ? sapiVoices : this.getMockVoices();
  }

  /**
   * Get mock voices for development
   */
  private getMockVoices(): Voice[] {
    return [
      { id: 'sapi-david', name: 'Microsoft David Desktop', gender: 'male', language: 'en-US' },
      { id: 'sapi-zira', name: 'Microsoft Zira Desktop', gender: 'female', language: 'en-US' },
      { id: 'sapi-helena', name: 'Microsoft Helena Desktop', gender: 'female', language: 'fr-FR' },
      { id: 'sapi-hortense', name: 'Microsoft Hortense Desktop', gender: 'female', language: 'fr-FR' },
    ];
  }

  /**
   * Wait for voices to be loaded (Web Speech API quirk)
   */
  private waitForVoices(timeout: number = 1000): Promise<void> {
    return new Promise((resolve) => {
      if (window.speechSynthesis.getVoices().length > 0) {
        resolve();
        return;
      }

      const timeoutId = setTimeout(() => {
        resolve();
      }, timeout);

      window.speechSynthesis.onvoiceschanged = () => {
        clearTimeout(timeoutId);
        window.speechSynthesis.onvoiceschanged = null;
        resolve();
      };
    });
  }

  /**
   * Infer gender from voice name
   */
  private inferGender(name: string): 'male' | 'female' | 'neutral' {
    const lowerName = name.toLowerCase();
    
    const maleIndicators = ['male', 'david', 'james', 'richard', 'george', 'henri', 'francois'];
    const femaleIndicators = ['female', 'zira', 'samantha', 'victoria', 'helena', 'hortense', 'suzanne', 'marie'];
    
    if (maleIndicators.some(indicator => lowerName.includes(indicator))) {
      return 'male';
    }
    if (femaleIndicators.some(indicator => lowerName.includes(indicator))) {
      return 'female';
    }
    return 'neutral';
  }

  /**
   * Generate voiceover using SAPI
   */
  async generateVoiceOver(voiceOver: VoiceOver): Promise<string> {
    if (!('speechSynthesis' in window)) {
      throw new Error('Web Speech API not available');
    }

    return new Promise((resolve, reject) => {
      const utterance = new SpeechSynthesisUtterance(voiceOver.text);
      
      // Configure utterance parameters
      utterance.rate = Math.max(0.5, Math.min(2, voiceOver.speed));
      utterance.pitch = Math.max(0.5, Math.min(2, 1 + voiceOver.pitch / 10));
      utterance.volume = 1;

      // Select appropriate voice
      const voices = window.speechSynthesis.getVoices();
      const selectedVoice = this.selectVoice(voices, voiceOver.voice, voiceOver.language);
      
      if (selectedVoice) {
        utterance.voice = selectedVoice;
      }

      // Handle completion
      utterance.onend = () => {
        resolve(this.createAudioUrl(voiceOver));
      };

      utterance.onerror = (event) => {
        console.error('SAPI TTS error:', event);
        reject(new Error(`Speech synthesis failed: ${event.error}`));
      };

      // Start synthesis
      window.speechSynthesis.speak(utterance);
    });
  }

  /**
   * Select best matching voice
   */
  private selectVoice(
    voices: SpeechSynthesisVoice[],
    voiceId: string,
    language: string
  ): SpeechSynthesisVoice | null {
    // Try to find exact voice match
    if (voiceId) {
      const exactMatch = voices.find(v => 
        v.voiceURI === voiceId || v.name === voiceId
      );
      if (exactMatch) return exactMatch;
    }

    // Try to find voice by language
    const langPrefix = language.split('-')[0];
    const langMatch = voices.find(v => 
      v.lang.toLowerCase().startsWith(langPrefix)
    );
    if (langMatch) return langMatch;

    // Return first available voice
    return voices[0] || null;
  }

  /**
   * Create a placeholder audio URL
   * Note: In production, you'd want to capture the actual audio
   */
  private createAudioUrl(voiceOver: VoiceOver): string {
    // This is a placeholder - actual implementation would capture
    // the Web Speech API output using MediaRecorder
    return `data:audio/wav;base64,UklGRiQAAABXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YQAAAAA=`;
  }
}

// Export provider
export { SapiTTSProvider };

// Export singleton instance
export const sapiTTSProvider = new SapiTTSProvider();

// Re-export types for convenience
export type { SapiTTSProviderConfig, SapiVoice };

