/**
 * Create a new UndoRedoManager instance
 * 
 * @param initialState - The initial state
 * @param config - Configuration options
 * @returns New UndoRedoManager instance
 */
export function createUndoRedoManager<T>(
  initialState: T,
  config?: UndoRedoConfig
): UndoRedoManager<T> {
  return new UndoRedoManager(initialState, config);
}

/**
 * UndoRedoPersistence - IndexedDB-based persistence for undo/redo history
 * 
 * This service provides:
 * - Persistent storage of undo/redo history in IndexedDB
 * - Automatic restoration on page load
 * - Cleanup of old history entries
 * - Support for multiple projects/contexts
 * 
 * Requirements: 7.8
 */

import { HistoryEntry } from './UndoRedoManager';

// ============================================================================
// Type Definitions
// ============================================================================

/**
 * Persisted history data structure
 */
export interface PersistedHistory<T = any> {
  id: string;
  projectId: string;
  undoStack: HistoryEntry<T>[];
  redoStack: HistoryEntry<T>[];
  savedStateId: string | null;
  lastModified: number;
}

/**
 * Configuration for persistence service
 */
export interface PersistenceConfig {
  /** Database name (default: 'undoRedoHistory') */
  dbName?: string;
  
  /** Store name (default: 'history') */
  storeName?: string;
  
  /** Database version (default: 1) */
  version?: number;
  
  /** Maximum age of history entries in days (default: 30) */
  maxAgeDays?: number;
}

// ============================================================================
// UndoRedoPersistence Class
// ============================================================================

/**
 * Service for persisting undo/redo history to IndexedDB
 * 
 * Requirements: 7.8
 * 
 * @example
 * const persistence = new UndoRedoPersistence();
 * await persistence.initialize();
 * 
 * // Save history
 * await persistence.saveHistory('project-1', undoStack, redoStack, savedStateId);
 * 
 * // Load history
 * const history = await persistence.loadHistory('project-1');
 */
export class UndoRedoPersistence {
  private db: IDBDatabase | null = null;
  private config: Required<PersistenceConfig>;

  constructor(config: PersistenceConfig = {}) {
    this.config = {
      dbName: config.dbName || 'undoRedoHistory',
      storeName: config.storeName || 'history',
      version: config.version || 1,
      maxAgeDays: config.maxAgeDays || 30
    };
  }

  // ============================================================================
  // Initialization
  // ============================================================================

  /**
   * Initialize the IndexedDB database
   * 
   * @returns Promise that resolves when database is ready
   */
  async initialize(): Promise<void> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.config.dbName, this.config.version);

      request.onerror = () => {
        reject(new Error('Failed to open IndexedDB'));
      };

      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;

        // Create object store if it doesn't exist
        if (!db.objectStoreNames.contains(this.config.storeName)) {
          const store = db.createObjectStore(this.config.storeName, {
            keyPath: 'id'
          });

          // Create indexes
          store.createIndex('projectId', 'projectId', { unique: false });
          store.createIndex('lastModified', 'lastModified', { unique: false });
        }
      };
    });
  }

  // ============================================================================
  // Save Operations
  // ============================================================================

  /**
   * Save undo/redo history to IndexedDB
   * 
   * Requirements: 7.8
   * 
   * @param projectId - Unique identifier for the project/context
   * @param undoStack - Array of undo history entries
   * @param redoStack - Array of redo history entries
   * @param savedStateId - ID of the last saved state
   * @returns Promise that resolves when save is complete
   */
  async saveHistory<T>(
    projectId: string,
    undoStack: HistoryEntry<T>[],
    redoStack: HistoryEntry<T>[],
    savedStateId: string | null
  ): Promise<void> {
    if (!this.db) {
      throw new Error('Database not initialized. Call initialize() first.');
    }

    const history: PersistedHistory<T> = {
      id: `history-${projectId}`,
      projectId,
      undoStack: undoStack.map(entry => ({
        ...entry,
        inverseAction: undefined // Don't persist functions
      })),
      redoStack: redoStack.map(entry => ({
        ...entry,
        inverseAction: undefined
      })),
      savedStateId,
      lastModified: Date.now()
    };

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([this.config.storeName], 'readwrite');
      const store = transaction.objectStore(this.config.storeName);
      const request = store.put(history);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(new Error('Failed to save history'));
    });
  }

  // ============================================================================
  // Load Operations
  // ============================================================================

  /**
   * Load undo/redo history from IndexedDB
   * 
   * Requirements: 7.8
   * 
   * @param projectId - Unique identifier for the project/context
   * @returns Promise that resolves with the persisted history, or null if not found
   */
  async loadHistory<T>(projectId: string): Promise<PersistedHistory<T> | null> {
    if (!this.db) {
      throw new Error('Database not initialized. Call initialize() first.');
    }

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([this.config.storeName], 'readonly');
      const store = transaction.objectStore(this.config.storeName);
      const request = store.get(`history-${projectId}`);

      request.onsuccess = () => {
        const result = request.result as PersistedHistory<T> | undefined;
        resolve(result || null);
      };

      request.onerror = () => reject(new Error('Failed to load history'));
    });
  }

  /**
   * Load all history entries for a project
   * 
   * @param projectId - Unique identifier for the project
   * @returns Promise that resolves with array of history entries
   */
  async loadAllHistoryForProject<T>(projectId: string): Promise<PersistedHistory<T>[]> {
    if (!this.db) {
      throw new Error('Database not initialized. Call initialize() first.');
    }

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([this.config.storeName], 'readonly');
      const store = transaction.objectStore(this.config.storeName);
      const index = store.index('projectId');
      const request = index.getAll(projectId);

      request.onsuccess = () => {
        resolve(request.result as PersistedHistory<T>[]);
      };

      request.onerror = () => reject(new Error('Failed to load project history'));
    });
  }

  // ============================================================================
  // Delete Operations
  // ============================================================================

  /**
   * Delete history for a specific project
   * 
   * @param projectId - Unique identifier for the project
   * @returns Promise that resolves when deletion is complete
   */
  async deleteHistory(projectId: string): Promise<void> {
    if (!this.db) {
      throw new Error('Database not initialized. Call initialize() first.');
    }

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([this.config.storeName], 'readwrite');
      const store = transaction.objectStore(this.config.storeName);
      const request = store.delete(`history-${projectId}`);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(new Error('Failed to delete history'));
    });
  }

  /**
   * Delete all history entries
   * 
   * @returns Promise that resolves when deletion is complete
   */
  async deleteAllHistory(): Promise<void> {
    if (!this.db) {
      throw new Error('Database not initialized. Call initialize() first.');
    }

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([this.config.storeName], 'readwrite');
      const store = transaction.objectStore(this.config.storeName);
      const request = store.clear();

      request.onsuccess = () => resolve();
      request.onerror = () => reject(new Error('Failed to clear history'));
    });
  }

  // ============================================================================
  // Cleanup Operations
  // ============================================================================

  /**
   * Clean up old history entries
   * 
   * Removes entries older than maxAgeDays
   * 
   * @returns Promise that resolves with the number of deleted entries
   */
  async cleanupOldHistory(): Promise<number> {
    if (!this.db) {
      throw new Error('Database not initialized. Call initialize() first.');
    }

    const maxAge = this.config.maxAgeDays * 24 * 60 * 60 * 1000; // Convert to milliseconds
    const cutoffTime = Date.now() - maxAge;

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([this.config.storeName], 'readwrite');
      const store = transaction.objectStore(this.config.storeName);
      const index = store.index('lastModified');
      const request = index.openCursor(IDBKeyRange.upperBound(cutoffTime));

      let deletedCount = 0;

      request.onsuccess = (event) => {
        const cursor = (event.target as IDBRequest).result as IDBCursorWithValue;

        if (cursor) {
          cursor.delete();
          deletedCount++;
          cursor.continue();
        } else {
          resolve(deletedCount);
        }
      };

      request.onerror = () => reject(new Error('Failed to cleanup old history'));
    });
  }

  // ============================================================================
  // Utility Methods
  // ============================================================================

  /**
   * Check if database is initialized
   * 
   * @returns True if database is ready
   */
  isInitialized(): boolean {
    return this.db !== null;
  }

  /**
   * Close the database connection
   */
  close(): void {
    if (this.db) {
      this.db.close();
      this.db = null;
    }
  }

  /**
   * Get database statistics
   * 
   * @returns Promise that resolves with statistics
   */
  async getStatistics(): Promise<{
    totalEntries: number;
    totalSize: number;
    oldestEntry: number | null;
    newestEntry: number | null;
  }> {
    if (!this.db) {
      throw new Error('Database not initialized. Call initialize() first.');
    }

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([this.config.storeName], 'readonly');
      const store = transaction.objectStore(this.config.storeName);
      const request = store.getAll();

      request.onsuccess = () => {
        const entries = request.result as PersistedHistory[];
        
        const stats = {
          totalEntries: entries.length,
          totalSize: JSON.stringify(entries).length,
          oldestEntry: entries.length > 0
            ? Math.min(...entries.map(e => e.lastModified))
            : null,
          newestEntry: entries.length > 0
            ? Math.max(...entries.map(e => e.lastModified))
            : null
        };

        resolve(stats);
      };

      request.onerror = () => reject(new Error('Failed to get statistics'));
    });
  }
}

// ============================================================================
// Singleton Instance
// ============================================================================

let persistenceInstance: UndoRedoPersistence | null = null;

/**
 * Get the singleton persistence instance
 * 
 * @param config - Configuration options (only used on first call)
 * @returns Persistence instance
 */
export function getPersistenceInstance(config?: PersistenceConfig): UndoRedoPersistence {
  if (!persistenceInstance) {
    persistenceInstance = new UndoRedoPersistence(config);
  }
  return persistenceInstance;
}

/**
 * Initialize the persistence service
 * 
 * @param config - Configuration options
 * @returns Promise that resolves when initialized
 */
export async function initializePersistence(config?: PersistenceConfig): Promise<UndoRedoPersistence> {
  const instance = getPersistenceInstance(config);
  await instance.initialize();
  return instance;
}

/**
 * User Edit Tracking Service
 * 
 * Tracks which fields have been manually edited by the user
 * Preserves user edits during LLM regeneration
 * 
 * Validates Requirements: 1.8
 */

// ============================================================================
// Types
// ============================================================================

export interface EditTrackingState {
  /**
   * Map of field paths to edit status
   * Example: { "name": true, "visual_identity.hair_color": true }
   */
  editedFields: Record<string, boolean>;

  /**
   * Timestamp of last edit
   */
  lastEditTime: Date;
}

// ============================================================================
// Edit Tracking Manager
// ============================================================================

export class EditTrackingManager {
  private editedFields: Set<string> = new Set();
  private lastEditTime: Date = new Date();

  /**
   * Mark a field as edited by the user
   */
  markFieldAsEdited(fieldPath: string): void {
    this.editedFields.add(fieldPath);
    this.lastEditTime = new Date();
  }

  /**
   * Mark multiple fields as edited
   */
  markFieldsAsEdited(fieldPaths: string[]): void {
    fieldPaths.forEach((path) => this.editedFields.add(path));
    this.lastEditTime = new Date();
  }

  /**
   * Check if a field has been edited
   */
  isFieldEdited(fieldPath: string): boolean {
    return this.editedFields.has(fieldPath);
  }

  /**
   * Get all edited field paths
   */
  getEditedFields(): string[] {
    return Array.from(this.editedFields);
  }

  /**
   * Clear edit tracking for a specific field
   */
  clearFieldEdit(fieldPath: string): void {
    this.editedFields.delete(fieldPath);
  }

  /**
   * Clear all edit tracking
   */
  clearAllEdits(): void {
    this.editedFields.clear();
    this.lastEditTime = new Date();
  }

  /**
   * Reset a field to generated state (allow regeneration)
   */
  resetFieldToGenerated(fieldPath: string): void {
    this.editedFields.delete(fieldPath);
  }

  /**
   * Get edit tracking state for persistence
   */
  getState(): EditTrackingState {
    return {
      editedFields: Object.fromEntries(
        Array.from(this.editedFields).map((field) => [field, true])
      ),
      lastEditTime: this.lastEditTime,
    };
  }

  /**
   * Restore edit tracking state from persistence
   */
  restoreState(state: EditTrackingState): void {
    this.editedFields = new Set(Object.keys(state.editedFields));
    this.lastEditTime = new Date(state.lastEditTime);
  }

  /**
   * Get count of edited fields
   */
  getEditedFieldCount(): number {
    return this.editedFields.size;
  }
}

// ============================================================================
// Merge Strategy for Regeneration
// ============================================================================

/**
 * Merges generated data with user-edited data
 * Preserves user edits while updating non-edited fields
 */
export function mergeWithUserEdits<T extends Record<string, unknown>>(
  generatedData: T,
  currentData: T,
  editTracker: EditTrackingManager
): T {
  // Recursively preserve edited fields
  // Using 'any' for recursive merge to handle nested objects of varying structures
  function preserveEdits(
    generated: unknown,
    current: unknown,
    path: string = ''
  ): unknown {
    if (typeof generated !== 'object' || generated === null) {
      // Check if this field was edited
      if (editTracker.isFieldEdited(path)) {
        return current;
      }
      return generated;
    }

    if (Array.isArray(generated)) {
      // For arrays, check if the entire array was edited
      if (editTracker.isFieldEdited(path)) {
        return current;
      }
      return generated;
    }

    // For objects, recursively check each property
    // Using 'any' for result object to build merged structure dynamically
    const result: unknown = {};
    const allKeys = new Set([
      ...Object.keys(generated),
      ...Object.keys(current || {}),
    ]);

    allKeys.forEach((key) => {
      const fieldPath = path ? `${path}.${key}` : key;
      const generatedValue = generated[key];
      const currentValue = current?.[key];

      if (editTracker.isFieldEdited(fieldPath)) {
        // Preserve user edit
        result[key] = currentValue;
      } else if (
        typeof generatedValue === 'object' &&
        generatedValue !== null &&
        !Array.isArray(generatedValue)
      ) {
        // Recursively merge nested objects
        result[key] = preserveEdits(generatedValue, currentValue, fieldPath);
      } else {
        // Use generated value
        result[key] = generatedValue;
      }
    });

    return result;
  }

  return preserveEdits(generatedData, currentData) as T;
}

// ============================================================================
// Field Path Utilities
// ============================================================================

/**
 * Converts a nested object path to a field path string
 * Example: ["visual_identity", "hair_color"] => "visual_identity.hair_color"
 */
export function createFieldPath(pathSegments: string[]): string {
  return pathSegments.join('.');
}

/**
 * Extracts field path from an input name
 * Example: "visual_identity.hair_color" => ["visual_identity", "hair_color"]
 */
export function parseFieldPath(fieldPath: string): string[] {
  return fieldPath.split('.');
}

/**
 * Gets the value at a field path in an object
 */
// Using 'any' for obj parameter and return type to support accessing any object structure
export function getValueAtPath(obj: unknown, fieldPath: string): unknown {
  const segments = parseFieldPath(fieldPath);
  let current = obj;

  for (const segment of segments) {
    if (current === null || current === undefined) {
      return undefined;
    }
    current = current[segment];
  }

  return current;
}

/**
 * Sets the value at a field path in an object
 */
// Using 'any' for obj and value parameters to support setting values in any object structure
export function setValueAtPath(
  obj: unknown,
  fieldPath: string,
  value: unknown
): void {
  const segments = parseFieldPath(fieldPath);
  let current = obj;

  for (let i = 0; i < segments.length - 1; i++) {
    const segment = segments[i];
    if (!(segment in current)) {
      current[segment] = {};
    }
    current = current[segment];
  }

  current[segments[segments.length - 1]] = value;
}

// ============================================================================
// React Hook for Edit Tracking
// ============================================================================

import { useState, useCallback, useRef } from 'react';

export function useEditTracking() {
  const trackerRef = useRef(new EditTrackingManager());
  const [editCount, setEditCount] = useState(0);

  const markFieldAsEdited = useCallback((fieldPath: string) => {
    trackerRef.current.markFieldAsEdited(fieldPath);
    setEditCount(trackerRef.current.getEditedFieldCount());
  }, []);

  const markFieldsAsEdited = useCallback((fieldPaths: string[]) => {
    trackerRef.current.markFieldsAsEdited(fieldPaths);
    setEditCount(trackerRef.current.getEditedFieldCount());
  }, []);

  const isFieldEdited = useCallback((fieldPath: string) => {
    return trackerRef.current.isFieldEdited(fieldPath);
  }, []);

  const resetFieldToGenerated = useCallback((fieldPath: string) => {
    trackerRef.current.resetFieldToGenerated(fieldPath);
    setEditCount(trackerRef.current.getEditedFieldCount());
  }, []);

  const clearAllEdits = useCallback(() => {
    trackerRef.current.clearAllEdits();
    setEditCount(0);
  }, []);

  const getEditedFields = useCallback(() => {
    return trackerRef.current.getEditedFields();
  }, []);

  const mergeWithEdits = useCallback(
    <T extends Record<string, unknown>>(generatedData: T, currentData: T): T => {
      return mergeWithUserEdits(generatedData, currentData, trackerRef.current);
    },
    []
  );

  return {
    markFieldAsEdited,
    markFieldsAsEdited,
    isFieldEdited,
    resetFieldToGenerated,
    clearAllEdits,
    getEditedFields,
    mergeWithEdits,
    editCount,
    tracker: trackerRef.current,
  };
}

/**
 * VideoReplicationService
 * Upload reference video and recreate with Digital Human support
 */

import { getPerformanceMonitoringService } from './performanceMonitoringService';
import { videoFrameCache, estimateSize } from '../utils/memoryMonitor';
import { logger } from '../utils/logger';

// ============================================================================
// Types
// ============================================================================

export interface ReferenceVideo {
  id: string;
  fileUrl: string;
  duration: number;
  resolution: { width: number; height: number };
  fps: number;
  uploadedAt: Date;
  structure?: VideoStructureAnalysis;
  digitalHumanAnalysis?: DigitalHumanAnalysis;
}

export interface VideoStructureAnalysis {
  totalDuration: number;
  shots: ShotInfo[];
  transitions: TransitionInfo[];
  keyframeCount: number;
  sceneChanges: SceneChange[];
}

export interface ShotInfo {
  id: string;
  startTime: number;
  endTime: number;
  duration: number;
  keyframeUrl?: string;
  composition: CompositionInfo;
  cameraMovement?: string;
}

export interface CompositionInfo {
  ruleOfThirds: boolean;
