        lastAccessedAt: Date.now(),
        accessCount: 0,
        originalWidth: 1920,
        originalHeight: 1080,
      };
      cache.set(entry);
      expect(cache.has('video-1', 0)).toBe(true);
      
      cache.delete('video-1', 0);
      expect(cache.has('video-1', 0)).toBe(false);
    });

    it('deletes all thumbnails for a video', () => {
