          createdAt: Date.now(),
          lastAccessedAt: Date.now(),
          accessCount: 0,
          originalWidth: 1920,
          originalHeight: 1080,
        };
        cache.set(entry);
      }
      
      const deleted = cache.deleteVideo('video-1');
      expect(deleted).toBe(5);
      expect(cache.has('video-1', 0)).toBe(false);
    });

    it('clears entire cache', () => {
      for (let i = 0; i < 5; i++) {
        const entry: ThumbnailEntry = {
          key: `video-1:${i}`,
          videoId: 'video-1',
          frameNumber: i,
          timestamp: i / 30,
          dataUrl: 'data:image/jpeg;base64,test',
          createdAt: Date.now(),
          lastAccessedAt: Date.now(),
          accessCount: 0,
          originalWidth: 1920,
          originalHeight: 1080,
        };
        cache.set(entry);
      }
      
      cache.clear();
      expect(cache.size).toBe(0);
    });
  });

  describe('Hit Rate Tracking', () => {
    it('tracks hits correctly', () => {
      const entry: ThumbnailEntry = {
        key: 'video-1:0',
        videoId: 'video-1',
        frameNumber: 0,
        timestamp: 0,
        dataUrl: 'data:image/jpeg;base64,test',
        createdAt: Date.now(),
        lastAccessedAt: Date.now(),
        accessCount: 0,
        originalWidth: 1920,
        originalHeight: 1080,
      };
      cache.set(entry);
      
      // Access the entry
      cache.get('video-1', 0);
      
      const stats = cache.getStats();
      expect(stats.hits).toBeGreaterThan(0);
    });

    it('tracks misses correctly', () => {
      cache.get('video-1', 999);
      
      const stats = cache.getStats();
      expect(stats.misses).toBeGreaterThan(0);
    });

    it('calculates hit rate correctly', () => {
      const entry: ThumbnailEntry = {
        key: 'video-1:0',
        videoId: 'video-1',
        frameNumber: 0,
        timestamp: 0,
        dataUrl: 'data:image/jpeg;base64,test',
        createdAt: Date.now(),
        lastAccessedAt: Date.now(),
        accessCount: 0,
        originalWidth: 1920,
        originalHeight: 1080,
      };
      cache.set(entry);
      
      // Hit
      cache.get('video-1', 0);
      // Miss
      cache.get('video-1', 1);
      
      const stats = cache.getStats();
      expect(stats.hitRate).toBe(0.5);
    });
  });

  describe('Preloading', () => {
    it('cancels pending preloads for a video', () => {
      cache.requestPreload('video-1', 0, 100, 1);
      cache.requestPreload('video-2', 0, 100, 1);
      
      cache.cancelPreloads('video-1');
      
      // Queue should still have video-2 request
      expect((cache as unknown as { preloadQueue: unknown[] }).preloadQueue.length).toBeGreaterThanOrEqual(1);
    });
  });

  describe('Cleanup', () => {
    it('destroys cache and clears all data', () => {
      const entry: ThumbnailEntry = {
        key: 'video-1:0',
        videoId: 'video-1',
        frameNumber: 0,
        timestamp: 0,
        dataUrl: 'data:image/jpeg;base64,test',
        createdAt: Date.now(),
        lastAccessedAt: Date.now(),
        accessCount: 0,
        originalWidth: 1920,
        originalHeight: 1080,
      };
      cache.set(entry);
      cache.destroy();
      expect(cache.size).toBe(0);
    });

    it('resets statistics', () => {
      const entry: ThumbnailEntry = {
        key: 'video-1:0',
        videoId: 'video-1',
        frameNumber: 0,
        timestamp: 0,
        dataUrl: 'data:image/jpeg;base64,test',
        createdAt: Date.now(),
        lastAccessedAt: Date.now(),
        accessCount: 0,
        originalWidth: 1920,
        originalHeight: 1080,
      };
      cache.set(entry);
      cache.get('video-1', 0);
      
      cache.resetStats();
      
      const stats = cache.getStats();
      expect(stats.hits).toBe(0);
      expect(stats.misses).toBe(0);
    });
  });

  describe('Get Multiple', () => {
    it('retrieves multiple thumbnails at once', () => {
      for (let i = 0; i < 5; i++) {
        const entry: ThumbnailEntry = {
          key: `video-1:${i}`,
          videoId: 'video-1',
          frameNumber: i,
          timestamp: i / 30,
          dataUrl: 'data:image/jpeg;base64,test',
          createdAt: Date.now(),
          lastAccessedAt: Date.now(),
          accessCount: 0,
          originalWidth: 1920,
          originalHeight: 1080,
        };
        cache.set(entry);
      }
      
      const result = cache.getMultiple('video-1', [0, 2, 4]);
      expect(result.size).toBe(3);
      expect(result.has(0)).toBe(true);
      expect(result.has(2)).toBe(true);
      expect(result.has(4)).toBe(true);
    });
  });
});

/**
 * Voice HTTP Client
 * 
 * Handles HTTP communication with the backend for voice recording synchronization
 * Uses the fetch API for making HTTP requests
 */

import type { VoiceRecording, PhraseData } from '@/types';

/**
 * Voice HTTP Client Configuration
 */
export interface VoiceHttpConfig {
  baseUrl: string;
  timeout: number;
  retryAttempts: number;
}

/**
 * Default configuration for Voice HTTP Client
 */
const DEFAULT_VOICE_CONFIG: VoiceHttpConfig = {
  baseUrl: import.meta.env.VITE_BACKEND_URL || 'http://localhost:3000',
  timeout: 120000, // 2 minutes for TTS generation
  retryAttempts: 3,
};

/**
 * API response types for voice operations
 */
export interface VoiceApiResponse<T = any> {
  success: boolean;
  data?: T;
  error?: string;
  message?: string;
}

/**
 * Voice recording upload response
 */
export interface VoiceUploadResponse {
  recordingId: string;
  status: 'uploaded' | 'processing' | 'completed' | 'failed';
  message: string;
  timestamp: string;
}

/**
 * Phrase synchronization response
 */
export interface PhraseSyncResponse {
  phraseId: string;
  recordingId: string;
  syncStatus: 'synced' | 'pending' | 'failed';
  timestamp: string;
}

/**
 * Voice HTTP Client Class
 */
export class VoiceHttpClient {
  private config: VoiceHttpConfig;

  constructor(config?: Partial<VoiceHttpConfig>) {
    this.config = { ...DEFAULT_VOICE_CONFIG, ...config };
  }

  /**
   * Upload voice recording to backend
   * 
   * @param recording - Voice recording data
   * @returns Upload response with recording ID
   */
  async uploadVoiceRecording(
    recording: VoiceRecording
  ): Promise<VoiceApiResponse<VoiceUploadResponse>> {
    try {
      const formData = new FormData();
      formData.append('audio', recording.audioBlob, recording.filename);
      formData.append('metadata', JSON.stringify({
        userId: recording.userId,
        sessionId: recording.sessionId,
        timestamp: recording.timestamp,
        duration: recording.duration,
        sampleRate: recording.sampleRate,
      }));

      const response = await this.fetchWithRetry('/api/voice/upload', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        const error = await response.json();
        return {
          success: false,
          error: error.message || 'Failed to upload voice recording',
        };
      }

      const data = await response.json();
      return {
        success: true,
        data,
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  /**
   * Synchronize phrase data with backend
   * 
   * @param phrase - Phrase data to synchronize
   * @returns Synchronization response
   */
  async syncPhraseData(
    phrase: PhraseData
  ): Promise<VoiceApiResponse<PhraseSyncResponse>> {
    try {
      const response = await this.fetchWithRetry('/api/voice/phrase/sync', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(phrase),
      });

      if (!response.ok) {
        const error = await response.json();
        return {
          success: false,
          error: error.message || 'Failed to synchronize phrase data',
        };
      }

      const data = await response.json();
      return {
        success: true,
        data,
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  /**
   * Get voice recording status
   * 
   * @param recordingId - ID of the recording to check
   * @returns Status response
   */
  async getRecordingStatus(
    recordingId: string
  ): Promise<VoiceApiResponse<VoiceUploadResponse>> {
    try {
      const response = await this.fetchWithRetry(
        `/api/voice/status/${recordingId}`
      );

      if (!response.ok) {
        const error = await response.json();
        return {
          success: false,
          error: error.message || 'Failed to get recording status',
        };
      }

      const data = await response.json();
      return {
        success: true,
        data,
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  /**
   * Get all recordings for a session
   * 
   * @param sessionId - Session ID to get recordings for
   * @returns List of voice recordings
   */
  async getSessionRecordings(
    sessionId: string
  ): Promise<VoiceApiResponse<VoiceRecording[]>> {
    try {
      const response = await this.fetchWithRetry(
        `/api/voice/session/${sessionId}`
      );

      if (!response.ok) {
        const error = await response.json();
        return {
          success: false,
          error: error.message || 'Failed to get session recordings',
        };
      }

      const data = await response.json();
      return {
        success: true,
        data,
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  /**
   * Delete a voice recording
   * 
   * @param recordingId - ID of the recording to delete
   * @returns Deletion response
   */
  async deleteRecording(
    recordingId: string
  ): Promise<VoiceApiResponse<void>> {
    try {
      const response = await this.fetchWithRetry(
        `/api/voice/delete/${recordingId}`,
        {
          method: 'DELETE',
        }
      );

      if (!response.ok) {
        const error = await response.json();
        return {
          success: false,
          error: error.message || 'Failed to delete recording',
        };
      }

      return {
        success: true,
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  /**
   * Fetch with retry logic for voice operations
   * 
   * @param url - URL to fetch
   * @param options - Fetch options
   * @returns Fetch response
   */
  private async fetchWithRetry(
    url: string,
    options?: RequestInit
  ): Promise<Response> {
    const fullUrl = `${this.config.baseUrl}${url}`;
    let lastError: Error | null = null;

    for (let attempt = 0; attempt < this.config.retryAttempts; attempt++) {
      try {
        const controller = new AbortController();
        const timeoutId = setTimeout(
          () => controller.abort(),
          this.config.timeout
        );

        const response = await fetch(fullUrl, {
          ...options,
          signal: controller.signal,
        });

        clearTimeout(timeoutId);
        return response;
      } catch (error) {
        lastError = error instanceof Error ? error : new Error('Unknown error');

        // Don't retry on abort (timeout)
        if (error instanceof Error && error.name === 'AbortError') {
          throw new Error('Request timeout');
        }

        // Wait before retry (exponential backoff)
        if (attempt < this.config.retryAttempts - 1) {
          await this.delay(Math.pow(2, attempt) * 1000);
        }
      }
    }

    throw lastError || new Error('Failed after retries');
  }

  /**
   * Delay helper
   * 
   * @param ms - Milliseconds to delay
   */
  private delay(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  /**
   * Update voice HTTP configuration
   * 
   * @param config - New configuration
   */
  updateConfig(config: Partial<VoiceHttpConfig>): void {
    this.config = { ...this.config, ...config };
  }

  /**
   * Get current configuration
   * 
   * @returns Current voice HTTP configuration
   */
  getConfig(): VoiceHttpConfig {
    return { ...this.config };
  }
}

/**
 * Default Voice HTTP Client instance
 */
export const voiceHttpClient = new VoiceHttpClient();

/**
 * Mock Voice HTTP Client for development/testing
 */
export class MockVoiceHttpClient extends VoiceHttpClient {
  private mockDelayMs: number = 500;

  async uploadVoiceRecording(
