// Validation Engine
// ============================================================================

export class WizardValidationEngine {
  private readonly rules: Map<string, readonly StepValidationRule[]> = new Map();

  constructor() {
    this.registerDefaultRules();
  }

  /**
   * Register default validation rules for all wizards
   */
  private registerDefaultRules(): void {
    // Character Wizard
    this.registerRule('character', 1, validateCharacterStep1);
    this.registerRule('character', 2, validateCharacterStep2);
    this.registerRule('character', 3, validateCharacterStep3);
    this.registerRule('character', 4, validateCharacterStep4);
    this.registerRule('character', 5, validateCharacterStep5);
    this.registerRule('character', 6, validateCharacterStep6);

    // World Wizard
    this.registerRule('world', 1, validateWorldStep1);
    this.registerRule('world', 2, validateWorldStep2);
    this.registerRule('world', 3, validateWorldStep3);
    this.registerRule('world', 4, validateWorldStep4);
    this.registerRule('world', 5, validateWorldStep5);

    // Storyteller Wizard
    this.registerRule('storyteller', 1, validateStorytellerStep1);
    this.registerRule('storyteller', 2, validateStorytellerStep2);
    this.registerRule('storyteller', 3, validateStorytellerStep3);
    this.registerRule('storyteller', 4, validateStorytellerStep4);
    this.registerRule('storyteller', 5, validateStorytellerStep5);

    // Project Setup Wizard
    this.registerRule('project-setup', 1, validateProjectSetupStep1);
    this.registerRule('project-setup', 2, validateProjectSetupStep2);
    this.registerRule('project-setup', 3, validateProjectSetupStep3);
  }

  /**
   * Register a validation rule for a specific wizard step
   */
  registerRule<T extends WizardValidationData>(
    wizardType: string,
    step: number,
    validate: (data: T) => ValidationResult,
    dependencies?: string[]
  ): void {
    const key = wizardType;
    if (!this.rules.has(key)) {
      this.rules.set(key, []);
    }
    // Cast to mutable array for pushing - the Map value is intentionally readonly for external access
    const rulesArray = this.rules.get(key) as StepValidationRule[];
    rulesArray.push({ step, wizardType, validate: validate as (data: WizardValidationData) => ValidationResult, dependencies });
  }

  /**
   * Validate a specific step for a wizard
   */
  validateStep<T extends WizardValidationData>(wizardType: string, step: number, data: T): ValidationResult {
    const rules = this.rules.get(wizardType);
    if (!rules) {
      logger.warn(`[ValidationEngine] No validation rules found for wizard type: ${wizardType}`);
      return createValidResult();
    }

    const rule = rules.find(r => r.step === step);
    if (!rule) {
      logger.warn(`[ValidationEngine] No validation rule found for step ${step} in ${wizardType}`);
      return createValidResult();
    }

    return rule.validate(data as WizardValidationData);
  }

  /**
   * Validate all steps for a wizard
   */
  validateAll(wizardType: string, allData: Record<number, WizardValidationData>): ValidationResult {
    const rules = this.rules.get(wizardType);
    if (!rules) {
      return createValidResult();
    }

    const results = rules.map(rule => {
      const stepData = allData[rule.step];
      return rule.validate(stepData);
    });

    return combineResults(...results);
  }

  /**
   * Get validation summary for display
   */
  getSummary(result: ValidationResult): {
    totalErrors: number;
    totalWarnings: number;
    totalInfos: number;
    hasErrors: boolean;
    message: string;
  } {
    const totalErrors = result.errors.length;
    const totalWarnings = result.warnings.length;
    const totalInfos = result.infos.length;

    let message = '';
    if (totalErrors > 0) {
      message = `${totalErrors} error${totalErrors > 1 ? 's' : ''} found`;
    } else if (totalWarnings > 0) {
      message = `${totalWarnings} warning${totalWarnings > 1 ? 's' : ''} found`;
    } else {
      message = 'All validations passed';
    }

    return {
      totalErrors,
      totalWarnings,
      totalInfos,
      hasErrors: totalErrors > 0,
      message,
    };
  }
}

// ============================================================================
// Singleton instance
// ============================================================================

export const validationEngine = new WizardValidationEngine();

// ============================================================================
// Helper functions for UI
// ============================================================================

/**
 * Format validation errors for display in a form
 */
export function formatValidationErrors(result: ValidationResult): string[] {
  return result.errors.map(error => `${error.field}: ${error.message}`);
}

/**
 * Get first error message for a specific field
 */
export function getFieldError(result: ValidationResult, field: string): string | null {
  const error = result.errors.find(e => e.field === field);
  return error ? error.message : null;
}

/**
 * Check if a field has any errors
 */
export function hasFieldError(result: ValidationResult, field: string): boolean {
  return result.errors.some(e => e.field === field);
}

/**
 * Get all errors, warnings, and infos grouped by field
 */
export function groupErrorsByField(result: ValidationResult): Record<string, ValidationFieldError[]> {
  const grouped: Record<string, ValidationFieldError[]> = {};
  
  [...result.errors, ...result.warnings, ...result.infos].forEach(error => {
    if (!grouped[error.field]) {
      grouped[error.field] = [];
    }
    grouped[error.field].push(error);
  });
  
  return grouped;
}

/**
 * Wizard Service
 *
 * Handles launching wizards from the UI by executing CLI commands
 */

import { WizardDefinition } from '../../types/configuration';
import { getComfyUIServersService } from '../comfyuiServersService';
import { testComfyUIConnection } from '../comfyuiService';
import { OLLAMA_URL, COMFYUI_URL } from '../../config/apiConfig';
import { logger } from '@/utils/logger';
import {
  CharacterWizardInput,
  SceneGeneratorInput,
  StoryboardInput,
  DialogueInput,
  WorldBuildingInput,
  StyleTransferInput,
  WizardOutput
} from './types';

export interface WizardLaunchResult {
  success: boolean;
  message: string;
  output?: string;
  error?: string;
}

export interface ConnectionStatus {
  connected: boolean;
  service: 'ollama' | 'comfyui';
  endpoint: string;
  error?: string;
}

export class WizardService {
  /**
   * Launch a wizard by executing its CLI command
   */
  async launchWizard(
    wizardId: string,
    projectPath?: string,
    options: Record<string, unknown> = {}
  ): Promise<WizardLaunchResult> {
    try {
      // Map wizard IDs to CLI commands
      const command = this.getWizardCommand(wizardId, options);

      if (!command) {
        return {
          success: false,
          message: `Unknown wizard: ${wizardId}`,
          error: 'Wizard not implemented'
        };
      }

      // Execute the command
      const result = await this.executeCommand(command, projectPath);

      return {
        success: result.success,
        message: result.success ? 'Wizard launched successfully' : 'Failed to launch wizard',
        output: result.output,
        error: result.error
      };

    } catch (error) {
      logger.error(`Failed to launch wizard ${wizardId}:`, error);
      return {
        success: false,
        message: 'Failed to launch wizard',
        error: error instanceof Error ? error.message : 'Unknown error'
      };
    }
  }

  /**
   * Get the CLI command for a wizard
   */
  private getWizardCommand(wizardId: string, options: Record<string, unknown>): string | null {
    const commands: Record<string, string> = {
      'project-init': 'storycore init',
      'world-building': 'storycore world-wizard',
      'character-creation': 'storycore character-wizard',
      'shot-planning': 'storycore shot-planning',
      'shot-reference-wizard': this.buildShotReferenceCommand(options),
      'dialogue-wizard': this.buildDialogueCommand(options),
      'scene-generator': 'storycore scene-generator',
      'storyboard-creator': 'storycore storyboard-creator',
      'style-transfer-wizard': this.buildStyleTransferCommand(options),
      'style-transfer': 'storycore style-transfer'
    };

    return commands[wizardId] || null;
  }

  /**
   * Build shot reference wizard command with options
   */
  private buildShotReferenceCommand(options: Record<string, unknown>): string {
    let command = 'storycore shot-reference-wizard';

    if (options.style && typeof options.style === 'string') {
      command += ` --style ${options.style}`;
    }

    if (options.quality && typeof options.quality === 'string') {
      command += ` --quality ${options.quality}`;
    }

    if (options.shots && Array.isArray(options.shots)) {
      command += ` --shots ${(options.shots as string[]).join(' ')}`;
    }

    if (options.preview) {
      command += ' --preview';
    }

    return command;
  }

  /**
   * Build dialogue wizard command with options
   */
  private buildDialogueCommand(options: Record<string, unknown>): string {
    let command = 'storycore dialogue-wizard';

    if (options.quick && options.characters && options.topic) {
      const characters = Array.isArray(options.characters) ? options.characters : [options.characters];
      const topic = typeof options.topic === 'string' ? options.topic : String(options.topic);
      command += ` --quick --characters ${characters.join(' ')} --topic "${topic}"`;
    } else if (options.interactive) {
      command += ' --interactive';
    } else {
      // Default to interactive mode
      command += ' --interactive';
    }

    if (options.tone && typeof options.tone === 'string') {
      command += ` --tone ${options.tone}`;
    }

    if (options.purpose && typeof options.purpose === 'string') {
      command += ` --purpose ${options.purpose}`;
    }

    return command;
  }

  /**
   * Build style transfer wizard command with options
   */
  private buildStyleTransferCommand(options: Record<string, unknown>): string {
    let command = 'storycore style-transfer-wizard';

    // Mode selection
    if (options.mode) {
      command += ` --mode ${options.mode}`;
    }

    // Source image
    if (options.sourceImage) {
      command += ` --source "${options.sourceImage}"`;
    }

    // Style reference (for workflow mode)
    if (options.styleImage) {
      command += ` --style "${options.styleImage}"`;
    }

    // Prompt (for prompt mode)
    if (options.prompt) {
      command += ` --prompt "${options.prompt}"`;
    }

    // Configuration options
    if (options.steps) {
      command += ` --steps ${options.steps}`;
    }

    if (options.cfgScale) {
      command += ` --cfg ${options.cfgScale}`;
    }

    if (options.seed !== undefined && options.seed !== -1) {
      command += ` --seed ${options.seed}`;
    }

    if (options.outputPrefix) {
      command += ` --output "${options.outputPrefix}"`;
    }

    // Model configuration
    if (options.modelName) {
      command += ` --model "${options.modelName}"`;
    }

    return command;
  }

  /**
   * Execute a command via Electron API
   */
  private async executeCommand(command: string, projectPath?: string): Promise<WizardLaunchResult> {
    if (!window.electronAPI?.executeCommand) {
      return {
        success: false,
        message: 'Command execution not available',
        error: 'Electron API not available'
      };
    }

    try {
      // Change to project directory if specified
      const fullCommand = projectPath
        ? `cd "${projectPath}" && ${command}`
        : command;


      const result = await window.electronAPI.executeCommand({
        command: fullCommand,
        cwd: projectPath || process.cwd(),
        shell: true
      });

      return {
        success: result.success,
        message: result.success ? 'Command executed successfully' : 'Command failed',
        output: result.output,
        error: result.error
      };

    } catch (error) {
      logger.error('Command execution error:', error);
      return {
        success: false,
        message: 'Command execution failed',
        error: error instanceof Error ? error.message : 'Unknown error'
      };
    }
  }

  /**
   * Check Ollama connection status
   */
  async checkOllamaConnection(): Promise<ConnectionStatus> {
    const ollamaEndpoint = OLLAMA_URL;
    try {
      // Try to connect to Ollama API
      const response = await fetch(`${ollamaEndpoint}/api/tags`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
        signal: AbortSignal.timeout(5000) // 5 second timeout
      });

      if (response.ok) {
        return {
          connected: true,
          service: 'ollama',
          endpoint: ollamaEndpoint
        };
      } else {
        return {
          connected: false,
          service: 'ollama',
          endpoint: ollamaEndpoint,
          error: `HTTP ${response.status}: ${response.statusText}`
        };
      }
    } catch (error) {
      return {
        connected: false,
        service: 'ollama',
        endpoint: ollamaEndpoint,
        error: error instanceof Error ? error.message : 'Connection failed'
      };
    }
  }

  /**
   * Check ComfyUI connection status using ComfyUI Servers Service
   * Note: ComfyUI is an OPTIONAL service - connection failures are expected and should be silent
   */
  async checkComfyUIConnection(): Promise<ConnectionStatus> {
    try {
      // Get the ComfyUI Servers Service
      const comfyuiServersService = getComfyUIServersService();

      // Try to get an available server
      const availableServer = await comfyuiServersService.getAvailableServer();

      if (availableServer) {
        // Test the connection using the ComfyUI service
        const testResult = await testComfyUIConnection({
          serverUrl: availableServer.serverUrl,
          authentication: availableServer.authentication,
          timeout: availableServer.timeout,
        });

        if (testResult.success) {
          return {
            connected: true,
            service: 'comfyui',
            endpoint: availableServer.serverUrl
          };
        } else {
          // ComfyUI not running - this is expected for optional service
          return {
            connected: false,
            service: 'comfyui',
            endpoint: availableServer.serverUrl,
            error: testResult.message
          };
        }
      } else {
        // No servers configured - return disconnected silently
        return {
          connected: false,
          service: 'comfyui',
          endpoint: '',
          error: 'No ComfyUI server configured'
        };
      }
    } catch (error) {
      // ComfyUI connection failed - this is OK for optional service
      return {
        connected: false,
        service: 'comfyui',
        endpoint: COMFYUI_URL,
        error: error instanceof Error ? error.message : 'Connection failed'
      };
    }
  }

  /**
