          narrative_function: 'Hero',
          character_arc: 'Growth',
        },
      };

      useStore.getState().addCharacter(char);

      // Add a relationship
      useStore.getState().updateCharacter('char-1', {
        relationships: [
          {
            character_id: 'char-2',
            character_name: 'Bob',
            relationship_type: 'Friend',
            description: 'New friend',
            dynamic: 'Supportive',
          },
