        // ====================================================================
        // Story Actions
        // ====================================================================
        addStory: (story) =>
          set((state) => {
            const newStories = [...state.stories, story];

            // Persist to localStorage
            if (state.project) {
              try {
                StorageManager.setItem(
                  `project-${state.project.project_name}-stories`,
