    });

    it('should undo operation', () => {
      const { pushOperation, undo } = useUndoRedoStore.getState();
      
      const operation = createOperation(
        'transform',
        'Move panel',
        'panel-0-0',
        { x: 0, y: 0 },
        { x: 100, y: 100 }
      );
      
      pushOperation(operation);
      
      const undoneOp = undo();
      
