/**
 * Editor Store - Zustand store for editor-wizard-integration feature
 * 
 * This store manages:
 * - Project state (currentProject, projectPath)
 * - Wizard state (activeWizard, wizardHistory)
 * - Asset state (assets, selectedAssetId)
 * - Shot state (shots, selectedShotId)
 * 
 * Integrates with:
 * - WizardService for wizard execution
 * - AssetService for asset import
 * - ProjectService for project data operations
 * 
 * Requirements: All requirements - state management foundation
 */

import { create } from 'zustand';
import type { Shot } from '../types';
import type {
  ProjectData,
  ShotInput,
} from '../types/project';
import type { AssetMetadata, ImportResult } from '../types/asset';
import type {
  WizardOutput,
  CharacterWizardInput,
  SceneGeneratorInput,
  StoryboardInput,
  DialogueInput,
  WorldBuildingInput,
  StyleTransferInput,
  ConnectionStatus,
} from '../services/wizard/types';
import { WizardService } from '../services/wizard/WizardService';
import { AssetService } from '../services/assets/AssetService';
import { ProjectService } from '../services/project/ProjectService';

/**
 * Wizard state interface
 */
interface WizardState {
  wizardId: string;
  currentStep: number;
  totalSteps: number;
  formData: Record<string, unknown>;
  connectionStatus: {
    ollama: ConnectionStatus | null;
    comfyui: ConnectionStatus | null;
  };
  generationStatus: {
    inProgress: boolean;
    progress: number;
    stage: string;
    error?: string;
  };
  preservedData?: {
    timestamp: number; // timestamp in ms
    data: Record<string, unknown>;
  };
}

/**
 * Editor store state interface
 */
interface EditorStore {
  // Project state
  currentProject: ProjectData | null;
  projectPath: string | null;

  // Wizard state
  activeWizard: WizardState | null;
  wizardHistory: WizardState[];

  // Asset state
  assets: AssetMetadata[];
  selectedAssetId: string | null;

  // Shot state
  shots: Shot[];
  selectedShotId: string | null;

  // Service instances
  wizardService: WizardService;
  assetService: AssetService;
  projectService: ProjectService;

  // Project actions
  loadProject: (path: string) => Promise<void>;
  saveProject: () => Promise<void>;
  setProjectPath: (path: string | null) => void;

  // Wizard actions
  openWizard: (wizardId: string, totalSteps: number) => void;
  closeWizard: () => void;
  updateWizardState: (updates: Partial<WizardState>) => void;
  setWizardStep: (step: number) => void;
  setWizardFormData: (data: Record<string, unknown>) => void;
  updateWizardConnectionStatus: (service: 'ollama' | 'comfyui', status: ConnectionStatus) => void;
  setWizardGenerationStatus: (status: Partial<WizardState['generationStatus']>) => void;
  completeWizard: (output: WizardOutput) => Promise<void>;
  preserveWizardSession: () => void;
  restoreWizardSession: (wizardId: string) => boolean;

  // Wizard execution actions
  executeCharacterWizard: (input: CharacterWizardInput) => Promise<WizardOutput>;
  executeSceneGenerator: (input: SceneGeneratorInput) => Promise<WizardOutput>;
  executeStoryboardCreator: (input: StoryboardInput) => Promise<WizardOutput>;
  executeDialogueWriter: (input: DialogueInput) => Promise<WizardOutput>;
  executeWorldBuilder: (input: WorldBuildingInput) => Promise<WizardOutput>;
  executeStyleTransfer: (input: StyleTransferInput) => Promise<WizardOutput>;

  // Asset actions
  importAssets: (files: File[], onProgress?: (current: number, total: number, filename: string) => void) => Promise<ImportResult[]>;
  selectAsset: (assetId: string | null) => void;
  refreshAssets: () => Promise<void>;

  // Shot actions
  createShot: (shotData: ShotInput) => Promise<Shot>;
  updateShot: (shotId: string, updates: Partial<Shot>) => Promise<void>;
  deleteShot: (shotId: string) => Promise<void>;
  selectShot: (shotId: string | null) => void;
  reorderShots: (shotIds: string[]) => Promise<void>;
  refreshShots: () => Promise<void>;

  // Connection check actions
  checkOllamaConnection: () => Promise<ConnectionStatus>;
  checkComfyUIConnection: () => Promise<ConnectionStatus>;
  checkAllConnections: () => Promise<{ ollama: ConnectionStatus; comfyui: ConnectionStatus; allConnected: boolean }>;
}

/**
 * Create editor store with Zustand
 */
export const useEditorStore = create<EditorStore>((set, get) => ({
  // Initial state
  currentProject: null,
  projectPath: null,
  activeWizard: null,
  wizardHistory: [],
  assets: [],
  selectedAssetId: null,
  shots: [],
  selectedShotId: null,

  // Service instances
  wizardService: new WizardService(),
  assetService: new AssetService(),
  projectService: new ProjectService(),

  // ============================================================================
  // Project Actions
  // ============================================================================

  loadProject: async (path: string) => {
    try {
      const { projectService } = get();
      const project = await projectService.loadProject(path);

      set({
        currentProject: project,
        projectPath: path,
        shots: project.storyboard || [],
        assets: project.assets || [],
      });

    } catch (error) {
      console.error('Failed to load project:', error);
      throw error;
    }
  },

  saveProject: async () => {
    try {
      const { currentProject, projectPath, projectService } = get();

      if (!currentProject || !projectPath) {
        throw new Error('No project loaded');
      }

      await projectService.saveProject(projectPath, currentProject);
    } catch (error) {
      console.error('Failed to save project:', error);
      throw error;
    }
  },

  setProjectPath: (path: string | null) => {
    set({ projectPath: path });
  },

  // ============================================================================
  // Wizard Actions
  // ============================================================================

  openWizard: (wizardId: string, totalSteps: number) => {
    // Check for preserved session
    const preserved = get().restoreWizardSession(wizardId);

    if (!preserved) {
      set({
        activeWizard: {
          wizardId,
          currentStep: 0,
          totalSteps,
          formData: {},
          connectionStatus: {
            ollama: null,
            comfyui: null,
          },
          generationStatus: {
            inProgress: false,
            progress: 0,
            stage: '',
          },
        },
      });
    }

  },

  closeWizard: () => {
    const { activeWizard } = get();

    if (activeWizard) {
      // Preserve session before closing
      get().preserveWizardSession();

      // Add to history
      set((state) => ({
        wizardHistory: [...state.wizardHistory, activeWizard],
        activeWizard: null,
      }));

    }
  },

  updateWizardState: (updates: Partial<WizardState>) => {
    set((state) => ({
      activeWizard: state.activeWizard
        ? { ...state.activeWizard, ...updates }
        : null,
    }));
  },

  setWizardStep: (step: number) => {
    set((state) => ({
      activeWizard: state.activeWizard
        ? { ...state.activeWizard, currentStep: step }
        : null,
    }));
  },

  setWizardFormData: (data: Record<string, unknown>) => {
    set((state) => ({
      activeWizard: state.activeWizard
        ? { ...state.activeWizard, formData: data }
        : null,
    }));
  },

  updateWizardConnectionStatus: (service: 'ollama' | 'comfyui', status: ConnectionStatus) => {
    set((state) => ({
      activeWizard: state.activeWizard
        ? {
          ...state.activeWizard,
          connectionStatus: {
            ...state.activeWizard.connectionStatus,
            [service]: status,
          },
        }
        : null,
    }));
  },

  setWizardGenerationStatus: (status: Partial<WizardState['generationStatus']>) => {
    set((state) => ({
      activeWizard: state.activeWizard
        ? {
          ...state.activeWizard,
          generationStatus: {
            ...state.activeWizard.generationStatus,
            ...status,
          },
        }
        : null,
    }));
  },

  completeWizard: async (output: WizardOutput) => {
    try {
      const { projectPath, projectService, currentProject } = get();

      if (!projectPath || !currentProject) {
        throw new Error('No project loaded');
      }

      // Save wizard output files
      // This would typically involve writing files to the project directory
      // For now, we'll update the project data structure

      // Update project based on wizard type
      const data = output.data as any;
      switch (output.type) {
        case 'character':
          // Add character to project
          if (!currentProject.characters) {
            currentProject.characters = [];
          }
          currentProject.characters.push({
            id: data.id,
            name: data.name,
            reference_image_path: output.files[0]?.path || '',
            created_at: data.created_at,
          });
          break;

        case 'scene':
          // Add scene and shots to project
          if (!currentProject.scenes) {
            currentProject.scenes = [];
          }
          currentProject.scenes.push(data);

          // Add shots to storyboard
          if (data.shots && data.shots.length > 0) {
            await projectService.addShotsToStoryboard(projectPath, data.shots);
          }
          break;

        case 'storyboard':
          // Add or replace shots based on mode
          if (data.mode === 'replace') {
            currentProject.storyboard = data.shots;
          } else {
            await projectService.addShotsToStoryboard(projectPath, data.shots);
          }
          break;

        case 'dialogue':
          // Update shots with dialogue tracks
          // This would typically update specific shots
          break;

        case 'world':
          // Set world definition
          currentProject.world = data;
          break;

        case 'style':
          // Update shot with styled image
          await projectService.updateShot(projectPath, data.original_shot_id, {
            image: output.files[0]?.path,
          });
          break;
      }

      // Update capabilities
      await projectService.updateCapabilities(projectPath, {
        wizard_generation: true,
      });

      // Update generation status
      await projectService.updateGenerationStatus(projectPath, {
        wizard: 'done',
      });

      // Refresh state
      await get().loadProject(projectPath);

      // Close wizard
      get().closeWizard();

    } catch (error) {
      console.error('Failed to complete wizard:', error);
      throw error;
    }
  },

  preserveWizardSession: () => {
    const { activeWizard } = get();

    if (activeWizard) {
      const preservedData = {
        timestamp: Date.now(),
        data: activeWizard.formData,
      };

      // Store in localStorage with 24-hour expiration
      const storageKey = `wizard_session_${activeWizard.wizardId}`;
      localStorage.setItem(storageKey, JSON.stringify(preservedData));

    }
  },

  restoreWizardSession: (wizardId: string): boolean => {
    const storageKey = `wizard_session_${wizardId}`;
    const stored = localStorage.getItem(storageKey);

    if (!stored) {
      return false;
    }

    try {
      const preservedData = JSON.parse(stored);
      const timestamp = preservedData.timestamp;
      const now = Date.now();
      const hoursDiff = (now - timestamp) / (1000 * 60 * 60);

      // Check if session is within 24 hours
      if (hoursDiff > 24) {
        localStorage.removeItem(storageKey);
        return false;
      }

      // Restore wizard state
      set({
        activeWizard: {
          wizardId,
          currentStep: 0,
          totalSteps: 0, // Will be set by wizard component
          formData: preservedData.data,
          connectionStatus: {
            ollama: null,
            comfyui: null,
          },
          generationStatus: {
            inProgress: false,
            progress: 0,
            stage: '',
          },
          preservedData,
        },
      });

      return true;
    } catch (error) {
      console.error('Failed to restore wizard session:', error);
      localStorage.removeItem(storageKey);
      return false;
    }
  },

  // ============================================================================
  // Wizard Execution Actions
  // ============================================================================

  executeCharacterWizard: async (input: CharacterWizardInput) => {
    const { wizardService } = get();
    return await wizardService.executeCharacterWizard(input);
  },

  executeSceneGenerator: async (input: SceneGeneratorInput) => {
    const { wizardService } = get();
    return await wizardService.executeSceneGenerator(input);
  },

  executeStoryboardCreator: async (input: StoryboardInput) => {
    const { wizardService } = get();
    return await wizardService.executeStoryboardCreator(input);
  },

  executeDialogueWriter: async (input: DialogueInput) => {
    const { wizardService } = get();
    return await wizardService.executeDialogueWriter(input);
  },

  executeWorldBuilder: async (input: WorldBuildingInput) => {
    const { wizardService } = get();
    return await wizardService.executeWorldBuilder(input);
  },

  executeStyleTransfer: async (input: StyleTransferInput) => {
    const { wizardService } = get();
    return await wizardService.executeStyleTransfer(input);
  },

  // ============================================================================
  // Asset Actions
  // ============================================================================

  importAssets: async (files: File[], onProgress?: (current: number, total: number, filename: string) => void) => {
    try {
      const { assetService, projectPath } = get();

      if (!projectPath) {
        throw new Error('No project loaded');
      }

      const results = await assetService.importAssets(files, projectPath, onProgress);

      // Refresh assets
      await get().refreshAssets();

      return results;
    } catch (error) {
      console.error('Failed to import assets:', error);
      throw error;
    }
  },

  selectAsset: (assetId: string | null) => {
    set({ selectedAssetId: assetId });
  },

  refreshAssets: async () => {
    try {
      const { assetService, projectPath } = get();

      if (!projectPath) {
        return;
      }

      const assets = await assetService.getAllAssets(projectPath);
      set({ assets });
    } catch (error) {
      console.error('Failed to refresh assets:', error);
    }
  },

  // ============================================================================
  // Shot Actions
  // ============================================================================

  createShot: async (shotData: ShotInput) => {
    try {
      const { projectService, projectPath, currentProject } = get();

      if (!currentProject) {
        throw new Error('No project loaded');
      }

      // If we have a projectPath, use the service to persist
      if (projectPath) {
        const shot = await projectService.createShot(projectPath, shotData);

        // Refresh shots
        await get().refreshShots();

        // Auto-select new shot
        set({ selectedShotId: shot.id });

        return shot;
      } else {
        // For in-memory projects (JSON-loaded), create shot directly
        const shot: Shot = {
          id: crypto.randomUUID(),
          title: shotData.title || `Shot ${(currentProject.storyboard?.length || 0) + 1}`,
          position: shotData.number || (currentProject.storyboard?.length || 0) + 1,
          description: shotData.description || '',
          duration: shotData.duration || 3,
          effects: [],
          audioTracks: [],
          textLayers: [],
          animations: [],

        };

        // Update current project
        const updatedProject = {
          ...currentProject,
          storyboard: [...(currentProject.storyboard || []), shot],
        };

        set({
          currentProject: updatedProject,
          shots: updatedProject.storyboard || [],
          selectedShotId: shot.id,
        });

        return shot;
      }
    } catch (error) {
      console.error('Failed to create shot:', error);
      throw error;
    }
  },

  updateShot: async (shotId: string, updates: Partial<Shot>) => {
    try {
      const { projectService, projectPath, currentProject, shots } = get();

      if (!currentProject) {
        throw new Error('No project loaded');
      }

      // If we have a projectPath, use the service to persist
      if (projectPath) {
        // Find the shot to get its sequence ID
        const shot = shots.find(s => s.id === shotId);

        if (shot && (shot as any).sequencePlanId) {
          // This is a ProductionShot with sequence information
          const sequenceId = (shot as any).sequencePlanId;

          // Use the new sequence IPC method to update the shot in its sequence file
          if (window.electronAPI?.sequence) {
            try {
              await window.electronAPI.sequence.updateShot(projectPath, sequenceId, shotId, updates);
            } catch (error) {
              console.warn('Failed to update shot in sequence file, falling back to project service:', error);
              await projectService.updateShot(projectPath, shotId, updates);
            }
          } else {
            // Fallback to old method if sequence API not available
            await projectService.updateShot(projectPath, shotId, updates);
          }
        } else {
          // Regular shot without sequence information, use old method
          await projectService.updateShot(projectPath, shotId, updates);
        }

        // Refresh shots
        await get().refreshShots();
      } else {
        // For in-memory projects, update shot directly
        const updatedStoryboard = (currentProject.storyboard || []).map(shot =>
          shot.id === shotId ? { ...shot, ...updates } : shot
        );

        const updatedProject = {
          ...currentProject,
          storyboard: updatedStoryboard,
        };

        set({
          currentProject: updatedProject,
          shots: updatedStoryboard,
        });

      }
    } catch (error) {
      console.error('Failed to update shot:', error);
      throw error;
    }
  },

  deleteShot: async (shotId: string) => {
    try {
      const { projectService, projectPath, currentProject, selectedShotId } = get();

      if (!currentProject) {
        throw new Error('No project loaded');
      }

      // If we have a projectPath, use the service to persist
      if (projectPath) {
        await projectService.deleteShot(projectPath, shotId);

        // Refresh shots
        await get().refreshShots();
      } else {
        // For in-memory projects, delete shot directly
        const updatedStoryboard = (currentProject.storyboard || []).filter(
          shot => shot.id !== shotId
        );

        const updatedProject = {
          ...currentProject,
          storyboard: updatedStoryboard,
        };

        set({
          currentProject: updatedProject,
          shots: updatedStoryboard,
          selectedShotId: selectedShotId === shotId ? null : selectedShotId,
        });

      }
    } catch (error) {
      console.error('Failed to delete shot:', error);
      throw error;
    }
  },

  selectShot: (shotId: string | null) => {
    set({ selectedShotId: shotId });
  },

  reorderShots: async (shotIds: string[]) => {
    try {
      const { projectService, projectPath, currentProject } = get();

      if (!currentProject) {
        throw new Error('No project loaded');
      }

      // If we have a projectPath, use the service to persist
      if (projectPath) {
        await projectService.reorderShots(projectPath, shotIds);

        // Refresh shots
        await get().refreshShots();
      } else {
        // For in-memory projects, reorder shots directly
        const shotMap = new Map((currentProject.storyboard || []).map(shot => [shot.id, shot]));
        const reorderedStoryboard = shotIds
          .map(id => shotMap.get(id))
          .filter((shot): shot is Shot => shot !== undefined);

        const updatedProject = {
          ...currentProject,
          storyboard: reorderedStoryboard,
        };

        set({
          currentProject: updatedProject,
          shots: reorderedStoryboard,
        });

      }
    } catch (error) {
      console.error('Failed to reorder shots:', error);
      throw error;
    }
  },

  refreshShots: async () => {
    try {
      const { projectPath } = get();

      if (!projectPath) {
        return;
      }

      // Reload project to get updated shots
      await get().loadProject(projectPath);
    } catch (error) {
      console.error('Failed to refresh shots:', error);
    }
  },

  // ============================================================================
  // Connection Check Actions
  // ============================================================================

  checkOllamaConnection: async () => {
    const { wizardService } = get();
    return await wizardService.checkOllamaConnection();
  },

  checkComfyUIConnection: async () => {
    const { wizardService } = get();
    return await wizardService.checkComfyUIConnection();
  },

  checkAllConnections: async () => {
    const { wizardService } = get();
    return await wizardService.checkAllConnections();
  },
}));

/**
 * Generation Store - Zustand store for generation-buttons-ui feature
 * 
 * This store manages:
 * - Pipeline state (currentPipeline, stages)
 * - Queue management (tasks, activeTask)
 * - History tracking (delegated to GenerationHistoryService)
 * - Asset associations (relatedAssets graph)
 * 
 * Requirements: 6.1, 6.2, 6.3, 6.4
 */

import { create } from 'zustand';
import { generationHistoryService } from '../services/GenerationHistoryService';
import { PipelineStateMachine } from '../services/PipelineStateMachine';
import type { PipelineStage } from '../services/PipelineStateMachine';
import type {
  GenerationPipelineState,
  GenerationQueue,
  GenerationTask,
  GeneratedAsset,
  GeneratedPrompt,
  GenerationHistory,
  HistoryEntry,
  StageState,
  GenerationProgress,
  BatchGenerationConfig,
  BatchGenerationTask,
  BatchGenerationState,
} from '../types/generation';

/**
 * Asset graph for tracking relationships
 */
interface AssetGraph {
  nodes: Map<string, GeneratedAsset>;
  edges: Map<string, string[]>; // assetId -> [relatedAssetIds]
}

/**
 * Generation store state interface
 */
interface GenerationStore {
  // Pipeline state
  currentPipeline: GenerationPipelineState | null;
  
  // Queue management
  queue: GenerationQueue;
  
  // Batch generation state
  batchConfig: BatchGenerationConfig;
  activeBatch: BatchGenerationState | null;
  batchHistory: BatchGenerationState[];
  
  // History (delegated to GenerationHistoryService)
  // Use generationHistoryService for history operations
  
  // Asset graph
  assetGraph: AssetGraph;
  
  // Actions - Pipeline Management
  startPipeline: () => string;
  completeStage: (stage: 'prompt' | 'image' | 'video' | 'audio', result: GeneratedPrompt | GeneratedAsset) => void;
  failStage: (stage: 'prompt' | 'image' | 'video' | 'audio', error: string) => void;
  skipStage: (stage: 'prompt' | 'image' | 'video' | 'audio') => void;
  updateStageProgress: (stage: 'prompt' | 'image' | 'video' | 'audio', progress: GenerationProgress) => void;
  resetPipeline: () => void;
  
  // Actions - Pipeline State Machine
  progressToNextStage: () => void;
  restartFromStage: (stage: PipelineStage) => void;
  getAvailableActions: () => ReturnType<typeof PipelineStateMachine.getAvailableActions>;
  getPipelineProgress: () => number;
  getAllPipelineAssets: () => ReturnType<typeof PipelineStateMachine.getAllAssets>;
  
  // Actions - Queue Management
  addToQueue: (task: Omit<GenerationTask, 'id' | 'createdAt' | 'status' | 'progress'>) => string;
  removeFromQueue: (taskId: string) => void;
  updateTaskStatus: (taskId: string, status: GenerationTask['status']) => void;
  updateTaskProgress: (taskId: string, progress: GenerationProgress) => void;
  completeTask: (taskId: string, result: GeneratedAsset) => void;
  failTask: (taskId: string, error: string) => void;
  cancelTask: (taskId: string) => void;
  clearQueue: () => void;
  reorderQueue: (taskId: string, newIndex: number) => void;
  
  // Actions - Batch Generation Management
  setBatchConfig: (config: Partial<BatchGenerationConfig>) => void;
  startBatch: (type: 'image' | 'video' | 'audio', baseParams: Record<string, unknown>) => string;
  cancelBatch: (batchId: string) => void;
  updateBatchTaskStatus: (batchId: string, taskId: string, status: BatchGenerationTask['status']) => void;
  completeBatchTask: (batchId: string, taskId: string, result: GeneratedAsset) => void;
  failBatchTask: (batchId: string, taskId: string, error: string) => void;
  markAsFavorite: (batchId: string, assetId: string) => void;
  markAsDiscarded: (batchId: string, assetId: string) => void;
  clearBatchSelections: (batchId: string) => void;
  
  // Actions - History Management (delegated to service)
  // Use generationHistoryService.logGeneration() instead of addToHistory()
  // Use generationHistoryService.queryHistory() instead of getHistoryByType()
  // Use generationHistoryService.getEntriesByPipelineId() instead of getHistoryByPipeline()
  
  // Actions - Asset Graph Management
  linkAssets: (sourceId: string, targetId: string) => void;
  getRelatedAssets: (assetId: string) => GeneratedAsset[];
  addAssetToGraph: (asset: GeneratedAsset) => void;
  removeAssetFromGraph: (assetId: string) => void;
}

/**
 * Create initial stage state
 */
const createInitialStageState = <T>(): StageState<T> => ({
  status: 'pending',
  attempts: 0,
});

/**
 * Create initial pipeline state
 */
const createInitialPipeline = (): GenerationPipelineState => {
  const now = Date.now();
  return {
    id: crypto.randomUUID(),
    currentStage: 'prompt',
    stages: {
      prompt: createInitialStageState<GeneratedPrompt>(),
      image: createInitialStageState<GeneratedAsset>(),
      video: createInitialStageState<GeneratedAsset>(),
      audio: createInitialStageState<GeneratedAsset>(),
    },
    createdAt: now,
    updatedAt: now,
  };
};

/**
 * Create generation store with Zustand
 */
export const useGenerationStore = create<GenerationStore>((set, get) => ({
  // Initial state
  currentPipeline: null,
  queue: {
    tasks: [],
    activeTask: null,
    maxConcurrent: 1,
  },
  batchConfig: {
    enabled: false,
    batchSize: 4,
    variationParams: {
      varySeeds: true,
      varyPrompts: false,
      varyParameters: false,
    },
  },
  activeBatch: null,
  batchHistory: [],
  assetGraph: {
    nodes: new Map(),
    edges: new Map(),
  },

  // ============================================================================
  // Pipeline Management Actions
  // ============================================================================

  startPipeline: () => {
    const pipeline = createInitialPipeline();
    set({ currentPipeline: pipeline });
    return pipeline.id;
  },

  completeStage: (stage, result) => {
    const state = get();
    if (!state.currentPipeline) return;

    const updatedPipeline = { ...state.currentPipeline };
    // Use type assertion to handle the union type assignment
    (updatedPipeline.stages[stage] as StageState<GeneratedPrompt | GeneratedAsset>) = {
      status: 'completed',
      result: result,
      attempts: updatedPipeline.stages[stage].attempts + 1,
    };

    // Determine next stage
    const stageOrder: Array<'prompt' | 'image' | 'video' | 'audio'> = ['prompt', 'image', 'video', 'audio'];
    const currentIndex = stageOrder.indexOf(stage);
    const nextStage = currentIndex < stageOrder.length - 1 ? stageOrder[currentIndex + 1] : 'complete';

    updatedPipeline.currentStage = nextStage as GenerationPipelineState['currentStage'];
    updatedPipeline.updatedAt = Date.now();

    set({ currentPipeline: updatedPipeline });

    // Add to history if result is an asset (using GenerationHistoryService)
    if ('url' in result) {
      generationHistoryService.logGeneration(
        updatedPipeline.id,
        stage as 'image' | 'video' | 'audio',
        result.metadata.generationParams,
        result as GeneratedAsset
      );

      // Add to asset graph
      get().addAssetToGraph(result as GeneratedAsset);
    }
  },

  failStage: (stage, error) => {
    const state = get();
    if (!state.currentPipeline) return;

    const updatedPipeline = { ...state.currentPipeline };
    (updatedPipeline.stages[stage] as StageState<GeneratedPrompt | GeneratedAsset>) = {
      ...updatedPipeline.stages[stage],
      status: 'failed',
      error,
      attempts: updatedPipeline.stages[stage].attempts + 1,
    };
    updatedPipeline.updatedAt = Date.now();

    set({ currentPipeline: updatedPipeline });
  },

  skipStage: (stage) => {
    const state = get();
    if (!state.currentPipeline) return;

    const updatedPipeline = { ...state.currentPipeline };
    (updatedPipeline.stages[stage] as StageState<GeneratedPrompt | GeneratedAsset>) = {
      ...updatedPipeline.stages[stage],
      status: 'skipped',
    };

    // Determine next stage
    const stageOrder: Array<'prompt' | 'image' | 'video' | 'audio'> = ['prompt', 'image', 'video', 'audio'];
    const currentIndex = stageOrder.indexOf(stage);
    const nextStage = currentIndex < stageOrder.length - 1 ? stageOrder[currentIndex + 1] : 'complete';

    updatedPipeline.currentStage = nextStage as GenerationPipelineState['currentStage'];
    updatedPipeline.updatedAt = Date.now();

    set({ currentPipeline: updatedPipeline });
  },

  updateStageProgress: (stage, progress) => {
    const state = get();
    if (!state.currentPipeline) return;

    const updatedPipeline = { ...state.currentPipeline };
    (updatedPipeline.stages[stage] as StageState<GeneratedPrompt | GeneratedAsset>) = {
      ...updatedPipeline.stages[stage],
      status: 'in_progress',
      progress,
    };
    updatedPipeline.updatedAt = Date.now();

    set({ currentPipeline: updatedPipeline });
  },

  resetPipeline: () => {
    set({ currentPipeline: null });
  },

  // ============================================================================
  // Pipeline State Machine Actions
  // ============================================================================

  progressToNextStage: () => {
    const state = get();
    if (!state.currentPipeline) return;

    const nextStage = PipelineStateMachine.getNextStage(state.currentPipeline.currentStage);
    if (!nextStage) return;

    const updatedPipeline = { ...state.currentPipeline };
    updatedPipeline.currentStage = nextStage;
    updatedPipeline.updatedAt = Date.now();

    set({ currentPipeline: updatedPipeline });
  },

  restartFromStage: (stage) => {
    const state = get();
    if (!state.currentPipeline) return;

    if (!PipelineStateMachine.canRestartFromStage(state.currentPipeline, stage)) {
      throw new Error(`Cannot restart from stage: ${stage}`);
    }

    const { clearSubsequent } = PipelineStateMachine.getRestartStage(state.currentPipeline, stage);
    const updatedPipeline = { ...state.currentPipeline };

    // Reset the target stage
    updatedPipeline.currentStage = stage;
    updatedPipeline.stages[stage as keyof typeof updatedPipeline.stages] = {
      status: 'pending',
      attempts: 0,
    };

    // Clear subsequent stages if needed
    if (clearSubsequent) {
      const allStages = PipelineStateMachine.getAllStages();
      const stageIndex = allStages.indexOf(stage);
      
      for (let i = stageIndex + 1; i < allStages.length; i++) {
        const stageToReset = allStages[i];
        if (stageToReset !== 'complete') {
          updatedPipeline.stages[stageToReset as keyof typeof updatedPipeline.stages] = {
            status: 'pending',
            attempts: 0,
          };
        }
      }
    }

    updatedPipeline.updatedAt = Date.now();
    set({ currentPipeline: updatedPipeline });
  },

  getAvailableActions: () => {
    const state = get();
    if (!state.currentPipeline) {
      return {
        canProgress: false,
        canSkip: false,
        canRestart: false,
        restartableStages: [],
      };
    }

    return PipelineStateMachine.getAvailableActions(state.currentPipeline);
  },

  getPipelineProgress: () => {
    const state = get();
    if (!state.currentPipeline) return 0;
    return PipelineStateMachine.calculateProgress(state.currentPipeline);
  },

  getAllPipelineAssets: () => {
    const state = get();
    if (!state.currentPipeline) {
      return {
        prompt: undefined,
        image: undefined,
        video: undefined,
        audio: undefined,
      };
    }

    return PipelineStateMachine.getAllAssets(state.currentPipeline);
  },

  // ============================================================================
  // Queue Management Actions
  // ============================================================================

  addToQueue: (taskData) => {
    const task: GenerationTask = {
      ...taskData,
      id: crypto.randomUUID(),
      createdAt: Date.now(),
      status: 'queued',
      progress: {
        stage: '',
        stageProgress: 0,
        overallProgress: 0,
        estimatedTimeRemaining: 0,
        message: 'Queued',
        cancellable: true,
      },
    };

    const state = get();
    set({
      queue: {
        ...state.queue,
        tasks: [...state.queue.tasks, task],
      },
    });

    return task.id;
  },

  removeFromQueue: (taskId) => {
    const state = get();
    set({
      queue: {
        ...state.queue,
        tasks: state.queue.tasks.filter(t => t.id !== taskId),
        activeTask: state.queue.activeTask === taskId ? null : state.queue.activeTask,
      },
    });
  },

  updateTaskStatus: (taskId, status) => {
    const state = get();
    const updatedTasks = state.queue.tasks.map(t =>
      t.id === taskId ? { ...t, status } : t
    );
    const activeTask = status === 'running' ? taskId : state.queue.activeTask;

    set({
      queue: {
        ...state.queue,
        tasks: updatedTasks,
        activeTask,
      },
    });
  },

  updateTaskProgress: (taskId, progress) => {
    const state = get();
    const updatedTasks = state.queue.tasks.map(t =>
      t.id === taskId ? { ...t, progress } : t
    );

    set({
      queue: {
        ...state.queue,
        tasks: updatedTasks,
      },
    });
  },

  completeTask: (taskId, result) => {
    const state = get();
    const updatedTasks = state.queue.tasks.map(t =>
      t.id === taskId
        ? { ...t, status: 'completed' as const, result, completedAt: Date.now() }
        : t
    );
    const activeTask = state.queue.activeTask === taskId ? null : state.queue.activeTask;

    set({
      queue: {
        ...state.queue,
        tasks: updatedTasks,
        activeTask,
      },
    });
  },

  failTask: (taskId, error) => {
    const state = get();
    const updatedTasks = state.queue.tasks.map(t =>
      t.id === taskId
        ? { ...t, status: 'failed' as const, error, completedAt: Date.now() }
        : t
    );
    const activeTask = state.queue.activeTask === taskId ? null : state.queue.activeTask;

    set({
      queue: {
        ...state.queue,
        tasks: updatedTasks,
        activeTask,
      },
    });
  },

  cancelTask: (taskId) => {
    const state = get();
    const updatedTasks = state.queue.tasks.map(t =>
      t.id === taskId
        ? { ...t, status: 'cancelled' as const, completedAt: Date.now() }
        : t
    );
    const activeTask = state.queue.activeTask === taskId ? null : state.queue.activeTask;

    set({
      queue: {
        ...state.queue,
        tasks: updatedTasks,
        activeTask,
      },
    });
  },

  clearQueue: () => {
    const state = get();
    set({
      queue: {
        ...state.queue,
        tasks: [],
        activeTask: null,
      },
    });
  },

  reorderQueue: (taskId, newIndex) => {
    const state = get();
    const tasks = [...state.queue.tasks];
    const currentIndex = tasks.findIndex(t => t.id === taskId);
    
    if (currentIndex === -1 || newIndex < 0 || newIndex >= tasks.length) {
      return;
    }

    const [task] = tasks.splice(currentIndex, 1);
    tasks.splice(newIndex, 0, task);

    set({
      queue: {
        ...state.queue,
        tasks,
      },
    });
  },

  // ============================================================================
  // Batch Generation Management Actions
  // ============================================================================

  setBatchConfig: (config) => {
    const state = get();
    set({
      batchConfig: {
        ...state.batchConfig,
        ...config,
      },
    });
  },

  startBatch: (type, baseParams) => {
    const state = get();
    const { batchConfig } = state;
    
    if (!batchConfig.enabled) {
      throw new Error('Batch generation is not enabled');
    }

    const batchId = crypto.randomUUID();
    const tasks: BatchGenerationTask[] = [];

    // Generate tasks based on batch configuration
    for (let i = 0; i < batchConfig.batchSize; i++) {
      const params = { ...baseParams };

      // Apply variations
      if (batchConfig.variationParams.varySeeds) {
        const seedRange = batchConfig.variationParams.seedRange || [0, 999999];
        params.seed = Math.floor(Math.random() * (seedRange[1] - seedRange[0] + 1)) + seedRange[0];
      }

      if (batchConfig.variationParams.varyPrompts && batchConfig.variationParams.promptVariations) {
        const variations = batchConfig.variationParams.promptVariations;
        params.prompt = variations[i % variations.length];
      }

      if (batchConfig.variationParams.varyParameters && batchConfig.variationParams.parameterRanges) {
        Object.entries(batchConfig.variationParams.parameterRanges).forEach(([key, [min, max]]) => {
          params[key] = Math.random() * (max - min) + min;
        });
      }

      tasks.push({
        id: crypto.randomUUID(),
        batchId,
        type,
        params,
        priority: 1,
        status: 'queued',
        progress: {
          stage: '',
          stageProgress: 0,
          overallProgress: 0,
          estimatedTimeRemaining: 0,
          message: 'Queued',
          cancellable: true,
        },
        createdAt: Date.now(),
        batchIndex: i,
      });
    }

    const batch: BatchGenerationState = {
      id: batchId,
      config: batchConfig,
      tasks,
      status: 'pending',
      completedCount: 0,
      failedCount: 0,
      results: [],
      favorites: new Set(),
      discarded: new Set(),
      createdAt: Date.now(),
    };

    set({ activeBatch: batch });
    return batchId;
  },

  cancelBatch: (batchId) => {
    const state = get();
    
    if (state.activeBatch?.id === batchId) {
      const cancelledBatch: BatchGenerationState = {
        ...state.activeBatch,
        status: 'cancelled',
        completedAt: Date.now(),
        tasks: state.activeBatch.tasks.map(t => 
          t.status === 'queued' || t.status === 'running'
            ? { ...t, status: 'cancelled' as const }
            : t
        ),
      };

      set({
        activeBatch: null,
        batchHistory: [...state.batchHistory, cancelledBatch],
      });
    }
  },

  updateBatchTaskStatus: (batchId, taskId, status) => {
    const state = get();
    
    if (state.activeBatch?.id !== batchId) return;

    const updatedTasks = state.activeBatch.tasks.map(t =>
      t.id === taskId ? { ...t, status, startedAt: status === 'running' ? Date.now() : t.startedAt } : t
    );

    set({
      activeBatch: {
        ...state.activeBatch,
        tasks: updatedTasks,
        status: updatedTasks.some(t => t.status === 'running') ? 'running' : state.activeBatch.status,
      },
    });
  },

  completeBatchTask: (batchId, taskId, result) => {
    const state = get();
    
    if (state.activeBatch?.id !== batchId) return;

    const updatedTasks = state.activeBatch.tasks.map(t =>
      t.id === taskId
        ? { ...t, status: 'completed' as const, result, completedAt: Date.now() }
        : t
    );

    const completedCount = updatedTasks.filter(t => t.status === 'completed').length;
    const failedCount = updatedTasks.filter(t => t.status === 'failed').length;
    const allDone = updatedTasks.every(t => 
      t.status === 'completed' || t.status === 'failed' || t.status === 'cancelled'
    );

    const updatedBatch: BatchGenerationState = {
      ...state.activeBatch,
      tasks: updatedTasks,
      completedCount,
      failedCount,
      results: [...state.activeBatch.results, result],
      status: allDone ? 'completed' : 'running',
      completedAt: allDone ? Date.now() : undefined,
    };

    // Add result to asset graph
    get().addAssetToGraph(result);

    // If batch is complete, move to history
    if (allDone) {
      set({
        activeBatch: null,
        batchHistory: [...state.batchHistory, updatedBatch],
      });
    } else {
      set({ activeBatch: updatedBatch });
    }
  },

  failBatchTask: (batchId, taskId, error) => {
    const state = get();
    
    if (state.activeBatch?.id !== batchId) return;

    const updatedTasks = state.activeBatch.tasks.map(t =>
      t.id === taskId
        ? { ...t, status: 'failed' as const, error, completedAt: Date.now() }
        : t
    );

    const completedCount = updatedTasks.filter(t => t.status === 'completed').length;
    const failedCount = updatedTasks.filter(t => t.status === 'failed').length;
    const allDone = updatedTasks.every(t => 
      t.status === 'completed' || t.status === 'failed' || t.status === 'cancelled'
    );

    const updatedBatch: BatchGenerationState = {
      ...state.activeBatch,
      tasks: updatedTasks,
      completedCount,
      failedCount,
      status: allDone ? (completedCount > 0 ? 'completed' : 'failed') : 'running',
      completedAt: allDone ? Date.now() : undefined,
    };

    // If batch is complete, move to history
    if (allDone) {
      set({
        activeBatch: null,
        batchHistory: [...state.batchHistory, updatedBatch],
      });
    } else {
      set({ activeBatch: updatedBatch });
    }
  },

  markAsFavorite: (batchId, assetId) => {
    const state = get();
    
    if (state.activeBatch?.id === batchId) {
      const favorites = new Set(state.activeBatch.favorites);
      const discarded = new Set(state.activeBatch.discarded);
      
      favorites.add(assetId);
      discarded.delete(assetId); // Remove from discarded if present

      set({
        activeBatch: {
          ...state.activeBatch,
          favorites,
          discarded,
        },
      });
    } else {
      // Check batch history
      const batchIndex = state.batchHistory.findIndex(b => b.id === batchId);
      if (batchIndex !== -1) {
        const updatedHistory = [...state.batchHistory];
        const batch = updatedHistory[batchIndex];
        const favorites = new Set(batch.favorites);
        const discarded = new Set(batch.discarded);
        
        favorites.add(assetId);
        discarded.delete(assetId);

        updatedHistory[batchIndex] = {
          ...batch,
          favorites,
          discarded,
        };

        set({ batchHistory: updatedHistory });
      }
    }
  },

  markAsDiscarded: (batchId, assetId) => {
    const state = get();
    
    if (state.activeBatch?.id === batchId) {
      const favorites = new Set(state.activeBatch.favorites);
      const discarded = new Set(state.activeBatch.discarded);
      
      discarded.add(assetId);
      favorites.delete(assetId); // Remove from favorites if present

      set({
        activeBatch: {
          ...state.activeBatch,
          favorites,
          discarded,
        },
      });
    } else {
      // Check batch history
      const batchIndex = state.batchHistory.findIndex(b => b.id === batchId);
      if (batchIndex !== -1) {
        const updatedHistory = [...state.batchHistory];
        const batch = updatedHistory[batchIndex];
        const favorites = new Set(batch.favorites);
        const discarded = new Set(batch.discarded);
        
        discarded.add(assetId);
        favorites.delete(assetId);

        updatedHistory[batchIndex] = {
          ...batch,
          favorites,
          discarded,
        };

        set({ batchHistory: updatedHistory });
      }
    }
  },

  clearBatchSelections: (batchId) => {
    const state = get();
    
    if (state.activeBatch?.id === batchId) {
      set({
        activeBatch: {
          ...state.activeBatch,
          favorites: new Set(),
          discarded: new Set(),
        },
      });
    } else {
      // Check batch history
      const batchIndex = state.batchHistory.findIndex(b => b.id === batchId);
      if (batchIndex !== -1) {
        const updatedHistory = [...state.batchHistory];
        updatedHistory[batchIndex] = {
          ...updatedHistory[batchIndex],
          favorites: new Set(),
          discarded: new Set(),
        };

        set({ batchHistory: updatedHistory });
      }
    }
  },

  // ============================================================================
  // Asset Graph Management Actions
  // ============================================================================

  linkAssets: (sourceId, targetId) => {
    const state = get();
    const edges = new Map(state.assetGraph.edges);
    const existing = edges.get(sourceId) || [];
    
    if (!existing.includes(targetId)) {
      edges.set(sourceId, [...existing, targetId]);
    }

    set({
      assetGraph: {
        ...state.assetGraph,
        edges,
      },
    });
  },

  getRelatedAssets: (assetId) => {
    const { assetGraph } = get();
    const relatedIds = assetGraph.edges.get(assetId) || [];
    return relatedIds
      .map(id => assetGraph.nodes.get(id))
      .filter((asset): asset is GeneratedAsset => asset !== undefined);
  },

  addAssetToGraph: (asset) => {
    const state = get();
    const nodes = new Map(state.assetGraph.nodes);
    nodes.set(asset.id, asset);

    set({
      assetGraph: {
        ...state.assetGraph,
        nodes,
      },
    });
  },

  removeAssetFromGraph: (assetId) => {
    const state = get();
    const nodes = new Map(state.assetGraph.nodes);
    const edges = new Map(state.assetGraph.edges);
    
    nodes.delete(assetId);
    edges.delete(assetId);
    
    // Remove from other assets' edges
    edges.forEach((targets, sourceId) => {
      const filtered = targets.filter(id => id !== assetId);
      if (filtered.length !== targets.length) {
        edges.set(sourceId, filtered);
      }
    });

    set({
      assetGraph: {
        nodes,
        edges,
      },
    });
  },
}));

/**
 * Preset Store - Manages grid layout presets
