export interface EditHistoryEntry {
  id: string;
  timestamp: number;
  segmentId: string;
  previousText: string;
  newText: string;
  type: 'text' | 'speaker' | 'segment_type' | 'timing';
}

export interface TranscriptionState {
  // Transcript state
  transcript: Transcript | null;
  transcriptId: string | null;
  audioId: string | null;
  audioUrl: string | null;
  language: string;
  
  // Loading and error state
