);

export const GeneratedShotSchema = z.object({
  shotId: z.string(),
  imageUrl: z.string(),
  qaScore: z.number().min(0).max(100),
  processingTime: z.number().nonnegative(),
});

export const QAReportSchema = z.object({
  overallScore: z.number().min(0).max(100),
