import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import {
  encryptValue,
  decryptValue,
  isEncrypted,
  saveLLMSettings,
  loadLLMSettings,
  deleteLLMSettings,
  exportSettings,
  importSettings,
