  // Neutral colors
  white: '#ffffff',
  black: '#000000',
  gray50: '#f9fafb',
  gray100: '#f3f4f6',
  gray200: '#e5e7eb',
  gray300: '#d1d5db',
  gray400: '#9ca3af',
  gray500: '#6b7280',
  gray600: '#4b5563',
  gray700: '#374151',
  gray800: '#1f2937',
  gray900: '#111827',

  // Status colors
  success: '#059669',
  warning: '#d97706',
  error: '#dc2626',
  info: '#0891b2',

  // Text colors
  textPrimary: '#111827',
  textSecondary: '#4b5563',
  textTertiary: '#9ca3af',
  textInverse: '#ffffff',

  // Background colors
  bgPrimary: '#ffffff',
  bgSecondary: '#f9fafb',
  bgTertiary: '#f3f4f6',
};

/**
 * Validate all colors in a palette
 */
export function validatePalette(
  palette: Record<string, string>,
  options: { level?: 'AA' | 'AAA' } = {}
): Record<string, unknown> {
  const results: Record<string, unknown> = {};

  // Check common text on background combinations
  const combinations = [
    { fg: 'textPrimary', bg: 'bgPrimary', name: 'Primary text on primary background' },
    { fg: 'textPrimary', bg: 'bgSecondary', name: 'Primary text on secondary background' },
    { fg: 'textSecondary', bg: 'bgPrimary', name: 'Secondary text on primary background' },
    { fg: 'textInverse', bg: 'primary', name: 'Inverse text on primary color' },
  ];

  combinations.forEach(({ fg, bg, name }) => {
    if (palette[fg] && palette[bg]) {
      results[name] = validateContrast(palette[fg], palette[bg], options);
    }
  });

  return results;
}

/**
 * Error Handling Utilities
 * 
 * Provides comprehensive error categorization, recovery strategies,
 * and user guidance for the generation pipeline.
 * 
 * Requirements: 8.1, 8.2, 8.3, 8.4, 8.5
 */

/**
 * Error categories for generation pipeline
 */
export const ErrorCategory = {
  SERVICE_UNAVAILABLE: 'service_unavailable',
  VALIDATION: 'validation',
  GENERATION: 'generation',
  TIMEOUT: 'timeout',
  FILE_SYSTEM: 'file_system',
  NETWORK: 'network',
  UNKNOWN: 'unknown',
} as const;

export type ErrorCategory = typeof ErrorCategory[keyof typeof ErrorCategory];

/**
 * Error severity levels
 */
export const ErrorSeverity = {
  LOW: 'low',
  MEDIUM: 'medium',
  HIGH: 'high',
  CRITICAL: 'critical',
} as const;

export type ErrorSeverity = typeof ErrorSeverity[keyof typeof ErrorSeverity];

/**
 * Recovery strategy types
 */
export const RecoveryStrategy = {
  RETRY: 'retry',
  RETRY_WITH_BACKOFF: 'retry_with_backoff',
  ADJUST_PARAMETERS: 'adjust_parameters',
  FALLBACK: 'fallback',
  USER_ACTION_REQUIRED: 'user_action_required',
  NONE: 'none',
} as const;

export type RecoveryStrategy = typeof RecoveryStrategy[keyof typeof RecoveryStrategy];

/**
 * Categorized error interface
 */
export interface CategorizedError {
  category: ErrorCategory;
  severity: ErrorSeverity;
  message: string;
  originalError: Error;
  userMessage: string;
  technicalDetails: string;
  recoveryStrategy: RecoveryStrategy;
  troubleshootingSteps: string[];
  canRetry: boolean;
  retryDelay?: number;
  suggestedParameters?: Record<string, unknown>;
}

/**
 * Error recovery result
 */
export interface RecoveryResult {
  success: boolean;
  message: string;
  shouldRetry: boolean;
  retryDelay?: number;
  adjustedParameters?: Record<string, unknown>;
}

/**
 * Error categorization patterns
 */
const ERROR_PATTERNS = {
  [ErrorCategory.SERVICE_UNAVAILABLE]: [
    /service.*unavailable/i,
    /connection.*refused/i,
    /ECONNREFUSED/i,
    /not.*configured/i,
    /server.*not.*responding/i,
    /ComfyUI.*not.*available/i,
    /TTS.*service.*unavailable/i,
  ],
  [ErrorCategory.VALIDATION]: [
    /invalid.*parameter/i,
    /validation.*failed/i,
    /out.*of.*range/i,
    /required.*field/i,
    /must.*be/i,
    /cannot.*be.*empty/i,
  ],
  [ErrorCategory.GENERATION]: [
    /generation.*failed/i,
    /workflow.*error/i,
    /processing.*error/i,
    /model.*error/i,
    /inference.*failed/i,
  ],
  [ErrorCategory.TIMEOUT]: [
    /timeout/i,
    /timed.*out/i,
    /exceeded.*time/i,
    /took.*too.*long/i,
  ],
  [ErrorCategory.FILE_SYSTEM]: [
    /ENOENT/i,
    /EACCES/i,
    /EPERM/i,
    /disk.*space/i,
    /permission.*denied/i,
    /file.*not.*found/i,
    /cannot.*write/i,
    /cannot.*read/i,
  ],
  [ErrorCategory.NETWORK]: [
    /network.*error/i,
    /fetch.*failed/i,
    /ETIMEDOUT/i,
    /ENETUNREACH/i,
  ],
};

/**
 * Categorize an error based on its message and type
 * 
 * Requirement: 8.1
 */
export function categorizeError(error: Error): CategorizedError {
  const errorMessage = error.message.toLowerCase();

  // Determine category
  let category: ErrorCategory = ErrorCategory.UNKNOWN;
  for (const [cat, patterns] of Object.entries(ERROR_PATTERNS)) {
    if (patterns.some(pattern => pattern.test(errorMessage))) {
      category = cat as ErrorCategory;
      break;
    }
  }

  // Determine severity based on category
  const severity = getSeverityForCategory(category);

  // Determine recovery strategy
  const recoveryStrategy = getRecoveryStrategy(category, error);

  // Generate user-friendly message
  const userMessage = generateUserMessage(category, error);

  // Generate troubleshooting steps
  const troubleshootingSteps = generateTroubleshootingSteps(category, error);

  // Determine if retry is possible
  const canRetry = determineRetryability(category, recoveryStrategy);

  // Calculate retry delay if applicable
  const retryDelay = canRetry ? calculateRetryDelay(category) : undefined;

  return {
    category,
    severity,
    message: error.message,
    originalError: error,
    userMessage,
    technicalDetails: error.stack || error.message,
    recoveryStrategy,
    troubleshootingSteps,
    canRetry,
    retryDelay,
  };
}

/**
 * Get severity level for error category
 */
function getSeverityForCategory(category: ErrorCategory): ErrorSeverity {
  switch (category) {
    case ErrorCategory.SERVICE_UNAVAILABLE:
      return ErrorSeverity.HIGH;
    case ErrorCategory.VALIDATION:
      return ErrorSeverity.LOW;
    case ErrorCategory.GENERATION:
      return ErrorSeverity.MEDIUM;
    case ErrorCategory.TIMEOUT:
      return ErrorSeverity.MEDIUM;
    case ErrorCategory.FILE_SYSTEM:
      return ErrorSeverity.HIGH;
    case ErrorCategory.NETWORK:
      return ErrorSeverity.MEDIUM;
    default:
      return ErrorSeverity.MEDIUM;
  }
}

/**
 * Determine recovery strategy for error
 * 
 * Requirement: 8.2
 */
function getRecoveryStrategy(category: ErrorCategory, error: Error): RecoveryStrategy {
  switch (category) {
    case ErrorCategory.SERVICE_UNAVAILABLE:
      return RecoveryStrategy.USER_ACTION_REQUIRED;

    case ErrorCategory.VALIDATION:
      return RecoveryStrategy.ADJUST_PARAMETERS;

    case ErrorCategory.GENERATION:
      // Check if it's a parameter-related generation error
      if (/parameter|setting|config/i.test(error.message)) {
        return RecoveryStrategy.ADJUST_PARAMETERS;
      }
      return RecoveryStrategy.RETRY_WITH_BACKOFF;

    case ErrorCategory.TIMEOUT:
      return RecoveryStrategy.RETRY;

    case ErrorCategory.FILE_SYSTEM:
      return RecoveryStrategy.USER_ACTION_REQUIRED;

    case ErrorCategory.NETWORK:
      return RecoveryStrategy.RETRY_WITH_BACKOFF;

    default:
      return RecoveryStrategy.RETRY;
  }
}

/**
 * Generate user-friendly error message
 * 
 * Requirement: 8.3
 */
function generateUserMessage(category: ErrorCategory, error: Error): string {
  switch (category) {
    case ErrorCategory.SERVICE_UNAVAILABLE:
      if (/ComfyUI/i.test(error.message)) {
        return 'ComfyUI service is not available. Please check your ComfyUI configuration and ensure the server is running.';
      }
      if (/TTS/i.test(error.message)) {
        return 'Text-to-speech service is not available. Please check your TTS configuration.';
      }
      return 'A required service is not available. Please check your configuration.';

    case ErrorCategory.VALIDATION:
      return 'Invalid parameters provided. Please check your input values and try again.';

    case ErrorCategory.GENERATION:
      return 'Generation failed. This may be due to invalid parameters or a temporary issue with the generation service.';

    case ErrorCategory.TIMEOUT:
      return 'The operation took too long to complete. You can try again or adjust your parameters for faster processing.';

    case ErrorCategory.FILE_SYSTEM:
      if (/space/i.test(error.message)) {
        return 'Insufficient disk space. Please free up some space and try again.';
      }
      if (/permission/i.test(error.message)) {
        return 'Permission denied. Please check file permissions and try again.';
      }
      return 'File system error. Please check your file permissions and available disk space.';

    case ErrorCategory.NETWORK:
      return 'Network error occurred. Please check your internet connection and try again.';

    default:
      return 'An unexpected error occurred. Please try again or contact support if the problem persists.';
  }
}

/**
 * Generate troubleshooting steps
 * 
 * Requirement: 8.3
 */
function generateTroubleshootingSteps(category: ErrorCategory, error: Error): string[] {
  switch (category) {
    case ErrorCategory.SERVICE_UNAVAILABLE:
      if (/ComfyUI/i.test(error.message)) {
        return [
          'Verify ComfyUI server is running',
          'Check ComfyUI configuration in settings',
          'Ensure the correct port is configured',
          'Test ComfyUI connection in settings panel',
          'Restart ComfyUI server if necessary',
        ];
      }
      if (/TTS/i.test(error.message)) {
        return [
          'Check TTS service configuration',
          'Verify TTS provider is selected',
          'Test TTS connection in settings',
          'Ensure required TTS dependencies are installed',
        ];
      }
      return [
        'Check service configuration',
        'Verify service is running',
        'Test connection in settings',
        'Restart the service if necessary',
      ];

    case ErrorCategory.VALIDATION:
      return [
        'Review the highlighted invalid parameters',
        'Check parameter ranges and constraints',
        'Ensure all required fields are filled',
        'Try using default or recommended values',
      ];

    case ErrorCategory.GENERATION:
      return [
        'Try reducing generation complexity (lower steps, smaller dimensions)',
        'Check if the prompt is valid and not too long',
        'Verify model is properly loaded',
        'Try again in a few moments',
        'Check ComfyUI logs for detailed error information',
      ];

    case ErrorCategory.TIMEOUT:
      return [
        'Reduce generation parameters (steps, dimensions)',
        'Check system resources (CPU, GPU, memory)',
        'Ensure no other heavy processes are running',
        'Try again when system is less busy',
      ];

    case ErrorCategory.FILE_SYSTEM:
      if (/space/i.test(error.message)) {
        return [
          'Free up disk space by deleting unnecessary files',
          'Move old projects to external storage',
          'Check available disk space in system settings',
        ];
      }
      if (/permission/i.test(error.message)) {
        return [
          'Check file and folder permissions',
          'Ensure the application has write access',
          'Try running with appropriate permissions',
          'Check if files are locked by another process',
        ];
      }
      return [
        'Check file permissions',
        'Verify disk space availability',
        'Ensure files are not locked',
        'Try saving to a different location',
      ];

    case ErrorCategory.NETWORK:
      return [
        'Check your internet connection',
        'Verify firewall settings',
        'Try again in a few moments',
        'Check if the service is accessible from your network',
      ];

    default:
      return [
        'Try the operation again',
        'Check system logs for more details',
        'Restart the application if the problem persists',
        'Contact support with error details',
      ];
  }
}

/**
 * Determine if error is retryable
 */
function determineRetryability(category: ErrorCategory, strategy: RecoveryStrategy): boolean {
  if (strategy === RecoveryStrategy.USER_ACTION_REQUIRED || strategy === RecoveryStrategy.NONE) {
    return false;
  }

  const retryableCategories: ErrorCategory[] = [
    ErrorCategory.GENERATION,
    ErrorCategory.TIMEOUT,
    ErrorCategory.NETWORK,
  ];

  return retryableCategories.includes(category);
}

/**
 * Calculate retry delay based on category
 */
function calculateRetryDelay(category: ErrorCategory): number {
  switch (category) {
    case ErrorCategory.NETWORK:
      return 2000; // 2 seconds
    case ErrorCategory.TIMEOUT:
      return 5000; // 5 seconds
    case ErrorCategory.GENERATION:
      return 3000; // 3 seconds
    default:
      return 1000; // 1 second
  }
}

/**
 * Automatic retry with exponential backoff
 * 
 * Requirement: 8.2
 */
export async function retryWithBackoff<T>(
  operation: () => Promise<T>,
  maxAttempts: number = 3,
  initialDelay: number = 1000,
  onRetry?: (attempt: number, error: Error) => void
): Promise<T> {
  let lastError: Error | null = null;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await operation();
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error));

      if (attempt < maxAttempts) {
        const delay = initialDelay * Math.pow(2, attempt - 1);
        onRetry?.(attempt, lastError);
        await new Promise(resolve => setTimeout(resolve, delay));
      }
    }
  }

  throw lastError || new Error('Operation failed after retries');
}

/**
 * Preserve state on error
 * 
 * Requirement: 8.5
 */
export interface PreservedState {
  timestamp: number;
  errorCategory: ErrorCategory;
  userInputs: Record<string, unknown>;
  generatedAssets: unknown[];
  pipelineState: unknown;
}

export function preserveStateOnError(
  error: CategorizedError,
  userInputs: Record<string, unknown>,
  generatedAssets: unknown[] = [],
  pipelineState: unknown = null
): PreservedState {
  return {
    timestamp: Date.now(),
    errorCategory: error.category,
    userInputs: { ...userInputs },
    generatedAssets: [...generatedAssets],
    pipelineState: pipelineState ? { ...(pipelineState as any) } : null,
  };
}

/**
 * Restore preserved state
 * 
 * Requirement: 8.5
 */
export function restorePreservedState(preserved: PreservedState): {
  userInputs: Record<string, unknown>;
  generatedAssets: unknown[];
  pipelineState: unknown;
} {
  return {
    userInputs: { ...preserved.userInputs },
    generatedAssets: [...preserved.generatedAssets],
    pipelineState: preserved.pipelineState ? { ...(preserved.pipelineState as any) } : null,
  };
}

/**
 * Graceful degradation handler
 * 
 * Requirement: 8.2
 */
export function handleGracefulDegradation(
  error: CategorizedError,
  fallbackOptions: {
    skipStage?: boolean;
    useDefaultParameters?: boolean;
    useCachedResult?: boolean;
  } = {}
): RecoveryResult {
  const { skipStage, useDefaultParameters, useCachedResult } = fallbackOptions;

  // If we can skip the stage, suggest that
  if (skipStage && error.category !== ErrorCategory.SERVICE_UNAVAILABLE) {
    return {
      success: true,
      message: 'Stage skipped due to error. You can continue with the next stage.',
      shouldRetry: false,
    };
  }

  // If we can use default parameters, suggest that
  if (useDefaultParameters && error.category === ErrorCategory.VALIDATION) {
    return {
      success: true,
      message: 'Using default parameters to continue.',
      shouldRetry: true,
      adjustedParameters: {}, // Would contain actual defaults
    };
  }

  // If we can use cached result, suggest that
  if (useCachedResult) {
    return {
      success: true,
      message: 'Using previously generated result.',
      shouldRetry: false,
    };
  }

  // No graceful degradation possible
  return {
    success: false,
    message: 'Cannot recover automatically. User action required.',
    shouldRetry: false,
  };
}

/**
 * Suggest parameter adjustments for generation errors
 * 
 * Requirement: 8.2
 */
export function suggestParameterAdjustments(
  error: CategorizedError,
  currentParams: Record<string, unknown>
): Record<string, unknown> | null {
  if (error.category !== ErrorCategory.GENERATION && error.category !== ErrorCategory.TIMEOUT) {
    return null;
  }

  const suggestions: Record<string, unknown> = {};

  // Reduce complexity for timeout or generation errors
  const params = currentParams as any;
  if (params.steps && params.steps > 20) {
    suggestions.steps = Math.max(10, Math.floor(params.steps * 0.7));
  }

  if (params.width && params.width > 1024) {
    suggestions.width = 1024;
  }

  if (params.height && params.height > 1024) {
    suggestions.height = 1024;
  }

  if (params.cfgScale && params.cfgScale > 7) {
    suggestions.cfgScale = 7;
  }

  return Object.keys(suggestions).length > 0 ? suggestions : null;
}

/**
 * Format error for display
 */
export function formatErrorForDisplay(error: CategorizedError): {
  title: string;
  message: string;
  details: string;
  actions: Array<{ label: string; action: string }>;
} {
  const actions: Array<{ label: string; action: string }> = [];

  // Add retry action if applicable
  if (error.canRetry) {
    actions.push({
      label: 'Retry',
      action: 'retry',
    });
  }

  // Add adjust parameters action if applicable
  if (error.recoveryStrategy === RecoveryStrategy.ADJUST_PARAMETERS) {
    actions.push({
      label: 'Adjust Parameters',
      action: 'adjust_parameters',
    });
  }

  // Add configuration action for service unavailable
  if (error.category === ErrorCategory.SERVICE_UNAVAILABLE) {
    actions.push({
      label: 'Open Settings',
      action: 'open_settings',
    });
  }

  // Always add cancel action
  actions.push({
    label: 'Cancel',
    action: 'cancel',
  });

  return {
    title: getSeverityTitle(error.severity),
    message: error.userMessage,
    details: error.troubleshootingSteps.join('\nÔÇó '),
    actions,
  };
}

/**
 * Get title based on severity
 */
function getSeverityTitle(severity: ErrorSeverity): string {
  switch (severity) {
    case ErrorSeverity.LOW:
      return 'Input Error';
    case ErrorSeverity.MEDIUM:
      return 'Generation Error';
    case ErrorSeverity.HIGH:
      return 'Service Error';
    case ErrorSeverity.CRITICAL:
      return 'Critical Error';
    default:
      return 'Error';
  }
}

/**
 * Generation Error Handling Utilities
 * 
 * Provides error handling, retry logic with exponential backoff,
 * and partial result saving for generation pipeline failures.
 * 
 * Requirements: 3.7, 9.5
 */

import type {
  GenerationError,
  GeneratedShot,
} from '../types/projectDashboard';

// ============================================================================
// Types
// ============================================================================

/**
 * Error severity levels
 */
export type ErrorSeverity = 'low' | 'medium' | 'high' | 'critical';

/**
 * Retry strategy configuration
 */
export interface RetryStrategy {
  maxAttempts: number;
  initialDelayMs: number;
  maxDelayMs: number;
  backoffMultiplier: number;
  retryableErrors: string[];
}

/**
 * Error context for detailed error reporting
 */
export interface ErrorContext {
  stage: string;
  shotId?: string;
  timestamp: number;
  attemptNumber: number;
  stackTrace?: string;
  additionalInfo?: Record<string, unknown>;
}

/**
 * Partial results for recovery
 */
export interface PartialResults {
  projectId: string;
  timestamp: number;
  completedStages: string[];
  generatedShots: GeneratedShot[];
  masterCoherenceSheetUrl?: string;
  lastError?: GenerationError;
}

/**
 * Error recovery action
 */
export type RecoveryAction = 'retry' | 'skip' | 'abort' | 'manual';

/**
 * Error handler result
 */
export interface ErrorHandlerResult {
  action: RecoveryAction;
  message: string;
  canRetry: boolean;
  suggestedDelay?: number;
}

// ============================================================================
// Constants
// ============================================================================

/**
 * Default retry strategy
 * Requirements: 3.7
 */
export const DEFAULT_RETRY_STRATEGY: RetryStrategy = {
  maxAttempts: 3,
  initialDelayMs: 2000,
  maxDelayMs: 30000,
  backoffMultiplier: 2,
  retryableErrors: [
    'timeout',
    'network',
    'connection',
    'temporary',
    'rate_limit',
    'service_unavailable',
  ],
};

/**
 * Error severity mapping
 */
const ERROR_SEVERITY_MAP: Record<string, ErrorSeverity> = {
  timeout: 'medium',
  network: 'medium',
  connection: 'medium',
  validation: 'high',
  authentication: 'critical',
  authorization: 'critical',
  not_found: 'high',
  invalid_input: 'high',
  service_unavailable: 'medium',
  rate_limit: 'low',
  unknown: 'medium',
};

// ============================================================================
// Error Handling Class
// ============================================================================

/**
 * Generation error handler with retry logic
 * Requirements: 3.7, 9.5
 */
export class GenerationErrorHandler {
  private retryStrategy: RetryStrategy;
  private errorHistory: ErrorContext[] = [];
  private partialResults: PartialResults | null = null;

  constructor(retryStrategy: RetryStrategy = DEFAULT_RETRY_STRATEGY) {
    this.retryStrategy = retryStrategy;
  }

  /**
   * Handle error and determine recovery action
   * Requirements: 3.7
   */
  handleError(
    error: Error | GenerationError,
    context: Partial<ErrorContext>
  ): ErrorHandlerResult {
    // Record error in history
    const errorContext: ErrorContext = {
      stage: context.stage || 'unknown',
      shotId: context.shotId,
      timestamp: Date.now(),
      attemptNumber: context.attemptNumber || 1,
      stackTrace: error instanceof Error ? error.stack : undefined,
      additionalInfo: context.additionalInfo,
    };

    this.errorHistory.push(errorContext);

    // Determine if error is retryable
    const isRetryable = this.isErrorRetryable(error);
    const canRetry =
      isRetryable && errorContext.attemptNumber < this.retryStrategy.maxAttempts;

    // Calculate retry delay with exponential backoff
    const suggestedDelay = canRetry
      ? this.calculateRetryDelay(errorContext.attemptNumber)
      : undefined;

    // Determine recovery action
    let action: RecoveryAction;
    let message: string;

    if (canRetry) {
      action = 'retry';
      message = `Retrying after ${Math.round(suggestedDelay! / 1000)}s (attempt ${errorContext.attemptNumber + 1}/${this.retryStrategy.maxAttempts})`;
    } else if (isRetryable && errorContext.attemptNumber >= this.retryStrategy.maxAttempts) {
      action = 'abort';
      message = `Maximum retry attempts (${this.retryStrategy.maxAttempts}) reached. Generation aborted.`;
    } else {
      action = 'abort';
      message = this.getErrorMessage(error);
    }

    return {
      action,
      message,
      canRetry,
      suggestedDelay,
    };
  }

  /**
   * Check if error is retryable
   * Requirements: 3.7
   */
  private isErrorRetryable(error: Error | GenerationError): boolean {
    const errorMessage = this.getErrorMessage(error).toLowerCase();

    return this.retryStrategy.retryableErrors.some(retryableError =>
      errorMessage.includes(retryableError)
    );
  }

  /**
   * Calculate retry delay with exponential backoff
   * Requirements: 3.7
   */
  private calculateRetryDelay(attemptNumber: number): number {
    const delay =
      this.retryStrategy.initialDelayMs *
      Math.pow(this.retryStrategy.backoffMultiplier, attemptNumber - 1);

    return Math.min(delay, this.retryStrategy.maxDelayMs);
  }

  /**
   * Get error message from error object
   */
  private getErrorMessage(error: Error | GenerationError): string {
    if ('message' in error) {
      return error.message;
    }
    return 'Unknown error';
  }

  /**
   * Save partial results for recovery
   * Requirements: 9.5
   */
  savePartialResults(
    projectId: string,
    completedStages: string[],
    generatedShots: GeneratedShot[],
    masterCoherenceSheetUrl?: string,
    lastError?: GenerationError
  ): void {
    this.partialResults = {
      projectId,
      timestamp: Date.now(),
      completedStages,
      generatedShots,
      masterCoherenceSheetUrl,
      lastError,
    };

    // Persist to localStorage for recovery
    try {
      localStorage.setItem(
        `generation_partial_${projectId}`,
        JSON.stringify(this.partialResults)
      );
    } catch (err) {
      console.error('Failed to save partial results:', err);
    }
  }

  /**
   * Load partial results for recovery
   * Requirements: 9.5
   */
  loadPartialResults(projectId: string): PartialResults | null {
    try {
      const stored = localStorage.getItem(`generation_partial_${projectId}`);
      if (stored) {
        return JSON.parse(stored);
      }
    } catch (err) {
      console.error('Failed to load partial results:', err);
    }
    return null;
  }

  /**
   * Clear partial results after successful completion
   */
  clearPartialResults(projectId: string): void {
    this.partialResults = null;
    try {
      localStorage.removeItem(`generation_partial_${projectId}`);
    } catch (err) {
      console.error('Failed to clear partial results:', err);
    }
  }

  /**
   * Get error history
   */
  getErrorHistory(): ErrorContext[] {
    return [...this.errorHistory];
  }

  /**
   * Clear error history
   */
  clearErrorHistory(): void {
    this.errorHistory = [];
  }

  /**
   * Get error severity
   */
  getErrorSeverity(error: Error | GenerationError): ErrorSeverity {
    const errorMessage = this.getErrorMessage(error).toLowerCase();

    for (const [keyword, severity] of Object.entries(ERROR_SEVERITY_MAP)) {
      if (errorMessage.includes(keyword)) {
        return severity;
      }
    }

    return 'medium';
  }

  /**
   * Format error for display
   * Requirements: 3.7
   */
  formatErrorForDisplay(error: Error | GenerationError): string {
    const message = this.getErrorMessage(error);
    const severity = this.getErrorSeverity(error);

    const severityEmoji: Record<ErrorSeverity, string> = {
      low: 'ÔÜá´©Å',
      medium: 'ÔÜá´©Å',
      high: 'ÔØî',
      critical: '­ƒÜ¿',
    };

    return `${severityEmoji[severity]} ${message}`;
  }

  /**
   * Update retry strategy
   */
  updateRetryStrategy(strategy: Partial<RetryStrategy>): void {
    this.retryStrategy = { ...this.retryStrategy, ...strategy };
  }

  /**
   * Reset handler state
   */
  reset(): void {
    this.errorHistory = [];
    this.partialResults = null;
  }
}

// ============================================================================
// Utility Functions
// ============================================================================

/**
 * Create descriptive error message for generation errors
 * Requirements: 3.7
 */
export function createGenerationError(
  stage: string,
  message: string,
  shotId?: string,
  retryable: boolean = true
): GenerationError {
  return {
    stage: stage as any,
    message,
    shotId,
    retryable,
  };
}

/**
 * Wrap async function with retry logic
 * Requirements: 3.7
 */
export async function withRetry<T>(
  fn: () => Promise<T>,
  strategy: RetryStrategy = DEFAULT_RETRY_STRATEGY,
  onRetry?: (attempt: number, error: Error) => void
): Promise<T> {
  let lastError: Error | null = null;

  for (let attempt = 1; attempt <= strategy.maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error instanceof Error ? error : new Error('Unknown error');

      // Check if error is retryable
      const errorMessage = lastError.message.toLowerCase();
      const isRetryable = strategy.retryableErrors.some(retryableError =>
        errorMessage.includes(retryableError)
      );

      if (!isRetryable || attempt >= strategy.maxAttempts) {
        throw lastError;
      }

      // Calculate delay with exponential backoff
      const delay =
        strategy.initialDelayMs *
        Math.pow(strategy.backoffMultiplier, attempt - 1);
      const actualDelay = Math.min(delay, strategy.maxDelayMs);

      // Notify about retry
      onRetry?.(attempt, lastError);

      // Wait before retry
      await new Promise(resolve => setTimeout(resolve, actualDelay));
    }
  }

  throw lastError || new Error('Failed after retries');
}

/**
 * Check if error indicates a temporary failure
 */
export function isTemporaryError(error: Error): boolean {
  const temporaryKeywords = [
    'timeout',
    'network',
    'connection',
    'temporary',
    'unavailable',
    'rate limit',
    'too many requests',
  ];

  const errorMessage = error.message.toLowerCase();
  return temporaryKeywords.some(keyword => errorMessage.includes(keyword));
}

/**
 * Check if error indicates a permanent failure
 */
export function isPermanentError(error: Error): boolean {
  const permanentKeywords = [
    'not found',
    'invalid',
    'unauthorized',
    'forbidden',
    'authentication',
    'authorization',
  ];

  const errorMessage = error.message.toLowerCase();
  return permanentKeywords.some(keyword => errorMessage.includes(keyword));
}

/**
 * Get user-friendly error message
 * Requirements: 3.7
 */
export function getUserFriendlyErrorMessage(error: Error | GenerationError): string {
  const message = 'message' in error ? error.message : String(error);

  // Map technical errors to user-friendly messages
  const errorMappings: Record<string, string> = {
    'network error': 'Unable to connect to the server. Please check your internet connection.',
    'timeout': 'The operation took too long to complete. Please try again.',
    'not found': 'The requested resource was not found.',
    'unauthorized': 'You are not authorized to perform this action.',
    'rate limit': 'Too many requests. Please wait a moment and try again.',
    'service unavailable': 'The service is temporarily unavailable. Please try again later.',
    'invalid input': 'The provided input is invalid. Please check and try again.',
  };

  for (const [keyword, friendlyMessage] of Object.entries(errorMappings)) {
    if (message.toLowerCase().includes(keyword)) {
      return friendlyMessage;
    }
  }

  return message;
}

/**
 * Create error report for debugging
 */
export function createErrorReport(
  error: Error | GenerationError,
  context: Partial<ErrorContext>
): string {
  const timestamp = new Date().toISOString();
  const message = 'message' in error ? error.message : String(error);
  const stack = error instanceof Error ? error.stack : 'No stack trace';

  return `
Error Report
============
Timestamp: ${timestamp}
Stage: ${context.stage || 'unknown'}
Shot ID: ${context.shotId || 'N/A'}
Attempt: ${context.attemptNumber || 1}

Message:
${message}

Stack Trace:
${stack}

Additional Info:
${JSON.stringify(context.additionalInfo || {}, null, 2)}
  `.trim();
}

/**
 * Log error to console with formatting
 */
export function logError(
  error: Error | GenerationError,
  context: Partial<ErrorContext>
): void {
  const report = createErrorReport(error, context);
  console.error(report);
}

/**
 * Default error handler instance
 */
export const defaultErrorHandler = new GenerationErrorHandler();

/**
 * IndexedDB utilities for persistent storage
 * Provides a simple API for storing and retrieving data with TypeScript support
 */

export interface IDBConfig {
  name: string;
  version: number;
  stores: IDBStoreConfig[];
}

export interface IDBStoreConfig {
  name: string;
  keyPath: string;
  indexes?: IDBIndexConfig[];
}

export interface IDBIndexConfig {
  name: string;
  keyPath: string | string[];
  unique?: boolean;
}

export class IndexedDB {
  private db: IDBDatabase | null = null;
  private config: IDBConfig;

  constructor(config: IDBConfig) {
    this.config = config;
  }

  async open(): Promise<void> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.config.name, this.config.version);

      request.onerror = () => {
        reject(new Error(`Failed to open database: ${request.error?.message}`));
      };

      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;

        // Create object stores
        for (const storeConfig of this.config.stores) {
          if (!db.objectStoreNames.contains(storeConfig.name)) {
            const store = db.createObjectStore(storeConfig.name, {
              keyPath: storeConfig.keyPath
            });

            // Create indexes
            if (storeConfig.indexes) {
              for (const indexConfig of storeConfig.indexes) {
                store.createIndex(indexConfig.name, indexConfig.keyPath, {
                  unique: indexConfig.unique || false
                });
              }
            }
          }
        }
      };
    });
  }

  async put(storeName: string, value: unknown): Promise<void> {
    if (!this.db) throw new Error('Database not opened');

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([storeName], 'readwrite');
      const store = transaction.objectStore(storeName);
      const request = store.put(value);

      request.onerror = () => {
        reject(new Error(`Failed to put data: ${request.error?.message}`));
      };

      request.onsuccess = () => {
        resolve();
      };
    });
  }

  async get<T = any>(storeName: string, key: unknown): Promise<T | undefined> {
    if (!this.db) throw new Error('Database not opened');

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([storeName], 'readonly');
      const store = transaction.objectStore(storeName);
      const request = store.get(key as any);

      request.onerror = () => {
        reject(new Error(`Failed to get data: ${request.error?.message}`));
      };

      request.onsuccess = () => {
        resolve(request.result);
      };
    });
  }

  async getAll<T = any>(storeName: string): Promise<T[]> {
    if (!this.db) throw new Error('Database not opened');

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([storeName], 'readonly');
      const store = transaction.objectStore(storeName);
      const request = store.getAll();

      request.onerror = () => {
        reject(new Error(`Failed to get all data: ${request.error?.message}`));
      };

      request.onsuccess = () => {
        resolve(request.result);
      };
    });
  }

  async delete(storeName: string, key: unknown): Promise<void> {
    if (!this.db) throw new Error('Database not opened');

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([storeName], 'readwrite');
      const store = transaction.objectStore(storeName);
      const request = store.delete(key as any);

      request.onerror = () => {
        reject(new Error(`Failed to delete data: ${request.error?.message}`));
      };

      request.onsuccess = () => {
        resolve();
      };
    });
  }

  async clear(storeName: string): Promise<void> {
    if (!this.db) throw new Error('Database not opened');

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([storeName], 'readwrite');
      const store = transaction.objectStore(storeName);
      const request = store.clear();

      request.onerror = () => {
        reject(new Error(`Failed to clear store: ${request.error?.message}`));
      };

      request.onsuccess = () => {
        resolve();
      };
    });
  }

  async getByIndex<T = any>(
    storeName: string,
    indexName: string,
    key: unknown
  ): Promise<T[]> {
    if (!this.db) throw new Error('Database not opened');

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([storeName], 'readonly');
      const store = transaction.objectStore(storeName);
      const index = store.index(indexName);
      const request = index.getAll(key as any);

      request.onerror = () => {
        reject(new Error(`Failed to get by index: ${request.error?.message}`));
      };

      request.onsuccess = () => {
        resolve(request.result);
      };
    });
  }

  close() {
    if (this.db) {
      this.db.close();
      this.db = null;
    }
  }

  get isOpen(): boolean {
    return this.db !== null;
  }
}

