import type { ChatboxLLMConfig } from './llmConfigStorage';
import { saveConfiguration, saveLanguagePreference, STORAGE_KEYS } from './llmConfigStorage';

// ============================================================================
// Types
// ============================================================================

/**
 * Legacy Ollama configuration structure
 */
interface LegacyOllamaConfig {
