  }

  // Check if new config already exists (migration already done)
  const hasNewConfig = localStorage.getItem(STORAGE_KEYS.LLM_CONFIG) !== null;
  
  // Migration needed if legacy exists and new doesn't
  return !hasNewConfig;
}

