/**
 * Generate scenario.md file content in standard screenplay format
 */
export function generateScenarioContent(story: Story): string {
  const lines: string[] = [];

  // Title page
  lines.push('# SCENARIO');
  lines.push('');
  lines.push(`**${story.title.toUpperCase()}**`);
  lines.push('');
  lines.push(`Genre: ${story.genre.join(', ')}`);
  lines.push(`Ton: ${story.tone.join(', ')}`);
  lines.push(`Dur├®e estim├®e: ${getEstimatedDuration(story.length)}`);
  lines.push('');
  lines.push('---');
  lines.push('');

  // Characters section
  if (story.charactersUsed.length > 0) {
    lines.push('## PERSONNAGES');
    lines.push('');
    story.charactersUsed.forEach((char) => {
      lines.push(`**${char.name}** - ${char.role}`);
    });
    lines.push('');
    lines.push('---');
    lines.push('');
  }

  // Locations section
  if (story.locationsUsed.length > 0) {
    lines.push('## LIEUX');
    lines.push('');
    story.locationsUsed.forEach((loc) => {
      lines.push(`**${loc.name}** - ${loc.significance}`);
    });
    lines.push('');
    lines.push('---');
    lines.push('');
  }

  // Synopsis
  lines.push('## SYNOPSIS');
  lines.push('');
  lines.push(story.summary);
  lines.push('');
  lines.push('---');
  lines.push('');

  // Story content formatted as scenario
  lines.push('## SC├ëNARIO');
  lines.push('');

  // Parse story content into scenes
  const scenes = parseStoryToScenes(story.content, story.parts);

  scenes.forEach((scene, index) => {
    lines.push(`### SC├êNE ${index + 1}`);
    lines.push('');
    lines.push(`**LIEU:** ${scene.location}`);
    lines.push(`**TEMPS:** ${scene.timeOfDay}`);
    lines.push('');

    // Scene description
    lines.push('*' + scene.description + '*');
    lines.push('');

    // Dialogues
    scene.dialogues.forEach((dialogue) => {
      lines.push(`**${dialogue.character}:**`);
      lines.push(dialogue.text);
      lines.push('');
    });

    lines.push('---');
    lines.push('');
  });

  // Footer
  lines.push('*G├®n├®r├® automatiquement par StoryCore-Engine*');

  return lines.join('\n');
}

/**
 * Parse story content into scenes
 */
function parseStoryToScenes(content: string, parts?: StoryPart[]): Scene[] {
  const scenes: Scene[] = [];

  if (parts && parts.length > 0) {
    // Use parts if available
    parts.forEach((part, index) => {
      scenes.push({
        location: '├Ç d├®terminer',
        timeOfDay: 'Jour',
        description: part.summary || part.content.substring(0, 200),
        dialogues: extractDialogues(part.content),
      });
    });
  } else {
    // Parse content into scenes
    const paragraphs = content.split(/\n\n+/);
    let currentScene: Scene = {
      location: '├Ç d├®terminer',
      timeOfDay: 'Jour',
      description: '',
      dialogues: [],
    };

    paragraphs.forEach((para) => {
      const trimmed = para.trim();
      if (!trimmed) return;

      // Check for scene header
      if (trimmed.match(/^(INT\.|EXT\.|CHAPITRE|SC├êNE)/i)) {
        if (currentScene.description || currentScene.dialogues.length > 0) {
          scenes.push(currentScene);
        }
        currentScene = {
          location: extractLocation(trimmed),
          timeOfDay: 'Jour',
          description: '',
          dialogues: [],
        };
      } else if (trimmed.includes(':') && trimmed.length < 500) {
        // Likely dialogue
        const colonIndex = trimmed.indexOf(':');
        currentScene.dialogues.push({
          character: trimmed.substring(0, colonIndex).trim(),
          text: trimmed.substring(colonIndex + 1).trim(),
        });
      } else {
        currentScene.description += (currentScene.description ? ' ' : '') + trimmed;
      }
    });

    if (currentScene.description || currentScene.dialogues.length > 0) {
      scenes.push(currentScene);
    }
  }

  return scenes.length > 0 ? scenes : [{
    location: '├Ç d├®terminer',
    timeOfDay: 'Jour',
    description: content.substring(0, 500),
    dialogues: [],
  }];
}

interface Scene {
  location: string;
  timeOfDay: string;
  description: string;
  dialogues: Array<{ character: string; text: string }>;
}

function extractDialogues(content: string): Array<{ character: string; text: string }> {
  const dialogues: Array<{ character: string; text: string }> = [];
  const lines = content.split('\n');

  lines.forEach((line) => {
    const trimmed = line.trim();
    if (trimmed.includes(':') && trimmed.length < 300) {
      const colonIndex = trimmed.indexOf(':');
      const beforeColon = trimmed.substring(0, colonIndex).trim();
      // Check if it looks like a character name (short, starts with capital)
      if (beforeColon.length < 30 && /^[A-Z├ë├ê├è├ï├Ç├é├ä├Ö├ø├£├ö├û├Ä├Å├ç]/.test(beforeColon)) {
        dialogues.push({
          character: beforeColon,
          text: trimmed.substring(colonIndex + 1).trim(),
        });
      }
    }
  });

  return dialogues;
}

function extractLocation(header: string): string {
  const match = header.match(/(?:INT\.|EXT\.)\s*[:-]?\s*(.+)/i);
  return match ? match[1].trim() : '├Ç d├®terminer';
}

function getEstimatedDuration(length: Story['length']): string {
  const durations: Record<string, string> = {
    scene: '1-2 minutes',
    short: '2-5 minutes',
    short_story: '5-10 minutes',
    medium: '10-20 minutes',
    novella: '20-40 minutes',
    long: '40-60 minutes',
    novel: '60-90 minutes',
    epic_novel: '90-120 minutes',
  };
  return durations[length] || '15-30 minutes';
}

/**
 * Save scenario.md file to project
 */
export async function saveScenarioToDisk(projectPath: string, story: Story): Promise<void> {
  if (!window.electronAPI?.fs) {
    throw new Error('Electron API not available');
  }

  try {
    // Generate scenario content
    const scenarioContent = generateScenarioContent(story);

    // Write scenario.md at project root
    const scenarioPath = `${projectPath}/scenario.md`;
    await window.electronAPI.fs.writeFile(scenarioPath, scenarioContent);

    console.log(`[StoryFileIO] Scenario saved: ${scenarioPath}`);
  } catch (error) {
    console.error('[StoryFileIO] Failed to save scenario:', error);
    throw error;
  }
}

/**
 * Validation Schemas using Zod
 * 
 * Provides runtime validation for component props and data structures
 */

import { z } from 'zod';

// ============================================================================
// Basic Type Schemas
// ============================================================================

export const IdSchema = z.string().min(1, 'ID cannot be empty');
export const NameSchema = z.string().min(1, 'Name cannot be empty').max(255, 'Name too long');
export const DescriptionSchema = z.string().max(1000, 'Description too long').optional();

// ============================================================================
// Project Schemas
// ============================================================================

export const ProjectSchema = z.object({
  project_id: IdSchema,
  project_name: NameSchema,
  project_type: z.enum(['short_film', 'commercial', 'music_video', 'animation']),
  description: DescriptionSchema,
  created_at: z.date().optional(),
  updated_at: z.date().optional(),
});

export type Project = z.infer<typeof ProjectSchema>;

// ============================================================================
// Character Schemas
// ============================================================================

export const CharacterSchema = z.object({
  character_id: IdSchema,
  name: NameSchema,
  description: DescriptionSchema,
  role: z.string().optional(),
  appearance: z.string().optional(),
  personality: z.string().optional(),
  creation_method: z.enum(['wizard', 'manual', 'import']).optional(),
  creation_timestamp: z.date().optional(),
  version: z.string().optional(),
});

export type Character = z.infer<typeof CharacterSchema>;

// ============================================================================
// World Schemas
// ============================================================================

export const WorldSchema = z.object({
  id: IdSchema,
  name: NameSchema,
  description: DescriptionSchema,
  setting: z.string().optional(),
  atmosphere: z.string().optional(),
  rules: z.string().optional(),
});

export type World = z.infer<typeof WorldSchema>;

// ============================================================================
// Story Schemas
// ============================================================================

export const StorySchema = z.object({
  id: IdSchema,
  title: NameSchema,
  description: DescriptionSchema,
  genre: z.string().optional(),
  theme: z.string().optional(),
  plot_summary: z.string().optional(),
});

export type Story = z.infer<typeof StorySchema>;

// ============================================================================
// Shot Schemas
// ============================================================================

export const ShotSchema = z.object({
  id: IdSchema,
  name: NameSchema,
  description: DescriptionSchema,
  duration: z.number().positive().optional(),
  camera_angle: z.string().optional(),
  lighting: z.string().optional(),
});

export type Shot = z.infer<typeof ShotSchema>;

// ============================================================================
// Validation Utilities
// ============================================================================

/**
 * Validates data against a schema and returns the result
 * @param schema - The Zod schema to validate against
 * @param data - The data to validate
 * @returns Object with success flag and either validated data or errors
 */
export function validateData<T>(
  schema: z.ZodSchema<T>,
  data: unknown
): { success: boolean; data?: T; errors?: Record<string, string> } {
  try {
    const validated = schema.parse(data);
    return { success: true, data: validated };
  } catch (error) {
    if (error instanceof z.ZodError) {
      const errors: Record<string, string> = {};
      (error as any).errors.forEach((err: z.ZodIssue) => {
        const path = err.path.join('.');
        errors[path] = err.message;
      });
      return { success: false, errors };
    }
    return { success: false, errors: { _general: 'Validation failed' } };
  }
}

/**
 * Validates data and throws an error if validation fails
 * @param schema - The Zod schema to validate against
 * @param data - The data to validate
 * @returns The validated data
 * @throws ZodError if validation fails
 */
export function validateDataOrThrow<T>(schema: z.ZodSchema<T>, data: unknown): T {
  return schema.parse(data);
}

/**
 * Safely validates data without throwing
 * @param schema - The Zod schema to validate against
 * @param data - The data to validate
 * @returns The validated data or null if validation fails
 */
export function validateDataSafe<T>(schema: z.ZodSchema<T>, data: unknown): T | null {
  const result = schema.safeParse(data);
  return result.success ? result.data : null;
}

/**
 * WorkerPool - Gestion d'un pool de Web Workers pour traitement asynchrone
 * 
 * Cette classe g├¿re un pool de workers pour ex├®cuter des t├óches en arri├¿re-plan
 * sans bloquer l'interface utilisateur. Elle impl├®mente une file d'attente de t├óches
 * et alloue automatiquement les workers disponibles.
 * 
 * Exigences: 10.1, 10.6
 */

export interface WorkerTask<T = any, R = any> {
  id: string;
  type: string;
  data: T;
  resolve: (result: R) => void;
  reject: (error: Error) => void;
  priority?: number;
}

export interface WorkerMessage<T = any> {
  id: string;
  type: string;
  data: T;
}

export interface WorkerResponse<R = any> {
  id: string;
  status: 'completed' | 'error' | 'progress';
  result?: R;
  error?: string;
  progress?: number;
}

export class WorkerPool {
  private workers: Worker[] = [];
  private availableWorkers: Worker[] = [];
  private taskQueue: WorkerTask[] = [];
  public readonly size: number;
  private workerUrl: string;

  /**
   * Cr├®e un nouveau pool de workers
   * @param size - Nombre de workers dans le pool (par d├®faut: nombre de c┼ôurs CPU)
   * @param workerUrl - URL du script worker ├á charger
   */
  constructor(
    size: number = navigator.hardwareConcurrency || 4,
    workerUrl: string = new URL('../../workers/processing.worker.ts', import.meta.url).href
  ) {
    this.size = size;
    this.workerUrl = workerUrl;
    this.initializeWorkers();
  }

  /**
   * Initialise tous les workers du pool
   * Exigence: 10.1 - Traitement non-bloquant
   */
  private initializeWorkers(): void {
    for (let i = 0; i < this.size; i++) {
      const worker = this.createWorker();
      this.workers.push(worker);
      this.availableWorkers.push(worker);
    }
  }

  /**
   * Cr├®e un nouveau worker avec les gestionnaires d'├®v├®nements
   */
  private createWorker(): Worker {
    const worker = new Worker(this.workerUrl, { type: 'module' });

    worker.onmessage = (event: MessageEvent<WorkerResponse>) => {
      this.handleWorkerMessage(worker, event.data);
    };

    worker.onerror = (error: ErrorEvent) => {
      this.handleWorkerError(worker, error);
    };

    return worker;
  }

  /**
   * Ex├®cute une t├óche dans le pool de workers
   * @param type - Type de t├óche ├á ex├®cuter
   * @param data - Donn├®es ├á traiter
   * @param priority - Priorit├® de la t├óche (optionnel)
   * @returns Promise qui se r├®sout avec le r├®sultat
   * 
   * Exigence: 10.6 - File d'attente avec priorit├®s
   */
  async execute<T, R>(type: string, data: T, priority: number = 0): Promise<R> {
    return new Promise((resolve, reject) => {
      const task: WorkerTask<T, R> = {
        id: this.generateTaskId(),
        type,
        data,
        resolve,
        reject,
        priority
      };

      const worker = this.availableWorkers.pop();

      if (worker) {
        // Worker available, execute immediately
        this.executeTask(worker, task);
      } else {
        // No worker available, add to queue
        this.enqueueTask(task);
      }
    });
  }

  /**
   * Adds a task to the queue respecting priorities
   * Requirement: 10.6 - Priority management
   */
  private enqueueTask(task: WorkerTask): void {
    // Insert task based on its priority (higher priority = earlier in queue)
    const insertIndex = this.taskQueue.findIndex(t => (t.priority || 0) < (task.priority || 0));
    
    if (insertIndex === -1) {
      this.taskQueue.push(task);
    } else {
      this.taskQueue.splice(insertIndex, 0, task);
    }
  }

  /**
   * Executes a task on a specific worker
   */
  private executeTask(worker: Worker, task: WorkerTask): void {
    const message: WorkerMessage = {
      id: task.id,
      type: task.type,
      data: task.data
    };

    worker.postMessage(message);

    // Store task for later resolution
    (worker as any).__currentTask = task;
  }

  /**
   * Handles messages received from a worker
   * Requirement: 10.2 - Progress updates
   */
  private handleWorkerMessage(worker: Worker, response: WorkerResponse): void {
    const task = (worker as any).__currentTask as WorkerTask;

    if (!task || response.id !== task.id) {
      console.warn('Received message for unknown task:', response.id);
      return;
    }

    if (response.status === 'progress') {
      // Progress message - do not release worker
      // Progress callbacks can be added in a future version
      return;
    }

    if (response.status === 'error') {
      task.reject(new Error(response.error || 'Worker task failed'));
    } else if (response.status === 'completed') {
      task.resolve(response.result);
    }

    // Release worker
    delete (worker as any).__currentTask;
    this.availableWorkers.push(worker);

    // Process next pending task
    this.processNextTask(worker);
  }

  /**
   * Processes the next task in the queue
   */
  private processNextTask(worker: Worker): void {
    const nextTask = this.taskQueue.shift();
    if (nextTask) {
      // Remove worker from available list
      const index = this.availableWorkers.indexOf(worker);
      if (index !== -1) {
        this.availableWorkers.splice(index, 1);
      }
      this.executeTask(worker, nextTask);
    }
  }

  /**
   * Handles worker errors
   * Requirement: 10.7 - Error handling with context
   */
  private handleWorkerError(worker: Worker, error: ErrorEvent): void {
    const task = (worker as any).__currentTask as WorkerTask;

    if (task) {
      task.reject(new Error(`Worker error: ${error.message}`));
      delete (worker as any).__currentTask;
    }

    // Recreate failed worker
    const index = this.workers.indexOf(worker);
    if (index !== -1) {
      worker.terminate();
      this.workers.splice(index, 1);

      const newWorker = this.createWorker();
      this.workers.push(newWorker);
      this.availableWorkers.push(newWorker);
    }
  }

  /**
   * Cancels a specific task by its ID
   * Requirement: 10.5 - Task cancellation
   */
  cancel(taskId: string): boolean {
    // Search in queue
    const queueIndex = this.taskQueue.findIndex(t => t.id === taskId);
    if (queueIndex !== -1) {
      const task = this.taskQueue.splice(queueIndex, 1)[0];
      task.reject(new Error('Task cancelled'));
      return true;
    }

    // Search in running tasks
    for (const worker of this.workers) {
      const task = (worker as any).__currentTask as WorkerTask;
      if (task && task.id === taskId) {
        task.reject(new Error('Task cancelled'));
        delete (worker as any).__currentTask;
        
        // Send cancellation message to worker
        worker.postMessage({ id: taskId, type: 'cancel' });
        
        // Make worker available
        if (!this.availableWorkers.includes(worker)) {
          this.availableWorkers.push(worker);
        }
        
        // Process next task
        this.processNextTask(worker);
        return true;
      }
    }

    return false;
  }

  /**
   * Cancels all running and pending tasks
   * Requirement: 10.5 - Task cancellation
   */
  cancelAll(): void {
    // Reject all pending tasks
    while (this.taskQueue.length > 0) {
      const task = this.taskQueue.shift();
      if (task) {
        task.reject(new Error('Task cancelled'));
      }
    }

    // Reject all running tasks
    for (const worker of this.workers) {
      const task = (worker as any).__currentTask as WorkerTask;
      if (task) {
        task.reject(new Error('Task cancelled'));
        delete (worker as any).__currentTask;
        
        // Send cancellation message to worker
        worker.postMessage({ id: task.id, type: 'cancel' });
      }
    }

    // Reset available workers list
    this.availableWorkers = [...this.workers];
  }

  /**
   * Properly terminates all workers in the pool
   * Requirement: 10.5 - Clean termination
   */
  terminate(): void {
    this.cancelAll();

    for (const worker of this.workers) {
      worker.terminate();
    }

    this.workers = [];
    this.availableWorkers = [];
  }

  /**
   * Returns the number of pending tasks
   */
  getQueueSize(): number {
    return this.taskQueue.length;
  }

  /**
   * Retourne le nombre de workers disponibles
   */
  getAvailableWorkers(): number {
    return this.availableWorkers.length;
  }

  /**
   * Retourne le nombre de workers occup├®s
   */
  getBusyWorkers(): number {
    return this.size - this.availableWorkers.length;
  }

  /**
   * G├®n├¿re un ID unique pour une t├óche
   */
  private generateTaskId(): string {
    return `task_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
}

